local P = LoreForeverPacks.Begin("LoreForever_Lang_zhCN")
P.entries["quest:581"] = {n="耶尼库的下落",s="尼姆布亚从奥格瑞玛回到了荆棘谷的丛林，寻找他的酋长最小的儿子耶尼库。这位侦察兵怀疑血顶部落囚禁了这个年轻人，他请求你去猎杀他们的战士并带回獠牙，以证明你的实力。",h="尼姆布亚从奥格瑞玛回到了荆棘谷的丛林，寻找他的酋长最小的儿子耶尼库。这位侦察兵怀疑血顶部落囚禁了这个年轻人，他请求你去猎杀他们的战士并带回獠牙，以证明你的实力。",kw={"血顶","暗矛","格罗姆高","寻找耶尼库","尼姆布亚","荆棘谷","獠牙","耶尼库","祖尔格拉布"},ang={["faction:Horde"]="尼姆布亚直接受命于奥格瑞玛，他依靠格罗姆高营地的部落盟友来帮助营救暗矛酋长的亲人。",["race:Troll"]="对于暗矛巨魔来说，响应尼姆布亚的号召意味着帮助他们自己的酋长家庭，并猎杀可能囚禁着耶尼库的血顶巨魔。"},sec={{t="酋长失踪的儿子",b="在格罗姆高营地，尼姆布亚谈到了暗矛巨魔酋长最小的儿子耶尼库所面临的严峻命运。按照古老的部落习俗，这个男孩曾被送往祖尔格拉布的古拉巴什巨魔那里。当暗矛部族跟随兽人酋长萨尔离开家园时，耶尼库被留在了那里并失踪了。尼姆布亚被从遥远的奥格瑞玛派回，承担起了寻找酋长之子并将其安全带回的责任。"},{t="猎杀血顶巨魔",b="尼姆布亚相信耶尼库现在被血顶部落扣押。他要求冒险者证明自己有足够的实力去猎杀他们。你被派往北方猎杀血顶巨魔并收集九根獠牙。将这些战利品带回格罗姆高营地将证明你的武勇，并开启寻找酋长之子的漫长任务，直接通往名为“猎头者”的狩猎行动。"}},faq={{q="耶尼库是谁？",a="耶尼库是暗矛部族酋长最小的儿子。按照部落习俗，他被送往祖尔格拉布的古拉巴什巨魔那里，但在暗矛部族离开该地区时，他与族人失散了。",al={"耶尼库背景故事","耶尼库是谁","酋长之子"}},{q="为什么耶尼库被留在了荆棘谷？",a="按照部落习俗，耶尼库被送往祖尔格拉布的古拉巴什巨魔那里。当暗矛部族与萨尔结盟并离开时，这个年轻人就被他们遗失了。",al={"耶尼库为何留下","耶尼库如何失踪","为何祖尔格拉布"}},{q="尼姆布亚是谁？",a="尼姆布亚是一位驻扎在格罗姆高营地的暗矛巨魔。他被从遥远的奥格瑞玛派回荆棘谷，寻找他酋长失踪的儿子。",al={"谁发布了寻找耶尼库的任务","尼姆布亚","格罗姆高侦察兵"}},{q="为什么要收集血顶巨魔的獠牙？",a="尼姆布亚怀疑血顶部落抓走了耶尼库。他需要九根血顶巨魔的獠牙作为证明，以确认你有足够的实力去猎杀这些敌对的巨魔，然后再继续寻找。",al={"血顶獠牙的用途","为何要獠牙","寻找耶尼库獠牙"}},{q="血顶巨魔在哪里？",a="尼姆布亚指引猎人前往格罗姆高营地以北的领地寻找血顶部落。",al={"去哪里找血顶巨魔","血顶巨魔位置","血顶巨魔在哪里"}}},fp="16,227,22.403.0,23.315.0,15.188.0,45.133.0,15.140.0,44.166.0,40.78.0"}
P.entries["quest:582"] = {n="猎头行动",s="格罗姆高营地的尼姆布亚需要确定暗矛酋长的儿子耶尼库是否已经遇害。冒险者们被要求去猎杀血顶猎头者并收缴他们的缩颅，以便尼姆布亚进行检查。",h="格罗姆高营地的尼姆布亚需要确定暗矛酋长的儿子耶尼库是否已经遇害。冒险者们被要求去猎杀血顶猎头者并收缴他们的缩颅，以便尼姆布亚进行检查。",kw={"血顶","加祖拉","格罗姆高营地","猎头行动","尼姆布亚","缩颅","耶尼库","祖尔昆达","祖尔达亚"},ang={["faction:Horde"]="部落军队以格罗姆高营地为基地，协助他们的暗矛盟友查明酋长失踪的儿子是否还活着。",["race:Troll"]="酋长儿子的命运对暗矛部族来说事关重大，他们必须面对血顶部族来了解究竟发生了什么。"},sec={{t="搜寻战利品",b="在“寻找耶尼库”的任务开始搜寻之后，尼姆布亚担心酋长的儿子可能已经死在了血顶巨魔的手中。为了查明真相，他要求你去猎杀游荡在北方海岸祖尔达亚和祖尔昆达废墟中的血顶猎头者。通过从他们身上收集二十个缩颅，尼姆布亚希望能通过检查这些可怕的战利品来确认耶尼库是否遭遇了不幸，如果这名年轻人确实被杀害，他将诅咒血顶酋长加祖拉。"}},faq={{q="谁在寻找耶尼库？",a="格罗姆高营地的尼姆布亚正在寻找耶尼库，他是暗矛部族酋长的儿子。",al={"谁发布了猎头行动","尼姆布亚的目的","为什么要寻找耶尼库"}},{q="为什么尼姆布亚想要缩颅？",a="尼姆布亚计划检查从血顶猎头者身上获取的缩颅，以核实耶尼库的头颅是否在他们的战利品之中。",al={"为什么要收集缩颅","缩颅的用途","尼姆布亚用这些头颅做什么"}},{q="在哪里可以找到血顶猎头者？",a="血顶猎头者聚集在荆棘谷的北海岸，特别是祖尔达亚和祖尔昆达的废墟周围。",al={"猎头者的位置","祖尔达亚和祖尔昆达在哪里","去哪里寻找缩颅"}},{q="文中提到的血顶部族由谁领导？",a="血顶部族由酋长加祖拉领导，如果耶尼库确实死了，尼姆布亚希望能对其灵魂施加六百年的诅咒。",al={"血顶酋长","加祖拉是谁","酋长加祖拉"}}},fp="11,206,22.438.0,27.95.0,37.126.0,46.127.0,46.128.0"}
P.entries["quest:5821"] = {n="雇佣保镖",s="考克·基泽尔顿和里格原本会带着他们的科多兽经过科尔卡半人马村，但每当听到半人马的战鼓声时，他们就会停下来。考克请求你护送商队穿过科尔卡村，酬劳会在前方不远处的瑟卡布斯库的营地由斯米德·瑟卡布斯库支付。",h="考克·基泽尔顿和里格原本会带着他们的科多兽经过科尔卡半人马村，但每当听到半人马的战鼓声时，他们就会停下来。考克请求你护送商队穿过科尔卡村，酬劳会在前方不远处的瑟卡布斯库的营地由斯米德·瑟卡布斯库支付。",kw={"保镖","半人马","考克·基泽尔顿","凄凉之地","基泽尔顿商队","科尔卡","里格","斯米德·瑟卡布斯库"},sec={{t="战鼓",b="考克·基泽尔顿和里格原本会直接带着他们的科多兽经过科尔卡半人马的地盘。偶尔半人马的战鼓声响起，商队就会停下来，因为死掉的商人是赚不到钱的。考克请求你护送商队穿过科尔卡村，虽然距离不长，但请务必让商队完整无损。商队正等在科尔卡村的北面，雷斧堡垒的东南方。"},{t="斯米德·瑟卡布斯库",b="酬劳在前方不远处的瑟卡布斯库的营地由斯米德·瑟卡布斯库支付。斯米德和基泽尔顿商队做些小生意。"}},faq={{q="谁是考克·基泽尔顿？",a="考克·基泽尔顿与里格一起带领着一支科多兽商队穿过凄凉之地。每当半人马的战鼓声响起，他们就会停下来。",al={"考克·基泽尔顿","谁发布了雇佣保镖任务","谁开启此任务"}},{q="为什么商队需要护送？",a="考克和里格每当听到半人马的战鼓声就会停下来，因为死掉的商人是赚不到钱的。",al={"为什么要雇佣保镖","为什么商队停下了","他们为什么要等待"}},{q="这次护送任务从哪里开始？",a="科尔卡村的北面，以及雷斧堡垒的东南方。",al={"雇佣保镖任务地点","商队从哪里出发","护送起始点"}},{q="报酬在哪里领取？",a="在前方不远处的瑟卡布斯库的营地，由斯米德·瑟卡布斯库发放。斯米德和考克做些小生意。",al={"谁给奖励","在哪里交任务","斯米德是谁"}}},fp="18,183,9.325.0,19.147.0,21.112.0,37.125.0,29.84.0,29.131.0"}
P.entries["quest:583"] = {n="欢迎来到丛林",s="巴尼尔·石罐欢迎来到荆棘谷北部狩猎营地的新手。他看出你是一位久经沙场的流浪者，于是为你引荐了探险队的领袖，著名猎人赫米特·奈辛瓦里。",h="巴尼尔·石罐欢迎来到荆棘谷北部狩猎营地的新手。他看出你是一位久经沙场的流浪者，于是为你引荐了探险队的领袖，著名猎人赫米特·奈辛瓦里。",kw={"巴尼尔","赫米特","奈辛瓦里","豹","迅猛龙","石罐","荆棘谷","虎"},ang={["class:Hunter"]="对于一名在荆棘谷丛林中游荡的猎人来说，赫米特·奈辛瓦里或许会有一些狩猎技巧可以分享。",["faction:Alliance"]="巴尼尔·石罐指出，赫米特·奈辛瓦里是一位著名的联盟战争英雄，对同行老兵格外青睐。",["race:Dwarf"]="营地著名的猎人赫米特·奈辛瓦里和你一样是矮人，巴尼尔·石罐特别向你推荐他为大型猎物狩猎大师。"},sec={{t="觐见大师",b="巴尼尔·石罐在荆棘谷丛林的营地欢迎新来者，他一眼就能认出经验丰富的战士。他为你指出了赫米特·奈辛瓦里——一位著名的联盟战争英雄和无与伦比的追踪者。奈辛瓦里只接纳久经考验的老兵，而巴尼尔认为，这位老神枪手或许愿意向一位经历过战斗考验的人传授他的狩猎智慧。"},{t="探险队的试炼",b="奈辛瓦里热情地欢迎了你，并指出在这片荒野见到你这样的职业是非常罕见的。他解释说，他的探险队聚集在这里只有一个目标：追捕一头传说中难以捉摸的丛林野兽。虽然他愿意让你加入这场伟大的狩猎，但信任必须通过猎杀低级猎物来赢取。奈辛瓦里亲自负责追踪迅猛龙的行动，而他的同伴阿杰克和埃尔格丁爵士则会指导猎人如何对付老虎和豹子。"}},faq={{q="赫米特·奈辛瓦里是谁？",a="赫米特·奈辛瓦里是一位著名的联盟战争老兵，也是一位享有盛誉的大型猎物猎人。他带领着一支探险队驻扎在荆棘谷的丛林中。",al={"赫米特·奈辛瓦里","赫米特是谁","奈辛瓦里背景故事"}},{q="是谁派你去找奈辛瓦里谈话的？",a="巴尼尔·石罐，驻扎在丛林营地的成员之一，在认出冒险家的战斗经验后，会引导他们去向奈辛瓦里致意。",al={"巴尼尔·石罐","任务发布者","谁开启了欢迎来到丛林"}},{q="和奈辛瓦里谈话后会发生什么？",a="将会开启几项狩猎任务：迅猛龙狩猎、虎王狩猎、豹王狩猎和荆棘谷的青山。",al={"如何加入狩猎","奈辛瓦里的试炼","狩猎课程"}}},fp="21,181,27.334.0,28.373.1,24.144.0,39.134.0,42.140.0"}
P.entries["quest:584"] = {n="血顶之颅",s="在整理完丛林中收集的战利品后，尼姆布亚证实失踪的年轻巨魔耶尼库并不在其中。为了查明耶尼库命运的真相，暗矛部族试图从敌对的血顶氏族首领那里强行索取答案。",h="在整理完丛林中收集的战利品后，尼姆布亚证实失踪的年轻巨魔耶尼库并不在其中。为了查明耶尼库命运的真相，暗矛部族试图从敌对的血顶氏族首领那里强行索取答案。",kw={"血顶氏族","大熔炉","暗矛部族","甘祖拉","格罗姆高","内兹里奥克","尼姆布亚","耶尼库","祖昆达"},ang={["faction:Horde"]="格罗姆高营地的部落战士为暗矛部族搜寻耶尼库提供了支援。",["race:Troll"]="对于暗矛部族而言，对抗血顶氏族酋长意味着要面对一个敌对部族的首领。"},sec={{t="从死者口中索求答案",b="在之前的狩猎行动证实耶尼库并不在血顶氏族的战利品中之后，尼姆布亚将目光投向了更高层的首领来寻求答案。血顶氏族酋长甘祖拉和他的巫医恐怖的内兹里奥克是暗矛部族的敌人，绝不会心甘情愿地开口。尼姆布亚打算从他们死后的尸体上强行逼问出真相，将他们的头颅带到格罗姆高营地的大熔炉里，好让他们开口说话。"},{t="进入祖昆达",b="两位血顶氏族的首领都栖身于荆棘谷西北部的祖昆达废墟深处。尼姆布亚打算夺取他们的头颅并将其投入沸腾的药水之中，以此逼迫他们说出关于耶尼库的消息。"}},faq={{q="为什么尼姆布亚想要甘祖拉和内兹里奥克的头颅？",a="耶尼库仍然下落不明，尼姆布亚相信只有血顶氏族的酋长和他的巫医掌握着真相。由于这些首领是暗矛部族的敌人，绝不会主动开口，尼姆布亚计划利用大熔炉从他们死后的唇间强行逼问出真相。",al={"为什么要杀死血顶氏族首领","为什么要用割下的头颅","尼姆布亚的动机"}},{q="甘祖拉和内兹里奥克在哪里？",a="这两位巨魔首领都居住在荆棘谷西北部，靠近海滩的祖昆达废墟深处。",al={"甘祖拉在哪里","内兹里奥克在哪里","寻找血顶氏族酋长","祖昆达的位置"}},{q="头颅交付后会发生什么？",a="割下的头颅会被直接放入格罗姆高营地翻滚的大熔炉中，这样就能让这两位首领开口说话了。",al={"头颅要送到哪里","我该如何处理这些头颅","翻滚的大熔炉任务交付"}},{q="这与搜寻耶尼库有什么关联？",a="这项调查始于对年轻耶尼库的搜寻。在之前的搜集头颅行动证明他不在那些普通的死者中之后，审问血顶氏族的首领便成了追查他下落的下一步努力。",al={"耶尼库任务线","与狩猎耶尼库的关联"}}},fp="21,158,31.363.0,14.186.0,58.212.0,41.114.0,42.122.0,48.181.0"}
P.entries["quest:585"] = {n="奈兹里奥克",s="在击败了血顶的巫医之后，他被砍下的头颅在格罗姆高营地的一个沸腾的大锅中说话。他声称知道失踪的暗矛巨魔的孩子被带到了哪里，但拒绝在没有残酷贡品的情况下泄露秘密。",h="在击败了血顶的巫医之后，他被砍下的头颅在格罗姆高营地的一个沸腾的大锅中说话。他声称知道失踪的暗矛巨魔的孩子被带到了哪里，但拒绝在没有残酷贡品的情况下泄露秘密。",kw={"巴里亚曼","血顶","大锅","格罗姆高","奈兹里奥克","裂颅者","荆棘谷","耶尼库","赞塔加","祖玛维"},ang={["faction:Horde"]="部落依靠在格罗姆高营地与一个被束缚的敌对灵魂进行谈判，来揭开暗矛酋长之子耶尼库失踪的真相。",["race:Troll"]="暗矛巨魔必须与一颗敌对的血顶巫医的断头进行交易，以揭开他们酋长失踪儿子的下落。"},sec={{t="灵魂的代价",b="尽管在搜寻血顶氏族首领的过程中，奈兹里奥克的灵魂被束缚在沸腾的大锅里，但他一点也不配合。他承认知道耶尼库被带到了哪里，但在透露信息之前，他要求进行安抚。他命令从敌对的裂颅者部族那里取回三颗战利品骷髅，并带到他安息的地方，以确保他离去的灵魂能在虚空中统御奴仆。"},{t="敌人的头颅",b="奈兹里奥克要求从巴里亚曼的裂颅者战利品堆中直接拿一颗头颅，从赞塔加拿第二颗，从祖玛维拿第三颗。只有当这三件贡品都摆在他的头颅旁边时，这位已死的巫医才会认为他的灵魂得到了满足。"}},faq={{q="谁是奈兹里奥克？",a="奈兹里奥克曾是血顶部族的一名巫医。在战斗中倒下后，他被砍下的头颅被放置在格罗姆高营地的一个沸腾大锅中，他被束缚的灵魂在那里继续说话。",al={"奈兹里奥克","巫医奈兹里奥克","奈兹里奥克的背景故事"}},{q="奈兹里奥克要求什么？",a="他要求从他所憎恨的对手——裂颅者的营地中偷取三颗战利品骷髅：一颗来自巴里亚曼，一颗来自赞塔加，一颗来自祖玛维。",al={"奈兹里奥克想要什么","奈兹里奥克的战利品","与奈兹里奥克交谈的任务目标"}},{q="为什么奈兹里奥克想要裂颅者的战利品？",a="奈兹里奥克想要将这些战利品骷髅放在他身边，这样当他的灵魂进入虚空时，他就能拥有三个在死后受他奴役的仆人。",al={"为什么需要头颅战利品","为什么奈兹里奥克需要头颅"}},{q="这件事发生在什么地方？",a="这个事件发生在荆棘谷深处，格罗姆高营地的一口沸腾的大锅旁。",al={"奈兹里奥克在哪里","沸腾大锅的位置"}}},fp="22,186,16.295.0,20.233.0,16.188.0,26.161.0,46.150.0,23.101.0"}
P.entries["quest:586"] = {n="甘祖拉恩",s="即便是在格罗姆高营地的沸腾药水中身首异处，血顶巨魔酋长加兹瑞拉依然怒火中烧。为了平息他那挥之不去的怒火，这个残缺的灵魂要求杀死他那苦大仇深的裂颅者对手，并毁掉他们的统治者：残忍的安娜塞克。",h="即便是在格罗姆高营地的沸腾药水中身首异处，血顶巨魔酋长加兹瑞拉依然怒火中烧。为了平息他那挥之不去的怒火，这个残缺的灵魂要求杀死他那苦大仇深的裂颅者对手，并毁掉他们的统治者：残忍的安娜塞克。",kw={"安纳希克","狂暴者","血顶","大熔炉","加兹瑞拉","格罗姆高","猎头者","裂颅者","荆棘谷"},ang={["faction:Horde"]="加兹瑞拉的头颅位于格罗姆高营地的大锅中，他派遣部落勇士去对抗他的裂颅者敌人。",["race:Troll"]="对于暗矛巨魔来说，看着像血顶和裂颅者酋长这样的世仇将他们不灭的仇恨转向彼此，是对丛林残酷纷争的一声沉痛提醒。"},sec={{t="酋长的复仇",b="在收集了血顶氏族的首领头颅之后，加兹瑞拉的断头继续诅咒着每一个站在沸腾大锅旁的人。由于对捕获者和世仇的双重仇恨，这位死去的酋长指引了一条平息他沸腾怒火的道路：袭击裂颅者部落的东部据点。他要求屠杀他们的猎手、猎头者和狂暴者，并怂恿旅行者去对抗他们凶猛的战团，直至战死。"},{t="破碎的护甲",b="加兹瑞拉预料到这场袭击会以惨败告终，他深信残忍的安娜塞克酋长会撕碎任何胆敢挑战他的入侵者。他要求必须从裂颅者统治者身上剥下破碎的护甲作为胜利的证明。只有将这个战利品带回格罗姆高营地的大熔炉，才能满足这位死去的酋长的怨念。"},{t="不安的和平",b="献上安娜塞克的破碎护甲平息了加兹瑞拉的侮辱。面对对手倒台的现实，酋长那复仇的怒火终于消退了。虽然他承认了击败安娜塞克所需要的力量，但他承诺这场胜利只是推迟了他们清算的日子，发誓要在虚空中再次交锋。"}},faq={{q="加兹瑞拉想让你去哪里？",a="加兹瑞拉指示你向东进入裂颅者的领地中心，前往残忍的安娜塞克指挥下战士们聚集的定居点。",al={"裂颅者在哪里","与加兹瑞拉交谈要去哪里","裂颅者位置"}},{q="谁是残忍的安娜塞克？",a="残忍的安娜塞克是裂颅者巨魔的酋长，也是加兹瑞拉和血顶部落的宿敌。",al={"安娜塞克是谁","谁是裂颅者酋长","残忍的安娜塞克背景故事"}},{q="为什么加兹瑞拉还能说话？",a="加兹瑞拉的断头被浸泡在格罗姆高营地的附魔大锅中，这让他的灵魂能够在他死后发出挥之不去的诅咒和要求。",al={"加兹瑞拉如何说话","为什么头颅在说话","加兹瑞拉大锅"}},{q="加兹瑞拉索要什么战利品？",a="他要求从残忍的安娜塞克酋长身上剥下破碎的护甲，并屠杀裂颅者的猎手、猎头者和狂暴者。",al={"加兹瑞拉需要什么物品","安娜塞克的破碎护甲","加兹瑞拉任务提交物品"}},{q="帮助加兹瑞拉后接下来会发生什么？",a="在解决了各部落酋长之后，探索将继续深入，通过“耶尼库的命运”来揭开这位年轻的暗矛巨魔的下落。",al={"与加兹瑞拉交谈后接什么","加兹瑞拉后的下一个任务","与加兹瑞拉交谈后续"}}},fp="23,199,23.337.0,16.292.0,15.303.1,36.108.0,26.109.0,30.136.0,34.131.0,40.143.0"}
P.entries["quest:5863"] = {n="砂槌食人魔",s="加基森的安迪·利恩警告说，最近有一大群游荡的食人魔抵达了塔纳利斯。他们在镇子南面建立了一个营地，安迪·利恩希望在他们积蓄力量之前将其摧毁。",h="加基森的安迪·利恩警告说，最近有一大群游荡的食人魔抵达了塔纳利斯。他们在镇子南面建立了一个营地，安迪·利恩希望在他们积蓄力量之前将其摧毁。",kw={"安迪·利恩","砂槌","砂槌蛮兵","砂槌营地","砂槌执法者","加基森","蹂躏者戈尔玛洛克","食人魔","塔纳利斯"},sec={{t="沙漠里的食人魔",b="最近，一大群游荡的食人魔抵达了塔纳利斯。他们在加基森南面占据了大片沙漠，并建立了砂槌营地。还有几支较小的食人魔队伍在沙漠中游荡，其中一些甚至入侵了古老的巨魔废墟。安迪·利恩说，绝不能让这些食人魔积蓄力量。"},{t="擒贼先擒王",b="安迪·利恩希望你消灭十个砂槌蛮兵和十个砂槌执法者。这群食人魔的领袖是蹂躏者戈尔玛洛克，安迪·利恩认为，一旦他失去了指挥权，这些食人魔就会开始土崩瓦解。"}},faq={{q="谁要求摧毁砂槌营地？",a="加基森的安迪·利恩。",al={"安迪·利恩","任务发布者是谁","任务发布者"}},{q="砂槌营地在哪里？",a="在加基森南面，食人魔占据的那片广阔沙漠区域中。",al={"砂槌营地位置","食人魔在哪里"}},{q="谁在领导砂槌食人魔？",a="蹂躏者戈尔玛洛克是这群食人魔的领袖。安迪·利恩认为，只要他不再指挥，这些食人魔就会开始崩溃。",al={"食人魔领袖","戈尔玛洛克是谁","蹂躏者戈尔玛洛克"}},{q="为什么安迪·利恩认为这些食人魔很危险？",a="安迪·利恩说，绝不能让这些食人魔积蓄力量。一大群食人魔在镇子南面占据了一个营地，其他较小的队伍也在沙漠中游荡，其中一些还侵占了古老的巨魔废墟。",al={"为什么要杀食人魔","塔纳利斯的食人魔威胁"}}},fp="21,148,19.273.0,20.194.0,51.73.0,31.68.0,29.123.0,45.177.0"}
P.entries["quest:587"] = {n="鼻烟",s="在藏宝海湾，海盗迪格在港口时总喜欢来上一瓶格罗格酒和一点上好的鼻烟，但镇上的草药商却卖光了。草药商说血帆海盗劫持了这批货物，迪格想让你给他带十五份鼻烟来。",h="在藏宝海湾，海盗迪格在港口时总喜欢来上一瓶格罗格酒和一点上好的鼻烟，但镇上的草药商却卖光了。草药商说血帆海盗劫持了这批货物，迪格想让你给他带十五份鼻烟来。",kw={"血帆","藏宝海湾","迪格","格罗格酒","草药商","鼻烟"},sec={{t="岸上的恶习",b="迪格承认海上生活可能并不算什么美好生活，但这却是迪格唯一的生活方式。在港口时，迪格总是寻找格罗格酒和优质的鼻烟：虽然是坏习惯，但海盗总得有点自己的消遣。迪格得知藏宝海湾的草药商那里已经没有存货时感到非常沮丧。草药商声称血帆海盗劫持了那批货物。迪格觉得一位无所畏惧的冒险者或许能说服海盗分享战利品，他需要十五份鼻烟。"},{t="迪格的感谢",b="迪格对这些鼻烟感到非常满意，很高兴能在起航前及时收到，并像对待老朋友一样热切地感谢你。"}},faq={{q="迪格是谁？",a="迪格是藏宝海湾的一名海盗，在港口时总喜欢寻找格罗格酒和上好的鼻烟。",al={"迪格 藏宝海湾","谁发布了岸上的恶习"}},{q="为什么草药商没有鼻烟了？",a="据草药商所说，那一批鼻烟被血帆海盗劫持了。",al={"为什么没有鼻烟","草药商 货物被劫"}},{q="谁有鼻烟？",a="据草药商所说，血帆海盗劫持了那批货物，迪格希望能说服他们分享一些。",al={"谁拿走了鼻烟","血帆鼻烟"}},{q="迪格需要多少鼻烟？",a="十五份鼻烟，送到藏宝海湾给迪格。",al={"多少鼻烟","岸上的恶习需求"}}},fp="11,191,12.324.0,13.115.1,12.90.0,34.78.0,18.109.0,30.63.0"}
P.entries["quest:588"] = {n="耶尼库的命运",s="在格罗姆高营地，奈兹里奥克的头颅从冒泡的大熔炉中说话，准备讲述年轻的暗矛巨魔耶尼库遭遇了什么。肯维雷站在锅边，等待着倾听灵魂的话语。",h="在格罗姆高营地，奈兹里奥克的头颅从冒泡的大熔炉中说话，准备讲述年轻的暗矛巨魔耶尼库遭遇了什么。肯维雷站在锅边，等待着倾听灵魂的话语。",kw={"大熔炉","格罗姆高","肯维雷","奈兹里奥克","耶尼库","赞吉尔"},ang={["faction:Horde"]="找回酋长的儿子对于暗矛部族及其驻扎在格罗姆高营地的盟友来说至关重要。"},sec={{t="锅中的话语",b="在安抚了甘祖拉和奈兹里奥克的灵魂之后，你倾听着冒泡的大熔炉里的头颅终于揭示了它的秘密。肯维雷正站在大熔炉边，等待着听这一切。"},{t="头颅揭示的内容",b="奈兹里奥克宣称耶尼库已经脱离了他的部族，被放逐者赞吉尔带走了。赞吉尔已经彻底束缚了这个男孩，除非有非常强大的魔法，否则无法让他重获自由。肯维雷听后，只剩下了一线希望。"}},faq={{q="谁揭示了耶尼库的下落？",a="奈兹里奥克的头颅通过冒泡的大熔炉开口，揭示了耶尼库的遭遇。",al={"谁在大熔炉中说话","谁揭示了耶尼库的命运","大熔炉的声音"}},{q="应该把奈兹里奥克的话告诉谁？",a="肯维雷站在格罗姆高营地北缘的冒泡大熔炉旁，他需要知道奈兹里奥克揭示了什么。",al={"我该和谁交谈","耶尼库的命运任务交付","肯维雷的位置"}}},fp="19,126,21.156.0,22.209.1,34.88.0,43.132.0"}
P.entries["quest:5881"] = {n="召回卫兵",s="“召唤预备役”是一个部落信使任务，委托给正在烈日石居休息的冒险者。马格兰让你前往贫瘠之地南部的边缘，命令你替换掉一名守卫升降梯、已精疲力竭的哨兵。",h="“召唤预备役”是一个部落信使任务，委托给正在烈日石居休息的冒险者。马格兰让你前往贫瘠之地南部的边缘，命令你替换掉一名守卫升降梯、已精疲力竭的哨兵。",kw={"召唤预备役","升降梯","瑞什·远行者","马格兰","石爪山脉","烈日石居","贫瘠之地","千针石林"},ang={["faction:Horde"]="这项任务展示了部落指挥官如何管理卡利姆多边境的部队，通过轮换哨兵来保持士气和哨所的稳定。",["race:Tauren"]="协助轮换升降梯的哨兵，有助于维持连接卡利姆多南部区域与雷霆崖更广阔领土的这条重要通道。"},sec={{t="期待已久的换防",b="即使在第三次战争后的相对繁荣时期，维持卡利姆多中部的驻军依然在考验着部落的资源。在石爪山脉的烈日石居，马格兰负责监督后勤和部队福利。马格兰意识到久经沙场的老兵在漫无止境的守卫任务下早已疲惫不堪，于是向南方的升降梯寄出一封调任信，而那里的一名年轻哨兵瑞什·远行者已经远离家乡，独自驻守多时。"},{t="守卫升降梯",b="升降梯是连接南贫瘠之地的高原与千针石林风蚀峡谷的唯一工程动脉。将这封信交给瑞什，将让他从孤立且单调的升降梯机械守卫工作中解脱出来，使他最终能够回到家人身边，并让新的预备役人员接替岗位。"}},faq={{q="谁发放这个任务？",a="马格兰在坐落于石爪山脉高处的烈日石居发放该任务。",al={"任务发布者","如何获取召唤预备役","马格兰位置"}},{q="我该把马格兰的信件送到哪里？",a="你必须带着马格兰的信件穿过贫瘠之地，一路向南前往升降梯，这是一座位于边界处、俯瞰千针石林的巨大木制升降结构。",al={"瑞什·远行者位置","瑞什在哪里","升降梯在哪里"}},{q="瑞什·远行者为什么要换防？",a="瑞什独自驻守升降梯机械已有一段时间了。他早些时候正式提交了换防请求，以便能够回家探望家人。",al={"瑞什背景故事","瑞什为何离开","升降梯哨兵任务"}},{q="这个任务需要战斗吗？",a="不需要战斗。这纯粹是一个信使任务，旨在引导旅行者向南前往千针石林。",al={"我需要战斗吗","和平任务","信使任务"}},{q="完成该任务会获得哪个阵营的声望？",a="将信件交给瑞什可以获得雷霆崖声望，这反映了牛头人对这条路线的管辖和管理。",al={"声望奖励","这个任务奖励什么声望","雷霆崖声望"}},{q="这个任务接下来会导向哪里？",a="这次递送会把你直接带到升降梯顶部，使你能够乘电梯下到千针石林的峡谷中，以探索更多的部落哨站。",al={"后续任务","之后去哪里","千针石林指引任务"}}},fp="23,180,21.382.0,17.227.0,22.89.0,36.98.0,38.141.0,44.73.0,52.95.0,32.144.0"}
P.entries["quest:589"] = {n="歌唱水晶",s="肯维雷正在寻找营救年轻的耶尼库的方法，以让他摆脱侵蚀他的黑暗。在了解了耶尼库的困境后，这位巫医计划找到一颗被称为“心灵之眼”的传奇宝石，并派遣你去收集掌握其力量所需的共鸣碎片。",h="肯维雷正在寻找营救年轻的耶尼库的方法，以让他摆脱侵蚀他的黑暗。在了解了耶尼库的困境后，这位巫医计划找到一颗被称为“心灵之眼”的传奇宝石，并派遣你去收集掌握其力量所需的共鸣碎片。",kw={"水晶矿洞","格罗姆高","铁颚蛇颈龙","肯维雷","心灵之眼","脉动的蓝色碎片","荆棘谷","耶尼库"},ang={["faction:Horde"]="这一努力旨在帮助格罗姆高营地的暗矛部族，以协助他们全力营救暗矛酋长失踪儿子的绝望斗争。"},sec={{t="心灵之眼的回响",b="在得知耶尼库的可怕遭遇后，医药师肯维雷转向古老的丛林传说寻求答案。传说中提到的心灵之眼是一颗隐藏在荆棘谷深处的宝石，拥有巨大的魔法力量。肯维雷相信这块宝石可能掌握着让这位年轻巨魔灵魂获得自由的秘密。在他向丛林之灵寻求指引以确定其位置的同时，他需要稀有的催化剂来安全地驾驭这颗宝石的强大魔法。"},{t="水晶矿洞",b="肯维雷指引你前往东南方向的水晶矿洞，那里生活着栖息于地下的铁颚蛇颈龙。你需要从这些生物身上找回三块脉动的蓝色碎片。肯维雷打算在最后的仪式中引导这些鸣响之石的固有魔法，以便在找回心灵之眼后将其强大的力量纳入掌控。"}},faq={{q="谁发布了这个任务？",a="肯维雷，一位驻扎在荆棘谷格罗姆高营地的巨魔医药师，发布了这项任务。",al={"谁发布了鸣响之水晶","任务发布者","在哪里开始鸣响之水晶任务"}},{q="为什么需要脉动的蓝色碎片？",a="肯维雷需要利用它们的魔法来控制心灵之眼，他打算用这颗强大的宝石将耶尼库从束缚他的黑暗力量中解救出来。",al={"为什么需要蓝色碎片","碎片有什么用","脉动的蓝色碎片的作用"}},{q="在哪里可以找到铁颚蛇颈龙？",a="它们栖息在水晶矿洞内，该矿洞位于格罗姆高营地东南方，古拉巴什竞技场东面的山峰之上。",al={"铁颚蛇颈龙位置","铁颚蛇颈龙在哪里","水晶矿洞在哪里"}},{q="这个任务的前置任务是什么？",a="这个任务紧接在“耶尼库的命运”之后，该任务说明了这位年轻巨魔的危急处境。",al={"鸣响之水晶前置任务","上一个任务"}},{q="当你去收集碎片时，肯维雷在做什么？",a="他正在与丛林之灵沟通，以发掘心灵之眼的具体藏身之处，并找出守护它的东西。",al={"肯维雷在做什么","肯维雷的作用"}}},fp="20,163,24.314.0,23.315.0,21.95.0,39.151.0,41.121.0,27.81.0,53.110.0"}
P.entries["quest:59"] = {n="布甲和皮甲",s="“布甲与皮甲”是闪金镇的治安官杜汉委派的一项任务。由于对一名冒险者的表现印象深刻，杜汉签发了一张正式的暴风城护甲标记，可以在当地工匠萨拉·迪博雷恩处兑换。这项任务指引新兵向东穿过卫兵托马斯把守的桥梁，前往东谷伐木场，从而获得装备以保卫王国。",h="“布甲与皮甲”是闪金镇的治安官杜汉委派的一项任务。由于对一名冒险者的表现印象深刻，杜汉签发了一张正式的暴风城护甲标记，可以在当地工匠萨拉·迪博雷恩处兑换。这项任务指引新兵向东穿过卫兵托马斯把守的桥梁，前往东谷伐木场，从而...",kw={"护甲标记","布甲与皮甲","东谷","艾尔文森林","卫兵托马斯","伐木场","治安官杜汉","萨拉·迪博雷恩","暴风城军队"},ang={["faction:Alliance"]="通过当地合同为保卫者提供装备，展示了艾尔文森林的乡村社区如何在首都政治瘫痪的情况下维持联盟的运作。",["profession:Tailoring"]="萨拉·迪博雷恩与军队的委任关系表明，布甲制作是王国中一项关键的、官方赞助的军事贸易。",["race:Human"]="为治安官杜汉效力并与萨拉·迪博雷恩进行交易，反映了将艾尔文森林的小型家园凝聚在一起的共同公民纽带。"},sec={{t="治安官的信物",b="卫兵托马斯在艾尔文森林东部的河边桥梁处站岗，守卫边境，抵御敌对的鱼人和游荡的豺狼人。当有能力的旅者将他的报告带到闪金镇时，治安官杜汉会以一张正式的暴风城护甲标记作为奖励，而不是从驻军本就稀缺的储备中调拨装备。此标记作为一份军事征用凭证，正式认可了持有者对王国的贡献。"},{t="东谷的织造者",b="穿过东边的桥梁就是东谷伐木场，这是艾尔文森林主要的木材作业点。萨拉·迪博雷恩在这个定居点工作，她持有暴风城军队的正式委任状，负责生产布甲和皮甲装备。由于王国的中央军械库资源紧张、捉襟见肘，像萨拉这样的当地工匠对于为前线的部队和辅助侦察兵配备装备至关重要。"}},faq={{q="什么是暴风城护甲标记？",a="这是一张由像治安官杜汉这样的军官签发的正式军事征用单。军官们不会在哨所储备笨重的护甲套装，而是随身携带标记，允许受信任的新兵从受委任的民间工匠那里领取量身定制的护甲。",al={"护甲标记","暴风城凭证","什么是标记"}},{q="萨拉·迪博雷恩是谁？",a="萨拉·迪博雷恩是一位居住在东谷伐木场的裁缝和工匠。她与暴风城军队签有合同，为王国人员和获准的辅助战斗人员制作布甲和皮甲装备。",al={"萨拉·迪博雷恩","东谷裁缝","谁制作护甲"}},{q="东谷伐木场在哪里？",a="东谷伐木场位于艾尔文森林的最东端。从卫兵托马斯的河桥哨所出发，沿路向东进入林木繁茂的山谷，那里有伐木工在为王国采伐木材。",al={"东谷位置","东谷在哪里","如何找到迪博雷恩"}},{q="为什么治安官杜汉要把冒险者派往东谷？",a="杜汉不会直接从他在闪金镇的哨所分发成品装备。相反，他通过将新兵派往萨拉·迪博雷恩处来奖励勇敢的行为，在指引旅者前往东谷的同时，确保他们得到妥善的保护，以保卫艾尔文森林。",al={"为什么杜汉给标记","杜汉的目的","为什么去东谷"}},{q="为什么军队要依靠当地裁缝来提供补给？",a="由于瓦里安·乌瑞恩国王失踪，且暴风城的兵力在应对迪菲亚兄弟会的活动和野生兽群时捉襟见肘，当地防卫哨所极度依赖与区域工人的合同来维持供应线。",al={"暴风城补给问题","为什么需要当地工匠","军队后勤"}},{q="卫兵托马斯在防范谁？",a="卫兵托马斯监视着艾尔文森林的东部边界，守护着桥梁，防止来自河栖鱼人、潜行野兽以及毗邻赤脊山的危险荒野的入侵。",al={"卫兵托马斯的敌人","桥梁的威胁","艾尔文森林东部威胁"}}},fx={ebb61187={q="治安官杜汉为什么要做这件事？",a="你从东部边境送来了卫兵托马斯的报告，治安官杜汉希望嘉奖你的英勇与机敏。他交给你一枚正式的军需凭证，让你拿去找萨拉·迪博雷恩，确保你能配上结实的布甲或皮甲，继续保卫艾尔文森林，抵御日益严峻的威胁。",al={"治安官杜汉的动机","为什么派去找萨拉·迪博雷恩","为什么给护甲凭证"}}},fp="23,236,19.363.0,22.315.0,33.270.0,23.210.0,35.188.0,53.223.0,54.199.0,38.162.0"}
P.entries["quest:590"] = {n="潜行者的交易",s="“盗贼的交易”是与丧钟镇的卡尔文·蒙泰古之间的一场对峙。在以财富为诱饵向新复生的被遗忘者提供工作后，当索要报酬时，这位狡猾盗贼的真实意图便暴露无遗。",h="“盗贼的交易”是与丧钟镇的卡尔文·蒙泰古之间的一场对峙。在以财富为诱饵向新复生的被遗忘者提供工作后，当索要报酬时，这位狡猾盗贼的真实意图便暴露无遗。",kw={"盗贼的交易","斗殴","卡尔文·蒙泰古","丧钟镇","被遗忘者盗贼","诈骗","提瑞斯法林地"},ang={["class:Rogue"]="与卡尔文·蒙泰古打交道给年轻的盗贼上了一堂职业风险课：不要相信任何人，看好你的钱袋，永远不要让其他无赖带着你的那一份报酬溜走。",["race:Undead"]="在丧钟镇醒来很快就证明了死亡并不能剥夺人类最卑劣的恶习；被遗忘者扒手坑骗自己同类的速度和活着的强盗一样快。"},sec={{t="不光彩的承诺",b="卡尔文·蒙泰古徘徊在丧钟镇的墓穴附近，向新复生的被遗忘者提供看似轻松的工作。蒙泰古谎称只要送一封信就能赚取丰厚的报酬，从而将涉世未深的冒险者置于险境。然而，当差事完成后，蒙泰古却对支付报酬的承诺装傻充愣，假装对任何约定或欠款一无所知。"},{t="付出代价",b="当被迫履行承诺时，蒙泰古露出了真面目。他不仅不愿交出银币，反而拔出武器，赌定自己能轻易干掉一个毫无经验的新手。通过武力教训这名盗贼迫使他屈服。鼻青脸肿的他吐出了一部分钱财，并坦率承认他撒谎是因为觉得可以侥幸逃脱报酬。"}},faq={{q="为什么卡尔文·蒙泰古在被索要报酬时会发动攻击？",a="卡尔文·蒙泰古是一个毫无职业道德的盗贼，他从未打算分享他的钱财。当因为背信弃义被质问时，他试图永远让他的合伙人闭嘴，而不是支付报酬，因为他认定刚复生的被遗忘者是个容易对付的目标。",al={"为什么卡尔文会战斗","卡尔文·蒙泰古敌对","为什么盗贼会攻击"}},{q="这场对峙发生在哪里？",a="对峙直接发生在丧钟镇，即提瑞斯法林地西南部的一座废弃村庄，那里是新复生的被遗忘者最初醒来的地方。",al={"卡尔文·蒙泰古在哪里","卡尔文·蒙泰古位置","盗贼的交易在哪里"}},{q="卡尔文·蒙泰古真的支付了他承诺的报酬吗？",a="没有。在战斗中落败后，卡尔文投降并交出了一些钱币，但他承认这比他最初承诺的要少得多，因为他从一开始就在报酬金额上撒了谎。",al={"卡尔文的奖励","卡尔文会付钱吗","他是否在钱币上撒谎"}},{q="这项后续任务是如何解锁的？",a="在完成了卡尔文·蒙泰古最初的送信差事后，返回并再次与他交谈，索要他承诺的钱币。质疑他的欺诈行为会立即触发战斗。",al={"如何获得第二部分","解锁盗贼交易战斗","秘密盗贼任务"}},{q="卡尔文·蒙泰古在被打败后会死吗？",a="不会。蒙泰古在受到致命一击前就会投降，他会大肆恭维你的战斗技巧，并心不甘情不愿地打开钱袋以保住性命。",al={"我杀死了卡尔文吗","卡尔文死了吗","卡尔文投降"}},{q="这次遭遇给新的被遗忘者提供了什么教训？",a="它成为了被遗忘者残酷现实的一堂早期实践课：亡灵之间荣誉匮乏，言语廉价，尊重只能通过武力来赢得。",al={"盗贼交易的意义","盗贼的交易背后的故事"}}},fx={["80d08ba4"]={q="为什么你必须与卡尔文·蒙泰古战斗？",a="卡尔文·蒙泰古是个彻头彻尾的盗贼。他用财富的虚假承诺诱骗你替他干脏活，等你回来讨要报酬时却装作不知情。他不想付出银币，觉得直接攻击你更便宜、更容易，还指望你会成为任他宰割的猎物。想要拿回应得的报酬，你就得打到他服气，让他乖乖付钱。",al={"为什么要和卡尔文·蒙泰古战斗","卡尔文·蒙泰古要对付谁","为什么要攻击卡尔文"}}},fp="14,216,22.368.0,16.390.1,55.244.1,41.145.0,51.177.1,33.183.1,39.153.1,54.183.0"}
P.entries["quest:591"] = {n="心灵之眼",s="格罗姆高营地的肯维雷正在寻找一颗被称为“心灵之眼”的强力宝石，这件神器对于营救年轻的耶尼库至关重要。这块宝石现在落入了强大的食人魔施法者玛兹拉什手中，他居住在莫什奥格食人魔山深处。",h="格罗姆高营地的肯维雷正在寻找一颗被称为“心灵之眼”的强力宝石，这件神器对于营救年轻的耶尼库至关重要。这块宝石现在落入了强大的食人魔施法者玛兹拉什手中，他居住在莫什奥格食人魔山深处。",kw={"暗矛巨魔","格罗姆高","肯维雷","玛兹拉什","心灵之眼","莫什奥格","食人魔山","耶尼库"},ang={["faction:Horde"]="这次行动以格罗姆高营地为基地，代表暗矛巨魔直接向莫什奥格食人魔据点发起冲击。",["race:Troll"]="寻回心灵之眼对于释放暗矛酋长的儿子耶尼库至关重要。"},sec={{t="强力宝石",b="在寻回了歌唱水晶之后，肯维雷将注意力转向了获取心灵之眼。这件强大的神器是帮助营救暗矛巨魔酋长之子耶尼库的唯一工具。然而，这块宝石目前被玛兹拉什持有，这是一位残忍的食人魔术士，肯维雷还记得他在部落早期在丛林中活动时对方的存在。"},{t="莫什奥格的深处",b="玛兹拉什居住在格罗姆高东面的莫什奥格食人魔山深处。即使在获得心灵之眼之前，他的魔法造诣也已十分强大，而这块宝石更是增强了他的力量。在食人魔的据点中与他对抗充满了危险，但从他手中夺回这件神器依然是解救那名年轻巨魔的唯一希望。"},{t="进入虚空",b="随着宝石的寻回，肯维雷指出，击败玛兹拉什将把这位食人魔术士从血肉的世界放逐到虚空之中。虽然他的肉体威胁已经消除，但肯维雷心中仍隐约担心，玛兹拉什可能会在灵界开辟新的领地。不过，眼下这些担忧先被放到了一边，以便巫医可以准备拯救耶尼库所需的仪式。"}},faq={{q="谁拥有心灵之眼？",a="心灵之眼由玛兹拉什持有，这是一位将巢穴设在格罗姆高营地以东的莫什奥格食人魔山深处的食人魔术士。",al={"谁拥有心灵之眼","心灵之眼在哪里","谁掉落心灵之眼"}},{q="肯维雷为什么需要心灵之眼？",a="肯维雷需要这件神器来举行一场仪式，他认为这是拯救暗矛酋长失踪的儿子耶尼库的唯一方法。",al={"为什么需要心灵之眼","心灵之眼的用途","为什么要获取心灵之眼"}},{q="这在寻找耶尼库的任务中处于什么位置？",a="这紧随“歌唱水晶”任务之后。一旦心灵之眼到手，通往下一步“拯救耶尼库”的道路就会打开。",al={"心灵之眼的前置任务是什么","心灵之眼之前的任务","歌唱水晶之后是什么任务"}},{q="玛兹拉什是谁？",a="玛兹拉什是一位凶残的食人魔术士，肯维雷在暗矛巨魔居住在丛林的那个时代就已认识他。他的魔法非常强大，而心灵之眼的力量又进一步放大了他的能力。",al={"玛兹拉什是谁","关于玛兹拉什","玛兹拉什背景故事"}}},fp="14,127,14.266.0,22.253.0,15.306.1,29.94.0,40.126.0,48.97.0,16.152.0"}
P.entries["quest:592"] = {n="拯救耶尼库",s="在获得心灵之眼后，肯维雷将其制作成一颗特殊的灵魂宝石，以从流亡者赞吉尔手中救出年轻的巨魔耶尼库。这个附魔容器旨在击晕耶尼库并捕获他的灵魂，让他能够被解救并带回给尼姆布亚。",h="在获得心灵之眼后，肯维雷将其制作成一颗特殊的灵魂宝石，以从流亡者赞吉尔手中救出年轻的巨魔耶尼库。这个附魔容器旨在击晕耶尼库并捕获他的灵魂，让他能够被解救并带回给尼姆布亚。",kw={"阿博拉兹","肯维雷","尼姆布亚","拯救耶尼库","灵魂宝石","荆棘谷","耶尼库","赞吉尔"},ang={["faction:Horde"]="来自格罗姆高营地的部落冒险者们带着尼姆布亚对耶尼库的搜寻任务前往阿博拉兹废墟寻找流亡者赞吉尔。",["race:Troll"]="对于Darkspear tribe来说，将年轻的耶尼库从流亡者赞吉尔的邪恶魔法中解救出来，意味着将一名被俘的暗矛青年带回他的族人身边。"},sec={{t="灵魂容器",b="在找回心灵之眼后，肯维雷将这一强大的圣物重塑为一颗魔法灵魂宝石。它的双重附魔可以让冒险者先击晕耶尼库，然后将宝石放在他的头上，将他游离的灵魂捕获其中。一旦男孩的本质被封存在宝石内，就可以安全地将他送回格罗姆高营地的族人那里。"},{t="驱逐者的巢穴",b="耶尼库与流亡者赞吉尔一起居住在阿博拉兹废墟，这里位于荆棘谷海角南端的水晶海岸沿岸。要救出这名堕落的年轻人，需要冒险进入流亡者赞吉尔的领地，使用制作好的容器打破巫医对他的控制，并将装满的灵魂宝石带回给尼姆布亚。"}},faq={{q="是谁为这项任务提供了灵魂宝石？",a="肯维雷在重塑找回的心灵之眼后制作并提供了灵魂宝石，并派你去取回耶尼库的灵魂。",al={"谁给予灵魂宝石","在哪里获得灵魂宝石","谁开启了拯救耶尼库的任务"}},{q="耶尼库在哪里？",a="耶尼库可以在荆棘谷海角远处的阿博拉兹废墟，位于水晶海岸的流亡者赞吉尔身边找到。",al={"耶尼库在哪里","耶尼库位置","阿博拉兹废墟位置"}},{q="灵魂宝石是如何运作的？",a="经过重塑的宝石有两种附魔：首先用于击晕耶尼库，然后直接放在他的头上将他的灵魂吸入其中。",al={"如何使用灵魂宝石","灵魂宝石有什么用","荆棘谷灵魂宝石"}},{q="一旦耶尼库被救出，谁会接收装满的灵魂宝石？",a="一旦耶尼库的灵魂被安全地困在宝石中，就必须将其送回格罗姆高营地的尼姆布亚那里。",al={"在哪里交还装满的灵魂宝石","谁接收宝石","耶尼库交付地点"}}},fp="14,198,23.250.0,18.266.0,40.108.0,25.112.0,27.90.0,57.65.0"}
P.entries["quest:5921"] = {n="月光林地",s="月光林地是年轻的暗夜精灵德鲁伊学习与卡利姆多的神圣土地进行交流的入门仪式。在达纳苏斯的玛斯雷·驭熊者指导下，新手们学会了魔法传送咒语，将自己传送到世界另一端的月光林地，去会见永夜港的德迪利特·星焰。这标志着他们迈向掌握熊形态力量的精神之旅的开始。",h="月光林地是年轻的暗夜精灵德鲁伊学习与卡利姆多的神圣土地进行交流的入门仪式。在达纳苏斯的玛斯雷·驭熊者指导下，新手们学会了魔法传送咒语，将自己传送到世界另一端的月光林地，去会见永夜港的德迪利特·星焰。这标志着他们迈向掌握熊...",kw={"熊","塞纳里奥","德迪利特","玛斯雷","月光林地","永夜港","雷姆洛斯","星焰","传送"},ang={["class:Druid"]="这段旅程代表了你对全球德鲁伊传统的觉醒，为你提供了一条通往塞纳里奥议会宁静核心的永恒生命线。",["faction:Alliance"]="虽然达纳苏斯代表了联盟，但踏入月光林地提醒了暗夜精灵德鲁伊，有一种超越世俗阵营的更古老、更高的使命。",["race:NightElf"]="离开泰达希尔的枝叶前往古老的月光林地，将年轻的卡多雷与大分裂前保留下来的祖先家园直接联系在了一起。"},sec={{t="神圣的避难所",b="月光林地作为一处致力于塞纳留斯教诲的古老圣地，在艾泽拉斯的其他地方显得格外独特。在守护者雷姆洛斯的监管下，这里宁静的树林提供了安宁以及与自然的深度交流。对于一名年轻的德鲁伊来说，学习通过传送咒语将自己的灵魂跨越大地投射到月光林地是关键的一步，它使德鲁伊无论相隔多远都能随时获取德鲁伊智慧的核心。"},{t="议会政治",b="虽然月光林地向所有追寻荒野之路的人敞开大门，但这里也并非没有紧张气氛。在大德鲁伊范达尔·鹿盔与月光林地的守护者雷姆洛斯之间，围绕着自然治理和泰达希尔的创建问题，产生了一道日益加深的裂痕。尽管塞纳里奥议会内部存在这些哲学上的分歧，但年轻的学徒们依然受到永夜港无条件的欢迎，来此进行神圣的修行。"},{t="熊之道",b="抵达永夜港后，新手将来到德迪利特·星焰面前，这位长者负责引导新晋德鲁伊走上利爪之道。在任何学徒获取熊的斗篷之前，他们必须沉浸在熊的视角中：坚韧、狂怒以及对荒野毫不动摇的防守。星焰怀着对塞纳留斯大人的崇敬之情接待每一位新学生，并开启伟大的熊之灵的试炼。"}},faq={{q="德鲁伊为什么要学习传送到月光林地？",a="传送到月光林地能让德鲁伊直接连接到他们教派的核心。由于训练、与灵魂的交流以及高层会议都在永夜港进行，拥有一种瞬时的精神通道确保了每位修行者都能随时返回去学习和补充他们的精神能量。",al={"为什么要传送到月光林地","传送月光林地的目的","为什么要去月光林地"}},{q="德迪利特·星焰是谁？",a="德迪利特·星焰是一位驻扎在永夜港主要旅店上层的长者德鲁伊。他负责监督抵达月光林地的学徒，开启他们掌握动物视角的试炼——从原始的熊之灵开始。",al={"德迪利特·星焰的作用","德迪利特是谁","德迪利特·星焰"}},{q="范达尔·鹿盔和守护者雷姆洛斯之间存在什么紧张关系？",a="大德鲁伊范达尔·鹿盔在没有获得龙类守护巨龙祝福的情况下领导了泰达希尔的种植，为暗夜精灵追求一种更激进、更民族主义的姿态。而守护者雷姆洛斯和月光林地的传统主义者仍然致力于塞纳留斯古老、中立的道路，这在塞纳里奥议会内部造成了意识形态上的摩擦。",al={"鹿盔与雷姆洛斯的紧张关系","范达尔对决雷姆洛斯","议会分裂"}},{q="部落德鲁伊也能访问月光林地吗？",a="是的。月光林地是一个由守护者雷姆洛斯和塞纳里奥议会保护的中立避难所。暗夜精灵和牛头人德鲁伊都受到欢迎来到永夜港共同学习荒野之道，在塞纳留斯的和平庇护下放下阵营间的敌意。",al={"部落月光林地","牛头人可以去月光林地吗","月光林地是中立的吗"}},{q="见到德迪利特·星焰后会发生什么？",a="一旦你向德迪利特·星焰报到，他就会引导你进入伟大的熊之灵的仪式试炼。这种精神上的对抗将考验你的决心和理解力，之后你才被允许驾驭熊的原始力量。",al={"月光林地任务之后","熊形态下一步","熊任务后续"}},{q="德迪利特在永夜港的什么位置？",a="德迪利特·星焰位于永夜港中心附近主要的暗夜精灵旅店内，站在二楼阳台上俯瞰着整个村庄。",al={"寻找德迪利特·星焰","德迪利特·星焰位置","德迪利特在哪里"}}},fp="9,196,15.292.0,22.310.0,20.299.0,45.237.0,26.190.0,64.314.0,41.204.0,47.203.0,40.143.0"}
P.entries["quest:5922"] = {n="月光林地",s="这个任务标志着一位年轻的牛头人德鲁伊初次接触月光林地，这里是塞纳里奥德鲁伊教义的神圣庇护所。在雷霆崖的图拉克·符文图腾指导下，这位新成员学会了穿越清醒的世界，直接与自然的远古守护者进行交流。",h="这个任务标志着一位年轻的牛头人德鲁伊初次接触月光林地，这里是塞纳里奥德鲁伊教义的神圣庇护所。在雷霆崖的图拉克·符文图腾指导下，这位新成员学会了穿越清醒的世界，直接与自然的远古守护者进行交流。",kw={"熊形态","塞纳留斯","德迪利特·星焰","月光林地","永夜港","雷姆洛斯","传送月光林地","图拉克·符文图腾"},ang={["class:Druid"]="这一通过仪式架起了传统部落信仰与塞纳里奥议会更广泛教义之间的桥梁，为开启远古变形形态打开了大门。",["faction:Horde"]="尽管卡利姆多各地局势紧张，但部落德鲁伊发现月光林地是世上少有的几个可以与暗夜精灵同伴和平相遇的地方之一。",["race:Tauren"]="对于牛头人初学者而言，抵达月光林地是一次深度的觉醒：这证明了他们与大地母亲的古老联系与塞纳留斯的教义有着深刻的共鸣。"},sec={{t="超越阵营的神圣避难所",b="月光林地超然于卡利姆多动荡的政治之外。这片远古山谷坐落在原始的林木之下，由塞纳留斯之子，守护者雷姆洛斯所看护，它是一切遵循自然之道者的中立避难所。无论是暗夜精灵还是牛头人，任何进入永夜港的德鲁伊，在塞纳里奥议会永恒的庇护下，都是平等的同侪。"},{t="跨越卡利姆多的飞跃",b="为了辅助你的精神与战斗成长，图拉克·符文图腾会教给你一种与这片山谷相连的独特传送法术。通过祈唤德鲁伊与自然世界之间的神秘纽带，你可以在瞬间跨越数百里。这片圣地将作为你旅途中的学习之所和永恒的避难所。"},{t="觉醒巨熊",b="到达永夜港后，你会见到德迪利特·星焰，一位等待新学员的暗夜精灵德鲁伊长者。在他的指引下，你职业生涯的第一次真正考验开始了：寻求巨熊的视角。想要掌握利爪之道，就必须在巨熊之灵面前证明自己的力量、勇气与平衡。"}},faq={{q="为什么牛头人可以造访像月光林地这样的暗夜精灵避难所？",a="月光林地是在塞纳里奥议会管理下的主权神圣土地，由守护者雷姆洛斯指引。在它的边界之内，对自然和塞纳留斯的奉献完全超越了部落与联盟之间的阵营冲突，使得牛头人和暗夜精灵德鲁伊能够在此和平共处与修行。",al={"为什么牛头人会在月光林地","部落能否进入月光林地","月光林地是中立的吗"}},{q="谁是德迪利特·星焰？",a="德迪利特·星焰是一位驻扎在永夜港定居点的暗夜精灵德鲁伊长者。他负责指导新抵达的两个种族的初学者，在他们与远古动物之灵建立调和的过程中，主持他们的早期试炼。",al={"德迪利特·星焰","德迪利特是谁","暗夜精灵任务发布者"}},{q="谁是守护者雷姆洛斯？",a="守护者雷姆洛斯是一位强大的林地守护者，也是半神塞纳留斯之子。他担任月光林地的最高守护者，看守着沉睡的德鲁伊们进行休眠的神圣兽穴，并确保这片山谷的圣洁不容亵渎。",al={"守护者雷姆洛斯","雷姆洛斯月光林地","谁保护月光林地"}},{q="到达月光林地后该做什么？",a="与德迪利特·星焰交谈即可开启你的巨熊之灵试炼。他会指引你前往月光林地西北方的灵魂家园，去学习身体的力量与心灵的力量，这是解锁巨熊形态奥秘的第一步。",al={"接下来我该做什么","巨熊任务线","月光林地任务之后"}},{q="传送：月光林地在背景设定中是如何运作的？",a="德鲁伊编织自然的脉线能量以及他们与塞纳里奥议会的精神联结，从而瞬间跨越他们所在位置与月光林地中心之间的距离。这是一种精神锚点，让他们在被召唤时能够随时返回接受指导或寻求慰藉。",al={"传送月光林地背景","德鲁伊传送法术"}},{q="图拉克·符文图腾在哪里？",a="图拉克·符文图腾位于雷霆崖的长者高地上，他负责指导那些响应自然召唤的年轻牛头人，并在之后将他们引向月光林地。",al={"图拉克·符文图腾位置","图拉克在哪里"}}},fp="9,189,29.260.0,24.289.0,18.299.1,54.238.0,26.186.0,22.210.0,38.220.0,44.257.0,33.156.0"}
P.entries["quest:5923"] = {n="响应召唤",s="“响应号召”标志着一位暗夜精灵德鲁伊学徒终于进入了塞纳里奥议会高层领导的视野。这位年轻的入门者被召集到达纳苏斯去觐见玛斯雷·驭熊者，由此开启了掌握其第一个动物形态——熊——的神圣之路。",h="“响应号召”标志着一位暗夜精灵德鲁伊学徒终于进入了塞纳里奥议会高层领导的视野。这位年轻的入门者被召集到达纳苏斯去觐见玛斯雷·驭熊者，由此开启了掌握其第一个动物形态——熊——的神圣之路。",kw={"熊形态","塞纳里奥区","达纳苏斯","德纳萨里安","德鲁伊任务","范达尔·鹿盔","响应号召","卡尔","玛斯雷·驭熊者","瑟利德兰"},ang={["class:Druid"]="此任务代表你正式从一个只会编织根须与愤怒法术的单纯新手，蜕变为一个正在学习卡利姆多灵魂的真正变形者。",["faction:Alliance"]="能从暴风城的瑟利德兰处接到此任务，体现了泰达希尔的卡多雷与他们东部人类盟友之间日益增长的协调性。",["race:NightElf"]="响应召唤将引导你进入达纳苏斯塞纳里奥区的中心，在范达尔·鹿盔的圈子注视下，向延续千年的卡多雷传统致敬。"},sec={{t="来自塞纳里奥区的召唤",b="在泰达希尔磨练技艺，或者在暴风城等遥远国度求学的德鲁伊新手，最终都会收到个人的召唤。多兰纳尔的卡尔、达纳苏斯的德纳萨里安，或是无尽之海彼岸的瑟利德兰等导师会传达消息，称玛斯雷·驭熊者希望亲自指导他们的训练。作为大德鲁伊范达尔·鹿盔的直接助手，玛斯雷是暗夜精灵中最受尊敬且学识渊博的导师之一，他的关注无疑表明这位学徒已经准备好迎接真正的考验了。"},{t="熊之道",b="在塞纳里奥区找到位于范达尔·鹿盔高耸居所上层的玛斯雷，将为你打开通往更深奥秘的大门。为了更好地侍奉自然，德鲁伊必须学会体现其生命形态，而不仅仅是观察它们。玛斯雷欢迎候选人并告知他们，他们的第一个重大任务将是拥抱熊的力量、耐力和精神——这将是一段带他们远赴泰达希尔之外的神圣祖地之旅。"}},faq={{q="谁会派发这个任务给我？",a="当你达到足够的等级后，可以从多位德鲁伊训练师处接到此召唤：多兰纳尔的卡尔、达纳苏斯的德纳萨里安，或是暴风城的公园区的瑟利德兰。",al={"任务发放者","谁开启任务","在哪里接到任务"}},{q="玛斯雷·驭熊者是谁？",a="玛斯雷·驭熊者是一位资深的暗夜精灵德鲁伊，也是大德鲁伊范达尔·鹿盔的直接助手。他居住在达纳苏斯的塞纳里奥区，是寻求掌握动物形态的入门者的首席导师。",al={"玛斯雷","玛斯雷是谁","驭熊者"}},{q="我在达纳苏斯哪里可以找到玛斯雷·驭熊者？",a="他在达纳苏斯西北部的塞纳里奥区。你会发现他在那棵作为大德鲁伊范达尔·鹿盔圣殿的大型生命之树的二楼等你。",al={"玛斯雷位置","玛斯雷在哪里","塞纳里奥区位置"}},{q="这个任务会指引我进行什么样的训练？",a="向玛斯雷报到即开启了熊形态的神圣试炼。他会指引你跨越卡利姆多前往神圣的避难所月光林地，学习与伟大的熊灵交流所需的体魄与心智。",al={"接下来是什么","我能得到什么","后续任务"}},{q="为什么我能在暴风城接到这个任务？",a="暗夜精灵使者和德鲁伊（例如瑟利德兰）在暴风城的公园区维护着一座圣殿，以协助联盟盟友。如果一位年轻的德鲁伊正在艾尔文森林的大海上冒险，瑟利德兰可以将此召唤传达给他们，指引他们回到泰达希尔。",al={"暴风城任务","瑟利德兰","能在暴风城接吗"}},{q="为什么熊形态是第一个教授的动物形态？",a="德鲁伊认为自然既需要守护者也需要照料者。熊代表着原始的韧性、肉体的力量，以及保护平衡不受伤害的勇气，这使它成为在危险的荒野试炼中生存的基础形态。",al={"为什么是熊形态","德鲁伊熊形态背景"}}},fx={["7976a971"]={q="为什么要派我去找玛斯雷·驭熊者？",a="你的德鲁伊导师认为，你的基础学徒训练已经完成，已经可以接受进阶教导。玛斯雷·驭熊者直接听命于大德鲁伊范达尔·鹿盔，并负责监督与巨熊精魂沟通的重要仪式。训练师指引你去找他，让你开始学习变形，获得保护自然平衡所需的身心力量。",al={"为什么找玛斯雷","为什么响应召唤","响应召唤的原因","为什么德纳萨里安派我去"}},fad6f2dc={q="为什么玛斯雷·驭熊者想要我，而不是其他人？",a="这不是国家事务或军事防务，而是与你作为德鲁伊见习者的道路息息相关的个人成年礼。玛斯雷·驭熊者正在寻找有潜力引导野性精魂的年轻德鲁伊。只有你能与守护精魂沟通，并经受掌握第一个动物形态所需的精神考验。",al={"为什么响应召唤的人是我","为什么选我","为什么玛斯雷需要我"}}},fp="16,167,26.409.0,20.385.0,27.114.0,29.204.0,52.194.0,38.190.0,38.183.0,52.199.0"}
P.entries["quest:5924"] = {n="Heeding the Call",s="玛斯雷·驭熊者在达纳苏斯等候你，召唤你学习熊之道。这是你侍奉自然、维护平衡的第一步。",h="玛斯雷·驭熊者在达纳苏斯等候你，召唤你学习熊之道。这是你侍奉自然、维护平衡的第一步。",kw={"平衡","塞纳里奥区","塞纳留斯","达纳苏斯","响应召唤","玛斯雷·驭熊者","自然","熊之道"},ang={["class:Druid"]="作为一名德鲁伊，玛斯雷召唤你学习熊之道，并通过维护平衡来侍奉自然。"},sec={{t="达纳苏斯的召唤",b="在达纳苏斯的塞纳里奥区，玛斯雷·驭熊者欢迎你，并召唤你迈出探索广阔世界的第一步。他教导你，塞纳留斯的子嗣肩负着侍奉自然的使命，动物与植物既是朋友，也是需要守护的对象。你将从学习熊之道，以及锤炼身心力量开始。"}},faq={{q="是谁叫我来这里？",a="玛斯雷·驭熊者在达纳苏斯的塞纳里奥区等候你。",al={"谁想找我","玛斯雷是谁","玛斯雷"}},{q="我在哪里能找到玛斯雷·驭熊者？",a="玛斯雷·驭熊者在达纳苏斯的塞纳里奥区。",al={"玛斯雷在哪里","玛斯雷的位置","塞纳里奥区"}},{q="玛斯雷想让我学习什么？",a="他召唤你学习熊之道，并锤炼身心力量。",al={"我要学什么","熊之道","响应召唤"}},{q="塞纳留斯的子嗣肩负着什么使命？",a="塞纳留斯的子嗣肩负着侍奉自然、维护平衡的使命，为了植物、动物，也为了他们自己。",al={"塞纳留斯的召唤","侍奉自然","为何要守护自然"}}},fp="16,166,19.319.0,30.70.0,38.62.0,38.74.0,39.124.0"}
P.entries["quest:5925"] = {n="响应召唤",s="“听从召唤”是一项关键的传唤，指引见习暗夜精灵德鲁伊前往达纳苏斯。大德鲁伊范达尔·鹿盔的直属助手玛斯雷·驭熊者召集新手，以推进他们的训练并为熊的试炼做准备。",h="“听从召唤”是一项关键的传唤，指引见习暗夜精灵德鲁伊前往达纳苏斯。大德鲁伊范达尔·鹿盔的直属助手玛斯雷·驭熊者召集新手，以推进他们的训练并为熊的试炼做准备。",kw={"熊形态","塞纳里奥区","达纳苏斯","德鲁伊训练","范达尔·鹿盔","听从召唤","玛斯雷·驭熊者","泰达希尔"},ang={["class:Druid"]="这次传唤标志着你从基础新手训练过渡到与自然形态的更深层交流，而这一切将直接在大德鲁伊鹿盔的私人助手的指导下开始。",["faction:Alliance"]="在达纳苏斯响应塞纳里奥召唤的暗夜精灵德鲁伊，巩固了联盟在卡利姆多古老的魔法与自然根基。",["race:NightElf"]="这次传唤发生在达纳苏斯中心的塞纳里奥区，强调了塞纳里奥德鲁伊教义在卡多雷社会中的深层融合。"},sec={{t="达纳苏斯的传唤",b="当一位年轻的德鲁伊在泰达希尔的枝叶间完成基础训练后，消息传来，玛斯雷·驭熊者希望能亲自与他交谈。玛斯雷并非普通的导师——他是大德鲁伊范达尔·鹿盔的直属助手，也是塞纳里奥区中最受尊敬和睿智的人物之一。这次传唤标志着新手的训练已准备好迎接更宏大的目标，超越基础的守望职责，迈向更深奥的自然神圣艺术。"},{t="熊之道",b="旅程直接通往达纳苏斯的塞纳里奥区，登上大德鲁伊鹿盔巨树的二层。驭熊者欢迎这位新手，并申明每一位响应塞纳留斯召唤的追随者都必须尊重草木与野兽，视其为同伴与责任。致力于维护自然的平衡不仅仅需要静谧的冥想，更需要学习野生熊之道，掌握身心真正的力量。"}},faq={{q="玛斯雷·驭熊者是谁？",a="玛斯雷·驭熊者是一位庄严而睿智的德鲁伊，担任大德鲁伊范达尔·鹿盔的直属助手。他负责监管达纳苏斯有前途的德鲁伊们的高阶训练。",al={"谁想和我交谈","玛斯雷是谁","玛斯雷·驭熊者是谁"}},{q="玛斯雷·驭熊者在哪里？",a="他位于达纳苏斯塞纳里奥区内范达尔·鹿盔的树屋二层，那里是塞纳里奥议会的高阶成员在泰达希尔集会的地方。",al={"我在哪里可以找到驭熊者","玛斯雷在哪里","塞纳里奥区位置"}},{q="为什么我会被传唤去与玛斯雷交谈？",a="你被传唤是因为你的基础训练已经完成，作为一名德鲁伊，你的道路即将拓展。玛斯雷将亲自负责引导你深入探索自然的深奥领域。",al={"我为什么被传唤","这个任务是为了什么","为什么要听从召唤"}},{q="我能从玛斯雷·驭熊者那里学到什么？",a="玛斯雷将开始传授你熊之道，教导你获得身心的力量，以成为自然平衡的守护者。",al={"玛斯雷会教我什么","接下来我学什么","我会获得什么形态"}},{q="成为“塞纳留斯之子”意味着什么？",a="塞纳留斯是自然的守护半神，也是第一批德鲁伊的导师。他的追随者认为所有德鲁伊都有共同的职责，那就是保护艾泽拉斯的野生草木与野兽。",al={"塞纳留斯是谁","塞纳留斯之子的含义"}},{q="范达尔·鹿盔的树是指什么？",a="那是指达纳苏斯塞纳里奥区内的一棵巨大的空心生命之树，大德鲁伊范达尔·鹿盔和他的核心圈子在那里指挥泰达希尔各处的塞纳里奥事务。",al={"他在哪棵树里","鹿盔之树的位置"}}},fp="16,195,22.324.0,20.393.0,29.161.0,39.176.0,44.136.0,45.123.0,51.164.0,32.189.0"}
P.entries["quest:5926"] = {n="响应召唤",s="“听从召唤”标志着一位德鲁伊新手被传唤至雷霆崖的长者高地，接受高级的个人指导。通过部落定居点各地的旅店老板和族人转达，这项召唤指引着有抱负的变形者去找图拉克·符文图腾。这次会面开启了掌握熊的形态与精神所必需的神圣试炼。",h="“听从召唤”标志着一位德鲁伊新手被传唤至雷霆崖的长者高地，接受高级的个人指导。通过部落定居点各地的旅店老板和族人转达，这项召唤指引着有抱负的变形者去找图拉克·符文图腾。这次会面开启了掌握熊的形态与精神所必需的神圣试炼。",kw={"熊形态","血蹄村","塞纳里奥议会","德鲁伊","长者高地","根妮亚·符文图腾","听从召唤","雷霆崖","图拉克·符文图腾"},ang={["class:Druid"]="这个任务是你掌握动物形态道路上至关重要的第一步，开启了获取熊之精神与坚韧的神圣旅程。",["faction:Horde"]="兽人和牛头人领地各处的旅店老板帮助确保新晋德鲁伊收到他们的召唤，促进了部落与大地之野性之间至关重要的联系。",["race:Tauren"]="对于牛头人来说，在长者高地跟随图拉克学习，重申了他们与塞纳里奥议会及卡利姆多野性之灵之间深厚的祖先联系。"},sec={{t="旅店中的传言",b="消息在莫高雷的平原和奥格瑞玛尘土飞扬的街道上迅速传播开来。无论你是从兽人那里的旅店老板格雷什卡口中，还是从雷霆崖的旅店老板帕拉，或是血蹄村的根妮亚·符文图腾口中得知，消息都是一样的：图拉克·符文图腾已经注意到了你早期的进步。塞纳里奥议会绝不会轻易传唤修行者，这份邀请标志着你简单的草药采集和基础施法日子已经结束，你已经赢得了与自然狂野之灵更深层次交流的机会。"},{t="长者高地上的议会",b="图拉克·符文图腾是大德鲁伊哈缪尔·符文图腾的助手，在长者高地的塞纳里奥大帐篷内指引着年轻的牛头人履行他们的祖先职责。图拉克欢迎初学者进入对塞纳留斯遗产更广泛的认知领域，并教导他们动植物既是盟友也是庄严的责任。与他会面是仪式的开端：超越基础的指导，去面对与巨熊之灵直接沟通所必需的身心试炼。"}},faq={{q="谁指派我去和图拉克·符文图腾交谈？",a="这项传唤可以通过几位不同的联络人传达：血蹄村的根妮亚·符文图腾、雷霆崖的旅店老板帕拉，或是奥格瑞玛的旅店老板格雷什卡。每个人都收到了消息，称图拉克希望亲自指导你的训练。",al={"谁发布听从召唤","听从召唤任务发布者","如何开始听从召唤"}},{q="我在哪里可以找到图拉克·符文图腾？",a="图拉克居住在雷霆崖的长者高地。他就在城中其他德鲁伊导师附近的塞纳里奥议会大帐篷里。",al={"图拉克·符文图腾位置","图拉克在哪里","如何找到图拉克"}},{q="为什么这项传唤对年轻的德鲁伊如此重要？",a="这项传唤标志着你正式变形试炼的开始。图拉克·符文图腾会指引你前往月光林地的神圣之地，这样你就可以学习熊之道，并获得你的第一个动物形态。",al={"为什么需要找图拉克","这个任务是为了什么","部落德鲁伊10级任务"}},{q="图拉克·符文图腾在塞纳里奥议会的阶层中是什么地位？",a="图拉克是一位受人尊敬的牛头人德鲁伊，也是大德鲁伊哈缪尔·符文图腾值得信赖的助手。他因在教导年轻初学者自然平衡时的耐心和智慧而闻名。",al={"图拉克·符文图腾是谁","图拉克背景故事"}},{q="其他职业可以接受这个任务吗？",a="不能。这个任务仅供达到十级经验的德鲁伊接取，作为他们进入变形之路的成人礼。",al={"听从召唤是德鲁伊专属任务吗","萨满可以做这个任务吗"}},{q="我与图拉克交谈后会发生什么？",a="图拉克会欢迎你加入塞纳留斯的侍从行列，并派遣你前往神圣的德鲁伊避难所月光林地，去寻找德迪利特·星焰，开始与巨熊之灵的沟通。",al={"听从召唤之后是什么","图拉克之后的下一个任务"}}},fp="16,222,17.393.0,24.373.0,43.197.0,33.121.0,50.160.0,49.174.0,36.125.0,36.153.1"}
P.entries["quest:5928"] = {n="Heeding the Call",s="图拉克·符文图腾召你前来，开始学习熊之道。他教导你，德鲁伊侍奉自然，维护平衡。",h="图拉克·符文图腾召你前来，开始学习熊之道。他教导你，德鲁伊侍奉自然，维护平衡。",kw={"熊","塞纳留斯","德鲁伊","长者高地","heeding the call","自然","雷霆崖","图拉克·符文图腾"},ang={["class:Druid"]="图拉克对德鲁伊的教导，始于侍奉自然和学习熊之道。"},sec={{t="求学的召唤",b="雷霆崖长者高地的图拉克·符文图腾请你前去与他交谈。他说，你迈向更广阔世界的第一步，时机已经到来。\n\n他教导你，塞纳留斯的子嗣侍奉自然，将动物和植物视为朋友，也视为需要照料的生命。你的第一课是学习熊之道，以及身体与内心的力量。"}},faq={{q="是谁叫我来这里的？",a="图拉克·符文图腾请你到雷霆崖的长者高地与他交谈。",al={"谁派我来的","图拉克是谁","谁是图拉克"}},{q="图拉克想让我学习什么？",a="图拉克说，你的第一步是学习熊之道，以及身体与内心的力量。",al={"我要学什么","熊之道课程","学习熊之道"}},{q="图拉克说德鲁伊要做什么？",a="图拉克说，塞纳留斯的子嗣侍奉自然，为了动物、植物和自身维护平衡。",al={"德鲁伊的召唤","侍奉自然","为何侍奉自然"}},{q="我该去哪里与图拉克交谈？",a="图拉克·符文图腾在雷霆崖的长者高地。",al={"图拉克在哪里","长者高地","图拉克的位置"}}},fp="16,123,15.329.0,30.74.0,33.91.0,30.112.0,28.50.0"}
P.entries["quest:5929"] = {n="巨熊之灵",s="巨熊之灵是月光林地德鲁伊的一项基础导师任务，指引初学者前往西北方的荒野中寻找一位古老而高贵的灵魂。与该灵魂交流能够传授关于熊的本性和力量的关键智慧，这标志着德鲁伊精神与武艺训练中的关键一步。",h="巨熊之灵是月光林地德鲁伊的一项基础导师任务，指引初学者前往西北方的荒野中寻找一位古老而高贵的灵魂。与该灵魂交流能够传授关于熊的本性和力量的关键智慧，这标志着德鲁伊精神与武艺训练中的关键一步。",kw={"熊形态","德迪利特·星焰","德鲁伊任务","巨熊之灵","月光林地","永夜港"},ang={["class:Druid"]="与巨熊之灵的交流是每一位德鲁伊必经的成人仪式，它传授了获得熊之韧性所需的自然智慧和精神基础。"},sec={{t="月光林地的高贵导师",b="巨熊之灵栖息在月光林地的西北荒野中，远离了永夜港那宁静的小径。作为一位备受尊敬的高贵古老导师，该灵魂是所有试图理解熊之自然本质的初学者的基础导师。寻求它的祝福与智慧是每一位行走于自然之道的德鲁伊所共同遵守的神圣传统。"},{t="原始专注的仪式",b="在永夜港德迪利特·星焰的指引下，年轻的德鲁伊们踏上旅程，前往山丘之中向这位灵魂觐见。与巨熊之灵的交流传授了原始的智慧和对自然力量的感知。在归来后，德迪利特会考验他们的专注力，并指出尽管这次相遇灌注了原始的力量和明确的意图，但德鲁伊仍需学习如何将那股内在的力量引导至日常工作中。"}},faq={{q="在哪里可以找到巨熊之灵？",a="巨熊之灵居住在月光林地的西北方，远离了永夜港的定居点，栖息在这一神圣避难所更为荒野的边缘地带。",al={"巨熊之灵的位置","寻找月光林地巨熊之灵","巨熊之灵坐标"}},{q="是谁指引德鲁伊去寻找巨熊之灵的？",a="驻扎在永夜港的德鲁伊长者德迪利特·星焰会指引初学者与该灵魂进行交流，以此作为他们自然训练的一部分。",al={"谁指引去见巨熊之灵","德迪利特·星焰的作用","巨熊之灵任务给予者"}},{q="什么是巨熊之灵？",a="巨熊之灵被尊为一位睿智而高贵的实体，它为所有修行中的德鲁伊提供关于熊之原始理解的指引、教导和辅导。",al={"什么是巨熊之灵","巨熊之灵背景故事","巨熊之灵是谁"}},{q="为什么德鲁伊必须与巨熊之灵交流？",a="初学者寻找该灵魂是为了了解熊的核心本性，吸收其原始的力量、韧性和智慧，然后再回去将这些特质运用到自己的修行之中。",al={"为什么要与巨熊之灵交谈","巨熊之灵任务目的","从巨熊之灵那里学到什么"}},{q="当巨熊之灵感到满意后会发生什么？",a="在与灵魂交流后，初学者会回到永夜港找德迪利特·星焰，他会认可他们新获得的领悟，并让他们准备好驾驭和专注于那股力量。",al={"巨熊之灵之后发生什么","灵魂试炼后的德迪利特","拜访巨熊之灵后"}},{q="所有德鲁伊都需要寻求该灵魂的智慧吗？",a="每一位德鲁伊最终都必须寻求巨熊之灵的教诲，因为与该灵魂的交流被视为掌握动物形态和自然力量的一个基础步骤。",al={"所有德鲁伊都要拜访巨熊之灵吗","巨熊之灵是必须的吗","谁会去拜访巨熊之灵"}}},fp="17,202,29.273.0,22.330.0,41.113.0,51.129.0,30.127.0,51.164.0,54.169.0,47.139.0"}
P.entries["quest:593"] = {n="灵魂宝石",s="在荆棘谷茂密的丛林深处，有人试图挽救年轻的巨魔耶尼库。当这名年轻人陷入恍惚状态时，有人拿出一颗准备好的灵魂宝石，试图捕捉他的灵魂。",h="在荆棘谷茂密的丛林深处，有人试图挽救年轻的巨魔耶尼库。当这名年轻人陷入恍惚状态时，有人拿出一颗准备好的灵魂宝石，试图捕捉他的灵魂。",kw={"拯救耶尼库","灵魂宝石","荆棘谷","巨魔","耶尼库"},sec={{t="丛林中的恍惚",b="在尝试拯救耶尼库之后，你与荆棘谷中的这名年轻巨魔面对面。他的心智已经迷失，完全被困在了另一个地方，而他的身体却依然在你面前一动不动。唯一的解决办法是使用那颗专门为容纳他的灵魂而准备的附魔宝石。"},{t="容器",b="将宝石按在耶尼库的额头上，会将他的灵魂直接吸入石中。随着灵魂被抽离，他的肉体战栗着瘫倒在地，变成了一具空洞、毫无心智的躯壳。"}},faq={{q="当你找到耶尼库时，他的状态如何？",a="耶尼库处于昏迷且无反应的状态，他的意识远离了他的躯体。",al={"耶尼库状态","耶尼库怎么了","耶尼库昏迷"}},{q="什么物品被用在了耶尼库身上？",a="一颗从荆棘谷带来的灵魂宝石被用来与这名年轻巨魔互动。",al={"需要什么物品","用在耶尼库身上的宝石","耶尼库物品"}},{q="在此之前发生了什么？",a="这次遭遇紧接在荆棘谷丛林中“拯救耶尼库”的任务之后。",al={"前置任务","填充灵魂宝石的前提条件","导致此结果的原因"}}},fp="20,136,22.195.0,10.138.1,48.104.0,29.62.0,29.86.0"}
P.entries["quest:5930"] = {n="巨熊之灵",s="在月光林地，德迪利特·星焰派你去拜访巨熊之灵，了解熊的本性。他相信你的力量与意志已准备好接受引导。",h="在月光林地，德迪利特·星焰派你去拜访巨熊之灵，了解熊的本性。他相信你的力量与意志已准备好接受引导。",kw={"熊","德迪利特·星焰","巨熊之灵","月光林地","熊的本性","永夜港"},sec={{t="熊之本性的教诲",b="德迪利特·星焰在永夜港，月光林地等候，准备给你上一课。他请你前往西北方寻找巨熊之灵，了解它能告诉你什么关于熊的本性。完成后，回去找德迪利特；他看到了你的力量与意志，并说你可以通过熊的本性学会引导二者。"}},faq={{q="谁派我去找巨熊之灵？",a="永夜港的德迪利特·星焰请你去寻找巨熊之灵。",al={"谁派我去","德迪利特的请求"}},{q="巨熊之灵在哪里？",a="巨熊之灵位于月光林地西北部。",al={"熊灵的位置","熊灵在哪里"}},{q="我应该学习什么？",a="德迪利特请你了解巨熊之灵能告诉你什么关于熊的本性。",al={"熊之本性的教诲","熊灵教什么"}},{q="之后我该回哪里？",a="与巨熊之灵交谈后，回到永夜港，月光林地的德迪利特·星焰身边。",al={"之后回哪里","回到德迪利特身边"}}},fp="17,165,23.333.0,38.72.0,31.51.0,25.96.0,28.97.0"}
P.entries["quest:5931"] = {n="返回达纳苏斯",s="此任务标志着一位暗夜精灵德鲁伊新手从月光林地的圣所归来，抵达达纳苏斯。在与巨熊之灵沟通后，这位新兵需要向塞纳里奥区的玛斯雷·驭熊者汇报，以开始实际的变形试炼。",h="此任务标志着一位暗夜精灵德鲁伊新手从月光林地的圣所归来，抵达达纳苏斯。在与巨熊之灵沟通后，这位新兵需要向塞纳里奥区的玛斯雷·驭熊者汇报，以开始实际的变形试炼。",kw={"巨熊之灵","驭熊者","塞纳里奥区","达纳苏斯","德迪利特","玛斯雷","月光林地","变形","星焰"},ang={["class:Druid"]="这趟旅程代表了年轻德鲁伊的关键成人礼，标志着从理论上的精神沟通到物理变形的转变。",["race:NightElf"]="在古老的月光林地圣所和新种植的世界之树泰达希尔之间穿梭，反映了卡多雷千年传承与其目前职责之间的平衡。"},sec={{t="圣所之间的旅程",b="在与月光林地的巨熊之灵沟通后，年轻的德鲁伊必须在永恒的自然圣所与动荡的世界之间架起桥梁。德迪利特·星焰会派新兵从永夜港返回达纳苏斯，将下一阶段的训练托付给守护泰达希尔的当地导师。"},{t="利爪之路",b="玛斯雷·驭熊者在塞纳里奥区等待着，即使在平衡受到威胁的地方，他依然守护着自然。接受巨熊之灵的祝福仅仅是第一步；玛斯雷会通过对身体和心灵的严苛考验，让新兵学会将那种狂野的先祖智慧转化为物理形态。"}},faq={{q="为什么我需要回到达纳苏斯？",a="月光林地提供的是与巨熊之灵的精神交流，但你的直接导师玛斯雷·驭熊者居住在达纳苏斯的塞纳里奥区。他将指导你掌握新获得的力量所需的实际测试。",al={"为何返回达纳苏斯","为何离开月光林地","德迪利特派我去哪"}},{q="玛斯雷·驭熊者是谁？",a="玛斯雷·驭熊者是一位经验丰富的暗夜精灵德鲁伊训练师，驻扎在达纳苏斯的塞纳里奥区。他专门指导年轻的新兵通过利爪之路并掌握熊形态。",al={"玛斯雷是谁","玛斯雷·驭熊者背景故事","驭熊者"}},{q="我该如何从月光林地回到达纳苏斯？",a="位于永夜港西南部的角鹰兽管理员席尔瓦·菲尔纳维斯可以为新兵提供直飞回海对岸鲁瑟兰村的航班，你可以从那里通过传送门前往达纳苏斯。",al={"如何离开永夜港","月光林地返程飞行","席尔瓦·菲尔纳维斯"}},{q="我和玛斯雷交谈后会发生什么？",a="玛斯雷将指派你进行第一次真正的目的测试，让你前往黑海岸奥伯丁东部的枭兽石面对月爪，以证明你的身体和心灵已做好驾驭熊形态的准备。",al={"返回达纳苏斯后的下一个任务","接下来是什么"}},{q="什么是利爪之路？",a="利爪之路是德鲁伊的传统，专注于引导熊的狂暴、坚韧和力量，并通过与古老的原始灵魂沟通来实现这一点。",al={"利爪之路","德鲁伊利爪背景知识"}},{q="为什么德迪利特提到平衡在达纳苏斯附近动摇？",a="泰达希尔还很年轻，没有受到龙类的祝福，这使其枝叶极易受到各种奇怪的腐蚀、熊怪的疯狂和不断逼近的黑暗侵害，而塞纳里奥区的德鲁伊们正在积极对抗这些威胁。",al={"达纳苏斯平衡动摇","泰达希尔腐化"}}},fp="17,180,29.323.0,20.282.0,37.202.0,29.182.0,46.163.0,41.195.0,29.150.0,59.208.0"}
P.entries["quest:5932"] = {n="返回雷霆崖",s="“回到雷霆崖”是牛头人德鲁伊学徒从神圣的月光林地归来后必经的重要仪式。在与伟大的熊之灵交流后，学徒会被德迪利特·星焰送回长者高地，继续在图拉克·符文图腾的教导下进行训练。",h="“回到雷霆崖”是牛头人德鲁伊学徒从神圣的月光林地归来后必经的重要仪式。在与伟大的熊之灵交流后，学徒会被德迪利特·星焰送回长者高地，继续在图拉克·符文图腾的教导下进行训练。",kw={"回到雷霆崖","熊形态","德迪利特·星焰","长者高地","伟大的熊之灵","月光林地","永夜港","图拉克·符文图腾"},ang={["class:Druid"]="你旅程的这一段将古老隐秘的避难所月光林地与风吹日晒的雷霆崖高地连接了起来，标志着你在利爪之路上又迈进了一步。",["faction:Horde"]="从月光林地带回的知识确保了部落在卡利姆多的平原上拥有强大的变形防御者。",["race:Tauren"]="回到长者高地，将古老之灵的智慧带回家园，从而造福并保护你遍布莫高雷的部落。"},sec={{t="跨越种族的友谊",b="月光林地超然于凡世的阵营纷争之外，作为一处避难所，暗夜精灵与牛头人的自然魔法修行者在此汇聚，组成了塞纳里奥议会。在与伟大的熊之灵交流后，暗夜精灵导师德迪利特·星焰会将年轻的牛头人送回他们的族人身边。尽管暗夜精灵通常视牛头人为塞纳留斯教义的学习新手，但星焰导师十分认可图拉克·符文图腾所展现的深邃智慧与平衡之道。"},{t="返回雷霆崖",b="当回到雷霆崖长者高地那广阔的高地时，这位学徒已经脱胎换骨，站在了图拉克·符文图腾的面前。与伟大的熊之灵等古老的图腾之灵交流在牛头人文化中根深蒂固，而踏上利爪之路则标志着一种严肃的承诺。随着精神连接的建立，图拉克正在准备让这位德鲁伊将新获得的力量与耐力付诸实践。"}},faq={{q="为什么暗夜精灵会在月光林地教导牛头人？",a="塞纳里奥议会保持中立，完全致力于保护自然。在月光林地内，部落与联盟之间的政治敌对被严格搁置，这使得像德迪利特·星焰这样的暗夜精灵长者能够指引年轻的牛头人德鲁伊。",al={"德迪利特·星焰 部落","为什么暗夜精灵是导师","塞纳里奥议会 牛头人"}},{q="谁是图拉克·符文图腾？",a="图拉克·符文图腾是一位受人尊敬的牛头人德鲁伊，他是大德鲁伊的助手之一，驻扎在雷霆崖的长者高地。他负责监督那些寻求走上自然与利爪之路的年轻牛头人的训练，是塞纳里奥议会的关键联络人。",al={"图拉克·符文图腾职责","长者高地 德鲁伊领袖"}},{q="在此任务之前，这位年轻的德鲁伊做了什么？",a="在被送回莫高雷之前，学徒前往月光林地寻找并与古老的伟大的熊之灵进行了交流，获得了它的祝福，并掌握了熊形态的精神核心。",al={"回到雷霆崖之前","伟大的熊之灵任务"}},{q="年轻的德鲁伊如何从月光林地返回雷霆崖？",a="位于永夜港西南方的布瑟恩·草风提供了专门的飞行管理员服务，在仪式结束后安全地将牛头人德鲁伊送回雷霆崖。",al={"如何从月光林地返回","月光林地 返回飞行"}},{q="这位德鲁伊接下来的训练是什么？",a="返回后，图拉克·符文图腾会交给学徒任务“身与心”，派遣他们前往贫瘠之地与莫高雷交界处的枭兽石，迎接体能挑战，以证明他们能够将灵体的力量转化为真正的野兽形态。",al={"下一个德鲁伊任务","回到雷霆崖之后"}},{q="为什么德迪利特·星焰称牛头人在塞纳留斯之道的修行上尚显稚嫩？",a="虽然牛头人的传说追溯到世界黎明时与塞纳留斯的古老交流，但正式的塞纳里奥德鲁伊教义是由暗夜精灵在过去一万年间发展并维持的。牛头人只是最近才在塞纳里奥议会的指导下重新建立了系统性的学习。",al={"牛头人是新德鲁伊吗","牛头人德鲁伊历史 塞纳留斯"}}},fp="21,197,20.396.0,20.356.0,51.212.0,23.239.0,52.182.0,64.142.0,40.201.0,72.250.0"}
P.entries["quest:594"] = {n="瓶中信",s="一个被冲上荆棘谷海岸的瓶子中装有一份紧急求援信。写信者声称自己被困在南海一座孤岛上，被一只巨大的野兽囚禁着。",h="一个被冲上荆棘谷海岸的瓶子中装有一份紧急求援信。写信者声称自己被困在南海一座孤岛上，被一只巨大的野兽囚禁着。",kw={"半埋的瓶子","瓶中信","普巴尔公主","天鬃兽","南海","荆棘谷","蛮荒海岸"},sec={{t="来自波涛的呼唤",b="在一个半埋在沙子里的玻璃容器中，躺着一张字迹工整的字条，上面写着请求立即援助的内容。被囚禁者报告称，自己被困在异国岛屿上，头顶是茂密的丛林树冠，看守她的是一只巨大的天鬃兽。透过树木的缝隙只能隐约看到模糊的地标：西北方可以看到蛮荒海岸，而西南方则有大型帆船漂流经过。"},{t="字条的作者",b="根据航海指示越过水域到达一座近海岛屿，写下这封信的人就在那里等待。被困的俘虏是普巴尔公主，她迫切希望能有一位冒险者最终找到她，给予她重获自由的机会。"}},faq={{q="瓶子里的字条写了什么？",a="这条消息是一封用清晰字迹写就的紧急求援信。信中解释说作者被一只巨大的天鬃兽囚禁在南海的一座岛屿上，并恳求捡到这封信的人予以营救。",al={"字条内容","瓶中信","瓶子里写了什么"}},{q="写信者说岛屿位于何处？",a="虽然丛林树木遮挡了夜空，但被囚禁者提到，在晴朗的日子里，西北方向可以看到蛮荒海岸，西南方向则会出现大型帆船。",al={"岛屿位置","如何找到被俘者","岛屿地标"}},{q="是什么囚禁了作者？",a="字条上写着，一只被称为“巨大的天鬃兽”的生物将作者囚禁在了岛上。",al={"谁俘虏了作者","是什么囚禁了作者","天鬃兽俘虏"}},{q="这会引出后续的冒险吗？",a="找到寄信人是两步任务链的第一部分，一旦找到被俘者，便会直接触发第二部分。",al={"后续任务","是否有后续","之后会发生什么"}}},fp="19,175,21.267.0,22.194.1,37.182.0,48.163.0,35.88.0,37.96.0"}
P.entries["quest:5943"] = {n="基泽尔顿车队",s="里格·基泽尔顿和科克为了发财而组建了商队，却发现贸易比他们预想的要危险得多。玛诺洛克集会所就在前方，里格想要一位能干的冒险者来护送商队安全通过。",h="里格·基泽尔顿和科克为了发财而组建了商队，却发现贸易比他们预想的要危险得多。玛诺洛克集会所就在前方，里格想要一位能干的冒险者来护送商队安全通过。",kw={"商队","科克","集会所","凄凉之地","基泽尔顿","科多兽","玛诺洛克","里格","瑟卡布斯库","斯米德"},sec={{t="穿过玛诺洛克集会所",b="里格·基泽尔顿和科克组建商队是为了赚大钱，他们根本不知道获利的过程竟然如此冒险。玛诺洛克集会所就在前方。恶魔们通常不会理会商队，但这次科多兽却受惊了。如果你能护送商队通过集会所，里格愿意支付报酬。一旦商队安全通过，你的报酬可以在瑟卡布斯库的营地找他们的商业伙伴斯米德领取。"},{t="斯米德的忧虑",b="在瑟卡布斯库的营地，斯米德擦着汗说，如果商队失踪他会破产，所以很高兴听到它没有丢。他不确定花这么多钱去保护一个每周只能赚一个金币的商队是否有意义。不过，只要科克和里格继续为他的科多兽付钱，他就不在乎他们怎么经营生意。"}},faq={{q="谁是里格·基泽尔顿？",a="一个和科克一起创办了基泽尔顿商队的商队老板，希望能赚大钱。",al={"里格是谁","基泽尔顿背景","里格·基泽尔顿"}},{q="为什么商队需要护送通过玛诺洛克集会所？",a="里格说那里的恶魔通常会无视商队，但这次有什么东西让科多兽受惊了。",al={"为什么护送商队","玛诺洛克集会所危险","为什么要保护商队"}},{q="谁为你护送商队支付报酬？",a="斯米德，基泽尔顿在瑟卡布斯库的营地的商业伙伴，商队安全通过集会所后向他领取。",al={"谁付钱给我","基泽尔顿商队任务在哪里交","斯米德报酬"}},{q="谁是科克？",a="里格·基泽尔顿的商队合伙人。",al={"考克·基泽尔顿","科克是谁"}}},fp="16,160,19.366.0,18.332.1,23.86.0,57.120.0,40.117.0,12.49.0"}
P.entries["quest:595"] = {n="血帆海盗",s="黑水强盗的大副克拉兹需要一位冒险者去调查有关敌对海盗的传闻。由于他的船员们都在藏宝海湾忙着喝酒寻欢，他请求你去野人海岸附近的一个小海湾，打探血帆海盗的踪迹。",h="黑水强盗的大副克拉兹需要一位冒险者去调查有关敌对海盗的传闻。由于他的船员们都在藏宝海湾忙着喝酒寻欢，他请求你去野人海岸附近的一个小海湾，打探血帆海盗的踪迹。",kw={"黑水强盗","血帆海盗","藏宝海湾","通信","大副克拉兹","野人海岸","荆棘谷"},sec={{t="野人海岸的斥候",b="黑水强盗刚在藏宝海湾停靠，就听说他们的死对头——血帆海盗——在荆棘谷南部出没的消息。由于其他船员正沉迷于朗姆酒和岸上的享乐，大副克拉兹只能向外人求助。他让你沿着野人海岸向北走，去探查一个小海湾，看看血帆海盗究竟在搞什么鬼。"},{t="海湾的迹象",b="在搜索海湾时，你发现了一个木桶，上面放着一些钱币和一张画满潦草笔记的地图。"}},faq={{q="大副克拉兹是谁？",a="大副克拉兹是驻扎在藏宝海湾的黑水强盗的一名军官。面对敌对海盗的传闻和缺乏干劲的船员，他只能雇佣路过的冒险者去海岸侦察。",al={"大副克拉兹","谁给予任务","克拉兹是谁"}},{q="为什么大副克拉兹需要外人帮忙？",a="黑水强盗的船员才刚刚靠岸，他们正忙着在岸上寻欢作乐，根本无暇分身去进行任何侦察任务。",al={"为什么要雇佣冒险者","为什么他的船员不能去","为什么要帮助克拉兹"}},{q="克拉兹让你去哪里调查？",a="他指引你去侦察藏宝海湾以北，也就是被称为野人海岸的那片区域内的一个小海湾。",al={"我该去哪里","海湾在哪里","血帆海盗在哪里"}},{q="黑水强盗面临着怎样的敌对势力？",a="黑水强盗与血帆海盗之间有着深仇大恨，最近有人发现血帆海盗正在向荆棘谷南部大举扩张。",al={"谁是竞争对手","为什么要憎恨血帆海盗","血帆竞争"}}},fp="24,190,30.324.0,17.121.1,24.193.0,43.104.0,41.81.0,49.138.0"}
P.entries["quest:596"] = {n="染血的白骨项链",s="位于格罗姆高营地的肯维雷在荆棘谷另有打算，不仅仅是为了协助尼姆布亚。他试图通过收集鲜血头皮部族战士的战利品，来削弱这个敌对部族的力量。",h="位于格罗姆高营地的肯维雷在荆棘谷另有打算，不仅仅是为了协助尼姆布亚。他试图通过收集鲜血头皮部族战士的战利品，来削弱这个敌对部族的力量。",kw={"鲜血头皮","暗矛","格罗姆高","肯维雷","项链","尼姆布亚","荆棘谷"},ang={["faction:Horde"]="肯维雷被派往格罗姆高营地是为了协助尼姆布亚，并利用在那里待命的时间猎杀北方的鲜血头皮部族。",["race:Troll"]="对于暗矛部族来说，猎杀鲜血头皮部族是为了获得对敌对部族的控制力量。"},sec={{t="战争的战利品",b="尽管肯维雷来到格罗姆高营地这个丛林前哨是为了帮助尼姆布亚，但他仍有自己的私心。居住在北方的鲜血头皮巨魔是暗矛部族的敌人。肯维雷相信，从倒下的敌人身上获取私人战利品可以获得凌驾于他们之上的灵魂力量，因此他要求旅行者去猎杀鲜血头皮战士，并取下他们颈间佩戴的血色骨质项链。"},{t="汲取灵魂",b="在收到采集来的骨质饰品后，肯维雷打算将它们煮沸并萃取成糊状。通过这种仪式，他旨在直接枯竭并削弱鲜血头皮部族亡者的残余灵魂。"}},faq={{q="谁想要这些骨质项链？",a="肯维雷在荆棘谷的格罗姆高营地提供这项任务。尽管他被派往那里是为了协助尼姆布亚，但他利用这个营地来执行他自己的灵魂复仇计划。",al={"任务发布者","谁提供血色骨质项链任务","肯维雷任务"}},{q="为什么肯维雷想要鲜血头皮部族的战利品？",a="鲜血头皮部族是暗矛部族的死敌。肯维雷相信从死去的敌人身上获取战利品可以获得控制他们的力量，让暗矛部族确立对竞争对手的统治地位。",al={"为什么要收集项链","鲜血头皮项链的用途","为什么要猎杀鲜血头皮"}},{q="鲜血头皮部族在哪里？",a="鲜血头皮巨魔居住在格罗姆高营地以北的土地上，遍布荆棘谷北部。",al={"去哪里寻找鲜血头皮","鲜血头皮位置","巨魔在哪里"}},{q="这次狩猎之后会发生什么？",a="在这项任务之后，肯维雷会派遣冒险者去执行后续任务：分裂的骨质项链。",al={"下一个任务","血色骨质项链后续","血色骨质项链之后做什么"}}},fp="21,88,15.332.0,20.167.1,32.147.0,60.193.0,34.92.0,32.63.0"}
P.entries["quest:597"] = {n="血帆海盗",s="从血帆海盗那里缴获的信件里有一张藏宝海湾的地图，上面写着命令，要求他们在那处标记点建立一个隐秘的营地，并等待来自他们南方指挥所的信号后再发动进攻。",h="从血帆海盗那里缴获的信件里有一张藏宝海湾的地图，上面写着命令，要求他们在那处标记点建立一个隐秘的营地，并等待来自他们南方指挥所的信号后再发动进攻。",kw={"血帆海盗","血帆信件","藏宝海湾","大副克拉兹","南方指挥所","荆棘谷"},sec={{t="揭露阴谋",b="继你之前对血帆海盗的调查之后，一份截获的地图和书面命令揭示了海盗们的近期计划。藏宝海湾地图上的一个红色叉号标记了海盗们预定建立营地的确切地点。命令要求船员们悄悄驻守原地，消灭任何靠近的人，并等待从南方指挥所发出的进攻信号。"},{t="向港口汇报",b="将这些书面发现带回藏宝海湾，意味着直接向大副克拉兹报告情报，正是他当初派你去侦察的。海盗们显然是在等待进攻信号。"}},faq={{q="血帆海盗的信件上写了什么？",a="信件指示海盗船员在标记地点建立一个隐秘的营地，杀死任何靠近的人，并等待来自他们南方指挥所的信号以发动突袭。",al={"血帆计划书内容","字条上写了什么","血帆地图详情"}},{q="地图指向哪里？",a="这张缴获的藏宝海湾地图上有一个红色的叉号，那就是海盗们打算安营扎寨的地方。",al={"血帆地图叉号","红色叉号代表什么","营地在哪里"}},{q="谁需要了解这一发现？",a="这份情报必须直接报告给藏宝海湾的大副克拉兹，他还记得曾派你去侦察该区域。",al={"我该找谁交任务","谁会收到血帆地图","向大副克拉兹报告"}},{q="在找到这封信之前发生了什么？",a="这项调查直接承接大副克拉兹在藏宝海湾下达的关于血帆海盗的初始任务。",al={"前置任务","之前的血帆任务","血帆任务线起始"}}},fp="24,89,15.223.0,23.152.0,48.202.0,25.67.0,39.92.0,45.87.0"}
P.entries["quest:598"] = {n="裂骨项链",s="格罗姆高营地的肯维雷号召部落盟友去猎杀东南方的裂颅者部族。虽然暗矛巨魔已经离开了荆棘谷，但他们与这些丛林宿敌之间古老的冲突仍未解决。带回二十五条裂颅者骨项链将有助于暗矛巨魔的战争，并能赢得他们的友谊。",h="格罗姆高营地的肯维雷号召部落盟友去猎杀东南方的裂颅者部族。虽然暗矛巨魔已经离开了荆棘谷，但他们与这些丛林宿敌之间古老的冲突仍未解决。带回二十五条裂颅者骨项链将有助于暗矛巨魔的战争，并能赢得他们的友谊。",kw={"暗矛巨魔","格罗姆高营地","肯维雷","裂颅者","裂颅者骨项链","荆棘谷"},ang={["faction:Horde"]="在格罗姆高营地协助肯维雷进行针对裂颅者的战争，可以赢得暗矛巨魔的友谊。",["race:Troll"]="对于暗矛巨魔来说，从裂颅者那里获取战利品延续了一场漫长的战争，这场战争并没有随着部族离开荆棘谷而结束。"},sec={{t="一场未了的世仇",b="在收集了血顶巨魔的战利品后，肯维雷将注意力转向了另一个长期以来的敌人。裂颅者部族居住在格罗姆高营地的东南方，多年来他们一直与暗矛巨魔发生冲突。尽管暗矛巨魔不再居住在荆棘谷的丛林中，但他们依然被这场持久的战争所束缚。"},{t="战争的战利品",b="为了赢得暗矛部族的友谊和尊重，冒险者必须挺进裂颅者的领地，并夺取二十五条他们标志性的裂颅者骨项链。肯维雷以看到这些敌对巨魔像被蛇颈龙砍倒的幼苗一样被消灭而自豪，并将每一件回收的战利品视为对他的人民的一场胜利。"}},faq={{q="是谁提供了这次狩猎，他在哪里？",a="肯维雷在荆棘谷西海岸的部落前哨站格罗姆高营地提供这次狩猎任务。",al={"谁给予裂颅者骨项链任务","肯维雷位置","裂颅者骨项链任务发布者"}},{q="这项任务之前发生了什么？",a="这项任务是在“血顶骨项链”之后进行的，那是一次早期的狩猎，当时肯维雷指派冒险者从血顶部族那里收集战利品。",al={"裂颅者骨项链前置条件","裂颅者骨项链的前一个任务","上一步任务"}},{q="既然暗矛巨魔已经离开了荆棘谷，为什么他们还要与裂颅者作战？",a="暗矛巨魔和裂颅者在丛林中交战多年。尽管暗矛部族已经迁离了荆棘谷，但肯维雷解释说，他们仍然受到这场冲突的束缚，并决心让他们的敌人为当初的挑衅感到后悔。",al={"为什么暗矛巨魔憎恨裂颅者","裂颅者战争背景","暗矛巨魔与裂颅者的冲突"}},{q="在哪里可以找到裂颅者部族？",a="裂颅者居住在荆棘谷格罗姆高营地东南方的领地中。",al={"裂颅者位置","裂颅者在哪里","裂颅者营地"}},{q="肯维雷要求从这次狩猎中提供什么证明？",a="肯维雷要求从倒下的裂颅者巨魔身上直接获取二十五条裂颅者骨项链。",al={"肯维雷需要什么物品","裂颅者骨项链物品","需要多少条项链"}}},fp="19,267,16.252.0,15.291.0,46.106.0,27.115.0,79.210.0,43.84.0,48.92.0"}
P.entries["quest:599"] = {n="血帆海盗",s="大副克拉兹已经得知血帆海盗打算对藏宝海湾发动袭击。威胁的规模需要引起黑水强盗指挥官舰队指挥官卡拉·海角的注意，他需要立即听到这个警告。",h="大副克拉兹已经得知血帆海盗打算对藏宝海湾发动袭击。威胁的规模需要引起黑水强盗指挥官舰队指挥官卡拉·海角的注意，他需要立即听到这个警告。",kw={"黑水强盗","血帆海盗","藏宝海湾","大副克拉兹","舰队指挥官卡拉·海角","荆棘谷"},sec={{t="给舰队指挥官的警告",b="在发现血帆海盗计划直接袭击藏宝海湾后，大副克拉兹意识到事情比他想象的要严重。他指示你寻找舰队指挥官卡拉·海角，他就在这个港口城市里的某个地方，并在敌对海盗采取行动之前通知他这场迫在眉睫的袭击。"},{t="海角的蔑视",b="当看到有关计划袭击的报告时，舰队指挥官卡拉·海角对这些敌对海盗的野心嗤之以鼻，宣称攻击藏宝海湾就像从眺望台悬崖跳下去一样愚蠢。尽管如此，他还是承认了这份情报的价值，并代表黑水强盗向你表示感谢。"}},faq={{q="是谁派你去警告舰队指挥官卡拉·海角的？",a="大副克拉兹在得知血帆海盗针对该港口的敌对计划的严重性后，派你去警告卡拉·海角。",al={"谁开启了这个任务","大副克拉兹任务","血帆海盗任务发布者"}},{q="舰队指挥官卡拉·海角在哪里？",a="舰队指挥官卡拉·海角驻扎在荆棘谷南部的海盗避风港藏宝海湾内。",al={"卡拉·海角在哪里","卡拉·海角位置","舰队指挥官卡拉·海角城镇"}},{q="血帆海盗的计划是什么？",a="血帆海盗正在准备对藏宝海湾进行全面攻击，挑战黑水海盗对该镇的统治。",al={"血帆海盗在做什么","血帆海盗攻击计划","血帆海盗阴谋"}},{q="哪个阵营控制着藏宝海湾？",a="藏宝海湾由黑水海盗控制和运营，他们极力保护这个港口免受血帆海盗对手的侵害。",al={"谁管理藏宝海湾","藏宝海湾海盗阵营"}}},fp="24,182,30.294.0,18.237.1,43.125.0,40.86.0,41.127.0,33.109.0"}
P.entries["quest:6"] = {n="加瑞克·帕德弗特的赏金",s="“悬赏加瑞克·帕德弗特”是北郡修道院的维里副队长发布的一份联盟悬赏契约。契约指示年轻的新兵去搜捕一名臭名昭著的当地窃贼，此人一直在农场附近的一间偏僻棚屋骚扰艾尔文森林的农民和商人们。",h="“悬赏加瑞克·帕德弗特”是北郡修道院的维里副队长发布的一份联盟悬赏契约。契约指示年轻的新兵去搜捕一名臭名昭著的当地窃贼，此人一直在农场附近的一间偏僻棚屋骚扰艾尔文森林的农民和商人们。",kw={"悬赏","恶棍","艾尔文","加瑞克","北郡","帕德弗特","窃贼","农场","维里"},ang={["class:Rogue"]="对于潜行者来说，加瑞克·帕德弗特让他们初步了解了不法之徒如何在艾尔文森林的阴影中运作，同时也表明了藏匿不当的据点只会招致快刀。",["faction:Alliance"]="除掉加瑞克·帕德弗特是有志向的联盟冒险者为恢复暴风王国稳定所做的第一次直接服务之一。",["race:Human"]="对于在王国成长起来的人类来说，清除帕德弗特这样的恶棍是保护他们家园神圣土地和当地农民的私事。"},sec={{t="山谷之灾",b="北郡山谷曾被视为训练新兵和照料圣地农场的安全避难所，但最近艾尔文森林各地法律和秩序的崩溃使这里暴露在了危险之中。成群的窃贼潜入了山谷，一个名叫加瑞克·帕德弗特的恶棍很快便纠集了他们。数周以来，加瑞克和他的团伙一直在劫掠货物、在路上抢劫商人，并威胁当地的农民。"},{t="维里副队长的正义",b="由于暴风城的守卫兵力分散在保卫首都和外围边界，当地的治安官和副队长们必须依靠热心的志愿者来维持北郡的和平。维里副队长发出了针对加瑞克的悬赏令，以彻底清除山谷中的这个团伙。在河东岸的简陋棚屋里除掉帕德弗特，是对渗透进人类核心地带的广泛无法无天现象的一次先发制人的打击。"}},faq={{q="加瑞克·帕德弗特是谁？",a="加瑞克·帕德弗特是一名在北郡山谷活动的强盗和恶棍。他花了数周时间骚扰当地农民并伏击商人，在他周围聚集了一小群暴徒，企图在农场附近占据地盘。",al={"加瑞克·帕德弗特","加瑞克是谁","帕德弗特"}},{q="在哪里可以找到加瑞克·帕德弗特？",a="他躲藏在北郡修道院东侧的一间小木棚里，穿过河上的桥，靠近农场的地方。他有同伙的暴徒守卫。",al={"加瑞克·帕德弗特在哪里","加瑞克位置","加瑞克的棚屋"}},{q="谁发布了针对加瑞克的悬赏？",a="驻扎在北郡修道院外的维里副队长发布了这份悬赏。由于缺乏足够的城市卫兵来维持山谷的治安，维里雇佣流浪的新兵来将此歹徒绳之以法。",al={"谁发布了针对加瑞克·帕德弗特的悬赏","维里的悬赏"}},{q="为什么暴风城不派正规士兵去处理他？",a="暴风城的军队兵力不足。随着瓦里安·乌瑞恩国王失踪，艾尔文森林及其他地区局势日益紧张，首都无法为每一个小混混分出资深驻军，只能让当地的副队长招募新兵。",al={"为什么守卫不杀加瑞克","暴风城的守卫在哪里"}},{q="加瑞克·帕德弗特是单独行动的吗？",a="不是。加瑞克身边围拢了一小群不法之徒和强盗，他们驻扎在他北郡农场附近的棚屋周围，以保护他。",al={"加瑞克是一个人吗","帕德弗特团伙"}},{q="维里副队长需要什么证据？",a="在支付赏金之前，维里副队长要求提供实物证据，具体来说就是需要你带回加瑞克·帕德弗特的头颅到北郡修道院。",al={"加瑞克死亡证明","加瑞克的头颅"}}},fx={["38d5a8ce"]={q="维里副队长为什么要杀死加瑞克·帕德弗特？",a="加瑞克·帕德弗特已在北郡山谷肆虐数周。这个凶徒带领着一伙盗贼，专门劫掠维系山谷生计的当地农民与往来商人。维里副队长要取他性命，是为了终结他的劫掠，让葡萄园和道路恢复安全，并保护修道院周边的居民免遭更多暴行。",al={"为什么杀死加瑞克·帕德弗特","维里副队长的动机","维里为什么要杀死加瑞克"}}},fp="25,176,22.327.0,23.394.0,23.180.0,35.143.0,33.178.0,63.235.0,33.132.0,38.124.0"}
P.entries["quest:60"] = {n="狗头人的蜡烛",s="“狗头人的蜡烛”是威廉·匹斯特在闪金镇的狮王之傲旅店提供的一项早期任务。作为一名来自暴风城的炼金师，匹斯特需要狗头人头顶上那种大蜡烛的厚蜡，这些狗头人已经挤满了艾尔文森林的当地矿洞。对于冒险者来说，这是对这些侵蚀王国珍贵金矿脉的地下害虫的初步了解。",h="“狗头人的蜡烛”是威廉·匹斯特在闪金镇的狮王之傲旅店提供的一项早期任务。作为一名来自暴风城的炼金师，匹斯特需要狗头人头顶上那种大蜡烛的厚蜡，这些狗头人已经挤满了艾尔文森林的当地矿洞。对于冒险者来说，这是对这些侵蚀王国珍贵...",kw={"药剂师","蜡烛","艾尔文","法戈第","闪金镇","玉石","狗头人","蜡","威廉·匹斯特"},ang={["faction:Alliance"]="由于皇室军队因内部政治斗争和缺编的王室部队而兵力吃紧，保障当地基础设施的安全便落在了平民志愿者和往来的冒险者肩上。",["profession:Mining"]="为了收集蜡烛而清理狗头人，能将勘探者直接引入艾尔文森林最丰富的铜矿脉和金矿脉，这些矿脉此前已被人类矿工废弃。",["race:Human"]="收复被窃的艾尔文矿洞并为暴风城的本土工匠提供货物，是王国年轻臣民的早期职责。"},sec={{t="药剂师的跑腿",b="威廉·匹斯特与他的兄弟一起在暴风城的贸易区经营着匹斯特药剂店。在调制药剂、药膏和合剂时，像蜡这样的原材料总是供不应求。与其从城市商人那里采购精致的蜡烛，匹斯特意识到那些困扰艾尔文森林的害虫额头上顶着令人惊讶的、厚实的牛脂和蜡——如果冒险者愿意将其撬下来，这些材料唾手可得。"},{t="艾尔文的矿洞",b="狗头人已经彻底占据了闪金镇南部的法戈第矿洞和东北部的玉石矿洞。这些嗅来嗅去的地下生物几乎视蜡烛为生命，利用那摇曳的烛光在黑暗的矿井中穿行，挖掘金矿和闪亮的饰品。掠夺这些蜡烛不仅能满足匹斯特的炼金库存，还能削弱那些正在扼杀王国珍贵矿脉的害虫。"}},faq={{q="威廉·匹斯特为什么需要狗头人蜡烛？",a="威廉·匹斯特和他的兄弟在暴风城的贸易区经营着一家药剂店。他们使用从大蜡烛中提炼出的牛脂和蜡作为密封、药膏以及各种炼金制品的原料。",al={"匹斯特为什么想要蜡烛","蜡烛的用途","蜡烛的蜡的用途"}},{q="去哪里寻找大蜡烛？",a="蜡烛是由栖息在艾尔文森林矿洞中的狗头人苦工、害虫和挖掘者携带的，主要位于闪金镇南部的法戈第矿洞和东部的玉石矿洞内。",al={"哪里有狗头人蜡烛","蜡烛位置","如何获得大蜡烛"}},{q="为什么狗头人如此痴迷于蜡烛？",a="狗头人生活在漆黑的地下隧道中，依靠绑在头上的小火焰在挖掘时照明。他们对黑暗怀有一种近乎疯狂的迷信恐惧，并会拼死保护自己的蜡烛，不让任何人夺走。",al={"为什么狗头人有蜡烛","你不能拿走蜡烛是什么意思","狗头人蜡烛背景故事"}},{q="威廉·匹斯特是谁？",a="威廉·匹斯特是一位来自暴风城的人类商人和炼金师。当他不在城市贸易区的店铺工作时，他会前往闪金镇从往来的冒险者那里获取廉价材料。",al={"威廉·匹斯特是谁","威廉·匹斯特背景故事","闪金镇匹斯特"}},{q="这个任务与艾尔文森林的其他麻烦有关吗？",a="是的。法戈第矿洞和玉石矿洞的虫害对闪金镇和暴风城构成了重大的经济威胁。人类矿工已被驱逐，确保矿洞的安全是杜汉元帅的首要任务之一。",al={"艾尔文森林矿洞问题","为什么狗头人在矿洞里","闪金镇狗头人威胁"}},{q="艾尔文森林还有其他被狗头人占据的矿洞吗？",a="法戈第矿洞和玉石矿洞是闪金镇附近的两个主要地点，但狗头人的活动也蔓延到了森林的河岸边以及向东通往赤脊山的边界处。",al={"其他狗头人矿洞","艾尔文森林矿洞列表"}}},fx={["13eaf00c"]={q="大蜡烛有什么用途？",a="威廉·匹斯特需要大蜡烛上的蜡。他和兄弟在暴风城的贸易区经营着匹斯特的药剂店。任务并未说明他们具体用这些蜡制作什么。",al={"大蜡烛用途","为什么需要大蜡烛","蜡烛有什么用"}},decb568d={q="狗头人为什么会出现在艾尔文的矿洞里？",a="狗头人是生活在地下的拾荒者，阴暗而矿藏丰富的坑道对它们很有吸引力，它们可以在那里挖掘黄金和珍贵矿石。暴风城兵力捉襟见肘，瓦里安·乌瑞恩国王又下落不明，艾尔文当地的法戈第和玉石等矿洞因而防守薄弱，让狗头人得以占据矿井，赶走人类矿工。",al={"狗头人为什么在这里","法戈第为什么有狗头人","艾尔文狗头人泛滥"}},["27573e3c"]={q="威廉·匹斯特为什么找你，而不找暴风城的卫兵？",a="威廉·匹斯特是炼金师，并非士兵。狗头人凶狠地守着法戈第和玉石的坑道，他若亲自冒险进入矿洞，很可能丧命。与此同时，当地的暴风城卫兵和艾尔文治安官们为应付迪菲亚匪徒与豺狼人，早已忙得不可开交，收集蜡烛这类琐事只能交给路过的冒险者。",al={"威廉为什么不自己取蜡烛","为什么雇冒险者收集蜡烛","为什么不找暴风城卫兵"}}},fp="14,275,20.343.0,19.353.0,44.177.0,36.165.0,41.248.0,22.181.0,52.197.0,56.181.0"}
P.entries["quest:600"] = {n="风险投资公司",s="在藏宝海湾，地精克兰克·菲兹巴布希望有人能打击荆棘谷地精在北荆棘谷的行动。他们在水晶矿洞附近的挖掘点源源不断地从附近的山丘中产出珍贵的歌唱蓝水晶，克兰克要求你带回十块这样的石头。",h="在藏宝海湾，地精克兰克·菲兹巴布希望有人能打击荆棘谷地精在北荆棘谷的行动。他们在水晶矿洞附近的挖掘点源源不断地从附近的山丘中产出珍贵的歌唱蓝水晶，克兰克要求你带回十块这样的石头。",kw={"藏宝海湾","克兰克·菲兹巴布","水晶矿洞","歌唱蓝水晶","荆棘谷","荆棘谷地精"},sec={{t="扰乱竞争",b="在你之前收集了歌唱蓝碎片之后，克兰克·菲兹巴布把目标指向了一个更大的竞争对手。荆棘谷地精在整个丛林中开展业务，侵占了独立地精的利润。虽然大量的蛇怪让矿工们无法踏入水晶矿洞，但工人们仍在周围的山坡上挖掘以提取歌唱蓝水晶。克兰克要求你从这些矿工手中夺取水晶，并将其带回藏宝海湾，作为他们受挫的证明。"},{t="水晶送达之后",b="虽然克兰克把这个请求说成是对无情卡特尔的正义报复，但当他看到收集来的歌唱蓝水晶时所表现出的兴奋，暴露了他真正的意图。他并非仅仅想让荆棘谷地精受挫，而是打算在藏宝海湾将这些回收的石头卖个大价钱。"}},faq={{q="谁发布了“扰乱竞争”任务？",a="在完成“歌唱蓝碎片”任务后，可以在藏宝海湾找到地精克兰克·菲兹巴布并接受该任务。",al={"谁发布了扰乱竞争任务","扰乱竞争任务发布者"}},{q="矿工们在什么地方挖掘这些水晶？",a="荆棘谷地精正在北荆棘谷的水晶矿洞附近作业，在矿洞周围的山丘上进行挖掘。",al={"扰乱竞争任务地点","荆棘谷水晶矿洞位置"}},{q="为什么荆棘谷地精的矿工不在矿洞里？",a="克兰克解释说，水晶矿洞里有大量的蛇怪，阻止了矿工进入，迫使他们只能在周边山丘上挖掘。",al={"为什么不去水晶矿洞里面","水晶矿洞蛇怪"}},{q="克兰克·菲兹巴布让你带给他什么？",a="他要求带回十块从在水晶矿洞附近作业的荆棘谷地精矿工手中夺来的歌唱蓝水晶。",al={"扰乱竞争任务需求物品","克兰克·菲兹巴布需要的物品"}},{q="“扰乱竞争”的前置任务是什么？",a="该任务序列的前一个任务是“歌唱蓝碎片”，克兰克会让你先在荆棘谷收集较小的水晶碎片。",al={"扰乱竞争任务链","扰乱竞争前置任务"}}},fp="22,173,26.400.0,25.235.1,43.98.0,48.95.0,54.112.0,47.120.0,40.102.0"}
P.entries["quest:6001"] = {n="身心之力",s="“身与心”是年轻暗夜精灵德鲁伊进行爪之教派入会仪式的终极考验。在达纳苏斯的玛斯雷·驭熊者的指导下，初学者必须前往黑海岸的荒野，召唤枭兽守护者月爪，在获得熊形态之前证明自己兼具内在的坚韧与武力。",h="“身与心”是年轻暗夜精灵德鲁伊进行爪之教派入会仪式的终极考验。在达纳苏斯的玛斯雷·驭熊者的指导下，初学者必须前往黑海岸的荒野，召唤枭兽守护者月爪，在获得熊形态之前证明自己兼具内在的坚韧与武力。",kw={"奥伯丁","熊形态","身与心","塞纳里奥月尘","爪之德鲁伊","月爪","玛斯雷·驭熊者","枭兽之石"},ang={["class:Druid"]="这项仪式代表了早期德鲁伊训练的决定性门槛，将新手施法者转变为能够承担起强大的熊形态的变形保护者。",["race:NightElf"]="对于暗夜精灵来说，与古老的野兽之灵沟通并尊崇黑海岸的神圣石块，重申了数千年前建立的塞纳里奥习俗。"},sec={{t="月爪的试炼",b="达纳苏斯的玛斯雷·驭熊者会指引暗夜精灵德鲁伊初学者前往奥伯丁海岸定居点以东的地区。在那里，藏在栖息着野生枭兽的天然洞穴中，坐落着一块古老的枭兽之石。通过将塞纳里奥月尘涂抹在这块神圣的巨石上，初学者可以唤醒月爪，这位守护着石头、并将挑战任何希望继承神圣之爪力量的祈求者的古老卫士。"},{t="身与心的力量",b="想要披上熊的斗篷，需要的远不止蛮力。虽然巨熊之灵传授了自然狂野的基础教诲，但与月爪的战斗考验的是初学者是否拥有驯服并驾驭这种原始力量所需的坚定内心。通过在战斗中战胜这位守护者并铭记灵魂残留的智慧，德鲁伊证明了自己已经准备好使用熊形态，而不会迷失在野兽的本能之中。"}},faq={{q="月爪是谁？",a="月爪是一只凶猛的枭兽灵魂守护者，栖息在黑海岸奥伯丁正东方的洞穴中。它保卫着神圣的枭兽之石，并会回应那些在圣物上撒下塞纳里奥月尘的初学者的召唤。",al={"什么是月爪","月爪背景故事","奥伯丁枭兽首领"}},{q="这个试炼的目的是什么？",a="这项通过仪式是暗夜精灵初学者寻求加入爪之德鲁伊行列的最终测试。征服月爪证明了初学者拥有获得熊之灵和熊形态所需的身体韧性和精神沉着的平衡。",al={"为什么要完成身与心任务","这个任务有什么用","熊形态任务背景"}},{q="谁给予这个任务？",a="玛斯雷·驭熊者，一位位于达纳苏斯塞纳里奥区的德鲁伊训练师长辈。一旦初学者与巨熊之灵沟通，他就会将这项试炼交给他们。",al={"身与心任务发布者","谁提供熊形态任务"}},{q="什么是塞纳里奥月尘？",a="塞纳里奥月尘是长辈们给予初学者的一种神圣仪式粉末。当撒在枭兽之石上时，其魔法属性会唤醒月爪并开启仪式战斗。",al={"什么是月尘","塞纳里奥月尘背景"}},{q="这项试炼在哪里进行？",a="试炼在黑海岸奥伯丁以东的一个洞穴中进行，那里有野生枭兽在一块古老的雕刻枭兽之石周围筑巢。",al={"枭兽之石在哪里","奥伯丁枭兽洞穴"}},{q="击败月爪后会发生什么？",a="在击败这个生物后，月爪的灵魂会显现在其躯体之上，给予祝福并认可这位德鲁伊在返回达纳苏斯之前所展现出的身与心的双重力量。",al={"击杀月爪后发生什么","月爪之灵"}}},fp="14,211,21.343.0,26.355.1,16.190.0,34.225.0,21.160.0,26.170.0,33.129.0,40.205.1"}
P.entries["quest:6002"] = {n="身心之力",s="“身与心”是牛头人德鲁伊学徒掌握熊形态的终极试炼。在雷霆崖的图拉克·符文图腾指引下，学徒必须前往莫高雷与贫瘠之地的交界处，在月光枭兽之石前召唤并击败月爪。",h="“身与心”是牛头人德鲁伊学徒掌握熊形态的终极试炼。在雷霆崖的图拉克·符文图腾指引下，学徒必须前往莫高雷与贫瘠之地的交界处，在月光枭兽之石前召唤并击败月爪。",kw={"贫瘠之地","熊形态","身与心","陶拉祖营地","赛纳里奥银尘","月爪","月光枭兽之石","莫高雷","雷霆崖","图拉克·符文图腾"},ang={["class:Druid"]="这一成人礼架起了暗夜精灵塞纳里奥教义与牛头人传统之间的桥梁，使年轻的德鲁伊终于能够展现出熊形态那凶猛的韧性。",["faction:Horde"]="牛头人德鲁伊为部落的前线带来了至关重要的韧性，将部落的魔法力量根植于深厚的荒野守护之中。",["race:Tauren"]="对于舒哈鲁人来说，唤醒心中的熊既是与自然之灵的神圣沟通，也是保护莫高雷平原免受威胁的切实手段。"},sec={{t="利爪之道",b="为了真正走上利爪德鲁伊之路，牛头人学徒必须将精神信念与肉体韧性结合起来。在月光林地与伟大熊灵沟通后，德鲁伊的训练便迎来了一次实战考验。雷霆崖长者高地上的资深德鲁伊训练师图拉克·符文图腾会将赛纳里奥银尘赐予有资格的学徒，并指引他们前往莫高雷与贫瘠之地接壤的荒芜边境寻找一块神圣之石。"},{t="月爪的试炼",b="月光枭兽之石位于陶拉祖营地以西，是卡利姆多南部一处罕见的塞纳里奥遗迹。月光枭兽并非卡利姆多中部烈日灼烤平原的原生物种，因此守护兽月爪在此出现意义深远。德鲁伊将银尘洒在古老的纪念碑上，便能召唤月爪进行战斗。击败这只生物证明了学徒既有强健的体魄，又有清澈的心灵，从而赢得了野兽的祝福，解开了熊的内在精髓。"}},faq={{q="这项试炼的目的是什么？",a="这项任务是部落德鲁伊获得熊形态的最后一步。完成这一挑战，即证明了你有资格在图拉克·符文图腾的教导下承担起利爪德鲁伊的职责。",al={"为什么要进行身与心试炼","身与心试炼有什么作用","完成身与心试炼有什么奖励"}},{q="月光枭兽之石在哪里？",a="月光枭兽之石位于贫瘠之地，陶拉祖营地以西，通往莫高雷大门的道路旁。在那条路南边，一顶孤零零的帐篷旁，藏在树后便是那块神圣之石。",al={"月光枭兽之石的位置","月光枭兽之石在哪里","如何找到月光枭兽之石"}},{q="月爪是谁？",a="月爪是一只凶猛的月光枭兽守护者，与月光枭兽之石绑定。它可以通过赛纳里奥银尘召唤出来，旨在测试德鲁伊是否拥有运用熊之力所必需的原始韧性和情绪自控力。",al={"月爪是谁","什么是月爪"}},{q="如果我在与月爪的战斗中失败了怎么办？",a="如果你被击败，你的赛纳里奥银尘就会消耗掉。你必须回到雷霆崖长者高地找图拉克·符文图腾领取另一袋银尘，然后才能再次进行召唤。",al={"月爪挑战失败","银尘丢失","死于月爪之手"}},{q="月光枭兽是贫瘠之地的原生物种吗？",a="不是。正如图拉克·符文图腾所言，月光枭兽并非贫瘠之地或莫高雷的原生生物。这种生物出现在稀树草原上显得很不自然，它们与塞纳里奥仪式和古老的天界力量遗迹有着特殊的联系。",al={"贫瘠之地有月光枭兽吗","为什么这里会有月光枭兽","贫瘠之地的月光枭兽"}},{q="谁发放“身与心”任务？",a="该任务由位于雷霆崖长者高地的资深德鲁伊训练师图拉克·符文图腾发放，就在学徒从月光林地归来之后。",al={"谁发放身与心任务","身与心任务发放人"}}},fp="14,227,19.385.0,21.383.0,34.185.0,35.178.0,16.175.0,51.169.0,34.161.0,35.142.0"}
P.entries["quest:601"] = {n="水元素",s="在有了关于海潮之石的发现后，大财主里维加兹一直在寻找对抗该神器诅咒的方法。他派遣冒险者重返岛屿，从召唤出的水元素身上收集护腕，以便专家能检查其上的魔法残余。",h="在有了关于海潮之石的发现后，大财主里维加兹一直在寻找对抗该神器诅咒的方法。他派遣冒险者重返岛屿，从召唤出的水元素身上收集护腕，以便专家能检查其上的魔法残余。",kw={"藏宝海湾","护腕","诅咒","达拉然","加兹班","里维加兹","海潮之石","水元素"},sec={{t="遏制诅咒",b="大财主里维加兹认为这些水元素是由地精法师加兹班召唤的，并怀疑它们身上的魔法残余隐藏着处理海潮之石的关键线索。据说这块石头会诅咒任何持有它的人，使持有者在现实中忽隐忽现。为了找到对策，里维加兹指引你重返近海岛屿，收集元素护腕，以便达拉然的博学法师们进行研究。"},{t="藏宝海湾的主人",b="在收到护腕后，里维加兹承认他缺乏专业的知识来判断它们是否有用。他并不打算亲自前往达拉然——他可不愿为了和那帮讨厌的老法师闲聊而离开藏宝海湾——于是他派遣你前往北方，请一位法师来鉴定它们。"}},faq={{q="谁想要这些水元素护腕？",a="藏宝海湾黑水强盗的领袖大财主里维加兹需要这些护腕，以调查围绕着海潮之石的魔法。",al={"谁给予水元素任务","大财主里维加兹任务","谁想要护腕"}},{q="大财主里维加兹为什么需要元素护腕？",a="他希望研究护腕上的魔法残余能揭示出对抗海潮之石诅咒的方法，这种诅咒会导致持有者在现实中忽隐忽现。",al={"为什么要收集护腕","水元素护腕的用途","海潮之石的诅咒"}},{q="是谁召唤了这些水元素？",a="大财主里维加兹认为它们是由加兹班召唤的，据传这位地精法师发现了海潮之石。",al={"谁召唤了元素","加兹班背景","地精法师"}},{q="这项任务接下去要做什么？",a="接下来是魔法分析：里维加兹会将护腕送往北方的达拉然，让法师检查上面的残余。",al={"水元素任务之后是什么","下一个任务","护腕会被送到哪里"}},{q="为什么里维加兹不亲自将护腕送到达拉然？",a="他不想为了和那帮讨厌的老法师闲聊而离开藏宝海湾，而且他坚称自己无惧任何潜在的竞争对手。",al={"里维加兹为什么不去","里维加兹 达拉然","为什么要留在藏宝海湾"}}},fp="16,165,17.297.0,18.199.0,38.148.0,47.158.0,36.121.0,31.84.0,57.130.0"}
P.entries["quest:602"] = {n="魔法分析",s="大财主里维加兹指引你从藏宝海湾向北出发，去达拉然咨询肯瑞托。你带着一袋水元素护腕，前往寻找大法师安斯雷姆·鲁因维沃尔，以破译与海潮之石有关的奥术诅咒。",h="大财主里维加兹指引你从藏宝海湾向北出发，去达拉然咨询肯瑞托。你带着一袋水元素护腕，前往寻找大法师安斯雷姆·鲁因维沃尔，以破译与海潮之石有关的奥术诅咒。",kw={"大法师安斯雷姆·鲁因维沃尔","大财主里维加兹","藏宝海湾","达拉然","古拉巴什帝国","魔法分析","海潮之石","水元素护腕"},ang={["class:Mage"]="将奥术神器交给肯瑞托的大法师很适合法师，正如大财主里维加兹自己所说，法师无法抗拒魔法谜题。"},sec={{t="前往达拉然的请求",b="在你搜集完水元素护腕后，大财主里维加兹交给你一捆护腕。这位地精领袖知道，想要解开海潮之石背后的诅咒，需要比藏宝海湾所能提供的更深奥的魔法知识。他指引你向北前往达拉然的废墟，那里的法师们正忙于重建他们破碎的王国。里维加兹确信奥术学者无法抗拒这种引人入胜的谜题，因此建议你直接去寻找大法师安斯雷姆·鲁因维沃尔，因为他过去曾与这位知识渊博的法师有过往来。"},{t="大法师的学识",b="在达拉然繁忙的重建工作中找到安斯雷姆·鲁因维沃尔后，这位忙碌的大法师在听说这件遗物时停下了手中的工作。多年前，鲁因维沃尔曾撰写过一篇关于古拉巴什帝国古代传说的学术论文，这使他对该遗物的历史有着罕见的深刻见解。在检查这些护腕时，他发现了适合研究的微量魔法残留，于是放下手头的工作，开始揭开这些附魔中隐藏的秘密。"}},faq={{q="是谁派你去达拉然进行这项研究的？",a="藏宝海湾的大财主里维加兹给了你那袋元素护腕，并指示你去咨询达拉然的法师们。",al={"谁提供魔法分析","魔法分析任务发布者","谁开始魔法分析"}},{q="为什么大财主里维加兹选择了大法师安斯雷姆·鲁因维沃尔？",a="里维加兹以前和鲁因维沃尔打过交道，深知这位大法师知识渊博；他也相信法师们无法抗拒魔法谜题。",al={"为什么是安斯雷姆","里维加兹与安斯雷姆的关系","为什么是大法师安斯雷姆·鲁因维沃尔"}},{q="在前往达拉然之前发生了什么？",a="这个任务紧接着“水元素”任务，你在该任务中为大财主里维加兹收集了水元素护腕。",al={"前置任务","魔法分析前置条件","什么任务引导至此"}},{q="在找到大法师之后接下来要做什么？",a="交出护腕后，任务将引导至“安斯雷姆的钥匙”。",al={"后续任务","魔法分析之后是什么","交付护腕后"}}},fp="16,176,17.400.0,19.379.1,40.110.0,57.143.0,41.105.0,44.55.0"}
P.entries["quest:6027"] = {n="上古之书",s="位于艾瑟雷索高塔的阿佐尔·奥达蒙特托付给你一颗宝石。将它安放在拉纳加尔岛上一座蛇形雕像的手中，那座岛就在高塔的西北方，它会召唤出《古人之书》的守护者。这本书里记载着纳迦数个世纪以来保守的秘密。",h="位于艾瑟雷索高塔的阿佐尔·奥达蒙特托付给你一颗宝石。将它安放在拉纳加尔岛上一座蛇形雕像的手中，那座岛就在高塔的西北方，它会召唤出《古人之书》的守护者。这本书里记载着纳迦数个世纪以来保守的秘密。",kw={"阿佐尔·奥达蒙特","古人之书","艾瑟雷索","毒蛇宝石","纳迦","拉纳加尔岛","蛇形雕像"},sec={{t="蛇形雕像",b="在完成“光之权杖”任务后，阿佐尔·奥达蒙特会交给你毒蛇宝石。在艾瑟雷索高塔西北方的一座小岛——拉纳加尔岛上，矗立着一座蛇形雕像，这颗宝石需要安放在它的手上。这样做会引出《古人之书》的守护者，这本书里记载着纳迦数个世纪以来保守的秘密。阿佐尔希望它能让我们更多地了解这些鳞片敌人。"}},faq={{q="阿佐尔·奥达蒙特是谁？",a="艾瑟雷索高塔的看守者，他希望了解更多关于纳迦的信息，阿佐尔称他们为“鳞片敌人”。",al={"阿佐尔·奥达蒙特","谁给予古人之书任务","艾瑟雷索高塔的人"}},{q="什么是《古人之书》？",a="一本记载了纳迦数个世纪以来保守秘密的书籍。有人在守护着它。",al={"什么是古人之书","书籍背景","凄凉之地纳迦之书"}},{q="拉纳加尔岛在哪里？",a="位于艾瑟雷索高塔西北方的一座小岛。",al={"拉纳加尔岛位置","拉纳加尔岛在哪里","带着宝石去哪"}},{q="毒蛇宝石有什么用？",a="将它安放在拉纳加尔岛上的蛇形雕像手中，便会引出《古人之书》的守护者。",al={"毒蛇宝石","蛇形雕像的手","如何召唤守护者"}},{q="在此之前发生了什么？",a="在此步骤之前是“光之权杖”任务。",al={"前置任务","光之权杖任务线","先决条件"}}},fp="20,212,18.355.0,22.119.0,33.91.0,23.68.0,35.134.0,22.40.0"}
P.entries["quest:603"] = {n="安斯雷姆的钥匙",s="经过魔法测试后，大法师安斯雷姆·鲁因维沃尔指出了这把上古巨魔匕首，它能够干扰增强海潮之石的聚焦祭坛。很久以前，他把这把匕首交给了他的女儿凯特琳，一个倔强的女孩，她为了加入藏宝海湾的海盗而离家出走。",h="经过魔法测试后，大法师安斯雷姆·鲁因维沃尔指出了这把上古巨魔匕首，它能够干扰增强海潮之石的聚焦祭坛。很久以前，他把这把匕首交给了他的女儿凯特琳，一个倔强的女孩，她为了加入藏宝海湾的海盗而离家出走。",kw={"安斯雷姆","藏宝海湾","凯特琳","匕首","鲁因维沃尔","海潮之石","巨魔遗物"},sec={{t="误入歧途的女儿",b="安斯雷姆·鲁因维沃尔断定，有一个祭坛或焦点正在放大海潮之石的力量。要压制这种魔法，需要另一件巨魔遗物：一把他在荆棘谷研究时发现的上古匕首。很久以前，他把这把匕首交给了他的女儿凯特琳，一个倔强的女孩，她为了加入藏宝海湾的海盗而离家出走。"},{t="缴械的战士",b="抵达藏宝海湾后发现，匕首已经不在凯特琳的腰间了。她曾是这个定居点最犀利的刀客，但在与一名血帆海盗的决斗中战败了。胜者将那把巨魔刀刃当作战利品抢走，让她落得个被缴械、受羞辱的下场，还遭到了其他海盗同伙的冷嘲热讽。"}},faq={{q="为什么大法师安斯雷姆需要那把巨魔匕首？",a="持有海潮之石的法师正通过一座祭坛引导其魔法。安斯雷姆打算通过压制来干扰这种能量增强，而他知道一把上古巨魔匕首可以做到这一点。",al={"为什么需要匕首","安斯雷姆之钥的目的","匕首的用途"}},{q="凯特琳是谁？",a="凯特琳是大法师安斯雷姆·鲁因维沃尔那倔强的女儿。她抛下了父亲，跑到藏宝海湾过起了海盗生活。",al={"凯特琳是谁","安斯雷姆的女儿","利刃凯特琳"}},{q="安斯雷姆最初是在哪里找到这把匕首的？",a="安斯雷姆是在荆棘谷的丛林中进行研究时发现了这件遗物，随后将其交给了女儿。",al={"匕首的起源","安斯雷姆在哪里找到的匕首"}},{q="在哪里可以找到凯特琳？",a="她住在荆棘谷南端的藏宝海湾，那是一处海盗避风港。",al={"凯特琳在哪里","凯特琳的位置"}}},fp="13,223,18.317.0,18.289.1,48.163.0,15.128.0,45.109.0,27.87.0"}
P.entries["quest:604"] = {n="血帆海盗",s="舰队指挥官卡拉·海角信任黑水强盗的忠实盟友，委托其突袭血帆海盗在蛮荒海岸所谓的南方指挥所。夺回他们的海图和书面计划书将揭示这些海盗到底在谋划什么。",h="舰队指挥官卡拉·海角信任黑水强盗的忠实盟友，委托其突袭血帆海盗在蛮荒海岸所谓的南方指挥所。夺回他们的海图和书面计划书将揭示这些海盗到底在谋划什么。",kw={"黑水强盗","血帆海盗","血帆海图","血帆计划书","藏宝海湾","舰队指挥官卡拉·海角","蛮荒海岸"},sec={{t="突袭蛮荒海岸",b="在完成了克拉兹早先的任务后，舰队指挥官卡拉·海角注意到了你对黑水强盗的忠诚。血帆海盗在蛮荒海岸建立了他们所谓的南方指挥所。卡拉·海角指派你去突袭这个营地，消灭他们的剑客，并夺取他们的航海图和书面计划书，以便舰队能够了解他们的企图。"},{t="揭露海盗的阴谋",b="拿到海图和计划书后，卡拉·海角了解了血帆海盗的计划，并断定这伙海盗已经在海角附近抛锚驻扎。"}},faq={{q="谁发布了这个突袭任务？",a="在听闻克拉兹对你的奉献精神大加赞赏后，舰队指挥官卡拉·海角在藏宝海湾发布了这项任务。",al={"谁发布了血帆海盗任务","卡拉·海角任务"}},{q="血帆海盗的指挥所在哪里？",a="血帆海盗在荆棘谷藏宝海湾南部的蛮荒海岸建立了他们的南方指挥营地。",al={"血帆南方指挥所位置","蛮荒海岸在哪里"}},{q="从血帆营地需要取回什么物品？",a="卡拉·海角要求取回血帆海图和他们的书面血帆计划书，以解读这些敌对海盗的意图。",al={"卡拉·海角需要什么文件","血帆计划书和海图"}},{q="为什么舰队指挥官卡拉·海角想要他们的海图和计划书？",a="卡拉·海角想要确切地了解血帆海盗到底在策划什么。",al={"为什么要突袭蛮荒海岸","卡拉·海角想要知道什么"}}},fp="24,205,22.329.0,29.115.1,22.89.0,44.118.0,52.120.0,59.101.0"}
P.entries["quest:605"] = {n="歌唱水晶碎片",s="克兰克·菲兹巴布正在寻找一位有进取心的冒险者，从荆棘谷的石化蜥蜴身上收集歌唱水晶碎片。与荆棘谷地精的竞争使他无法直接开采矿床，因此石化蜥蜴皮成了次优选择。他承诺将利润的一部分分给任何愿意为他带来十个合格样本的人。",h="克兰克·菲兹巴布正在寻找一位有进取心的冒险者，从荆棘谷的石化蜥蜴身上收集歌唱水晶碎片。与荆棘谷地精的竞争使他无法直接开采矿床，因此石化蜥蜴皮成了次优选择。他承诺将利润的一部分分给任何愿意为他带来十个合格样本的人。",kw={"石化蜥蜴","克兰克·菲兹巴布","歌唱蓝色水晶","歌唱水晶","荆棘谷","荆棘谷地精","祖昆达"},sec={{t="有利可图的机会",b="克兰克·菲兹巴布发现荆棘谷独有的歌唱水晶市场非常广阔。但不幸的是，荆棘谷地精的强势存在让他难以在野外直接收集原始水晶。为了绕过他的竞争对手，菲兹巴布转向了一种替代方法：石化蜥蜴会吞食这些水晶，并将其矿物质融入到它们坚硬的皮中，从而可以从它们身上获得可用的碎片。"},{t="海岸狩猎",b="虽然丛林中的任何石化蜥蜴都可能掉落合适的水晶碎片，但菲兹巴布说，在祖昆达以南、北部海岸一带能找到更温顺的石化蜥蜴。收集到十个碎片后，他就可以继续与买家进行交易，此后他的商业重心将转向荆棘谷地精的行动本身。"}},faq={{q="克兰克·菲兹巴布为什么要歌唱水晶碎片？",a="歌唱水晶是荆棘谷独有的，对某些特定的买家来说非常有价值。克兰克·菲兹巴布说他可以将其出售，并承诺分给冒险者一部分利润。",al={"为什么需要歌唱水晶","克兰克·菲兹巴布的目的","歌唱水晶的用途"}},{q="为什么克兰克·菲兹巴布不能直接开采水晶？",a="菲兹巴布将原因归咎于荆棘谷地精，认为他们让像他这样的诚实商人很难亲自收集原始水晶。",al={"为什么要杀石化蜥蜴","荆棘谷地精的问题","为什么不能直接开采水晶"}},{q="为什么石化蜥蜴会有这些水晶？",a="荆棘谷的石化蜥蜴以这些水晶为食，水晶会逐渐融入它们的皮中，使它们长出坚硬的岩石状皮肤。",al={"石化蜥蜴与水晶的背景故事","为什么石化蜥蜴会掉落水晶"}},{q="克兰克·菲兹巴布建议在哪里寻找石化蜥蜴？",a="菲兹巴布说任何石化蜥蜴都能产出碎片，但更温顺的石化蜥蜴生活在祖昆达以南的北部海岸沿线。",al={"哪里可以找到碎片","石化蜥蜴的位置","祖昆达的石化蜥蜴"}},{q="上交碎片后会发生什么？",a="在收到十个碎片后，菲兹巴布会支付承诺的利润分成，并将注意力直接转向荆棘谷地精的活动。",al={"完成歌唱蓝色水晶后的后续","歌唱蓝色水晶后续任务"}}},fp="19,221,23.301.0,17.264.0,53.162.0,57.88.0,37.128.0,57.109.0,41.143.1"}
P.entries["quest:606"] = {n="吓唬病鬼",s="“海狼”马克基雷无法忍受未偿还的赌债，而且很多人都欠他的钱。首先就是藏宝海湾码头附近的“病鬼”菲利普，他在上周的赌局中还欠下一大笔钱。马克基雷的计划是恐吓一下，利用年长的迷雾谷大猩猩的杂碎。",h="“海狼”马克基雷无法忍受未偿还的赌债，而且很多人都欠他的钱。首先就是藏宝海湾码头附近的“病鬼”菲利普，他在上周的赌局中还欠下一大笔钱。马克基雷的计划是恐吓一下，利用年长的迷雾谷大猩猩的杂碎。",kw={"藏宝海湾","赌债","迷雾谷杂碎","迷雾谷大猩猩","恐吓“病鬼”","“海狼”马克基雷","“病鬼”菲利普","荆棘谷"},sec={{t="收债",b="“海狼”马克基雷无法容忍未偿还的赌债，有很多人都欠他的钱。其中首当其冲的就是“病鬼”菲利普，他就在码头附近，他在上周的赌局中欠下了巨额债务。收债的方法就是恐吓菲利普。你被派到城外去猎杀年长的迷雾谷大猩猩，并带回一大堆杂碎交给菲利普。马克基雷希望保密这些杂碎来自动物，好让菲利普往最坏处想。"},{t="菲利普的反应",b="菲利普对那些杂碎感到退缩，也不想知道它们是从哪里来的。然后，菲利普询问是不是“海狼”派你来的。"}},faq={{q="谁是“海狼”马克基雷？",a="马克基雷被许多人欠着赌债，他想要人帮忙收债，首先就是从“病鬼”菲利普开始。",al={"马克基雷是谁","“海狼”马克基雷","谁给予恐吓“病鬼”任务"}},{q="为什么马克基雷要恐吓“病鬼”菲利普？",a="菲利普在上周的赌局中还欠马克基雷一大笔钱，而马克基雷认为恐吓一下是讨债的好办法。",al={"为什么要恐吓“病鬼”","“病鬼”菲利普的债务","为什么要针对菲利普"}},{q="什么生物会掉落这些杂碎？",a="年长的迷雾谷大猩猩，马克基雷说它们在城外。",al={"杂碎从哪里来","迷雾谷杂碎来源","为了杂碎要杀什么"}},{q="哪里可以找到“病鬼”菲利普？",a="在藏宝海湾的码头边。",al={"“病鬼”菲利普在哪里","“病鬼”的位置","寻找“病鬼”菲利普"}},{q="关于这些杂碎，你应该告诉菲利普什么？",a="什么都别说。马克基雷希望菲利普往最坏处想，所以不能提这些杂碎是来自动物的。",al={"我需要告诉“病鬼”杂碎的来源吗"}}},fp="13,203,17.353.0,19.134.1,28.131.0,50.108.0,35.74.0,36.60.0,48.93.0"}
P.entries["quest:6061"] = {n="驯服野兽",s="驯服野兽是血蹄村年轻牛头人猎人的基础成年仪式。在训练师雅文·刺鬃的指导下，猎人会深入莫高雷去驯服一只成年平原陆行鸟，这是与大地母亲的生物建立精神纽带的第一步。",h="驯服野兽是血蹄村年轻牛头人猎人的基础成年仪式。在训练师雅文·刺鬃的指导下，猎人会深入莫高雷去驯服一只成年平原陆行鸟，这是与大地母亲的生物建立精神纽带的第一步。",kw={"血蹄村","大地母亲","猎人任务","莫高雷","平原陆行鸟","驯服","驯兽棒","雅文·刺鬃"},ang={["class:Hunter"]="这项仪式标志着从初出茅庐的追踪者向真正的兽王转变，教导你如何在大地母亲的指引下与动物交流。",["race:Tauren"]="驯服野兽是莫高雷游牧狩猎传统中的核心祖先实践，它加强了猎人与自然之间的纽带。"},sec={{t="与荒野的神圣纽带",b="对牛头人来说，狩猎从来不仅仅是为了肉和皮毛而猎杀野兽。祖先的传统认为，征服并与莫高雷的野生动物交流，可以让猎人吸收它们的精神，从而更接近大地母亲。驯服一头伴侣野兽升华了这种联系，将原本可能是对手的生物变成与平原的自然平衡相一致的终身伙伴。"},{t="初次试炼",b="雅文·刺鬃对新手的指导并不是从凶猛的顶级掠食者开始，而是从漫步在莫高雷草原上敏捷且警觉的平原陆行鸟开始。猎人带着一根附魔的驯兽棒，必须面对一只成年平原陆行鸟，平复它野性的本能，并赢得它的信任。这次初期的试炼旨在证明猎人的决心，并为他们后续更具挑战性的驯服任务做好准备。"}},faq={{q="这项试炼的目的是什么？",a="这个任务是初出茅庐的牛头人猎人学习动物伙伴艺术的第一次实践测试。通过使用驯兽棒来安抚一只成年平原陆行鸟，猎人可以学习与野兽建立精神和工作联系的基本原则。",al={"为什么要驯服平原陆行鸟","任务目的","牛头人宠物任务目的"}},{q="谁发布了这个任务，他们在哪里？",a="该任务由位于莫高雷中部平原血蹄村的猎人训练师雅文·刺鬃发布。",al={"谁发布任务","任务发布者位置","雅文·刺鬃位置"}},{q="我会永久保留这只成年平原陆行鸟吗？",a="不会。在雅文·刺鬃最初的三次试炼中驯服的野兽只是临时的练习伙伴。当你完成整个训练链并掌握驯服野兽的技巧后，你就可以出去永久驯服任何兼容的伴侣了。",al={"宠物是永久的吗","我会保留平原陆行鸟吗","任务后保留野兽"}},{q="为什么牛头人认为驯服野兽是一种精神行为？",a="牛头人的传统教导说，与野生生物互动并战胜它们，可以让猎人吸收它们的精神，并与自然世界合而为一。驯服一头野兽体现了对大地母亲创造物的相互尊重与团结。",al={"牛头人宠物知识","大地母亲驯服知识","为什么牛头人要驯服野兽"}},{q="在哪里可以找到成年平原陆行鸟？",a="成年平原陆行鸟广泛分布在莫高雷血蹄村周围起伏的稀树草原和山谷中。",al={"平原陆行鸟在哪里","平原陆行鸟位置","寻找成年平原陆行鸟"}},{q="这个任务之后是什么？",a="将驯兽棒交还给雅文·刺鬃会开启下一个试炼，任务要求你驯服一只潜伏者，接着是一只攻击性更强的峭壁鸟，之后才能学习永久驯服野兽的艺术。",al={"下一步是什么","后续任务链","驯服的下一步"}}},fp="16,235,27.287.0,14.313.0,34.202.0,48.92.0,45.199.0,52.210.0,39.87.0,28.177.0"}
P.entries["quest:6062"] = {n="驯服野兽",s="这个试炼标志着年轻的部落猎人向驯兽艺术迈出了第一步。在剃刀岭的资深猎人索塔尔的指导下，初出茅庐的猎人们使用一根附魔驯兽棒来制服并驯化一头凶猛的杂斑野猪。",h="这个试炼标志着年轻的部落猎人向驯兽艺术迈出了第一步。在剃刀岭的资深猎人索塔尔的指导下，初出茅庐的猎人们使用一根附魔驯兽棒来制服并驯化一头凶猛的杂斑野猪。",kw={"杂斑野猪","杜隆塔尔","猎人任务","宠物驯服","剃刀岭","驯兽棒","索塔尔"},ang={["class:Hunter"]="这项成人礼架起了从一名普通神射手到真正野兽大师之间的桥梁，解锁了猎人与动物同伴之间决定性的羁绊。",["race:Orc"]="对于兽人来说，指挥野兽体现了意志的力量和对杜隆塔尔新家园恶劣荒野的掌控力。",["race:Troll"]="暗矛猎人利用这种训练将他们的精神与卡利姆多崎岖的野生动物相协调，延续他们古老的追踪传统。"},sec={{t="猎人的成人礼",b="对于在杜隆塔尔成年的兽人和暗矛巨魔猎人来说，独自在荒野中生存仅仅是考验的一半。一名真正的荒野大师必须学会对自然本身施加权威，将敌对的野兽变成忠诚的盟友。猎人训练师索塔尔将一根附魔驯兽棒交给新手，并要求他们面对一头凶猛的野猪，而不使用致命的箭矢。"},{t="杜隆塔尔的野猪",b="杂斑野猪游荡在剃刀岭周围干旱的灌木丛中。虽然它们粗野且脾气暴躁，但其韧性和凶猛使它们成为理想的入门驯服对象。在引导驯兽棒力量的同时，承受它们的冲锋和暴躁，需要耐心和钢铁般的意志——这是任何部落追踪者必备的品德。"}},faq={{q="这项试炼的目的是什么？",a="这是年轻猎人在杜隆塔尔进行的第一次实践测试，教导他们如何通过驯兽棒引导自己的意志来制服野兽，而不是仅仅将其杀死。",al={"为什么要完成这个任务","驯服野猪任务的原因","驯服野兽的任务重点"}},{q="谁发布这个任务？",a="一旦你在杜隆塔尔证明了自己的基本生存技能，驻扎在剃刀岭的猎人训练师索塔尔就会提供这项任务。",al={"任务发布者","谁发布了驯服野兽","在哪里获得野猪任务"}},{q="在哪里可以找到杂斑野猪？",a="杂斑野猪可以在杜隆塔尔中部剃刀岭的栅栏外干旱的灌木丛中找到。",al={"野猪位置","杂斑野猪在哪里","在哪里寻找野猪"}},{q="完成任务后我可以永久保留这头野猪吗？",a="不能。在这个初步练习中驯服的野猪仅用于练习。一旦归还给索塔尔，它就会离开，因为你必须在形成持久的羁绊之前继续你与其他生物的训练。",al={"我能保留这头野猪吗","这头野猪是我的永久宠物吗","保留杂斑野猪"}},{q="这项任务之后是什么？",a="一旦你回到索塔尔那里，他会测试你对在杜隆塔尔发现的其他致命捕食者的控制能力，包括冲浪爬行者和装甲蝎子。",al={"后续任务","驯服野猪之后做什么","驯服任务链的下一步"}},{q="为什么要使用驯兽棒而不是纯粹的直觉？",a="新手猎人缺乏直接与野兽建立联系所需的精炼精神和身体纪律。附魔驯兽棒充当了一个焦点，帮助新手将权威投射到野兽的精神上，直到他们彻底掌握这门艺术。",al={"为什么使用驯兽棒","驯兽棒有什么作用","驯兽棒的背景故事"}}},fp="16,149,26.265.0,20.252.0,34.148.0,21.121.0,39.95.0,50.146.0,27.138.0,46.193.0"}
P.entries["quest:6063"] = {n="驯服野兽",s="此任务是暗夜精灵猎人通往掌握野兽伙伴之路的第一次试炼。在多兰纳尔的达扎拉指导下，有志成为猎人的新兵必须使用一根附魔的驯兽棒与一只野生的网林潜伏者建立联系。这考验了猎人尊重并与自然交流的能力，而非试图暴力征服。",h="此任务是暗夜精灵猎人通往掌握野兽伙伴之路的第一次试炼。在多兰纳尔的达扎拉指导下，有志成为猎人的新兵必须使用一根附魔的驯兽棒与一只野生的网林潜伏者建立联系。这考验了猎人尊重并与自然交流的能力，而非试图暴力征服。",kw={"达扎拉","多兰纳尔","猎人宠物","卡多雷","驯服","驯兽棒","泰达希尔","网林潜伏者"},ang={["class:Hunter"]="这一成人礼标志着猎人从孤独的弓箭手转变为荒野的真正伙伴，与森林的野兽结下羁绊。",["race:NightElf"]="这种驯服宠物的做法反映了卡多雷的哲学，强调与自然的交流和对自然的敬畏，而非征服和统治。"},sec={{t="神圣的羁绊",b="对于卡多雷来说，狩猎不仅仅是追踪猎物或在荒野中生存；它与自然之间存在着一种神圣的关系。像达扎拉这样的猎人训练师教导说，自然远比任何凡人个体都要伟大。动物不是驮兽，也不是可以强行屈从于个人意志的工具，而是需要相互尊重的独立生物。为了证明自己已经准备好迎接终身的野兽伙伴，新手猎人必须通过古老的技术，而不是蛮力，来证明他们能够掌控当地野生动物的原始本能。"},{t="第一次试炼",b="试炼始于泰达希尔枝干上出没的巨型蛛类。达扎拉将一根特制的驯兽棒交给猎人，指引他们去寻找一只网林潜伏者。猎人必须深入阴影丛林，面对剧毒蜘蛛，并在抵挡其攻击的同时建立共情通道。成功建立起这座临时的心灵之桥，证明了猎人甚至可以与世界之树那些令人毛骨悚然、爬行的掠食者进行交流。"}},faq={{q="此任务的目的是什么？",a="此任务启动了暗夜精灵猎人永久驯服动物伙伴所需的训练序列。通过对指定的当地野兽使用驯兽棒，猎人证明了他们拥有与野生掠食者交流的性情和技巧。",al={"为什么要进行此任务","宠物任务目的","驯服野兽提供什么"}},{q="谁提供此任务？",a="达扎拉，这位居住在泰达希尔多兰纳尔定居点的猎人训练师，会向那些在该领域达到足够经验的年轻暗夜精灵猎人提供此任务。",al={"任务提供者","在哪里接取驯服任务","谁开启驯服野兽任务"}},{q="在此试炼中必须驯服什么生物？",a="你的任务是驯服一只网林潜伏者，它们是居住在多兰纳尔外围荒野丛林中的剧毒巨型蜘蛛之一。",al={"驯服哪种宠物","网林潜伏者目标","我驯服什么野兽"}},{q="我能永久保留网林潜伏者吗？",a="不能。在此任务中驯服的网林潜伏者只是一个临时伙伴，仅用于练习宠物处理的基础知识。一旦回到达扎拉那里，当你准备进行下一次试炼时，这种羁绊就会解除。",al={"我可以保留这只蜘蛛吗","网林潜伏者可以永久保留吗","保留宠物"}},{q="为什么暗夜精灵先用蜘蛛来测试猎人？",a="网林潜伏者具有掠食性和攻击性，这使其成为了对新手心态的严峻考验。能够掌控这种看似非自然的蛛类，证明了猎人能够将自己的意识与自然界中各种敌对的表象连接起来。",al={"为什么是网林潜伏者","为什么驯服蜘蛛","蜘蛛驯服背景知识"}},{q="回到达扎拉那里之后要做什么？",a="达扎拉会派遣猎人去测试他们与泰达希尔其他本土动物——特别是夜刃豹潜行者和夜枭尖啸者——之间的羁绊，之后才会授予永久驯服能力。",al={"接下来做什么","驯服野兽任务之后","下一次试炼"}}},fp="16,220,13.403.0,15.339.0,34.176.0,21.124.0,42.106.0,41.161.0,51.182.0,38.180.1"}
P.entries["quest:6064"] = {n="驯服野兽",s="驯服野兽是矮人猎人踏上驯服野兽旅程后的第一个试炼，地点位于丹莫罗。在卡拉诺斯的格瑞夫指导下，年轻的追踪者们将学习如何使用一根附魔的驯兽棒，来安抚并与凶猛的大型岩鬃野猪建立羁绊。",h="驯服野兽是矮人猎人踏上驯服野兽旅程后的第一个试炼，地点位于丹莫罗。在卡拉诺斯的格瑞夫指导下，年轻的追踪者们将学习如何使用一根附魔的驯兽棒，来安抚并与凶猛的大型岩鬃野猪建立羁绊。",kw={"野兽","野猪","岩鬃野猪","丹莫罗","格瑞夫","猎人","卡拉诺斯","驯服","驯兽棒"},ang={["class:Hunter"]="这个任务标志着新手神枪手向真正的兽王猎人迈出的决定性一步，同时也开启了解锁永久动物伙伴的试炼序列。",["race:Dwarf"]="铁炉堡的登山者崇敬那些能在丹莫罗严寒中生存的野兽；从顽强的岩鬃野猪开始，正体现了矮人对坚毅和韧性的推崇。"},sec={{t="猎人的伙伴",b="在此之前，矮人登山者和追踪者主要依靠枪械、陷阱和野外求生本能。然而，猎人真正的灵魂在于与野生猛兽建立终身的伙伴关系。常驻于卡拉诺斯雷酒酿制厂外的格瑞夫，负责监督这一成年仪式。格瑞夫并没有要求新手永久束缚他们遇到的第一只野兽，而是指导他们先测试自己对付丹莫罗几种原生野兽时的耐心与决心。"},{t="岩鬃野猪",b="第一个试炼要求追踪者对付一只大型岩鬃野猪，这种皮糙肉厚的野猪漫步在丹莫罗白雪皑皑的山脚下。它们覆盖着刚毛，肉体坚韧，性格顽固且好斗，是测试意志力的绝佳初始目标。猎人必须挥舞格瑞夫提供的附魔驯兽棒，抵挡野猪的冲锋，并平息它的凶性，直到它服从命令为止。"}},faq={{q="是谁提供了这项试炼？",a="该试炼由格瑞夫提供，他是一位资深的矮人猎人训练师，位于卡拉诺斯的雷酒酿制厂外。",al={"任务发放者","谁开启驯服野兽","格瑞夫位置"}},{q="为什么我首先要驯服大型岩鬃野猪？",a="大型岩鬃野猪在丹莫罗的雪岭中随处可见，它们身体强壮且顽固。制服这样一种耐寒、皮厚的生物，是学习如何以冷静的权威来驾驭凶猛野兽的基础练习。",al={"为什么选择岩鬃野猪","我该驯服什么野兽","驯服野猪"}},{q="我能永远拥有这只野猪吗？",a="不能。这项试炼纯粹是练习。用驯兽棒建立的羁绊是暂时的，让你在归还驯兽棒并尝试其他物种之前，体验指挥野兽的感觉。",al={"这只野猪是永久的吗","保留岩鬃野猪","我能留着这只宠物吗"}},{q="我在哪里可以找到大型岩鬃野猪？",a="大型岩鬃野猪广泛分布在卡拉诺斯周边的开阔雪原和松树林，以及丹莫罗的冻土坡地中。",al={"野猪位置","大型岩鬃野猪在哪里","大型岩鬃野猪刷新点"}},{q="驯服岩鬃野猪之后该做什么？",a="回到格瑞夫处完成这一最初的课程，便会直接进行第二个试炼，你需要驯服一只雪豹。",al={"下一个试炼","在这个任务之后做什么","猎人后续任务链"}},{q="驯兽棒是如何工作的？",a="驯兽棒是猎人训练师提供的一种附魔工具，旨在帮助新手引导他们的意志并安抚野兽的本能，而无需进行高深的魔法训练或拥有终身的驭兽经验。",al={"驯兽棒背景","什么是驯兽棒","我该如何驯服"}}},fx={["49cdd252"]={q="为什么格瑞夫要你驯服一只野兽？",a="格瑞夫·野心正在训练你掌握成为真正矮人猎人的基本功。在他看来，学会与野兽伙伴建立羁绊并指挥它，与保养武器同样重要。他认为，学习驯服野兽的正当方式是在野外亲身实践，让你面对当地不同种类的生物，检验自己的耐心和本领，然后再选择永久的伙伴。",al={"格瑞夫·野心的动机","为什么要驯服野兽","格瑞夫·野心安排训练的原因"}}},fp="16,210,20.345.0,13.318.0,22.112.0,38.179.0,35.122.0,34.113.0,38.115.0,29.192.0"}
P.entries["quest:6065"] = {n="猎人之道",s="“猎人之道”是莫高雷年轻牛头人猎人生命中至关重要的里程碑，它指引他们开始学习更进阶的野兽伙伴训练。当新手猎人们展现出基础的射击和追踪能力后，他们会收到导师的指派，前往血蹄村寻求猎人训练师雅文·刺鬃的指点。这段旅程标志着他们将开始进行驯服和结交野兽伙伴所需的精神与实践试炼。",h="“猎人之道”是莫高雷年轻牛头人猎人生命中至关重要的里程碑，它指引他们开始学习更进阶的野兽伙伴训练。当新手猎人们展现出基础的射击和追踪能力后，他们会收到导师的指派，前往血蹄村寻求猎人训练师雅文·刺鬃的指点。这段旅程标志着他...",kw={"野兽","血蹄村","纳拉其营地","猎人之道","莫高雷","宠物任务","驯服","雅文·刺鬃"},ang={["class:Hunter"]="这项任务标志着一名弓箭手或火枪手向真正的兽王转变的时刻，并迈出了获得忠诚战斗伙伴的第一步。",["faction:Horde"]="部落猎人极其依赖凶猛的边境野兽，让它们在卡利姆多严酷的荒野中充当前线防御者和追踪者。",["race:Tauren"]="对于舒哈鲁而言，学习驯服野兽是他们对自然以及大地母亲创造万物所怀的崇敬之情的精神延伸。"},sec={{t="成人礼",b="对于游牧的舒哈鲁（牛头人）来说，狩猎不仅是一项运动，更是神圣的仪式。猎人必须理解自然的平衡，尊崇平原上的灵魂，并尊重那些供养部族的动物。当年轻的猎人在野外生存和弓箭或枪械的使用上证明了自己的能力，长者们便会认可他们已经做好了超越单纯追踪的准备。前往寻求经验丰富的导师指引，标志着牛头人文化中真正成年人的门槛。"},{t="通往血蹄村之路",b="这条路引领着新手们穿越莫高雷辽阔的草地，来到石牛湖畔的中央集散地——血蹄村。在那里等待他们的是雅文·刺鬃，一位对当地动物习性了如指掌的资深猎人。与刺鬃交谈绝非仅仅是走过场；它象征着猎人已经准备好承担艰巨的野兽驯服试炼，学习如何与掠食者沟通，而不仅仅是猎杀它们。"}},faq={{q="“猎人之道”的目的是什么？",a="这项任务是正式邀请新手牛头人猎人开启他们的驯兽试炼。它指引猎人前往血蹄村与雅文·刺鬃交谈，由他来监督与动物伙伴建立联系所需的仪式。",al={"为什么要接这个任务","猎人之道的目标","猎人宠物任务起始"}},{q="谁会指派这项任务给你？",a="当有志向的猎人获得足够的经验并掌握了基础的生存与射击技巧后，这项任务会由牛头人猎人训练师（例如雷霆崖的卡尔·雷角）提供。",al={"谁提供猎人之道","猎人训练师任务"}},{q="雅文·刺鬃是谁？",a="雅文·刺鬃是一位受人尊敬的牛头人猎人训练师，居住在血蹄村。他肩负着教导年轻猎人如何接近、安抚并驯服莫高雷荒野野兽的危险技艺的职责。",al={"谁是刺鬃","雅文·刺鬃的作用"}},{q="完成这项任务后会发生什么？",a="在向雅文·刺鬃报到后，他会开始一系列“驯服野兽”的试炼。这些任务要求猎人携带驯兽棒进入野外，在获得训练永久伙伴的权利之前，先安抚几只当地的生物。",al={"接下来是什么","猎人之道后续任务"}},{q="为什么牛头人猎人要与野兽建立联系，而不只是狩猎它们？",a="在牛头人的传统中，野兽是大地母亲的同胞灵魂。结伴的动物并非仆从，而是伙伴和狩猎搭档，体现了双方在平原上共同生存的相互尊重。",al={"牛头人宠物背景故事","牛头人为何驯服宠物"}},{q="其他种族的猎人可以接取这个特定的任务吗？",a="这个版本的任务是专门为在莫高雷受训的牛头人猎人量身定制的。其他的部落种族，如兽人和巨魔，会在他们各自的家园领地，如杜隆塔尔，收到相应的训练指引。",al={"这是牛头人专属吗","兽人可以做牛头人的猎人之道吗"}}},fp="17,183,17.365.0,29.299.0,41.203.0,28.158.0,21.148.0,41.210.0,68.182.0,52.170.0"}
P.entries["quest:6068"] = {n="猎人之道",s="“猎人之道”是一项指引年轻兽人和巨魔猎人前往剃刀岭的成年礼。在猎人大师索塔尔的指导下，初出茅庐的追踪者们将学习驾驭野生猛兽这一至关重要的本领。",h="“猎人之道”是一项指引年轻兽人和巨魔猎人前往剃刀岭的成年礼。在猎人大师索塔尔的指导下，初出茅庐的追踪者们将学习驾驭野生猛兽这一至关重要的本领。",kw={"杜隆塔尔","猎人训练师","猎人之道","宠物任务","剃刀岭","驯服野兽","索塔尔"},ang={["class:Hunter"]="这次召唤标志着你旅途中最关键的转折点：从一名孤军奋战的神射手转变为真正的野兽大师。",["faction:Horde"]="部落依靠其斥候和追踪者来驯服地区的捕食者，将杜隆塔尔严酷的生态环境转化为一种资产。",["race:Orc"]="对于兽人来说，与凶猛的同伴并肩作战，呼应着追溯至德拉诺狼骑兵的古老传统。",["race:Troll"]="暗矛猎人视驯服当地的迅猛龙和野猪为在杜隆塔尔险恶荒野中站稳脚跟的关键。"},sec={{t="猎人的觉醒",b="在此之前，杜隆塔尔的猎人学徒只能依靠自己的弓箭和智慧。在红土峡谷和严酷的灌木丛中追踪猎物可以磨练耐心，但若想在部落中成为真正的大师，就必须与这片土地上未被驯服的野兽建立羁绊。职业训练师在认定学生拥有足够的资格后，便会指引他们直接前往剃刀岭。"},{t="剃刀岭的大师",b="在剃刀岭等待着的是索塔尔，一位精通杜隆塔尔野生生物知识的资深猎人。索塔尔担任导师，负责指导新手进行这项危险的仪式：在不摧毁野兽精神的前提下将其制服。见到他，就是你迈向与忠诚伙伴一同行走于荒野之路的第一步。"}},faq={{q="“猎人之道”的目的是什么？",a="这是一项入门级的召唤任务，旨在指引兽人和巨魔猎人前往剃刀岭，以便他们开始野兽驯服训练。",al={"为何要进行猎人之道","猎人之道任务目的","这个任务有什么作用"}},{q="索塔尔是谁？",a="索塔尔是位于剃刀岭的一位经验丰富的猎人，他负责监督年轻的部落追踪者完成与野生猛兽建立羁绊并对其进行指挥所需的试炼。",al={"索塔尔是谁","谁是索塔尔","索塔尔 剃刀岭"}},{q="为什么年轻的猎人不能立即驯服宠物？",a="控制危险的捕食者需要深厚的纪律、耐心和专业的驯服技巧。在猎人展示出基本的生存技能之前，尝试束缚野兽只会导致被野兽撕碎或死亡。",al={"为什么1级不能带宠物","为什么猎人必须等待才能获得宠物","猎人何时获得宠物"}},{q="哪些种族需要进行这项特殊的试炼？",a="这个版本的试炼专门针对在杜隆塔尔成年的兽人和暗矛巨魔，而牛头人猎人则是在莫高雷进行类似的试炼。",al={"谁会接到这个任务","这是兽人和巨魔专有的吗","哪些种族进行此试炼"}},{q="向索塔尔报到后会发生什么？",a="索塔尔会立即指派猎人去追踪并制服杜隆塔尔各地的土生捕食者，以此证明他们的驯服能力。",al={"接下来是什么","猎人之道之后","索塔尔之后的下一个任务"}},{q="这项训练在哪里进行？",a="试炼的核心区域是剃刀岭，这是杜隆塔尔中部的主要定居点，位于试炼谷和奥格瑞玛之间。",al={"剃刀岭在哪里","索塔尔位置","去哪里"}}},fp="17,129,20.299.0,24.193.0,41.82.0,14.111.0,46.158.0,42.110.0,39.139.0,36.119.0"}
P.entries["quest:6069"] = {n="猎人之道",s="剃刀岭的索塔尔可以指引你获得一位野兽伙伴。你被派去与他交谈。",h="剃刀岭的索塔尔可以指引你获得一位野兽伙伴。你被派去与他交谈。",kw={"野兽","伙伴","猎人","hunter's path","宠物","剃刀岭","索塔尔"},ang={["class:Hunter"]="作为一名猎人，你被认为已经有足够的本领驾驭一头野兽，并将它训练成自己的伙伴。"},sec={{t="野兽伙伴",b="一位训练师看出你在驾驭野兽方面颇有潜力，便派你去剃刀岭找索塔尔。他可以指引你获得属于自己的宠物。"}},faq={{q="我该与谁交谈？",a="与剃刀岭的索塔尔交谈。",al={"找谁交谈","去哪里","索塔尔任务"}},{q="索塔尔能帮我做什么？",a="索塔尔可以指引你获得属于自己的宠物。",al={"索塔尔做什么","获得宠物","猎人宠物"}},{q="为什么派我去找索塔尔？",a="一位训练师认为，你已经有足够的本领驾驭一头野兽，并将它训练成伙伴。",al={"为什么找索塔尔","有什么用","猎人之路"}}},fp="17,100,17.138.0,24.32.0,29.54.0,30.85.0"}
P.entries["quest:607"] = {n="向马克基雷回报",s="在被内脏吓坏之后，“病鬼”菲利普递给你一个钱袋，让你带给“海狼”马克基雷。菲利普发誓说这笔债务一直都打算偿还，并补充说没必要动粗。",h="在被内脏吓坏之后，“病鬼”菲利普递给你一个钱袋，让你带给“海狼”马克基雷。菲利普发誓说这笔债务一直都打算偿还，并补充说没必要动粗。",kw={"债务","马克基雷","海狼","病鬼菲利普","荆棘谷"},sec={{t="病鬼的恳求",b="菲利普把一袋偿还给海狼的钱塞给你。菲利普要你转告马克基雷，这笔债务一直都打算偿还，他对此发誓。菲利普将其归咎于喝醉了酒迷了路，并说马克基雷会理解的，没必要动粗。"},{t="海狼听故事",b="马克基雷轻声笑了笑，问你给菲利普看内脏的时候，他抖得有多厉害。马克基雷补充说菲利普这人太好懂了，跟他打牌，赢起来毫不费力。"}},faq={{q="是谁给了你钱袋？",a="“病鬼”菲利普给了你这个给海狼马克基雷的钱袋。",al={"谁给的返回马克基雷任务","我在哪里开始返回马克基雷任务"}},{q="菲利普为没付钱找了什么借口？",a="菲利普将其归咎于喝醉了酒迷了路，并誓言说这笔债务一直都是要偿还的。",al={"为什么病鬼没付钱","菲利普的借口","为什么病鬼菲利普迟到了"}},{q="这步任务之前发生了什么？",a="这是继“吓唬病鬼”之后的后续，在那个任务里，马克基雷让你用内脏去吓唬菲利普。",al={"返回马克基雷之前是什么任务","前置任务"}}},fp="19,139,12.248.0,23.205.1,24.69.0,46.99.0,27.79.0"}
P.entries["quest:6074"] = {n="猎人之道",s="“猎人之道”是丹莫罗的矮人猎人新手在掌握了基本的追踪和射击技巧后所要经历的成年仪式。当地训练师会指引他们的学徒去找卡拉诺斯的格瑞夫，开始学习驯服野生动物并使其成为忠实伙伴的技艺。",h="“猎人之道”是丹莫罗的矮人猎人新手在掌握了基本的追踪和射击技巧后所要经历的成年仪式。当地训练师会指引他们的学徒去找卡拉诺斯的格瑞夫，开始学习驯服野生动物并使其成为忠实伙伴的技艺。",kw={"丹莫罗","格瑞夫","猎人","卡拉诺斯","奥尔明·燃须","宠物任务","驯服","提斯坦·影石"},ang={["class:Hunter"]="这个任务标志着从孤独的追踪者向能够驾驭野生掠食者的真正驯兽师的决定性转变。",["race:Dwarf"]="长期以来，矮人登山家一直将熊和野猪作为他们穿越丹莫罗雪峰时值得信赖的侦察伙伴。"},sec={{t="猎人的真正使命",b="在掌握驯兽之术前，猎人只能独自走在丹莫罗的雪山上，依靠斧头、步枪或弓箭生存。像奥尔明·燃须和提斯坦·影石这样的训练师会密切观察他们的学员，直到他们表现出足以在不杀死野兽的前提下直面凶猛生物的沉稳。一旦新手表现出足够的纪律性，他们就会被派往山下的卡拉诺斯。"},{t="向格瑞夫报到",b="在卡拉诺斯，格瑞夫负责监督矮人猎人训练的最终试炼。驯服野兽被认为比为了肉食或毛皮而猎杀野兽要困难得多；它需要耐心、耐力，以及与山中野生捕食者之间直觉性的联结。格瑞夫是这些试炼的引路人，为猎人进行磨练意志的准备，以应对丹莫罗最凶猛的野生动物。"}},faq={{q="这个任务的目的是什么？",a="它是正式的召唤，将成熟的猎人派往卡拉诺斯，在格瑞夫的指导下开始他们的宠物驯服试炼。",al={"为什么要完成这个任务","什么是猎人之道","猎人宠物任务起始"}},{q="谁指引我踏上这条道路？",a="猎人训练师——包括铁炉堡武器大厅的奥尔明·燃须、提斯坦·影石以及恩瑞斯·锐矛——会指引他们的学员接受这项任务。",al={"任务发布者","谁给予猎人之道任务","在哪里接取任务"}},{q="在哪里可以找到格瑞夫？",a="格瑞夫就驻扎在卡拉诺斯的雷酒酿制厂外，位于丹莫罗的雪谷之中。",al={"格瑞夫的位置","格瑞夫在哪里","卡拉诺斯猎人训练师"}},{q="为什么猎人需要训练师来驯服野兽？",a="驯服野兽需要专门的技术和驯兽棒，以便与掠食性生物沟通，而不会引发不死不休的战斗。格瑞夫教授的正是这些传统技艺。",al={"为什么需要驯服训练","宠物驯服的背景知识","为什么我还不能驯服野兽"}},{q="向格瑞夫报到后会发生什么？",a="格瑞夫会立即考验你的勇气，派你带着驯兽棒进入荒野，去制服几种丹莫罗特有的野兽。",al={"下一个任务","猎人之道之后是什么","后续任务链"}},{q="任何猎人都能接取这个特殊任务吗？",a="这个特别的召唤专为在丹莫罗活动的矮人猎人量身定制，指引他们前往卡拉诺斯的当地训练师处。",al={"这是矮人专属吗","暗夜精灵可以做这个吗","种族限制"}}},fx={["5e8bda0f"]={q="猎人训练师为什么派你去找格瑞夫？",a="你的训练师认为，你已经具备与野兽沟通并驾驭它们所需的基本本领。他们让你前往卡拉诺斯寻找格瑞夫，接受专门的训练，而非继续常规的武艺指导。在他们看来，掌握与野兽结伴的技艺，是你成长为真正猎人所必经的下一个重要阶段。",al={"为什么派我去找格瑞夫","猎人训练师的动机","为什么去找格瑞夫"}}},fp="17,143,23.329.0,27.347.0,34.77.0,26.159.0,32.98.0,45.156.0,47.164.0,40.84.0"}
P.entries["quest:608"] = {n="血帆海盗",s="随着血帆海盗准备发起进攻，舰队指挥官卡拉·海角决定不派遣他的整个舰队进行反击。相反，他指挥一支冒险者小队潜入登陆地点，在海盗发动攻击前除掉他们的最高领导层。",h="随着血帆海盗准备发起进攻，舰队指挥官卡拉·海角决定不派遣他的整个舰队进行反击。相反，他指挥一支冒险者小队潜入登陆地点，在海盗发动攻击前除掉他们的最高领导层。",kw={"黑水","血帆","藏宝海湾","菲拉隆","基尔霍尔","海盗","海角","斯提尔沃特"},sec={{t="斩首海盗舰队",b="在获悉了海盗的入侵计划后，舰队指挥官卡拉·海角拒绝坐等敌人集结兵力发起进攻。海角嘲讽了舰队指挥官菲拉隆的航海技术，旨在通过除掉敌方指挥官来迅速消除威胁。他没有冒着进行全面海军交战的风险，而是直接派遣一支打击小队前往菲拉隆的登陆营地，斩杀菲拉隆以及斯提尔沃特船长和基尔霍尔船长，确保海盗部队因群龙无首而土崩瓦解。"}},faq={{q="是谁下令对血帆海盗领导层进行打击的？",a="藏宝海湾的舰队指挥官卡拉·海角指挥了这次突袭，意在敌方舰队发动攻击前将其瓦解。",al={"谁发布血帆海盗任务","血帆海盗任务发布者","谁派你去对付菲拉隆"}},{q="需要消灭哪些海盗指挥官？",a="目标是领导血帆海盗部队的舰队指挥官菲拉隆、斯提尔沃特船长和基尔霍尔船长。",al={"血帆海盗的目标","需要击杀的血帆指挥官","血帆的首领是谁"}},{q="为什么舰队指挥官卡拉·海角派遣冒险者而不是他的船只？",a="海角认为一支有能力的冒险者小队可以突袭登陆营地并暗杀敌方军官，从而导致敌方舰队在不危及他自身船只的情况下瓦解。",al={"为什么派冒险者去对付菲拉隆","为什么不派黑水舰队","海角的计划"}},{q="这次冲突在与血帆海盗的更广泛对抗中处于什么位置？",a="这场对抗发生在荆棘谷血帆海盗调查的早期阶段，发现了海盗的书面攻击计划之后。",al={"之前的血帆任务","这个任务之前是什么任务","血帆任务链顺序"}}},fp="24,214,29.399.0,50.110.0,49.113.0,68.147.0,85.151.0"}
P.entries["quest:6081"] = {n="训练野兽",s="训练野兽是杜隆塔尔年轻兽人和巨魔猎人的最终成人礼。在证明了自己能够驾驭平原上的野兽后，猎人们会被派往剃刀岭，前往奥格瑞玛拜师于资深猎人奥玛克。完成这段旅程将教会新手如何照料、喂养他们的终生动物伙伴，并磨练它们的技能。",h="训练野兽是杜隆塔尔年轻兽人和巨魔猎人的最终成人礼。在证明了自己能够驾驭平原上的野兽后，猎人们会被派往剃刀岭，前往奥格瑞玛拜师于资深猎人奥玛克。完成这段旅程将教会新手如何照料、喂养他们的终生动物伙伴，并磨练它们的技能。",kw={"杜隆塔尔","猎人宠物","奥格瑞玛","奥玛克","剃刀岭","索塔尔","训练野兽","荣誉谷"},ang={["class:Hunter"]="这个任务标志着你的宠物成为了一个永久的、可靠的盟友，而不再是一个短暂的召唤物，它解锁了“喂养宠物”和“复活宠物”这些至关重要的艺术。",["faction:Horde"]="部落依靠其斥候和野兽来保卫杜隆塔尔和贫瘠之地脆弱的边界，抵御半人马、野猪人和联盟的入侵。",["race:Orc"]="兽人将与狩猎伙伴的羁绊视为一种军事荣誉和职责，这是一种在杜隆塔尔严酷的前线战场上经过考验的伙伴关系。",["race:Troll"]="对于在卡利姆多开拓新家园的暗矛巨魔来说，学习与杜隆塔尔的野蛮生物交流，对于在陌生的土地上侦察和生存至关重要。"},sec={{t="荒野之外的旅程",b="在杜隆塔尔干旱的峡谷中，掌握弓箭并能在严酷的环境下生存，仅仅是猎人职责的一半。在通过驯服杜隆塔尔凶猛的野猪、食腐蟹和装甲蝎虫证明了自己的韧性后，年轻的猎人们便做好了承担真正责任的准备。驻扎在剃刀岭的索塔尔会指引他们穿过红土峡谷，直接前往奥格瑞玛的防御要塞。"},{t="荣誉谷",b="在这座繁华的首府内，渴望成为驯兽大师的猎人们必须前往荣誉谷，那是一片战士精神与资深猎人磨练技艺的飞地。奥玛克就居住在那里，他是部落最受尊敬的大师级猎人之一。奥玛克能够透过年轻猎人的青涩，洞察他们是否拥有不仅仅是驾驭野兽，还能在饥荒、战斗和失落中支撑并呵护它们的耐心。"},{t="与荒野建立羁绊",b="通过武力获得的野兽，在猎人与伙伴之间达成默契之前依然是野性的。奥玛克传授了维持这种羁绊所需的神圣传统：了解哪些食物能够滋养每种生物的灵魂，学习传授它们致命技巧所需的纪律，以及在野兽因公殉职时将其复活所需的精神专注。"}},faq={{q="谁发布了训练野兽这个任务？",a="当你成功制服了杜隆塔尔各地的全部三只测试生物后，位于剃刀岭军营外的猎人训练师索塔尔会提供这项任务。",al={"任务发布者","谁提供 训练野兽","在哪里开始 训练野兽"}},{q="我在哪里可以找到奥玛克？",a="奥玛克居住在奥格瑞玛主城的东区，即荣誉谷，与其他资深猎人和战士导师在一起。",al={"奥玛克位置","寻找奥玛克","奥玛克在哪里"}},{q="奥玛克会传授什么技能？",a="奥玛克会教你如何通过主动和被动技能来训练你的伙伴，如何喂养宠物以保持其忠诚和满足，以及如果它在战斗中死亡如何复活它。",al={"我能学到什么","任务奖励技能","猎人宠物技能"}},{q="为什么兽人和巨魔猎人必须为此前往奥格瑞玛？",a="像索塔尔这样的当地训练师可以传授基本的荒野生存技能，但进阶的野兽控制知识是由部落的资深斥候和像奥玛克这样受人尊敬的追踪者在主城中保留下来的。",al={"为什么要前往奥格瑞玛","为什么是奥格瑞玛","访问荣誉谷"}},{q="其他部落种族会进行这个特定的任务吗？",a="不。这个特定的仪式是专为在杜隆塔尔起步的兽人和巨魔猎人设计的。牛头人猎人会在莫高雷进行一项平行的仪式，由他们自己的部落大师指导。",al={"牛头人可以做这个吗","这是兽人专属吗","亡灵猎人"}},{q="如果猎人忽略了完成这次训练会怎样？",a="如果不完成这项指导，猎人将无法喂养、妥善训练或复活他们的伙伴，这会导致捕获的野兽变得不快乐、虚弱，并最终可能会抛弃他们。",al={"我必须做这个吗","我可以跳过 训练野兽 吗"}}},fp="18,266,31.396.0,19.306.0,21.311.0,40.141.0,32.112.0,42.150.0,62.182.0,48.149.0,60.166.0"}
P.entries["quest:6082"] = {n="驯服野兽",s="这个任务标志着年轻的部落猎人在杜隆塔尔所经历的基本试炼的最后一环。在剃刀岭资深猎人索塔尔的指导下，渴望成为追踪者的猎人必须去对抗并驯服一只危险的装甲蝎。征服这只装甲掠食者，证明了其驾驭野兽的能力，并能永久解锁驯服、召唤和解散忠实伙伴的技能。",h="这个任务标志着年轻的部落猎人在杜隆塔尔所经历的基本试炼的最后一环。在剃刀岭资深猎人索塔尔的指导下，渴望成为追踪者的猎人必须去对抗并驯服一只危险的装甲蝎。征服这只装甲掠食者，证明了其驾驭野兽的能力，并能永久解锁驯服、召唤和...",kw={"装甲蝎","杜隆塔尔","猎人试炼","宠物任务","剃刀岭","驯服野兽","驯兽棒","索塔尔"},ang={["class:Hunter"]="这次成人礼是猎人早期旅程中的决定性里程碑，赋予了永久使用驯服、召唤和指挥动物伙伴的核心技术的权限。",["faction:Horde"]="杜隆塔尔的兽人和巨魔后辈必须在贫瘠之地的最凶残掠食者威胁下生存下来，才能赢得他们作为部落真正的斥候和供养者的地位。",["race:Orc"]="制服杜隆塔尔的蝎子体现了兽人的哲学，即通过坚韧的意志和严明的纪律来克服恶劣的环境。",["race:Troll"]="暗矛猎人利用敏锐的直觉和与荒野之灵的深层联系，去安抚那些会置他人于死地的毒性掠食者。"},sec={{t="最后的试炼",b="在准许猎人带着忠实的动物伙伴在卡利姆多漫游之前，他们必须证明自己有能力驾驭杜隆塔尔最凶猛的野生动物。剃刀岭的猎人训练师索塔尔会派遣学员使用一支附魔的驯兽棒去制服三种不同的生物。在测试过对付恐鬃野猪和迅捷滩行蟹的身手后，猎人们还需要面对装甲蝎——一种毒性强烈、外壳坚硬、兼具韧性与致命速度的掠食者。"},{t="与荒野结缘",b="制服装甲蝎并非单纯的杀戮，而是在遭受猛烈攻击时展现专注与统治力的表现。索塔尔敦促猎人们效仿野兽那种迅捷而自信的打击方式。成功安抚这只毒性蛛形纲动物并返回剃刀岭，证明了猎人具备维持控制所需的冷静意志。归还驯兽棒后，索塔尔会传授荒野的本能技巧，让猎人能够寻找并绑定属于自己的永久伙伴。"}},faq={{q="我在这个试炼中需要驯服什么生物？",a="你必须去寻找在杜隆塔尔赤色干旱崖壁间游荡的装甲蝎，并使用索塔尔的驯兽棒来安抚和控制它。",al={"要驯服什么野兽","目标野兽","蝎子任务"}},{q="任务完成后，我可以保留那只装甲蝎吗？",a="不能。试炼中驯服的装甲蝎是临时的，在你归还训练棒后它就会消失。然而，完成这项任务会让你习得驯服任何你想要的野生野兽的永久能力。",al={"保留蝎子","我可以保留宠物吗","永久蝎子"}},{q="谁发起了这次成人礼试炼？",a="索塔尔，位于杜隆塔尔中部剃刀岭的猎人训练师，负责监督年轻兽人和巨魔猎人的这次成人礼试炼。",al={"任务发布者","谁发布了驯服野兽任务","索塔尔位置"}},{q="为什么索塔尔特别要求猎人驯服装甲蝎？",a="索塔尔认为装甲蝎因其自信、迅捷的打击和天生的韧性，是猎人效仿的理想对象。征服这样危险的掠食者证明了猎人已经做好准备，去驾驭荒野中的任何野兽。",al={"为什么是蝎子","蝎子的目的"}},{q="完成任务后能学到什么技能？",a="完成这项试炼将赋予经验丰富的兽王猎人最基础的能力：驯服野兽、召唤宠物和解散宠物。",al={"奖励","我能获得什么法术","解锁驯服技能"}},{q="这次试炼之后是什么？",a="一旦你学会了如何驯服和召唤自己的伙伴，索塔尔就会指导你进行宠物训练，并派遣你去完成后续任务“驯服野兽”，以掌握喂养和指挥盟友的技巧。",al={"下一个任务","接下来做什么","驯服三个目标之后"}}},fp="16,213,15.404.0,21.393.0,47.100.0,63.182.0,35.93.0,69.160.0,52.48.0,28.149.0"}
P.entries["quest:6083"] = {n="驯服野兽",s="这是年轻猎人在杜隆塔尔进行的第二项掌握试炼，由剃刀岭的训练师索塔尔指导。有抱负的兽人和巨魔猎人会被派往回音群岛附近的海岸线，去平息一只冲浪蟹，将他们的羁绊从陆地野兽扩展到沿海野生生物。",h="这是年轻猎人在杜隆塔尔进行的第二项掌握试炼，由剃刀岭的训练师索塔尔指导。有抱负的兽人和巨魔猎人会被派往回音群岛附近的海岸线，去平息一只冲浪蟹，将他们的羁绊从陆地野兽扩展到沿海野生生物。",kw={"杜隆塔尔","回音群岛","宠物驯服","剃刀岭","森金村","冲浪蟹","驯兽棒","索塔尔"},ang={["class:Hunter"]="这项试炼灌输了指挥防御型野兽所需的基本准则，展示了野兽的天然护甲和坚韧如何与远程射手相辅相成。",["race:Orc"]="对于在杜隆塔尔开辟永久家园的兽人来说，制服海岸线耐寒的动物群加强了他们对这片崎岖土地的掌控。",["race:Troll"]="暗矛巨魔对回音群岛和森金村附近的水域非常熟悉，这使得这项试炼成为他们与其沿海避难所中熟悉的野生动物的一次邂逅。"},sec={{t="与海岸结缘",b="在成功驯服了一只凶猛的杂斑野猪后，初出茅庐的猎人会接到索塔尔的任务，将注意力转向大海。杜隆塔尔恶劣的环境包括锯齿状的海岸和充满装甲甲壳类动物的浅滩。面对冲浪蟹需要耐心和坚韧，因为这些装甲蟹会抵御对其沿海领地的入侵。"},{t="意志的延伸",b="索塔尔教导说，猎人驯服的任何野兽都必须成为其自身力量的延伸。通过使用驯兽棒制服像冲浪蟹这样的水生生物，猎人学会了在不同的性格和环境下调整自己的统御气场，证明他们已经为获得永久同伴做好了准备。"}},faq={{q="哪里可以找到冲浪蟹？",a="冲浪蟹在杜隆塔尔的东海岸疾行，具体来说是在森金村对面的浅滩，靠近通往回音群岛的水域。",al={"冲浪蟹位置","哪里有冲浪蟹","螃蟹位置"}},{q="驯服冲浪蟹的目的是什么？",a="索塔尔指定驯服冲浪蟹是为了教导猎人如何指挥多样的野兽。学会驯服一种带护甲的水生生物可以拓宽猎人的掌控范围，证明他们能像掌握陆地动物一样轻松地掌握水生动物。",al={"为什么要驯服螃蟹","冲浪蟹任务目的"}},{q="我可以永久保留这只冲浪蟹吗？",a="不能。在这些最初试炼中驯服的野兽只是通过索塔尔的驯兽棒的魔法所制服的临时练习对象。只有完成整个试炼系列后，你才能学会永久的驯服技能。",al={"我能留下这只螃蟹吗","冲浪蟹是永久的吗"}},{q="谁提供这个任务？",a="索塔尔，位于剃刀岭的猎人训练师，在你证明了自己有能力驯服一只凶猛的杂斑野猪后提供这项试炼。",al={"任务提供者","谁开启野兽之驯2"}},{q="驯服冲浪蟹之后该做什么？",a="将驯兽棒归还给索塔尔后，他会用第三项也是最后一项试炼来考验你，让你追踪并驯服一只装甲蝎，然后才会教你永久的野兽控制技能。",al={"下一个任务","任务链下一步是什么"}},{q="为什么要用驯兽棒而不是自然技能？",a="新手猎人尚未培养出永久羁绊野生野兽所需的内在精神权威。驯兽棒充当了媒介，让初学者在学习真正的技巧之前，可以安全地练习引导他们的意志。",al={"为什么要用驯兽棒","什么是驯兽棒"}}},fp="16,254,22.266.0,21.257.0,30.153.0,45.211.0,39.191.0,21.112.0,41.158.0,47.200.0"}
P.entries["quest:6084"] = {n="驯服野兽",s="这项任务是卡拉诺斯的格瑞夫交给矮人猎人试炼的第二项。在学会了如何应付峭壁野猪那粗犷的生命力后，年轻的猎人将接受新的挑战，去驯服一种更为迅捷致命的本土生物——雪豹。",h="这项任务是卡拉诺斯的格瑞夫交给矮人猎人试炼的第二项。在学会了如何应付峭壁野猪那粗犷的生命力后，年轻的猎人将接受新的挑战，去驯服一种更为迅捷致命的本土生物——雪豹。",kw={"丹莫罗","格瑞夫","猎人任务","卡拉诺斯","雪豹","驯兽棒","驯服野兽"},ang={["class:Hunter"]="这一试炼向矮人猎人新手展示了高耐力宠物（如野猪）与迅捷、极具攻击性的伤害输出宠物（如猫科动物）之间的差异。",["race:Dwarf"]="卡兹莫丹的登山者们长期以来一直与雪豹共享丹莫罗的冰冻山峰，并敬畏它们隐秘且致命的狩猎本领。"},sec={{t="技巧课",b="如果说峭壁野猪教会了登山者如何承受猛烈的攻击和吸收伤害，那么格瑞夫强调，一名大师级猎人必须理解不同的战斗风格。他将学生指向丹莫罗的东南方，那里徘徊着雪豹。格瑞夫将这些优雅的捕食者比作一把做工精良的步枪：外表引人注目，却在它们那纯净的白色皮毛下蕴藏着毁灭性的力量。"},{t="掌握驯兽棒",b="猎人必须使用附魔的驯兽棒去面对一只野生的雪豹，并将其狩猎本能转变为伙伴关系。雪豹考验的是敏捷、速度和敏锐的反应，而非纯粹的耐力。驯服这样一只生物证明了新手能够与那些从雪山峭壁上迅疾出击的掠食者达成和谐，这是向真正掌控荒野猛兽迈出的又一步。"}},faq={{q="这个任务的目的是什么？",a="这是矮人猎人试炼的第二阶段。猎人训练师格瑞夫要求他的学生在获得永久驯服动物伙伴的知识之前，必须先测试自己对抗不同荒野猛兽的能力。",al={"为什么要完成这个任务","矮人雪豹任务","驯兽师任务2"}},{q="我在哪里可以找到雪豹？",a="雪豹徘徊在丹莫罗卡拉诺斯东南部和南部的岩石峭壁与雪坡上。",al={"雪豹位置","丹莫罗雪豹在哪里"}},{q="为什么格瑞夫要我驯服一只雪豹？",a="格瑞夫认为猎人必须同时体验强壮的体魄和精湛的技巧。峭壁野猪依靠的是粗犷的生命力，而雪豹则教会猎人如何与迅捷、敏捷且致命的伤害输出者并肩作战。",al={"为什么选择雪豹","格瑞夫驯服雪豹的理由"}},{q="我可以永久保留这只雪豹吗？",a="不能。在这些初步试炼中驯服的野兽只是临时的训练伙伴，它们受驯兽棒的魔法所束缚。当你完成这一任务线并得到格瑞夫的认可后，你才能获得永久驯服任意野生野兽的能力。",al={"我可以保留雪豹吗","雪豹是永久的吗"}},{q="谁指派了这个试炼？",a="格瑞夫，驻扎在丹莫罗卡拉诺斯旅店外的矮人猎人训练师。",al={"谁发布的任务","任务发布者","格瑞夫的角色"}},{q="任务链的下一步是什么？",a="在展示了对雪豹的驾驭能力后，格瑞夫会派你去进行第三次，也就是最后一次驯兽试炼，去掌握冰爪熊，之后他才会正式传授你独自驯服和训练野生野兽的方法。",al={"下一个任务","雪豹之后是什么"}}},fx={baf34ad8={q="雪豹是一种什么样的野兽？",a="雪豹是丹莫罗积雪山脊上土生土长的掠食者，行动迅捷，身手敏捷。与你在第一场试炼中面对的强壮而顽固的峭壁野猪不同，这些白色大型猫科动物依靠灵巧、速度和致命的攻击捕猎。格瑞夫让你去驯服它们，是为了让你学会驾驭体质较弱却生性凶猛的狩猎伙伴，它们的战斗方式与蛮力型野兽截然不同。",al={"雪豹的背景","为什么驯服雪豹","丹莫罗的雪豹"}},["4533de88"]={q="格瑞夫为什么让我亲自驯服雪豹？",a="这是你作为年轻猎人必须经历的成长仪式，并不是格瑞夫需要你替镇上处理的杂务。驯服需要你亲自确立对野兽的主导地位，并与它们心意相通。格瑞夫早已掌握这门技艺；需要学会引导驯兽棒的魔力、抵挡掠食者冲锋的是你，以此证明你已准备好驾驭一位终身相伴的伙伴。",al={"为什么必须亲自驯服","为什么选我使用驯兽棒","格瑞夫为什么派我去"}}},fp="16,114,19.236.0,24.331.0,34.184.0,34.94.0,50.184.0,47.198.0,23.101.0,29.174.1"}
P.entries["quest:6085"] = {n="驯服野兽",s="此任务标志着矮人猎人在卡拉诺斯的格瑞夫指导下完成的基础训练的最后一项试炼。通过使用一根附魔的棍棒来制服并了解一头凶猛的冰爪熊，猎人展示了对纯粹蛮力的掌控。完成这项练习将解锁驯服、召唤和解散永久野生伙伴所需的基础能力。",h="此任务标志着矮人猎人在卡拉诺斯的格瑞夫指导下完成的基础训练的最后一项试炼。通过使用一根附魔的棍棒来制服并了解一头凶猛的冰爪熊，猎人展示了对纯粹蛮力的掌控。完成这项练习将解锁驯服、召唤和解散永久野生伙伴所需的基础能力。",kw={"丹莫罗","格瑞夫","猎人任务","冰爪熊","卡拉诺斯","宠物驯服","驯兽棒","驯服野兽"},ang={["class:Hunter"]="这个任务是让孤立的弓箭手转变为真正的宠物驯服猎人的必经之路，它解锁了驯服和召唤野兽的基本能力。",["race:Dwarf"]="熊长期以来一直是巡逻丹莫罗的矮人山地探险者的标志性伙伴，它们以与主人一样顽强的韧性而闻名。"},sec={{t="野性的力量",b="在整个丹莫罗，山地探险者和侦察兵长期以来都依靠强壮的野兽来忍受严寒的岩壁。在指导学生练习对付敏捷而狡猾的掠食者之后，猎手大师格瑞夫指派新手猎人去捕捉一头冰爪熊。这些巨大的野兽经常在卡拉诺斯东部的雪堆中徘徊，它们体现了原始的体力和顽强的耐力——这是每一位矮人猎手都必须学会控制的品质。"},{t="获得伙伴",b="使用驯兽棒进行的试炼纯粹是教育性的练习，旨在教导猎人野生本能如何回应意志与平静的意图。一旦驯兽棒使熊变得温顺，这种暂时的羁绊便完成了它的使命。将工具交还给格瑞夫即完成了正式的试炼，促使这位大师分享野兽控制的永久秘密：如何安抚任何兼容的野生生物，并在漫长的冒险生涯中召唤它。"}},faq={{q="我需要为了这个任务驯服什么动物？",a="你必须寻找一头冰爪熊，它在丹莫罗卡拉诺斯东部的冰冻山脚下徘徊。使用提供的驯兽棒可以制服这个生物，这样你就能体验到驾驭原始蛮力的感觉。",al={"哪种熊","目标动物","驯服目标"}},{q="我在交还任务后可以保留这头冰爪熊吗？",a="不可以。被驯兽棒制服的熊只是对纪律和技巧的临时测试。一旦你将驯兽棒交还给格瑞夫，野兽就会离开，而你将被授予真正驯服任何你选择的野生野兽的能力。",al={"可以保留熊吗","保留宠物","熊是永久的吗"}},{q="格瑞夫在哪里？",a="格瑞夫驻扎在丹莫罗卡拉诺斯的雷酒酿制厂外，他在那里训练初出茅庐的猎人，传授他们射击和野兽控制之道。",al={"格瑞夫位置","格瑞夫在哪里","卡拉诺斯猎人训练师"}},{q="完成这次试炼后我能学到什么技能？",a="完成这项最终试炼将教会你猎人的基础法术：驯服野兽、召唤宠物和解散宠物。这使你可以冒险进入世界，并与一个永久的伙伴建立羁绊。",al={"任务奖励","猎人习得技能","驯服野兽奖励"}},{q="完成这个任务后的下一步是什么？",a="格瑞夫会让你继续进行“训练野兽”任务，指导你学习如何喂养、培育和正确指示你的新伙伴，以便它在战斗中保持忠诚。",al={"后续任务","接下来是什么","训练野兽"}},{q="为什么格瑞夫要让猎人测试多种类型的野兽？",a="三项试炼让新手猎人接触到不同的战斗风格——敏捷、狡诈和蛮力。体验这些不同的性情，能让山地探险者为自己的狩猎风格选择最佳伙伴。",al={"为什么是三种野兽","试炼的目的","三种动物"}}},fx={d0a90924={q="冰爪熊是什么，它们为什么会出现在卡拉诺斯附近？",a="冰爪熊是丹莫罗积雪峭壁上土生土长的掠食者，体格强壮，皮毛厚实，常在卡拉诺斯以东的荒野中游荡。格瑞夫认为，它们天生的坚韧与蛮力，使它们成为成长中的猎人的理想伙伴。面对这样的野兽，你必须证明自己能在强大的蛮力面前站稳脚跟，驾驭真正强健的山地野兽，之后才能宣称已完全掌握驯兽之道。",al={"冰爪熊的背景","为什么驯服冰爪熊","丹莫罗的冰爪熊"}}},fp="16,234,24.304.0,19.321.0,45.158.0,55.220.0,32.140.0,52.123.0,50.136.0,57.176.0"}
P.entries["quest:6086"] = {n="训练野兽",s="训练野兽是丹莫罗年轻矮人猎人的最终成人礼。在掌握了安抚并驯服白雪皑皑的山脊中野生猛兽的艺术后，新手游侠们被指引前往铁炉堡的中心，学习如何维持、训练和照料终生的动物伙伴。",h="训练野兽是丹莫罗年轻矮人猎人的最终成人礼。在掌握了安抚并驯服白雪皑皑的山脊中野生猛兽的艺术后，新手游侠们被指引前往铁炉堡的中心，学习如何维持、训练和照料终生的动物伙伴。",kw={"贝莉亚·雷岩","丹莫罗","矮人猎人","格瑞夫","武器大厅","铁炉堡","宠物训练","训练野兽"},ang={["class:Hunter"]="这一里程碑解锁了猎人职业的核心定义：正确喂养、指挥和复活永久动物伙伴的能力。",["faction:Alliance"]="铁炉堡的兽王们为联盟的侦察部队做出了巨大贡献，他们依靠忠诚的荒野伙伴在严寒的山路上进行巡逻。",["race:Dwarf"]="矮人视狩猎为卡兹莫丹多山荒野的一种持久传统，将熊、野猪和山猫视为探索与防御中值得尊敬的伙伴。"},sec={{t="从荒野到熔炉",b="在证明了自己有能力对抗丹莫罗的凶猛野兽——用驯兽棒安抚大型岩鬃野猪、雪豹和强壮的冰爪熊——之后，猎人学徒们在卡拉诺斯附近的格瑞夫注视下完成了他们的试炼。然而，捕获动物的野性之心只是羁绊的一半。格瑞夫将他刚历练过的新手学员派上山路，前往铁炉堡，去寻找被称为武器大厅的军事区。"},{t="贝莉亚·雷岩的教导",b="在铁炉堡武器大厅的石拱顶下，站着矮人王国最受尊敬的野兽训练大师之一，贝莉亚·雷岩。贝莉亚传授了关键的知识，将一头野性、惊恐的野兽变成忠诚的战斗伙伴。她的教导远不止简单的命令：她向年轻的猎人展示了如何喂养宠物、传授它们新的战斗技能，甚至在它们为保卫主人而倒下时，如何从死亡边缘将它们的灵魂召唤回来。"},{t="矮人猎人的羁绊",b="矮人传统强调，驯服野兽的核心在于尊重而非征服。贝莉亚提醒每一位年轻的猎人，动物伙伴反映了它所受到的照料。如果喂养得当、受到尊重并经过适当的训练，野兽将在对抗穴居人、冰霜巨魔以及任何敢于威胁卡兹莫丹的敌人时，展现出坚定不移的忠诚。"}},faq={{q="这个任务的目的是什么？",a="这个任务标志着矮人猎人基础训练的最后一步。它将奖励你维护永久战斗宠物的核心知识，使你能够喂养它、训练它的能力、召唤它到你身边，并在它死亡时复活它。",al={"为什么要完成这个任务","训练野兽 任务目的","猎人宠物任务奖励"}},{q="谁是贝莉亚·雷岩？",a="贝莉亚·雷岩是一位受人尊敬的野兽训练大师，驻扎在铁炉堡的武器大厅。她是矮人游侠的高级教官，负责传授他们将驯服的野生动物变成终生盟友所需的纪律、饮食和命令。",al={"谁是贝莉亚","贝莉亚·雷岩背景故事","铁炉堡猎人训练师"}},{q="我在哪里可以找到贝莉亚·雷岩？",a="贝莉亚·雷岩位于铁炉堡的武器大厅内，这是该市的军事区，矮人和侏儒的战士、猎人以及圣骑士都在这里聚集和训练。",al={"贝莉亚位置","贝莉亚·雷岩在哪里","铁炉堡 武器大厅 在哪里"}},{q="矮人猎人在接受这项训练前会驯服哪些野兽？",a="在通往此任务的试炼过程中，格瑞夫通过要求年轻猎人使用附魔棒暂时安抚丹莫罗各地的大型岩鬃野猪、雪豹和冰爪熊，来考验他们。",al={"你会驯服什么野兽","矮人宠物试炼野兽","先导任务野兽"}},{q="为什么矮人猎人必须喂养他们的宠物？",a="矮人的野兽知识认为，动物伙伴是伙伴，而不是工具。忽视野兽的饥饿会导致其情绪恶化并削弱其战斗意愿，而保持良好的喂养则能确保它们在战斗中展现出凶猛的忠诚和最大的效力。",al={"为什么要喂养宠物","宠物快乐度背景知识","矮人野兽忠诚度"}},{q="谁发布了这个任务？",a="格瑞夫，那位驻扎在丹莫罗卡拉诺斯东侧路边的资深猎人训练师，会在你成功完成第三次驯服试炼后发布这个任务。",al={"谁开启 训练野兽","格瑞夫的角色","任务发布者"}}},fx={["5ee43731"]={q="格瑞夫为什么派你去铁炉堡？",a="格瑞夫指引你在丹莫罗的峭壁间完成了基础试炼，教会你驯服野兽。然而，要掌握照料、喂养和管教野兽伙伴的方法，还需要更高深的知识。格瑞夫派你前往铁炉堡，让贝莉亚·雷岩为你完成训练，确保你的宠物成为坚定的盟友，她是武器大厅中最受矮人敬重的训练大师之一。",al={"格瑞夫为什么派人去","格瑞夫的动机","猎人为什么去铁炉堡"}}},fp="18,205,26.281.0,32.371.0,25.293.0,34.191.0,28.210.0,37.154.0,67.171.0,41.195.0,21.157.0"}
P.entries["quest:6087"] = {n="驯服野兽",s="这一试炼标志着牛头人猎人驯兽艺术启蒙的第二阶段。在血蹄村猎人训练师雅文·刺鬃的指引下，新手被要求驯服迅捷而无畏的草原巡行者。",h="这一试炼标志着牛头人猎人驯兽艺术启蒙的第二阶段。在血蹄村猎人训练师雅文·刺鬃的指引下，新手被要求驯服迅捷而无畏的草原巡行者。",kw={"血蹄村","猎人试炼","莫高雷","草原巡行者","驯兽棒","驯服野兽","牛头人猎人","雅文·刺鬃"},ang={["class:Hunter"]="这次成年礼将基础的生存技巧与进攻性协作连接起来，教导你如何与快速攻击的伙伴并肩作战。",["race:Tauren"]="与那些纯粹将宠物视为工作动物的文化不同，舒哈鲁视驯兽为在大地母亲的慈爱注视下建立神圣的亲属关系。"},sec={{t="巡行者的课程",b="在成功掌握了成年陆行鸟的防御耐力后，雅文·刺鬃挑战这位年轻的猎人，要求其超越单纯的生存本能。草原巡行者代表了完全不同的狩猎哲学：无情的速度、狼群般的协作以及无畏的攻击性。驯服它需要以不间断的步调接近这只狡猾的捕食者，效仿狼本身那种果断的天性。"},{t="肌肉与肌肉的较量",b="对于牛头人来说，与野兽一同狩猎从不是关于奴役或单纯的征服。雅文·刺鬃强调，猎人和捕食者必须作为一个紧密的整体并肩作战，通过相互尊重和共同的节奏连接在一起。通过在莫高雷的广阔天空下与草原巡行者建立羁绊，猎人学会了在战斗的白热化阶段与伙伴的攻势相辅相成，并同步移动。"}},faq={{q="雅文·刺鬃要求我在这次试炼中驯服什么动物？",a="这第二堂课要求你驯服一只草原巡行者，这是一种游荡在莫高雷草海平原上的迅捷野狼。",al={"我要驯服什么野兽","下一个宠物是谁","驯服草原巡行者"}},{q="为什么牛头人猎人要学习驯服狼？",a="雅文·刺鬃教导说，草原巡行者体现了速度与无畏。通过与这样的捕食者建立羁绊，猎人能够将这些特质内化，学会如何与迅捷的狩猎伙伴无缝衔接，协同攻击。",al={"为什么要选狼","草原巡行者背景故事","为什么驯服狼"}},{q="通常能在哪里找到草原巡行者？",a="草原巡行者游荡在莫高雷中部和北部的草地平原上，经常在血蹄村周边的草原上徘徊。",al={"草原巡行者位置","草原巡行者在哪里","寻找草原巡行者"}},{q="任务完成后我可以留下这只草原巡行者吗？",a="不能。驯兽棒仅仅为了训练目的创造了一种暂时的羁绊。当你完成整个系列的试炼后，你将获得永久驯服你所选择的任何野生伙伴的能力。",al={"我可以留下这只狼吗","留下草原巡行者","这是我的永久宠物吗"}},{q="雅文·刺鬃是谁？",a="雅文·刺鬃是驻扎在血蹄村的猎人训练师。他引导年轻的牛头人完成掌握莫高雷荒野所需的精神和实践上的里程碑。",al={"雅文是谁","刺鬃背景故事","雅文血蹄"}},{q="驯服草原巡行者之后要做什么？",a="一旦雅文·刺鬃确认你已经驯服了这头野狼，他会派你去完成整个试炼链的第三项也是最后一项任务，考验你面对潜行掠翼者时的决心。",al={"下一个任务","草原巡行者之后是什么","第三个驯兽任务"}}},fp="16,125,21.257.0,16.313.0,60.94.0,46.173.0,44.121.0,53.150.0,21.154.0,44.134.0"}
P.entries["quest:6088"] = {n="驯服野兽",s="这次试炼是血蹄村的雅文·刺鬃指导下的牛头人猎手训练的最后一课。通过使用驯兽棒与一只野生迅猛龙建立羁绊，猎手证明了自己对空中生物的掌控力，并获得了大地母亲神圣的信任。完成此项任务将使你获得永久性的知识，学会驯服和指挥一位终生的伙伴。",h="这次试炼是血蹄村的雅文·刺鬃指导下的牛头人猎手训练的最后一课。通过使用驯兽棒与一只野生迅猛龙建立羁绊，猎手证明了自己对空中生物的掌控力，并获得了大地母亲神圣的信任。完成此项任务将使你获得永久性的知识，学会驯服和指挥一位终...",kw={"血蹄村","大地母亲","猎手宠物","莫高雷","迅猛龙","驯兽棒","驯服野兽","雅文·刺鬃"},ang={["class:Hunter"]="这个任务完成了基础训练链，解锁了永久的野兽驯服，标志着你从一名学徒成长为一名完全能够独立生存的荒野斥候。",["race:Tauren"]="对于舒哈鲁人来说，与一只野生野兽建立羁绊是受到大地母亲祝福的精神交流行为，在莫高雷的平原上具有深远的文化意义。"},sec={{t="天空的掌控",b="在已经征服了莫高雷草海平原上的地面掠食者后，雅文·刺鬃将你的注意力转向了广阔的天空。迅猛龙是一种凶猛、拥有锐利喙部的猛禽，以其迅猛的俯冲和威慑性的姿态而闻名。将这种野生的空中猎手驯服是对你反应能力和冷静程度的考验，它要求你在承受其利爪攻击的同时，使用附魔的驯兽棒将你的精神与它的本能调和一致。"},{t="大地母亲的馈赠",b="对于牛头人来说，狩猎和驯养动物本质上是一种精神追求，而非仅仅是征服。通过掌握大地和天空的生物，你展现了在平原上行走而又不破坏自然所需的平衡与尊重。雅文·刺鬃认可了你的成熟，收回了他临时的驯兽棒，并将召唤、解散和永久驯服你所选伙伴的持久技巧传授给你。"}},faq={{q="为什么最终试炼必须要驯服一只迅猛龙？",a="雅文·刺鬃想要测试你面对空中生物的能力。迅猛龙拥有敏捷而锐利的攻击，且具有威慑力，这证明了猎手在获得真正的独立之前，既能应对空中掠食者，也能应对地面野兽。",al={"为什么要驯服迅猛龙","驯服迅猛龙的目的","为什么是迅猛龙"}},{q="在这个任务中驯服的迅猛龙我可以留下吗？",a="不能。作为仪式训练的一部分，迅猛龙是使用雅文·刺鬃的驯兽棒暂时驯服的。一旦你完成了任务，你将获得真正的能力，可以驯服任何你想永久保留的野生野兽。",al={"迅猛龙可以留下来吗","迅猛龙是我的宠物吗","我可以留下这只鸟吗"}},{q="谁发布了这个任务，他在哪里？",a="雅文·刺鬃，位于莫高雷中部血蹄村的猎手训练师，他发布了这个任务，这是你最初野兽驯服试炼的第三步，也是最后一步。",al={"任务发布者","谁开启了这个任务","雅文·刺鬃在哪里"}},{q="我归还驯兽棒之后会发生什么？",a="雅文·刺鬃会教给你独自驯服、召唤和解散野兽的固有能力。他还将引导你前往雷霆崖，学习如何正确地训练和照顾你所选的伙伴。",al={"接下来我学什么","完成任务的奖励","这个任务之后是什么"}},{q="我在莫高雷哪里可以找到野生的迅猛龙？",a="迅猛龙在莫高雷中部的开阔草原和台地边缘游荡，经常在血蹄村外的平原上盘旋。",al={"迅猛龙位置","迅猛龙在哪里","寻找迅猛龙"}},{q="为什么宠物驯服被认为是牛头人的成人礼？",a="牛头人文化不将野兽视为工具，而是视为大地母亲的子民。学习与伙伴建立羁绊需要耐心、相互尊重和精神平衡，而不是纯粹的力量。",al={"牛头人猎手传说","猎手的精神之路","大地母亲的联系"}}},fp="16,283,18.312.0,22.371.0,50.219.0,45.157.0,48.146.0,43.190.0,40.118.0,58.164.0"}
P.entries["quest:6089"] = {n="训练野兽",s="“训练野兽”是莫高雷年轻牛头人猎人的最终成人礼。在展示了安抚平原野兽所需的精神耐心与决心后，猎人们将被派往雷霆崖，学习如何与一只终生的动物伙伴建立羁绊、喂养它并指挥它的终身纪律。",h="“训练野兽”是莫高雷年轻牛头人猎人的最终成人礼。在展示了安抚平原野兽所需的精神耐心与决心后，猎人们将被派往雷霆崖，学习如何与一只终生的动物伙伴建立羁绊、喂养它并指挥它的终身纪律。",kw={"野兽训练","浩特·雷角","猎人高地","莫高雷","牛头人猎人","雷霆崖","训练野兽","雅文·刺鬃"},ang={["class:Hunter"]="这项仪式标志着你从独自战斗转向与忠诚的伙伴并肩作战，完成了你作为荒野守护者的基础训练。",["race:Tauren"]="对于舒哈鲁而言，带着动物同伴参加战斗，肩负着神圣的守护职责，并承载着对大地母亲造物的尊重。"},sec={{t="通往大崖之路",b="在成功地针对莫高雷的危险掠食者——平原陆行鸟、草原狼和扫荡者——试炼过自己的精神后，牛头人猎人被认为已具备了传承猎人衣钵的资格。血蹄村的导师雅文·刺鬃会将这位新手托付给雷霆崖猎人高地的旅程。那里驻守着浩特·雷角，他是舒哈鲁中极具传奇色彩的人物，他对自然界的共鸣声誉仅次于他对大地母亲的虔诚。"},{t="神圣的羁绊",b="对牛头人而言，野兽并非简单的武器或奴隶；它是通过与自然世界和谐共处而获得的伙伴。浩特·雷角传授了维持这种伙伴关系所需的关键知识。猎人不仅必须学习如何引导生物的战斗本能，还要学习如何通过定期喂食来滋养它的身体、治愈它的伤口，并在它为保卫同伴而倒在平原上时唤回它的灵魂。"}},faq={{q="我该向谁交付这个任务？",a="你必须与雷霆崖猎人高地顶端的狩猎大师浩特·雷角交谈。一旦你在莫高雷驯服野兽的初步试炼完成，雅文·刺鬃就会指引你去找他。",al={"任务交付","浩特·雷角是谁","浩特在哪里"}},{q="牛头人猎人在完成此任务后能学会什么技能？",a="浩特·雷角会教你如何训练你的宠物学习新技能、如何喂养你的伙伴以保持其忠诚与满足，以及如何在宠物在战斗中阵亡时将其复活。",al={"我能获得什么能力","任务奖励技能","浩特教什么"}},{q="此任务在牛头人猎人任务链中处于什么位置？",a="这是该序列中的最后一个任务。它紧随“猎人之道”以及三部分的“驯服野兽”试炼之后，在那些试炼中，猎人需要暂时安抚平原各处的一只成年平原陆行鸟、一只草原狼和一只扫荡者。",al={"猎人任务链","莫高雷宠物任务","训练野兽系列任务"}},{q="为什么浩特·雷角在牛头人猎人中享有如此高的地位？",a="浩特一生都在对抗艾泽拉斯最凶猛的野兽来磨练自己，他能指挥多只强大的同伴，同时与大地母亲保持着深厚的精神纽带。他的智慧使他成为雷霆崖年轻舒哈鲁猎人的首席导师。",al={"浩特·雷角背景故事","浩特是谁"}},{q="猎人能在交付此任务前驯服他们的永久宠物吗？",a="你从之前的试炼中已经获得了驯服野兽的能力，但在与浩特·雷角交谈之前，你还缺乏喂养、复活所选同伴或教导其技能的知识。",al={"我现在能驯服宠物吗","我什么时候能得到宠物","我需要完成训练野兽吗"}},{q="为什么在牛头人文化中，宠物照料与大地母亲有关？",a="牛头人将所有生物视为大地母亲的孩子。猎人不是靠纯粹的意志力来征服野兽，而是订立了一份精神契约，猎人提供食物和照料，以换取动物的忠诚和保护。",al={"牛头人宠物背景故事","大地母亲的野兽"}}},fp="18,224,27.374.0,13.346.0,33.149.0,63.148.0,53.226.0,71.262.0,66.177.0,58.216.0"}
P.entries["quest:609"] = {n="讨债行动",s="身处藏宝海湾的“海狼”马克基雷需要向三位老相识追讨欠债，以结清他的账目。尽管有传言称这些人受到了诅咒和蛊惑，在古老的丛林废墟中游荡，但马克基雷不在乎他们的悲惨命运，只要求你找回他们珍贵的财物。",h="身处藏宝海湾的“海狼”马克基雷需要向三位老相识追讨欠债，以结清他的账目。尽管有传言称这些人受到了诅咒和蛊惑，在古老的丛林废墟中游荡，但马克基雷不在乎他们的悲惨命运，只要求你找回他们珍贵的财物。",kw={"藏宝海湾","十指苏克","乌鸦乔乔","畸形足玛雷·威尔金斯","阿博拉兹废墟","朱布瓦尔废墟","海狼马克基雷","荆棘谷","巫毒之债"},sec={{t="未付的账目",b="在你之前为“海狼”马克基雷完成了一些收债任务后，这位海盗手中仍然有一份未结清的欠债清单。三名特定的债务人——“畸形足”玛雷·威尔金斯、乌鸦乔乔和“十指”苏克——已经拖欠债务数月之久。马克基雷起初以为这三人只是为了逃债而离开了藏宝海湾，但后来他听说他们在丛林深处遭遇了更加诡异的命运。"},{t="废墟中的诅咒",b="有传言称这三名债务人受到了蛊惑和诅咒，导致他们徘徊在藏宝海湾东北方的古代石构建筑区域，即阿博拉兹废墟和朱布瓦尔废墟。马克基雷并不关心他们的不幸，他指示你前往废墟，找到这三个人，并收回他们身上显眼的贵重物品：乔乔的金色望远镜、苏克的巨型戒指和玛雷的畸形足。"}},faq={{q="是谁要求追讨这些债务？",a="“海狼”马克基雷在他位于藏宝海湾的据点提出了这个请求。他正在清理一份欠债名单，绝不容许这些债务就此勾销。",al={"谁给予巫毒之债任务","海狼马克基雷任务"}},{q="这三名债务人是谁？",a="这三名债务人分别是“畸形足”玛雷·威尔金斯、乌鸦乔乔和“十指”苏克。他们的欠款已经拖欠了数月。",al={"谁欠马克基雷的钱","巫毒之债的目标"}},{q="在哪里可以找到这三名债务人？",a="他们徘徊在藏宝海湾东北方的古代石构建筑中，具体来说是在阿博拉兹废墟和朱布瓦尔废墟内。",al={"债务人在哪里","阿博拉兹和朱布瓦尔在哪里"}},{q="这三个人发生了什么事？",a="据传到马克基雷耳中的消息，这三个人受到了蛊惑和诅咒，现在在丛林废墟中游荡，而不是回到港口。",al={"为什么他们被诅咒了","他们出了什么问题"}},{q="需要找回哪些特定的物品？",a="马克基雷需要三件特定的贵重物品：乔乔的金色望远镜、苏克的巨型戒指和玛雷的畸形足。",al={"马克基雷想要什么物品","巫毒之债任务物品"}},{q="在这个任务链之前还有什么任务？",a="这是继“吓唬谢基”和“回到马克基雷那里”之后的任务，你将继续协助这位海盗完成他的收债清单。",al={"巫毒之债的前置任务","上一个任务"}}},fp="11,316,15.341.0,22.321.0,37.164.0,26.149.0,37.118.0,31.124.0,38.88.0,40.110.0"}
P.entries["quest:61"] = {n="送往暴风城的货物",s="“运往暴风城”是一个联盟的运送任务，它结束了威廉·匹斯特在艾尔文森林的蜡烛生意。在从当地的狗头人害虫那里收集了大蜡烛后，冒险者将包装好的货物沿着大路带入暴风城的贸易区，交给威廉的兄弟摩根·匹斯特。",h="“运往暴风城”是一个联盟的运送任务，它结束了威廉·匹斯特在艾尔文森林的蜡烛生意。在从当地的狗头人害虫那里收集了大蜡烛后，冒险者将包装好的货物沿着大路带入暴风城的贸易区，交给威廉的兄弟摩根·匹斯特。",kw={"艾尔文森林","闪金镇","狗头人蜡烛","摩根·匹斯特","匹斯特药店","运往暴风城","贸易区","威廉·匹斯特"},ang={["faction:Alliance"]="带着物资沿着国王大道进入暴风城，对于从乡村小规模战斗转向繁华首都的年轻联盟勇士来说，是一次经典的试炼。",["profession:Herbalism"]="匹斯特家族的生意与艾尔文森林当地的试剂紧密相连，在他们的暴风城店铺停留是采集者和药剂师们熟悉的一项日常。"},sec={{t="家族生意",b="匹斯特兄弟在艾尔文森林的田园村落和暴风城繁华的大街之间维持着炼金贸易。威廉在闪金镇收集草药、试剂和原材料，而他的兄弟摩根则在首都的贸易区经营着匹斯特药店。由于威廉无法轻易离开他在狮王之傲旅店的岗位，他便委托前往城门的旅行者来负责运送工作。"},{t="从狗头人蜡烛到首都药剂",b="威廉的包裹里装着从艾尔文森林矿洞里的狗头人身上收集的大蜡烛。他和摩根在暴风城经营着一家药店，威廉说他收集这些蜡烛是为了它们的蜡。完成这批货物的运送，就把这些物资带给了贸易区的摩根。"}},faq={{q="威廉的货物里有什么？",a="这批货物里装着从艾尔文森林的狗头人身上收集的蜡烛。威廉收集它们是为了获得蜡，并将它们打包好送到匹斯特药店交给摩根。",al={"货物内容","包裹里有什么","威廉寄了什么"}},{q="我在哪里可以找到摩根·匹斯特？",a="摩根·匹斯特在匹斯特药店里工作，该药店位于暴风城的贸易区，就在穿过正门后不远的地方。",al={"摩根·匹斯特位置","摩根在哪里","找到摩根·匹斯特"}},{q="威廉和摩根·匹斯特是什么关系？",a="威廉·匹斯特和摩根·匹斯特是兄弟，他们共同经营着一家炼金企业。威廉在艾尔文森林采购材料，而摩根则在暴风城经营他们的店铺。",al={"匹斯特兄弟","谁是威廉·匹斯特的兄弟"}},{q="为什么威廉不亲自去送包裹？",a="威廉忙于经营他的生意和在闪金镇收集炼金材料。他更倾向于雇佣路过的冒险者，这些冒险者正好要向北前往首都城门。",al={"为什么威廉不去暴风城","为什么要雇佣快递员"}},{q="狗头人蜡烛真的有炼金用途吗？",a="威廉说他和他的兄弟需要这些蜡烛的蜡。任务中并没有具体描述他们在药店里是如何使用这些蜡的。",al={"为什么是狗头人蜡烛","狗头人蜡烛炼金"}},{q="交付货物后接下来要做什么？",a="这次交付结束了从收集艾尔文森林狗头人蜡烛开始的简短任务链。摩根只是支付了你的快递费用，并欢迎你在他的店里进行交易。",al={"运往暴风城之后做什么","运往暴风城后续任务"}}},fx={e0018b76={q="威廉·匹斯特为什么要送出这批货物？",a="摩根正在暴风城的兄弟药剂店里等候这批蜡烛。威廉为了获取蜡而收集了这些蜡烛，却无暇亲自跑一趟，因此请一位旅者代为运送这些物资。",al={"为何送出货物","威廉·匹斯特的动机","为何运送蜡烛"}}},fp="21,168,14.254.0,34.230.0,34.157.0,30.116.0,42.168.0,48.165.0,48.118.0,41.183.0"}
P.entries["quest:610"] = {n="帅小伙子邓肯",s="在受她父亲之托追踪到利刃凯特琳后，一位冒险者得知她的武器已经不在她手中了。她要求在进一步合作之前，必须先从一个名叫“漂亮男孩”邓肯的海盗手中找回她丢失的匕首。",h="在受她父亲之托追踪到利刃凯特琳后，一位冒险者得知她的武器已经不在她手中了。她要求在进一步合作之前，必须先从一个名叫“漂亮男孩”邓肯的海盗手中找回她丢失的匕首。",kw={"血帆海盗","藏宝海湾","利刃凯特琳","凯特琳的利刃","漂亮男孩邓肯","荆棘谷"},ang={["class:Mage"]="凯特琳明确地嘲弄奥术学者，声称她离家出走正是为了避免整日被那些古板、灰发的施法者所包围。"},sec={{t="海盗的怨恨",b="顺着安斯雷姆的钥匙的线索，直接找到了利刃凯特琳。她为了逃离与法师们为伴、整日沉浸在陈旧书籍与学术研究中的平静生活而离家出走。她无法应她父亲的要求交出匕首，因为她已经没有那把匕首了。如果有人想要拿到她的利刃，就必须先去对付那个夺走它的血帆海盗。"},{t="被窃的钢刃",b="凯特琳在“漂亮男孩”邓肯手中遭遇了一场不同寻常的失败，邓肯打晕了她并拿走了她的标志性武器。作为一个依赖随身匕首战斗的战士，她坚持在进行任何后续行动之前，必须从那个血帆海盗手中夺回那把武器。"}},faq={{q="“漂亮男孩”邓肯是谁？",a="“漂亮男孩”邓肯是活跃在藏宝海湾附近的一名血帆海盗。他在战斗中击败了利刃凯特琳，将她打晕并夺走了她的匕首。",al={"漂亮男孩邓肯","邓肯是谁","邓肯海盗"}},{q="为什么凯特琳想要找回她的匕首？",a="凯特琳在战斗中完全依赖她的匕首，并拒绝使用其他武器。在与邓肯的匕首决斗中输掉武器后，她在帮助任何找上门来的人之前，都一定要先拿回这把刀。",al={"凯特琳匕首","凯特琳小刀","为什么要找回利刃"}},{q="凯特琳为什么要离家出走？",a="凯特琳抛弃了她的家庭，是为了逃离那种整日阅读古书并与刻板、年迈的法师为伍的枯燥生活；她拒绝过那种无聊的日子。",al={"凯特琳为何离家出走","安斯雷姆的女儿","凯特琳背景故事"}},{q="这一步在搜索过程中处于什么位置？",a="这次对抗发生在找回安斯雷姆的钥匙之后，在揭开潮汐诅咒之前。",al={"任务线","什么引向了漂亮男孩邓肯"}}},fp="19,140,20.261.0,16.211.0,25.135.0,38.150.0,35.128.0,41.113.0"}
P.entries["quest:6101"] = {n="驯服野兽",s="这一试炼标志着暗夜精灵猎人在多兰纳尔的达扎拉指导下进行宠物驯服训练的第二阶段。猎人的任务是使用一根附魔的驯兽棒去制服一只夜刃豹潜行者，以此更好地理解野生野兽不断变化的习性。这加深了泰达希尔的荒野与行走在树冠下的哨兵追踪者之间的理解纽带。",h="这一试炼标志着暗夜精灵猎人在多兰纳尔的达扎拉指导下进行宠物驯服训练的第二阶段。猎人的任务是使用一根附魔的驯兽棒去制服一只夜刃豹潜行者，以此更好地理解野生野兽不断变化的习性。这加深了泰达希尔的荒野与行走在树冠下的哨兵追踪者...",kw={"野兽驯服","达扎拉","多兰纳尔","猎人","夜刃豹潜行者","驯兽棒","泰达希尔"},ang={["class:Hunter"]="这一仪式代表了猎人教育的核心，在你被托付给终身同伴之前，教导你如何尊重不同动物的脾气。",["race:NightElf"]="夜刃豹与卡多雷的历史和文化紧密交织，使得驯服一头潜行者成为当地林地侦察兵的传统里程碑。"},sec={{t="野兽多变的本性",b="虽然早期的课程侧重于理解基本的本能，但达扎拉强调自然的唯一不变就是其持续的变化。森林中的每一个物种都有独特的脾气，猎人必须学会相应地调整自己的意志。在泰达希尔的树冠阴影下，这意味着要与那些狡猾、隐秘且比单纯的蛛网怪更具掠食性的生物打交道。"},{t="制服夜刃豹",b="夜刃豹被卡多雷奉为神圣的掠食者、凶猛的守护者，以及哨兵们隐秘的同伴。对于新手猎人来说，要对抗一只夜刃豹潜行者并引导驯兽棒的力量，需要坚定的意志和冷静的权威。通过将潜行者的掠食攻击性转化为一种接纳的纽带，猎人证明了他们不仅能驾驭温顺或弱小的林地生物。"}},faq={{q="这个任务的目的是什么？",a="这是暗夜精灵猎人任务链中的中间试炼，完成后可以解锁永久的野兽驯服能力。达扎拉会派你去驯服一只夜刃豹潜行者，让你观察不同掠食性生物之间的脾气差异。",al={"为什么要做这个任务","宠物驯服任务2","夜刃豹驯服目标"}},{q="哪里可以找到夜刃豹潜行者？",a="夜刃豹潜行者游荡在泰达希尔中部多兰纳尔以南的林间小径和灌木丛中。",al={"夜刃豹潜行者在哪里","潜行者位置","去哪里找猫"}},{q="我可以把这只夜刃豹潜行者留作我的永久宠物吗？",a="不能。用驯兽棒驯服的野兽是临时的，仅作为练习对象。当全部三个部分的试炼完成后并归还驯兽棒，你将学会真正的驯服技能，届时可以选择永久的同伴。",al={"我可以留下宠物吗","我可以留下夜刃豹吗","这是我永远的宠物吗"}},{q="谁发布了这个任务？",a="达扎拉，位于泰达希尔多兰纳尔的猎人训练师。在你完成第一次驯服测试后，他会发布这个指令。",al={"任务发布者","谁开始这个任务","达扎拉的位置"}},{q="为什么暗夜精灵如此推崇夜刃豹？",a="数千年来，夜刃豹一直与卡多雷共同生活，作为哨兵和艾露恩的祭司们的同伴、侦察兵和战骑。驯服一头夜刃豹被视为卡多雷精通林地生活的骄傲标志。",al={"暗夜精灵猫类背景","为什么夜刃豹很重要","夜刃豹背景资料"}},{q="完成这个任务后接下来做什么？",a="达扎拉会给予最后一个涉及泰达希尔另一种生物的驯服任务，在那之后才会教你驯服、喂养和管理艾泽拉斯各地永久同伴野兽的先天能力。",al={"下一个任务","夜刃豹潜行者之后是什么","猎人试炼后续"}}},fp="16,173,29.251.0,23.296.0,34.218.0,39.99.0,60.161.0,21.110.0,48.196.0,38.170.0"}
P.entries["quest:6102"] = {n="驯服野兽",s="这个任务标志着年轻的暗夜精灵猎人基础训练的最终试炼。在多兰纳尔的达扎拉的指导下，猎人必须驯服一只天空中的掠食猫头鹰，才能解锁选择真正终身伙伴的能力。",h="这个任务标志着年轻的暗夜精灵猎人基础训练的最终试炼。在多兰纳尔的达扎拉的指导下，猎人必须驯服一只天空中的掠食猫头鹰，才能解锁选择真正终身伙伴的能力。",kw={"野兽","达扎拉","多兰纳尔","猎人宠物","尖啸者","巨翼恶枭","驯服","驯兽棒","泰达希尔"},ang={["class:Hunter"]="这个成年礼是猎人从孤军奋战到与野生伙伴建立终身合作关系的转折点。",["race:NightElf"]="驯服泰达希尔本土的野生动物，反映了卡多雷与自然和谐共处，而非以武力征服的道路。"},sec={{t="树冠的掌控",b="在完成最初的野兽技艺之前，暗夜精灵猎人必须与泰达希尔生态系统各个角落的生物建立和谐关系。在证明了对抗林下野兽的意志之后，达扎拉要求猎人制服天空之灵：巨翼恶枭。这些警觉的猛禽栖息在多兰纳尔西侧高处的枝干上，需要耐心和稳定的神经才能用附魔的驯兽棒将其安抚。"},{t="猎人的羁绊",b="成功制服巨翼恶枭意味着完成了卡多雷猎人与自然沟通的古老课程。当学徒将用过的棒子还给达扎拉时，他们就结束了训练，并获得了在艾泽拉斯召唤、遣散以及永久驯服自己选择的野兽的完整技艺。"}},faq={{q="巨翼恶枭在哪里？",a="巨翼恶枭栖息在多兰纳尔西侧的树林里。猎人必须在村外树冠和根须间寻找这些掠食鸟类，以测试他们的驯兽棒。",al={"巨翼恶枭位置","巨翼恶枭在哪里","猫头鹰位置"}},{q="达扎拉是谁？",a="达扎拉是一位驻扎在多兰纳尔的暗夜精灵猎人训练师。他负责指导那些在射箭和追踪方面达到基本水平的年轻卡多雷，在赋予他们绑定真正动物伙伴的能力之前，先测试他们对陆地和天空野兽的应对能力。",al={"达扎拉的角色","谁在多兰纳尔教授驯兽","多兰纳尔的猎人训练师"}},{q="我能把巨翼恶枭留作宠物吗？",a="不能。在此试炼中驯服的巨翼恶枭只是暂时的，仅受驯兽棒魔法的束缚。一旦试炼完成，驯兽棒就会上交，猎人将学习如何在这个世界上驯服自己选择的永久伙伴。",al={"保留猫头鹰","巨翼恶枭是永久的吗","我能保留这只宠物吗"}},{q="完成这个试炼后会发生什么？",a="达扎拉会永久解锁你驯服、召唤和遣散野兽的能力。他还指引你去达纳苏斯接受进一步的训练，以学习喂养和在战斗中教导伙伴的重要技巧。",al={"接下来是什么","驯服野兽任务之后","猎人宠物任务完成"}},{q="为什么暗夜精灵特别驯服猫头鹰？",a="猫头鹰之类的猛禽在卡多雷文化中具有深远的意义，它们是警觉的黑夜猎手和值得信赖的侦察兵。征服一种天空生物证明了猎人不仅了解陆地野兽，也了解空中掠食者。",al={"猫头鹰的暗夜精灵背景","为什么选择猫头鹰","巨翼恶枭的重要性"}},{q="猎人在完成这个任务后可以选择任何动物吗？",a="是的。一旦达扎拉教授了永久驯服能力，猎人就可以自由寻找泰达希尔乃至更广阔天地中任何可驯服的陆地、水下或天空野兽。",al={"我可以获得什么宠物","选择第一只宠物","所有野兽都可以驯服吗"}}},fp="16,230,21.353.0,15.316.0,35.156.0,15.231.0,49.231.0,41.190.0,42.231.0,47.146.0"}
P.entries["quest:6103"] = {n="训练野兽",s="训练野兽是泰达希尔的新手暗夜精灵猎人的最终成人礼。在通过驯服各地树枝上的野兽证明了自己的掌控能力后，猎人们会被派往达纳苏斯，向祖卡斯特学习更深奥的宠物护理和驯服技巧。",h="训练野兽是泰达希尔的新手暗夜精灵猎人的最终成人礼。在通过驯服各地树枝上的野兽证明了自己的掌控能力后，猎人们会被派往达纳苏斯，向祖卡斯特学习更深奥的宠物护理和驯服技巧。",kw={"塞纳里奥区","达纳苏斯","达扎拉","猎人宠物","祖卡斯特","泰达希尔","训练野兽"},ang={["class:Hunter"]="这项仪式标志着你从一名新手追踪者毕业，成为了一名真正的野兽大师，解锁了训练、喂养和复活你伙伴的能力。",["race:NightElf"]="卡多雷的野兽伙伴传统以尊重与共存为核心，反映了达纳苏斯和塞纳里奥区传授的教义。"},sec={{t="猎人的成人礼",b="在暗夜精灵猎人能够带着忠诚的伙伴漫游卡利姆多之前，他们必须掌握的不仅仅是驯兽棒。虽然制服一只野兽能证明基本的实力和意志，但未经训练的野兽仍然是一个不可预测的隐患。一旦新兵在多兰纳尔周边的荒野中展现了自己的能力，达扎拉就会指引他们前往达纳苏斯完成训练。"},{t="塞纳里奥区的指导",b="在塞纳里奥区宁静的树林中，受人尊敬的猎人祖卡斯特传授着伙伴关系的重要技艺。她教导年轻的猎人如何适当地喂养宠物，在悲剧发生时如何复活它，并通过训练培养它的战斗本能。对暗夜精灵来说，这种关系植根于对自然的深切敬畏，而非单纯的支配。"}},faq={{q="这个任务的目的是什么？",a="此任务是暗夜精灵猎人初始宠物任务线的最后一环。它会指引你前往达纳苏斯，解锁维持和训练你的永久动物伙伴所需的核心技能。",al={"为什么要完成这个任务","暗夜精灵宠物训练任务","训练野兽有什么用"}},{q="我在哪里可以找到祖卡斯特？",a="祖卡斯特住在达纳苏斯的塞纳里奥区，位于这座首都西北部高耸的树木和猎人小屋之间。",al={"祖卡斯特在哪里","祖卡斯特的位置","寻找祖卡斯特"}},{q="谁发布这个任务？",a="在你完成泰达希尔各地的全部三项驯服考验后，多兰纳尔的猎人训练师达扎拉会提供此任务。",al={"任务发布者","谁发布训练野兽","达扎拉的位置"}},{q="你可以从祖卡斯特那里学到什么技能？",a="与祖卡斯特交谈将解锁野兽掌握的核心技艺：喂养你的伙伴，在它战斗中倒下时将其复活，以及通过训练赋予它新的能力。",al={"我可以获得什么能力","祖卡斯特的奖励","猎人宠物法术"}},{q="为什么暗夜精灵文化强调宠物训练？",a="卡多雷猎人将他们的宠物视为伙伴而非从属工具。适当的训练和护理反映了该种族与自然和谐共处并敬畏自然的这一核心哲学。",al={"暗夜精灵猎人背景故事","为什么暗夜精灵要训练野兽"}},{q="其他种族可以接取此任务吗？",a="这趟前往达纳苏斯的特殊旅程是暗夜精灵猎人独有的。其他种族的猎人会在各自种族的导师指导下进行同等的训练仪式。",al={"矮人能做这个任务吗","部落能做训练野兽吗"}}},fp="18,168,26.297.0,32.248.0,34.166.0,24.102.0,21.112.0,38.107.0,50.141.0,39.127.0"}
P.entries["quest:611"] = {n="海潮的诅咒",s="利刃凯特琳从Pretty Boy Duncan那里找回了她的匕首，并借出了这件巨魔神器，以便将其用于摧毁海岸外的一座沉没祭坛。藏宝海湾的大财主里维加兹想要得到海潮之石，以充实他的古代巨魔神器收藏。",h="利刃凯特琳从Pretty Boy Duncan那里找回了她的匕首，并借出了这件巨魔神器，以便将其用于摧毁海岸外的一座沉没祭坛。藏宝海湾的大财主里维加兹想要得到海潮之石，以充实他的古代巨魔神器收藏。",kw={"海潮之石的祭坛","大财主里维加兹","藏宝海湾","利刃凯特琳","加兹班","海潮之石","荆棘谷","暗礁海"},ang={["faction:Alliance"]="联盟冒险者完成了大财主里维加兹对这件古代圣物的搜寻，深入靠近部落格罗姆高营地的水域。"},sec={{t="沉没的祭坛",b="利刃凯特琳借出了她找回的那把巨魔匕首，用来破坏一座深埋在波浪之下的祭坛。虽然她不像她父亲那样是研究巨魔遗迹的专家，但她听说过一座沉没的巨魔城市，并指出了它的位置，就在格罗姆高营地西北方的暗礁海附近。在暗礁海的水下遗迹中，海潮之石的祭坛静静伫立，在一片海洋生物和鱼人之间散发着独特的蓝色光芒。"},{t="被困的法师",b="用利刃凯特琳的匕首击打海潮之石的祭坛会粉碎其魔法，并引出加兹班，一个携带着海潮之石的地精法师，他在受到挑战时会化身为水元素。一旦击败他，这块石头便可与借来的匕首一同带回藏宝海湾。在那里，大财主里维加兹准备了一个特别的展示台，将这件圣物所蕴含的海洋魔法展示在他的珍贵藏品中。"}},faq={{q="海潮之石的祭坛位于何处？",a="祭坛位于暗礁海深处的海底，是一处沉没的遗迹，坐落在格罗姆高营地西北方的海岸外。它在水下散发着显眼的蓝色光芒。",al={"祭坛在哪里","海潮之石的祭坛位置","我该去哪里找到祭坛"}},{q="大财主里维加兹为什么要这块石头？",a="大财主里维加兹是一位狂热的古代巨魔文物收藏家，他特意清理了空间并购买了一个精美的展示台，专门用来展示这件圣物。",al={"里维加兹的石头","为什么里维加兹想要石头","里维加兹怎么处理它"}},{q="利刃凯特琳为什么要借出她的匕首？",a="在从邓肯那里找回了她那把特殊的匕首后，利刃凯特琳借出了这件巨魔圣物来粉碎祭坛，并要求在事情办完后将其安全归还。",al={"凯特琳的匕首","为什么要借出匕首","利刃凯特琳"}}},fp="22,204,16.333.0,16.407.1,40.149.0,39.117.0,32.121.0"}
P.entries["quest:6121"] = {n="新的课程",s="“新的课程”是达纳苏斯的玛斯雷·驭熊者给予暗夜精灵德鲁伊新手的入门任务。它指引新手前往神圣的月光林地，与德迪利特·星焰会面，并开始学习净化毒素和毒液的艺术。",h="“新的课程”是达纳苏斯的玛斯雷·驭熊者给予暗夜精灵德鲁伊新手的入门任务。它指引新手前往神圣的月光林地，与德迪利特·星焰会面，并开始学习净化毒素和毒液的艺术。",kw={"奥伯丁","塞纳留斯","治疗毒素","德迪利特·星焰","“新的课程”","玛斯雷·驭熊者","月光林地","永夜港","解毒之力"},ang={["class:Druid"]="这次成人礼标志着你从基础的变形与生存过渡到真正成为荒野的守护者，教会你从自然中解除致命的枯萎与毒素。",["faction:Alliance"]="威胁奥伯丁的危机突显了德鲁伊的援助对于保卫黑海岸北部脆弱的联盟定居点是多么至关重要。",["race:NightElf"]="该任务由达纳苏斯的塞纳里奥区发布，将年轻的卡多雷直接与月光林地和黑海岸更深层次的祖先责任联系起来。"},sec={{t="塞纳留斯的礼物",b="德鲁伊与生灵世界有着神圣的联系，这种联系是通过半神塞纳留斯的教导与祝福传承下来的。这些天赋之一便是能够通过简单的咒语来清除污秽的毒素。然而，如此强大的天赋绝不会轻易授予新手。为了真正尊重魔法艺术带来的非凡便利，年轻的德鲁伊必须首先了解在没有自然之力直接干预的情况下，通过艰苦的世俗劳作来对抗毒素的必要性。"},{t="前往永夜港的召唤",b="居住在达纳苏斯塞纳里奥区的德鲁伊训练师玛斯雷·驭熊者指示他的学生跳过本地的练习，直接前往月光林地。在那里，在宁静的永夜港，德迪利特·星焰负责协调塞纳里奥议会的广泛事务，并准备好为新手分配一项紧急的实战任务。"},{t="现实世界的危机",b="到达永夜港后，新手们会了解到他们的试炼并非某种精心编排的测试或刻板的仪式。黑海岸的奥伯丁定居点正面临严重的动物中毒事件，当地人对此束手无策。德迪利特·星焰指派新手去调查并援助黑海岸，将他们直接推向一个生死攸关的现实危机之中。"}},faq={{q="谁提供了“新的课程”这个任务？",a="该任务由达纳苏斯塞纳里奥区的暗夜精灵德鲁伊训练师玛斯雷·驭熊者提供。",al={"谁提供“新的课程”","“新的课程”任务给予者","玛斯雷·驭熊者任务"}},{q="我需要去哪里完成这个任务？",a="你必须前往神圣的德鲁伊领域月光林地，并向位于宁静的永夜港定居点的德迪利特·星焰汇报。",al={"我要去哪里","德迪利特·星焰在哪里","“新的课程”交任务地点"}},{q="为什么德鲁伊必须首先像外行一样学习治疗毒素？",a="德鲁伊导师们认为，仅仅通过念咒就能获得塞纳留斯治疗毒液的神奇天赋，可能会滋生自满情绪。通过让新手首先学习并使用草药和世俗方法来解决毒素危机，他们确保德鲁伊能够真正尊重毒素所带来的负担和痛苦。",al={"为什么要像外行一样学习","为什么要在没有魔法的情况下治疗毒素","塞纳留斯的毒素教诲"}},{q="奥伯丁发生了什么问题？",a="奥伯丁正遭受黑海岸沿岸严重的动物中毒事件的困扰。当地的暗夜精灵无法治愈这种病痛，促使他们向月光林地的塞纳里奥议会发出求援。",al={"奥伯丁的毒素问题","奥伯丁发生了什么","黑海岸动物中毒事件"}},{q="这个任务链最终会奖励什么技能？",a="该任务开启了“解毒之力”任务链，教导德鲁伊掌握关键的“解毒术”法术，使他们能够通过魔法清除盟友身上的毒素。",al={"我能获得什么奖励","治疗毒素任务","“解毒之力”任务链"}},{q="部落的德鲁伊可以接这个任务吗？",a="不可以。“新的课程”是专属于达纳苏斯的联盟版本任务。牛头人德鲁伊在雷霆崖会接到一个平行的任务，同样指引他们前往月光林地学习治疗毒素的艺术。",al={"部落的“新的课程”","牛头人可以做这个任务吗","牛头人的“新的课程”"}}},fp="12,182,20.286.0,21.255.0,19.265.1,34.94.0,45.67.0,58.198.0,42.166.0,52.126.0,40.178.0"}
P.entries["quest:6122"] = {n="毒水之源",s="“源头之水”是年轻暗夜精灵德鲁伊了解并修复自然界的重要试炼。德鲁伊学徒受月光林地的德迪利特·星焰派遣，必须从黑海岸的壁泉河收集被污染的水，以帮助奥伯丁的博物学家奥兰达利亚·夜歌阻止一场在林中鹿群间蔓延的瘟疫。",h="“源头之水”是年轻暗夜精灵德鲁伊了解并修复自然界的重要试炼。德鲁伊学徒受月光林地的德迪利特·星焰派遣，必须从黑海岸的壁泉河收集被污染的水，以帮助奥伯丁的博物学家奥兰达利亚·夜歌阻止一场在林中鹿群间蔓延的瘟疫。",kw={"奥兰达利亚·夜歌","奥伯丁","塞纳里奥议会","峭壁之泉","治愈毒素","黑海岸","德迪利特·星焰","娜迦","祛除毒素"},ang={["class:Druid"]="这项任务是基础德鲁伊试炼的一部分。通过对抗壁泉河的生态衰退并配制解毒剂，你将唤醒在野外治愈毒素所需的精神和植物学知识。",["race:NightElf"]="对于奥伯丁的卡多雷来说，壁泉河的腐蚀是对他们祖先森林的直接亵渎，要求立即采取干预措施以保护这片土地上无辜的生灵。"},sec={{t="被污染的生命之源",b="壁泉河是黑海岸北部地区主要的淡水来源。当野生动物——特别是当地的鹿群——开始感染一种非自然、持续性的疾病时，塞纳里奥议会将目光转向了这条河流。德迪利特·星焰怀疑含水层本身受到了影响，因此委托新手德鲁伊去壁泉河瀑布下的洞穴入口，采集一份未受干扰的污染水样，这是一项至关重要的任务。"},{t="瀑布下的阴影",b="取水的过程并非没有危险。邪恶的娜迦已经在壁泉河洞穴内盘踞，并在瀑布源头附近筑巢。它们在地底泉水附近的存在，对任何调查这起枯萎病的人构成了直接威胁。尽管危险重重，但从洞口获取一份未受污染的样本，是塞纳里奥议会研究导致荒野染病之源的唯一途径。"},{t="更深层的疾病",b="当把样本送到奥伯丁的奥兰达利亚·夜歌手中后，水的污秽证实了议会最担心的事。然而，检查这种肮脏的液体揭示了一个令人不安的事实：虽然被污染的瀑布确实是毒害河岸的主要源头，但在远离其直接路径的地方也发现了受感染的鹿。这些水是制作解毒剂的重要试剂，但奥兰达利亚怀疑一种更深、更广泛的腐蚀正在蔓延至黑海岸整个地下水系。"}},faq={{q="为什么壁泉河对黑海岸如此重要？",a="壁泉河是黑海岸北部主要的天然饮用水源。由于其水流供给当地的溪流、河流以及周边的植被和动物，任何在源头引入的污染物都会迅速扩散到整个地区生态系统中。",al={"壁泉河的重要性","黑海岸的水源"}},{q="为什么黑海岸的鹿会生病？",a="当地的鹿直接饮用壁泉河及其支流的水。一种剧毒污染物污染了源头的地下水系，导致这些林中生物遭受了严重的、衰弱性的疾病。",al={"为什么鹿会生病","黑海岸生病的鹿","是什么毒害了鹿"}},{q="德迪利特·星焰是谁？",a="德迪利特·星焰是一位居住在神圣避难所月光林地的德鲁伊导师。他作为进阶德鲁伊的向导，监控着整个卡利姆多的动乱，并协调塞纳里奥议会对自然危机的应对。",al={"德迪利特·星焰背景","谁给了我这个任务","星焰月光林地"}},{q="奥兰达利亚·夜歌是谁？",a="奥兰达利亚·夜歌是一位驻扎在奥伯丁的暗夜精灵博物学家。她对黑海岸蔓延的腐蚀和饱受折磨的动物群感到忧心忡忡，于是向月光林地的塞纳里奥议会请求有经验的援助，以研究这种疾病并制定治疗方法。",al={"谁是奥兰达利亚·夜歌","夜歌奥伯丁"}},{q="为什么娜迦会出现在壁泉河？",a="来自黑海岸沿岸的娜迦已经深入内陆，占据了壁泉河后的洞穴系统。它们日益逼近的存在，对任何试图进入源头调查水源的人来说都构成了极大的威胁。",al={"壁泉河洞穴中的娜迦","为什么娜迦在这里","壁泉河娜迦"}},{q="这项任务帮助德鲁伊学习什么能力？",a="这项调查是“祛除毒素”试炼的一部分。通过诊断这种野生动物瘟疫，并与奥兰达利亚·夜歌一起合成解毒剂，德鲁伊学徒可以学习治愈毒素这一重要的魔法艺术。",al={"这个任务奖励什么法术","德鲁伊去毒任务","去毒任务线"}}},fp="20,196,26.307.0,20.240.0,15.334.1,51.178.0,42.152.0,26.190.0,29.222.0,34.192.0,47.185.0"}
P.entries["quest:6123"] = {n="收集解药",s="“搜集治疗材料”是年轻的暗夜精灵德鲁伊在黑海岸学习驾驭自然治疗之力的重要试炼。在奥伯丁的奥兰达利亚·夜歌指导下，德鲁伊收集关键的天然试剂，为该地区患病的野生动物配制修复药膏。这项任务为理解草药如何对抗毒素和疾病奠定了实践基础。",h="“搜集治疗材料”是年轻的暗夜精灵德鲁伊在黑海岸学习驾驭自然治疗之力的重要试炼。在奥伯丁的奥兰达利亚·夜歌指导下，德鲁伊收集关键的天然试剂，为该地区患病的野生动物配制修复药膏。这项任务为理解草药如何对抗毒素和疾病奠定了实践...",kw={"奥兰达利亚·夜歌","奥伯丁","解除中毒","黑海岸","德鲁伊任务","地根草","搜集治疗材料","月亮菇","枭兽洞穴"},ang={["class:Druid"]="这一成人礼教会年轻的德鲁伊凡人医学是如何与自然毒素相互作用的，为在没有世俗工具的情况下引导原始治疗能量奠定了基础。",["profession:Herbalism"]="奥兰达利亚特别指出了草药师的价值，他们拥有直接从大地中采集地根草所需的训练有素的眼光。",["race:NightElf"]="保护黑海岸的神圣树林和动物是卡多雷的神圣职责，他们崇敬艾露恩和荒野的灵魂。"},sec={{t="黑海岸野生动物的救星",b="在发现当地野生动物受污染的水源困扰后，奥伯丁的奥兰达利亚·夜歌着手调制一种有效的治疗药膏。虽然采样到的崖泉水构成了混合物的基础，但真正的疗效需要强效的天然催化剂。受感染的林地鹿无法自行恢复，这使得收集有益的治疗材料成为塞纳里奥议会的当务之急。"},{t="根茎与月亮之花",b="这种修复药膏需要两种关键植物：地根草和月亮菇。地根草具有纯粹的治疗功效，需要草药师受过训练的眼睛才能从岩石土壤中采集。为了增强混合物的药效，奥兰达利亚派遣德鲁伊前往附近的东部洞穴，收集那些在黑暗中繁茂生长，并隐藏在日益具有领地意识且焦躁不安的枭兽群中的真菌花朵。"},{t="净化毒素之路",b="为每种毒素合成特定的解毒剂是一项细致且艰巨的任务。通过引导新手完成物理原料的精细采集和酿造过程，奥兰达利亚展示了传统医学所付出的巨大努力。这种亲手制作的过程是通往掌握德鲁伊通过自然魔法净化毒素的先天艺术的垫脚石。"}},faq={{q="“搜集治疗材料”的目的是什么？",a="该任务要求德鲁伊新手为奥伯丁的奥兰达利亚·夜歌收集地根草和月亮菇。这些试剂用于制作治疗药膏，以治疗黑海岸患病的鹿，作为学习中和毒素的教学步骤。",al={"为什么要完成这个任务","搜集治疗材料目标","搜集治疗材料的用途"}},{q="月亮菇在哪里生长？",a="月亮菇生长在奥伯丁正东方山丘内的洞穴中。德鲁伊必须小心地穿过这些巢穴，因为居住在那里的野生枭兽已经变得富有领地意识且具有攻击性。",al={"月亮菇在哪里","月亮菇位置","如何找到月亮菇"}},{q="我需要成为草药师才能获得地根草吗？",a="你不需要自己学习草药学，尽管地根草是从野外草药节点采集的。如果你没有学习该专业，你必须与草药师交易或从他人处获取，以完成奥兰达利亚的配方。",al={"地根草需要草药学吗","非草药师能获得地根草吗","无需专业获取地根草"}},{q="奥兰达利亚·夜歌是谁？",a="奥兰达利亚·夜歌是一位驻扎在奥伯丁的暗夜精灵，她向塞纳里奥议会寻求帮助。她监测着黑海岸动植物的健康状况，引导年轻的德鲁伊完成最初的试炼，以净化和保护这片荒野。",al={"奥兰达利亚是谁","奥兰达利亚·夜歌背景故事"}},{q="为什么黑海岸的鹿会生病？",a="这些鹿食用了荒野中受污染泉水的水。由此产生的毒素使它们丧失能力并遭受痛苦，需要一种有效的治疗药膏来缓解它们的症状。",al={"为什么鹿会中毒","黑海岸生病的鹿","是什么毒害了鹿"}},{q="这个任务如何帮助我学习“解除中毒”？",a="该任务是更大的“毒素之力”训练的一部分。通过向新手展示为各种毒素准备草药解毒剂是多么费力，塞纳里奥议会让他们准备好引导原始的自然魔法，从而能够毫不费力地中和毒素。",al={"德鲁伊解除中毒任务","学习解除中毒","毒素之力系列任务"}}},fx={["0cfb14cd"]={q="奥兰达利亚·夜歌为什么要你完成这件事？",a="作为一名在奥伯丁守望黑海岸的德鲁伊，奥兰达利亚无法眼看当地野生动物受苦而袖手旁观。当地的鹿染上了一种令人衰弱的疾病，无法自行康复。她眼下最要紧的是配制有效的疗伤膏，尽快结束它们的痛苦，并恢复这片遭到污染的森林的平衡。",al={"奥兰达利亚的动机","为什么要帮助病鹿","奥兰达利亚为什么在意"}},e3b496ec={q="大地之根有什么用？",a="奥兰达利亚用大地之根为疗伤膏注入恢复活力的特性。将它混入取自峭壁之泉的水样中——那是药膏的基底——这种草药天然的药性便能抵消使黑海岸的鹿染病的毒素。",al={"为什么要大地之根","大地之根有什么作用","大地之根药膏"}},["74e6ce3c"]={q="月亮菇有什么用？",a="月亮菇能为药膏提供必要的效力。它强大的天然生长力可以增强混合物的疗效，确保药剂足以清除患病鹿体内根深蒂固的毒素。",al={"为什么要月亮菇","月亮菇的用途","药膏为什么需要月亮菇"}}},fp="18,176,33.319.0,22.279.0,28.277.1,42.213.0,33.126.0,46.199.0,29.225.0,35.140.0,46.205.0"}
P.entries["quest:6124"] = {n="消除疾病",s="“治愈伤病者”是年轻的联盟德鲁伊的一项基本试炼，要求他们使用准备好的药膏去治疗徘徊在黑海岸的受毒害野生动物。通过直接缓解患病鹿群的痛苦，初学者们在向月光林地的塞纳里奥议会报告之前，解决了困扰卡利姆多北部地区那日益严重的颓势。",h="“治愈伤病者”是年轻的联盟德鲁伊的一项基本试炼，要求他们使用准备好的药膏去治疗徘徊在黑海岸的受毒害野生动物。通过直接缓解患病鹿群的痛苦，初学者们在向月光林地的塞纳里奥议会报告之前，解决了困扰卡利姆多北部地区那日益严重的颓...",kw={"奥兰达利亚·夜歌","奥伯丁","塞纳里奥议会","壁泉河","动物医疗药膏","治愈伤病者","黑海岸","德迪利特·星焰","毒素","生病的鹿"},ang={["class:Druid"]="这次成人礼测试了初学者对于维护平衡的承诺，并作为获得用德鲁伊魔法净化毒素的天赋能力的桥梁。",["race:NightElf"]="黑海岸代表了现代暗夜精灵定居点的祖先边界，这使得鹿群中突然出现的枯萎病对Kaldorei来说是一个不祥之兆。"},sec={{t="林地中的瘟疫",b="在黑海岸阴暗的森林中，从壁泉河的水域向南一直到灰谷的边界，当地的野生动物正遭受着持续不断的疾病折磨。患病的鹿群在雾气中漫无目的地徘徊，因渗入土壤和溪流的非自然毒素而变得虚弱。在收集了必要的试剂后，奥兰达利亚·夜歌委托一位有抱负的德鲁伊使用新鲜调制的动物医疗药膏去野外治疗那些受苦的生物。"},{t="月光林地中洞悉的目光",b="一旦治疗了十头鹿，初学者会被派往月光林地的神圣避难所，向德迪利特·星焰报告。虽然奥伯丁能稍微松一口气，但德迪利特却将这些病弱的鹿群视为席卷卡利姆多北部地区那更邪恶腐化的预兆。他警告说，当达纳苏斯的领导者们还在争论并忽视那蔓延的腐朽时，塞纳里奥议会必须对正在整个大陆扎根的生态腐化的真实规模保持警惕。"}},faq={{q="为什么黑海岸的鹿会生病？",a="鹿群正在遭受一种蔓延的生态腐化的折磨，这种腐化已经开始渗入黑海岸的水域和土壤，从壁泉河一直延伸到南部的灰谷。作为野生食草动物，这些鹿无意中食用了被污染的植物和河水，因此变得虚弱且染病。",al={"为什么鹿会生病","黑海岸生病的鹿","是什么毒害了鹿"}},{q="是谁制作了用于治疗鹿群的动物医疗药膏？",a="奥兰达利亚·夜歌，一位驻扎在暗夜精灵城镇奥伯丁的暗夜精灵，用德鲁伊初学者收集的稀有试剂制作动物医疗药膏。她调制的一批药膏提供了十剂，可以立即治疗受苦的动物，同时她也在尝试与镇民们一起制作更多药膏。",al={"谁制作了治疗药膏","奥兰达利亚的药膏","动物医疗药膏制作者"}},{q="为什么德迪利特·星焰会关心这些鹿？",a="德迪利特·星焰代表月光林地的塞纳里奥议会监督德鲁伊的训练。对他而言，照料野生动物既是对德鲁伊职责的实践检验，也是一种鲜明的证据，表明某种更广泛、更危险的腐化正在接管卡利姆多的荒野。",al={"为什么是德迪利特和月光林地","塞纳里奥议会对鹿群的关注","德迪利特·星焰的职责"}},{q="德迪利特·星焰暗示了怎样的政治紧张局势？",a="在完成任务后，德迪利特指出，虽然达纳苏斯的一些暗夜精灵当局承认日益严重的环境腐化，但其他人却固执地忽视了这些警告信号。他敦促初学者永远不要对自然界面临的不适事实视而不见。",al={"达纳苏斯的紧张局势","谁忽视了这种腐化","达纳苏斯的视而不见"}},{q="哪里可以找到生病的鹿？",a="生病的鹿在几乎整个黑海岸四处徘徊。它们分布在奥伯丁以北的壁泉河南部，并一路向南在整个沿海森林中游荡，直到灰谷的边界。",al={"生病的鹿的位置","鹿在哪里","黑海岸鹿的位置"}},{q="德鲁伊从完成这项任务中学到了什么？",a="这个任务构成了德鲁伊毒素净化学习的实践高潮。通过目睹森林动物的苦难并应用物理治疗，德鲁伊架起了连接植物疗法和对毒素的精神掌控之间的桥梁。",al={"这对德鲁伊的教导","德鲁伊净化毒素训练","治愈伤病者的教训"}}},fp="15,209,25.286.0,26.345.1,35.200.0,49.192.0,48.208.0,55.181.0,35.124.0,50.167.0"}
P.entries["quest:6125"] = {n="解毒之术",s="“驾驭毒素”标志着一名年轻德鲁伊掌握剧毒苦难试炼的终章。在黑海岸亲手学会调制草药疗法后，初学者回到达纳苏斯，接受塞纳里奥议会的魔法祝福，从而能随心所欲地净化毒素。",h="“驾驭毒素”标志着一名年轻德鲁伊掌握剧毒苦难试炼的终章。在黑海岸亲手学会调制草药疗法后，初学者回到达纳苏斯，接受塞纳里奥议会的魔法祝福，从而能随心所欲地净化毒素。",kw={"奥伯丁","塞纳里奥区","驱散毒素","达纳苏斯","德迪利特·星焰","玛斯雷·驭熊者","月光林地","驾驭毒素"},ang={["class:Druid"]="这一通过仪式架起了谦逊的草药学与神圣的恢复魔法之间的桥梁，标志着德鲁伊获得了凭借自然恩典中和剧毒的直接力量。",["race:NightElf"]="这项试炼在达纳苏斯的塞纳里奥区进行，反映了卡多雷对平衡的敬畏，以及他们对古老森林的庄严守护。"},sec={{t="学徒的谦卑",b="在赋予德鲁伊净化毒素的天生魔法能力之前，塞纳里奥议会要求初学者理解平民所遭受的痛苦。在黑海岸，奥兰达利亚·夜歌指派年轻的修行者手动采集地根草和月亮菇，调制出可以治愈患病野生动物的草药膏。这一课确保了德鲁伊在引导自然之力治愈毒素时，能够对那些必须在没有精神干预的情况下与剧毒抗争的生灵怀有深刻的同理心。"},{t="回到塞纳里奥区",b="一旦物理疗法在奥伯丁证明有效，星焰便会将德鲁伊送回海对岸的达纳苏斯。在塞纳里奥区的树枝间，玛斯雷·驭熊者正在等待他们的归来。玛斯雷对初学者在压力下的从容表现感到满意，正式传授了自然净化的艺术，赋予了他们永久驾驭毒素的能力。然而，这次试炼也带来了令人不安的消息：奥伯丁周边荒野中存在的致命毒素表明，某种非自然的枯萎病正在破坏这片土地微妙的平衡。"}},faq={{q="这个任务的目的是什么？",a="该任务是德鲁伊“治愈毒素”试炼的终点。在月光林地和黑海岸成功为德迪利特·星焰制备了物理治疗药剂后，学生回到达纳苏斯的玛斯雷·驭熊者处，学习天生魔法技能“驱散毒素”。",al={"为何要做驾驭毒素任务","驾驭毒素任务目标","驱散毒素任务"}},{q="德迪利特·星焰是谁？",a="德迪利特·星焰是一位驻扎在月光林地神圣避难所——永夜港的德鲁伊长者。他引导初学者完成精神试炼，在将他们送回各自的导师处之前，考验他们的耐心以及对自然的奉献精神。",al={"德迪利特·星焰的角色","谁发布了驾驭毒素任务"}},{q="玛斯雷·驭熊者是谁？",a="玛斯雷·驭熊者是一位居住在达纳苏斯塞纳里奥区的德鲁伊导师。他负责监管泰达希尔枝叶间暗夜精灵德鲁伊的成长，传授变形术、恢复系法术以及塞纳里奥议会的庄严职责。",al={"玛斯雷·驭熊者背景故事","驭熊者达纳苏斯"}},{q="为什么德鲁伊首先需要亲手制作解毒剂？",a="德迪利特·星焰教导说，德鲁伊必须了解毒素带来的身体痛苦，以及在没有魔法辅助的情况下治疗它所需的辛劳。通过采集普通草药并亲手帮助病患，初学者学会了谦卑，并懂得了感激他们即将获得的自然恩赐。",al={"为何要制作草药解毒剂","驾驭毒素的教训"}},{q="玛斯雷对奥伯丁的情况有何担忧？",a="玛斯雷指出，奥伯丁周围黑海岸荒野中突然出现的致命毒素是不自然的。对当地野生动物和植物群的破坏威胁到了生态平衡，暗示这片多雾的海岸上存在着某种腐蚀性的力量。",al={"奥伯丁毒素背景","玛斯雷的担忧"}}},fp="17,172,22.416.0,21.391.0,34.184.0,26.200.0,29.203.0,56.253.0,58.210.0"}
P.entries["quest:6126"] = {n="新的课程",s="“新的课程”是年轻牛头人德鲁伊的成人仪式，由雷霆崖长者高地的图拉克·符文图腾发起。它指引学徒前往月光林地的圣地，开始掌握净化自然与非自然毒素的艺术。在暗夜精灵德迪利特·星焰的指导下，这门课程摒弃了模拟演练，转而面对一场紧迫的、现实世界的中毒危机。",h="“新的课程”是年轻牛头人德鲁伊的成人仪式，由雷霆崖长者高地的图拉克·符文图腾发起。它指引学徒前往月光林地的圣地，开始掌握净化自然与非自然毒素的艺术。在暗夜精灵德迪利特·星焰的指导下，这门课程摒弃了模拟演练，转而面对一场紧...",kw={"塞纳里奥议会","十字路口","驱毒术","德迪利特·星焰","新的课程","月光林地","永夜港","图拉克·符文图腾"},ang={["class:Druid"]="这个任务标志着你从基本的变形和小型冲突转变为荒野的真正管家，开启了掌握驱毒术的旅程。",["faction:Horde"]="当部落勇士在灰谷与暗夜精灵发生冲突时，部落德鲁伊在塞纳里奥议会的神圣庇护下，在月光林地获得了安全的港湾。",["race:Tauren"]="对于牛头人来说，这次朝圣展示了大地母亲的孩子们是如何与他们的暗夜精灵同伴一起，重新与塞纳留斯的教义紧密连接的。"},sec={{t="塞纳留斯的馈赠",b="德鲁伊肩负着守护荒野的神圣使命，其中包括塞纳留斯赐予的、通过简单咒语即可净化剧毒的神奇能力。然而，如此强大的魔法并非唾手可得。图拉克·符文图腾坚持认为，在引导神圣能量轻松驱散枯萎之前，德鲁伊必须了解毒素造成的生理痛苦，并学会通过扎实的世俗手段来治疗它。"},{t="前往永夜港的召唤",b="与其仅仅在莫高雷的断崖上进行训练，有前途的侍僧会被送往北方，穿过神圣的小径前往月光林地。在那里，在宁静的永夜港村庄中，像德迪利特·星焰这样的古老暗夜精灵导师会监督精灵和牛头人修行者的教育。这种共同教学凸显了塞纳里奥议会内部存在的微妙休战，超越了部落与联盟之间的政治冲突。"},{t="贫瘠之地的真实危机",b="虽然以前的入会者是在受控条件下练习净化仪式，但星焰没有时间进行人为的演习。贫瘠之地干旱的十字路口附近爆发了一场无法控制的动物中毒事件。来自十字路口的绝望求援将一场学术性的成人仪式转变为了一项紧急实地任务，要求年轻的德鲁伊直接面对野生动物的苦难。"}},faq={{q="谁发布了这个任务，我该去哪里找他？",a="该任务由雷霆崖长者高地的牛头人德鲁伊训练师图拉克·符文图腾发布。他呼吁那些已经证明自己对塞纳里奥教义有初步承诺的入会者。",al={"谁发布新的课程","在哪里领取新的课程","新的课程任务发布者"}},{q="德迪利特·星焰是谁？",a="德迪利特·星焰是一位居住在月光林地永夜港的年长暗夜精灵德鲁伊。尽管暗夜精灵和牛头人之间存在广泛的阵营紧张关系，但他仍在塞纳里奥议会的传统下指导两个种族的年轻德鲁伊。",al={"德迪利特是谁","德迪利特·星焰的角色","月光林地的暗夜精灵是谁"}},{q="这个任务教给我什么力量？",a="这个任务线开启了你对“驱毒术”的指导。它教导德鲁伊理解毒素的生理和魔法本质，使他们能够从盟友和他们照料的野生生物身上清除有害的折磨。",al={"我学会了什么技能","这是什么法术的任务","驱毒任务"}},{q="为什么牛头人必须在暗夜精灵门下学习？",a="塞纳里奥议会是一个致力于自然平衡的中立兄弟会。虽然暗夜精灵是第一批在塞纳留斯麾下将现代德鲁伊教义正规化的种族，但他们欢迎牛头人重回教团，尽管存在阵营战争，依然共享月光林地这样的圣地。",al={"为什么是暗夜精灵训练师","牛头人暗夜精灵德鲁伊","塞纳里奥议会阵营"}},{q="十字路口发生了什么？",a="贫瘠之地十字路口附近的当地野生动物正遭受一波猛烈的中毒浪潮，当地的驯兽师无法遏制。德迪利特·星焰将你的训练直接转向实地，以查明来源并合成补救措施。",al={"十字路口的问题","什么在毒害动物","十字路口的疾病"}},{q="完成这个任务去月光林地的最快方法是什么？",a="作为一名德鲁伊，你拥有传送技能：月光林地，它可以直接将你送入永夜港的圣所，而无需徒步穿越危险的争议领土。",al={"如何前往月光林地","前往永夜港","传送月光林地"}}},fp="12,236,20.291.0,21.363.0,28.289.1,47.178.0,26.208.0,37.189.0,50.249.0,36.231.0,59.167.0"}
P.entries["quest:6127"] = {n="毒水之源",s="“主要源头”是月光林地的德迪利特·星焰发布的一项部落德鲁伊任务。它派遣初出茅庐的德鲁伊前往贫瘠之地北部的鬼雾峰，采集受污染的池水，并将其带给十字路口的图加·符文图腾。该样本提供了了解这一地区野生动物所遭受的蔓延毒素所需的根本依据。",h="“主要源头”是月光林地的德迪利特·星焰发布的一项部落德鲁伊任务。它派遣初出茅庐的德鲁伊前往贫瘠之地北部的鬼雾峰，采集受污染的池水，并将其带给十字路口的图加·符文图腾。该样本提供了了解这一地区野生动物所遭受的蔓延毒素所需的...",kw={"贫瘠之地","塞纳里奥议会","十字路口","德迪利特·星焰","鬼雾峰","毒素的克星","主要源头","生病的瞪羚","图加·符文图腾"},ang={["class:Druid"]="这项成年仪式是你作为荒野守护者道路上的重要一步，证明你能够追溯腐败的源头，并在魔法毒素摧毁整个生态系统之前将其隔离。",["faction:Horde"]="十字路口是部落在卡利姆多存在的基础物流枢纽，因此其后院中不受控制地蔓延的恶魔枯萎病对贸易和生存构成了直接威胁。",["race:Tauren"]="贫瘠之地是卡利姆多各族的祖居之地；净化水源有助于保护那些世世代代供养你们族人的瞪羚群免受恶魔腐蚀。"},sec={{t="被污染的高山",b="鬼雾峰矗立在十字路口的西北方，山势极高，其高处的泉水和池塘影响着周围的天气模式和干旱的贫瘠之地北部的自然湿度。不幸的是，信奉恶魔的火刃氏族邪教徒已经在山脊上扎了根。德迪利特·星焰意识到，在如此重要的自然制高点上进行的邪恶巫术可能会污染整个周围盆地。"},{t="平原上的瘟疫",b="在整个北方草原上，人们看到生病的瞪羚在东西向主干道十字路口的北侧蹒跚而行。图加·符文图腾代表当地牛头人寻求援助，联系了塞纳里奥议会，以帮助查明是什么毒害了牛群。通过勇敢地登上山峰并取回纯净的受污染水样，德鲁伊为图加提供了分析病情和酿造解药所需的关键催化剂。"}},faq={{q="我在哪里可以获得这个任务的水样？",a="水必须从位于贫瘠之地十字路口西北方鬼雾峰最顶端的池塘中汲取。你必须到达火刃氏族邪教徒聚集的山顶池塘，并使用德迪利特·星焰提供的采样器。",al={"鬼雾峰水池位置","水池在哪里","主要源头水样"}},{q="为什么鬼雾峰的水对贫瘠之地如此重要？",a="鬼雾峰空气清新的高处拥有的池塘直接影响着当地的天气模式和水雾。当恶魔邪教徒污染这些水源时，带毒的蒸汽和径流会向下漂移，腐蚀下方的平原，使整个贫瘠之地北部的野生动物患病。",al={"为什么鬼雾峰很重要","贫瘠之地天气水池","鬼雾峰水池"}},{q="图加·符文图腾是谁？",a="图加·符文图腾是一位驻扎在贫瘠之地十字路口的牛头人德鲁伊。他对在当地瞪羚中蔓延的不自然疾病深感担忧，因此向月光林地的塞纳里奥议会请求协助，以诊断和净化这片土地。",al={"图加是谁","图加·符文图腾的作用","十字路口德鲁伊"}},{q="是谁在污染山顶的水？",a="水源已被火刃氏族污染，这是一个信奉恶魔的术士和邪能使用者的阴暗邪教，他们占据了鬼雾峰蜿蜒的小径和山顶。",al={"谁污染了池塘","鬼雾峰邪教徒","火刃氏族鬼雾峰"}},{q="完成这个任务链会教授什么能力？",a="此项任务是年轻部落德鲁伊“毒素的克星”仪式中较大环节的一部分，最终将掌握在野外治愈毒素所需的精神和草药知识。",al={"毒素的克星奖励","德鲁伊驱毒法术","贫瘠之地驱毒任务"}},{q="联盟德鲁伊可以完成这个任务吗？",a="不能。“主要源头”是专门针对部落的试炼版本，派遣玩家前往贫瘠之地协助图加·符文图腾。联盟德鲁伊将在黑海岸进行类似的旅程，以获得他们的解毒能力。",al={"联盟对应任务","暗夜精灵可以完成主要源头吗","联盟毒素任务"}}},fp="20,208,18.328.0,22.305.0,47.173.0,63.192.0,23.200.0,40.145.0,46.121.0,34.164.0"}
P.entries["quest:6128"] = {n="收集解药",s="“收集解药”是对于驻扎在十字路口的牛头人德鲁伊学徒来说是一项神圣的试炼。在图加·符文图腾的指派下，德鲁伊需要收集地根草和结实的科多兽角，为贫瘠之地中毒的瞪羚调制治疗药膏。",h="“收集解药”是对于驻扎在十字路口的牛头人德鲁伊学徒来说是一项神圣的试炼。在图加·符文图腾的指派下，德鲁伊需要收集地根草和结实的科多兽角，为贫瘠之地中毒的瞪羚调制治疗药膏。",kw={"贫瘠之地","十字路口","德鲁伊任务","地根草","收集解药","瞪羚","科多兽角","药膏","图加·符文图腾"},ang={["class:Druid"]="这项任务是关键试炼的一部分，德鲁伊通过试炼学习超越凡人的草药学，并引导自然魔法直接驱除毒素。",["faction:Horde"]="协助图加有助于保护十字路口周围的野生动物，为部落在这一地区的中心前哨确保稳定的生态环境。",["profession:Herbalism"]="该任务依赖于地根草，强调了从大草原多岩石的山坡上采集野生药用根茎的持久价值。"},sec={{t="救治配方",b="在获得了鬼雾峰的水样后，图加·符文图腾需要原始试剂来调制一种有效的物理抗毒剂。天然泉水是药膏的基础，普通的地根草提供了基本的药用功效，而研磨后的科多兽角则赋予了药膏所需的复原效力，足以将毒素从生物体内驱除。对于年轻的德鲁伊来说，获取这些原料意味着要依赖大地的馈赠并猎杀当地的野兽。"},{t="净化课程",b="炼金术和草药学是抵御特定毒素的传统手段，但每种独特的毒素通常都需要精确、定制的解药。图加利用这种费力的准备工作来教导学徒们物理药物的局限性。真正掌控自然毒素的能力并非来自于携带无穷无尽的干草药和兽角，而是直接与自然的治愈能量共鸣——这是一门意义深远的课程，它将直接引向德鲁伊的“解毒术”技能。"}},faq={{q="图加·符文图腾需要什么原料？",a="图加要求收集五捆地根草和五根完整的科多兽角。地根草提供治疗性的草药属性，而兽角则提供中和当地瞪羚体内毒素所必需的强大效力。",al={"收集解药物品","我需要什么试剂","解药材料"}},{q="去哪里寻找科多兽角？",a="科多兽游荡在贫瘠之地北部和中部的干旱平原上，经常在十字路口周围的道路附近吃草。图加强调，只有从这些野兽身上获取完整、结实的兽角才能用于药膏，易碎的残片是无法使用的。",al={"科多兽在哪里","科多兽角位置","在贫瘠之地寻找科多兽"}},{q="我必须要是草药师才能获得地根草吗？",a="不需要，你本身并不需要草药学专业。虽然草药师可以在贫瘠之地的悬崖和岩石缝隙中采集地根草，但如果德鲁伊缺乏直接采集的技能，也可以从其他旅者或贸易站获得。",al={"我需要草药学吗","无需草药学采集地根草","地根草专业要求"}},{q="为什么图加要准备一种物理药膏？",a="图加正在准备一种物理抗毒剂，以治疗在贫瘠之地北部受毒害的瞪羚。他还利用这种制作特定物理药剂的繁琐过程，来演示学习先天的魔法净化法术所具有的巨大优势。",al={"为什么要制作抗毒剂","药膏的用途","为什么不使用魔法"}},{q="图加·符文图腾是谁？",a="图加·符文图腾是一位驻扎在贫瘠之地十字路口的年长牛头人德鲁伊。他负责调查该地区水源中蔓延的腐蚀，并引导年轻的德鲁伊掌握自然平衡。",al={"谁发布收集解药任务","图加·符文图腾的角色","图加是谁"}},{q="收集完这些原料后要做什么？",a="当图加用试剂调制好药膏后，他会派德鲁伊前往大草原，直接将混合物涂抹在患病的瞪羚身上，以此在传授更深奥的魔法净化艺术之前先测试这种疗法。",al={"收集解药之后是什么","收集解药的后续任务","完成收集解药之后"}}},fp="18,189,19.337.0,20.321.0,46.187.0,34.158.0,49.217.0,40.177.0,23.197.0,45.170.1"}
P.entries["quest:6129"] = {n="消除疾病",s="“医治病患”是部落年轻德鲁伊的一项基本考验，任务要求他们治疗贫瘠之地北部受感染的野生动物。通过为患病的瞪羚涂抹新鲜配制的草药药膏，新兵们展示了他们实地的医疗技术以及维护自然平衡的决心。完成这项职责直接向月光林地的塞纳里奥议会证明了他们的忠诚。",h="“医治病患”是部落年轻德鲁伊的一项基本考验，任务要求他们治疗贫瘠之地北部受感染的野生动物。通过为患病的瞪羚涂抹新鲜配制的草药药膏，新兵们展示了他们实地的医疗技术以及维护自然平衡的决心。完成这项职责直接向月光林地的塞纳里奥...",kw={"贫瘠之地","塞纳里奥议会","十字路口","动物医疗药膏","净化毒素","医治病患","德迪利特·星焰","月光林地","患病的瞪羚","图加·符文图腾"},ang={["class:Druid"]="这项治疗仪式标志着你从一名草药学学生转变为了一名积极的自然守护者，证明了你已准备好运用生命魔法对抗致命的毒素。",["faction:Horde"]="通过在十字路口附近治疗受感染的野生动物，牛头人德鲁伊帮助保护了重要的狩猎场和交通走廊，支持了部落在卡利姆多中部的立足点。",["race:Tauren"]="随着你们的人民重燃与塞纳里奥议会的古老纽带，治愈贫瘠之地证明了大地之母的孩子们是有资格维持平衡的守护者。"},sec={{t="兽群之灾",b="在贫瘠之地的北部草原上，成群的瞪羚开始死于一种非自然的疾病。在收集了地根草和科多兽角以配置治疗药剂后，十字路口的图加·符文图腾会将野外治疗的任务托付给一位年轻的德鲁伊。新兵必须在主要路口以北搜寻，找到十只受苦的动物并进行医治，在腐化进一步深入生态系统之前提供紧急救助。"},{t="议会的祝福",b="药膏分发完毕后，德鲁伊的道路将指引他们回到月光林地那宁静的枝叶下。在那里，德迪利特·星焰会认可这位新兵的同情心与警觉性。他指出，瞪羚的苦难仅仅是潜伏在卡利姆多荒野中的某种更深层、更阴险的腐化的症状。通过照料这些最卑微的野兽，牛头人德鲁伊证明了他们对塞纳留斯的崇敬超越了部落的界限，从而获得了更多关于净化毒素与自然魔法的秘密。"}},faq={{q="哪里可以找到患病的瞪羚？",a="受感染的瞪羚在贫瘠之地北部的干旱平原上游荡，主要位于十字路口交汇的东西向主要贸易路线以北。",al={"瞪羚位置","患病瞪羚在哪里","贫瘠之地瞪羚"}},{q="谁发放这个任务？",a="图加·符文图腾，一位驻扎在贫瘠之地十字路口的牛头人德鲁伊，在完成他收集试剂的任务后，会提供此任务并提供动物医疗药膏。",al={"谁给予医治病患","任务发布者","图加·符文图腾位置"}},{q="治好动物后我该向谁报告？",a="你需要向月光林地德鲁伊圣地的德迪利特·星焰交付任务，使用你的传送魔法到达那片神圣的林地。",al={"我在哪里交付任务","任务交付","德迪利特·星焰位置"}},{q="为什么塞纳里奥议会对贫瘠之地感兴趣？",a="塞纳里奥议会守护着大地的和谐。野生瞪羚中蔓延的疾病反映了某种正在卡利姆多渗透的广泛腐化，如果不加以遏制，将威胁到自然秩序的稳定。",al={"为什么德鲁伊关心贫瘠之地","塞纳里奥议会贫瘠之地"}},{q="这个任务链解锁什么技能？",a="这项考验构成了德鲁伊成年仪式的后半部分，最终将奖励新兵净化自身及盟友身上毒素与毒药的能力。",al={"净化毒素任务奖励","为什么德鲁伊要做这个任务"}},{q="非德鲁伊职业可以治疗这些瞪羚吗？",a="不可以。这个任务线是德鲁伊专属的，作为一项由塞纳里奥议会直接监督的职业考验。",al={"这是德鲁伊专属吗","谁可以做医治病患"}}},fx={f2ed6f7d={q="图加·符文图腾为什么要你治好这些瞪羚？",a="一股蔓延的腐化正在侵蚀贫瘠之地北部的野生动物，当地的瞪羚因此染上了令人衰弱的疾病。图加·符文图腾已经配制出疗伤膏来对抗病症，但大自然等不起。他需要你立即为受苦的动物带去救治，在污秽进一步破坏这片土地脆弱的平衡之前遏止它。",al={"为什么要治瞪羚","图加·符文图腾的动机","为什么帮助患病的瞪羚"}},f6349169={q="图加·符文图腾为什么需要你帮忙，而不亲自救治瞪羚？",a="图加只来得及配制出十剂药膏，必须留在十字路口与当地官员协调，准备更多药剂。作为一名踏上塞纳留斯之路的见习德鲁伊，你与自然的联系能让你找到四散患病的动物，并在不给它们增添痛苦的情况下施用药剂。",al={"图加·符文图腾为什么找我","图加为什么需要帮手","为什么不让当地卫兵去"}}},fp="15,202,23.376.0,21.428.0,36.144.0,22.163.0,44.154.0,53.187.0,42.156.0,35.112.0"}
P.entries["quest:613"] = {n="玛雷的腿",s="“海狼”马克基雷取回了他已故债务人莫里的脚，却发现他被欠下的财物被锁在里面了。为了索回欠款，他指引旅行者前往荆棘谷的莫什奥格食人魔山去寻找丢失的钥匙。",h="“海狼”马克基雷取回了他已故债务人莫里的脚，却发现他被欠下的财物被锁在里面了。为了索回欠款，他指引旅行者前往荆棘谷的莫什奥格食人魔山去寻找丢失的钥匙。",kw={"藏宝海湾","钥匙","马克基雷","莫里","莫什奥格","食人魔","海狼","荆棘谷"},sec={{t="上锁的奖品",b="在“巫医的代价”任务中取回莫里的脚之后，“海狼”马克基雷在藏宝海湾遇到了意想不到的麻烦。这位已故的债务人在他的脚上加了一把锁，而他欠下的财物就封在里面。"},{t="食人魔土堆",b="莫里喜欢和东北方向莫什奥格食人魔山的食人魔们赌博。马克基雷记得莫里曾说，在他赢了太多之后，食人魔把他赶走了，所以他怀疑食人魔现在持有钥匙，于是派遣旅行者去寻找。"}},faq={{q="为什么“海狼”马克基雷需要莫里的钥匙？",a="莫里把自己欠下的东西封在了自己的脚里，并加上了一把锁。没有开锁的钥匙，马克基雷无法拿到欠他的债款。",al={"为什么需要钥匙","钥匙是做什么用的","莫里钥匙的目的"}},{q="莫里的钥匙被认为在哪里？",a="马克基雷怀疑这把钥匙可能被藏宝海湾东北方向的莫什奥格食人魔山的食人魔所持有。",al={"钥匙在哪里","钥匙位置","哪里寻找莫里钥匙"}},{q="为什么莫什奥格食人魔会有这把钥匙？",a="莫里经常与莫什奥格食人魔赌博，马克基雷记得食人魔在莫里赢了一大笔钱后就把他赶走了。这就是他猜测钥匙可能在他们手里的原因。",al={"为什么食人魔有钥匙","莫里与食人魔的关系","莫里认识食人魔吗"}},{q="在马克基雷的这些生意中，之前发生了什么？",a="这是继“巫医的代价”之后的任务，而在那之前，围绕藏宝海湾的债务结算工作还包括“恐吓谢基”和“回到马克基雷那里”。",al={"前置任务","任务链顺序","首先发生什么"}}},fp="21,201,14.173.0,16.220.0,47.101.0,35.93.0,42.139.0,47.122.0"}
P.entries["quest:6130"] = {n="解毒之术",s="“毒素掌控”是年轻部落德鲁伊掌握恢复自然魔法的试炼中的最终仪式。在只使用草药混合剂治愈了十字路口附近的患病羚羊后，学徒将回到雷霆崖长者高地，向图拉克·符文图腾汇报，从而获得“解毒术”的真正天赋。",h="“毒素掌控”是年轻部落德鲁伊掌握恢复自然魔法的试炼中的最终仪式。在只使用草药混合剂治愈了十字路口附近的患病羚羊后，学徒将回到雷霆崖长者高地，向图拉克·符文图腾汇报，从而获得“解毒术”的真正天赋。",kw={"贫瘠之地","十字路口","解毒术","德迪利特·星焰","长者高地","月光林地","雷霆崖","图拉克·符文图腾"},ang={["class:Druid"]="这次成人礼将卡利姆多的物理草药学与天生的自然魔法连接起来，赋予了德鲁伊永久清除盟友体内毒素的能力。",["faction:Horde"]="围绕十字路口的试炼展示了部落在保护卡利姆多中部荒野免受非自然腐蚀方面日益增长的作用。",["race:Tauren"]="对于牛头人新手来说，完成这个任务证明了他们对塞纳里奥议会的奉献，同时也让大地母亲的智慧在长者高地上得以延续。"},sec={{t="苦难的课程",b="在赋予年轻的德鲁伊净化毒素的天生魔法力量之前，塞纳里奥议会要求他们理解苦难的物理本质。德迪利特·星焰将新手派往十字路口，图加·符文图腾在那里让他们收集大地试剂，并亲手制作治疗药膏。只有在没有精神力量辅助的情况下治疗贫瘠之地中毒的平原羚羊，学生才能见证普通生物在对抗自然与非自然毒素时所面临的痛苦挣扎。"},{t="回到长者高地",b="试炼完成后，德迪利特将学徒送回雷霆崖长者高地，去寻找居住在那里的德鲁伊导师图拉克·符文图腾。图拉克指出，十字路口附近出现的奇怪、剧毒的毒素正在威胁平原的自然平衡，这值得严重关注。为了嘉奖学徒在压力下的优雅表现，图拉克永久传授了解除毒素的精神艺术，并委托他们守护卡利姆多的所有生物。"}},faq={{q="这个任务的目的是什么？",a="这个任务标志着部落德鲁伊解毒试炼的结束。在通过准备凡俗药物来挽救受苦的羚羊展现出纪律性之后，学徒回到图拉克·符文图腾身边，通过德鲁伊的交流直接学习“解毒术”。",al={"为什么要做毒素掌控","这个任务做什么","德鲁伊解毒任务目的"}},{q="图拉克·符文图腾在哪里？",a="图拉克·符文图腾居住在雷霆崖的长者高地上。他的家位于牛头人德鲁伊交流和修行的帐篷和中空栖木之中。",al={"图拉克·符文图腾位置","图拉克在哪里","寻找图拉克·符文图腾"}},{q="是谁把德鲁伊送回雷霆崖的？",a="德迪利特·星焰，一位驻扎在月光林地圣地的塞纳里奥议会暗夜精灵德鲁伊，在学徒成功治愈了十字路口附近的野生动物后，将他们送回导师身边。",al={"谁给予毒素掌控任务","任务给予者","德迪利特·星焰"}},{q="为什么塞纳里奥议会要让德鲁伊先手动治疗野兽？",a="德迪利特·星焰强调，德鲁伊在运用轻松的精神魔法之前，必须通过纯粹的劳动和凡人的局限来理解治愈毒素的意义。体验患病生物的困境能教导人们对自然平衡的同理心与尊重。",al={"为什么手动治愈病人","为什么要先用药膏","德鲁伊毒素课程"}},{q="图拉克·符文图腾对十字路口有什么担忧？",a="图拉克深感忧虑地指出，非自然的、具有侵略性的毒素正在被引入十字路口附近的贫瘠之地野生动物体内。他认为这种污染是对土地平衡的严重破坏，需要未来保持警惕。",al={"图拉克对十字路口的担忧","十字路口毒素平衡"}},{q="这个任务联盟德鲁伊可以做吗？",a="联盟德鲁伊会进行一个同名的平行试炼。暗夜精灵新手不是向长者高地的图拉克·符文图腾汇报，而是回到达纳苏斯向玛斯雷·驭熊者汇报来完成课程。",al={"暗夜精灵可以做这个吗","联盟毒素掌控"}}},fp="17,212,21.384.0,24.381.0,34.197.0,33.141.0,42.172.0,70.206.0,51.171.0,43.166.0"}
P.entries["quest:6132"] = {n="救我出去！",s="梅丽萨来到长矛谷，希望与玛洛迪做生意，但他们不肯交谈，她担心他们打算吃掉她。她请求你带她离开那里；她的哥哥霍恩尼兹会给你丰厚的报酬。",h="梅丽萨来到长矛谷，希望与玛洛迪做生意，但他们不肯交谈，她担心他们打算吃掉她。她请求你带她离开那里；她的哥哥霍恩尼兹会给你丰厚的报酬。",kw={"半人马","凄凉之地","霍恩尼兹","科多兽坟场","玛洛迪","梅丽萨","长矛谷"},sec={{t="山谷中的麻烦",b="梅丽萨走进长矛谷，想与玛洛迪谈谈，以为能做成一笔生意。他们不肯交谈，她怀疑他们更想吃掉她。她说，就在几分钟前，她还偷听到半人马在讨论给煮锅添柴的事，她想赶快离开。"},{t="哥哥的营地",b="霍恩尼兹在家族营地等候，营地就在这里的东边，科多兽坟场旁。梅丽萨承诺，只要你带她离开山谷，她的哥哥就会给你丰厚的报酬。"},{t="回到营地",b="霍恩尼兹说，梅丽萨告诉过他你要来，并感谢你帮她摆脱了困境。他猜她已经又惹上了新的麻烦。梅丽萨跑到前面，说玛洛迪太难打交道，她要去找更通情达理的吉尔吉斯。"}},faq={{q="梅丽萨为什么遇到了麻烦？",a="梅丽萨走进长矛谷，希望与玛洛迪做生意。他们不肯交谈，她觉得他们想吃掉她。",al={"梅丽萨为什么被俘","梅丽萨的故事","梅丽萨发生了什么事"}},{q="玛洛迪是谁？",a="玛洛迪是凄凉之地的半人马。梅丽萨前往长矛谷，想试着与他们做生意。",al={"玛洛迪半人马","玛洛迪是谁","玛洛迪氏族"}},{q="霍恩尼兹在哪里？",a="霍恩尼兹在凄凉之地东边、科多兽坟场旁的布瑞布兹家族营地等候。",al={"霍恩尼兹的位置","霍恩尼兹在哪里","霍恩尼兹的营地"}},{q="梅丽萨为什么说她的哥哥会付给你报酬？",a="她承诺，只要你护送她离开山谷，她的哥哥霍恩尼兹就会给你丰厚的报酬。",al={"梅丽萨的奖励","霍恩尼兹给什么报酬"}}},fp="19,153,21.252.0,18.197.0,16.275.1,37.136.0,23.110.0,36.128.0,46.88.0"}
P.entries["quest:6134"] = {n="幽灵电浆",s="霍恩尼兹觉得白骨之谷的鬼魂里藏着商机。他认为玛格拉姆半人马愿意花大价钱购买鬼魂能量，于是他给了你一箱用来引诱鬼魂的幽灵磁铁。",h="霍恩尼兹觉得白骨之谷的鬼魂里藏着商机。他认为玛格拉姆半人马愿意花大价钱购买鬼魂能量，于是他给了你一箱用来引诱鬼魂的幽灵磁铁。",kw={"巨兽残骸","凄凉之地","幽灵磁铁","幽灵质","霍恩尼兹","玛格拉姆","幽灵","白骨之谷"},sec={{t="闹鬼的山谷",b="霍恩尼兹指引你前往东南方的白骨之谷，那里游荡着玛格拉姆的鬼魂。他承认这听起来很吓人，但对玛格拉姆人来说肯定更可怕。他确信在那里收集到的鬼魂能量对那些半人马来说价值连城。"},{t="在巨兽残骸之间",b="他交给你一箱幽灵磁铁。把它放置在山谷中两具巨大的骸骨之间（即所谓的巨兽残骸），磁铁就会引诱鬼魂靠近。从它们身上你可以提取出幽灵质，这正是霍恩尼兹打算卖给玛格拉姆人的东西。他需要你带回八份幽灵质，以及那个箱子。"},{t="满载而归",b="当你回来时，霍恩尼兹注意到你身上沾到了一些幽灵质，并称其为粘糊糊的玩意儿。他认为只要能说服半人马，这东西就能让他发大财。"}},faq={{q="霍恩尼兹是谁？",a="霍恩尼兹在凄凉之地的科多兽坟场西南方设立了一个营地。他想要把鬼魂能量卖给玛格拉姆半人马。",al={"霍恩尼兹","布里姆巴兹","谁发布了搜集幽灵质任务"}},{q="白骨之谷在哪里？",a="霍恩尼兹说白骨之谷在东南方。那两具用来放置磁铁的巨大骸骨——巨兽残骸，就位于山谷的南端。",al={"白骨之谷位置","哪里可以找到鬼魂","巨兽残骸位置"}},{q="霍恩尼兹为什么想要幽灵质？",a="他确信玛格拉姆半人马会花大价钱购买在闹鬼的白骨之谷中捕获的鬼魂能量，而幽灵质正是他打算卖给它们的东西。",al={"为什么要收集鬼魂能量","谁会购买幽灵质","半人马幽灵质"}},{q="幽灵磁铁是如何运作的？",a="将磁铁放置在两具巨兽残骸之间可以吸引山谷里的鬼魂靠近，而这些鬼魂会产生幽灵质。",al={"如何使用幽灵磁铁","在哪里放置幽灵磁铁","吸引玛格拉姆鬼魂"}}},fp="22,111,16.264.0,25.291.0,18.172.1,26.130.0,29.170.0,36.156.0,31.126.0"}
P.entries["quest:6141"] = {n="安东修士",s="克罗雷修士提到了安东修士，那是一位战士同袍。他听说遥远的卡利姆多出现了亡灵，便立刻启程前往消灭它们。安东正在寻找勇敢且坚定的人，他在凄凉之地的尼耶尔前哨站等待着。",h="克罗雷修士提到了安东修士，那是一位战士同袍。他听说遥远的卡利姆多出现了亡灵，便立刻启程前往消灭它们。安东正在寻找勇敢且坚定的人，他在凄凉之地的尼耶尔前哨站等待着。",kw={"安东修士","克罗雷修士","凄凉之地","尼耶尔前哨站","血色","亡灵"},sec={{t="远方的修士",b="克罗雷修士说，关于遥远的卡利姆多大陆上的凄凉之地出现亡灵侵扰的传言传到了安东耳中，他随即动身前往，誓要寻出并消灭这些威胁。安东希望得到那些勇敢且意志坚定的人的帮助。克罗雷告诉你，如果你的内心坚定，就去凄凉之地的联盟城镇尼耶尔前哨站与安东交谈。"},{t="来自东方的消息",b="安东修士已经收到消息说会有援军从东方赶来。他询问你是否就是那些传言的来源，以及你是否是来协助血色十字军的远征的。"}},faq={{q="安东修士是谁？",a="安东修士是克罗雷修士的战友。他听说凄凉之地遭到了亡灵的侵扰，便动身前往那里去消灭它们。",al={"安东是谁","安东修士背景故事","安东 凄凉之地"}},{q="在哪里可以找到安东修士？",a="安东修士位于凄凉之地的联盟城镇尼耶尔前哨站。",al={"安东修士在哪里","安东位置","安东修士地点"}},{q="安东修士为什么去卡利姆多？",a="因为有传言称卡利姆多的凄凉之地遭到了亡灵的侵扰，他随即动身前往那里去消灭它们。",al={"安东为什么在凄凉之地","安东在凄凉之地的任务","安东为什么旅行"}}},fp="13,130,16.292.0,18.168.1,21.138.0,33.75.0,37.108.0"}
P.entries["quest:6142"] = {n="蚌肉鱼饵",s="葬影村的麦拉斯一生都在捕鱼，他说最好的鱼饵是软壳蛤肉，没有任何鱼能抗拒。他想要十份，可以在北边沿海的一艘失事船只附近找到。",h="葬影村的麦拉斯一生都在捕鱼，他说最好的鱼饵是软壳蛤肉，没有任何鱼能抗拒。他想要十份，可以在北边沿海的一艘失事船只附近找到。",kw={"蛤肉鱼饵","凄凉之地","钓鱼鱼饵","麦拉斯","葬影村","失事船只","软壳蛤"},sec={{t="最好的鱼饵",b="麦拉斯一生都在捕鱼，他坚信软壳蛤肉是最好的鱼饵，因为鱼儿无法抗拒它的诱惑。在北边的海岸外有一艘失事船只，那片区域散布着软壳蛤。他请求你带给他十份蛤肉。"},{t="麦拉斯怎么说",b="麦拉斯说巫医给他的头痛建议就是这样：去钓鱼，他就会感觉好些。他确实已经感觉好多了。"}},faq={{q="谁是麦拉斯？",a="麦拉斯是凄凉之地海岸上葬影村的一名渔夫。他一生都在捕鱼。",al={"麦拉斯","谁需要蛤肉鱼饵","葬影村的渔夫"}},{q="去哪里可以找到软壳蛤？",a="在葬影村北面，海岸外的一艘失事船只周围，那里散布着软壳蛤。",al={"蛤肉鱼饵位置","失事船只在哪里","软壳蛤肉位置"}},{q="为什么麦拉斯想要蛤肉？",a="他说软壳蛤肉是最好的鱼饵，鱼儿无法抗拒它。",al={"为什么用蛤肉鱼饵","为什么需要蛤肉"}},{q="麦拉斯需要多少蛤肉？",a="十份蛤肉。",al={"需要多少蛤肉","蛤肉数量"}}},fp="9,160,13.279.0,19.127.1,17.97.0,42.98.0,34.82.0,39.53.0"}
P.entries["quest:6143"] = {n="另一种鱼",s="凄凉之地的葬影村有一位名叫杜泽加尔的渔夫，他在拉纳加尔岛附近捕鱼时，整支船队都被纳迦杀害了。杜泽加尔深感愧疚，他请求你前去对付那些滑刃纳迦。",h="凄凉之地的葬影村有一位名叫杜泽加尔的渔夫，他在拉纳加尔岛附近捕鱼时，整支船队都被纳迦杀害了。杜泽加尔深感愧疚，他请求你前去对付那些滑刃纳迦。",kw={"凄凉之地","杜泽加尔","海妖","纳迦","煎炸纳迦","拉纳加尔岛","葬影村","斯卡格胡克","滑刃","女巫"},sec={{t="失去的船队",b="杜泽加尔和他的船员们经常在海岸边一处沉船残骸北面的拉纳加尔岛附近捕鱼。一天早上，纳迦发动了袭击，除了杜泽加尔外，所有人都丧生了。自那以后，杜泽加尔满脑子想的都是复仇，且深感愧疚，痛苦不堪。"},{t="煎炸纳迦",b="杜泽加尔想要消灭七个滑刃海妖、七个滑刃纳迦和五个滑刃女巫。杜泽加尔因为膝盖有伤，无法亲自前去。他说，纳迦通常潜伏在海浪下的珊瑚礁深处，如果你能完成任务，他定会重谢。"}},faq={{q="杜泽加尔是谁？",a="他是凄凉之地葬影村的一名渔夫。他的船队在拉纳加尔岛附近被纳迦杀害，他是唯一的幸存者。",al={"杜泽加尔","谁发布了煎炸纳迦任务"}},{q="杜泽加尔的船队在哪里遇袭？",a="在拉纳加尔岛旁边，海岸上一处沉船残骸的北面。船员们经常在那里捕鱼，直到一天早上纳迦发动了袭击。",al={"渔夫在哪里遇袭","船队遇袭地点","拉纳加尔岛伏击"}},{q="为什么杜泽加尔不亲自去对付纳迦？",a="杜泽加尔膝盖有伤，他说如果不是因为这样，他一定会帮你去杀纳迦。失去船员的愧疚让他深受折磨。",al={"为什么杜泽加尔不能战斗","杜泽加尔膝盖有伤"}},{q="滑刃纳迦潜伏在哪里？",a="杜泽加尔说它们通常潜伏在海浪下的珊瑚礁深处。船队遇袭的地点就在拉纳加尔岛附近。",al={"滑刃纳迦位置","哪里寻找滑刃纳迦","凄凉之地纳迦位置"}},{q="杜泽加尔想要消灭哪些纳迦？",a="七个滑刃海妖、七个滑刃纳迦和五个滑刃女巫。",al={"需要杀掉哪些纳迦","煎炸纳迦任务目标","滑刃纳迦任务要求"}}},fp="17,164,11.247.0,12.274.0,27.160.0,48.132.0,45.180.0,36.137.0,42.110.0"}
P.entries["quest:616"] = {n="幽灵岛",s="克拉兹克代表大财主里维加兹，在藏宝海湾四处打探各种不同寻常的流言。酒馆水手们分享的一个故事提到了离岸的一座闹鬼岛屿，岛上居住着水元素，还有一个语无伦次的鬼魂地精。将这个流言传达给大财主里维加兹，引起了他对一个古老巨魔传说的兴趣。",h="克拉兹克代表大财主里维加兹，在藏宝海湾四处打探各种不同寻常的流言。酒馆水手们分享的一个故事提到了离岸的一座闹鬼岛屿，岛上居住着水元素，还有一个语无伦次的鬼魂地精。将这个流言传达给大财主里维加兹，引起了他对一个古老巨魔传说...",kw={"大财主里维加兹","藏宝海湾","地精鬼魂","克拉兹克","海潮之石","荆棘谷","巨魔传说","水元素"},sec={{t="藏宝海湾的酒馆故事",b="在繁忙的藏宝海湾港口，克拉兹克受大财主里维加兹之托，搜集荆棘谷各地发生的任何异常消息。虽然克拉兹克通常不太在意鬼怪流言，但当地酒馆里水手们的谈话引起了他的注意。他们谈到了一座被水元素占据且有语无伦次的地精鬼魂出没的离岸岛屿，于是他请你将这个故事转达给大财主。"},{t="一个巨魔传说",b="听到克拉兹克关于闹鬼岛屿的报告后，大财主里维加兹回忆起他曾在一本书中读到的一个古老巨魔传说。水元素和地精鬼魂的出现让大财主怀疑，一件古代圣物“海潮之石”可能终于可以被他收入私人藏品中了。"}},faq={{q="是谁派你去和大财主里维加兹谈话的？",a="在藏宝海湾酒馆听到当地水手讲述了一个不安的故事后，克拉兹克请你将这个流言转达给大财主里维加兹。",al={"谁发布了闹鬼岛屿任务","闹鬼岛屿任务发布者","克拉兹克的流言"}},{q="水手们分享了什么流言？",a="水手们报告称，离岸有一座岛屿到处都是水元素，还有一个语无伦次的地精鬼魂在那里徘徊。",al={"岛上有什么","闹鬼岛屿流言","水手故事"}},{q="为什么大财主里维加兹关心鬼故事？",a="大财主回想起一本旧书中记载的巨魔传说。岛上奇怪的描述暗示，一件被称为“海潮之石”的远古圣物可能真的就在那里。",al={"为什么里维加兹想知道","里维加兹的反应","对海潮之石的兴趣"}},{q="这项调查接下来会指向哪里？",a="大财主里维加兹将你的注意力转向圣物本身，在下一步“海潮之石”中继续追寻。",al={"下一个任务是什么","闹鬼岛屿后续","闹鬼岛屿之后的步骤"}}},fp="16,159,25.358.0,14.275.0,43.121.0,34.114.0,49.133.0,40.86.0"}
P.entries["quest:6161"] = {n="拉克摩尔的财宝！",s="拉克摩尔的航海日志中提到，一艘开往羽月要塞的船只遭到了海洋生物的袭击。为了不让敌人得到财宝，拉克摩尔将箱子藏在了拉纳加尔岛上，而开启箱子的拉克摩尔的金钥匙和拉克摩尔的银钥匙却下落不明。",h="拉克摩尔的航海日志中提到，一艘开往羽月要塞的船只遭到了海洋生物的袭击。为了不让敌人得到财宝，拉克摩尔将箱子藏在了拉纳加尔岛上，而开启箱子的拉克摩尔的金钥匙和拉克摩尔的银钥匙却下落不明。",kw={"箱子","凄凉之地","羽月要塞","金钥匙","拉克摩尔","拉纳加尔岛","银钥匙"},sec={{t="隐藏的箱子",b="航海日志里写着，当拉克摩尔的船只在前往羽月要塞的途中遭到海洋生物袭击时，为了不让敌人得到财宝，他将箱子藏在了拉纳加尔岛上。开启箱子需要两把钥匙，一把银钥匙和一把金钥匙，两把钥匙都已丢失。如果有人能找到钥匙和箱子，就能获得财宝。"}},faq={{q="拉克摩尔的船只在遭到袭击时正航向何处？",a="他的日志记载，他的船在前往羽月要塞的途中遭到了海洋生物的袭击。",al={"拉克摩尔目的地","拉克摩尔要去哪里","拉克摩尔航线"}},{q="拉克摩尔的箱子藏在哪里？",a="在拉纳加尔岛上，那是拉克摩尔藏匿箱子的地方。",al={"拉克摩尔的箱子在哪里","拉克摩尔箱子位置","拉纳加尔岛箱子"}},{q="开启箱子需要什么？",a="两把钥匙，拉克摩尔的银钥匙和拉克摩尔的金钥匙。两把钥匙都已丢失。",al={"拉克摩尔箱子钥匙","如何打开拉克摩尔的箱子","开启拉克摩尔箱子的物品"}},{q="拉克摩尔为什么要藏起他的财宝？",a="他的船受到了攻击，为了不让财宝落入敌人之手，他将箱子藏在了拉纳加尔岛上。",al={"为什么要隐藏拉克摩尔的财宝","拉克摩尔财宝动机"}}},fp="26,220,14.295.0,55.94.0,33.40.0,35.79.0,35.122.0"}
P.entries["quest:6162"] = {n="最后一战",s="在费伍德森林的血毒岗哨，Dreka'Sur寻求向Overlord Ror复仇。她要你击败那个蛮兽，并把它斩下的利爪带回岗哨。",h="在费伍德森林的血毒岗哨，Dreka'Sur寻求向Overlord Ror复仇。她要你击败那个蛮兽，并把它斩下的利爪带回岗哨。",kw={"血毒岗哨","利爪","dreka'sur","费伍德森林","overlord ror"},sec={{t="鲜血与利爪",b="在费伍德森林的毒林中，Dreka'Sur在血毒岗哨等待复仇。她要你追猎Overlord Ror，并带回它被斩下的利爪作为行动的凭证。"}},faq={{q="Dreka'Sur是谁？",a="Dreka'Sur是一名驻扎在费伍德森林血毒岗哨的兽人，她一心要杀死Overlord Ror。",al={"dreka'sur是谁","dreka'sur 费伍德森林","谁给了这个任务"}},{q="血毒岗哨在哪里？",a="血毒岗哨是部落在受腐化的费伍德森林中建立的一处营地。",al={"血毒岗哨在哪里","血毒岗哨位置"}},{q="Overlord Ror是谁？",a="Overlord Ror是一个令人胆寒的生物，Dreka'Sur要求带回它的利爪作为它已毙命的凭证。",al={"ror是谁","overlord ror 费伍德森林"}}},fp="23,159,14.181.0,17.96.0,25.85.0,20.88.0"}
P.entries["quest:617"] = {n="一捆海蛇草",s="藏宝海湾的海盗布劳兹正在寻找一批珍贵的阿基里斯芦苇，送给一位名叫格罗伊的同伙。这些植物必须从纳迦手中夺取，最后一次有人见到他们是在北边的海滩上。",h="藏宝海湾的海盗布劳兹正在寻找一批珍贵的阿基里斯芦苇，送给一位名叫格罗伊的同伙。这些植物必须从纳迦手中夺取，最后一次有人见到他们是在北边的海滩上。",kw={"阿基里斯芦苇","藏宝海湾","格罗伊","纳迦","海盗布劳兹","芦苇","荆棘谷"},sec={{t="一种有利可图的海洋植物",b="海盗布劳兹在藏宝海湾为愿意从事海滨冒险的人提供工作。一位名叫格罗伊的同伙出高价收购阿基里斯芦苇，这是一种生长在海边、被纳迦称为这个名字的芦苇。布劳兹不知道格罗伊为什么要这些芦苇，只知道需要十株，而且纳迦最后一次出现是在北边的海滩上。"}},faq={{q="谁是海盗布劳兹？",a="海盗布劳兹是藏宝海湾的一名私掠者，他为那些寻求工作的人提供机会。",al={"布劳兹","谁发布阿基里斯芦苇任务","布劳兹是谁"}},{q="什么是阿基里斯芦苇？",a="阿基里斯芦苇是纳迦对一种珍贵海洋芦苇的称呼。虽然海盗布劳兹不知道其确切用途，但收藏家们愿意出高价购买这种芦苇。",al={"阿基里斯芦苇","什么是阿基里斯芦苇","阿基里斯芦苇的用途"}},{q="哪里可以找到持有芦苇的纳迦？",a="持有芦苇的纳迦在藏宝海湾以北，沿着荆棘谷的海岸线徘徊。",al={"纳迦在哪里","哪里获得阿基里斯芦苇","阿基里斯芦苇位置"}},{q="谁从海盗布劳兹那里购买芦苇？",a="布劳兹代表一位名叫格罗伊的同伙收集这些芦苇，格罗伊通过出售这些收获的海洋芦苇赚取了可观的利润。",al={"格罗伊是谁","谁需要阿基里斯芦苇","布劳兹的买家"}}},fp="20,169,24.293.0,24.78.0,23.161.0,46.105.0,41.114.0"}
P.entries["quest:618"] = {n="挑战奈古拉什",s="追踪着海克拜瑞·斯莫特船长丢失武器的线索，斯普罗格揭露了一个计划：利用那头巨兽最爱的佳肴来诱捕巨大的内戈拉什。通过在荆棘谷海岸的一艘遇难救生艇上摆下一场宴席，冒险者们可以引出这头野兽，夺回船长被偷走的弯刀。",h="追踪着海克拜瑞·斯莫特船长丢失武器的线索，斯普罗格揭露了一个计划：利用那头巨兽最爱的佳肴来诱捕巨大的内戈拉什。通过在荆棘谷海岸的一艘遇难救生艇上摆下一场宴席，冒险者们可以引出这头野兽，夺回船长被偷走的弯刀。",kw={"荒芜之地","秃鹫翅膀","斯莫特船长","密林葡萄酒","内戈拉什","斯莫特的弯刀","斯普罗格","荆棘谷"},ang={["profession:Cooking"]="整个计划都依赖于斯普罗格的烹饪手艺，特别是那道他远赴荒芜之地才学会的烤秃鹫翅膀的特制配方。"},sec={{t="饥饿的巨人",b="当巨人们摧毁了斯莫特船长的船只时，一头名叫内戈拉什的野兽径直冲向了厨房。与他的同类不同，他想要的并非船员，而是食物。斯普罗格发现内戈拉什想要的是葡萄酒和烤秃鹫翅膀——这是斯普罗格的独门秘制配方，他甚至为了学习这道菜专门去了一趟荒芜之地。"},{t="救生艇上的陷阱",b="为了诱捕这头巨人，斯普罗格设计了一场令人无法抗拒的盛宴。冒险者必须将十份烤秃鹫翅膀和五瓶葡萄酒搬到位于东南海岸线的船长失事救生艇上。被宴席气味吸引的内戈拉什将自投罗网，冒险者可以将他击杀，并剥取船长的宝剑。"}},faq={{q="内戈拉什是谁？",a="内戈拉什是一头饥饿的巨人，他参与了摧毁斯莫特船长船只的行动。他没有去猎杀船员，而是洗劫了船上的厨房，搜刮食物和酒水。",al={"什么是内戈拉什","巨人是谁","内戈拉什背景故事"}},{q="为什么斯普罗格知道如何诱捕内戈拉什？",a="斯普罗格目睹了巨人在沉船时洗劫他的厨房。内戈拉什表现出对斯普罗格的烤秃鹫翅膀和密林葡萄酒的执着，这使得这些储备成为了理想的诱饵。",al={"如何诱捕内戈拉什","为什么选择秃鹫翅膀","内戈拉什的食物"}},{q="对决在哪里进行？",a="宴席必须摆放在斯莫特船长那艘古老的废弃救生艇中，它搁浅在斯普罗格位置东南方的海岸线上。",al={"内戈拉什在哪里","食物放在哪里","救生艇位置"}},{q="这项任务之前发生了什么？",a="这场对决是一条任务线的终点，这条线索始于“绣字腰带”，并延续至“船长的弯刀”。",al={"前置任务是什么","面对内戈拉什之前的任务","内戈拉什的前置条件"}}},fp="15,155,14.228.0,24.259.0,16.133.0,44.185.0,40.110.0,27.113.0"}
P.entries["quest:6181"] = {n="快递消息",s="哨兵岭的军需官刘易斯急需从暴风城运送护甲，以装备人民民兵。由于西部荒野几乎得不到任何官方的军事援助，他派遣你去找狮鹫管理员索尔，将一份紧急征用说明通过航空送往首都。",h="哨兵岭的军需官刘易斯急需从暴风城运送护甲，以装备人民民兵。由于西部荒野几乎得不到任何官方的军事援助，他派遣你去找狮鹫管理员索尔，将一份紧急征用说明通过航空送往首都。",kw={"护甲","飞行管理员","狮鹫","old town","奥斯瑞克·斯图恩","人民民兵","军需官刘易斯","哨兵岭","暴风城","索尔"},ang={["faction:Alliance"]="这次差事揭示了宏伟的暴风城首都与其在西部荒野苦苦挣扎的边境哨所之间深重的后勤断层。",["race:Human"]="对于王国的居民（人类）来说，携带刘易斯的信件凸显了暴风城各省的紧张局势，并介绍了连接家园领土的重要狮鹫航线。"},sec={{t="天际的呼唤",b="哨兵岭在迪菲亚兄弟会暴徒和豺狼人的威胁下孤立无援，极度缺乏来自暴风城的直接军事援助。军需官刘易斯依靠在首都的私人关系来维持人民民兵的武器和护甲补给。装备即将耗尽，他唯一的救命稻草是位于Old Town的护甲商奥斯瑞克·斯图恩。将紧急征用说明送到他手中需要快速的交通，因此刘易斯请求旅行者联系西部荒野的狮鹫管理员索尔。"},{t="飞行网络",b="狮鹫为暴风王国提供了一套极其宝贵的快速交通和信使网络。索尔驻守在哨兵岭，负责管理该哨站与首都之间的空中联络。将刘易斯的信件交给索尔便开启了西部荒野与王城之间的空中航线，这证明了狮鹫骑士对于维持那些无法获得正式援助的边境哨所而言是何等重要。"}},faq={{q="军需官刘易斯为什么要给暴风城送信？",a="西部荒野从暴风城政府得到的直接军事援助很少，导致人民民兵的护甲严重短缺。刘易斯必须联系城内的一位可靠商人，即奥斯瑞克·斯图恩，以确保获得新的补给。",al={"为什么送信","刘易斯的信件目的","为什么要联系暴风城"}},{q="谁是奥斯瑞克·斯图恩？",a="奥斯瑞克·斯图恩是一位护甲商，他的商店“有限免疫”（Limited Immunity）位于暴风城的Old Town。当官方渠道失效时，他就是刘易斯可靠的私人供货商。",al={"奥斯瑞克·斯图恩","谁是奥斯瑞克","有限免疫店主"}},{q="谁是索尔？",a="索尔是驻守在哨兵岭的狮鹫管理员。他负责管理连接西部荒野和暴风城的飞行坐骑，从而实现快速的信使传送和旅行。",al={"谁是索尔","西部荒野飞行管理员","狮鹫管理员索尔"}},{q="为什么暴风城不直接向西部荒野派遣士兵和提供装备？",a="随着瓦里安·乌瑞恩国王失踪，资源捉襟见肘，暴风城的领导层在很大程度上忽视了偏远的农田。像哨兵岭这样的边境哨所必须依靠志愿民兵和私人安排来生存。",al={"为什么没有暴风城的援助","为什么暴风城忽视西部荒野","军队在哪里"}},{q="任何冒险者都能承担这个任务吗？",a="这一任务专门委托给在西部荒野证明了自己的冒险者，作为人类使用王国狮鹫飞行网络的入门介绍。",al={"谁能接受这个任务","人类专属任务","矮人能做这个任务吗"}},{q="这个送信任务接下来要去哪里？",a="将信件交给索尔后，他会安排一次直飞暴风城的狮鹫航程，你将在首都的Gryphon Roost降落，然后前往Old Town寻找奥斯瑞克·斯图恩。",al={"下一步","找过索尔后会发生什么","我接下来去哪"}}},fx={be76534e={q="军需官刘易斯为什么要你帮他送信？",a="西部荒野的守军捉襟见肘，被王室弃之不顾，还遭到遍布平原的迪菲亚暴徒围攻。军需官刘易斯不能离开哨兵岭的补给站，而人民民兵也无法抽调宣誓效忠的守卫去当普通信使，因为防线上每一把武器都不可或缺。一位正前往首都的可靠旅人，能以最快、最安全的方式安排重要补给，同时不让哨站人手短缺。",al={"刘易斯为什么需要我","为什么不派卫兵去暴风城","为什么要送刘易斯的信"}}},fp="15,244,23.376.0,18.312.0,62.196.0,20.146.0,12.149.0,67.224.0,39.130.0,42.155.0"}
P.entries["quest:619"] = {n="引诱奈古拉什",s="在荆棘谷的海岸边，停留着一艘废弃的救生艇，上面刻着已经模糊不清的字样：斯莫茨的复仇号。将烤秃鹫翅膀和密林葡萄酒堆放在这艘残骸上，便能引诱出巨兽尼格拉什。",h="在荆棘谷的海岸边，停留着一艘废弃的救生艇，上面刻着已经模糊不清的字样：斯莫茨的复仇号。将烤秃鹫翅膀和密林葡萄酒堆放在这艘残骸上，便能引诱出巨兽尼格拉什。",kw={"烤秃鹫翅膀","密林葡萄酒","尼格拉什","废弃的救生艇","斯莫茨的复仇号","荆棘谷"},sec={{t="诱人的祭品",b="这艘小船的残骸被遗弃在此，上面仅留着一行风化的刻字，写着斯莫茨的复仇号。为了在狩猎尼格拉什的过程中吸引它的注意，必须将这艘船变成诱饵，堆上十份烤秃鹫翅膀和五瓶密林葡萄酒。"}},faq={{q="什么是废弃的救生艇？",a="这是一艘废弃的破船，上面刻着模糊的斯莫茨的复仇号字样，被用作放置食物和饮料的平台，以引诱尼格拉什。",al={"斯莫茨的复仇号小船","荆棘谷救生艇","什么是斯莫茨的复仇号"}},{q="祭品需要什么物资？",a="祭品需要十份烤秃鹫翅膀以及五瓶密林葡萄酒，并将它们直接堆叠在船骸上。",al={"需要什么食物","诱人的尼格拉什物品","尼格拉什需要什么物品"}},{q="这项任务何时可以进行？",a="这项祭品只能在进行狩猎并面对尼格拉什的任务期间准备。",al={"什么时候可以做诱人的尼格拉什","面对尼格拉什的前提条件","如何解锁诱人的尼格拉什"}}},fp="17,164,19.187.0,28.148.0,46.108.0,37.57.0"}
P.entries["quest:62"] = {n="法戈第矿洞",s="闪金镇的治安官杜汉指派侦察兵去调查有关法戈第矿洞被狗头人占领的报告。该矿洞位于城镇南部的斯通菲尔德农场和马科伦农场之间，它的陷落预示着整个艾尔文森林的虫害问题正在加剧。",h="闪金镇的治安官杜汉指派侦察兵去调查有关法戈第矿洞被狗头人占领的报告。该矿洞位于城镇南部的斯通菲尔德农场和马科伦农场之间，它的陷落预示着整个艾尔文森林的虫害问题正在加剧。",kw={"杜汉","艾尔文","法戈第","闪金镇","玉石矿洞","狗头人","马科伦","斯通菲尔德"},ang={["faction:Alliance"]="矿洞的失守是暴风城在艾尔文森林统治力下降的又一个明显迹象，当地守卫正努力保护重要的基础设施。",["profession:Mining"]="法戈第矿洞内丰富的铜矿脉对初级铁匠至关重要，但开采它们需要清理掉领地意识极强的狗头人。"},sec={{t="闪金镇南部的麻烦",b="当北郡山谷还在处理自身的害虫问题时，令人不安的报告传到了闪金镇，称狗头人已经占据了另一个重要据点。法戈第矿洞坐落在镇南面互相争斗的斯通菲尔德和马科伦农场之间，曾经是该地区石料和矿石的来源。如今，潮湿的隧道里充斥着尖锐的叽叽喳喳声和摇曳的牛脂烛光，促使治安官杜汉派遣冒险者前去侦察矿洞深处，以确认最糟糕的情况。"},{t="紧张的卫兵",b="确认了虫害情况只会让暴风城卫队更加头疼。由于正规部队忙于防范迪菲亚兄弟会的强盗和豺狼人的入侵，人手捉襟见肘，守卫无法直接清理矿洞。在得到确认后，杜汉那阴沉的反应凸显了核心地带控制权的逐渐丧失，这让他立刻开始担忧东北方向像玉石矿洞那样的其他矿点。"}},faq={{q="法戈第矿洞在哪里？",a="法戈第矿洞位于艾尔文森林闪金镇的正南方，就在斯通菲尔德农场和马科伦农场之间。",al={"法戈第位置","法戈第矿洞在哪里","法戈第矿洞地图"}},{q="谁派你去侦察法戈第矿洞？",a="驻扎在闪金镇的暴风城卫队指挥官治安官杜汉，将侦察隧道任务交给了你。",al={"谁发布法戈第任务","治安官杜汉任务"}},{q="什么生物占领了矿洞？",a="矿洞已经被狗头人完全占领，它们在里面扎根，点燃蜡烛，并驱逐了人类工人。",al={"法戈第里有什么","法戈第里的怪物"}},{q="为什么治安官杜汉需要冒险者去检查矿洞？",a="暴风城卫队为了应对当地的强盗、兽人残党和豺狼人突袭已经疲于奔命，杜汉连派遣士兵去核实常规侦察报告的人手都抽调不出来。",al={"为什么要派侦察兵","为什么守卫不亲自去"}},{q="侦察法戈第矿洞后会发生什么？",a="当你向治安官杜汉报告这个坏消息后，他担心问题已经扩散，并派遣你去东北方向调查玉石矿洞。",al={"法戈第之后的任务","接下来是什么"}},{q="为什么法戈第矿洞的虫害如此严重？",a="法戈第矿洞的陷落证明北郡的狗头人虫害并非孤立事件。这显示了野外威胁正以何等速度侵蚀暴风城门外已经定居的农田。",al={"为什么法戈第很重要","法戈第矿洞背景故事"}}},fx={["88321243"]={q="狗头人为什么占据了法戈第矿洞？",a="狗头人天生就栖居在地道中，不断寻找地下的黄金和珍贵矿物。暴风城的卫兵忙于保护这片地区，抵御迪菲亚匪徒和野兽，人手捉襟见肘，当地的矿洞几乎无人防守。丰富的矿藏和黄金引来了这些害物，它们蜂拥而入，占据法戈第矿洞深处，赶走了所有工人。",al={"狗头人为什么在法戈第矿洞","狗头人占据法戈第矿洞的原因","法戈第矿洞里有谁"}}},fp="18,186,26.319.0,16.294.0,36.118.0,42.102.0,40.83.0,59.156.0,47.133.1,53.184.0"}
P.entries["quest:621"] = {n="赞吉尔的秘密",s="在藏宝海湾，地精克兰克·菲兹巴布看中了被放逐的巨魔赞吉尔所酿造的一种强效混合剂。赞吉尔利用这种植物混合物来控制附近丛林废墟中追随者的思想，并增强他们的体质。菲兹巴布认为这种物质对于任何想要控制他人的人来说都极具价值，因此他想要获得一些样本供自己使用。",h="在藏宝海湾，地精克兰克·菲兹巴布看中了被放逐的巨魔赞吉尔所酿造的一种强效混合剂。赞吉尔利用这种植物混合物来控制附近丛林废墟中追随者的思想，并增强他们的体质。菲兹巴布认为这种物质对于任何想要控制他人的人来说都极具价值，因此...",kw={"阿博拉兹","藏宝海湾","菲兹巴布","朱布瓦尔","混合剂","荆棘谷","赞吉尔"},sec={{t="精神控制药剂",b="在藏宝海湾东北方，名为赞吉尔的被放逐巨魔在朱布瓦尔废墟和阿博拉兹建立了一个避难所。他因被部落领袖忌惮其对他人的精神控制能力而被放逐，如今赞吉尔完全通过从丛林植物中提取的混合剂来指挥着一群追随者。这些混合剂在增强他们体力的同时消磨了他们的意志，将他们变成了温顺而强壮的奴隶。"},{t="一种有利可图的混合剂",b="克兰克·菲兹巴布从这位流亡者的技艺中看到了明显的商机。任何想要控制他人的人都会为这种药剂付出高昂的代价，这促使这名地精直接从废墟中寻求供应。只要运送者对这笔交易守口如瓶，交付足够的样本不仅能获得常规的金币报酬，还能获得一笔额外的封口费。"}},faq={{q="谁是被放逐者赞吉尔？",a="赞吉尔是一位居住在藏宝海湾东北部废墟中的被放逐巨魔。他之前的领袖因恐惧他对他人的精神控制能力而将他流放。",al={"谁是赞吉尔","赞吉尔背景故事","赞吉尔为何被放逐"}},{q="赞吉尔的药剂究竟有什么作用？",a="这种混合剂由原生丛林植物酿制而成，它能摧毁并压制饮用者的自由意志，同时不自然地增强他们的体力。",al={"什么是赞吉尔的药剂","赞吉尔药剂的效果","赞吉尔药水效果"}},{q="赞吉尔居住在哪里？",a="赞吉尔和他的追随者居住在位于荆棘谷、藏宝海湾东北部的朱布瓦尔废墟和阿博拉兹。",al={"赞吉尔位置","赞吉尔在哪里","废墟在哪里"}},{q="为什么克兰克·菲兹巴布想要这种混合剂？",a="克兰克·菲兹巴布认为，这种混合剂在那些想要控制他人的人群中能卖出高价，他打算寻找它的用途。",al={"克兰克为何想要混合剂","克兰克将如何使用赞吉尔的药剂"}},{q="为什么克兰克在交付时支付了额外费用？",a="克兰克提供额外的奖金明确是为了换取谨慎，确保这种精神控制药剂的获取过程保持为一项私人的商业事务。",al={"克兰克·菲兹巴布的额外报酬","克兰克的封口费"}}},fp="15,171,21.317.0,19.270.0,26.143.0,39.111.0,25.111.0,42.122.0,38.100.1"}
P.entries["quest:622"] = {n="向卡雷布下士回报",s="克拉兹克已经修好了锅，还加装了一个蒸汽哨，并在底部安装了一个新的斩骨刀，可以轻易切开腿骨。现在这口锅必须送回给反抗军营地的卡雷布下士。",h="克拉兹克已经修好了锅，还加装了一个蒸汽哨，并在底部安装了一个新的斩骨刀，可以轻易切开腿骨。现在这口锅必须送回给反抗军营地的卡雷布下士。",kw={"藏宝海湾","卡雷布下士","炖锅","克拉兹克","反抗军营地","荆棘谷"},sec={{t="更好的锅",b="克拉兹克已经完成了你送来的锅的修理工作。它现在多了一个蒸汽哨，底部还装了一把可以切开腿骨的新斩骨刀。克拉兹克称它是大厨的绝对心头好，相信主人一定会满意。必须把它送回给反抗军营地的卡雷布下士。"},{t="回到营地",b="卡雷布很高兴看到这口锅又能用了，因为晚饭终于可以开火了。卡雷布随后询问你在藏宝海湾过得如何，称那里是个混乱的城镇，并传达了一个谣言：地精有时会把醉酒的水手拖走，送上驶向未知地点的奴隶船。"}},faq={{q="卡雷布下士是谁？",a="卡雷布下士在反抗军营地，等待着藏宝海湾的克拉兹克修理好的烹饪锅。",al={"卡雷布下士","卡雷布是谁","卡雷布 反抗军营地","卡雷布下士在哪","卡雷布位置"}},{q="克拉兹克对这口锅做了什么？",a="克拉兹克修复了它，然后加装了第二个蒸汽哨，并在底部安装了一把可以切断腿骨的斩骨刀。",al={"克拉兹克的锅升级","克拉兹克修理了什么","克拉兹克的炖锅"}},{q="这一步之前发生了什么？",a="首先完成了克拉兹克的请求。",al={"前置任务","是什么导致了回到卡雷布下士任务"}}},fp="24,146,12.312.0,16.265.1,22.98.0,30.132.0,27.28.0"}
P.entries["quest:623"] = {n="一捆海蛇草",s="位于荆棘谷的海盗布劳兹需要将一捆新鲜的阿基里斯芦苇运过大海，送往尘泥沼泽。他的联络人水手格罗伊在塞拉摩岛有一位客户，急需更多的芦苇，而布劳兹自己要过一周才会启程前往那里。",h="位于荆棘谷的海盗布劳兹需要将一捆新鲜的阿基里斯芦苇运过大海，送往尘泥沼泽。他的联络人水手格罗伊在塞拉摩岛有一位客户，急需更多的芦苇，而布劳兹自己要过一周才会启程前往那里。",kw={"阿基里斯","布劳兹","尘泥","格罗伊","海盗","芦苇","荆棘谷","塞拉摩"},ang={["faction:Alliance"]="塞拉摩岛是尘泥沼泽的一座联盟据点，不过海盗布劳兹警告说，如果游客属于不招人待见的那类人，在这里依然会遇到麻烦。"},sec={{t="前往塞拉摩的航程",b="你离开的时候，海上传来了消息。塞拉摩岛的水手格罗伊给海盗布劳兹捎来口信，表示对之前那批阿基里斯芦苇很满意，并提到有客户急需更多货源。由于布劳兹计划在一周后才会启航前往尘泥沼泽，他便将这捆芦苇托付给你，让你亲自送达。"},{t="码头交货",b="水手格罗伊在塞拉摩的码头上等待着。虽然一开始对陌生人表现得有些冷淡，但在得知是布劳兹安排的送货后，格罗伊仔细检查了货物。他对芦苇的品质感到满意，付了一些钱作为跑腿费，并立刻警告旅客不要在他的码头附近闲逛。"}},faq={{q="水手格罗伊是谁？",a="水手格罗伊是尘泥沼泽塞拉摩岛上的一名海盗布劳兹的联络人，有一位客户想要更多的阿基里斯芦苇。",al={"谁是格罗伊","格罗伊 塞拉摩","水手格罗伊"}},{q="为什么海盗布劳兹需要一名信使？",a="布劳兹收到消息，格罗伊有一位急切的买家正在等待另一捆阿基里斯芦苇。由于布劳兹计划在一周后才会启航前往尘泥沼泽，他只能依靠旅行者立即出发进行运送。",al={"为什么要运送芦苇","为什么要塞拉摩","布劳兹的送货"}},{q="这批货物需要送到哪里？",a="这捆芦苇必须通过海路运往塞拉摩岛，那是一座位于尘泥沼泽的联盟港口。",al={"把芦苇带到哪里","阿基里斯交付地点","尘泥沼泽交付"}},{q="这次行程之前发生了什么？",a="这次运送是在荆棘谷的初步采集工作之后进行的，在那之前，人们采集了阿基里斯芦苇并将其带给了海盗布劳兹。",al={"前置任务","阿基里斯芦苇任务线","先决条件"}}},fp="20,209,23.311.0,21.279.1,22.128.0,41.182.0,36.77.0,30.127.0"}
P.entries["quest:624"] = {n="科泰罗的谜题",s="在一张于蛮荒海岸的血帆海盗船只上发现的隐藏羊皮纸上，记录着科泰罗那晦涩难懂的诗句。解开这首诗的谜题将指引旅行者去寻找那座华丽桥梁下所隐藏的线索。",h="在一张于蛮荒海岸的血帆海盗船只上发现的隐藏羊皮纸上，记录着科泰罗那晦涩难懂的诗句。解开这首诗的谜题将指引旅行者去寻找那座华丽桥梁下所隐藏的线索。",kw={"血帆海盗","桥","科泰罗","谜题","卷轴","悲伤沼泽","蛮荒海岸"},sec={{t="海盗的谜题",b="在停泊于荆棘谷南海岸的血帆舰队船只上，散落着写有诗句的笔记。科泰罗的诗句描述了一座做工精细、人来人往的桥梁，它位于逆风小径以东，赤脊山以南。任何想要解开这个谜团的人都必须遵循诗中的指引，走出丛林，进入沼泽，去寻找那桥下之物。"},{t="沼泽之渡",b="循着诗句的指引，会来到悲伤沼泽中一座横跨于浑浊水面之上的华丽桥梁下方。在桥底静静躺着一张浸湿的羊皮纸，等待着揭示科泰罗谜题的下一步。"}},faq={{q="这个谜团从哪里开始？",a="谜题始于一张羊皮纸碎片，它是从停泊在藏宝海湾以南、蛮荒海岸外的血帆海盗舰队周围发现的。",al={"科泰罗的谜题从哪里开始","科泰罗的谜题起始位置","科泰罗的谜题在哪里能找到"}},{q="谜题描述了什么地点？",a="这首诗指向位于悲伤沼泽的一座人来人往的华丽桥梁，它地处逆风小径以东，赤脊山以南。",al={"科泰罗的谜题中是哪座桥","谜题指向哪里","逆风小径以东赤脊山以南的桥"}},{q="你在桥下寻找什么？",a="谜题中说桥下有东西在等待着，那是一个在那里停留了无数个日夜的暗示或线索。",al={"你在悲伤沼泽中找到了什么","科泰罗桥下的线索","桥下有什么"}},{q="谁写下了这个谜题？",a="这个谜题以科泰罗之名流传，但羊皮纸上并未提及关于他身份的更多信息。",al={"谁是科泰罗","科泰罗背景故事","谁制作了科泰罗的谜题"}}},fp="17,163,20.319.0,18.160.1,30.131.0,41.134.0,46.55.0,21.87.0"}
P.entries["quest:625"] = {n="科泰罗的谜题",s="循着在悲伤沼泽中发现的一份浸水的羊皮纸所留下的线索，第二段神秘的诗句指引旅行者前往卡利姆多的一片遥远之地。解读这些诗句会将寻宝者引向尘泥沼泽西南方的一个洞穴。",h="循着在悲伤沼泽中发现的一份浸水的羊皮纸所留下的线索，第二段神秘的诗句指引旅行者前往卡利姆多的一片遥远之地。解读这些诗句会将寻宝者引向尘泥沼泽西南方的一个洞穴。",kw={"鲜血沼泽墓穴","科泰罗","科泰罗的谜题","尘泥沼泽","发霉的卷轴","浸湿的卷轴","荆棘谷"},sec={{t="指向海对岸的诗句",b="Cortello留下的第二段诗句指引寻找者前往遥远的卡利姆多大陆。这首诗描述了一片位于贫瘠之地东侧、危险而阴郁的区域：潮湿且险恶的尘泥沼泽。"},{t="西南方的洞穴",b="根据谜题，线索就藏在沼泽西南方的一个洞穴里。"},{t="诗句指引何处",b="沼泽西南方的洞穴就是鲜血沼泽墓穴，一份发霉的卷轴就在那里等待被发现。"}},faq={{q="这个谜题把旅行者引向何处？",a="这首诗把寻找者引向卡利姆多，具体来说是位于贫瘠之地东侧的尘泥沼泽。",al={"科泰罗的谜题去哪","科泰罗第二部分位置","第二个谜题线索在哪里"}},{q="线索藏在尘泥沼泽的什么地方？",a="诗句指出线索位于沼泽西南方的一个洞穴中。",al={"尘泥沼泽的洞穴在哪里","尘泥沼泽谜题洞穴","鲜血沼泽墓穴谜题"}},{q="什么物品开启了这一步线索？",a="这一步始于在第一段谜题的终点，即悲伤沼泽中发现的一份浸湿的卷轴。",al={"任务如何开始","什么开启了科泰罗的谜题2"}}},fp="17,149,31.125.0,20.68.0,21.104.1,38.79.0,45.57.0,43.106.0"}
P.entries["quest:626"] = {n="科泰罗的谜题",s="一张发霉的神秘卷轴上写着Cortello留下的最后一组诗句。这些押韵的指示指引寻宝者一路向北，前往饱受战火蹂躏的洛丹伦大陆，并在辛特兰的海岸瀑布旁找到了线索的终点。",h="一张发霉的神秘卷轴上写着Cortello留下的最后一组诗句。这些押韵的指示指引寻宝者一路向北，前往饱受战火蹂躏的洛丹伦大陆，并在辛特兰的海岸瀑布旁找到了线索的终点。",kw={"科泰罗","科泰罗的谜题","辛特兰","洛丹伦","发霉的卷轴","俯瞰悬崖","宝藏","瀑布"},sec={{t="最终线索",b="遵循之前的卷轴，这张风化的文本指引寻宝者离开南方的热带地区，前往战乱不断的洛丹伦。谜题要求寻宝者去寻找北方巨大的动荡，并承诺只要勇于面对那种动荡并沿着海岸线探索，这场漫长的追寻就会结束。"},{t="瀑布之下",b="诗句明确指出，最后的宝藏位于辛特兰的海岸边。在巨大的瀑布底部，宝藏就藏在水下。"}},faq={{q="这个谜题指向哪里？",a="诗句指向洛丹伦的辛特兰海岸，指引寻宝者去查看悬崖上奔流而下的巨大瀑布底部的水下区域。",al={"科泰罗谜题终点在哪里","科泰罗谜题3该去哪里","科泰罗辛特兰位置"}},{q="什么开启了这一部分的搜索？",a="这最后一条谜题出自一张发霉的卷轴，它是从科泰罗寻宝任务的早期步骤中发现的。",al={"如何开始科泰罗谜题第三部分","在哪里获取卷轴"}},{q="谁写了这些诗句？",a="这些谜题和隐藏的卷轴是一位名叫科泰罗的人留下的，他引导寻宝者去寻找他隐藏的宝藏。",al={"谁是科泰罗","谁制作了科泰罗谜题"}}},fp="17,191,14.198.0,19.99.0,28.139.0,36.94.0,23.81.0"}
P.entries["quest:6261"] = {n="杜加尔·朗德瑞克",s="这项任务旨在向冒险者介绍暴风城的首席狮鹫管理员邓加尔·长饮。在从奥斯瑞克·斯图恩处收集紧急物资后，信使必须安排快速的空中交通，将装备运送回西部荒野的受困守军手中。",h="这项任务旨在向冒险者介绍暴风城的首席狮鹫管理员邓加尔·长饮。在从奥斯瑞克·斯图恩处收集紧急物资后，信使必须安排快速的空中交通，将装备运送回西部荒野的受困守军手中。",kw={"邓加尔·长饮","狮鹫管理员","奥斯瑞克·斯图恩","奥斯瑞克的箱子","哨兵岭","暴风城","索尔","贸易区","西部荒野"},ang={["faction:Alliance"]="在王国中央军队缺席的情况下，建立暴风城与区域定居点之间的狮鹫航线对于维持秩序至关重要。",["race:Dwarf"]="像邓加尔·长饮和索尔这样的人类驯养员将矮人与狮鹫之间古老的羁绊带入了人类王国的中心。",["race:Human"]="由于西部荒野被暴风城贵族议会所忽视，个体商人和当地的驯养员必须直接合作，以确保前哨站拥有充足的武装。"},sec={{t="一条至关重要的补给线",b="西部荒野正被迪菲亚兄弟会的暴徒和狂暴的收割傀儡逼入绝境，使得军需官刘易斯和人民民兵组织急需补给。当刘易斯向首都发出请求新鲜装备的消息时，军械士奥斯瑞克·斯图恩打包了所有请求的物资。通过布满强盗的艾尔文森林和西部荒野的道路步行运送军事货物需要耗费宝贵的时间，这使得王国新建成的空中航线成为了一条至关重要的生命线。"},{t="狮鹫管理员",b="邓加尔·长饮坐镇在贸易区，负责协调暴风城的信使和载客狮鹫。这些雄伟的野兽传统上由蛮锤矮人饲养和驯化，只要两端的栖息地互相连通，就能在人类领地之间提供可靠的交通。通过将奥斯瑞克的重型板条箱直接带给邓加尔，信使们可以了解空中物流的运作方式，从而在首都的储备物资和像哨兵岭这样的前哨站之间建立直接联系。"}},faq={{q="邓加尔·长饮是谁？",a="邓加尔·长饮是暴风城的狮鹫管理员，驻扎在贸易区的飞行点。他负责管理首都的信使野兽，并监管洛丹伦南部和艾泽拉斯整个联盟领地的客运飞行。",al={"邓加尔","邓加尔是谁","暴风城狮鹫管理员"}},{q="为什么奥斯瑞克要通过狮鹫运送这个板条箱？",a="西部荒野的军需官刘易斯和人民民兵组织的装备严重短缺，难以抵御强盗。步行或用马车运送重型物资需要数天时间，且面临伏击的风险，而训练有素的狮鹫可以在几分钟内将奥斯瑞克的物资跨越边境运抵目的地。",al={"为什么要用狮鹫","为什么不步行","奥斯瑞克板条箱运输"}},{q="索尔是谁，为什么我必须先和他谈谈？",a="索尔是驻扎在西部荒野哨兵岭的狮鹫管理员。狮鹫是沿着特定的点对点航线进行训练的，这意味着只有当你已经在另一端通过与索尔联络规划好路径后，邓加尔的坐骑才能把你载回西部荒野。",al={"索尔是谁","为什么要见索尔","索尔狮鹫"}},{q="邓加尔接受了板条箱之后会发生什么？",a="一旦邓加尔检查完货物，他就会准备好狮鹫供你飞行，并指引你将板条箱直接送给哨兵岭的军需官刘易斯。",al={"接下来做什么","回到刘易斯","下一个任务"}},{q="这个任务在飞行链中处于什么位置？",a="它是飞行网络入门教程的第三步，该教程始于西部荒野的“迅捷的信使”，通过“前往暴风城”将你带到暴风城，与邓加尔会面，并以“回到刘易斯身边”结束。",al={"任务链","飞行任务线","有多少个任务"}},{q="为什么暴风城依赖矮人的狮鹫？",a="自从第二次战争将洛丹伦联盟与辛特兰的蛮锤部族团结在一起后，狮鹫就成为了联盟各领域最出色的侦察兵和运输工具，它们提供的快速交通绕过了荒废的道路和敌对的封锁。",al={"暴风城为何使用狮鹫","联盟狮鹫背景故事"}}},fx={["915b1473"]={q="奥斯瑞克·斯图恩为什么要这么做？",a="奥斯瑞克备齐了军需官刘易斯所需的装备，急需将它们送往西部荒野。驻守当地的士兵处境艰难，不能缺少新的补给和合适的装备。奥斯瑞克让你去找杜加尔·朗德瑞克，借助狮鹫运送，确保这些重要物资尽快抵达。",al={"奥斯瑞克·斯图恩的动机","为什么运送箱子","奥斯瑞克为什么要这么做"}}},fp="16,135,20.403.0,23.437.0,24.199.0,44.244.0,47.227.0,44.130.0,48.232.0,44.235.0"}
P.entries["quest:627"] = {n="克拉兹克的要求",s="当克拉兹克在藏宝海湾修理一只送来的瓦罐时，他要求你帮个忙作为回报。他想要在修理好炊具交给你之前，先从北边山峦中一个遥远的洞穴里取回稀有的次级血石矿。",h="当克拉兹克在藏宝海湾修理一只送来的瓦罐时，他要求你帮个忙作为回报。他想要在修理好炊具交给你之前，先从北边山峦中一个遥远的洞穴里取回稀有的次级血石矿。",kw={"阿拉希高地","血石","藏宝海湾","枯须峡谷","克拉兹克的帮忙","克拉兹克","次级血石矿","荆棘谷"},ang={["profession:Mining"]="克拉兹克明确指出，采集这种矿石需要采矿专长，并警告说任何缺乏该技能的人都需要找到有能力开采矿脉的人。"},sec={{t="北方的交易",b="在藏宝海湾交出破损的炊具后，克拉兹克停下手中的修理工作，向你提出了一笔交易。他没有免费修理这口锅，而是指引你向北远行至阿拉希高地。在枯须峡谷的一个洞穴中藏有次级血石矿，这是一种低品位但被知情者所珍视的矿物。"},{t="峡谷中的矿石",b="克拉兹克答应在你进行漫长的北方之旅时修理这口锅。他要求你带回四份血石矿回港口，并表示如果你带回了足够的样本，他会为你这次帮忙提供报酬。他还明确表示，如果你没有开采矿石所需的知识，你就需要寻找懂得开采的人帮忙。"}},faq={{q="克拉兹克是谁，他想要什么？",a="克拉兹克是在藏宝海湾的一名地精。在修理送来的破瓦罐时，他要求你从北方运回四份稀有的血石矿。",al={"克拉兹克是谁","克拉兹克的要求"}},{q="血石矿在哪里？",a="次级血石矿位于阿拉希高地北部深处的枯须峡谷里的一个山洞中。",al={"血石矿在哪里","血石位置","枯须峡谷位置"}},{q="为什么克拉兹克想要低品位的矿石？",a="尽管洞穴里的矿床质量不是最高的，但克拉兹克指出，即使是低品位的血石，对于那些拥有工艺和知识来利用它的人来说，也具有相当大的价值。",al={"为什么是次级血石","血石价值"}},{q="在这个任务之前发生了什么？",a="在克拉兹克提出这个要求之前，你被派往藏宝海湾，在“克拉兹克的烹饪”任务中运送破损的容器。",al={"前一个任务","之前发生了什么"}},{q="收集到血石后会发生什么？",a="一旦克拉兹克收到四份矿石并支付报酬，旅程将继续进行，接下来的任务是“返回卡雷布下士处”。",al={"下一个任务","接下来是什么"}}},fp="16,183,18.253.0,18.221.0,36.142.0,36.101.0,35.114.0,30.96.0,44.101.0"}
P.entries["quest:628"] = {n="刨花皮靴",s="在藏宝海湾，崔斯里克已经完成了刨花皮靴靴子的内部结构，现在需要一张老盐水鳄鱼皮来制作外部。",h="在藏宝海湾，崔斯里克已经完成了刨花皮靴靴子的内部结构，现在需要一张老盐水鳄鱼皮来制作外部。",kw={"藏宝海湾","鳄鱼","崔斯里克","年长鳄鱼","刨花皮靴","盐水鳄鱼","荆棘谷"},sec={{t="外层",b="内部结构已经完成，现在只剩下外层了。为此，崔斯里克只使用最上等的年长鳄鱼皮，因为它们更坚韧，能为刨花皮靴系列的图案和装饰提供更好的表面。唯一符合崔斯里克计划的皮肤就是年长盐水鳄鱼的皮，找到这种鳄鱼非常困难，因为这种年长的鳄鱼只会在保护其他盐水鳄鱼时才会现身。崔斯里克还在某处读到过，盐水鳄鱼的数量正在减少，这会影响生意。"},{t="崔斯里克的感谢",b="崔斯里克很高兴：订单可以完成了，并且能搭上下一班开往安德麦的船运往里德尔沃克斯主管那里，而且还是提前完成的。崔斯里克还多做了一些，并送给你一双作为你辛苦劳作的报酬，他坚称没有哪双靴子能比得上刨花皮靴系列。"}},faq={{q="谁是崔斯里克？",a="崔斯里克是藏宝海湾的一位制鞋匠，专门制作刨花皮靴系列的靴子。",al={"崔斯里克","藏宝海湾制鞋匠","崔斯里克非玩家角色"}},{q="为什么崔斯里克需要年长盐水鳄鱼皮？",a="崔斯里克说，年长鳄鱼的皮更坚韧，能为刨花皮靴系列的图案和装饰提供更好的表面，而且只有年长盐水鳄鱼的皮才符合他的计划。",al={"为什么需要鳄鱼皮","刨花皮靴材料","年长鳄鱼皮的用途"}},{q="为什么年长盐水鳄鱼很难找？",a="崔斯里克说，年长的鳄鱼只会在保卫其他盐水鳄鱼时才现身。",al={"哪里有年长鳄鱼","寻找年长盐水鳄鱼","如何召唤年长鳄鱼"}},{q="这个任务之前是什么任务？",a="之前是“需要组装”。",al={"前置任务","刨花皮靴前置条件","需要组装关联"}},{q="崔斯里克对盐水鳄鱼有什么担忧？",a="崔斯里克读到过盐水鳄鱼的数量正在减少，这对生意不利。",al={"鳄鱼是否正在灭绝","盐水鳄鱼数量","鳄鱼灭绝"}}},fp="9,140,15.430.0,17.222.1,16.56.0,57.152.0,48.93.0,30.34.0,59.93.0"}
P.entries["quest:6281"] = {n="赶赴暴风城",s="这个任务向西部荒野的冒险者们介绍了暴风城王国的狮鹫网络，既快速又方便。旅行者们带着哨兵岭急需的征用物资，直接飞往旧城区，将消息传达给商人奥斯瑞克·斯图恩。",h="这个任务向西部荒野的冒险者们介绍了暴风城王国的狮鹫网络，既快速又方便。旅行者们带着哨兵岭急需的征用物资，直接飞往旧城区，将消息传达给商人奥斯瑞克·斯图恩。",kw={"飞行点","狮鹫","刘易斯的便笺","有限无敌","旧城区","奥斯瑞克·斯图恩","哨兵岭","索尔"},ang={["faction:Alliance"]="由狮鹫管理员维护的飞行网络将联盟分散的前哨站连接在一起，使偏远的驻军与首都保持紧密联系。",["race:Human"]="回到旧城区后，人们可以感受到普通公民和孤立的前线人员对宏伟的贵族议会政治感到多么疏离。"},sec={{t="展翅高飞",b="在哨兵岭的军需官刘易斯准备好征用便笺后，当地的狮鹫管理员索尔会提供离开这片纷争平原的最快路径。只需支付少量费用，旅行者便可骑上一只受过训练的狮鹫，翱翔在尘土飞扬的农田、作为艾尔文森林边界的河流，以及暴风城高耸洁白的城墙之上。"},{t="旧城区补给线",b="降落在首都的贸易栖木后，信使前往旧城区，在他名为有限防护的商店找到奥斯瑞克·斯图恩。奥斯瑞克为前线提供装备和补给，但他冷淡的态度凸显了西部荒野陷入困境的人民民兵与暴风城中分心于政务的统治者之间日益加深的隔阂。"}},faq={{q="这个任务的目的是什么？",a="该任务是作为联盟狮鹫航线的实践入门，教导冒险者如何在遥远的前哨站和首都之间快速往返。",al={"为什么要完成此任务","任务目的","前往暴风城任务目标"}},{q="奥斯瑞克·斯图恩在哪里？",a="奥斯瑞克·斯图恩经营着有限免疫商店，位于暴风城内旧城区蜿蜒的街道旁。",al={"奥斯瑞克·斯图恩在哪里","寻找奥斯瑞克·斯图恩","有限的无敌位置"}},{q="为什么哨兵岭需要来自暴风城的补给？",a="哨兵岭的人民民兵正在与迪菲亚潜行者苦战，却从首都获得了极少的正式军事援助，这迫使军需官刘易斯不得不直接向民间商人购买装备。",al={"为什么需要补给","西部荒野补给问题","哨兵岭装备"}},{q="索尔是谁？",a="索尔是驻扎在哨兵岭的联盟狮鹫管理员，负责管理连接西部荒野与暴风城及其他友方据点的飞行路线。",al={"索尔是谁","西部荒野狮鹫管理员","索尔 西部荒野"}},{q="刘易斯的便笺里写了什么？",a="这是一份来自军需官刘易斯的紧急征用单，详细列出了维持哨兵岭驻军装备所需的物资和补给。",al={"刘易斯的便笺","便笺上写了什么","便笺内容"}},{q="交付便笺后会发生什么？",a="收到征用单后，奥斯瑞克会指示你去找暴风城的狮鹫管理员邓加·长酒，安排将订购的物资运回西部荒野。",al={"接下来做什么","后续任务","奥斯瑞克·斯图恩之后"}}},fx={["9888c0f8"]={q="索尔为什么要这么做？",a="索尔是西部荒野的狮鹫管理员，负责维持边境与都城之间的通信和运输。军需官刘易斯急需有人将补给送往哨兵岭，但狮鹫不会自行出发，总得有人握住缰绳，将物资申请交到奥斯瑞克·斯图恩手中。索尔让你骑乘他的一头坐骑，确保哨兵岭的求援能真正传到暴风城。",al={"索尔为什么派遣冒险者","索尔的动机 赶赴暴风城","狮鹫管理员索尔为什么帮忙"}},a35c3ce1={q="索尔为什么需要我，而不亲自飞往暴风城？",a="索尔不能就这样擅离哨兵岭的岗位。作为聚居地唯一的狮鹫管理员，他必须留在当地照料狮鹫，管理航线，让西部荒野与王国其他地区保持联系。像你这样能干的信使，愿意支付旅费，将刘易斯的物资申请直接交给旧城区的奥斯瑞克·斯图恩，便能让哨兵岭把消息送到暴风城，同时让哨站的管理员继续留守。",al={"为什么是我 赶赴暴风城","索尔为什么不能送信","索尔为什么需要冒险者"}}},fp="21,106,11.352.0,21.306.0,34.161.0,30.70.0,52.206.0,12.125.0,27.149.0,39.176.0"}
P.entries["quest:6282"] = {n="鹰身人的威胁",s="“鹰身人威胁”是一个部落任务，由石爪山脉烈日石居的马格兰提供。秉承牛头人作为大地守护者的天职，冒险者们将受命前往西部的焦炭谷，削减血怒鹰身人部族不断壮大的势力。",h="“鹰身人威胁”是一个部落任务，由石爪山脉烈日石居的马格兰提供。秉承牛头人作为大地守护者的天职，冒险者们将受命前往西部的焦炭谷，削减血怒鹰身人部族不断壮大的势力。",kw={"伏击者","血怒","焦炭谷","部族","鹰身人威胁","马格兰","暴羽者","杀戮者","石爪山脉","烈日石居"},ang={["class:Druid"]="血怒部族那扭曲的存在，亵渎了焦炭谷原本就脆弱不堪、饱受火灾蹂躏的生态环境。",["class:Shaman"]="在马格兰的号令下，萨满们响应召唤，肃清那些破坏自然元素平衡的邪恶亵渎者。",["faction:Horde"]="清扫焦炭谷的天空，巩固了部落在烈日石居的立足点，以抵御栖息在石爪山脉中的危险野外势力。",["race:Tauren"]="对于牛头人角色而言，剿灭这些不断蚕食领地的血怒鹰身人，是履行他们作为卡利姆多荒野守护者的祖先誓言的荣誉职责。"},sec={{t="大地的守护者",b="烈日石居的牛头人肩负着保卫石爪山脉的神圣职责，他们维护着自然平衡，并保护着过往的旅人免受当地危险的侵害。烈日石居的领袖长者马格兰正忧心忡忡地注视着当地鹰身人数量的疯狂增长。血怒部族已经遍布了焦炭谷那片焦灼的荒地，不仅袭扰过往的野兽，还切断了交通要道。如果不加遏制，这些掠食成性的族群迟早会彻底切断烈日石居与外界的联系。"},{t="扫荡焦炭谷",b="烈日石居的西侧是焦炭谷，那是一片由灰烬、焦土和残木构成的荒凉废墟，是灾难性大火后留下的伤痕。血怒鹰身人在此处古老林木的焦骸高处筑巢，建立了据点。马格兰委派部落勇士深入这片充满敌意的火山口，去削减数十名血怒伏击者、血怒杀戮者和血怒暴羽者的数量。削弱它们的族群可以打破该部族对山谷的即时掌控，从而为直接对抗她们的母系首领铺平道路。"}},faq={{q="谁发放“鹰身人威胁”任务？",a="该任务由马格兰发放，他是位于石爪山脉烈日石居中央水池附近的一名牛头人。",al={"鹰身人威胁任务发布者","在哪里接取鹰身人威胁","马格兰任务"}},{q="血怒鹰身人在哪里？",a="血怒鹰身人栖息在焦炭谷各地，这是一片位于烈日石居西侧的焦灼荒原。烈日石居后方的一条山路可直通山谷。",al={"血怒鹰身人在哪里","血怒鹰身人位置","焦炭谷鹰身人"}},{q="为什么牛头人要消灭鹰身人？",a="牛头人视自己为石爪山脉自然平衡的守护者。马格兰担心血怒鹰身人正在卡利姆多大举扩张，不仅袭击无辜者，还阻碍生物在土地上的自由迁徙。",al={"为什么要杀鹰身人","牛头人与鹰身人的冲突","为什么马格兰痛恨鹰身人"}},{q="完成“鹰身人威胁”后还有什么任务？",a="完成“鹰身人威胁”后将解锁后续任务“血怒血统”，马格兰会派遣你去消灭血怒部族的统治核心。",al={"鹰身人威胁的后续任务","鹰身人威胁后续","鹰身人威胁之后做什么"}},{q="这个任务是部落专属的吗？",a="是的。该任务仅向烈日石居营地的部落成员开放。",al={"联盟可以做鹰身人威胁吗","鹰身人威胁部落专属","联盟鹰身人威胁"}},{q="必须杀死哪些种类的鹰身人？",a="你必须在焦炭谷杀死七名血怒鹰身人、七名血怒伏击者、七名血怒杀戮者和七名血怒暴羽者。",al={"要杀哪种鹰身人","焦炭谷鹰身人种类","鹰身人威胁目标"}}},fp="16,193,22.322.0,25.479.0,37.124.0,40.139.0,42.225.0,45.102.0,25.66.0,36.153.0"}
P.entries["quest:6283"] = {n="血怒一族",s="血怒血脉是部落的一项任务，由烈日石居的马格兰发布，要求击杀血怒鹰身人的领袖。这是马格兰净化焦炭谷的最终努力，旨在打破这些鹰身人对这片荒凉之地的凶残统治。",h="血怒血脉是部落的一项任务，由烈日石居的马格兰发布，要求击杀血怒鹰身人的领袖。这是马格兰净化焦炭谷的最终努力，旨在打破这些鹰身人对这片荒凉之地的凶残统治。",kw={"血怒血脉","血怒撕裂者","焦炭谷","鹰身人","马格兰","石爪山脉","烈日石居"},ang={["faction:Horde"]="确保烈日石居周边的安全，对于保护这座坐落在充满争端的石爪山脉深处的部落避风港至关重要。",["race:Tauren"]="石爪山脉满目疮痍的景象让牛头人感到痛苦，而除掉凶残的鹰身人女王，能让像马格兰这样的当地长者重新将心思投入到和谐与疗愈之中。"},sec={{t="击杀女族长",b="在焦炭谷边缘猎杀那些弱小的鹰身人只能给烈日石居带来暂时的喘息。马格兰认为，要遏制她们的侵略行为，唯一持久的方法就是除掉她们的女族长——血怒撕裂者。鹰身人们视她为女王，并直接听命于她，在崎岖的西侧山脊上展现出残忍的协调性和大胆的攻势。"},{t="大地归于平静",b="一旦血怒撕裂者倒下，并将她的尸骸作为证明带回，烈日石居所面临的直接威胁便会平息。随着她们的族群女王被消灭，这些失去组织的鹰身人将更容易被阻挡。这场胜利也卸下了马格兰本人心灵上的重担，让他不再时刻保持警惕，从而能回归牛头人追求和谐与平衡的传统之道。"}},faq={{q="谁发布了“血怒血脉”任务？",a="该任务由烈日石居的牛头人首领马格兰发布，你可以在烈日石居内的水池旁找到他。",al={"血怒血脉任务发布者","谁开启血怒血脉","马格兰任务"}},{q="在解锁此次狩猎前，必须完成什么前置任务？",a="你必须完成“鹰身人的威胁”，在那项任务中，马格兰会第一次派你去焦炭谷削减血怒鹰身人的数量。",al={"血怒血脉前置任务","血怒血脉任务条件","鹰身人的威胁后续"}},{q="血怒撕裂者在哪里？",a="她徘徊在焦炭谷西北边缘的岩石山丘上。她有着独特的蓝色皮肤，这使她与族群中的其他鹰身人区别开来。",al={"血怒撕裂者位置","寻找血怒撕裂者","血怒撕裂者刷新点"}},{q="为什么马格兰想杀死血怒撕裂者？",a="马格兰认定血怒撕裂者是引领该族群进行凶残领土扩张的女王。杀掉她可以瓦解她们的领导核心，并永久削弱她们对焦炭谷的控制。",al={"为什么要杀血怒撕裂者","焦炭谷鹰身人领袖背景","马格兰动机"}},{q="血怒撕裂者的死亡如何影响烈日石居的牛头人？",a="她的死让马格兰获得内心的平静，使他从挥之不去的愤怒和对即将到来的攻击的恐惧中解脱出来，这样他就可以将重心重新转向治愈这片土地。",al={"石爪山脉鹰身人威胁背景","血怒撕裂者死后会发生什么","马格兰的反应"}},{q="从烈日石居前往焦炭谷最快的路径是什么？",a="烈日石居后方有一条直接通往山上的小径，可以绕过石爪山脉蜿蜒的大路，直达焦炭谷。",al={"如何从烈日石居去焦炭谷","烈日石居后路","焦炭谷近路"}}},fp="19,102,19.288.0,18.324.0,40.96.0,60.122.0,34.134.0,44.189.0,72.130.1,74.133.0"}
P.entries["quest:6284"] = {n="贝瑟莱斯",s="“蜘蛛恐惧症”是一个部落悬赏任务，目标是贝瑟莱斯——一只盘踞在石爪山脉南部、古老而巨大的掠食者。这份悬赏张贴在狂风峭壁附近的一处路边公告牌上，指引冒险者进入希塞尔山谷，并为烈日石居的马格兰带回这只蜘蛛女王的牙齿。终结她的统治能让山路对夜间行者来说更加安全。",h="“蜘蛛恐惧症”是一个部落悬赏任务，目标是贝瑟莱斯——一只盘踞在石爪山脉南部、古老而巨大的掠食者。这份悬赏张贴在狂风峭壁附近的一处路边公告牌上，指引冒险者进入希塞尔山谷，并为烈日石居的马格兰带回这只蜘蛛女王的牙齿。终结她的...",kw={"蜘蛛恐惧症","贝瑟莱斯","悬赏","马格兰","希塞尔山谷","蜘蛛","石爪山脉","烈日石居","蛛网小径"},ang={["class:Hunter"]="在希塞尔山谷的阴影峭壁中追踪这只难以捉摸的巨大蛛形纲生物，是山地追踪能力的一次真正考验。",["faction:Horde"]="清除贝瑟莱斯能够稳定通往烈日石居的交通，保护部落在石爪山脉中央峭壁的关键据点。",["race:Tauren"]="马格兰身上带着贝瑟莱斯毒液留下的痛苦伤疤，使得这次狩猎也成为了向大地之子致敬并提供协助的任务。"},sec={{t="路边的警告",b="在狂风峭壁以南的主干道上，旅行者会发现一张饱经风霜的通缉令，警告着西方的危险。希塞尔山谷和蛛网小径已被八条腿的掠食者完全占领。在这张蛛网威胁的中心，盘踞着贝瑟莱斯，一只异常巨大、有着橙色外壳的蜘蛛。她指挥着自己的族群，并在日落后伏击任何胆敢偏离道路的人。"},{t="马格兰的冤屈",b="这份针对贝瑟莱斯的悬赏由烈日石居的牛头人马格兰提出。马格兰与这位女王有一笔私人旧账要算：在之前的一次遭遇中，他曾被贝瑟莱斯巨大的两英尺长的牙齿击中，险些丧命。虽然他设法击退了她并一瘸一拐地逃到了安全地带，但留下的伤口时刻提醒着他峡谷阴影中潜伏的危险。通过让冒险者带回贝瑟莱斯的牙齿，马格兰希望能确保通道的安全，让往返于烈日石居的贸易和旅行不再受到恐惧的威胁。"}},faq={{q="“蜘蛛恐惧症”任务从哪里开始？",a="该任务通过调查石爪山脉主路西侧、狂风峭壁入口以南的一张通缉令开始。",al={"如何领取蜘蛛恐惧症","通缉令贝瑟莱斯位置","如何开启蜘蛛恐惧症任务"}},{q="在哪里可以找到贝瑟莱斯？",a="贝瑟莱斯栖息在希塞尔山谷内，位于路边通缉令的西侧。她和她的蜘蛛后代在满是蛛网的峡谷地面上游荡。",al={"贝瑟莱斯位置","贝瑟莱斯在哪里","寻找贝瑟莱斯蜘蛛"}},{q="马格兰是谁？",a="马格兰是一位位于石爪山脉烈日石居的牛头人。他曾亲身幸免于贝瑟莱斯的毒牙攻击，并发布了悬赏以铲除峡谷中这一威胁。",al={"马格兰是谁","马格兰的角色","谁交还蜘蛛恐惧症任务"}},{q="为什么贝瑟莱斯会对该地区构成如此大的威胁？",a="贝瑟莱斯是一只极其巨大且冷酷的蜘蛛，潜伏在希塞尔山谷和邻近的蛛网小径中。她和她的族群在夜幕的掩护下捕食旅行者，威胁着任何试图前往烈日石居的人。",al={"为什么要杀贝瑟莱斯","贝瑟莱斯做了什么"}},{q="领取悬赏需要什么证明？",a="你必须杀死贝瑟莱斯并割下她那巨大的两英尺长的牙齿。将贝瑟莱斯的牙齿交给烈日石居的马格兰即可完成悬赏。",al={"贝瑟莱斯的证明","贝瑟莱斯任务物品","贝瑟莱斯掉落什么"}},{q="联盟可以接取这个任务吗？",a="不能。这份通缉令奖励的是烈日石居（一个部落营地）的马格兰，因此“蜘蛛恐惧症”是部落专属任务。",al={"联盟能做蜘蛛恐惧症吗","联盟蜘蛛恐惧症任务"}}},fp="13,242,20.292.0,27.420.0,41.130.0,29.138.0,27.176.0,45.183.0,43.146.0,40.124.0"}
P.entries["quest:6285"] = {n="返回西部荒野",s="“回到刘易斯处”是新手信使飞行任务的最后一程，将从暴风城急需的盔甲直接运送到哨兵岭。在受托于邓加尔·长饮并带上奥斯瑞克的箱子后，信使们骑着狮鹫飞越艾尔文森林和西部荒野的天空，为身陷苦战的人民民兵补充物资。",h="“回到刘易斯处”是新手信使飞行任务的最后一程，将从暴风城急需的盔甲直接运送到哨兵岭。在受托于邓加尔·长饮并带上奥斯瑞克的箱子后，信使们骑着狮鹫飞越艾尔文森林和西部荒野的天空，为身陷苦战的人民民兵补充物资。",kw={"邓加尔·长饮","飞行航线","狮鹫","奥斯瑞克","奥斯瑞克的箱子","人民民兵","军需官刘易斯","哨兵岭","索尔","西部荒野"},ang={["class:Warrior"]="每一箱飞往哨兵岭的胸甲和胫甲，都意味着又多了一名能够抵挡迪菲亚匪徒攻击的民兵战士。",["faction:Alliance"]="在暴风城和像哨兵岭这样的偏远定居点之间建立狮鹫航线，对于维系日益分裂的王国至关重要。",["race:Dwarf"]="王国的空中交通依靠狮鹫——这种矮人的古老坐骑——从邓加尔·长饮位于首都的巢穴飞往西部荒野的索尔处。"},sec={{t="空中的生命线",b="西部荒野正逐渐脱离王国的掌控，受到迪菲亚潜行者、贪婪的豺狼人和机械收割机的围攻。由于陆路补给线受到骚扰，道路对于单行的马车来说过于危险，飞行管理员网络提供了一条至关重要的生命线。奥斯瑞克，一位位于暴风城旧城区的护甲商，准备了一箱沉重的盔甲，旨在支援哨兵岭受挫的人民民兵志愿者。"},{t="狮鹫的习性",b="狮鹫是极其忠诚且训练有素的野兽，但驾驶它们穿越各地需要建立一定的熟悉度。正如邓加尔·长饮向新手信使解释的那样，虽然狮鹫本能地知道如何飞回它们在暴风城的首都巢穴，但只有当旅行者亲自拜访过目的地的飞行管理员后，它们才会载着骑手前往遥远的前哨站。在之前与哨兵岭的索尔报到后，边境之上的天空便为快速运输敞开了大门。"},{t="民兵的补给",b="抵达哨兵岭后，运送的箱子由军需官刘易斯接收，他是负责为格里安·斯托曼的志愿军装备物资的军官。刘易斯立即着手将盔甲分发给边境守卫者。对于哨兵岭而言，与首都之间可靠的空中联系意味着坚守防线与被迪菲亚潜行者彻底淹没之间的区别。"}},faq={{q="奥斯瑞克的箱子里有什么？",a="箱子里装有由暴风城护甲商奥斯瑞克准备的新制造的盔甲。哨兵岭的人民民兵迫切需要这些物资，他们缺乏标准的皇家供给，只能依靠捐赠和私人运输来装备他们的志愿战士。",al={"奥斯瑞克的箱子内容","箱子里有什么","我要运送什么"}},{q="军需官刘易斯是谁？",a="军需官刘易斯是人民民兵的补给军官，驻扎在哨兵岭的塔楼旁。他负责管理在西部荒野对抗迪菲亚潜行者的志愿守卫者的口粮、装备和武器。",al={"刘易斯 西部荒野","军需官刘易斯的职责","刘易斯是谁"}},{q="邓加尔·长饮是谁？",a="邓加尔·长饮是暴风城的资深人类狮鹫管理员，位于首都贸易区的巢穴中。他负责监管王国的空中信使和客运航线。",al={"邓加尔 暴风城","暴风城狮鹫管理员","暴风城飞行管理员"}},{q="为什么狮鹫只飞往你去过的地方？",a="根据邓加尔的说法，狮鹫经过天性训练可以笔直飞回首都，但在将骑手运送到像哨兵岭索尔的站点这样的偏远边境巢穴之前，它们依赖于已建立的航点和个人的熟悉度。",al={"狮鹫飞行规则","飞行航线如何运作","为什么要先拜访索尔"}},{q="索尔是谁？",a="索尔是驻扎在西部荒野哨兵岭的飞行管理员。他照料着前哨站的狮鹫，并接收从暴风城抵达的空中信使。",al={"索尔 西部荒野","哨兵岭狮鹫管理员","飞行管理员索尔"}},{q="为什么暴风城不能直接派皇家马车运送补给？",a="连接艾尔文森林和西部荒野的道路受到迪菲亚潜行者、河爪豺狼人和盗贼的严重骚扰。陆路补给车队面临被伏击和抢劫的风险，因此空中狮鹫航线要快得多，也安全得多。",al={"为什么要使用狮鹫","为什么不用陆路运输","西部荒野的道路"}}},fx={["24b76519"]={q="杜加尔·朗德瑞克为什么要运送奥斯瑞克的箱子？",a="杜加尔掌管着暴风城的狮鹫航线，这是连接都城与困境中各处边境的重要生命线。哨兵岭的军需官刘易斯和人民军急需援军与护甲，才能抵挡迪菲亚暴徒和豺狼人，守住西部荒野。杜加尔依靠可信的旅人骑乘狮鹫将补给运回，确保关键的军事援助迅速抵达偏远哨站。",al={"杜加尔的动机","为什么运送奥斯瑞克的箱子","杜加尔为什么帮助刘易斯"}},["74eea5bf"]={q="杜加尔为什么需要你运送箱子，而不派一名信使？",a="杜加尔管理着都城繁忙的狮鹫栖所，无法擅离职守，而暴风城的正规驻军也很少抽调人手，去支援备受忽视的西部荒野防务。刘易斯最初就派你来协调这次补给运输，因此你已经赢得了索尔和哨兵岭民兵的信任。将箱子托付给愿意骑狮鹫返回的冒险者，是把护甲送到急需之人手中最快的办法。",al={"为什么不派信使","杜加尔为什么选我","为什么亲自运送箱子"}}},fp="15,199,17.333.0,20.372.0,24.248.0,29.251.0,27.212.0,24.176.0,58.226.0,12.142.0,57.195.0"}
P.entries["quest:629"] = {n="暗礁海",s="格罗姆高营地的肯维雷正在寻找一块位于野人海岸深处的远古石碑碎片。这座被称为暗礁海的沉没之城中盘踞着极具攻击性的鱼人，并记载着格里雷克的传奇历史，暗矛巨魔部族希望将其珍藏在奥格瑞玛。",h="格罗姆高营地的肯维雷正在寻找一块位于野人海岸深处的远古石碑碎片。这座被称为暗礁海的沉没之城中盘踞着极具攻击性的鱼人，并记载着格里雷克的传奇历史，暗矛巨魔部族希望将其珍藏在奥格瑞玛。",kw={"暗矛","格里雷克","格罗姆高营地","肯维雷","鱼人","野人海岸","荆棘谷","石碑碎片","暗礁海"},ang={["faction:Horde"]="帮助肯维雷为奥格瑞玛找回这件遗物，能够加强部落与暗矛部族之间的信任纽带。",["race:Troll"]="对于暗矛部族而言，找回这块碎片能让他们的古老传统以及对伟大英雄格里雷克的崇敬在奥格瑞玛的新家园中得以延续。"},sec={{t="沉没的传说",b="在格罗姆高营地的西北方，很久以前一场剧烈的地震震碎了大地，导致一座远古巨魔城市滑入了野人海岸的水下。如今这里被称为暗礁海，被洪水淹没的废墟中爬满了敌对的鱼人，它们会袭击任何胆敢靠近的人。在废墟深处的海床上，立着一块巨大的石碑，上面刻着巨魔英雄格里雷克的生平故事，对于暗矛部族来说，这段记忆是神圣的。"},{t="奥格瑞玛的纪念品",b="由于这座完整的纪念碑实在太过巨大，无法从深海中搬运出来，肯维雷请求你从石碑上敲下一块碎片。他打算将这块碎片带回奥格瑞玛，并将其供奉在神圣的地方，这样暗矛部族就不会忘记格里雷克的伟力和荣誉。"}},faq={{q="暗礁海位于何处？",a="暗礁海位于荆棘谷格罗姆高营地西北方的野人海岸水下。",al={"暗礁海位置","暗礁海在哪里","如何找到暗礁海"}},{q="为什么肯维雷想要石碑碎片？",a="这块石碑保留了巨魔英雄格里雷克的神圣传说。肯维雷计划将碎片带回奥格瑞玛并放置在神圣的地点，以便暗矛部族能在他们的新家园中缅怀先祖。",al={"为什么要获取石碑碎片","石碑碎片的用途","为什么格里雷克石碑"}},{q="暗礁海的古城发生了什么事？",a="很久以前，一场剧烈的地震震撼了野人海岸，导致整座巨魔城市沉入了海浪之下。",al={"暗礁海发生了什么","暗礁海是如何沉没的","沉没的巨魔城市历史"}},{q="现在的暗礁海里有什么生物？",a="敌对的鱼人已在沉没的废墟中安家，并会攻击任何靠近这座沉没之城的人。",al={"暗礁海里的怪物","暗礁海的敌人","谁住在暗礁海"}},{q="谁是格里雷克？",a="格里雷克是一位传奇的巨魔英雄，他的事迹刻在野人海岸下方的沉没石碑上，被暗矛部族视为神圣。",al={"谁是格里雷克","格里雷克背景故事","英雄格里雷克"}},{q="为什么要拿碎片而不是整块石碑？",a="海床上的雕刻纪念碑实在太庞大了，无法从废墟中打捞上来，因此取下一块破碎的残片是将这份传说带回奥格瑞玛的唯一可行办法。",al={"为什么只要碎片","可以带走整块石碑吗","带走整块石碑"}}},fp="13,163,14.433.0,24.252.0,31.99.0,42.204.0,51.106.0,41.93.0,15.134.0,50.127.0"}
P.entries["quest:63"] = {n="水之召唤",s="这一至关重要的试炼指引萨满祭司从贫瘠之地出发，跨越无尽之海，前往饱受摧残的银松森林海岸。为了赢得与水之灵沟通的资格，试炼者必须直面一个腐化的元素，并净化一座被天灾瘟疫所污染的古老海岸神龛。",h="这一至关重要的试炼指引萨满祭司从贫瘠之地出发，跨越无尽之海，前往饱受摧残的银松森林海岸。为了赢得与水之灵沟通的资格，试炼者必须直面一个腐化的元素，并净化一座被天灾瘟疫所污染的古老海岸神龛。",kw={"永恒之泉火盆","布莱恩","水之召唤","腐化显像","水之先知伊斯伦","瑟伯切尔","银松森林","水之图腾"},ang={["class:Shaman"]="这一仪式证明了萨满祭司不仅是风暴的召唤者，更是破碎之地的治愈者，肩负着净化精神腐化的重任。",["faction:Horde"]="前往银松森林的旅程，迫使来自卡利姆多的兽人和牛头人亲眼目睹了他们的被遗忘者盟友所面临的残酷、饱受瘟疫蹂躏的苦难。"},sec={{t="跨海朝圣",b="在隐士布莱恩的指引下收集到纯净之水后，萨满祭司回到了位于贫瘠之地海岸的水之先知伊斯伦身边。随后，伊斯伦交给了试炼者一项更为艰巨的任务：将这种净化过的精华带过海洋，送往银松森林那片闹鬼的海岸，那里位于被遗忘者避难所——瑟伯切尔的西侧。"},{t="净化永恒之泉",b="被选中的圣所是永恒之泉火盆，这是一个古老的元素焦点，其水域在洛丹伦瘟疫的弥漫侵蚀下变得扭曲而充满敌意。驻守于此的水之灵已变得沉默且狂暴。通过击败束缚在那里的腐化显像，并将它的护腕与最纯净的水一同献给火盆的火焰，萨满祭司便能打破瘟疫的束缚，召唤出一只未受玷污的潮汐之灵。"}},faq={{q="为什么萨满祭司必须远赴银松森林？",a="水之先知伊斯伦要求萨满祭司证明他们有能力掌控腐化，而不仅仅是学习如何保持宁静。瑟伯切尔西侧的海岸神龛已沦为洛丹伦瘟疫的牺牲品，这给予了试炼者一个机会去治愈元素圣所，并唤醒那些拒绝与其他任何人沟通的水之灵。",al={"为什么要前往银松森林","为什么要跨海旅行","银松森林水之任务的原因"}},{q="使用永恒之泉火盆会发生什么？",a="将击败的元素护腕与剩余的最纯净的水一同置于火焰中，会触发伊斯伦传授的净化仪式。噼啪作响的祭品会净化当地的水池，并召唤出一只纯净的水之显像，它将乐于赐予你祝福。",al={"永恒之泉火盆事件","火盆的作用","如何净化水池"}},{q="是谁在腐化银松森林的水之神龛？",a="水源受到了洛丹伦沦陷王国中挥之不去的弥漫瘟疫所扭曲。从山丘渗下的腐化玷污了当地的泉水，并使原生的水之灵扭曲成了狂暴、充满敌意的恶魔。",al={"谁腐化了神龛","为什么显像会被腐化","银松森林水之腐化"}},{q="完成这项试炼后你能得到什么？",a="净化永恒之泉火盆后，你便能与一只纯净的水之灵进行沟通。将净化的证据带回贫瘠之地交给水之先知伊斯伦，最终就能获得你的水之图腾，并完成漫长的水之召唤试炼。",al={"水之召唤奖励","如何解锁水之图腾","我能得到什么"}},{q="神龛具体在哪里？",a="神龛坐落在银松森林的西侧海岸线上，就在瑟伯切尔以西的腐化山脊上方。",al={"永恒之泉火盆位置","神龛在哪里","银松森林神龛坐标"}},{q="谁是水之先知伊斯伦？",a="水之先知伊斯伦是一位居住在贫瘠之地商旅海岸的牛头人萨满，位于棘齿城以南。她是一位受人尊敬的精神向导，指导年轻的部落萨满完成与水元素调和所需的艰苦仪式。",al={"谁是伊斯伦","水之先知伊斯伦背景","贫瘠之地水之训练师"}}},fp="13,190,27.271.0,23.363.1,66.227.0,51.203.0,49.174.0,48.228.0,36.107.0,23.209.0"}
P.entries["quest:630"] = {n="瓶中信",s="响应了一次来自海洋的求救后，你在荆棘谷海岸外一座孤岛上发现了被锁链囚禁的普巴尔公主。巨猿穆克拉大王统治着当地的野兽，并囚禁了她。你需要击败它才能拿到解开锁链的钥匙。",h="响应了一次来自海洋的求救后，你在荆棘谷海岸外一座孤岛上发现了被锁链囚禁的普巴尔公主。巨猿穆克拉大王统治着当地的野兽，并囚禁了她。你需要击败它才能拿到解开锁链的钥匙。",kw={"加基森群岛","穆克拉大王","普巴尔公主","锁链钥匙","天鬃","荆棘谷"},sec={{t="岛上的囚犯",b="沿着漂流瓶中的信息指引，你直接找到了被沉重锁链强行囚禁的普巴尔公主。天鬃大猩猩穆克拉大王统治着岛上徘徊的生物，并监视着对她的囚禁。普巴尔相信你有能力对抗这只可怕的猿猴，并夺回解开她束缚所需的钥匙。"},{t="东南方的野兽",b="普巴尔提到，经常能听到她的俘获者在岛屿东南侧徘徊。与穆克拉大王对峙绝非易事，但击败它是夺取锁链钥匙并确保普巴尔获救的唯一途径。"},{t="拯救与感激",b="带回锁链钥匙后，普巴尔公主从囚禁中获得了解放，免受了她所认为的奇耻大辱。虽然她没有能力让你完全加入她的部族，但她还是为你展现出的勇气献上了一份谢礼。"}},faq={{q="普巴尔公主是谁？",a="普巴尔公主是一位部族俘虏，被铁链锁在荆棘谷海岸外的一座岛屿上。在发出漂流瓶求救信息后，她一直在等待着有胆识的人来击败俘获者并解开她的锁链。",al={"普巴尔","普巴尔是谁","普巴尔公主背景故事"}},{q="是谁囚禁了普巴尔公主？",a="她是被天鬃大猩猩穆克拉大王所囚禁的，这只巨大的猿猴统治着岛上周围的野兽。",al={"谁俘虏了普巴尔","普巴尔的俘获者","穆克拉大王俘虏"}},{q="穆克拉大王在哪里？",a="普巴尔公主提到，经常能听到穆克拉大王在岛屿东南侧徘徊。",al={"穆克拉在哪里","穆克拉位置","寻找穆克拉大王"}},{q="解救普巴尔公主需要什么？",a="你需要击败穆克拉大王并找到她的锁链钥匙，然后将其带回以解开束缚她的锁链。",al={"普巴尔锁链钥匙","如何解救普巴尔","解救普巴尔公主的钥匙"}},{q="这一步骤在故事中处于什么位置？",a="这紧接在漂流瓶中的原始求救信息之后，是与穆克拉大王直接对峙，以解救普巴尔公主脱离锁链束缚的关键环节。",al={"漂流瓶任务链","漂流瓶第二部分","普巴尔任务线"}}},fp="19,226,21.304.0,26.182.0,25.206.1,23.208.0,34.123.0,26.81.0,39.110.0,38.135.0"}
P.entries["quest:6301"] = {n="生生不息",s="“重生之环”是部落的一项任务，由烈日石居的塔姆拉·荒原委派，要求收集暗色湖岸边稀有的盖亚之种。面对工业贪婪和石爪山脉战火造成的惨重代价，塔姆拉感到痛心疾首。她试图利用萨满之力为这些坚韧的种子祈福，以恢复山脉被破坏的土壤。这是旨在治愈这片伤痕累累的荒野的修复工作中，至关重要的第一步。",h="“重生之环”是部落的一项任务，由烈日石居的塔姆拉·荒原委派，要求收集暗色湖岸边稀有的盖亚之种。面对工业贪婪和石爪山脉战火造成的惨重代价，塔姆拉感到痛心疾首。她试图利用萨满之力为这些坚韧的种子祈福，以恢复山脉被破坏的土壤。...",kw={"焦炭谷","重生之环","大地母亲","盖亚之种","暗色湖","新生命","石爪山脉","烈日石居","塔姆拉·荒原"},ang={["class:Druid"]="德鲁伊会赞赏这种对自然循环和种子培育的共同关注，因为恢复贫瘠土地的行动与塞纳里奥议会的职责不谋而合。",["class:Shaman"]="塔姆拉的努力体现了萨满修复生态失衡的召唤，证明了灵魂和大地母亲能够修复工业掠夺所造成的破坏。",["race:Tauren"]="对于舒哈鲁人来说，治愈石爪山脉受伤的土壤是向大地母亲尽的一种精神义务，以回应鲁莽的伐木和阵营战争所造成的破坏。"},sec={{t="伤痕累累的荒野",b="石爪山脉的山峰承受着商业开发和连绵战火所留下的深深创伤。在疯狂的伐木行动和敌对阵营的冲突之间，大片的森林已被烧焦、砍伐殆尽，或化为灰烬。对于驻扎在烈日石居的牛头人来说，亲眼目睹自然世界如此迅速地毁灭是一种极大的痛苦。与其仅仅为了守住阵地而战，像塔姆拉·荒原这样的萨满更着眼于古老的自然秩序，努力践行大地母亲的复苏循环。"},{t="暗色湖的种子",b="想要让贫瘠的土地恢复生机，就需要非凡的生命力，而塔姆拉在暗色湖周围发现的稀有盖亚之种正具备这种力量。该湖位于烈日石居以北，其湖岸边孕育着这些坚韧的种子荚。尽管周围地区危机四伏，但这些种子却拥有石爪山脉独有的韧性。一旦回收，塔姆拉就会将祖先的萨满祝福灌注到每一粒种子中，唤醒它们潜藏的力量，为接下来的工作加速生长。"}},faq={{q="收集盖亚之种的目的是什么？",a="盖亚之种拥有非凡的自然生命力，这使它们非常适合用于修复荒芜的土地。塔姆拉·荒原收集它们是为了用大地母亲的祝福和萨满力量对其进行加持，让它们能够迅速发芽，并补充石爪山脉因工业和战争而遭到破坏的地区。",al={"为什么要盖亚之种","盖亚之种的用途","重生之环的目标"}},{q="盖亚之种在哪里？",a="盖亚之种散落在暗色湖的岸边，该湖位于石爪山脉的烈日石居正北方。它们静静地躺在湖泊周围的水边泥土中。",al={"盖亚之种位置","哪里找盖亚之种","暗色湖种子"}},{q="塔姆拉·荒原是谁？",a="塔姆拉·荒原是一位居住在烈日石居的牛头人萨满。由于战火和伐木集团对石爪山脉造成的森林砍伐与破坏，她深感痛苦，因此致力于通过大地母亲的祝福来治愈这片土地。",al={"塔姆拉是谁","塔姆拉·荒原背景"}},{q="种子归还后塔姆拉会做什么？",a="在收到十颗盖亚之种后，塔姆拉会开始诵读神圣的咒语，将萨满能量注入种子，激发它们潜在的自然生长力，以便将它们种植在受灾地区。",al={"种子会怎样","重生之环交任务"}},{q="“重生之环”之后的任务是什么？",a="完成“重生之环”后，可以直接接到任务“新生命”，届时被赋予力量的种子将被带到荒凉的焦炭谷，开始重新培育植被。",al={"重生之环后续","重生之环后的任务","重生之环之后做什么"}},{q="为什么石爪山脉的土地需要治愈？",a="石爪山脉因连绵不断的战争和工业伐木企业的过度砍伐而遭受了严重的环境破坏，留下了难以自然复苏的焦土荒野和伤痕累累的山谷。",al={"石爪山脉为何荒废","石爪山脉发生了什么"}}},fp="16,195,20.334.0,23.304.0,45.214.0,33.165.0,24.167.0,48.181.0,36.132.0,49.177.0"}
P.entries["quest:631"] = {n="萨多尔大桥",s="在一场震撼了湿地北部的毁灭性爆炸发生后，拉格·加玛森请求旅行者在萨多尔大桥的废墟中搜寻一名失踪的矮人侦察兵。黑铁部族对丹莫德发动了残酷的袭击，切断了通信，使当地守军在没有增援的情况下陷入困境。找到老锈锁是揭开破坏活动全貌的第一步。",h="在一场震撼了湿地北部的毁灭性爆炸发生后，拉格·加玛森请求旅行者在萨多尔大桥的废墟中搜寻一名失踪的矮人侦察兵。黑铁部族对丹莫德发动了残酷的袭击，切断了通信，使当地守军在没有增援的情况下陷入困境。找到老锈锁是揭开破坏活动全貌...",kw={"黑铁","丹莫德","加玛森","长须","锈锁","大桥","萨多尔","湿地"},ang={["faction:Alliance"]="萨多尔大桥是连接暴风城、铁炉堡与坚守在阿拉希及希尔斯布莱德的联盟部队的唯一陆路补给走廊。",["race:Dwarf"]="萨多尔大桥的毁灭不仅是对矮人石匠工艺的侮辱，也是黑铁矮人对卡兹莫丹同胞发动的直接打击。"},sec={{t="桥上的雷鸣",b="一场灾难性的爆炸最近摧毁了萨多尔大桥，震碎了连接湿地与阿拉希高地的巨大石桥。当黑铁矮人伏击丹莫德时，驻扎在边境的铜须士兵在破坏中遭受了重创。随着兵力减员和要塞被围，布莱德·长须率领的幸存者被迫针对袭击者进行绝望的防御坚守。"},{t="派往东方的侦察兵",b="为了抢修一条通道并确定向北的道路是否还能使用，布莱德·长须派遣资深侦察兵埃比尼泽·锈锁去检查东侧桥梁。数天过去了，却没有任何报告。由于丹莫德正处于被围困状态，拉格·加玛森和驻军缺乏足够的士兵进入敌方控制的废墟中展开救援远征。"},{t="冷酷的发现",b="冒险进入损毁的桥梁，便能看到黑铁袭击所带来的代价。老锈锁不仅没有带回侦察消息，反而死在了东侧大桥的瓦砾之中。他的尸体以及紧攥在手中的羊皮纸证实了最糟糕的情况：他遭遇了黑铁部族的伏击，而黑铁矮人对这条连接卡兹莫丹与洛丹伦的重要命脉的破坏活动尚未结束。"}},faq={{q="什么是萨多尔大桥？",a="萨多尔大桥是一座巨大的矮人桥梁结构，横跨湿地北部与阿拉希高地之间的裂谷。它是连接卡兹莫丹与北方洛丹伦地区的主要陆路通道。",al={"萨多尔大桥","什么是萨多尔大桥","湿地大桥"}},{q="是谁袭击了萨多尔大桥？",a="黑铁矮人部族袭击了这座大桥以及附近的丹莫德哨所。他们引爆了炸药截断了大桥，使联盟的交通瘫痪，并让铜须守军措手不及。",al={"是谁炸毁了大桥","萨多尔大桥爆炸","谁袭击了丹莫德"}},{q="老锈锁是谁？",a="埃比尼泽·锈锁是为布莱德·长须效力的一名值得信赖的矮人侦察兵。他被派去评估爆炸后东侧大桥的情况，但在任务期间被黑铁部队压制并杀害。",al={"埃比尼泽·锈锁","锈锁是谁","失踪的侦察兵"}},{q="拉格·加玛森在哪里？",a="拉格·加玛森驻扎在饱受战火的丹莫德定居点附近，就在湿地北部的萨多尔大桥南侧。在驻军与铁炉堡失去联系期间，他协助协调防御工作。",al={"拉格·加玛森位置","拉格在哪里","丹莫德任务发布者"}},{q="为什么铁炉堡没有派兵支援丹莫德？",a="袭击的突然性，加上大桥的损毁和丹莫德的被围，导致驻军陷入孤立无援的状态。守军兵力捉襟见肘，无法派出信使或调动部队，只能寄望于过往的冒险者来传递消息。",al={"为什么没有增援","铁炉堡支援湿地","丹莫德增援"}},{q="发现锈锁的尸体后会发生什么？",a="锈锁的遗物中有一份羊皮纸，显示袭击的幕后主使卡姆·深怒在大桥对面藏匿了一批炸药。这开启了一项行动，旨在炸毁这批炸药以免其威胁到剩余的桥体，并最终通过向避难谷地的联盟营地求援来寻求帮助。",al={"锈锁之后的任务","萨多尔大桥后续","萨多尔大桥之后"}}},fp="16,263,21.335.0,17.301.0,14.234.1,25.176.0,30.181.0,21.196.1,31.162.0,43.204.0,46.254.1"}
P.entries["quest:632"] = {n="萨多尔大桥",s="在萨多尔大桥，拉格·加玛森正等待失踪侦察兵的消息。矮人不再从这座巨大的石桥上报告后，他派冒险者去查看老埃比尼泽·拉斯洛克。桥拱下的搜寻或许会揭示对北方补给线的威胁。",h="在萨多尔大桥，拉格·加玛森正等待失踪侦察兵的消息。矮人不再从这座巨大的石桥上报告后，他派冒险者去查看老埃比尼泽·拉斯洛克。桥拱下的搜寻或许会揭示对北方补给线的威胁。",kw={"阿拉希","黑铁","深怒","埃本尼泽·锈锁","拉格·加玛森","萨多尔大桥","湿地"},ang={["faction:Alliance"]="萨多尔大桥是连接铁炉堡和暴风城与北部联盟据点的大动脉，这使得锈锁的发现对大陆安全至关重要。",["race:Dwarf"]="发现黑铁矮人在灼热峡谷以北如此远的地方活动，证明了他们阴险的渗透触角伸得有多深，这威胁到了铁炉堡的同胞。"},sec={{t="侦察兵的最后一战",b="布莱德·长须最初派遣埃本尼泽·锈锁去监视萨多尔大桥的结构完整性和安全性。当与这名侦察兵的联络中断时，人们立刻担心他遭到了暗算。在拱门下方的凹处进行探索，会发现锈锁已经遇害，他在从阴影中突然发起的残忍伏击中倒下，伏击者是黑铁矮人入侵者。"},{t="深怒的命令",b="从锈锁紧握的手指附近撬出了一份写着“深怒”名字的指令。这绝非简单的抢劫或孤立的边境冲突，这份羊皮纸勾勒出了黑铁矮人旨在破坏大桥的蓄意行动。将这份证据带回给加玛森，将使驻军的姿态从例行搜寻转变为紧急的战时防御。"}},faq={{q="埃本尼泽·锈锁是谁？",a="埃本尼泽“老”锈锁是一名联盟矮人，被派去侦察并守卫萨多尔大桥。他在桥下潜行时被黑铁矮人伏击杀害。",al={"谁是锈锁","老锈锁","埃本尼泽·锈锁"}},{q="谁杀了锈锁？",a="他在萨多尔大桥下遭到黑铁矮人特工的伏击，那些特工执行的是卡姆·深怒发布的指令。",al={"谁杀了锈锁","谁伏击了锈锁","锈锁的尸体"}},{q="在锈锁的尸体上发现了什么？",a="在他紧握的拳头旁放着一张羊皮纸，上面写着《深怒的命令》，记录了黑铁矮人针对这座关键北部大桥的秘密阴谋。",al={"他手里有什么","深怒的命令","锈锁身上的羊皮纸"}},{q="拉格·加玛森是谁？",a="拉格·加玛森是一名驻扎在湿地萨多尔大桥南侧的联盟军官，负责确保矮人领地与北方之间的交通安全。",al={"拉格·加玛森","谁是加玛森"}},{q="为什么萨多尔大桥争夺如此激烈？",a="萨多尔大桥是连接卡兹莫丹矮人领地和湿地，通往阿拉希高地和洛丹伦的唯一陆路大桥。保卫它是联盟后勤的关键。",al={"为什么萨多尔大桥很重要","萨多尔大桥的重要性"}},{q="把命令交给拉格·加玛森后会发生什么？",a="意识到威胁的严重性，拉格·加玛森会派你去摧毁一处储存在萨多尔大桥另一侧阿拉希高地的黑铁矮人炸药库，以挫败他们的破坏行动。",al={"接下来发生什么","萨多尔大桥后续"}}},fx={d453191c={q="为什么必须把锈锁尸体旁的命令带回来？",a="埃比尼泽·锈锁已经无法开口，也不能再传递警告，但他紧握的拳头旁那张羊皮纸表明，黑铁矮人已针对萨多尔大桥展开行动。若拉格·加玛森不了解这场伏击，也不检查深怒的书面命令，守卫大桥的联盟军队就会对脚下正在发生的破坏活动一无所知。",al={"为什么要报告锈锁尸体的情况","为什么要带回深怒的命令","锈锁尸体的缘由"}}},fp="16,267,21.357.0,17.380.1,27.191.1,21.123.1,34.141.1,21.184.0,45.196.0,54.184.1"}
P.entries["quest:6321"] = {n="瑟伯切尔的补给",s="“补给瑟伯切尔”是亡灵卫兵博迪瑞格在银松森林的瑟伯切尔发布的一项后勤任务。为了让当地的亡灵卫兵部队拥有足够的装备来对抗森林中潜伏的野兽和天灾军团，必须通过蝙蝠管理员卡洛斯·拉佐克将一份紧急的武器征用订单送往幽暗城的武器供应商处。",h="“补给瑟伯切尔”是亡灵卫兵博迪瑞格在银松森林的瑟伯切尔发布的一项后勤任务。为了让当地的亡灵卫兵部队拥有足够的装备来对抗森林中潜伏的野兽和天灾军团，必须通过蝙蝠管理员卡洛斯·拉佐克将一份紧急的武器征用订单送往幽暗城的武器供...",kw={"蝙蝠管理员","亡灵卫兵","高顿·温德哈姆","哈德瑞克","卡洛斯·拉佐克","博迪瑞格","征用","瑟伯切尔","银松","幽暗城"},ang={["faction:Horde"]="在据点与主城之间建立并维护可靠的飞行网络，是协调各个受争议地区军事防御的根本。",["race:Undead"]="维护像瑟伯切尔这样的前哨站，能确保被遗忘者将势力投射到提瑞斯法林地之外，并为黑暗女王守卫周围的荒野。"},sec={{t="武装前线",b="虽然亡灵卫兵博迪瑞格报告说瑟伯切尔的物资储备相对充足，但银松森林持续不断的消耗导致装备损耗速度惊人。在野兽、游荡的天灾余孽以及好斗的当地威胁的多重压力下，前线装备在战斗中不断损毁或丢失。在执行官哈德瑞克的命令下，博迪瑞格起草了一份直接寄给高顿·温德哈姆的征用订单，这位武器商人就在首都经营业务。如果被遗忘者希望在提瑞斯法林地之外保持他们那脆弱的立足点，确保替换武器和护甲的稳定供应至关重要。"},{t="飞行网络",b="在银松森林那雾气弥漫的道路上徒步运送重要信件和军用物资不仅速度缓慢，而且极易遭到伏击。为了避开这些危险，被遗忘者依靠被捕获并驯养的吸血蝙蝠。将博迪瑞格的征用订单交给蝙蝠管理员卡洛斯·拉佐克，能将地面部队纳入幽暗城更广阔的空中后勤网络，从而建立起将偏远据点与希尔瓦娜斯的首都直接连接起来的空中运输线。"}},faq={{q="博迪瑞格的订单目的是什么？",a="亡灵卫兵博迪瑞格代表执行官哈德瑞克视察了瑟伯切尔的军械库。虽然口粮和一般装备尚可，但仍需要武器来补充在与天灾军团和其他森林威胁的冲突中损毁或丢失的装备。",al={"博迪瑞格为何下令","什么是博迪瑞格的征用订单","补给瑟伯切尔的目的"}},{q="高顿·温德哈姆是谁？",a="高顿·温德哈姆是一位驻扎在幽暗城的武器商人。博迪瑞格特别将这份征用订单寄给他，以满足驻军对新武器的需求。",al={"高顿·温德哈姆是谁","高顿·温德哈姆幽暗城"}},{q="卡洛斯·拉佐克是谁？",a="卡洛斯·拉佐克是驻扎在瑟伯切尔的蝙蝠管理员。他负责管理那些用于在洛丹伦各地运送信使、侦察兵和物资的恐惧蝙蝠。",al={"卡洛斯·拉佐克的职责","谁是蝙蝠管理员"}},{q="为什么要用蝙蝠而不是陆路信使？",a="银松森林中到处都是敌对野兽、游荡的天灾军团和其他危险派系。走陆路的信使会面临不断的伏击，因此空中的蝙蝠航线是通往幽暗城最快、最安全的路径。",al={"为何要飞往幽暗城","为何使用蝙蝠"}},{q="瑟伯切尔面临哪些威胁？",a="瑟伯切尔被敌对势力包围，包括残留的天灾亡灵、狼人、野生野兽以及当地的人类派系，这使得他们必须保持时刻战斗的状态，并需要稳定的装备补给。",al={"瑟伯切尔的威胁","为何亡灵卫兵需要武器"}},{q="这项任务接下来会指向哪里？",a="将订单交给卡洛斯·拉佐克会促使他安排直飞幽暗城的运输，征用订单可以直接送达高顿·温德哈姆手中。",al={"下一个任务是什么","补给瑟伯切尔之后"}}},fp="23,178,21.436.0,18.305.0,38.219.0,22.115.0,19.134.0,38.175.0,37.161.0,31.112.0"}
P.entries["quest:6322"] = {n="迈克尔·加勒特",s="迈克尔·加勒特是一个简单的快递任务，连接了幽暗城的贸易与被遗忘者的飞行网络。在收集了由高顿·温德哈姆在贸易区打包的补给品后，你需要将箱子交给蝙蝠管理员迈克尔·加勒特，以安排飞往瑟伯切尔的空中运输。这突显了被遗忘者如何利用训练有素的吸血蝙蝠，将他们的首都与洛丹伦各地的哨站连接起来。",h="迈克尔·加勒特是一个简单的快递任务，连接了幽暗城的贸易与被遗忘者的飞行网络。在收集了由高顿·温德哈姆在贸易区打包的补给品后，你需要将箱子交给蝙蝠管理员迈克尔·加勒特，以安排飞往瑟伯切尔的空中运输。这突显了被遗忘者如何利用...",kw={"蝙蝠管理员","飞行管理员","高顿·温德哈姆","高顿的箱子","迈克尔·加勒特","瑟伯切尔","银松森林","幽暗城"},ang={["faction:Horde"]="对于从卡利姆多抵达的旅行者来说，被遗忘者的蝙蝠网络是横跨东部王国北部地区的主要快速交通方式。",["race:Undead"]="了解由像迈克尔·加勒特这样的管理员运营的空中补给线，对于维持希尔瓦娜斯在提瑞斯法林地之外的存在至关重要。"},sec={{t="哨站补给",b="在洛丹伦废墟上建立一个新兴王国需要持续的后勤支持。像银松森林中的瑟伯切尔这样的哨站，非常依赖从幽暗城运出的货物、军需品和补给。高顿·温德哈姆在城市的贸易区将必要的野外补给打包成一个箱子，但通过陆路穿过被瘟疫感染的森林运输货物不仅缓慢，而且容易遭到天灾残党或野兽的伏击。"},{t="被遗忘者的羽翼",b="为了避开道路上的危险，被遗忘者依赖由熟练的驯养师饲养和照料的俘获吸血蝙蝠。迈克尔·加勒特在幽暗城的贸易区的栖息处照看这些带翼野兽。将货物交给他，就能确保补给品被绑在蝙蝠身上，直接飞越群山前往银松森林，这也教会了新快递员首都如何与遥远的定居点进行协调。"}},faq={{q="迈克尔·加勒特是谁？",a="迈克尔·加勒特是幽暗城的蝙蝠管理员，驻扎在贸易区。他管理着飞行网络中的吸血蝙蝠，负责安排被遗忘者首都与洛丹伦各地联盟飞行管理员之间的旅行和空中运输。",al={"迈克尔·加勒特","幽暗城蝙蝠管理员","加勒特是谁"}},{q="高顿的箱子里装了什么？",a="该箱子装有由高顿·温德哈姆在贸易区收集的重要物资和野外补给，专门为驻扎在银松森林瑟伯切尔的被遗忘者部队准备。",al={"高顿的箱子","有什么补给","瑟伯切尔箱子"}},{q="为什么要用蝙蝠而不是马车或马匹？",a="从提瑞斯法林地蜿蜒而出进入银松森林的陆路充满了危险，包括游荡的天灾野兽、敌对人类和险恶的地形。通过受过训练的巨型蝙蝠进行空中飞行要快得多，并且可以完全避开地面伏击。",al={"为什么进行蝙蝠飞行","为什么要用蝙蝠","空运补给"}},{q="交给迈克尔·加勒特后，货物会送到哪里？",a="一旦迈克尔·加勒特收到高顿的箱子，货物就会被准备好，由蝙蝠直接飞往驻扎在银松森林瑟伯切尔的蝙蝠管理员处，从而完成整个后勤链。",al={"下一步","迈克尔·加勒特之后","蝙蝠飞往哪里"}},{q="在幽暗城哪里可以找到迈克尔·加勒特？",a="他位于贸易区的西南部，也是从瑟伯切尔飞来的蝙蝠降落的区域。",al={"加勒特在哪里","寻找蝙蝠管理员","幽暗城飞行管理员位置"}},{q="在做这个任务之前需要先去过瑟伯切尔吗？",a="要想在运送货物的同时亲自乘坐蝙蝠，你必须此前与瑟伯切尔的飞行管理员交谈过以解锁航线；否则，你将不得不步行前往那里。",al={"需要瑟伯切尔飞行点","我可以立刻飞行吗"}}},fp="15,221,22.281.0,21.321.0,23.175.0,26.112.0,40.103.0,49.146.0,48.120.0,60.155.0"}
P.entries["quest:6323"] = {n="飞往幽暗城",s="“前往幽暗城”任务旨在向初出茅庐的被遗忘者冒险者介绍部落在洛丹伦的空中飞行网络。信使携带来自饱受战火蹂躏的瑟伯切尔前哨站的武器征用令，搭乘恐惧蝙蝠直飞幽暗城的贸易区，为地区守军补充补给。",h="“前往幽暗城”任务旨在向初出茅庐的被遗忘者冒险者介绍部落在洛丹伦的空中飞行网络。信使携带来自饱受战火蹂躏的瑟伯切尔前哨站的武器征用令，搭乘恐惧蝙蝠直飞幽暗城的贸易区，为地区守军补充补给。",kw={"恐惧蝙蝠","飞行管理员","高顿·温德哈姆","卡洛斯·拉佐克","博迪瑞格的订单","前往幽暗城","瑟伯切尔","贸易区"},ang={["faction:Horde"]="飞行管理员构成了部落领土扩张不可或缺的连接纽带，将艰苦的荒野跋涉转变为快速的战术部署。",["profession:Blacksmithing"]="向高顿·温德哈姆运送订单，让铁匠们得以一窥洛丹伦的后勤脊梁，在这里，每一件铁器都保持着锋利，时刻准备投入战争。",["race:Undead"]="从银松森林飞往首都，彰显了黑暗女王网络的触角和组织能力，确保了孤立的驻军永远不会与幽暗城的工业脱节。"},sec={{t="银松森林之上",b="在被遗忘者的首都与其前线哨所之间保持通讯畅通，需要快速、可靠的交通方式。卡洛斯·拉佐克是驻扎在银松森林瑟伯切尔的蝙蝠管理员，负责管理训练有素的恐惧蝙蝠，这些蝙蝠负责在瘟疫肆虐的土地上运送信使和补给。由于道路上到处都是敌对野兽、月怒狼人以及天灾军团的残余势力，乘空飞行是确保紧急军事请求能够送达首都的最安全、最快捷的方式。"},{t="武装前线",b="当信使降落在幽暗城繁忙的贸易区后，会将博迪瑞格的装备征用令直接交给高顿·温德哈姆。作为一名致力于效忠黑暗女王的幽暗城武器匠，温德哈姆确保了像瑟伯切尔这样的地区哨所始终配备着干净、随时可用的战备武器。对于正在加固边界以抵御周围敌人的新兴被遗忘者政权来说，维持这些防御枢纽至关重要。"}},faq={{q="这次飞往幽暗城的任务目的是什么？",a="这项任务旨在将亡灵卫兵博迪瑞格从瑟伯切尔发出的正式武器征用令直接送交至幽暗城贸易区的一名武器商人高顿·温德哈姆手中，同时教导新的勇士如何使用被遗忘者的飞行网络。",al={"为什么要前往幽暗城","前往幽暗城任务目标","博迪瑞格的订单用途"}},{q="卡洛斯·拉佐克是谁？",a="卡洛斯·拉佐克是驻扎在银松森林瑟伯切尔的蝙蝠管理员。他负责监管被遗忘者所使用的恐惧蝙蝠巢穴，以维持与幽暗城之间的快速交通和通讯。",al={"卡洛斯·拉佐克的职责","瑟伯切尔的蝙蝠管理员是谁"}},{q="高顿·温德哈姆是谁？",a="高顿·温德哈姆是一位位于幽暗城贸易区的被遗忘者武器匠，就在蝙蝠管理员的降落平台附近。他以能让武器保持清洁、锋利并随时供希尔瓦娜斯女王的前线部队使用为荣。",al={"高顿·温德哈姆","高顿·温德哈姆在哪里"}},{q="为什么被遗忘者使用蝙蝠进行交通运输？",a="恐惧蝙蝠是洛丹伦枯萎天空中土生土长的夜行性捕食者。它们提供了在险恶的地表危险之上快速通行的手段，例如野生的狼人、敌对的腐皮豺狼人和天灾军团。",al={"为什么要使用蝙蝠","被遗忘者飞行坐骑"}},{q="完成交付后会发生什么？",a="在收到订单后，高顿·温德哈姆会指引信使去找幽暗城的蝙蝠管理员迈克尔·加勒特，从而建立起一条返回瑟伯切尔的返程飞行路线。",al={"接下来是什么","前往幽暗城的后续任务"}},{q="恐惧蝙蝠在幽暗城的什么地方降落？",a="恐惧蝙蝠降落在幽暗城贸易区中心位置上方高处的蝙蝠栖木上，可以直接通往城里的工匠和补给商人处。",al={"幽暗城蝙蝠降落点","蝙蝠在哪里降落"}}},fp="21,158,21.325.0,16.313.0,52.193.0,19.148.0,22.194.0,41.178.0,43.156.0,47.139.0"}
P.entries["quest:6324"] = {n="向博迪瑞格回报",s="“回到博迪瑞格身边”是一个物流任务，旨在完成银松森林与幽暗城之间的快递运输。在将一份急件送达首都后，快递员被委以运送一箱武器的重任，利用被遗忘者的蝙蝠管理员网络，将其送回瑟伯切尔的亡灵卫兵博迪瑞格手中。",h="“回到博迪瑞格身边”是一个物流任务，旨在完成银松森林与幽暗城之间的快递运输。在将一份急件送达首都后，快递员被委以运送一箱武器的重任，利用被遗忘者的蝙蝠管理员网络，将其送回瑟伯切尔的亡灵卫兵博迪瑞格手中。",kw={"蝙蝠管理员","高顿的箱子","卡洛斯·拉佐克","迈克尔·加勒特","博迪瑞格","瑟伯切尔","银松森林","幽暗城"},ang={["faction:Horde"]="这项任务展示了连接幽暗城与北部大陆各偏远哨站的后勤框架。",["race:Undead"]="保持前线驻军的武装对于保卫洛丹伦和巩固希尔瓦娜斯女王初创的疆域至关重要。"},sec={{t="幽暗城的补给线",b="洛丹伦各地的哨站都严重依赖来自幽暗城的定期补给以维持运转。在银松森林的瑟伯切尔，亡灵卫兵哨兵面临着当地狼人、达拉然残党和天灾军团残部的压力。为偏远驻军提供新锻造的军火，对于确保该地区处于被遗忘者的控制之下至关重要。"},{t="被遗忘者之翼",b="蝙蝠管理员迈克尔·加勒特经营着位于幽暗城贸易区的中央栖木，这里是被遗忘者空中旅行的枢纽。虽然蝙蝠会自然返回首都，但骑手在规划前往偏远哨站的航线之前，必须先与像卡洛斯·拉佐克这样的当地管理员协调。将高顿的箱子运送在洛丹伦的天空之上，教会了快递员被遗忘者是如何将他们分散的据点连接在一起的。"}},faq={{q="高顿的箱子里装的是什么？",a="箱子里装的是幽暗城生产的全新武器，以确保驻扎在瑟伯切尔的亡灵卫兵能够装备精良，应对周围的威胁。",al={"高顿的箱子内容物","我正在给博迪瑞格送什么"}},{q="亡灵卫兵博迪瑞格是谁？",a="亡灵卫兵博迪瑞格是一名驻扎在银松森林瑟伯切尔的被遗忘者士兵，负责管理当地驻军的后勤和防御职责。",al={"博迪瑞格","博迪瑞格是谁"}},{q="迈克尔·加勒特是谁？",a="迈克尔·加勒特是驻扎在幽暗城贸易区的被遗忘者蝙蝠管理员，负责协调横跨洛丹伦的飞行路径。",al={"迈克尔·加勒特","幽暗城蝙蝠管理员"}},{q="为什么在飞往某地之前必须与蝙蝠管理员交谈？",a="被遗忘者的蝙蝠会自然知道回到幽暗城中央栖木的路，但外出的飞行需要先与区域管理员建立航线，以确保顺利到达。",al={"飞行路径规则","蝙蝠管理员的工作方式"}},{q="为什么瑟伯切尔的补给如此重要？",a="瑟伯切尔是被遗忘者在银松森林的主要前哨基地。它稳固了他们针对该地区的狼人族群、月怒威胁和达拉然势力的军事存在。",al={"为什么瑟伯切尔很重要","瑟伯切尔的重要性"}},{q="卡洛斯·拉佐克是谁？",a="卡洛斯·拉佐克是驻扎在银松森林瑟伯切尔的蝙蝠管理员，管理着连接该哨站与幽暗城的栖木蝙蝠。",al={"卡洛斯·拉佐克","瑟伯切尔蝙蝠管理员"}}},fp="16,163,25.241.0,21.324.0,26.120.0,25.138.0,23.122.0,65.184.0,44.169.0,19.139.0"}
P.entries["quest:633"] = {n="萨多尔大桥",s="这项关键的联盟任务要求勇士们守卫萨多尔大桥上唯一幸存的一座桥梁。在伊本瑟·锈铁不幸遇害后，拉格·加玛森发现叛徒卡姆·深怒正企图引爆炸药，切断铁炉堡通往北方的生命线。",h="这项关键的联盟任务要求勇士们守卫萨多尔大桥上唯一幸存的一座桥梁。在伊本瑟·锈铁不幸遇害后，拉格·加玛森发现叛徒卡姆·深怒正企图引爆炸药，切断铁炉堡通往北方的生命线。",kw={"阿拉希高地","黑铁","伊本瑟·锈铁","炸药","卡姆·深怒","麦格尼·铜须","拉格·加玛森","萨多尔大桥","湿地"},ang={["faction:Alliance"]="守住大桥对于大陆安全至关重要；如果这个渡口失守，将联盟军队和资源运往阿拉希高地和洛丹伦将变得极其危险。",["profession:Engineering"]="工程师们可以体会到卡姆·深怒的弹药据点所具备的纯粹破坏力，它们是为摧毁巨大的Titan风格矮人石造建筑而建造的。",["race:Dwarf"]="对于铁炉堡的子民来说，保卫萨多尔大桥不仅能保护King Magni通往北方盟友的生命线，还能打击叛变的黑铁渗透者。"},sec={{t="阴谋败露",b="在萨多尔大桥的下层结构中发现了伊本瑟·锈铁的惨状后，一份回收的文件揭露了更黑暗的企图。黑铁煽动者卡姆·深怒，这座大桥最初被毁的始作俑者，并未就此罢手。在摧毁了其中一座宏伟的石桥之后，他的破坏网络在阿拉希高地的北部边界处又安放了第二批重型弹药，准备彻底完成破坏。"},{t="拯救生命线",b="萨多尔大桥是将卡兹莫丹和暴风城这两个南方王国与战火纷飞的北方领土连接起来的主要陆路通道。为了保护这条路线，拉格·加玛森下令在卡姆·深怒的同谋者部署这些炸药之前，对阿拉希高地的破坏据点进行先发制人的打击。引爆炸药消除了眼前的危险，保留了铁炉堡通往北方的通路，但加玛森仍然极度缺乏防守这一缺口的部队。"}},faq={{q="卡姆·深怒是谁？",a="卡姆·深怒是策划破坏萨多尔大桥的黑铁矮人主谋。他不满足于摧毁第一座拱桥，还在阿拉希高地的深渊对岸隐藏了额外的炸药，企图摧毁剩下的大桥。",al={"卡姆·深怒","谁炸毁了萨多尔大桥","萨多尔大桥幕后主谋"}},{q="萨多尔大桥为什么在战略上如此重要？",a="这座大桥是跨越湿地和阿拉希高地之间巨大深渊的唯一陆路桥梁。如果被切断，联盟将失去在铁炉堡、暴风城以及他们在洛丹伦北部坚守阵地的盟友之间的主要陆路补给线。",al={"为什么萨多尔大桥很重要","萨多尔大桥背景故事"}},{q="伊本瑟·锈铁发生了什么事？",a="伊本瑟·锈铁是一位在桥下深处被谋杀的铁炉堡守卫。正是通过他的调查以及从他的遗体旁回收的文件，拉格·加玛森才发现了卡姆·深怒隐藏的炸药据点。",al={"伊本瑟·锈铁之死","伊本瑟是谁"}},{q="炸药据点藏在哪里？",a="炸药被藏在大桥另一侧的阿拉希高地边界，位置靠近，足以让卡姆·深怒的同谋者迅速将其运送到尚存的桥梁结构处。",al={"炸药位置","炸药在哪里","补给点位置"}},{q="是谁下令摧毁这些炸药？",a="驻扎在湿地一侧萨多尔大桥的矮人军官拉格·加玛森下达了定位并摧毁该据点的命令，以纪念伊本瑟的牺牲并保护剩下的大桥。",al={"谁发布了这个任务","拉格·加玛森"}},{q="弹药被摧毁后会发生什么？",a="虽然眼前的破坏企图被挫败，但拉格·加玛森意识到他的驻军在没有援助的情况下无法长期守住这座受损的大桥。在等待铁炉堡的预备队时，他向避难谷地联盟营地的尼艾丝队长发出了增援请求。",al={"萨多尔大桥之后发生什么","联盟的请求任务"}}},fp="16,162,15.391.0,19.348.1,20.212.0,47.250.0,36.178.1,40.164.0,46.197.0,47.318.1"}
P.entries["quest:634"] = {n="请求援助",s="《给联盟的求援信》包含了来自丹莫德幸存矮人守军的一份绝望请求，要求横跨萨多尔大桥向阿拉希高地派遣援军。在驻地遭到黑铁矮人渗透者的屠杀后，这些矮人向驻扎在避难谷地的人类部队寻求援助，却发现联盟已自顾不暇。",h="《给联盟的求援信》包含了来自丹莫德幸存矮人守军的一份绝望请求，要求横跨萨多尔大桥向阿拉希高地派遣援军。在驻地遭到黑铁矮人渗透者的屠杀后，这些矮人向驻扎在避难谷地的人类部队寻求援助，却发现联盟已自顾不暇。",kw={"阿拉希高地","尼艾丝队长","黑铁","丹莫德","布莱德","避难谷地","拉格·加玛森","激流堡","萨多尔大桥"},ang={["faction:Alliance"]="这次交流凸显了联盟在东部王国北部依然处于分裂状态，当地守军各自为战，陷入了孤立无援的绝望战斗中。",["race:Dwarf"]="对于矮人而言，这次任务凸显了像丹莫德这样的北方驻地所遭受的痛苦孤立，证明了即使是长期的人类盟友，也因深陷重围而无力伸出援手。",["race:Human"]="人类旅行者亲眼目睹了尼艾丝队长的苦涩与悲伤，他正面临着在坚守联盟兄弟情谊与为保卫沦陷的激流堡而战之间的抉择。"},sec={{t="深渊彼端的呼喊",b="在丹莫德遭到摧毁且萨多尔大桥被黑铁矮人破坏之后，矮人幸存者在湿地的北缘维持着一个岌岌可危的据点。由于铁炉堡的主力预备队尚未抵达，拉格·加玛森和布莱德·长须将目光投向了北方的阿拉希高地。在得知联盟在避难谷地建立了一个营地后，加玛森派遣了一名信使穿过那座支离破碎的桥梁，恳求尼艾丝队长提供紧急军事援助。"},{t="激流堡的困境",b="当抵达避难谷地时，北方联盟严峻的现实便显露无疑。尼艾丝队长向布莱德·长须的士兵们表示了深切的同情，但他无法抽调哪怕一名战士。激流堡本身已成废墟，被辛迪加潜行者、石拳食人魔和枯木巨魔所淹没。激流堡的幸存守军正全力以赴地收复他们的祖国首都。受制于荣誉与自身绝望的处境，尼艾丝被迫传话回去，告知大桥上的矮人们必须孤军奋战。"}},faq={{q="是谁向避难谷地发出了求援信？",a="拉格·加玛森，驻扎在湿地边界萨多尔大桥被毁的桥头堡附近，代表布莱德·长须及丹莫德的残余守军发出了这份求援信。",al={"谁发出了给联盟的求援信","拉格·加玛森任务","谁在寻求帮助"}},{q="为什么矮人需要避难谷地的帮助？",a="丹莫德遭到黑铁氏族渗透者突如其来的残酷攻击而陷落，这些渗透者还破坏了萨多尔大桥。虽然幸存者们正在等待来自铁炉堡的重兵支援，但他们目前的人数太少，无法独自夺回定居点并守住通道。",al={"为什么需要联盟的帮助","为什么请求避难谷地","丹莫德援军"}},{q="为什么尼艾丝队长拒绝派遣士兵？",a="尼艾丝队长无法抽调任何部队，因为激流堡王国本身已经分崩离析，化为废墟。避难谷地的人类部队正全力投入到从辛迪加、食人魔和森林巨魔手中夺回激流堡的绝望战役中。",al={"为什么尼艾丝不提供帮助","为什么避难谷地拒绝","尼艾丝队长的回答"}},{q="避难谷地在哪里？",a="避难谷地位于阿拉希高地中部的主干道旁，在湿地与阿拉希之间萨多尔大桥通道的北面。",al={"避难谷地位置","尼艾丝队长在哪里","如何找到避难谷地"}},{q="丹莫德发生了什么事？",a="丹莫德被黑铁氏族攻陷并洗劫，他们通过群山渗透进来，切断了南部矮人领地与北方联盟领土之间的陆路通道。",al={"丹莫德背景资料","丹莫德发生了什么","谁袭击了丹莫德"}},{q="尼艾丝队长拒绝请求后发生了什么？",a="尼艾丝队长向布莱德·长须表示遗憾，确认不会有人类援军到来。桥上的矮人幸存者必须依靠自己的智谋、游荡的冒险者以及来自远方铁炉堡的增援。",al={"给联盟的求援信后续","求援信任务后的下一个任务","任务线延续"}}},fp="20,249,22.432.0,24.410.0,36.158.0,48.211.0,47.188.0,31.142.0,26.190.0,56.232.0"}
P.entries["quest:6341"] = {n="泰达希尔的渔业",s="“泰达希尔的馈赠”是由鲁瑟兰村的妮莎·影歌发布的一项初步任务。为了比较岛上鱼类异常庞大的体型和丰富的数量与大陆沿岸鱼类的差异，她准备了一袋鱼骨和鳞片，打算将其跨过海峡运往黑海岸。将这个包裹交给当地的角鹰兽管理员，是跨海前往奥伯丁的第一步。",h="“泰达希尔的馈赠”是由鲁瑟兰村的妮莎·影歌发布的一项初步任务。为了比较岛上鱼类异常庞大的体型和丰富的数量与大陆沿岸鱼类的差异，她准备了一袋鱼骨和鳞片，打算将其跨过海峡运往黑海岸。将这个包裹交给当地的角鹰兽管理员，是跨海前...",kw={"奥伯丁","泰达希尔的馈赠","黑海岸","角鹰兽","莱尔德","妮莎·影歌","鲁瑟兰村","维斯派塔斯"},ang={["faction:Alliance"]="鲁瑟兰和奥伯丁之间的路线是连接暗夜精灵主城与卡利姆多北部其余地区的重要交通动脉。",["race:NightElf"]="对于暗夜精灵旅行者来说，这段旅程标志着从泰达希尔安全的高地，向黑海岸阴影笼罩的大陆海岸过渡的传统路径。"},sec={{t="渔夫的研究",b="在世界之树巨大的枝干下，鲁瑟兰村周围受庇护的水域中栖息着体型惊人且数量庞大的海洋生物。妮莎·影歌观察到当地渔民捕获的丰厚渔获，希望能探明这种生命力是延伸到了古老的大陆海岸，还是仅仅局限于泰达希尔滋养的水域。为了验证她的理论，她准备了一袋鳞片和鱼骨，让跨海峡位于奥伯丁的同行鱼贩莱尔德进行检查。"},{t="安排行程",b="在岛屿枝干与卡利姆多大陆之间的广阔海峡运送货物和旅客，需要可靠的飞行坐骑。妮莎没有选择用小船运送包裹，而是让旅客直接去找村里的角鹰兽管理员维斯派塔斯。将收藏品交给他，旅客就能安排好必要的物流，骑上训练有素的野兽，直接将样本运送到黑海岸的码头。"}},faq={{q="妮莎想要调查什么？",a="妮莎·影歌注意到鲁瑟兰村周围水域捕获的鱼类异常巨大且数量丰富。她想把这些骨头和鳞片样本送到海的另一边，将泰达希尔的渔获与黑海岸大陆沿岸的鱼类进行比较。",al={"妮莎的目标","为什么要比较鱼类","泰达希尔的馈赠任务目的"}},{q="谁在奥伯丁接收这些鱼类样本？",a="这些收藏品是寄给莱尔德的，他是一位驻扎在黑海岸大陆沿岸奥伯丁村的鱼贩。",al={"谁接收妮莎的收集品","黑海岸的莱尔德","奥伯丁鱼贩"}},{q="为什么要将包裹交给维斯派塔斯，而不是直接前往奥伯丁？",a="维斯派塔斯是鲁瑟兰村的角鹰兽管理员。将收藏品交给他可以安排直接的空中运输，让你能够乘坐角鹰兽横跨大海前往黑海岸。",al={"为什么找维斯派塔斯","维斯派塔斯是谁","鲁瑟兰角鹰兽管理员"}},{q="鲁瑟兰村相对于泰达希尔的位置在哪里？",a="鲁瑟兰村位于泰达希尔南部的海平面基座上，通过翡翠传送门与达纳苏斯相连。它是进出世界之树的船舶和角鹰兽的主要沿海避风港和港口。",al={"鲁瑟兰位置","妮莎·影歌在哪里","如何到达鲁瑟兰"}},{q="将收藏品交给维斯派塔斯后会发生什么？",a="维斯派塔斯会收下收藏品并提供后续任务“飞往奥伯丁”，让你骑着角鹰兽飞越海峡，直接抵达黑海岸。",al={"下一步飞往奥伯丁","泰达希尔的馈赠之后","维斯派塔斯做什么"}},{q="这是暗夜精灵离开新手区的任务吗？",a="是的。这个任务线向年轻的暗夜精灵冒险者介绍了飞行点，并引导他们离开岛屿树冠，前往卡利姆多大陆，继续他们在黑海岸的旅程。",al={"离开泰达希尔","10级暗夜精灵任务","前往黑海岸"}}},fp="24,191,19.308.0,17.203.0,36.189.0,47.81.0,77.158.0,62.199.0,55.128.0,58.152.0"}
P.entries["quest:6342"] = {n="飞往奥伯丁",s="这项任务旨在向离开泰达希尔的冒险者介绍暗夜精灵的空中交通网络。在鲁瑟兰村接受了角鹰兽管理员维斯派塔斯的委托后，旅客们将飞越海洋，把一捆硕大的海洋标本送到奥伯丁的莱尔德手中。",h="这项任务旨在向离开泰达希尔的冒险者介绍暗夜精灵的空中交通网络。在鲁瑟兰村接受了角鹰兽管理员维斯派塔斯的委托后，旅客们将飞越海洋，把一捆硕大的海洋标本送到奥伯丁的莱尔德手中。",kw={"奥伯丁","黑海岸","飞行航线","飞往奥伯丁","角鹰兽","莱尔德","奈莎·影歌","鲁瑟兰村","泰达希尔","维斯派塔斯"},ang={["faction:Alliance"]="角鹰兽是联盟在卡利姆多北部的主要空中交通网络，将沿海哨所直接与首都连接起来。",["race:NightElf"]="乘坐角鹰兽飞往奥伯丁，对于从泰达希尔踏上祖先所在大陆的年轻卡多雷来说，是一个标志性的成年礼。"},sec={{t="飞往黑海岸",b="对于许多离开泰达希尔枝干的年轻冒险者来说，鲁瑟兰村标志着避风港与广阔世界之间的分界线。虽然有一艘普通的渡轮往返于这座岛屿避风港和卡利姆多大陆之间，但暗夜精灵同样依赖他们驯养的角鹰兽。受奈莎·影歌之托，旅客们带着一包稀有的鱼类标本，骑上这些长着翅膀的野兽，建立起他们通往黑海岸的第一条飞行航线。"},{t="奇怪的渔获",b="这次运送的东西引起了黑海岸渔民们浓厚的兴趣。莱尔德在奥伯丁码头等待着奈莎的研究成果，当他检查这些渔获时，发现鱼鳞竟有拳头那么大，而颌骨更是比大陆的标本大出近一倍。世界之树底部周围的岛屿水域似乎孕育着变异或异常巨大的生物，这种奇观暗示着泰达希尔本身所蕴含的强大而躁动的力量。"}},faq={{q="这次飞行的目的是什么？",a="这段旅程是一堂关于连接各定居点飞行航线的实践课，同时也负责将鲁瑟兰村附近捕获的异常鱼类研究样本送到奥伯丁的莱尔德手中。",al={"为什么我要飞往奥伯丁","飞往奥伯丁任务目标","为什么要飞行"}},{q="是谁寄送了包裹，里面装的是什么？",a="这个包裹来自渔夫奈莎·影歌。里面装有鲁瑟兰村周边水域的鱼类标本，包括巨大的鱼鳞和一块超大的颌骨。",al={"尼莎的货物","包裹里有什么","谁寄送了包裹"}},{q="为什么泰达希尔的鱼如此巨大？",a="莱尔德注意到那块颌骨的尺寸几乎是正常鱼类的两倍，而鱼鳞则有拳头那么大。与黑海岸的大陆海岸相比，环绕着泰达希尔世界之树的水域似乎孕育着体型异常巨大的野生生物。",al={"为什么鱼体型巨大","鲁瑟兰鱼类尺寸","巨大的鱼鳞"}},{q="维斯派塔斯是谁？",a="维斯派塔斯是驻扎在鲁瑟兰村的角鹰兽管理员。他负责照料暗夜精灵的坐骑，并协调跨越海面飞往卡利姆多大陆的空中旅行。",al={"维斯派塔斯背景故事","谁是角鹰兽管理员"}},{q="莱尔德是谁？",a="莱尔德是一位常驻黑海岸奥伯丁的暗夜精灵渔夫。他研究当地的水生生物，并将大陆的渔获与在泰达希尔附近捕获的渔获进行对比。",al={"莱尔德背景故事","莱尔德是谁","黑海岸的莱尔德"}},{q="不坐飞机能在鲁瑟兰和奥伯丁之间旅行吗？",a="可以。有一艘定期渡轮往返于鲁瑟兰村码头和奥伯丁码头之间，提供了一种除角鹰兽飞行之外的交通方式。",al={"前往奥伯丁的船","前往黑海岸的渡轮","前往奥伯丁的其他方式"}}},fp="19,132,24.326.0,15.314.0,35.135.0,44.162.0,42.181.0,18.150.0,13.158.0,63.142.0"}
P.entries["quest:6343"] = {n="飞回泰达希尔",s="这个任务指引年轻的旅行者从奥伯丁回到鲁瑟兰村，将莱尔德的调查结果交给娜萨·影歌。它是一项入门跑腿任务，旨在教导冒险者如何往返于卡利姆多大陆与泰达希尔之间。",h="这个任务指引年轻的旅行者从奥伯丁回到鲁瑟兰村，将莱尔德的调查结果交给娜萨·影歌。它是一项入门跑腿任务，旨在教导冒险者如何往返于卡利姆多大陆与泰达希尔之间。",kw={"奥伯丁","卡莱斯·月羽","黑海岸","莱尔德","娜萨·影歌","返回娜萨处","鲁瑟兰村","泰达希尔"},ang={["faction:Alliance"]="奥伯丁和鲁瑟兰村构成了至关重要的海上门户，将卡利姆多北部的暗夜精灵定居点与艾泽拉斯各地更广泛的联盟利益连接起来。",["race:NightElf"]="对于第一次离开泰达希尔枝干去冒险的暗夜精灵来说，这次交流标志着他们第一次正式的差事，将新的岛屿避风港与古老的黑海岸大陆连接了起来。"},sec={{t="跨海信使",b="在将娜萨·影歌最初的询问传达给奥伯丁的莱尔德之后，旅行者受托将他的书面观察带回水域另一端。莱尔德注意到黑海岸和泰达希尔海岸之间的渔获存在显著差异，他怀疑伟大的世界之树本身改变了当地的海洋生物。为了回到鲁瑟兰村，冒险者既可以从角鹰兽管理员卡莱斯·月羽那里租借飞行坐骑，也可以登上定期往返于奥伯丁码头的渡轮。"},{t="奇特的赏赐",b="在鲁瑟兰村收到莱尔德的回复后，娜萨对海洋生物的显著差异表现出了极大的兴趣。虽然世界之树附近鱼类的巨大体型为当地渔民带来了直接的好处，但其根本原因在卡多雷之中仍然是一个未解之谜。娜萨决定将这一发现与村民们分享，并满足于目前收获丰富的海产，同时密切关注真正导致这种现象的力量。"}},faq={{q="谁发放和完成这个任务？",a="这个任务由黑海岸奥伯丁的渔夫莱尔德发放。任务在泰达希尔脚下的鲁瑟兰村由娜萨·影歌处交还。",al={"任务发放者","任务交还地点","谁发布任务"}},{q="回到鲁瑟兰村最快的方法是什么？",a="你可以与奥伯丁的卡莱斯·月羽交谈进行快速的角鹰兽飞行，或者走上长长的码头搭乘定期的客运渡轮回到鲁瑟兰村的码头。",al={"如何返回","前往鲁瑟兰村","渡轮或角鹰兽"}},{q="为什么莱尔德要研究这些鱼？",a="莱尔德注意到黑海岸沿岸的渔获与泰达希尔周围收获的鱼类有很大不同。他怀疑世界之树的蓬勃生长和独特的能量正在直接改变周围的野生生物。",al={"为什么研究鱼类","鱼类差异","莱尔德的回复背景"}},{q="娜萨有没有弄清楚为什么这些鱼如此怪异？",a="并不是立刻就弄清楚了。娜萨注意到了这种显著的差异，并认为有必要进行进一步的调查，但目前她满足于与当地村民分享这份报告，并在此期间享受丰盛的渔获。",al={"为什么鱼会变大","泰达希尔鱼类之谜"}},{q="这个任务之前有什么？",a="该任务直接承接“飞往奥伯丁”，该任务指引旅行者从鲁瑟兰村前往黑海岸，将娜萨原本给莱尔德的信送达。",al={"前置任务","上一个任务","飞往奥伯丁"}},{q="这个任务链的目的是什么？",a="除了介绍泰达希尔对当地野生动物的神秘生态影响外，这个运送任务链还是一项通过仪式，教导年轻的暗夜精灵冒险者如何通过船只和飞行管理员在他们的岛屿家园和卡利姆多大陆之间通勤。",al={"为什么要完成这个任务","旅行任务"}}},fp="15,182,26.346.0,16.385.0,36.137.0,51.151.0,31.187.0,48.205.0,29.130.0,40.204.0"}
P.entries["quest:6344"] = {n="尼莎·影歌",s="“内莎·影歌”是一个引导性送信任务，由达纳苏斯的迈德兰努尔提供。它引导初出茅庐的冒险者从世界之树向下前往鲁瑟兰村，去见鱼类商人内莎·影歌。这项任务是将这座树冠之城与下方的海岸和港口连接起来的第一步。",h="“内莎·影歌”是一个引导性送信任务，由达纳苏斯的迈德兰努尔提供。它引导初出茅庐的冒险者从世界之树向下前往鲁瑟兰村，去见鱼类商人内莎·影歌。这项任务是将这座树冠之城与下方的海岸和港口连接起来的第一步。",kw={"奥伯丁","信使","黑海岸","达纳苏斯","迈德兰努尔","内莎·影歌","传送门","鲁瑟兰村","神殿花园"},ang={["faction:Alliance"]="这项任务引入了将孤立的泰达希尔岛与卡利姆多上其余联盟领土连接起来的关键物流网络。",["race:NightElf"]="对于暗夜精灵冒险者来说，这段旅程标志着他们从达纳苏斯宁静的高处，向连通着家园与古老黑海岸的繁忙沿海路线的传统迈进。"},sec={{t="树冠之外的跑腿任务",b="在达纳苏斯，迈德兰努尔一直在关注着寻找工作和目标的旅行者。当鱼类商人内莎·影歌需要将一个包裹送往海对岸的黑海岸时，迈德兰努尔就会把能干的信使指引向海岸方向。虽然许多年轻的暗夜精灵在旅途初期完全待在泰达希尔的枝叶间，但这个简单的请求鼓励他们放眼看向大陆。"},{t="前往码头",b="要到达鲁瑟兰村，需要穿过神殿花园附近城市西侧的闪光树根传送门。传送门穿过世界之树，直达海平面的根部，那里的渔港和角鹰兽栖息地将泰达希尔与卡利姆多的其他地区连接起来。内莎·影歌就在那里从事贸易，准备发往奥伯丁港口的货物。"}},faq={{q="谁提供这个任务？",a="该任务由位于达纳苏斯战士区的迈德兰努尔提供。",al={"任务发布者","如何获取内莎·影歌任务","迈德兰努尔位置"}},{q="我该如何前往鲁瑟兰村？",a="前往达纳苏斯神殿花园的西边。穿过巨大的发光树门，即可立即传送到泰达希尔底部的鲁瑟兰村。",al={"如何到达鲁瑟兰村","鲁瑟兰传送门","离开达纳苏斯"}},{q="内莎·影歌是谁？",a="内莎·影歌是一位驻扎在鲁瑟兰村码头的精灵鱼类供货商。她负责监督泰达希尔与黑海岸大陆之间的货物和包裹运输。",al={"内莎·影歌角色","内莎负责的工作","内莎·影歌非玩家角色"}},{q="这个任务链通向哪里？",a="与内莎交谈后会立即开启“泰达希尔的馈赠”，该任务会引导冒险者找到飞行管理员，并提供他们第一次跨越海面飞往奥伯丁的飞行服务。",al={"内莎·影歌后续任务","任务链后续","泰达希尔飞行任务链"}},{q="内莎与玛维·影歌有关联吗？",a="虽然她们都姓影歌，但没有记录表明内莎——一位平凡的码头鱼类商人，与传奇守望者玛维·影歌之间存在任何个人联系。",al={"内莎与玛维的关系","影歌家族","内莎是玛维的亲戚吗"}},{q="为什么这个跑腿任务对年轻的冒险者很重要？",a="它起到了主要的导航指引作用，教会新英雄如何离开泰达希尔的顶端，发现下方的码头，并学会使用角鹰兽飞行点到达卡利姆多大陆。",al={"为什么要完成此任务","任务意义"}}},fp="16,189,26.330.0,23.299.0,22.69.0,35.149.0,24.147.0,33.151.0,37.169.0,51.154.0"}
P.entries["quest:635"] = {n="山中的水晶",s="密斯莱尔坠饰在你手中跳动，一股恳求的意念传入你的脑海，仿佛有人迫切需要你的帮助。幻象向你展示了一颗从阿拉希北部山脉地面升起的闪亮水晶，你感到自己被那个地方所吸引。",h="密斯莱尔坠饰在你手中跳动，一股恳求的意念传入你的脑海，仿佛有人迫切需要你的帮助。幻象向你展示了一颗从阿拉希北部山脉地面升起的闪亮水晶，你感到自己被那个地方所吸引。",kw={"阿拉希高地","水晶","山中的水晶","密斯莱尔坠饰","密斯莱尔碎片","幻象"},sec={{t="无声的恳求",b="当你握住这枚坠饰时，它开始跳动。一股恳求的意念从中传来，仿佛有人正试图联系你并迫切需要你的帮助。随后，一个幻象在你眼前展开：那是阿拉希北部的群山，还有一颗从地面突出的闪亮水晶。你感到自己被那个地方所吸引。"},{t="在水晶处",b="当你找到这颗水晶时，它开始跳动，仿佛有一股活着的生命力被困在其中。"}},faq={{q="是什么开启了这段旅程？",a="这段旅程始于密斯莱尔坠饰。当你握住它时，它会跳动，并且你会感受到来自某位迫切需要你帮助之人的恳求。",al={"如何获得山中的水晶","密斯莱尔坠饰来自哪里","山中的水晶起始"}},{q="幻象将你引向何方？",a="它将你引向阿拉希北部山脉中矗立的一颗闪亮水晶，你感到自己被那个地方所吸引。",al={"水晶在哪里","山中的水晶位置","从幻象中寻找水晶"}}},fp="24,152,13.210.0,14.68.1,25.121.0,27.96.0"}
P.entries["quest:6361"] = {n="一捆兽皮",s="“一捆兽皮”是贫瘠之地的一项入门级运送任务，由十字路口的牛头人加翰·鹰翼发布。他请求旅行者将腌制好的野兽毛皮带过卡利姆多中部，送往雷霆崖进行制皮。这项差事旨在向部落新信使介绍十字路口的双足飞龙管理员及其飞行运输机制。",h="“一捆兽皮”是贫瘠之地的一项入门级运送任务，由十字路口的牛头人加翰·鹰翼发布。他请求旅行者将腌制好的野兽毛皮带过卡利姆多中部，送往雷霆崖进行制皮。这项差事旨在向部落新信使介绍十字路口的双足飞龙管理员及其飞行运输机制。",kw={"安哈努","一捆兽皮","十字路口","迪弗拉克","加翰·鹰翼","制皮","贫瘠之地","雷霆崖","双足飞龙"},ang={["faction:Horde"]="这次运送突显了连接卡利姆多部落基地的后勤工作，依靠像迪弗拉克这样的兽人兽栏管理员来跨越盟军领土之间的地理距离。",["race:Tauren"]="对于牛头人旅行者来说，这项差事代表了游荡在祖先之地贫瘠之地的猎人与定居在雷霆崖巨大台地上的工匠之间持续的合作关系。"},sec={{t="穿越大草原的贸易",b="十字路口是整个贫瘠之地商业与旅行的繁华中心，将兽人、巨魔和牛头人连接在干旱的平原上。猎人们不断地从大草原游荡的野兽身上采集毛皮和肉，但当地哨所缺乏就地加工所有原材料的设施。加翰·鹰翼收集区域狩猎得来的毛皮，并依靠路过的旅行者将其运往西边的雷霆崖，那里的制皮大师可以为部落制作重要的装备。"},{t="飞上蓝天",b="徒步背着沉重的货物穿过贫瘠之地崎岖的小路，再爬上莫高雷，是一段艰苦的旅程，还要时刻面临野猪人的伏击和捕食者。为了加快贸易速度，加翰指示信使直接去找十字路口的双足飞龙管理员迪弗拉克。将货物托付给迪弗拉克，并乘坐受过训练的双足飞龙起飞，这展示了将部落分散的定居点连接在一起的重要后勤网络。"}},faq={{q="谁发布了“一捆兽皮”任务？",a="加翰·鹰翼，一位位于贫瘠之地十字路口的牛头人，提供了这个任务。他收集了当地动物的毛皮，并寻找一位可靠的信使帮助将它们运往雷霆崖。",al={"任务发布者","谁发布一捆兽皮","在哪里获取一捆兽皮"}},{q="我应该把一捆兽皮带给谁？",a="你需要将包裹直接带给迪弗拉克，他是驻扎在十字路口站点的兽人双足飞龙管理员。他负责处理十字路口与其他主要部落枢纽之间的空中交通。",al={"任务提交人","兽皮要送到哪里","该找谁对话"}},{q="把毛皮交给迪弗拉克之后会发生什么？",a="迪弗拉克会提供后续任务，指示你骑上双足飞龙，直接将货物运送给安哈努，他是一位在雷霆崖高耸的峭壁之上等待的制皮师。",al={"下一个任务","一捆兽皮后续","后续任务"}},{q="为什么要把这些毛皮送到雷霆崖？",a="加翰·鹰翼与雷霆崖的一位名叫安哈努的同事合作，他将贫瘠之地野兽的生毛皮加工成成品皮甲和商品，供牛头人及其部落盟友使用。",al={"为什么去雷霆崖","安哈努与兽皮","兽皮的作用"}},{q="为什么要使用双足飞龙而不是步行？",a="徒步穿越广阔的贫瘠之地并攀登巨大的雷霆崖台地既危险又缓慢。双足飞龙可以提供快速、安全的交通方式，飞越充满敌意的大草原野生动物和野猪人部族。",al={"为什么要飞往雷霆崖","双足飞龙旅行"}},{q="这需要先有飞行管理员经验吗？",a="这个任务旨在为部落冒险者提供飞行管理员系统的早期介绍，让你熟悉迪弗拉克的站点，以便你能利用双足飞龙进行长距离的区域旅行。",al={"飞行点需求","是否需要飞行点"}}},fp="17,197,24.271.0,19.282.0,38.189.0,42.150.0,46.147.0,48.153.0,40.187.0,49.133.0"}
P.entries["quest:6362"] = {n="飞往雷霆崖",s="这个任务引导年轻的部落冒险者搭乘双足飞龙，完成他们在卡利姆多的首次飞行点航行。旅行者们带着一捆鞣制好的兽皮，从贫瘠之地干燥的十字路口出发，将贵重的皮革补给品直接运送到雷霆崖的高地。",h="这个任务引导年轻的部落冒险者搭乘双足飞龙，完成他们在卡利姆多的首次飞行点航行。旅行者们带着一捆鞣制好的兽皮，从贫瘠之地干燥的十字路口出发，将贵重的皮革补给品直接运送到雷霆崖的高地。",kw={"安哈努","贫瘠之地","一捆兽皮","十字路口","迪弗拉克","赫瓦军需处","飞往雷霆崖","双足飞龙"},ang={["faction:Horde"]="通过双足飞龙进行可靠的空中旅行，对于将贫瘠之地偏远的哨站与杜隆塔尔和莫高雷的主要堡垒连接起来至关重要。",["race:Tauren"]="对于从贫瘠之地归来的年轻牛头人来说，这次飞行让他们可以轻松地直抵他们民族宏伟首府的最高点。"},sec={{t="飞越热带草原",b="对于许多穿越贫瘠之地的旅行者来说，预订迪弗拉克的飞行服务，标志着他们第一次背负着双足飞龙翱翔于天空。这些长着翅膀的飞龙在部落初创时期分散的定居点之间提供了至关重要的空中交通，避开了充满危险、被野猪人和半人马部落潜伏的地面路线。"},{t="军需处的兽皮",b="这批货物是一捆在贫瘠之地加工好的兽皮，目的地是雷霆崖赫瓦军需处工作的工匠安哈努。安哈努的工坊位于中部高地的巨大双足飞龙栖息处正下方，他依靠从各地平原狩猎哨站运来的原始补给品，为当地的战士和猎人装备护甲。"}},faq={{q="谁发布了“飞往雷霆崖”这个任务？",a="贫瘠之地十字路口的双足飞龙管理员迪弗拉克，会向收集到一捆兽皮的旅行者提供这项任务。",al={"任务发布者","飞往雷霆崖任务起点","迪弗拉克位置"}},{q="安哈努是谁，他在哪里可以找到？",a="安哈努是一位驻扎在雷霆崖赫瓦军需处的牛头人工匠，工坊就在城市双足飞龙栖息处的正下方。",al={"安哈努在哪里","安哈努位置","赫瓦军需处"}},{q="这次运输的是什么物品？",a="你携带的是从贫瘠之地送来的一捆加工过的兽皮，安哈努打算立即将其用于皮革加工和护甲制作。",al={"我运送的是什么","一捆兽皮"}},{q="为什么要乘坐双足飞龙而不是步行？",a="双足飞龙可以直接飞越贫瘠之地抵达雷霆崖的高地，避开了进入莫高雷漫长的地面旅程，并直接降落在城市的双足飞龙塔上。",al={"为什么乘飞机去雷霆崖","飞行点的好处"}},{q="这条运送任务链从哪里开始？",a="这次运送始于十字路口的加翰·鹰翼，他在前置任务“一捆兽皮”中整理好了这捆鞣制好的兽皮。",al={"前置任务","兽皮任务线"}},{q="交付兽皮之后接下来要做什么？",a="收到兽皮后，安哈努会指引旅行者上楼直接与雷霆崖的双足飞龙管理员塔尔交谈。",al={"后续任务","飞往雷霆崖的后续"}}},fp="21,147,25.248.0,20.256.0,42.107.0,39.110.0,43.90.0,39.156.0,37.126.0,43.107.0"}
P.entries["quest:6363"] = {n="双足飞龙管理员塔尔",s="“风骑士训练师塔尔”是一项简单的信使任务，旨在将莫高雷的制皮师与贫瘠之地的商人们联系起来。制皮师安哈努委托将一包裹成品兽皮运出雷霆崖。将包裹直接送到位于台地上的飞行管理员塔尔手中，可以引导初出茅庐的部落旅行者了解风骑士运输网络。",h="“风骑士训练师塔尔”是一项简单的信使任务，旨在将莫高雷的制皮师与贫瘠之地的商人们联系起来。制皮师安哈努委托将一包裹成品兽皮运出雷霆崖。将包裹直接送到位于台地上的飞行管理员塔尔手中，可以引导初出茅庐的部落旅行者了解风骑士运...",kw={"安哈努","十字路口","迪弗拉克","飞行管理员","加翰","皮革制品","塔尔","雷霆崖","风骑士"},ang={["faction:Horde"]="在贫瘠之地和雷霆崖之间建立稳定的飞行航线，可以确保增援部队、贸易商品和信息能够迅速在卡利姆多中部流动。",["race:Tauren"]="栖息在雷霆崖峭壁上的风骑士，代表着让凯恩·血蹄那与世隔绝的族人融入更广泛的部落联盟的重要纽带。"},sec={{t="十字路口的补给",b="莫高雷与贫瘠之地干旱灌木丛之间的贸易对于年轻的部落至关重要。安哈努是一位在雷霆崖下层高地兜售货物的制皮师，他生产的耐用皮革制品是提供给十字路口加翰·鹰翼的贸易摊位的。由于步行走下峭壁并穿越金色平原需要数小时，商人们依赖有翼的信使，通过崎岖的分界线运送易碎或紧急的包裹。"},{t="台地栖木的主人",b="塔尔栖身于雷霆崖最高的中央平台，照料着城里的风骑士群——也就是双足飞龙。这些聪慧、长着皮质翅膀的野兽非常适合在卡利姆多不可预测的热气流和崎岖的山峰间穿行。塔尔负责协调飞往十字路口等哨所的航班，确保信使和货物能迅速往来于牛头人主城与他们的兽人盟友之间。"}},faq={{q="塔尔是谁？",a="塔尔是雷霆崖的飞行管理员，负责监管位于中央台地的风骑士栖木。他管理着往返于贫瘠之地及更远地区的旅行者和信使的空中运输。",al={"塔尔是谁","雷霆崖的塔尔","风骑士训练师塔尔"}},{q="安哈努是谁？",a="安哈努是一位居住在雷霆崖的牛头人制皮匠。他制作大宗皮革制品，并将它们打包运往卡利姆多各处的哨所供应商，包括十字路口的加翰·鹰翼。",al={"安哈努","安哈努是谁","雷霆崖的安哈努"}},{q="为什么货物需要运往十字路口？",a="十字路口是贫瘠之地重要的贸易和军事交汇处。在莫高雷平静的庇护下生产的货物，如兽皮和皮革服装，会被运往那里以供应旅行者、猎人和部落巡逻队。",al={"为什么是十字路口","十字路口的皮革制品","加翰的皮革"}},{q="我能带着这个包裹直接飞往十字路口吗？",a="你只有在已经访问过该定居点并与当地的风骑士训练师迪弗拉克建立联系后，才能飞往十字路口。如果你还没有解锁该航线，你必须步行前往。",al={"我能飞往十字路口吗","塔尔的飞行路线","如何飞往十字路口"}},{q="什么是风骑士？",a="风骑士，通常被称为双足飞龙，是卡利姆多岩石地带原生的感知型、有毒的带翼掠食者。自第三次战争以来，它们与部落结盟，成为该阵营主要的空中坐骑。",al={"双足飞龙","什么是风骑士","牛头人坐骑"}},{q="这个信使差事接下来要去哪？",a="一旦你将货物交给塔尔，他会指示你找一只坐骑，将安哈努的包裹运过平原，送到在十字路口等待的加翰·鹰翼手中。",al={"下一个任务","塔尔之后做什么","皮革制品去向"}}},fp="25,184,27.301.0,26.302.0,11.155.0,13.153.0,46.173.0,54.155.0,21.193.0,41.131.0"}
P.entries["quest:6364"] = {n="向加翰回复",s="“回到加翰身边”是部落在莫高雷与贫瘠之地之间双足飞龙航线介绍任务的最终环节。在前往雷霆崖将皮革交给剥皮训练师安哈努之后，旅行者会带着加工好的皮制品乘坐双足飞龙返回十字路口，交付给商人加翰·鹰翼。",h="“回到加翰身边”是部落在莫高雷与贫瘠之地之间双足飞龙航线介绍任务的最终环节。在前往雷霆崖将皮革交给剥皮训练师安哈努之后，旅行者会带着加工好的皮制品乘坐双足飞龙返回十字路口，交付给商人加翰·鹰翼。",kw={"安哈努","贫瘠之地","十字路口","迪弗拉克","加翰·鹰翼","塔尔","雷霆崖","双足飞龙"},ang={["faction:Horde"]="莫高雷、杜隆塔尔和贫瘠之地之间的双足飞龙航线是连接部落卡利姆多中部领地的生命动脉。",["race:Tauren"]="莫高雷制皮工匠与贫瘠之地哨所之间的贸易链展示了团结的部族如何支持部落的边境扩张。"},sec={{t="卡利姆多的双翼",b="对于许多旅行者来说，这趟差事是他们第一次体验骑乘训练有素的双足飞龙。塔尔是雷霆崖的风骑士训练师，他驻守在雷霆崖中央台地的高处，负责安排往返于卡利姆多中部的飞行航线。只要旅行者已经在其他定居点——比如位于十字路口的迪弗拉克——的栖息地建立了联系，这些长着翅膀的野兽就能轻而易举地跨越那些原本需要跋山涉水、穿越赤色石和北部贫瘠之地的险峻路途。"},{t="十字路口的贸易",b="这趟快递任务除了让玩家熟悉飞行航线，还具有经济意义。加翰·鹰翼在繁华的十字路口定居点经营生意，每天都有猎人、侦察兵和雇佣兵聚集于此。从雷霆崖高处寄给安哈努的生皮会被加工成耐用的护甲和装备，随后通过飞行航线送回尘土飞扬的贫瘠之地十字路口，以供应部落不断扩张的边境需求。"}},faq={{q="加翰·鹰翼是谁？",a="加翰·鹰翼是一位驻扎在贫瘠之地十字路口的牛头人商人。他负责买卖皮制品，依赖雷霆崖的工匠将兽皮加工成装备，供外出冒险的勇士们使用。",al={"加翰","加翰·鹰翼背景","加翰是谁"}},{q="为什么我需要乘双足飞龙回到十字路口？",a="这趟旅程是为了演示飞行网络是如何运作的。像雷霆崖的塔尔这样的风骑士训练师只能将快递员和乘客派往他们亲自侦察过或建立过联系的定居点，例如十字路口的迪弗拉克的栖息地。",al={"为什么要飞回去","双足飞龙返程","飞行点如何运作"}},{q="安哈努是谁？",a="安哈努是一位技艺精湛的制皮师和剥皮训练师，位于雷霆崖的高地之上。他负责接收从贫瘠之地的猎人那里运来的兽皮，将其加工成成品，然后再送回各处进行销售。",al={"安哈努","安哈努雷霆崖","谁制作了商品"}},{q="迪弗拉克是谁？",a="迪弗拉克是驻扎在十字路口的兽人风骑士训练师。他负责管理连接贫瘠之地与奥格瑞玛和雷霆崖等部落主要据点的飞行栖息地。",al={"迪弗拉克","十字路口飞行点","风骑士训练师迪弗拉克"}},{q="我能在不先与目的地训练师交谈的情况下使用双足飞龙吗？",a="不能。双足飞龙只能被派往旅行者已经拜访过当地风骑士训练师并完成注册的哨所，以此建立栖息地之间的航线连接。",al={"飞行航线规则","解锁飞行点","我可以飞往任何地方吗"}},{q="把皮革制品交给加翰后会发生什么？",a="交付完加工好的商品，就完成了莫高雷和贫瘠之地之间的快递链，此时旅行者已经熟悉了空中交通，可以自由地继续协助十字路口的守军和商人们。",al={"后续任务","接下来做什么","完成回到加翰身边之后"}}},fp="15,235,19.426.0,26.330.0,22.167.0,58.223.0,13.174.0,14.161.0,74.111.0,56.192.0"}
P.entries["quest:6365"] = {n="送往奥格瑞玛的肉",s="“运往奥格瑞玛的肉”是由扎尔夫在十字路口提供的一个简短的介绍性后勤任务。他请求年轻的兽人和巨魔冒险者将一包上好的贫瘠之地肉块交给定居点的风骑士训练师迪弗拉克，从而向他们介绍返回部落首都的飞行交通方式。",h="“运往奥格瑞玛的肉”是由扎尔夫在十字路口提供的一个简短的介绍性后勤任务。他请求年轻的兽人和巨魔冒险者将一包上好的贫瘠之地肉块交给定居点的风骑士训练师迪弗拉克，从而向他们介绍返回部落首都的飞行交通方式。",kw={"贫瘠之地","十字路口","迪弗拉克","飞行管理员","格里什卡","肉类配送","奥格瑞玛","风骑士","扎尔夫"},ang={["profession:Cooking"]="将贫瘠之地平原的新鲜肉块补给到格里什卡的奥格瑞玛旅店，可以保证首都里为来访勇士准备的浓汤锅总是满满当当的。",["race:Orc"]="对于离开杜隆塔尔前往贫瘠之地狩猎的年轻兽人来说，运送扎尔夫的包裹提供了一种快速建立回到大酋长首都的空中航线的方法。",["race:Troll"]="在十字路口活动的暗矛巨魔利用这个跑腿任务，将不断扩张的荒野前哨站与奥格瑞玛的后勤补给线连接起来。"},sec={{t="来自贫瘠之地的新鲜野味",b="贫瘠之地广袤的平原上栖息着丰富的野生动物，从斑马和平原陆行鸟到科多兽和雷霆蜥蜴，应有尽有。扎尔夫准备了几块精选肉块，打算亲自送给奥格瑞玛力量谷里忙碌的旅店老板格里什卡。为了保持肉的新鲜并避免长途跋涉，跨越怒水河进入杜隆塔尔，扎尔夫让跑腿的人穿过十字路口，直接去寻找风骑士。"},{t="草原之上的双翼",b="找到迪弗拉克，标志着年轻的部落勇士第一次正式接触风骑士飞行网络。通过与风骑士训练师合作，部落将像十字路口这样的偏远前哨站直接与奥格瑞玛这座坚固的权力中心连接起来。迪弗拉克正在为这次横跨大草原的快速空中飞行准备快递员和货物。"}},faq={{q="扎尔夫要把这些肉送给谁？",a="扎尔夫把这些肉块送给他的朋友格里什卡，她是一位广受欢迎的旅店老板，经营着奥格瑞玛力量谷的主要旅店。",al={"谁收到了肉","肉是给谁的","扎尔夫的肉接收者"}},{q="为什么只有兽人和巨魔能接这个任务？",a="这个任务作为文化飞行介绍，旨在将兽人和暗矛巨魔重新连接到他们共同的首都奥格瑞玛。牛头人通过任务“一捆兽皮”被指引前往雷霆崖，而亡灵角色则通过“补给瑟伯切尔”被指引前往银松森林。",al={"为什么牛头人接不到这个任务","亡灵肉类任务","种族限制"}},{q="迪弗拉克是谁？",a="迪弗拉克是驻扎在贫瘠之地十字路口的兽人风骑士训练师。他负责管理双足飞龙，这些飞龙负责在整个卡利姆多运送消息、补给和旅客。",al={"迪弗拉克十字路口","迪弗拉克是谁"}},{q="把肉交给迪弗拉克之后会发生什么？",a="迪弗拉克会收下这批货物，并为你安排一次风骑士飞行，让你将肉送到奥格瑞玛的天空塔，并通过后续任务“前往奥格瑞玛”将其交给旅店里的格里什卡。",al={"运往奥格瑞玛的肉的后续任务","迪弗拉克是做什么的"}},{q="扎尔夫在哪里？",a="扎尔夫驻扎在十字路口，这是位于贫瘠之地主要路口的部落中央贸易枢纽。",al={"扎尔夫的位置","扎尔夫在哪里"}},{q="为什么要用风骑士而不是步行？",a="风骑士可以提供横跨贫瘠之地严酷荒野和河流峡谷进入杜隆塔尔的快速交通，确保像新鲜肉类这样娇贵的货物在变质前就能运抵奥格瑞玛。",al={"为什么要飞往奥格瑞玛","风骑士肉类"}}},fp="18,191,27.318.0,22.258.0,34.97.0,45.227.0,14.155.0,45.175.0,23.92.0,40.149.0"}
P.entries["quest:637"] = {n="苏利·巴鲁的信",s="这封浸水的信是从萨多尔大桥破碎的拱门下的一具溺亡骷髅身上找回的，其中包含了名为苏利·巴鲁的矮人士兵的临终遗言。这封信写给他在铁炉堡的妻子萨拉，承载了一名在桥梁保卫战中失踪于冰冷河水下的守卫者最后的思绪。",h="这封浸水的信是从萨多尔大桥破碎的拱门下的一具溺亡骷髅身上找回的，其中包含了名为苏利·巴鲁的矮人士兵的临终遗言。这封信写给他在铁炉堡的妻子萨拉，承载了一名在桥梁保卫战中失踪于冰冷河水下的守卫者最后的思绪。",kw={"阿拉希","矮人士兵","铁炉堡","萨拉·巴鲁","骷髅","苏利·巴鲁","萨多尔大桥","浸水的信封","湿地"},ang={["faction:Alliance"]="这封信深刻地提醒着人们，普通的在一线保卫着南部与北部联盟领地之间脆弱陆路连接的士兵们所付出的个人牺牲。",["race:Dwarf"]="对于铁炉堡的矮人来说，带回苏利的遗言是对一位战友的敬意，他为了守卫宏伟的矮人石匠杰作抵御北方威胁而献出了生命。"},sec={{t="河床之音",b="在支撑萨多尔大桥——连接湿地与阿拉希高地的关键陆路桥梁——的巨大石桩下，静卧着一具阵亡矮人的溺亡骷髅。他那枯骨般的手中紧紧抓着一个几乎无法触碰的水浸信封。信件是在战火中费尽心思写下的，开篇即是那句温柔的“亲爱的萨拉……”，在潮水将他带走许久之后，依然保留着这位士兵的声音。"},{t="大桥的代价",b="萨多尔大桥见证了联盟军队与其敌人之间激烈的战斗，从黑铁矮人破坏者到争夺边境地区的劫掠战队，不一而足。苏利·巴鲁是被派往北方保卫这一交通要道的众多矮人士兵之一。当他葬身波涛之下时，他的家人们对此一无所知，直到一位潜水员最终找回了他的遗嘱。"},{t="铁炉堡的遗孀",b="将找回的信件带回铁炉堡，给苏利的遗孀萨拉·巴鲁带来了沉痛的打击。生活在繁华的矮人首都，她一直徘徊在悲伤与一线希望之间，不知道丈夫是失踪了还是永远离开了。面对他亲笔写下的文字，得知他最终长眠于水下，她终于不得不面对他已死亡的残酷现实。"}},faq={{q="苏利·巴鲁的信在哪里可以找到？",a="这封信握在一具淹没在萨多尔大桥（连接湿地与阿拉希高地）巨石桥墩正下方的深处河床上的骷髅手中。",al={"信件位置","苏利·巴鲁在哪里","萨多尔大桥骷髅"}},{q="苏利·巴鲁是谁？",a="苏利·巴鲁是一名在保卫萨多尔大桥时阵亡的联盟矮人士兵。在开始守卫大桥之前，他写了一封告别信给他的妻子萨拉，这封信在他遗骸的冰冷水下被发现时，仍被紧紧攥在手中。",al={"苏利是谁","苏利·巴鲁背景故事","苏利·巴鲁生平"}},{q="萨拉·巴鲁是谁？",a="萨拉·巴鲁是苏利的遗孀，居住在伟大的矮人首都铁炉堡。她已经在期盼中度过了数月，等待着她在北方前线的丈夫的消息。",al={"萨拉·巴鲁在哪里","萨拉是谁","萨拉·巴鲁位置"}},{q="送交这封信后会发生什么？",a="在收到苏利死亡的心碎确认后，萨拉·巴鲁悲痛欲绝，并请求为他立碑纪念，故事也会通过铁炉堡后续的任务请求继续展开。",al={"后续任务","苏利任务线","送信之后"}},{q="为什么信在水下还能保持完整？",a="这封信被保护在士兵遗骸紧紧攥着的信封里。虽然在被找回时已经部分溶解且浸透了水，但几页写着工整字迹的信纸仍然清晰可辨。",al={"为什么信件可读","信封如何保存下来"}},{q="这个任务背后的现实世界灵感是什么？",a="这个任务是为了向美国内战期间罗德岛第2步兵团的萨利文·巴卢少校致敬，他在第一次奔牛河之战阵亡前不久，曾写下一封感人至深的告别信给他的妻子。",al={"苏利·巴鲁趣闻","萨利文·巴卢","内战致敬"}}},fp="21,147,25.270.0,21.357.0,20.258.1,37.154.0,21.223.0,19.136.0,42.132.1,43.207.0,49.216.0"}
P.entries["quest:638"] = {n="巨魔之敌",s="沃金已下令暗矛巨魔从人类废墟王国激流堡中找回远古之剑托卡拉尔。随着托尔贝恩国王的陨落，这柄利刃将服务于部落，以应对未来与祖尔格拉布巨魔的冲突。",h="沃金已下令暗矛巨魔从人类废墟王国激流堡中找回远古之剑托卡拉尔。随着托尔贝恩国王的陨落，这柄利刃将服务于部落，以应对未来与祖尔格拉布巨魔的冲突。",kw={"落锤镇","尼姆布亚","激流堡","托卡拉尔","托尔贝恩","沃金","森古","祖尔格拉布"},ang={["faction:Horde"]="部落的猎人森古正在落锤镇等待，希望能看到这柄传奇之剑从人类手中夺回。",["race:Troll"]="沃金专门寻求托卡拉尔，是为了武装暗矛部族以对抗他们祖尔格拉布的远古族人。"},sec={{t="国王陨落，利刃渴求",b="在托尔贝恩国王去世、激流堡沦为废墟之后，沃金酋长已下令尽一切努力夺回托卡拉尔。这柄传奇之剑长期以来一直掌握在人类手中，但暗矛部族希望能将其夺回，以应对即将在祖尔格拉布展开的与丛林巨魔的战争。"},{t="前往落锤镇",b="为了执行沃金的指令，一位经验丰富的猎人名叫森古被派往阿拉希高地东北部的部落哨站落锤镇。尼姆布亚指引从荆棘谷前来的旅行者去寻找森古，并协助夺回这件传奇武器。"}},faq={{q="为什么沃金想要托卡拉尔之剑？",a="沃金打算在即将到来与祖尔格拉布敌对丛林巨魔的战斗中使用托卡拉尔。",al={"为何需要托卡拉尔","为何需要托尔贝恩之剑","托卡拉尔的用途"}},{q="森古是谁？",a="森古是一位经验丰富的猎人，由暗矛巨魔派遣至阿拉希高地的落锤镇，负责监督托卡拉尔的回收工作。",al={"谁是森古","森古的任务","猎人森古"}},{q="这段旅程将指引你去向何处？",a="旅程将引领你离开荆棘谷向北前往阿拉希高地东北部的哨站——落锤镇。",al={"去往何处","任务目的地","森古在哪里"}},{q="激流堡发生了什么？",a="在统治者托尔贝恩国王去世后，激流堡已成为一片废墟。",al={"激流堡现状","托尔贝恩国王发生了什么"}}},fp="9,190,30.261.0,21.192.0,43.90.0,13.118.0,33.104.0,28.70.0"}
P.entries["quest:6381"] = {n="新的生命",s="“新生命”是一个部落的恢复性任务，由烈日石居的塔姆拉·荒原提供。在收集了附有魔法的盖亚之种后，玩家将向西前往焦炭谷的灰烬废墟，将种子播撒在肥沃的土地上。这一仪式旨在让这片土地在充满敌意的元素生物和鹰身人中恢复生机。",h="“新生命”是一个部落的恢复性任务，由烈日石居的塔姆拉·荒原提供。在收集了附有魔法的盖亚之种后，玩家将向西前往焦炭谷的灰烬废墟，将种子播撒在肥沃的土地上。这一仪式旨在让这片土地在充满敌意的元素生物和鹰身人中恢复生机。",kw={"血怒鹰身人","焦炭谷","重生之环","土堆","火元素","盖亚之种","石爪山脉","烈日石居","塔姆拉·荒原"},ang={["class:Druid"]="德鲁伊与塔姆拉的使命有着密切的联系，他们将焦炭谷的更新视为对自然脆弱平衡的一次重要恢复。",["class:Shaman"]="萨满明白，除非这片饱受摧残的土地开始自我治愈，否则游荡在山谷中的焦躁火元素将永远无法获得平静。",["profession:Herbalism"]="草药师们能够领会这种坚韧种子所蕴含的深奥力量，它们能让在完全死寂的土壤中焕发出繁茂的植被。",["race:Tauren"]="对于牛头人来说，在满目疮痍的土地上播撒附有魔法的种子，是一种与大地母亲进行精神交流的行为，履行了他们治愈受伤土地的神圣职责。"},sec={{t="治愈焦土",b="焦炭谷是近期破坏惨状的悲剧见证，这里充斥着煤烟、狂暴的火元素和四处觅食的鹰身人。塔姆拉·荒原拒绝让该地区彻底荒废。依靠大地母亲古老的复原力，她派遣旅行者前往那片焦黑山谷的中心，寻找盖亚之土堆——那些在大火中幸存下来的肥沃表土。"},{t="未来的立足点",b="种在焦土中的附有魔法的盖亚之种旨在抵御挥之不去的元素腐蚀。通过生根发芽，它们开始编织一种至关重要的生态锚点，能够抵御衰败并引回谷中的植被。塔姆拉预想了一个长期的治愈过程：随着活着的根系慢慢收复这片盆地，焦躁的火灵将会平息，鹰身人将失去它们荒凉的栖息地，而荆棘谷地精贪婪的伐木作业最终也将被赶出去。"}},faq={{q="种植盖亚之种的目的是什么？",a="附有魔法的盖亚之种旨在焦炭谷伤痕累累的土地上生根发芽。它们可以抵御腐蚀，并建立起最初的生机勃勃的植被立足点，为森林逐渐恢复和治愈奠定基础。",al={"为什么要种植种子","“新生命”任务目的","盖亚之种的作用"}},{q="我需要去哪里种植种子？",a="你必须从烈日石居向西前往焦炭谷。种子需要种植在散布于焦黑盆地各处的小型盖亚之土堆中。",al={"焦炭谷在哪里","在哪里种植盖亚之种","种子位置"}},{q="塔姆拉·荒原是谁？",a="塔姆拉·荒原是一位居住在石爪山脉烈日石居的牛头人博物学家。她致力于安抚这片土地上受伤的灵魂，并修复被元素之怒和工业贪婪所蹂躏的区域。",al={"谁提供“新生命”任务","塔姆拉任务发布者","塔姆拉·荒原背景故事"}},{q="在种植时，有哪些威胁在焦炭谷游荡？",a="焦炭谷居住着因近期破坏而被惊动的流浪火元素，以及在烧焦的树木间筑巢的、极具攻击性的血怒鹰身人。",al={"焦炭谷的敌人","焦炭谷的攻击者","焦炭谷的危险"}},{q="在“新生命”之前的任务是什么？",a="“新生命”直接承接任务“重生之环”，在该任务中，你将帮助塔姆拉收集制备附有魔法的盖亚之种所需的关键材料。",al={"“新生命”前置任务","“重生之环”任务","如何开启“新生命”"}},{q="塔姆拉希望石爪山脉在长期内发生什么变化？",a="塔姆拉希望重新生长出来的土地最终能平息愤怒的火元素，排挤走掠食性的鹰身人，并熬过荆棘谷地精的伐木作业，让群山恢复成郁郁葱葱、宁静祥和的森林。",al={"石爪山脉的未来","塔姆拉的目标","焦炭谷的未来"}}},fp="8,151,26.225.0,25.321.0,47.178.0,41.105.0,24.212.0,50.144.0,33.122.0,58.209.0"}
P.entries["quest:6382"] = {n="灰谷狩猎",s="“灰谷狩猎”是一项指引部落中久经考验的冒险者离开干旱的贫瘠之地，北上进入灰谷茂密森林的任务。在陶拉祖营地的塞娜尼·雷心（原文为乔恩·星眼，此处遵照名录更正为塞娜尼·雷心，注：原文此处似乎有误，应为乔恩·星眼委托前往碎木岗哨协助塞娜尼·雷心，已按语境调整）委托下，旅行者们会被派往碎木岗哨协助塞娜尼·雷心，并在这一片充满野性与争端的土地上磨炼追踪技巧。",h="“灰谷狩猎”是一项指引部落中久经考验的冒险者离开干旱的贫瘠之地，北上进入灰谷茂密森林的任务。在陶拉祖营地的塞娜尼·雷心（原文为乔恩·星眼，此处遵照名录更正为塞娜尼·雷心，注：原文此处似乎有误，应为乔恩·星眼委托前往碎木岗...",kw={"灰谷","灰谷狩猎","贫瘠之地","陶拉祖营地","乔恩·天视","塞娜尼·雷心","碎木岗哨"},ang={["class:Hunter"]="从卡利姆多的平原进入灰谷，意味着地形的巨大转变，在浓密的林冠之下，有无数充满异国情调的野兽等待着你去追踪、研究和驯服。",["faction:Horde"]="灰谷是一个至关重要的战略前沿；在这里建立立足点，可以为杜隆塔尔和贫瘠之地的各个定居点提供维持运作所需的木材和食物补给。",["race:Tauren"]="乔恩·天视和塞娜尼·雷心共同指引着这段旅程，他们并不将狩猎仅仅视为屠戮，而是将其视为一种精神上的平衡，一种向荒野致敬的方式。"},sec={{t="深入古木天顶",b="在贫瘠之地那阳光灼烧的平原上证明了自己的狩猎实力后，部落的猎人和勇士们会被指引前往一个完全不同的试炼场。当旅行者们已不再满足于狩猎本地的野兽时，乔恩·天视就会为他们指明方向，让他们北上前往灰谷。对于年轻的部落成员来说，这些古老的林地既意味着丰富的资源，也是他们必须学习去理解和征服的一片深奥的政治与精神前沿。"},{t="碎木岗哨",b="沿着蜿蜒的道路向北，经过莫尔杉壁垒，旅行者们便会抵达碎木岗哨。这是一个深藏在林线之内的设防部落营地。在那里，牛头人女猎手塞娜尼·雷心欢迎着那些寻求更高生存挑战的资深勇士。为了在灰谷生存，部落依赖于那些能够追踪敌对掠食者，以及避开森林守护者警惕目光的熟练追踪者。"}},faq={{q="谁派我去执行“灰谷狩猎”？",a="乔恩·天视是一位驻扎在南贫瘠之地陶拉祖营地的牛头人猎人，当你证明了自己在本地狩猎野兽的技巧后，他便会提供这项任务。",al={"谁给予灰谷狩猎任务","灰谷狩猎任务发放者","乔恩·天视任务"}},{q="碎木岗哨在哪里？",a="碎木岗哨位于灰谷的中东部。如果你沿着主路从贫瘠之地向北走，经过莫尔杉壁垒并继续深入丛林，这个设防的前哨站就坐落在道路的北侧。",al={"碎木岗哨位置","塞娜尼·雷心在哪里","寻找碎木岗哨"}},{q="塞娜尼·雷心是谁？",a="塞娜尼·雷心是一位驻扎在碎木岗哨的牛头人女猎手。她负责协调整个灰谷的狩猎工作，教导新来的部落冒险者如何去追踪古老森林中最凶猛的掠食者和灵魂。",al={"塞娜尼·雷心","塞娜尼是谁","女猎手塞娜尼"}},{q="灰谷附近还有其他部落前哨站吗？",a="除了碎木岗哨，部落在东部还设有战歌伐木营地，并在最西端的佐拉姆海岸设有佐拉姆加前哨站。",al={"部落在灰谷的基地","灰谷的其他营地"}},{q="为什么部落对在灰谷狩猎感兴趣？",a="这片未经驯化的荒野提供了杜隆塔尔和贫瘠之地所缺乏的关键肉类、毛皮和资源。面对森林中危险的野兽，对于部落的勇士和猎人来说，也被视为是对意志和精神力量的重要考验。",al={"为什么要在灰谷狩猎","部落在灰谷的动机"}},{q="这段旅程之后还有什么挑战？",a="塞娜尼·雷心会招募老练的猎人去追踪林地中显眼的威胁，派他们深入林冠去狩猎顶级的掠食者，例如巨熊乌萨诺斯、猫科动物沙德拉以及角鹰兽尖爪。",al={"灰谷狩猎后的下一个任务","塞娜尼给予什么"}}},fp="18,182,23.279.0,17.332.0,35.135.0,35.180.0,27.191.0,50.124.0,52.192.0,36.177.0"}
P.entries["quest:6383"] = {n="灰谷狩猎",s="灰谷狩猎是由塞娜尼·雷心在碎木岗哨主持的一项传统仪式。部落猎人们接受挑战，去追踪并战胜徘徊在这片古老森林中的三头传奇掠食者：巨熊乌萨戈斯、夜刃豹莎德拉，以及凶猛的角鹰兽锐爪。这不仅仅是对武艺的考验，更是一段学习狡诈、尊重与自我认知的旅程。",h="灰谷狩猎是由塞娜尼·雷心在碎木岗哨主持的一项传统仪式。部落猎人们接受挑战，去追踪并战胜徘徊在这片古老森林中的三头传奇掠食者：巨熊乌萨戈斯、夜刃豹莎德拉，以及凶猛的角鹰兽锐爪。这不仅仅是对武艺的考验，更是一段学习狡诈、尊重...",kw={"灰谷狩猎","林中树居","塞娜尼·雷心","莎德拉","锐爪","碎木岗哨","石爪小径","乌萨戈斯"},ang={["class:Hunter"]="这场狩猎是一项经典的成年仪式，迫使追踪者在广袤的森林中搜寻、解读地形，并与足以轻易击败粗心侦察兵的野兽进行战斗。",["faction:Horde"]="与战歌氏族对森林的破坏性砍伐形成对比，这场狩猎为部落在纷争不断的灰谷中提供了一条兼具武艺荣誉与精神融合的道路。",["race:Tauren"]="对于牛头人猎人而言，追踪乌萨戈斯、莎德拉和锐爪体现了对大地母亲造物的传统敬畏，在对自然凶猛本能的尊重与追踪之道的荣誉之间达成了平衡。"},sec={{t="古老森林中的牛头人传统",b="随着部落在灰谷深处建立立足点，大地母亲的精神教诲通过塞娜尼·雷心得到了体现。与兽人们激进的伐木活动不同，塞娜尼的狩猎将阴影笼罩的林地视为神圣的试炼场。通过与森林中顶尖掠食者的博弈，猎人们有望与这片原始荒野进行心灵交流，并培养在灰谷生存所必需的沉静谦逊。"},{t="三大巨兽",b="狩猎的核心是三头游荡在林间的孤独传奇生物。在石爪小径附近徘徊着乌萨戈斯，这是一头体型巨大的长者巨熊，它的力量考验着猎人的肉体韧性。再向东，在那靠近林中树居以及难以捉摸的欢笑姐妹的边界地带，潜伏着莎德拉，这是一头因其狡诈而备受敬畏的潜行夜刃豹。最后，在碎木岗哨以南盘旋着锐爪，这是一头凶猛的角鹰兽，它对森林树冠的掌控为这场试炼画上了句点。"}},faq={{q="谁发起了灰谷狩猎？",a="这项狩猎由驻扎在灰谷的牛头人猎人塞娜尼·雷心主持。她向那些寻求在荒野中证明自己生存技能的部落旅行者们发出挑战。",al={"灰谷狩猎任务发布者","谁发起狩猎","塞娜尼·雷心任务"}},{q="我需要追踪哪些野兽？",a="你必须追踪并击杀三头传奇掠食者：巨熊乌萨戈斯、夜刃豹莎德拉，以及凶猛的角鹰兽锐爪。",al={"需要杀死的动物","三大野兽","灰谷狩猎目标"}},{q="乌萨戈斯在哪里可以找到？",a="乌萨戈斯在石爪小径以西不远处的一小片领地内游荡，它会在林地其他野生熊群中来回踱步。",al={"乌萨戈斯位置","熊在哪里","找到乌萨戈斯"}},{q="莎德拉在哪里徘徊？",a="莎德拉在林中树居以南的地区徘徊，它常在被称为欢笑姐妹的树妖们所居住的道路附近进行狩猎。",al={"莎德拉位置","莎德拉在哪里","夜刃豹位置"}},{q="锐爪可以在哪里被追踪到？",a="锐爪在碎木岗哨以南的一大片广阔区域内巡逻，它在树木和空地之间盘旋。",al={"锐爪位置","锐爪在哪里","角鹰兽位置"}},{q="为什么塞娜尼·雷心要派猎人去猎杀这些野兽？",a="塞娜尼将这场狩猎视为一种荣誉试炼，而非肆意的屠杀。通过让猎人们与森林中最致命的自然居民进行较量，他们可以更深刻地了解荒野，并深入洞察自身的内在力量。",al={"为什么要进行狩猎","狩猎目的","狩猎背景故事"}}},fp="18,171,39.309.0,22.321.0,30.164.0,36.88.0,29.78.0,28.110.0,32.81.0,61.180.0"}
P.entries["quest:6384"] = {n="飞往奥格瑞玛",s="这项差事向部落冒险者介绍了卡利姆多的空中旅行方式，玩家需要委托一名双足飞龙管理员从十字路口飞往奥格瑞玛。冒险者将带着扎尔夫的新鲜肉排，降落在奥格瑞玛的天空塔，并将包裹直接交给旅店老板格雷什卡。",h="这项差事向部落冒险者介绍了卡利姆多的空中旅行方式，玩家需要委托一名双足飞龙管理员从十字路口飞往奥格瑞玛。冒险者将带着扎尔夫的新鲜肉排，降落在奥格瑞玛的天空塔，并将包裹直接交给旅店老板格雷什卡。",kw={"贫瘠之地","十字路口","迪弗拉克","多拉斯","格雷什卡","奥格瑞玛","天空塔","双足飞龙","扎尔夫"},ang={["faction:Horde"]="十字路口和奥格瑞玛之间的双足飞龙航线是连接贫瘠之地中部与大酋长萨尔权力中心的重要命脉。",["profession:Cooking"]="格雷什卡在收到扎尔夫的礼物后，明确表达了她的烹饪偏好：卡利姆多最上等的野兽肉应该做成半熟，以保持其鲜味。"},sec={{t="草原之翼",b="在十字路口和杜隆塔尔红色的悬崖之间，徒步穿越干旱的荒原十分艰苦，但部落拥有一套可靠的双足飞龙网络来缩短距离。十字路口飞行管理员迪弗拉克负责监管这些双足飞龙，将信使和旅行者送往尘土飞扬的峡谷小径上方，直接将重要的公文和贸易货物送到首都。"},{t="给格雷什卡的特别快递",b="这次飞行不仅仅是一次观光之旅；它还带着一份私人心意。十字路口的扎尔夫准备了一份上好的生肉排，目的地是奥格瑞玛力量谷的旅店老板格雷什卡。当双足飞龙降落在奥格瑞玛中央的天空塔时，格雷什卡的旅店就在不远处，她会欣然接受这份礼物——并满怀爱意地表示，扎尔夫确实很懂得如何俘获女士的芳心。"}},faq={{q="这次飞行的目的是什么？",a="这趟旅程是部落双足飞龙旅行网络的实践介绍。你支付给迪弗拉克费用，从十字路口乘骑飞往奥格瑞玛，将扎尔夫的新鲜肉排送给旅店老板格雷什卡。",al={"为什么要飞往奥格瑞玛","飞往奥格瑞玛的目的","为什么要送肉到奥格瑞玛"}},{q="双足飞龙在奥格瑞玛的哪里降落？",a="双足飞龙降落在奥格瑞玛的天空塔，它高耸在力量谷之上。从塔台出发，你可以走下坡道到达主广场、附近的商贩以及格雷什卡的旅店。",al={"在奥格瑞玛哪里降落","天空塔位置","奥格瑞玛飞行降落点"}},{q="格雷什卡是谁？",a="旅店老板格雷什卡管理着奥格瑞玛力量谷中繁忙的旅店。她欢迎疲惫的旅行者来到首都，并与扎尔夫保持着良好的友谊，扎尔夫经常为她的厨房提供上好的生肉。",al={"旅店老板格雷什卡","格雷什卡是谁","格雷什卡的位置"}},{q="迪弗拉克是谁？",a="迪弗拉克是驻扎在贫瘠之地十字路口的双足飞龙管理员。他照看双足飞龙并协调连接贫瘠之地前哨站与杜隆塔尔及其他部落定居点的空中交通。",al={"迪弗拉克与十字路口","迪弗拉克是谁","十字路口双足飞龙管理员"}},{q="扎尔夫为什么要给格雷什卡送生肉？",a="扎尔夫认为来自贫瘠之地的新鲜猎物是一份珍贵的礼物。格雷什卡非常欣赏这份礼物，并指出上好的稀有肉排是俘获她芳心的绝佳方式。",al={"扎尔夫的肉","为什么给格雷什卡送肉","扎尔夫和格雷什卡"}},{q="送完肉后我该做什么？",a="在旅店完成送货后，格雷什卡会指引旅行者回到天空塔，与奥格瑞玛的双足飞龙管理员多拉斯交谈，为返程做准备。",al={"飞往奥格瑞玛后做什么","格雷什卡之后的任务","送货后去哪里"}}},fp="17,135,22.317.0,28.245.0,35.182.0,44.150.0,15.173.0,14.172.0,41.124.0,43.145.0"}
P.entries["quest:6385"] = {n="双足飞龙管理员多拉斯",s="奥格瑞玛的旅店老板格雷什卡写了一封感谢信给十字路口的扎尔夫，并需要一名信使把它空运回贫瘠之地。为了安排行程，她指引旅行者前往城市的飞行塔，去咨询部落的首席风骑士训练师多拉斯。",h="奥格瑞玛的旅店老板格雷什卡写了一封感谢信给十字路口的扎尔夫，并需要一名信使把它空运回贫瘠之地。为了安排行程，她指引旅行者前往城市的飞行塔，去咨询部落的首席风骑士训练师多拉斯。",kw={"贫瘠之地","十字路口","多拉斯","飞行管理员","格雷什卡","奥格瑞玛","双足飞龙","扎尔夫"},ang={["faction:Horde"]="双足飞龙网络将奥格瑞玛与关键的地区驻军连接起来，充当了连接的纽带，使年轻的部落能够在卡利姆多的荒野中投射兵力和运送补给。",["race:Orc"]="兽人在抵达这片大陆后，便与卡利姆多本土的双足飞龙建立了深厚的羁绊，依靠它们的敏捷和力量作为飞行坐骑和驮兽信使。"},sec={{t="信使的回复",b="在收到从贫瘠之地的狩猎场空运来的一批新鲜肉类后，旅店老板格雷什卡起草了一封给屠夫扎尔夫的正式感谢信。由于没有时间亲自经由杜隆塔尔进行陆路跋涉，她依靠卡利姆多各主要部落定居点之间建立的空中信使网络，将她的信息迅速送回边境。"},{t="巢穴主管",b="多拉斯负责监管奥格瑞玛位于力量谷飞行塔顶部的风骑士巢穴。他训练的双足飞龙是部落军事通讯和后勤的生命线，它们在首都和十字路口这样的边远哨所之间架起了桥梁，所花费的时间仅为步行或乘坐科多兽大车所需时间的一小部分。"}},faq={{q="谁是多拉斯？",a="多拉斯是驻扎在奥格瑞玛的主要风骑士训练师。他管理着城市的双足飞龙训练马厩，并协调前往卡利姆多中部各地偏远部落枢纽的空中旅行。",al={"多拉斯","谁是多拉斯","奥格瑞玛飞行管理员"}},{q="为什么旅店老板格雷什卡要寄这封信？",a="格雷什卡正在给十字路口的屠夫扎尔夫寄一封感谢信，以确认送到她奥格瑞玛旅店的肉类补给已安全抵达。",al={"为什么要寄信","格雷什卡的信","信是用来做什么的"}},{q="在哪里可以找到多拉斯？",a="多拉斯驻扎在奥格瑞玛力量谷上方的中央飞行塔顶端，可以通过塔内的木制坡道到达。",al={"多拉斯在哪里","多拉斯的位置","寻找多拉斯"}},{q="把格雷什卡的信交给多拉斯后会发生什么？",a="一旦你咨询了多拉斯，他就会准备一只双足飞龙带你回到贫瘠之地，这样你就可以直接把格雷什卡的信亲手交给十字路口的扎尔夫。",al={"接下来做什么","多拉斯之后","下一个任务"}},{q="谁是扎尔夫？",a="扎尔夫是一位常驻贫瘠之地十字路口的兽人屠夫，也是格雷什卡的朋友，他曾送给她一些精选的贫瘠之地肉类作为礼物。",al={"扎尔夫","谁是扎尔夫"}},{q="为什么要骑乘双足飞龙而不是步行？",a="从奥格瑞玛穿过杜隆塔尔，越过怒水河进入贫瘠之地的陆路旅程缓慢且充满危险。驯服的双足飞龙为部落提供了一种在定居点之间派遣侦察兵、传达命令和运送信件的快速、可靠的方式。",al={"为什么要飞行","双足飞龙的作用","飞行点背景故事"}}},fp="27,206,17.269.0,23.265.0,13.120.0,45.126.0,25.124.0,52.149.0,13.132.0,39.234.0"}
P.entries["quest:6386"] = {n="返回十字路口",s="这个差事完成了杜隆塔尔与贫瘠之地之间的一次信使投递，将格雷什卡的回复带回给了十字路口的扎尔夫。它展示了双足飞龙管理员是如何作为部落在整个卡利姆多各定居点之间的重要空中骨干发挥作用的。",h="这个差事完成了杜隆塔尔与贫瘠之地之间的一次信使投递，将格雷什卡的回复带回给了十字路口的扎尔夫。它展示了双足飞龙管理员是如何作为部落在整个卡利姆多各定居点之间的重要空中骨干发挥作用的。",kw={"贫瘠之地","十字路口","迪弗拉克","多拉斯","格雷什卡","信","奥格瑞玛","双足飞龙","飞龙","扎尔夫"},ang={["faction:Horde"]="奥格瑞玛和十字路口的双足飞龙栖息地构成了连接部落首府与卡利姆多危险荒原的经济与后勤脊梁。",["race:Orc"]="丰盛的新鲜野味仍然是兽人猎人向未来的伴侣表达爱意和尊重的最好信物之一。"},sec={{t="翼上归途",b="将一份上等肉块送到奥格瑞玛的格雷什卡手中后，你受托将她的亲笔回信带给扎尔夫。多拉斯，这位栖息在奥格瑞玛高耸峭壁上的双足飞龙管理员，为你提供了一匹回贫瘠之地的坐骑。因为你已经与十字路口的迪弗拉克建立了联系，多拉斯的双足飞龙认识飞行路线，从而将一次艰苦的穿越怒水河的陆路跋涉，变成了一段飞越荒漠天空的迅捷旅程。"},{t="贫瘠之地的良缘",b="扎尔夫大胆的烹饪求爱攻势成功了。格雷什卡那热情的回复证实了没有什么比优质的补给更能打动一位兽人，这促使扎尔夫欣喜若狂，甚至开始憧憬即将到来的婚礼。除了浪漫的胜利，这次旅程还巩固了旅行者进入贫瘠之地中央交通枢纽的权限。"}},faq={{q="为什么我必须使用双足飞龙返回？",a="多拉斯利用这次投递来演示部落的飞行网络。既然你之前拜访过十字路口的迪弗拉克，双足飞龙就能在两个栖息地之间直接飞行，既节省了时间，又确保了补给线的安全。",al={"为什么飞回去","需要双足飞龙","我可以走路吗"}},{q="格雷什卡是谁？",a="格雷什卡是奥格瑞玛力量谷的旅店老板。扎尔夫送给她一些精选的贫瘠之地肉块，希望能赢得她的青睐。",al={"格雷什卡背景故事","格雷什卡是谁","奥格瑞玛的送肉女士"}},{q="扎尔夫送肉去奥格瑞玛的目的是什么？",a="扎尔夫想要追求格雷什卡。在兽人文化中，赠送来自贫瘠之地荒原的丰盛优质野味被认为是一种盛大的浪漫姿态。",al={"为什么扎尔夫要送肉","扎尔夫的动机","扎尔夫的信"}},{q="这个任务在哪里结束？",a="任务在贫瘠之地的十字路口完成，你将在那里把格雷什卡的信交还给岗哨和马厩附近的扎尔夫。",al={"在哪里交任务","返回地点","谁收到格雷什卡的信"}},{q="多拉斯是谁？",a="多拉斯是驻扎在奥格瑞玛力量谷上方飞行栖息地的双足飞龙管理员，负责管理往来于卡利姆多的空中坐骑。",al={"双足飞龙管理员多拉斯","多拉斯的位置","奥格瑞玛飞行管理员"}},{q="这个任务之后会发生什么？",a="这次投递标志着“送肉去奥格瑞玛”信使任务线的终结。在连接了奥格瑞玛和十字路口后，你已经完全准备好去探索贫瘠之地更深处的地方了。",al={"后续任务","返回后的下一个任务","送肉去奥格瑞玛的后续"}}},fp="25,120,15.392.0,27.217.0,44.173.0,15.125.0,51.122.0,26.118.0,13.146.0,30.138.0"}
P.entries["quest:6387"] = {n="荣誉学员",s="采矿训练师布洛克·寻石者会奖励塞尔萨玛那些表现优异的年轻学徒，授予他们荣誉锄。为了安排从铁炉堡运送这些工具，他指引冒险者去寻求当地狮鹫管理员索格拉姆·伯雷森的帮助。",h="采矿训练师布洛克·寻石者会奖励塞尔萨玛那些表现优异的年轻学徒，授予他们荣誉锄。为了安排从铁炉堡运送这些工具，他指引冒险者去寻求当地狮鹫管理员索格拉姆·伯雷森的帮助。",kw={"布洛克·寻石者","高尼尔·石趾","狮鹫","矿工的馈赠","铁炉堡","洛克莫丹","采矿","塞尔萨玛","索格拉姆·伯雷森"},ang={["faction:Alliance"]="这项请求向洛克莫丹的旅人们介绍了联盟至关重要的飞行管理员和空中快递网络。",["profession:Mining"]="这个任务凸显了矮人对采矿这一严谨工艺的尊重，精通矿石和矿脉的技艺可以获得大师级导师实实在在的认可。",["race:Dwarf"]="对于矮人冒险者来说，这个任务反映了像塞尔萨玛这样的边境定居点与首都深山大厅之间的紧密联系。"},sec={{t="矿工的馈赠",b="在矮人城镇塞尔萨玛，采矿不仅仅是一项职业，更是他们日常生活和矮人自豪感的基石。布洛克·寻石者看着一批又一批的新兵通过他的训练，向他们传授岩石构成和隧道安全的知识。对于那些表现出众的学生，传统要求以一把做工精良的荣誉锄作为奖励。由于当地物资有限，获得这些锄头需要跨越卡兹莫丹，直抵铁炉堡的心脏地带。"},{t="飞向蓝天",b="布洛克并不指望人们通过漫长而艰难的山路徒步走回丹莫罗，而是依靠王国的空中快递网络。索格拉姆·伯雷森负责照看塞尔萨玛旁的狮鹫点，提供前往首都的快速交通。将布洛克的订单交给索格拉姆，就可以开启一次快递行程，将偏远的边境训练基地与矮人首都伟大的铸造厂直接连接起来。"}},faq={{q="布洛克·寻石者是谁？",a="布洛克·寻石者是一位居住在塞尔萨玛的采矿训练师。他向新手传授挖掘和石艺的基础技能。",al={"布洛克·寻石者","布洛克是谁","塞尔萨玛采矿训练师"}},{q="为什么布洛克需要从铁炉堡运来锄头？",a="布洛克编制了一份获得荣誉锄的高成就采矿学徒名单。为了兑现这些奖励，订单必须送到驻扎在铁炉堡的采矿用品商人高尼尔·石趾手中。",al={"为什么要去铁炉堡","为什么需要锄头","布洛克的名单"}},{q="索格拉姆·伯雷森在这一任务中扮演什么角色？",a="索格拉姆·伯雷森是塞尔萨玛的狮鹫管理员。布洛克指示快递员将订单名单交给他，以便他们安排前往铁炉堡的快速空中运输。",al={"索格拉姆·伯雷森","索格拉姆是谁","塞尔萨玛狮鹫管理员"}},{q="谁在铁炉堡接收名单？",a="这份名单最终将送达铁炉堡的高尼尔·石趾手中，他会为布洛克那些卓有成就的学生准备好这些仪式用的锄头。",al={"谁接收名单","高尼尔·石趾","铁炉堡联系人"}},{q="这个任务接下来要去哪？",a="一旦你与索格拉姆·伯雷森交谈，他就会安排狮鹫直飞铁炉堡，这样你就可以亲手将订单交给高尼尔·石趾。",al={"下一步","矿工的馈赠后续","布洛克的名单之后"}},{q="这个任务在哪里进行？",a="任务的开始和结束都在塞尔萨玛定居点内，该定居点坐落在洛克莫丹连绵的群山之中。",al={"任务地点","塞尔萨玛在哪里","矿工的馈赠起始点"}}},fx={["7a941756"]={q="布洛克·寻石者为什么请冒险者帮忙，而不亲自送名单？",a="布洛克正忙着在塞尔萨玛训练立志成为矿工的学徒，既要传授新人的技艺，也要照看自己的熔炉。若他离开岗位，远赴铁炉堡，当地学徒的课程就会停滞，因此四处旅行的冒险者便是替他将名单送往城里的理想信使。",al={"布洛克为何找我","布洛克为何不去铁炉堡","布洛克为何不能送名单"}}},fp="14,147,13.290.0,19.225.0,25.94.0,41.171.0,52.138.0,35.111.0,33.142.0,32.75.0"}
P.entries["quest:6388"] = {n="格莱斯·瑟登",s="这项任务旨在向冒险者们介绍铁炉堡的狮鹫网，要求他们将一捆仪式用具送交至城市的狮鹫管理员处。这捆荣誉锄是由高尼尔·石趾托付给跑腿者的，他必须将其送交至格里瑟·索丹手中，以便通过空运送回洛克莫丹。",h="这项任务旨在向冒险者们介绍铁炉堡的狮鹫网，要求他们将一捆仪式用具送交至城市的狮鹫管理员处。这捆荣誉锄是由高尼尔·石趾托付给跑腿者的，他必须将其送交至格里瑟·索丹手中，以便通过空运送回洛克莫丹。",kw={"飞行管理员","高尼尔·石趾","格里瑟·索丹","荣誉锄","铁炉堡","洛克莫丹","塞尔萨玛","索格拉姆·伯雷森"},ang={["faction:Alliance"]="铁炉堡的狮鹫停驻点是联盟使节往返于丹莫罗、洛克莫丹以及更广阔的王国之间不可或缺的交通枢纽。",["profession:Mining"]="这次运送直接帮助了洛克莫丹的布洛克·寻石者的采矿学徒，用在首府铸造的荣誉锄来庆祝他们的技艺。",["race:Dwarf"]="对于矮人来说，依靠狮鹫既是一种祖传的骄傲，也是一种现实的需要，它将穿过险峻山峰的各个山厅连接了起来。"},sec={{t="矿工的跑腿差事",b="在从洛克莫丹前往大锻炉之后，跑腿者会从高尼尔·石趾那里收到一捆荣誉锄，这是为了布洛克·寻石者的采矿学徒们准备的。高尼尔建议利用矮人的狮鹫网络，而不是徒步翻越山口走回去，他让信使穿过城市去与铁炉堡的首席驯兽师进行协调。"},{t="飞往塞尔萨玛",b="格里瑟·索丹负责管理这座大山厅内的飞行点，连接着铁炉堡与卡兹莫丹各处的矮人定居点。只要冒险者已经勘探过路线并与当地的驯兽师交谈过，索丹就同意安排前往塞尔萨玛索格拉姆·伯雷森处的运输。这次交付让初出茅庐的英雄们了解到了空中信使在连接矮人王国方面所起的至关重要的作用。"}},faq={{q="荣誉锄是用来做什么的？",a="荣誉锄是高尼尔·石趾在铁炉堡打造的仪式用具，旨在送给驻扎在塞尔萨玛的采矿指导员布洛克·寻石者的学生们使用。",al={"荣誉锄","荣誉锄的作用","送给布洛克的锄头"}},{q="格里瑟·索丹是谁？",a="格里瑟·索丹是驻扎在铁炉堡的首席狮鹫管理员。他负责监管连接着这座矮人首府与整个卡兹莫丹及其他地区周边定居点的飞行路线。",al={"格里瑟·索丹是谁","铁炉堡狮鹫管理员","格里瑟·索丹背景"}},{q="格里瑟·索丹在铁炉堡的什么位置？",a="格里瑟·索丹位于大锻炉的飞行点，靠近中央主干道和铁炉堡大门。",al={"格里瑟·索丹位置","格里瑟·索丹在哪里","铁炉堡飞行管理员"}},{q="为什么我需要先与索格拉姆·伯雷森交谈？",a="狮鹫管理员只会派骑手沿着规划好的路线飞行。在格里瑟·索丹能派遣骑手前往塞尔萨玛之前，旅行者必须已经与驻扎在洛克莫丹的管理员索格拉姆·伯雷森建立了联系。",al={"索格拉姆·伯雷森的前置条件","为什么需要塞尔萨玛飞行点","无法飞往塞尔萨玛"}},{q="把锄头交给格里瑟·索丹后会发生什么？",a="一旦格里瑟检查完包裹，他就会安排一次狮鹫飞行，让你返回塞尔萨玛，将这些工具直接送到布洛克·寻石者手中。",al={"格里瑟·索丹之后做什么","格里瑟·索丹后的下一个任务"}},{q="是谁派你去找格里瑟·索丹的？",a="高尼尔·石趾，一位在铁炉堡大锻炉附近工作的工匠，他会把锄头交给你并指引你去找格里瑟。",al={"谁开启了格里瑟·索丹任务","谁发布了这个任务"}}},fx={["05b277d3"]={q="高尼尔·石趾为什么让你去找格莱斯·瑟登？",a="高尼尔·石趾已经备好了荣誉锄，要交给远在塞尔萨玛的布洛克·寻石者手下的采矿学徒。高尼尔没有让你徒步穿过积雪的山口返回，而是指引你去找铁炉堡的狮鹫管理员格莱斯·瑟登，让你学会如何安排狮鹫航班，直接飞越群山返回。",al={"为何派去找格莱斯","高尼尔·石趾的动机","格莱斯·瑟登为何要送锄头"}}},fp="13,241,24.321.0,24.397.0,32.160.0,21.118.0,44.105.0,50.179.0,53.144.0,31.115.0"}
P.entries["quest:639"] = {n="激流堡符印",s="落锤镇的森古想要夺回守护托卡拉尔的印记，那可是伊格纳斯·托尔贝恩领主之剑。第一枚印记，也就是斯托姆印记，被辛迪加夺走了。斯托姆加德的一个辛迪加特工很有可能携带着它。",h="落锤镇的森古想要夺回守护托卡拉尔的印记，那可是伊格纳斯·托尔贝恩领主之剑。第一枚印记，也就是斯托姆印记，被辛迪加夺走了。斯托姆加德的一个辛迪加特工很有可能携带着它。",kw={"阿拉希高地","落锤镇","伊格纳斯","斯托姆印记","斯托姆加德","辛迪加","托卡拉尔","托尔贝恩","森古"},sec={{t="托尔贝恩的遗产",b="远古时期，巨魔与阿拉索帝国交战，而他们最强大的敌人就是来自斯托姆的伊格纳斯领主，人称“巨魔之敌”。他持剑托卡拉尔投入战斗，这个名字在巨魔的古语中意为“巨魔杀手”。如今，托尔贝恩的后代已经衰弱，他们的堡垒也已沦为废墟。"},{t="第一枚印记",b="有数枚印记守护着这把剑，斯托姆加德的幸存者们各自保管着一部分。森古说必须将它们全部找回。辛迪加夺走了第一枚，森古认为斯托姆加德的某个特工手里就有它。把它带回落锤镇交给森古。"}},faq={{q="森古是谁？",a="森古位于阿拉希的落锤镇。他正在收集守护伊格纳斯·托尔贝恩领主之剑——托卡拉尔的印记。",al={"谁给予斯托姆印记任务","落锤镇的森古"}},{q="什么是托卡拉尔？",a="托卡拉尔在巨魔的古语中意为“巨魔杀手”。来自斯托姆的伊格纳斯领主，也就是人称“巨魔之敌”的那位，曾手持此剑与巨魔作战。",al={"什么是托卡拉尔","托卡拉尔的含义","托尔贝恩之剑"}},{q="为什么要找斯托姆印记？",a="这把剑由数枚印记守护，斯托姆加德的幸存者们将它们分散保管。森古想要集齐所有印记，而斯托姆印记是第一枚。",al={"为什么要收集印记","斯托姆印记的用途"}},{q="谁持有斯托姆印记？",a="辛迪加夺走了它。它很可能就在斯托姆加德的某个辛迪加特工身上。",al={"谁拥有斯托姆印记","斯托姆印记在哪里","辛迪加印记"}}},fp="14,186,23.280.0,15.268.0,13.109.0,19.153.0,33.147.0,29.98.0"}
P.entries["quest:6391"] = {n="飞往铁炉堡",s="“前往铁炉堡”是一项入门级的信使任务，引导刚完成训练的冒险者搭乘他们的第一次狮鹫航班，从洛克莫丹的塞尔萨玛飞往矮人的首都。旅行者受布洛克·寻石者之托，携带一份列有最优秀采矿学员名单的文书，将其直接送交到位于大锻炉的高尼尔·石趾手中。",h="“前往铁炉堡”是一项入门级的信使任务，引导刚完成训练的冒险者搭乘他们的第一次狮鹫航班，从洛克莫丹的塞尔萨玛飞往矮人的首都。旅行者受布洛克·寻石者之托，携带一份列有最优秀采矿学员名单的文书，将其直接送交到位于大锻炉的高尼尔...",kw={"布洛克的名单","深山矿业公会","高尼尔·石趾","大锻炉","狮鹫","卡拉诺斯","前往铁炉堡任务","索格拉姆·伯雷森"},ang={["faction:Alliance"]="狮鹫飞行网络构成了卡兹莫丹联盟后勤的基石，将前线驻地与宏伟的首都无缝连接起来。",["profession:Mining"]="这项任务直接突显了深山矿业公会的传统，即对从洛克莫丹矿坑中脱颖而出的有前途的矿工进行表彰并镌刻荣誉。",["race:Dwarf"]="对于年轻的铜须矮人来说，骑着狮鹫飞入大锻炉是往返于乡村前哨与王国心脏地带之间的一种令人自豪的成人仪式。"},sec={{t="飞向蓝天",b="对于许多年轻的山地探险者和旅行者来说，从塞尔萨玛飞往铁炉堡的航程是他们第一次骑乘狮鹫的旅途。这段短途航线由狮鹫管理员索格拉姆·伯雷森负责，带领旅行者飞越丹莫罗白雪皑皑的山脊，直接进入这座山中要塞如洞穴般的入口。"},{t="深山矿业公会的荣誉",b="这项差事本身是为深山矿业公会服务的。布洛克·寻石者会定期传达他最优秀的采矿学员的消息。在高尼尔·石趾等待的大锻炉，他会将学员的名字刻在荣誉锄上，以奖励他们在洛克莫丹采石场和矿坑中的辛勤工作。"}},faq={{q="这段航线的起点和终点在哪里？",a="旅程始于洛克莫丹塞尔萨玛的飞行管理员索格拉姆·伯雷森处，并将你直接送往铁炉堡内大锻炉的飞行站。",al={"飞行航线","飞行地点","飞行目的地"}},{q="什么是布洛克的名单？",a="布洛克的名单是由塞尔萨玛的采矿训练师布洛克·寻石者汇编的一份名册。它记录了他最出色的学生，以便铁炉堡的公会能够奖励他们的勤奋。",al={"布洛克的名单背景","谁是布洛克","名单是什么"}},{q="谁是高尼尔·石趾？",a="高尼尔·石趾是深山矿业公会的代表，常驻于铁炉堡的大锻炉内。他负责接收来自当地训练师的名册，并将学生的名字凿刻在荣誉锄上。",al={"高尼尔的职责","高尼尔在哪里","谁是高尼尔·石趾"}},{q="递交名单后会发生什么？",a="一旦高尼尔收到名单，他会指引你去找铁炉堡的首席狮鹫管理员格雷斯·瑟登，让你进一步熟悉王国的空中交通网络。",al={"后续任务","之后做什么","后续"}},{q="为什么用狮鹫而不用走路？",a="虽然山路和隧道直通铁炉堡大门，但这项任务作为联盟狮鹫旅行的实用指导，向新冒险者展示了他们在各定居点之间穿梭是多么快捷。",al={"为什么要飞行","可以步行前往铁炉堡吗","为什么要骑狮鹫"}},{q="什么是荣誉锄？",a="荣誉锄是深山矿业公会制作的仪式性工具，旨在表彰那些在地区导师指导下掌握了基础挖掘和地质知识的杰出采矿学员。",al={"荣誉锄","锄头奖励","采矿锄仪式"}}},fx={d8819fd3={q="索格拉姆·伯雷森为什么要你乘狮鹫前往铁炉堡？",a="索格拉姆·伯雷森是洛克莫丹塞尔萨玛的狮鹫管理员，他的生计有赖于旅人从他的飞行站乘狮鹫出行。他安排你飞往铁炉堡，将布洛克那份有潜力的采矿学徒名单交给高尼尔·石趾，既让你领略狮鹫旅行的快捷与便利，也确保重要的公会信件及时送达都城。",al={"索格拉姆·伯雷森的动机","为何派往铁炉堡","为何送布洛克的名单"}}},fp="17,161,19.186.0,33.171.0,37.107.0,21.124.0,25.179.0,40.143.0,37.143.0,25.179.0"}
P.entries["quest:6392"] = {n="向布洛克回复",s="既然你已经将布洛克·寻石者的信件送到了铁炉堡，你现在受托携带一批荣誉锄返回塞尔萨玛。利用矮人的空中交通网络，你与格里希·瑟登一同乘坐狮鹫，迅速穿过群山返回。",h="既然你已经将布洛克·寻石者的信件送到了铁炉堡，你现在受托携带一批荣誉锄返回塞尔萨玛。利用矮人的空中交通网络，你与格里希·瑟登一同乘坐狮鹫，迅速穿过群山返回。",kw={"布洛克·寻石者","飞行管理员","狮鹫","格里希·瑟登","荣誉锄","铁炉堡","返回布洛克处","塞尔萨玛"},ang={["profession:Mining"]="交付这些荣誉锄将重要的工具交到了洛克莫丹最新一批矿工的手中，延续了矮人挖掘和勘探的传统。",["race:Dwarf"]="铁炉堡和塞尔萨玛之间的航线突显了蛮锤狮鹫和铁炉堡管理员在维系各矮人据点方面所发挥的重要作用。"},sec={{t="翱翔天际",b="铁炉堡这座伟大的山中堡垒依靠着协调统一的狮鹫管理员网络，来维持与洛克莫丹等边远定居点的通讯与贸易。格里希·瑟登是铁炉堡的狮鹫管理员，他在城市的中央飞行管理员平台监督着这项运输工作。由于旅客在乘机前往某处之前，必须先与当地的管理员建立联系，因此格里希确保你在启程返回之前，已经与塞尔萨玛的索格拉姆·伯雷森交谈过。"},{t="给学员的锄头",b="你的旅程除了让你了解狮鹫旅行之外，还有一个实际目的：布洛克·寻石者，塞尔萨玛的一位受人尊敬的采矿教练，需要为他的学徒提供新装备。随着荣誉锄被安全送到他手中，整个山谷的年轻矿工们就可以开始在洛克湖周围的山丘中开采丰富的铜矿和锡矿脉了。"}},faq={{q="布洛克·寻石者是谁？",a="布洛克·寻石者是一位驻扎在洛克莫丹的塞尔萨玛的矮人采矿训练师。他指导新手矿工从周围的山丘中提取原矿和石料。",al={"布洛克·寻石者","布洛克是谁","塞尔萨玛的布洛克"}},{q="为什么我需要乘坐狮鹫来完成这个任务？",a="这项任务向旅客介绍了联盟的飞行系统。格里希·瑟登解释说，狮鹫只能载你去你之前亲自拜访过的飞行点，例如索格拉姆·伯雷森在塞尔萨玛的巢穴。",al={"为什么要飞行","飞行点任务","狮鹫飞行"}},{q="荣誉锄是用来做什么的？",a="它们是布洛克·寻石者从铁炉堡订购的新锻造采矿工具，供他的新手采矿学生在洛克莫丹矿产丰富的悬崖上使用。",al={"荣誉锄","荣誉锄是什么"}},{q="格里希·瑟登是谁？",a="格里希·瑟登是铁炉堡的狮鹫管理员，驻扎在大锻炉。他负责管理这座首都进出卡兹莫丹及更远地区的飞行航线。",al={"格里希·瑟登","铁炉堡飞行管理员"}},{q="我可以直接走回塞尔萨玛，而不是飞行吗？",a="虽然这节课旨在教你如何使用飞行路线，但布洛克·寻石者只关心你能否安全地将荣誉锄带到塞尔萨玛交给他，至于你如何到达那里并不重要。",al={"我可以走回去吗","我必须乘坐狮鹫吗"}},{q="布洛克在塞尔萨玛的什么地方？",a="布洛克·寻石者可以在塞尔萨玛的锻炉和铁砧户外找到，他随时准备协助在洛克莫丹工作的矿工。",al={"布洛克在哪里","布洛克·寻石者位置","寻找布洛克"}}},fx={c8277dbd={q="格莱斯·瑟登为什么要我送这些锄头？",a="格莱斯·瑟登管理着铁炉堡的狮鹫飞行站，维系着王国飞行路线的畅通。远在塞尔萨玛的布洛克·寻石者正急切等待一批荣誉锄，准备交给他的采矿学徒。既然你已经打通铁炉堡与索格拉姆·伯雷森飞行站之间的路线，格莱斯便借这次运送满足布洛克的物资需求，同时确保你掌握乘狮鹫穿行卡兹莫丹的本领。",al={"格莱斯为何要求这样做","格莱斯·瑟登的动机","为何给布洛克送锄头"}},be2b1abc={q="格莱斯·瑟登为什么派冒险者去，而不亲自处理？",a="格莱斯·瑟登不能离开大锻炉的岗位，他要在那里照管络绎不绝的乘客，也要照料铁炉堡珍视的狮鹫。你亲自将布洛克的信带进城中，又开通了返回塞尔萨玛的飞行路线，因此最适合充当信使，检验这条新建立的连接，并将物资直接送回那位矿工手中。",al={"格莱斯为何需要我","为何派冒险者去塞尔萨玛","为何不派信使"}}},fp="15,145,19.279.0,20.188.0,25.143.0,55.176.0,32.95.0,21.149.0,52.176.0,36.102.0"}
P.entries["quest:6393"] = {n="元素战争",s="“元素之战”是苏纳曼委托的一项任务，他是居住在石爪山脉烈日石居的水元素使节。在猎潮者耐普图隆的意志指引下，冒险者们被派往焦炭谷焦灼的深处，去熄灭炽热的火元素，并收集它们闷燃的焚火余烬核心。这让我们得以一窥元素位面之间那场古老而永恒的纷争。",h="“元素之战”是苏纳曼委托的一项任务，他是居住在石爪山脉烈日石居的水元素使节。在猎潮者耐普图隆的意志指引下，冒险者们被派往焦炭谷焦灼的深处，去熄灭炽热的火元素，并收集它们闷燃的焚火余烬核心。这让我们得以一窥元素位面之间那场...",kw={"焦炭谷","元素之战","火元素","焚火余烬","耐普图隆","石爪山脉","烈日石居","潮汐议会","苏纳曼"},ang={["class:Shaman"]="萨满祭司尊崇元素的平衡，这使得耐普图隆的仆从与火元素之间的直接冲突，成为了原始元素纷争的生动体现。",["faction:Horde"]="鉴于苏纳曼驻扎在烈日石居，途经石爪山脉的部落冒险者们正处于协助这场元素冲突的绝佳位置。"},sec={{t="山脉中的原始纷争",b="在石爪山脉崎岖的区域，一位名叫苏纳曼的使节代表潮汐议会来到了烈日石居。在水元素领主猎潮者耐普图隆的至高意志下，苏纳曼试图对火元素同族执行一项古老的复仇。这场冲突并非为了争夺凡人的疆界，而是代表了艾泽拉斯原始力量之间无休止的碰撞。"},{t="灰烬与烈焰",b="这场争斗的主要战场是焦炭谷，这是一片位于石爪山脉南部、阴燃着的伤痕累累的荒地。火元素在灰烬中滋生，威胁着周围的地区。冒险者们被征召前往该谷地，扑灭这些烈焰缠身的实体，并收集焚火余烬——元素被击败后留下的灼热残余——以向议会证明它们的毁灭。"}},faq={{q="苏纳曼是谁？",a="苏纳曼是潮汐议会派往石爪山脉烈日石居的使者。他奉猎潮者耐普图隆之命，试图向火元素发动战争，并招募冒险者来协助消灭它们。",al={"苏纳曼是谁","苏纳曼任务发布者","烈日石居元素"}},{q="为什么耐普图隆想要消灭火元素？",a="水元素领主猎潮者耐普图隆对火元素怀有古老的敌意，并亲自关注着对它们的剿灭。苏纳曼正是受潮汐议会派遣，在石爪山脉执行这一行动。",al={"为什么要对抗火元素","元素之战缘由","耐普图隆与火元素"}},{q="焦炭谷在哪里？",a="焦炭谷是一个位于石爪山脉南部、满是灰烬的荒凉盆地。那里遍布着炽热的元素生物以及其他由烈焰与废墟中诞生的危险野兽。",al={"焦炭谷在哪里","石爪山脉火元素位置","哪里寻找焚火余烬"}},{q="什么是焚火余烬？",a="焚火余烬是焦炭谷的火元素被熄灭后留下的燃烧残余。苏纳曼收集这些核心作为它们被消灭的实证，以博取潮汐议会的青睐。",al={"什么是焚火余烬","火元素掉落","焚火余烬背景"}},{q="什么是潮汐议会？",a="潮汐议会是服务于猎潮者耐普图隆的水元素权威组织。他们指挥着元素力量和像苏纳曼这样的使节，推进猎潮者的意志，对抗敌对的元素领域。",al={"潮汐议会背景","潮汐议会是谁","水元素阵营"}},{q="猎潮者耐普图隆是谁？",a="猎潮者耐普图隆是水元素领主，统治着海洋、海域和所有的水元素。和其他元素领主一样，他与敌对元素，特别是火元素，进行着一场古老而永恒的冲突。",al={"耐普图隆是谁","水元素领主","猎潮者耐普图隆"}}},fp="13,330,31.297.0,21.307.0,16.202.0,53.191.0,34.153.0,21.205.0,34.227.0,31.223.0"}
P.entries["quest:6394"] = {n="塔兹利尔的镐",s="工头塔兹利尔在一次矿产勘测中，不小心将他最钟爱的附魔矿镐遗落在了北部洞穴深处。如今，这座被称为火刃集会所的洞穴已被危险的野兽占据，那把发光的工具正静静地等待着被寻回。",h="工头塔兹利尔在一次矿产勘测中，不小心将他最钟爱的附魔矿镐遗落在了北部洞穴深处。如今，这座被称为火刃集会所的洞穴已被危险的野兽占据，那把发光的工具正静静地等待着被寻回。",kw={"火刃集会所","杜隆塔尔","工头塔兹利尔","采矿","矿镐","塔兹利尔","试炼谷","瀑布"},ang={["faction:Horde"]="保障基础工具并清除像火刃集会所这样的敌对威胁，有助于部落在试炼谷建立稳固的立足点。",["profession:Mining"]="工头塔兹利尔依靠他的附魔矿镐在杜隆塔尔进行矿产勘测，他希望在当地的树木被清理干净后，能开辟新的采矿前景。"},sec={{t="遗失的工具",b="工头塔兹利尔是试炼谷的监工，负责监管这里的工作细节。此前他曾深入北部洞穴探寻矿脉，在勘测岩石内部结构时，不慎弄丢了他珍贵的矿镐。等他意识到并折返寻找时，凶猛的野兽和敌对的生物已经占据了洞穴，迫使这位工头不得不寻求有能力的年轻新兵协助找回他遗失的工具。"},{t="黑暗中发光",b="为了让这把珍贵的矿镐在昏暗的地下深处更易于使用，塔兹利尔为其施加了一个魔法，使它能够在黑暗中发光。这种魔法照明让冒险者可以轻易发现这把位于火刃集会所内一处瀑布室里的工具，尽管要拿回它，就必须面对潜伏在洞穴阴影中的危险生物。一旦找回，塔兹利尔希望这把矿镐能再次投入使用，在整个山谷中发掘新的采矿机遇。"}},faq={{q="谁是工头塔兹利尔？",a="工头塔兹利尔负责监管试炼谷的劳工和资源收集工作，指挥苦工伐木并为采矿作业清理土地。",al={"塔兹利尔是谁","塔兹利尔的职责","工头塔兹利尔"}},{q="塔兹利尔的矿镐为什么会发光？",a="塔兹利尔在他的矿镐上施加了魔法，使它能在黑暗中发光，这样即使在漆黑的洞穴深处也能轻易被发现。",al={"矿镐为什么特别","发光的矿镐","附魔矿镐"}},{q="火刃集会所在哪里？",a="火刃集会所是一处阴暗的洞穴网络，位于试炼谷苦工伐木营地的北面。",al={"火刃集会所在哪","集会所位置","矿镐洞穴"}},{q="塔兹利尔是怎么丢掉矿镐的？",a="塔兹利尔在勘测北部洞穴矿产时落下了他最喜欢的矿镐。当他折返去拿的时候，凶猛的野兽和黑暗的邪教徒已经侵占了那个洞穴。",al={"塔兹利尔如何丢失矿镐","为什么落下矿镐","遗落的矿镐"}},{q="矿镐被丢在洞穴里的什么位置？",a="矿镐被留在了洞穴深处的一间地下室内，那里有瀑布，也是塔兹利尔最后一次勘测岩壁的地方。",al={"洞穴内部位置","矿镐房间","瀑布室"}},{q="塔兹利尔拿回矿镐后打算做什么？",a="塔兹利尔计划等他的苦工们清理完试炼谷周边的树木后，寻找一处有产出的洞穴进行开采。",al={"塔兹利尔的未来计划","塔兹利尔要开采什么"}}},fp="16,144,11.273.0,16.311.0,25.151.0,31.106.0,33.101.0,32.163.0,40.128.0,59.133.0"}
P.entries["quest:6395"] = {n="玛拉的遗愿",s="“玛拉的遗愿”是丧钟镇的新兵艾尔雷斯给予被遗忘者玩家的早期任务。任务要求玩家去追猎被天灾军团奴役的塞缪尔·菲普斯的残骸，以便将他安葬在被他杀害的妻子玛拉身边。这个任务反映了初生的被遗忘者社会渴望缅怀人类情感，并将自己与毫无理智的天灾军团区分开来。",h="“玛拉的遗愿”是丧钟镇的新兵艾尔雷斯给予被遗忘者玩家的早期任务。任务要求玩家去追猎被天灾军团奴役的塞缪尔·菲普斯的残骸，以便将他安葬在被他杀害的妻子玛拉身边。这个任务反映了初生的被遗忘者社会渴望缅怀人类情感，并将自己与毫...",kw={"丧钟镇","坟墓","玛拉·菲普斯","玛拉的遗愿","新兵艾尔雷斯","遗骸","塞缪尔·菲普斯","天灾军团"},ang={["class:Priest"]="新兵艾尔雷斯坚持进行适当的葬礼，这直接体现了被遗忘者牧师的精神职责，他们需要直面死亡、悲伤以及洛丹伦死者所受到的亵渎。",["race:Undead"]="对于新复活的被遗忘者来说，实现玛拉的遗愿是他们与曾经人类生活的情感纽带，这证明了当洛丹伦陷落时，同情心与荣誉并未随之消亡。"},sec={{t="悲剧重逢",b="在第三次战争蹂躏洛丹伦之前，玛拉和塞缪尔·菲普斯曾是一对恩爱夫妻。当瘟疫席卷他们的土地时，塞缪尔没能幸免于难，并被复活成了天灾军团的一具无脑奴隶。虽然玛拉逃过了成为亡灵的命运，却没能逃过塞缪尔本人的毒手——他在疯狂中残忍地杀害了她。尽管死于丈夫之手，玛拉在临终前并没有心怀怨恨。新兵艾尔雷斯记得，她临终的愿望是能永远安息在丧钟镇墓地，陪伴在丈夫身边。"},{t="尊重死者",b="新兵艾尔雷斯派遣被遗忘者冒险者前往丧钟镇东北方向，寻找依然徘徊在一处废弃营地中的塞缪尔·菲普斯。终结塞缪尔的痛苦有着双重意义：既清除了山谷中入侵的天灾爪牙，也能将他的遗骸带回玛拉的安息之地。正如艾尔雷斯所强调的那样，缅怀逝者并尊重他们的遗愿，是新解放的被遗忘者与天灾军团的无脑恶意之间重要的道德分界线。"}},faq={{q="玛拉·菲普斯是谁？",a="玛拉·菲普斯是洛丹伦的一位居民，她在最初的亡灵瘟疫中幸存了下来，却在丈夫塞缪尔变成毫无理智的天灾食尸鬼后被他杀害。她临终的愿望是能与丈夫合葬。",al={"玛拉·菲普斯背景故事","玛拉是谁","玛拉的背景"}},{q="谁是塞缪尔·菲普斯？",a="塞缪尔·菲普斯是瘟疫爆发前玛拉的丈夫。他屈服于天灾军团，在巫妖王的意志下丧失了理智，并杀害了自己的妻子。他徘徊在丧钟镇东北部的一处废弃营地，直到被被遗忘者冒险者终结。",al={"塞缪尔·菲普斯背景故事","谁是塞缪尔·菲普斯","塞缪尔·菲普斯在哪里"}},{q="为什么新兵艾尔雷斯要在意将他们合葬？",a="新兵艾尔雷斯生前是玛拉的朋友。除了个人情感之外，艾尔雷斯认为，尊重死者的遗愿并有尊严地对待遗骸，证明了被遗忘者依然保留着人性与道德，这使他们与毫无理智的天灾军团区分开来。",al={"为什么要帮助玛拉","新兵艾尔雷斯的动机","为什么要安葬塞缪尔"}},{q="玛拉成为被遗忘者了吗？",a="没有。据新兵艾尔雷斯所说，玛拉并没有变成亡灵。她死于丈夫之手，死得像个凡人，并被安葬在丧钟镇的墓地里。",al={"玛拉是亡灵吗","玛拉成为了被遗忘者吗","玛拉·菲普斯与亡灵"}},{q="玛拉的墓地在哪里？",a="玛拉的坟墓位于丧钟镇主教堂外墓地的第一排。",al={"玛拉的墓地位置","玛拉葬在哪里","在哪里安葬塞缪尔"}},{q="在哪里可以找到塞缪尔·菲普斯？",a="塞缪尔·菲普斯在从丧钟镇向东北方向延伸的道路旁的一处废弃营地附近徘徊。",al={"塞缪尔·菲普斯的位置","寻找塞缪尔·菲普斯","塞缪尔在哪里"}}},fp="17,263,16.400.0,19.346.0,20.151.0,20.210.0,56.207.0,27.142.0,31.90.0,32.78.0"}
P.entries["quest:64"] = {n="遗失的怀表",s="农夫法布隆和他的妻子维娜在蒙面强盗占领了他们在西部荒野的南瓜田后被迫逃离了家园。在仓皇出逃时，法布隆将一件珍贵的传家宝遗落在了农舍的衣柜里。找回这块怀表是一次难得的机会，能让人在这片地区日益严重的混乱中挽救回一些私人物品。",h="农夫法布隆和他的妻子维娜在蒙面强盗占领了他们在西部荒野的南瓜田后被迫逃离了家园。在仓皇出逃时，法布隆将一件珍贵的传家宝遗落在了农舍的衣柜里。找回这块怀表是一次难得的机会，能让人在这片地区日益严重的混乱中挽救回一些私人物品...",kw={"本尼·布兰科","迪菲亚","法布隆","怀表","南瓜田","弗娜·法布隆","衣柜","西部荒野"},ang={["faction:Alliance"]="法布隆一家的困境凸显了王国粮仓社会秩序的严重崩溃，迫使联盟旅行者不得不去处理王室所忽视的问题。",["race:Human"]="对于暴风城的人类来说，看到诚实的农民在距离首都仅一日路程的地方被暴力亡命之徒驱逐，这令人清醒地意识到王国国内的动荡。"},sec={{t="午夜驱逐",b="像西部荒野的许多农场主一样，农夫法布隆和他的妻子维娜被暴力驱逐出了自己的土地。在南瓜田里响起的突如其来的叫喊声和暴力冲突中，这对夫妇从睡梦中惊醒，只来得及匆忙收拾起随身携带的少量物品就逃离了农场。在恐慌中，法布隆不得不留下了维娜的父亲在他们结婚那天送给他的怀表，并将它遗落在了他们被占领的农舍衣柜里。"},{t="田野间的流氓",b="现在的法布隆南瓜农场到处是迪菲亚暴徒、劫掠者和像本尼·布兰科这样趁火打劫的盗贼，他们在被废弃的房屋残骸中翻找。对于普通平民来说，回去找回私人财物无异于送死。通过在满目疮痍的房间里从衣柜中取回怀表，冒险者们为这个几乎失去了所有家当的家庭带去了一丝尊严，对抗着那不断高涨的无法无天之势。"}},faq={{q="为什么那块怀表对农夫法布隆如此重要？",a="这块怀表是维娜的父亲送给他们的结婚礼物。作为失去了生计、一无所有的难民，这块怀表是他们与过去的生活和家庭遗产之间仅存的极少数情感纽带之一。",al={"怀表的重要性","法布隆怀表的意义","谁送给法布隆怀表"}},{q="是谁将法布隆一家赶出了他们的农场？",a="迪菲亚强盗和劫掠者在夜间占领了农场。席卷西部荒野的动荡局势迫使许多农场家庭在暴力威胁下放弃了他们的田地和家园。",al={"谁袭击了农场","谁占领了法布隆农场","法布隆一家的遭遇"}},{q="怀表藏在哪里？",a="怀表存放在法布隆家园的一间卧室衣柜里，该农场位于法布隆路边营地以西的南瓜田。目前有非法占据者和迪菲亚歹徒占据着这处住所。",al={"怀表在哪里","寻找怀表","衣柜位置"}},{q="本尼·布兰科是谁？",a="本尼·布兰科是一个逃犯，他与迪菲亚同伙一起逗留在法布隆的农舍内，洗劫着这处废弃的住所，并守卫着这片偷来的领地，阻止原主人收复。",al={"本尼·布兰科背景故事","房子里的人是谁"}},{q="法布隆一家现在住在哪里？",a="逃离土地后，农夫法布隆和维娜现在流落在西部荒野的路边，避难于他们的马车旁，试图在这一地区的崩溃中生存下去。",al={"法布隆一家在哪里","农夫法布隆在哪里"}},{q="暴风城会派遣卫兵协助收复这样的农场吗？",a="由于政治上的冷漠和首都领导层的缺失，暴风城在西部荒野的官方军事存在几乎为零。哨兵岭的人民民兵缺乏人手来收复各个独立的农场，使得定居者完全处于无助的境地。",al={"暴风城援助西部荒野","为什么农场没有卫兵"}}},fx={["028db52d"]={q="法布隆的怀表是什么？",a="这是一块普通的怀表，却也是一件无价的传家宝。弗娜的父亲在他们成婚那天，将它送给了农夫法布隆。匪徒在一夜之间夺走了他们的土地、收成和家园，如今这对年迈夫妇能从往日生活的废墟中挽回的，只剩下这一件纪念物。",al={"法布隆的怀表","传家宝怀表","法布隆的怀表是什么"}}},fp="22,179,19.341.0,23.309.0,56.205.0,45.209.0,26.205.0,21.162.0,36.139.0,59.247.0"}
P.entries["quest:640"] = {n="破碎的符印",s="在你从辛迪加手中夺回第一枚徽记后，森古指派你去取回剩下的两枚，它们正由盘踞在激流堡的民兵把守。托拉斯·托尔贝恩之子加林将索拉丁徽记打碎，你需要将碎片带给落锤镇的巨魔萨满托尔甘。",h="在你从辛迪加手中夺回第一枚徽记后，森古指派你去取回剩下的两枚，它们正由盘踞在激流堡的民兵把守。托拉斯·托尔贝恩之子加林将索拉丁徽记打碎，你需要将碎片带给落锤镇的巨魔萨满托尔甘。",kw={"阿拉希高地","破碎的徽记","加林·托尔贝恩","落锤镇","索拉丁徽记","激流堡","托拉斯·托尔贝恩","托尔甘","森古"},sec={{t="破碎的徽记",b="有三枚徽记守护着托拉斯·托尔贝恩的陵墓，你已经从辛迪加手中收回了第一枚。另外两枚更难获取，因为它们被盘踞在激流堡的民兵牢牢把守着。托拉斯之子加林将索拉丁徽记分成了十一块碎片，并分发给了激流堡的守军。"},{t="前往托尔甘处",b="森古让你从激流堡的守军手中夺回这些碎片，并把它们带给落锤镇的巨魔萨满托尔甘，他能将碎片重铸为完整的徽记。"},{t="在落锤镇",b="托尔甘说森古已经告诉他你需要帮助。看到这些碎片后，他认为工作并不困难，因为碎片都在这里，而且其魔法结构很容易复原。他让你闭上眼睛，很快就宣布索拉丁徽记已经重圆了。"}},faq={{q="什么是索拉丁徽记？",a="它是守护托拉斯·托尔贝恩陵墓的三枚徽记之一。他的儿子加林将其分成了十一块碎片，并分发给了激流堡的守军。",al={"索拉丁徽记背景知识","破碎徽记的含义","什么是破碎的徽记"}},{q="是谁打碎了徽记？",a="托拉斯·托尔贝恩之子加林将索拉丁徽记分成了十一块碎片，并分发给了激流堡的守军。",al={"谁打碎了徽记","徽记为何破碎","加林·托尔贝恩与徽记"}},{q="徽记碎片藏在哪里？",a="碎片在激流堡的守军手中，那里的民兵正固守着剩余的徽记。",al={"在哪里寻找碎片","谁持有碎片","激流堡守军徽记"}},{q="谁能修复破碎的徽记？",a="落锤镇的巨魔萨满托尔甘能够将这些碎片重铸为完整的徽记。",al={"谁能修复徽记","托尔甘与徽记","谁能重铸碎片"}},{q="在此之前发生了什么？",a="此任务紧接“斯特姆徽记”之后，在该任务中，你从辛迪加手中收回了第一枚徽记。",al={"前置任务","破碎的徽记的前置任务是什么","徽记任务链起点"}}},fp="16,187,17.257.0,10.161.0,13.268.1,30.161.0,22.127.0,35.105.0,30.80.0,22.82.0"}
P.entries["quest:6401"] = {n="卡雅还活着",s="“卡雅还活着”是石爪山脉中的一个部落短任务，标志着对卡雅·扁蹄的营救任务圆满结束。在护送这位年轻的牛头人平安穿过充满敌意的恐怖图腾土匪后，你会被派往烈日石居，将她幸存的好消息带给她焦急的姑妈——塔姆拉·荒原。",h="“卡雅还活着”是石爪山脉中的一个部落短任务，标志着对卡雅·扁蹄的营救任务圆满结束。在护送这位年轻的牛头人平安穿过充满敌意的恐怖图腾土匪后，你会被派往烈日石居，将她幸存的好消息带给她焦急的姑妈——塔姆拉·荒原。",kw={"扁蹄","恐怖图腾","卡雅","玛卡巴","保护卡雅","石爪山脉","烈日石居","塔姆拉","牛头人","荒原"},ang={["faction:Horde"]="石爪山脉是一片充满争议的荒野，部落的防线十分吃紧；传达幸存者的消息有助于维护分散的营地之间的团结。",["race:Tauren"]="恐怖图腾的威胁是舒哈鲁人心中一道痛苦的裂痕，这使得像卡雅这样无辜家人的安危显得尤为重要。"},sec={{t="松了一口气",b="石爪山脉危机四伏，特别是在那些恐怖图腾部族肆无忌惮地发起突袭的争议路段。当他们的村庄遭受残酷袭击时，人们曾担心年轻的卡雅·扁蹄已经遇害或被那些叛徒俘虏了。她的幸存和随后的获救，为这片崎岖山岭中持续不断的部族冲突带来了一丝难得的胜利与宽慰。"},{t="抵达烈日石居",b="在引导卡雅安全脱险后，玛卡巴·扁蹄委托你直接前往烈日石居传达消息。在那里，卡雅的姑妈塔姆拉·荒原正焦急地等待着来自路上的消息。带去卡雅平安的消息不仅慰藉了这个破碎的家庭，也进一步强化了往来的勇士在维系偏远部落据点联系中所发挥的重要作用。"}},faq={{q="卡雅·扁蹄是谁？",a="卡雅·扁蹄是一位年轻的牛头人，在石爪山脉的定居点遭到恐怖图腾叛军的暴力袭击后，她与族人失散并陷入了危险之中。",al={"卡雅是谁","卡雅·扁蹄","卡雅"}},{q="塔姆拉·荒原是谁？",a="塔姆拉·荒原是卡雅的姑妈，居住在石爪山脉的烈日石居。她曾担心自己的侄女在恐怖图腾的袭击中丧生。",al={"塔姆拉·荒原","塔姆拉是谁","卡雅的姑妈"}},{q="是谁袭击了卡雅的村庄？",a="卡雅的村庄遭到了好战的恐怖图腾氏族的伏击。这个崇尚孤立主义的牛头人派系因频繁掠夺敌对部落和过往路人而臭名昭著。",al={"谁袭击了卡雅","村庄遇袭","恐怖图腾袭击"}},{q="这个任务的前置任务是什么？",a="该任务紧接在“保护卡雅”之后，那是一项护送任务，你需要防卫卡雅·扁蹄，让她逃离俘虏魔爪并安全返回。",al={"前置任务","保护卡雅","护送任务"}},{q="烈日石居在哪里？",a="烈日石居坐落在石爪山脉中部的高处，沿着主路向西，穿过狭窄的山间隘口进入一个隐蔽的盆地即可到达。",al={"烈日石居位置","烈日石居在哪里","寻找烈日石居"}},{q="为什么玛卡巴·扁蹄让你去，而不是自己去？",a="玛卡巴仍然坚守在石爪山脉东南部边缘的营地，他依赖一名行动敏捷的信使，以便迅速让烈日石居的家人们放下心来。",al={"玛卡巴为什么留下","为什么派我去"}}},fp="12,171,18.225.0,25.235.0,21.134.0,24.141.0,28.132.0,29.91.0,34.146.0,59.133.0"}
P.entries["quest:641"] = {n="索拉丁符印",s="托尔甘对破碎徽记的重铸工作非常完美。修复后的索拉丁徽记现在可以开启托尔贝恩之墓的封印了，他让你把它带回落锤镇交给森古。",h="托尔甘对破碎徽记的重铸工作非常完美。修复后的索拉丁徽记现在可以开启托尔贝恩之墓的封印了，他让你把它带回落锤镇交给森古。",kw={"阿拉希高地","落锤镇","索拉丁徽记","托尔甘","托尔卡拉","托尔贝恩之墓","森古"},sec={{t="修复后的徽记",b="托尔甘说重铸工作非常完美，索拉丁徽记现在已经可以开启托尔贝恩之墓的封印了。把它带回落锤镇交给森古，他肯定还有更多任务要交给你。"},{t="完成一半",b="森古问你是否拿到了第二个徽记，然后说他们离从托尔贝恩之墓取出托尔卡拉又近了一步。第三个徽记的下落尚不明确，因为持有它的人在阿拉希不断移动，但他相信你能找到它。"}},faq={{q="索拉丁徽记是用来做什么的？",a="修复后的徽记可以开启托尔贝恩之墓的封印。",al={"索拉丁徽记的用途","索拉丁徽记有什么用","为什么我们需要这个徽记"}},{q="你应该把索拉丁徽记交给谁？",a="落锤镇的森古。重铸了徽记的托尔甘让你把它带回给森古。",al={"我应该把徽记带到哪里","谁来交付索拉丁徽记","索拉丁徽记交付"}},{q="这一步在寻找托尔卡拉的过程中处于什么位置？",a="它紧接着“破碎的徽记”任务，在那个任务中，托尔甘用你带来的碎片重铸了徽记。",al={"徽记任务链进度","这个任务进行到什么程度了","这个任务的前置任务是什么"}}},fp="17,138,18.172.0,13.230.1,39.57.0,42.79.0,54.105.0"}
P.entries["quest:642"] = {n="被困的公主",s="当冒险者在阿拉希高地发现一枚虹光水晶碎片，并听到自称大地公主的米兹瑞尔被困在地底深处的哀求时，“被困的公主”便由此展开。她声称自己被敌对的巨人囚禁，并恳求旅行者前往枯须峡谷对抗这些巨人的狗头人盟友，恢复她那水晶通信网络的能量。",h="当冒险者在阿拉希高地发现一枚虹光水晶碎片，并听到自称大地公主的米兹瑞尔被困在地底深处的哀求时，“被困的公主”便由此展开。她声称自己被敌对的巨人囚禁，并恳求旅行者前往枯须峡谷对抗这些巨人的狗头人盟友，恢复她那水晶通信网络的...",kw={"阿拉希高地","枯须峡谷","枯须狗头人","大地公主","虹光碎片","米兹瑞尔微粒","米兹瑞尔","被困的公主"},ang={["class:Mage"]="利用共鸣水晶碎片和大地能量微粒进行远距离交流和能量引导，这展现了一种奇特的大地魔法。",["class:Shaman"]="作为与元素之灵沟通的修行者，萨满祭司会认出米兹瑞尔自称大地公主的说法，尽管她被囚禁在大地之下这一点值得进行严谨的元素审查。",["profession:Mining"]="冒险前往枯须峡谷附近和阿拉希地下矿脉的矿工，会发现自己不仅要面对狗头人的侵扰，还会遇到与这位公主息息相关的魔法水晶碎片。"},sec={{t="石中之声",b="散落在阿拉希高地的草海平原各处，奇怪的水晶碎片嗡嗡作响，散发着遥远的能量。靠近它们就能听到从深深的地底洞穴中传来的绝望呼唤：米兹瑞尔，一位自称大地公主的实体。她声称古老的巨人将她击落并囚禁在厚重的土壤之下，切断了她与阳光普照的地面世界的联系。嵌入地表的水晶是她与地表取得联系的唯一途径，将她的求救传达给任何愿意倾听的冒险者。"},{t="枯须之源",b="为了维持那脆弱的联系并开始突破地下的囚禁，米兹瑞尔指引旅行者向东前往枯须峡谷。峡谷里充斥着枯须狗头人，据她所说，这些生物正是囚禁她的巨人的盟友。这些狗头人携带着共鸣的米兹瑞尔微粒，并守卫着一簇显眼的虹光碎片。通过从狗头人手中夺取这些微粒并将其能量注入到晶簇中，救援者就能激活水晶簇，加深与这位被困公主的沟通。"}},faq={{q="米兹瑞尔是谁？",a="透过水晶说话的声音属于米兹瑞尔，一个声称自己是被囚禁在阿拉希高地下深处的“大地公主”。由于无法独自脱困，她向路过的冒险者求助，希望能借助他们的力量与地表进行沟通。",al={"谁是被困的公主","谁在透过水晶说话","米兹瑞尔是谁"}},{q="是谁把米兹瑞尔囚禁在高原之下？",a="据米兹瑞尔所说，她是由于巨人而被囚禁在阿拉希之下的。她声称巨人将她锁在地底深处，迫使她只能依赖散落在该地区的晶体碎片，与地面上行走的人进行沟通。",al={"谁囚禁了米兹瑞尔","谁困住了公主","为什么米兹瑞尔在地底"}},{q="什么是米兹瑞尔微粒？",a="米兹瑞尔微粒是由枯须狗头人携带的结晶或元素碎片。米兹瑞尔解释说，这些微粒蕴含着足够的潜在大地能量，可以激活并强化她与地表建立联系所需的水晶簇。",al={"为什么狗头人有微粒","枯须峡谷微粒","什么是米兹瑞尔微粒"}},{q="枯须狗头人与米兹瑞尔的囚禁者有什么关联？",a="米兹瑞尔指出，生活在枯须峡谷的枯须狗头人是囚禁她的巨人的盟友。他们守护着峡谷中的一个关键水晶簇，阻隔在公主与地表之间。",al={"为什么有狗头人参与","枯须狗头人与巨人","与巨人合作的狗头人"}},{q="米兹瑞尔是如何在地底说话的？",a="米兹瑞尔通过突起在阿拉希高地土壤中的神秘虹光水晶碎片传递她的声音。这些构造就像大地魔法的发射器，使她的灵魂或声音能够穿透地底深处，联系到地表的居民。",al={"米兹瑞尔如何说话","阿拉希虹光碎片","什么是水晶碎片"}},{q="枯须峡谷在哪里？",a="枯须峡谷是阿拉希高地东部的一处崎岖裂谷。那里居住着枯须狗头人，他们包围着虹光水晶簇，而米兹瑞尔正请求你用收集到的微粒去激活它们。",al={"枯须峡谷在哪里","去哪里交微粒","枯须碎片位置"}}},fp="20,233,22.343.0,25.439.0,15.201.0,42.162.0,30.206.0,62.187.0,46.182.0,34.188.0"}
P.entries["quest:6421"] = {n="滚岩峡谷",s="在石爪山脉深处的滚岩峡谷中，当地的狗头人开始疯狂挖掘一种被称为共鸣水晶的稀有地下矿石。摩罗加尔从大地的不安震动中察觉到了异样，于是派遣部落的冒险者去探索峡谷的洞穴系统，并取回矿石样本，以揭开埋藏在岩石之下的秘密。",h="在石爪山脉深处的滚岩峡谷中，当地的狗头人开始疯狂挖掘一种被称为共鸣水晶的稀有地下矿石。摩罗加尔从大地的不安震动中察觉到了异样，于是派遣部落的冒险者去探索峡谷的洞穴系统，并取回矿石样本，以揭开埋藏在岩石之下的秘密。",kw={"滚岩峡谷","土灵","狗头人","摩罗加尔","共鸣水晶","石爪山脉","烈日石居","泰坦"},ang={["class:Shaman"]="聆听大地的萨满祭司能够感受到那股不自然的共鸣在岩石中震动，因为狗头人正在揭开原始泰坦元素工艺的遗迹。",["profession:Mining"]="滚岩狗头人挖掘的共鸣水晶并非普通的矿石；其基质中注入了古代地下建筑者留下的古老奥术残余。",["race:Tauren"]="对于崇敬大地母亲的牛头人来说，挖掘出山脉下方的远古泰坦造物，预示着石爪山脉自然平衡的危险动荡。"},sec={{t="石中的震颤",b="牛头人摩罗加尔驻守在烈日石居，怀着深切的忧虑注视着石爪山脉的峰顶。大地本身似乎受到了惊扰，一股非自然的躁动正从东南方向蔓延开来。在那里，在滚岩峡谷的峭壁之中，当地的狗头人放弃了平时的搜寻，转而疯狂地开采一种稀有的地下矿石——共鸣水晶。为了查明这些迷信的害虫为何如此拼命地挖掘，摩罗加尔征召了部落的斥候，突破它们的防线，深入洞穴的最底层，并带回未经提炼的矿石样本。"},{t="唤醒远古",b="当原始的共鸣水晶被检查时，其真实本质显露无疑：这些晶体中回荡着古老的土灵魔法。盲目挖掘深层岩石的狗头人已经突破了世界的一层古老地壳，并挖掘出了一位土灵，这是泰坦为了塑造卡利姆多的地下基石而创造的原始岩石生物之一。狗头人眼中的矿石，竟是原始历史的遗迹，这迫使牛头人必须在埋藏的东西破土而出之前进行干预。"}},faq={{q="滚岩峡谷在哪里？",a="滚岩峡谷位于石爪山脉中烈日石居的东南方，切入山体之中。峡谷通向一个蜿蜒的洞穴系统，里面到处都是滚岩狗头人。",al={"滚岩峡谷位置","滚岩峡谷在哪里","如何找到滚岩峡谷"}},{q="谁发布了滚岩峡谷任务？",a="该任务由摩罗加尔发布，他是位于石爪山脉的主要部落哨所——烈日石居的一位牛头人。",al={"谁开启了滚岩峡谷","滚岩峡谷任务发布者","摩罗加尔任务"}},{q="什么是共鸣水晶？",a="共鸣水晶是一种深埋在滚岩洞穴系统中的稀有矿石。它携带着泰坦所造土灵魔法的残留痕迹，表明这些晶体是在靠近地下土灵遗迹的地方形成的。",al={"什么是共鸣水晶","共鸣水晶传说","共鸣水晶"}},{q="为什么狗头人要如此疯狂地挖掘共鸣水晶？",a="狗头人在挖掘时偶然发现了共鸣水晶，为了贪婪地寻找闪亮的矿石，他们深入山脉之下，直到惊动了埋藏在岩石中的远古土灵。",al={"为什么狗头人在挖掘","滚岩狗头人目标","石爪山脉狗头人阴谋"}},{q="根据牛头人的传说，什么是土灵？",a="根据摩罗加尔回忆的古老传说，土灵是泰坦在很久以前铸造的岩石生物，旨在雕琢和塑造这个世界的基岩。",al={"什么是土灵","土灵与泰坦的联系","谁是土灵"}},{q="完成这个任务后会发生什么？",a="在识别出共鸣水晶中蕴含的土灵魔法后，摩罗加尔准备了一种附魔的反制手段，并发布了后续任务“唤醒土灵”，派遣你回到洞穴去对抗那个苏醒的威胁。",al={"滚岩峡谷后的下一个任务","滚岩峡谷后续","滚岩峡谷任务后续"}}},fp="19,126,20.449.0,22.329.1,37.134.0,40.128.0,27.177.1,51.171.1,44.128.0,41.164.1"}
P.entries["quest:643"] = {n="阿拉索符印",s="继索拉丁符印任务之后，森古告诉你，人类王子将另一枚印记托付给了指挥骑兵的瓦洛卡尔中尉。找到他，并将印记带回落锤镇交给森古。",h="继索拉丁符印任务之后，森古告诉你，人类王子将另一枚印记托付给了指挥骑兵的瓦洛卡尔中尉。找到他，并将印记带回落锤镇交给森古。",kw={"阿拉希高地","落锤镇","瓦洛卡尔中尉","阿拉索符印","激流堡","托卡拉尔","瓦洛卡尔","森古"},sec={{t="王子的骑兵",b="森古嘲笑道，人类连保住激流堡都很难，更别提整个阿拉希高地了，但他们的王子却让仅存的骑兵在乡村里四处游荡。森古无法理解原因。更重要的是，其中一枚印记在率领这些骑兵的瓦洛卡尔中尉手中。森古想要找到他，并将印记带回落锤镇。"},{t="在马背上",b="森古警告说，瓦洛卡尔很难被追上，因为他的马带着他在大地上飞驰。一旦他倒下，森古预计激流堡的守军将遭受重创，而部落距离夺取托卡拉尔又近了一枚印记。"}},faq={{q="是谁派你去寻找阿拉索符印的？",a="命令来自在落锤镇等候的森古。",al={"阿拉索符印任务发布者","谁发布了阿拉索符印任务","在哪里接取阿拉索符印任务"}},{q="是谁持有阿拉索符印？",a="瓦洛卡尔中尉，人类骑兵的指挥官，人类王子将印记交给了他。森古说他骑着马，很难追踪。",al={"谁持有阿拉索符印","瓦洛卡尔在哪里","瓦洛卡尔中尉位置"}},{q="为什么瓦洛卡尔中尉拥有这枚印记？",a="森古说人类王子给了他一枚印记。森古没有说明原因。",al={"为什么瓦洛卡尔拥有印记","谁给了瓦洛卡尔印记"}},{q="这在托卡拉尔任务链中处于什么位置？",a="这是漫长的托卡拉尔任务链的第五步。它位于索拉丁符印之后，之后是托尔贝恩符印。",al={"托卡拉尔任务链阿拉索","阿拉索符印的前置任务","阿拉索符印的后续任务"}},{q="找到印记后该带到哪里？",a="带回落锤镇交给森古。",al={"在哪里上交阿拉索符印","阿拉索符印上交"}}},fp="16,164,20.312.0,12.231.1,43.61.0,31.175.0,45.100.0,44.136.0,46.44.0"}
P.entries["quest:644"] = {n="托尔贝恩符印",s="继阿拉索徽记之后，森古派你去杀死加林·托尔贝恩王子，并夺取最后那枚徽记——那枚可以开启他父亲托尔斯·托尔贝恩陵墓的徽记。王子将它随身携带，藏在激流堡深处。",h="继阿拉索徽记之后，森古派你去杀死加林·托尔贝恩王子，并夺取最后那枚徽记——那枚可以开启他父亲托尔斯·托尔贝恩陵墓的徽记。王子将它随身携带，藏在激流堡深处。",kw={"加林·托尔贝恩","落锤镇","阿拉索徽记","激流堡","托卡拉尔","森古","祖尔格拉布"},sec={{t="最后的徽记",b="能开启托尔斯·托尔贝恩陵墓的最后那枚徽记由托尔斯的儿子，加林王子亲自保管。他就在激流堡深处，民兵控制区内的一座教堂里。森古警告说，加林守卫森严，且是个厉害的战士，所以此行可能会非常艰难。你必须杀掉他，并将徽记带给落锤镇的森古。"},{t="森古的裁决",b="森古询问伊格纳斯·托尔贝恩的血脉是否已断绝。一旦断绝，他宣称托尔贝恩的血脉将不再困扰他的人民，而夺取托卡拉尔所需的所有徽记现在都已在他们手中。他发誓，用不了多久，他们就会向他痛恨的祖尔格拉布的巨魔发起进攻。"}},faq={{q="是谁派你去取回托尔贝恩徽记的？",a="是落锤镇的森古派你去取回的。",al={"托尔贝恩徽记任务发放者","谁发放托尔贝恩徽记任务","在哪里开始托尔贝恩徽记任务"}},{q="加林·托尔贝恩王子在哪里？",a="在激流堡深处的一座教堂里，位于民兵控制的区域内。",al={"加林·托尔贝恩王子位置","加林·托尔贝恩在哪里","激流堡的加林·托尔贝恩"}},{q="为什么要用到托尔贝恩徽记？",a="这是森古开启托尔斯·托尔贝恩陵墓所需的最后一枚徽记，由托尔斯的儿子亲自保管。",al={"托尔贝恩徽记的用途","为什么要获取托尔贝恩徽记"}},{q="获得托尔贝恩徽记之后会发生什么？",a="任务线将继续进行，接下来是托卡拉尔。",al={"托尔贝恩徽记之后的任务","托尔贝恩徽记后续"}}},fp="18,151,14.273.0,15.267.1,49.67.0,40.101.0,37.131.0,50.77.0"}
P.entries["quest:6441"] = {n="萨特的角",s="“萨特的角”是一份由游历灰谷碎木岗哨的地精皮克希尔提供的雇佣合同。皮克希尔在棘齿城的港口小镇发现了有利可图的贸易机会，于是雇佣有能力的部落冒险者去猎杀当地的萨特巢穴，收集他们珍贵的角。",h="“萨特的角”是一份由游历灰谷碎木岗哨的地精皮克希尔提供的雇佣合同。皮克希尔在棘齿城的港口小镇发现了有利可图的贸易机会，于是雇佣有能力的部落冒险者去猎杀当地的萨特巢穴，收集他们珍贵的角。",kw={"灰谷","夜道谷","皮克希尔","棘齿城","萨特的角","萨提纳尔","碎木岗哨","萨维亚"},ang={["class:Hunter"]="在萨提纳尔和夜道谷等被腐蚀的林地废墟中追踪恶魔类人生物，是对野外追踪技能的一项危险考验。",["class:Warlock"]="萨特体内灌注着强大的邪能魔法，这使得他们的躯体残骸对于那些研究恶魔力量的人来说是宝贵的奇珍。",["faction:Horde"]="清除灰谷中部的萨特可以削弱那些威胁碎木岗哨脆弱补给线的危险恶魔据点。"},sec={{t="有利可图的商机",b="在碎木岗哨这个部落前哨站休息时，一名投机的地精旅行者皮克希尔注意到边境市场有一个商机。在贫瘠之地的棘齿城，从灰谷的恶魔萨特身上获取的角需求量很大。皮克希尔不愿亲身犯险去面对那些堕落的生物，于是雇佣路过的冒险者在南下返回之前收集十六根完整的角。"},{t="堕落者的栖息地",b="灰谷的萨特居住在古老森林中四散的、被邪能污染的废墟里，这些是他们在古代大分裂期间背叛的遗迹。为了完成皮克希尔的订单，猎人们被指引前往已知的萨特据点，包括夜道谷、萨提纳尔的防御营地，以及萨维亚的阴影丛林。从这些巢穴中的任何一处进行采集，都能获得在棘齿城商铺中备受追捧的珍贵恶魔战利品。"}},faq={{q="皮克希尔是谁？",a="皮克希尔是一名进取的地精旅行者，在返回南方的中立港口棘齿城之前，他暂时停留在灰谷的碎木岗哨。",al={"任务发布者是谁","皮克希尔背景故事","碎木岗哨的地精"}},{q="为什么棘齿城需要萨特的角？",a="皮克希尔提到萨特的角在棘齿城能卖出高价。那里的商贩、炼金术士和奇异收藏家非常青睐从北部森林带回的原始恶魔试剂和奇珍材料。",al={"为什么收集萨特的角","角的用途","棘齿城的萨特角"}},{q="在灰谷哪里能找到萨特的角？",a="萨特栖息在灰谷的几处被污染的地区。著名的巢穴包括碎木岗哨西北方向的夜道谷、通往艾萨拉的大路旁的萨提纳尔，以及灰谷东北部的萨维亚。",al={"萨特位置","萨特在哪里","夜道谷 萨维亚 萨提纳尔"}},{q="什么是萨特？",a="萨特是数千年前屈服于燃烧军团恶魔腐蚀的古老暗夜精灵。他们变异成了长着蹄子和角的野兽，效忠于黑暗力量，并积极地腐蚀着周围的森林。",al={"什么是萨特","萨特背景故事","萨特是恶魔吗"}},{q="为什么这份合同在碎木岗哨处理？",a="碎木岗哨是部落在灰谷中部的核心要塞。皮克希尔将这里作为贸易路线间的一个安全休息点，并雇佣了周围那些已经卷入该地区危险冲突的部落战士。",al={"碎木岗哨萨特任务","为什么只有部落能接"}},{q="皮克希尔效忠于部落吗？",a="不。皮克希尔是一个独立的地精商人，只为了赚取利润。像许多以棘齿城为基地的地精一样，皮克希尔与任何能提供贵重贸易商品的人合作，并不关心阵营政治。",al={"皮克希尔是部落吗","皮克希尔阵营"}}},fp="11,147,23.301.0,23.319.0,13.120.0,34.177.0,44.184.0,16.175.0,50.176.0,44.188.0"}
P.entries["quest:6442"] = {n="佐拉姆海岸的纳迦",s="“佐拉姆海岸的娜迦”是一个部落任务，要求冒险者们清除灰谷西北海岸线上好战的蛇形入侵者。驻扎在佐拉姆加前哨站的巨魔玛鲁凯正试图通过驱逐沉没的古代佐拉姆废墟中的愤怒之尾娜迦，来确保这段备受争议的海岸线的安全。",h="“佐拉姆海岸的娜迦”是一个部落任务，要求冒险者们清除灰谷西北海岸线上好战的蛇形入侵者。驻扎在佐拉姆加前哨站的巨魔玛鲁凯正试图通过驱逐沉没的古代佐拉姆废墟中的愤怒之尾娜迦，来确保这段备受争议的海岸线的安全。",kw={"灰谷","玛鲁凯","娜迦","愤怒之尾","愤怒之尾首级","佐拉姆海岸","佐拉姆加前哨站"},ang={["faction:Horde"]="坚守佐拉姆加前哨站对部落在灰谷的扩张至关重要，因此清除娜迦已成了关乎军事生存的问题。",["race:Orc"]="玛鲁凯那种通过残酷击退来解决问题的直接策略，与兽人边境守军务实的尚武文化相吻合。"},sec={{t="岌岌可危的立足点",b="部落在佐拉姆海岸的处境非常不稳定。由于身处敌对暗夜精灵的领地之中，且灰谷内战火连绵，这座前哨站成了至关重要的沿海联络点。然而，突然出现的大量好战娜迦爬上岸来，威胁着要切断部落与海洋的联系，并在部落完全加固阵地之前将其守军淹没。"},{t="厄运佐拉姆的回响",b="在佐拉姆海岸的沙滩下掩埋着佐拉姆破碎的残骸。那曾是一座古老的精灵城市，在数千年前的大分裂中被大海吞没。玛鲁凯和前哨站的守军并不清楚这些愤怒之尾娜迦部族为何现在从深海沟壑中爬出来，但它们对沉没废墟突然表现出的兴趣对于任何在地面上行走的人来说都不是好兆头。"},{t="生存的代价",b="玛鲁凯以一种直截了当的生存视角看待局势：当利剑与三叉戟出鞘时，道理便不再重要。她要求收集二十颗愤怒之尾入侵者的首级，旨在以绝对武力将这些蛇形怪物赶回深海，从而为部落稳固海岸线。"}},faq={{q="谁发布了“佐拉姆海岸的娜迦”这个任务？",a="该任务由玛鲁凯发布，她是一位驻扎在灰谷西北部佐拉姆海岸的佐拉姆加前哨站的暗矛巨魔。",al={"任务发布者","谁开启任务","玛鲁凯位置"}},{q="佐拉姆海岸的背景历史是什么？",a="这段海岸线标志着古老而毁灭的佐拉姆城的安息之地。它在很久以前的大分裂时期被摧毁并沉没在无尽之海之下，如今其废墟部分位于灰谷的海岸线水下。",al={"什么是佐拉姆","佐拉姆历史","沉没之城"}},{q="为什么娜迦要攻击海岸？",a="部落驻军并不清楚愤怒之尾部族到来的确切动机，只知道这些生物从深海涌出，意图占据沉没的废墟并驱赶所有陆地居民。",al={"娜迦为何在此","愤怒之尾动机","娜迦目标"}},{q="我需要在这个任务中对抗哪些敌人？",a="你需要杀掉在佐拉姆海岸的沙滩和浪潮中爬行的愤怒之尾娜迦部族成员，并为玛鲁凯收集二十颗它们的首级。",al={"哪种娜迦","愤怒之尾首级","目标敌人"}},{q="“佐拉姆海岸的娜迦”之后是什么任务？",a="玛鲁凯在完成此任务后不会再提供后续任务；她只是感谢你，并希望能有更多像你一样的人来帮助守住海岸线。",al={"下一个任务","后续任务","玛鲁凯后续"}},{q="为什么部落关心这个偏僻的海滩？",a="灰谷是部落与暗夜精灵激烈争夺的地区。在佐拉姆海岸建立一个安全的沿海桥头堡，能让部落获得战略通路和补给线，避开密集的内陆森林。",al={"为什么部落在此","佐拉姆加前哨站目的"}}},fp="24,178,21.310.0,22.333.0,21.242.0,45.121.0,44.207.0,37.160.0,48.151.0,44.119.0,48.177.0"}
P.entries["quest:645"] = {n="托卡拉尔",s="继巨魔克星符印之后，森古发现四枚符印已合而为一，足以破除巨魔克星陵墓上的结界。他派你去激流堡从陵墓中取回托卡拉尔。",h="继巨魔克星符印之后，森古发现四枚符印已合而为一，足以破除巨魔克星陵墓上的结界。他派你去激流堡从陵墓中取回托卡拉尔。",kw={"墓穴","密室","伊格纳乌斯符印","激流堡","托卡拉尔","巨魔克星","森古"},sec={{t="四印合一",b="森古发现四枚符印已经汇聚并形成了一枚新的符印，即伊格纳乌斯符印。他深信这枚符印能够破除施加在巨魔克星陵墓上的结界。巨魔克星安葬于激流堡教堂后的密室中，森古派你去那里取回托卡拉尔。教堂入口右侧有一条带围栏的小径，通往下方的墓穴。"},{t="陵墓开启",b="陵墓表面的刻痕与符印上发光的纹路一一对应。将两者对齐，一道闪光吞没了符印，传说之剑托卡拉尔从抓住它的石手中被解放了出来。"}},faq={{q="是谁派你去取回托卡拉尔的？",a="是森古，在他发现四枚符印合成了伊格纳乌斯符印之后。",al={"谁发布此任务","任务发布者","森古"}},{q="巨魔克星的陵墓在哪里？",a="他的遗骸安葬在激流堡教堂后的密室里。教堂入口右侧有一条带围栏的小径，通往地下的墓穴。",al={"陵墓在哪里","陵墓位置","墓穴位置"}},{q="那四枚符印发生了什么事？",a="它们合而为一，形成了伊格纳乌斯符印。森古认为这枚符印可以破除巨魔克星陵墓上的结界。",al={"符印发生了什么","伊格纳乌斯符印"}},{q="这个任务链的上一步是什么？",a="巨魔克星符印是四枚符印中的最后一枚，也是此任务的前置。",al={"上一个任务","前置任务","巨魔克星符印"}}},fp="10,89,19.309.0,14.196.1,37.91.0,34.139.0,32.108.0,40.67.0"}
P.entries["quest:646"] = {n="托卡拉尔",s="漫长的托卡拉尔任务线终于到了最后一步。光芒渐渐消散，被封印在石鞘中的托卡拉尔重见天日。将它带给落锤镇的森古。",h="漫长的托卡拉尔任务线终于到了最后一步。光芒渐渐消散，被封印在石鞘中的托卡拉尔重见天日。将它带给落锤镇的森古。",kw={"阿拉希","落锤镇","尼姆布亚","托卡拉尔","托尔贝恩","森古","祖尔格拉布"},sec={{t="重获自由之剑",b="在托尔贝恩之墓，光芒渐渐消散，被封印在石鞘中的托卡拉尔重见天日。你带着这把剑鞘包裹着的剑，前往阿拉希高地落锤镇的森古那里。"},{t="森古的话",b="森古告诉你，斯托姆加德和阿拉索的军队世世代代都在捕杀巨魔，而现在他们最伟大的武器落入了他族人的手中。向祖尔格拉布潮湿丛林的缓慢推进将不再是一场苦战。他说暗矛巨魔欠你一个人情，他会负责将这把剑送到格罗姆高营地的尼姆布亚手中。"}},faq={{q="托卡拉尔需要带去哪里？",a="去阿拉希高地落锤镇找森古。你拿到这把剑时，它依然被封在石鞘里。",al={"我要把托卡拉尔带到哪里","托卡拉尔运送","托卡拉尔上交"}},{q="我在哪里能找到这把剑？",a="在托尔贝恩之墓，那里消散的光芒使其从石鞘中释放了出来。",al={"托卡拉尔在哪里","托卡拉尔位置"}},{q="这一步之前发生了什么？",a="这是漫长的托卡拉尔任务线的最后一步，它紧接着之前的托卡拉尔任务。",al={"托卡拉尔前置任务","托卡拉尔任务线"}}},fp="10,126,16.144.0,15.298.1,33.92.0,26.94.0,27.80.0"}
P.entries["quest:6461"] = {n="盗窃的蜘蛛",s="“吸血者”是玛拉卡金暗矛巨魔定居点中的辛吉拉发布的一项部落狩猎契约。当地的巨魔在石爪山脉的坡地上找到了丰富的猎物，但屠宰猎物散发出的气味引来了大群捕食性的深苔蜘蛛，它们成群结队地侵入了营地。",h="“吸血者”是玛拉卡金暗矛巨魔定居点中的辛吉拉发布的一项部落狩猎契约。当地的巨魔在石爪山脉的坡地上找到了丰富的猎物，但屠宰猎物散发出的气味引来了大群捕食性的深苔蜘蛛，它们成群结队地侵入了营地。",kw={"吸血者","深苔爬行者","深苔毒液喷吐者","玛拉卡金","希塞尔山谷","蜘蛛","石爪山脉","辛吉拉"},ang={["class:Hunter"]="对于穿行在岩架间的资深追踪者而言，追踪那些狩猎并骚扰友好定居点的危险掠食者是顺理成章的工作。",["faction:Horde"]="玛拉卡金是部落从北部贫瘠之地进入石爪山脉的重要通路支点，保卫这个村庄也就确保了整个南部隘道的安全。",["race:Troll"]="玛拉卡金的猎人们是同胞，他们努力在卡利姆多崎岖的高地上开辟自给自足的领地，而不屈服于荒野。"},sec={{t="不受欢迎的晚餐宾客",b="在石爪山脉东南部建立玛拉卡金前哨站的巨魔们最初是为了寻找良好的狩猎场所。崎岖的山坡果然物产丰富，但他们带回的肉类和猎物很快就引起了夜行性掠食者的注意。深苔蜘蛛是北方岩架和峡谷中的原生攻击性蛛形纲动物，它们开始在夜幕的掩护下潜入营地，试图搜刮补给，甚至将猎人当作猎物。"},{t="清理岩架",b="为了确保营地的安全并保护补给，辛吉拉请求冒险者们向北追踪这些掠食者，进入山间隘口。在希塞尔山谷的岩石沟壑和蛛网密布的区域，深苔爬行者和毒液喷吐者的数量最为密集。削减它们的数量可以将蜘蛛群从玛拉卡金的边界驱赶出去，确保村庄在夜晚无需担忧遭到伏击。"}},faq={{q="谁发布了任务“吸血者”？",a="位于石爪山脉东南部玛拉卡金村的暗矛巨魔辛吉拉，向途经此地的部落勇士发布了这项任务。",al={"谁发布吸血者任务","吸血者任务发布人","辛吉拉任务"}},{q="为什么蜘蛛会攻击玛拉卡金？",a="玛拉卡金的巨魔们在当地进行了大规模狩猎。新鲜猎物和风干肉食散发的气味在夜间将深苔蜘蛛从山口引诱下来，它们以此偷窃补给并猎杀村民。",al={"为什么蜘蛛会攻击","蜘蛛袭击玛拉卡金","为什么蜘蛛在入侵"}},{q="深苔蜘蛛位于何处？",a="深苔爬行者和毒液喷吐者在玛拉卡金以北的中央隘口和岩架上游荡，其中在蛛网密布的希塞尔山谷深处聚集成群。",al={"深苔蜘蛛在哪里","深苔爬行者位置","深苔毒液喷吐者位置"}},{q="什么是玛拉卡金？",a="玛拉卡金是一个暗矛巨魔定居点，位于石爪山脉的南入口，靠近贫瘠之地边界，是部落的一个前哨狩猎基地。",al={"什么是玛拉卡金","玛拉卡金背景传说","石爪山脉巨魔村庄"}},{q="这些蜘蛛是否还引发了更大的威胁？",a="在希塞尔山谷的蛛网深处居住着一只体型巨大且致命的蜘蛛女王。峡谷外的一块告示牌警告了过往的旅行者这种危险，并鼓励小队前去铲除它。",al={"石爪山脉大蜘蛛","希塞尔山谷精英蜘蛛","石爪山脉蜘蛛女王"}},{q="清理蜘蛛后会发生什么？",a="清理掉爬行者和毒液喷吐者后，玛拉卡金的压力得以缓解，巨魔猎人可以守住肉食储备，并在夜间于营地中走动，不再时刻受到伏击的威胁。",al={"吸血者任务后续","玛拉卡金是否变安全"}}},fp="13,179,22.391.0,18.377.0,35.138.0,41.210.0,39.164.0,19.173.0,48.179.0,42.169.0"}
P.entries["quest:6462"] = {n="巨魔符咒",s="“巨魔符咒”是部落的一项任务，由位于灰谷佐拉姆加前哨站的暗矛巨魔米苏瓦提供。在一队旅行的巨魔遭到蓟皮熊怪的伏击并被屠杀后，米苏瓦请求冒险者深入它们的巢穴，找回被从死者身上偷走的圣物。",h="“巨魔符咒”是部落的一项任务，由位于灰谷佐拉姆加前哨站的暗矛巨魔米苏瓦提供。在一队旅行的巨魔遭到蓟皮熊怪的伏击并被屠杀后，米苏瓦请求冒险者深入它们的巢穴，找回被从死者身上偷走的圣物。",kw={"灰谷","暗矛","熊怪","米苏瓦","蓟皮要塞","蓟皮村","巨魔符咒","佐拉姆加前哨站"},ang={["faction:Horde"]="深入蓟皮熊怪的领地是对那些伏击部落补给线和穿过灰谷的旅行者的林地威胁的反击。",["race:Troll"]="对于暗矛巨魔来说，找回符咒是一种精神职责，旨在确保神圣的祖传物品从野蛮的熊怪魔爪中被救回。"},sec={{t="遇袭的车队",b="佐拉姆加前哨站是部落在灰谷海岸西部的一处偏远避难所，这使得沿着林间小路行进充满了危险。一队前往该哨所的暗矛巨魔在途中失踪，他们遭遇了领地意识极强的蓟皮熊怪的暴力伏击。虽然米苏瓦接受了他的族人死亡这一事实，认为他们终会在来世重聚，但对他们圣物符咒的亵渎和窃取是不可容忍的侮辱。"},{t="圣物",b="在巨魔文化中，符咒和护身符与身份、精神保护以及与洛阿神的联系紧密相连。米苏瓦认为，一个没有符咒的巨魔就像一个没有战斗伤疤的兽人一样空虚且毫无价值。蓟皮熊怪将这些偷来的神器拖回了位于蓟皮村深处的蓟皮要塞洞穴系统中，并将它们藏在箱子里，使其远离真正的主人。"}},faq={{q="谁提供这个任务，他们位于哪里？",a="该任务由米苏瓦提供，他是一名驻扎在灰谷西北海岸佐拉姆海岸的佐拉姆加前哨站的暗矛巨魔。",al={"任务提供者","米苏瓦的位置","谁开启巨魔符咒任务"}},{q="为什么巨魔符咒对米苏瓦如此重要？",a="对巨魔而言，圣物符咒具有深远的精神和文化意义。米苏瓦将没有符咒的巨魔比作没有战斗伤疤的兽人，他认为敌对的熊怪持有这些圣物是对他被杀害的族人的粗暴亵渎。",al={"符咒的重要性","为什么巨魔符咒很重要","符咒的意义"}},{q="巨魔符咒位于哪里？",a="符咒被存放在蓟皮要塞内的箱子里，这是一个位于蓟皮村北缘的深层洞穴建筑群，坐落在暗夜精灵定居点阿斯特兰纳的北部。",al={"符咒位置","箱子在哪里","寻找符咒"}},{q="谁偷走了符咒？",a="蓟皮熊怪在米苏瓦的族人前往佐拉姆加前哨站的途中伏击并杀害了他们，洗劫了他们的财物并将圣物符咒拖入了他们的洞穴中。",al={"谁拿走了符咒","伏击元凶"}},{q="最初携带符咒的巨魔遭遇了什么？",a="他们在路上被蓟皮熊怪杀害了。米苏瓦哀悼他们的离去，但相信终有一天能在来世与他们重聚，目前他将找回他们的圣物作为首要任务。",al={"车队命运","被杀的巨魔","米苏瓦的族人"}},{q="联盟可以接这个任务吗？",a="不可以。该任务始于佐拉姆加前哨站，仅供帮助暗矛部族的部落玩家接取。",al={"联盟能接巨魔符咒吗","联盟可以做这个任务吗"}}},fp="11,155,19.358.0,15.388.0,48.112.0,49.198.0,35.134.0,21.159.0,62.173.0,40.58.0"}
P.entries["quest:647"] = {n="马克里尔的月光酒",s="马克里尔的月光酒是一个节奏紧凑的跑腿任务，受托于醉鬼马克里尔。这位矮人被困在萨多尔大桥断裂的一侧。由于贪杯喝多了自己酿的烈酒，导致在执勤时睡过了头，醉鬼马克里尔只能拜托一名联盟旅人赶紧把刚酿好的一批酒送去希尔斯布莱德，以还清他欠南海镇布鲁米·比格尔的一笔旧债。",h="马克里尔的月光酒是一个节奏紧凑的跑腿任务，受托于醉鬼马克里尔。这位矮人被困在萨多尔大桥断裂的一侧。由于贪杯喝多了自己酿的烈酒，导致在执勤时睡过了头，醉鬼马克里尔只能拜托一名联盟旅人赶紧把刚酿好的一批酒送去希尔斯布莱德，以...",kw={"比格尔","醉鬼马克里尔","布莱德·长须","马克里尔","米奈希尔","月光酒","南海镇"},ang={["faction:Alliance"]="这段快速的陆路行程突显了萨多尔大桥与希尔斯布莱德联盟控制下的南海镇之间至关重要的联系。",["race:Dwarf"]="矮人们会立刻理解那种伴随着剧烈宿醉，同时又欠同胞一笔酿酒债的双重窘境。"},sec={{t="守卫的宿醉",b="在断裂的萨多尔大桥上执勤的日子又湿又冷，而且出了名的枯燥。醉鬼马克里尔通过畅饮自己私酿的月光酒来抵御潮湿的寒意，这种酒极其猛烈，他形容喝完之后的感觉就像有一整支攻城器械部队从他的脑壳上碾过。但不幸的是，马克里尔因为喝得太多，在执勤时昏了过去。由于布莱德·长须正在指挥守卫大桥的矮人部队，马克里尔绝不能再出任何纪律上的岔子了。"},{t="与时间的赛跑",b="让马克里尔雪上加霜的是，他欠南海镇的布鲁米·比格尔一笔长期债务。马克里尔曾答应比格尔会送去一批他亲手酿的酒来抵债，但宿醉加上执勤任务，让他距离违约只剩几分钟的时间了。旅人必须依靠狮鹫和双脚，穿过阿拉希高地赶往南海镇，在比格尔认定马克里尔又一次赖账之前把酒桶送达。"}},faq={{q="醉鬼马克里尔是谁？",a="醉鬼马克里尔是一位矮人，可以在萨多尔大桥断裂的一侧找到，从阿拉希高地那一侧可以到达那里。他以酿造极其烈性的私酿月光酒而闻名，而且在执勤时往往会对自己的产品浅尝辄止得有点过头。",al={"醉鬼马克里尔","醉鬼马克里尔是谁","马克里尔任务发布者"}},{q="为什么这次送货这么紧急？",a="马克里尔因为在执勤时醉倒，导致任务严重延误。他有一个必须把月光酒送到布鲁米·比格尔手中以还清逾期债务的最后期限，从萨多尔大桥赶往南海镇的时间只剩下不到一刻钟了。",al={"为什么有计时器","为什么是15分钟","马克里尔的月光酒计时器"}},{q="布鲁米·比格尔是谁？",a="布鲁米·比格尔是一位矮人酿酒大师，在希尔斯布莱德丘陵的南海镇沿海定居点经营他的生意。他钟爱烈性酒精，并与醉鬼马克里尔有一笔未完成的商业协议。",al={"布鲁米·比格尔","比格尔是谁","比格尔 南海镇"}},{q="如何才能及时把月光酒送到南海镇？",a="从大桥没有船去南海镇。最快的路线是前往阿拉希高地，如果你知道飞行点，就从避难谷地骑狮鹫飞往南海镇，然后在计时结束前在镇子里找到布鲁米·比格尔。",al={"如何运送月光酒","马克里尔南海镇最快路线","月光酒配送路线"}},{q="长须是谁？",a="布莱德·长须是驻扎在湿地丹莫德外围的矮人指挥官，负责领导萨多尔大桥的守卫工作。马克里尔非常害怕被长须发现他在执勤时喝得不省人事。",al={"长须队长","长须 米奈希尔"}}},fp="20,211,18.422.0,24.368.0,22.183.0,31.217.0,26.206.0,53.196.0,17.208.0"}
P.entries["quest:648"] = {n="拯救OOX-17/TN！",s="受损的归航机器人OOX-17/TN发出了奥格索普的声音。它需要一个开阔、安全的地方来进行长时间的起飞，你被要求将其安全护送至热砂港，然后前往藏宝海湾找到奥格索普·奥布诺提斯。",h="受损的归航机器人OOX-17/TN发出了奥格索普的声音。它需要一个开阔、安全的地方来进行长时间的起飞，你被要求将其安全护送至热砂港，然后前往藏宝海湾找到奥格索普·奥布诺提斯。",kw={"藏宝海湾","归航机器人","机械小鸡","奥格索普·奥布诺提斯","17型机械小鸡","热砂港","塔纳利斯"},sec={{t="护送至港口",b="奥格索普的声音再次从机器人体内传出，伴随着杂音。该机器人有内置的隐形装置，但奥格索普需要时间使其重新运作，因此它必须到达一个开阔、安全的地方，以便开始其漫长的起飞程序。热砂港正是奥格索普所想的地方，这段旅程能为他争取到修复的时间。你的任务是将机器人安全护送至那里。"},{t="前往藏宝海湾报告",b="一旦机器人安全抵达港口，你被要求在藏宝海湾寻找工程学大师奥格索普·奥布诺提斯。"},{t="感激的发明家",b="奥格索普把你当作救下OOX-17/TN的人来迎接。归航机器人系列仍需改进，但找回这一台机器节省了无数的重建时间以及大量的金币重造费用。奥格索普说，无论是机器人还是这位发明家都欠你一个人情。"}},faq={{q="需要把机器人护送到哪里？",a="送往热砂港，它可以在那里安全地开始起飞。",al={"机械小鸡-17要去哪里","机械小鸡-17护送路线","机器人目的地"}},{q="是谁在通过机器人说话？",a="奥格索普·奥布诺提斯，一位侏儒兼工程学大师，这台归航机器人就是他的。你可以在藏宝海湾找到这位发明家。",al={"谁制造了机械小鸡-17","机械小鸡-17的制造者","谁在通过机器人说话"}},{q="为什么要转移这台机器人？",a="它需要一个开阔、安全的地方来开始漫长的起飞程序。它内置的隐形装置也需要时间来重新恢复运作。",al={"为什么要转移机械小鸡-17","为什么要前往热砂港"}},{q="护送任务完成后该去哪里报告？",a="奥格索普·奥布诺提斯在藏宝海湾等待。",al={"奥格索普·奥布诺提斯在哪里","任务交给谁","机械小鸡-17任务交接地点"}}},fp="17,190,21.343.0,19.106.0,19.271.1,41.86.0,34.114.0,36.119.0,37.44.0"}
P.entries["quest:6481"] = {n="土灵的觉醒",s="在滚岩峡谷深处，萨满祭司摩罗加尔发现了一个名为高戈罗克的沉睡土灵，它被封印在一个共鸣水晶桶中。由于担心这古老的石造生物会给卡利姆多带来破坏性的力量，他派遣一名勇士去击碎水晶桶，趁高戈罗克恢复全部实力之前将其击倒。",h="在滚岩峡谷深处，萨满祭司摩罗加尔发现了一个名为高戈罗克的沉睡土灵，它被封印在一个共鸣水晶桶中。由于担心这古老的石造生物会给卡利姆多带来破坏性的力量，他派遣一名勇士去击碎水晶桶，趁高戈罗克恢复全部实力之前将其击倒。",kw={"滚岩峡谷","土灵","石中沉眠任务","高戈罗克","摩罗加尔","共鸣水晶桶","萨满祭司","石爪山脉"},ang={["class:Shaman"]="摩罗加尔引导萨满力量来操纵共鸣水晶，破坏了保护桶内土灵的元素平衡。",["faction:Horde"]="通过消灭高戈罗克，部落的勇士巩固了他们在石爪山脉险峻岩脊上的立足点，同时也赢得了雷霆崖领袖们长久的尊重。",["race:Tauren"]="石爪山脉是雷霆崖各部族神圣的先祖狩猎地，在其山峰深处中和这个古老的毁灭性实体，保护了这片土地免遭荒废。"},sec={{t="石中沉眠",b="在调查滚岩峡谷的害虫侵扰时，侦察兵在狗头人中发现了一件奇怪的遗物：一个散发着超自然力量的共鸣水晶桶。摩罗加尔，一位驻扎在石爪山脉的牛头人萨满祭司，认出了这个容器的真面目——它是一个囚禁着沉睡土灵高戈罗克的监狱兼庇护所。这些原始的石造生物拥有超过凡人战士的力量，高戈罗克一旦重获自由，将对该地区构成生存威胁。"},{t="共鸣水晶",b="唤醒全盛时期的土灵对石爪山脉来说将是灾难性的。为了扭转局势，摩罗加尔改变了他所获得的共鸣水晶的混合比例，并向其中注入了萨满魔法。这种魔化共鸣水晶旨在以足够的力度击碎共鸣水晶桶，从而在高戈罗克极度虚弱的状态下将其震醒。部落的战士必须击碎容器，在泰坦造物从数百年的沉睡中清醒过来之前将其击倒。"}},faq={{q="摩罗加尔是谁？",a="摩罗加尔是一位驻扎在石爪山脉的牛头人萨满祭司。他研究该地区的异常现象，并利用他的元素魔法来评估当地害虫挖掘出的奇异古代文物和威胁。",al={"摩罗加尔","任务给予者是谁","兽人萨满摩罗加尔"}},{q="什么是土灵？",a="土灵是古代由活石锻造而成的生物，是泰坦在世界黎明时期留下的造物。它们与大地有着深厚的联系，并拥有惊人的体魄，数千年来一直沉睡在卡利姆多和东部王国的地下。",al={"什么是土灵","土灵背景知识","土灵是什么人"}},{q="摩罗加尔为什么要杀死高戈罗克？",a="摩罗加尔担心，一个活跃的土灵所拥有的无与伦比的力量会给石爪山脉和整个卡利姆多带来灾难。由于这种原始生物不可预测且力量强大，他认为在高戈罗克沉睡后的虚弱状态下将其消灭，是保护这片土地的唯一方法。",al={"为什么要杀死高戈罗克","高戈罗克是邪恶的吗","为什么要击杀土灵"}},{q="高戈罗克在哪里？",a="高戈罗克被封印在位于石爪山脉东南部的滚岩峡谷的洞穴深处的一个共鸣水晶桶中，周围环绕着在那挖掘洞穴的滚岩狗头人。",al={"水晶桶在哪里","高戈罗克的位置","寻找共鸣水晶桶"}},{q="如何唤醒高戈罗克？",a="你需要直接在洞穴中的共鸣水晶桶上使用摩罗加尔提供的魔化共鸣水晶。这种经过魔法改造的水晶会使容器破裂，迫使沉睡的土灵现身。",al={"如何召唤高戈罗克","使用魔化共鸣水晶","打开水晶桶"}},{q="击杀高戈罗克后会发生什么？",a="带着高戈罗克死亡的消息回到摩罗加尔那里，可以缓解这位萨满祭司深沉的忧虑。他将你视为英雄，你的事迹避免了一场巨大的灾难，这为你赢得了雷霆崖牛头人中崇高的荣誉和地位。",al={"任务奖励剧情","摩罗加尔的反应","提交任务石中沉眠"}}},fp="13,240,18.369.0,20.369.1,17.197.0,19.223.0,38.193.0,26.172.0,27.179.0,37.204.1"}
P.entries["quest:6482"] = {n="鲁尔的自由",s="在灰谷北部，Ruul 被关在 Thistlefur Hold 深处的一座牢笼里。他需要一位部落盟友助他杀出这座被腐化的熊怪巢穴，抵达安全之地。",h="在灰谷北部，Ruul 被关在 Thistlefur Hold 深处的一座牢笼里。他需要一位部落盟友助他杀出这座被腐化的熊怪巢穴，抵达安全之地。",kw={"灰谷","德鲁伊护送","熊怪","碎木岗哨","thistlefur hold","雅玛·雪蹄"},ang={["class:Druid"]="鲁尔的被捕是一个令人谦卑的提醒，告诫人们以动物伪装在野性领地徘徊的风险，因为在那里的腐化生物无法分辨谁是朋友，谁是猎物。",["faction:Horde"]="从灰谷北部腐化的空洞中救出的每一个灵魂，都在加强部落在碎木岗哨那摇摇欲坠的据点。",["race:Tauren"]="拯救一名塞纳里奥议会的被困兄弟，并平息他在碎木岗哨亲人的忧虑，这既是对大地母亲的尊崇，也是对部落情谊的践行。"},sec={{t="枷锁中的德鲁伊",b="当德鲁伊鲁尔·雪蹄在灰谷北部的腐化森林中冒险时，他以熊形态徘徊到了离Thistlefur Hold太近的地方。那些失去祖先智慧并受野性偏执驱使的腐化熊怪，误以为这位变形的牛头人只是一头普通的野兽。它们不仅没有对他保持敬畏，反而将他关进笼子里并让他挨饿，耗尽了他的魔法储备，使他无法独自脱身。"},{t="逃离巢穴",b="由于饥饿和囚禁而虚弱不堪，鲁尔无法变形或在没有帮助的情况下从熊怪巢穴中杀出重围。一旦被部落的盟友救出，他便依赖援救者清理出一条道路，以通过成群的敌对Thistlefur熊怪。在安全抵达碎木岗哨郊外后，他短暂地显露出牛头人的真身，表达了衷心的感谢，随后便回到荒野中去睡觉以消除疲劳。"}},faq={{q="为什么鲁尔·雪蹄会被熊怪关起来？",a="鲁尔当时正以熊的形态探索森林。腐化的Thistlefur熊怪没能认出他是一位德鲁伊，误以为他是一头野兽，便将他关进笼子里，让他挨饿，直到他没有力气逃跑。",al={"为什么鲁尔被困","鲁尔是如何被捕的","为什么被关在笼子里"}},{q="雅玛·雪蹄是谁？",a="雅玛·雪蹄是鲁尔的妹妹，驻扎在灰谷的碎木岗哨。几天前鲁尔进入森林后便没了音讯，她为此深感担忧。",al={"鲁尔的妹妹","碎木岗哨的雅玛","雅玛是谁"}},{q="为什么鲁尔不能直接变回人形逃走？",a="长期的囚禁和Thistlefur熊怪蓄意的虐待让他饥肠辘辘，鲁尔变得极度虚弱。由于缺乏食物和体力，他体内的自然能量储备完全耗尽，直到获救前都束手无策。",al={"为什么鲁尔没有变身","德鲁伊熊形态陷阱"}},{q="鲁尔到达安全地带后会发生什么？",a="一旦被护送出充满敌意的巢穴并到达碎木岗哨的边缘，鲁尔会短暂地变回牛头人的自然形态以表达感激之情，随后变回熊的形态，去寻找一个安静的地方睡觉和恢复体力。",al={"鲁尔去哪里了","鲁尔结局"}},{q="灰谷里的所有熊怪都像Thistlefur熊怪一样敌对吗？",a="不。虽然许多熊怪部族拥有高贵的传承和与自然的深厚联系，但灰谷北部的Thistlefur部族已经屈服于黑暗的腐化力量，变得具有攻击性且难以预料。",al={"熊怪是邪恶的吗","thistlefur腐化"}},{q="救援在哪里进行？",a="鲁尔被关押在Thistlefur Hold内部，这是一个位于灰谷碎木岗哨西北方山区和阿斯特兰纳北部的熊怪巢穴。",al={"鲁尔在哪里","鲁尔·雪蹄位置"}}},fx={cd4f3bf3={q="鲁尔·雪蹄为什么需要你护送，而不是自己逃出去？",a="鲁尔被困在一座刺毛熊怪的牢笼里已有数日，遭受堕落的熊怪囚禁并忍受饥饿。他的体力几乎耗尽。他虚弱不堪、营养不良，又身陷敌对的刺毛熊怪巢穴深处，无法独自杀出周围部族的包围，只能依靠你为他开辟一条自由之路。",al={"鲁尔为什么需要帮助","鲁尔为什么不能独自逃走","为什么让我找鲁尔·雪蹄"}}},fp="15,164,17.433.0,19.421.1,48.238.0,21.176.1,56.235.0,39.229.1,59.215.0,33.145.0"}
P.entries["quest:65"] = {n="迪菲亚兄弟会",s="这一差事标志着揭开恐怖统治西部荒野的秘密辛迪加面纱的第一步。受哨兵岭的格里安·斯托曼派遣，旅行者被指引向东进入赤脊山，去咨询一位可能知道窃贼藏身之处的线人。",h="这一差事标志着揭开恐怖统治西部荒野的秘密辛迪加面纱的第一步。受哨兵岭的格里安·斯托曼派遣，旅行者被指引向东进入赤脊山，去咨询一位可能知道窃贼藏身之处的线人。",kw={"迪菲亚","格里安·斯托曼","湖畔镇","赤脊山","哨兵岭","西部荒野","黑衣威利"},ang={["class:Rogue"]="斯托曼认识到正规军无法瓦解一个犯罪集团；这需要一个了解阴影和街头交易的人，这直接指向了黑衣威利。",["faction:Alliance"]="从西部荒野到赤脊山的漫长旅程凸显了在首都漠不关心的情况下，暴风城的外围领地必须多么依赖彼此。"},sec={{t="尘土中的威胁",b="西部荒野已沦为废墟，农作物被洗劫一空，且到处都是戴着红色头巾的强盗。格里安·斯托曼和人民民兵团在哨兵岭抵御着近乎不断的骚扰，但他们是在盲目作战。斯托曼意识到，如果不找到这个卡特尔的核心圈子并查明幕后主使，仅靠砍杀零散的劫匪永远无法拯救这片地区。"},{t="外地的线人",b="斯托曼没有依赖官方军事渠道或暴风城那些缺位的贵族，而是动用了他的人情债。他派遣值得信任的冒险者穿过艾尔文森林进入赤脊山。在宁静的湖畔镇，潜伏在当地旅店二楼的是一名叫黑衣威利的潜行者。比起任何民兵队长，威利更了解地下世界，他是揭开迪菲亚潜行者藏身处的第一条线索。"}},faq={{q="格里安·斯托曼是谁？",a="格里安·斯托曼是人民民兵团的领袖，这是一支驻扎在西部荒野哨兵岭的乌合之众般的防御力量。由于暴风城忽视了边境地区，他负责协调剩余少数当地农民和难民的防御工作。",al={"格里安·斯托曼","谁发布了这个任务","西部荒野任务发布者"}},{q="斯托曼为什么要让你去湖畔镇？",a="人民民兵团在西部荒野内部缺乏地下线人。斯托曼动用了以前欠下的人情，要求湖畔镇旅店里的潜行者黑衣威利帮忙，希望通过地下情报网揭露谁是窃贼的头目。",al={"为什么去湖畔镇","为什么要前往赤脊山","为什么找威利"}},{q="黑衣威利是谁？",a="黑衣威利是一名潜行者，住在赤脊山的湖畔镇旅店二楼。他欠格里安·斯托曼一个人情，这使他成为传递地下传闻和犯罪消息的有用渠道。",al={"威利是谁","威利 湖畔镇","黑衣威利"}},{q="什么是迪菲亚潜行者？",a="迪菲亚潜行者是一个戴着红色面具的冷酷犯罪卡特尔，他们夺取了西部荒野的农场、道路和废弃矿井的控制权，正积极驱逐定居者并挑战暴风城的权威。",al={"迪菲亚潜行者","什么是迪菲亚","红头巾强盗"}},{q="我在湖畔镇哪里可以找到威利？",a="黑衣威利位于赤脊山湖畔镇大桥附近的湖畔镇旅店二楼。",al={"威利在哪里","寻找威利","威利位置"}},{q="这个任务需要战斗吗？",a="不需要。最初的这一步纯粹是信息收集。你只需从西部荒野的哨兵岭出发，穿过艾尔文森林前往湖畔镇的旅店与威利取得联系。",al={"这个任务难吗","迪菲亚潜行者任务有战斗吗","敌人"}}},fx={e3561313={q="格里安·斯托曼为什么需要冒险者，而不派自己的人民军？",a="格里安·斯托曼麾下的人民军光是守卫哨兵岭、保护西部荒野仅存的农民，就已经疲于奔命。暴风城拒绝派遣王室援军，当地守军因此严重缺员。此外，斯托曼特别需要一名能秘密潜入的外来者，而当地民兵的面孔太熟，立刻就会被迪菲亚的哨兵认出来。",al={"为什么派我去","为什么不派民兵","斯托曼 为什么需要冒险者"}}},fp="22,127,22.168.0,22.188.0,25.219.0,43.215.0,23.194.0,31.179.0,36.130.0,35.102.0"}
P.entries["quest:6503"] = {n="灰谷先驱者",s="“灰谷斥候”是库莱比在灰谷发布的一项部落巡逻拦截任务。暗夜精灵侦察兵从银翼哨站四散而出，搜集附近部落营地的情报，这促使部落发动先发制人的打击，以隐藏哨站的防御状况。通过猎杀这些潜行的侦察兵，部落可以使当地的联盟部队失去耳目，并遏制其未来的入侵企图。",h="“灰谷斥候”是库莱比在灰谷发布的一项部落巡逻拦截任务。暗夜精灵侦察兵从银翼哨站四散而出，搜集附近部落营地的情报，这促使部落发动先发制人的打击，以隐藏哨站的防御状况。通过猎杀这些潜行的侦察兵，部落可以使当地的联盟部队失去耳...",kw={"联盟","灰谷","灰谷斥候","部落","库莱比","暗夜精灵侦察兵","银翼哨站"},ang={["class:Hunter"]="在深邃的林地地形中追踪隐蔽的斥候，依靠的是敏锐的直觉、强化的追踪感官和精准的箭术。",["class:Rogue"]="消灭敌方斥候可以扭转暗夜精灵的隐身优势，确保部落的渗透者能掌控森林阴影中的主动权。",["faction:Horde"]="在灰谷中每消灭一个暗夜精灵侦察兵，都能保护当地营地和伐木作业免受联盟协同反攻的威胁。"},sec={{t="林冠之眼",b="灰谷的森林依然是一片竞争激烈的边境，每一条小径和山脊都受到严密的监视。情报如同战斧一般致命，传给库莱比的报告证实，被称为“灰谷斥候”的暗夜精灵侦察兵已经从联盟位于银翼哨站的据点溜了出来。这些侦察兵在基地以东、当地部落据点以南的茂密荒野中活动，他们在林间小径潜行，以绘制防御工事图并追踪部队动向。"},{t="致盲联盟",b="为了防止有组织的突袭，部落必须在敌方侦察兵返回基地前将其消灭。通过猎杀这些斥候，部落勇士可以阻止银翼哨站的指挥官获得有关部队兵力和哨站外围防御的重要情报。失去了前进的耳目，暗夜精灵将变得不知所措，在穿越这片争议林区时也会减少采取激进战术的意愿。"}},faq={{q="谁发布了“灰谷斥候”这个任务？",a="该任务由驻扎在灰谷的部落侦察协调员库莱比发布，他致力于追踪并反制暗夜精灵在森林各处的行动。",al={"任务发布者","谁发布任务","库莱比任务"}},{q="灰谷斥候位于何处？",a="这些斥候在银翼哨站以东、库莱比营地以南的森林中徘徊，在灌木丛中巡逻以搜集情报。",al={"斥候位置","斥候在哪里","去哪里找斥候"}},{q="为什么斥候对部落构成威胁？",a="这些斥候是从银翼哨站出发的先遣侦察兵。如果他们成功绘制了部落营地和部队兵力的地图，联盟就能针对薄弱位置协调进行精确突袭。",al={"为什么要杀斥候","斥候的威胁","斥候的目的"}},{q="什么是银翼哨站？",a="银翼哨站是暗夜精灵在灰谷的重要军事设施，作为联盟部队保卫森林和对抗部落扩张的前线基地。",al={"银翼哨站背景","什么是银翼哨站","银翼联盟"}},{q="这个任务是更长故事线的一部分吗？",a="此任务主要是一项独立的战术任务，旨在减少该区域的联盟侦察活动，奖励那些协助库莱比巩固周边防线的战士。",al={"任务链","后续任务","斥候任务链"}},{q="联盟玩家可以完成这个任务吗？",a="不可以，此任务仅限部落玩家。库莱比完全是代表部落在灰谷的前线利益行事。",al={"这是部落专属吗","联盟版本","联盟能做这个吗"}}},fp="20,189,20.332.0,21.325.0,41.141.0,43.140.0,45.183.0,27.172.0,41.144.0,41.66.0"}
P.entries["quest:6504"] = {n="丢失的书页",s="在将一台刚从棘齿城买来的地精伐木机运往战歌伐木营地的途中，兽人古尔达·怒痕因为一阵突如其来的大风弄丢了机器的操作手册。她现在被困在碎木岗哨附近，如果不找回这些散落的书页，她根本无法操作这台复杂的工程奇迹。",h="在将一台刚从棘齿城买来的地精伐木机运往战歌伐木营地的途中，兽人古尔达·怒痕因为一阵突如其来的大风弄丢了机器的操作手册。她现在被困在碎木岗哨附近，如果不找回这些散落的书页，她根本无法操作这台复杂的工程奇迹。",kw={"灰谷","古尔达·怒痕","棘齿城","伐木机","伐木机操作手册","碎木岗哨","丢失的书页","战歌伐木营地"},ang={["faction:Horde"]="每一台运抵战歌伐木营地的伐木机，都能加快采集珍贵木材的速度，这些木材是杜隆塔尔建设围墙、小屋和战舰所必需的。",["profession:Engineering"]="工匠们会对古尔达的困境感同身受：在没有制造商指南的情况下驾驶地精制造的伐木机，很容易导致锅炉灾难性地损坏。",["race:Orc"]="体力劳动和战士传统使得人们对繁琐的地精文书工作缺乏耐心，这让古尔达因为丢失技术手册而感到懊恼显得非常真实。"},sec={{t="倒霉的一阵风",b="战歌氏族主要依靠从棘齿城港口的地精那里购买的蒸汽伐木机来清除灰谷的树木。对于普通的兽人战士来说，操作这些精巧又吵闹的装置绝非易事。当古尔达·怒痕带着一台刚买来的伐木机向北行进时，一阵突如其来的狂风从她手中卷走了说明书，十二页脆弱的羊皮纸散落在森林的地面上。"},{t="荒野中的书页",b="由于狂风将手册吹过了树冠，散落的书页散布到了整个地区，落入了游荡的生物、邪教徒和森林居民的手中。如果无法集齐这三个章节，这台复杂的机器就只是一堆静止的钢铁和旋转的锯片，古尔达也只能被困在前往碎木岗哨的路上，无法去伐木营地报到。"}},faq={{q="古尔达·怒痕是谁？",a="古尔达·怒痕是一位部落劳工，她的任务是将一台地精伐木机从棘齿城商港运送到灰谷，加入战歌伐木营地的伐木工作。",al={"古尔达","怒痕","任务发布者是谁"}},{q="为什么古尔达需要说明书才能驾驶伐木机？",a="地精工程学以挑剔和反直觉著称，依赖于不稳定的锅炉、复杂的压力阀和精密的杠杆。即使是一个急切的兽人，如果不阅读制造商的手册，也无法安全地操作这种装置。",al={"为什么需要说明书","为什么她无法驾驶伐木机","伐木机操作手册"}},{q="手册的书页是怎么散落在灰谷各处的？",a="在沿森林道路向北行驶时，一阵猛烈的狂风将书从古尔达的手中吹走。散乱的书页在树林中四散飘落，只剩下空荡荡的封皮还抓在她手里。",al={"书页是如何丢失的","风吹散了书页"}},{q="伐木机最终要去哪里？",a="这台机器的目的地是战歌伐木营地，部落在那里开展了大规模的砍伐行动，为奥格瑞玛和杜隆塔尔提供木材。",al={"伐木机要去哪里","战歌伐木机的目的地"}},{q="在哪里可以找到丢失的书页？",a="狂风将书页吹得到处都是，它们已经被在灰谷各处游荡的各种人形生物和敌对森林生物捡走了。",al={"去哪里寻找书页","谁会掉落书页"}},{q="部落为什么要从棘齿城购买机械？",a="棘齿城是最近的中立港口，拥有与地精贸易财阀相连的活跃贸易网络。部落经常购买专业的工程设备、爆破工具和蒸汽驱动的车辆来加强其军事后勤。",al={"部落的地精机械","棘齿城的部落贸易"}}},fp="14,213,18.331.0,23.258.0,22.130.0,64.132.0,61.182.0,42.111.0,37.118.0,51.189.0"}
P.entries["quest:651"] = {n="禁锢之石",s="在“公主被困”任务完成后，来自虹色碎片的一个声音讲述了分散在阿拉希的四块缚灵石，它们将它镇压在地下。其中最强大的那一块——内缚灵石，只有使用从其他三块石头上取得的钥匙才能解锁。",h="在“公主被困”任务完成后，来自虹色碎片的一个声音讲述了分散在阿拉希的四块缚灵石，它们将它镇压在地下。其中最强大的那一块——内缚灵石，只有使用从其他三块石头上取得的钥匙才能解锁。",kw={"阿拉希高地","烈焰钥匙","海浪钥匙","虹色碎片","米兹拉尔","内缚灵石","缚灵石","雷霆钥匙"},sec={{t="四块缚灵石",b="那个声音讲述了分散在阿拉希的四块缚灵石，它们将它镇压在地下。若要松动它们，必须首先解锁最强大的一块：内缚灵石，它需要从其他三块——西缚灵石、东缚灵石和外缚灵石上收集的钥匙。这些钥匙分别是烈焰钥匙、海浪钥匙和雷霆钥匙。守护者们看守着这些石头，但聪明或幸运的人或许能找到驱逐它们的方法。收集齐钥匙后，便可将其带到内缚灵石处。"},{t="在内缚灵石处",b="这块石头传出了米兹拉尔的声音：缚灵石已被打开，枷锁正在松动，自由已近在咫尺。米兹拉尔称赞你是高尚的拯救者。"}},faq={{q="这一步来自哪里？",a="它来自虹色碎片，是在完成“公主被困”之后。",al={"缚灵石任务发布者","谁发布缚灵石任务","如何开始缚灵石任务"}},{q="四块缚灵石分别是什么？",a="西缚灵石、东缚灵石、外缚灵石，以及最强大的内缚灵石。",al={"哪些是缚灵石","阿拉希缚灵石","四块石头"}},{q="解锁内缚灵石需要哪些钥匙？",a="烈焰钥匙、海浪钥匙和雷霆钥匙，分别从西、东和外缚灵石处收集。",al={"缚灵钥匙","需要什么钥匙","内缚灵石的钥匙"}},{q="谁在看守缚灵石？",a="守护者们在看守着这些石头，不过聪明或幸运的冒险者也许能找到驱逐它们的方法。",al={"石头守护者","谁在看守石头","缚灵石保卫者"}},{q="钥匙必须送到哪里？",a="送到内缚灵石处，这是其中最强大的一块，必须先解锁它，其他石头才会打开。",al={"我该把钥匙带去哪里","交付缚灵石任务","内缚灵石位置"}}},fp="17,159,11.387.0,18.163.1,31.83.0,36.140.0,48.118.0,30.99.0,33.115.0"}
P.entries["quest:652"] = {n="打开钥匙之石",s="一旦束缚之石被开启，那个声音的禁锢便缓解了许多，但仍有一道锁将其困住。那道锁就是石环中的基石，而那个声音的囚禁者之一，岩石看守者弗兹鲁克，持有这把钥匙。看守者们称其为秩序魔棒。",h="一旦束缚之石被开启，那个声音的禁锢便缓解了许多，但仍有一道锁将其困住。那道锁就是石环中的基石，而那个声音的囚禁者之一，岩石看守者弗兹鲁克，持有这把钥匙。看守者们称其为秩序魔棒。",kw={"阿拉希高地","弗兹鲁克","基石","秩序魔棒","内在束缚之石","岩石看守者"},sec={{t="最后的锁",b="随着束缚之石被开启，那个声音的禁锢已经大大缓解，但仍有一道锁未解：基石，位于你周围的石环之中。它的钥匙由一名囚禁者持有，即岩石看守者弗兹鲁克，看守者们称之为秩序魔棒。从弗兹鲁克手中夺取魔棒并将其带到基石处，这道锁就会被解开。那个声音承诺，如果你能做到这一点，它的感激之情将震动大地的根基。基石本身充盈着巨大的地脉能量。"},{t="在基石处",b="当魔棒被插入基石时，你的脚下传来一阵颤动。"}},faq={{q="这一步之前要做什么？",a="首先是束缚之石，开启那些石头减轻了那个声音的大部分禁锢。",al={"前置条件","前置任务","束缚之石前置条件"}},{q="弗兹鲁克是谁？",a="弗兹鲁克是一位岩石看守者，也是那个声音的囚禁者之一，他持有基石的钥匙。",al={"弗兹鲁克是谁","弗兹鲁克背景故事","岩石看守者弗兹鲁克"}},{q="什么是秩序魔棒？",a="这是岩石看守者对基石钥匙的称呼，由弗兹鲁克持有。",al={"秩序魔棒","什么是秩序魔棒","基石钥匙"}},{q="基石在哪里？",a="基石矗立在阿拉希高地的一处石环之中。",al={"破碎基石在哪里","基石位置","阿拉希石环"}}},fp="21,170,13.399.0,15.66.1,28.85.0,14.91.0,25.82.0,22.67.0"}
P.entries["quest:6521"] = {n="An Unholy Alliance",s="瓦里玛萨斯派你前往剃刀高地外，迎战Ambassador Malcin。这名使者的出现，或许能解释部分quilboar为何力量异常强大，并显露出瘟疫的迹象。",h="瓦里玛萨斯派你前往剃刀高地外，迎战Ambassador Malcin。这名使者的出现，或许能解释部分quilboar为何力量异常强大，并显露出瘟疫的迹象。",kw={"ambassador malcin","邪恶同盟","巫妖王","瘟疫","quilboar","剃刀高地","幽暗城","瓦里玛萨斯"},sec={{t="使者",b="瓦里玛萨斯在幽暗城等着你，并交给你一项任务。剃刀高地外的Ambassador Malcin，或许能解释部分quilboar为何力量大增，还显露出瘟疫的迹象。瓦里玛萨斯称，在巫妖王眼中，这名使者的任务已经失败，并要求你杀了他。"}},faq={{q="是谁要我去找Malcin？",a="幽暗城的瓦里玛萨斯要你去剃刀高地外寻找Ambassador Malcin。",al={"谁派我去","瓦里玛萨斯的要求"}},{q="Ambassador Malcin是谁？",a="Ambassador Malcin是剃刀高地外的一名使者。他的出现或许能解释部分quilboar为何力量异常强大，并显露出瘟疫的迹象。",al={"malcin是谁","ambassador malcin"}},{q="瓦里玛萨斯为何要杀Malcin？",a="瓦里玛萨斯说，在巫妖王眼中，Malcin的任务已经失败。",al={"为何杀malcin","malcin的任务"}},{q="quilboar身上发生了什么？",a="部分quilboar的力量变得异常强大，还以自己的方式显露出瘟疫的迹象。",al={"quilboar瘟疫","quilboar为何力量强大"}},{q="Malcin在哪里？",a="瓦里玛萨斯说，Ambassador Malcin在剃刀高地外。",al={"malcin的位置","寻找malcin"}},{q="瓦里玛萨斯要我带回什么？",a="瓦里玛萨斯要你把Ambassador Malcin的头带回幽暗城交给他。",al={"malcin的头","带什么给瓦里玛萨斯"}}},fp="18,167,9.286.0,32.87.0,25.138.0,38.71.0,34.90.0,16.61.0,43.76.0"}
P.entries["quest:6522"] = {n="邪恶的盟友",s="一卷小卷轴是要交给幽暗城的瓦里玛萨斯的。你正带着它去找他。",h="一卷小卷轴是要交给幽暗城的瓦里玛萨斯的。你正带着它去找他。",kw={"an unholy alliance","事务","小卷轴","幽暗城","瓦里玛萨斯"},sec={{t="面见瓦里玛萨斯",b="瓦里玛萨斯在幽暗城等着听你此行所为何事。小卷轴就在你手中，他认为你要谈的事必定很重要。"}},faq={{q="这卷轴是给谁的？",a="这卷小卷轴是要交给幽暗城的瓦里玛萨斯的。",al={"卷轴是给谁的","谁收卷轴"}},{q="我该把这卷小卷轴送到哪里？",a="把这卷小卷轴交给幽暗城的瓦里玛萨斯。",al={"卷轴送到哪里","把卷轴送到哪里"}},{q="瓦里玛萨斯想听什么事？",a="瓦里玛萨斯询问你想谈些什么。",al={"什么事","告诉瓦里玛萨斯什么"}}},fp="18,85,18.147.0,22.59.0,33.54.0,41.52.0"}
P.entries["quest:6523"] = {n="保护卡雅",s="“保护卡雅”是一个位于石爪山脉的部落护送任务。在发现卡雅·扁蹄被敌对的恐怖图腾牛头人俘虏后，冒险者将指引她穿过危险的山路，抵达阿帕拉耶营地。带回她幸存的消息，会让她焦急的父亲玛卡巴·扁蹄感到无比宽慰。",h="“保护卡雅”是一个位于石爪山脉的部落护送任务。在发现卡雅·扁蹄被敌对的恐怖图腾牛头人俘虏后，冒险者将指引她穿过危险的山路，抵达阿帕拉耶营地。带回她幸存的消息，会让她焦急的父亲玛卡巴·扁蹄感到无比宽慰。",kw={"阿帕拉耶营地","护送","恐怖图腾","卡雅·扁蹄","玛卡巴·扁蹄","保护卡雅","石爪山脉","牛头人"},ang={["faction:Horde"]="确保旅行家庭的安全可以巩固部落在石爪山脉来之不易的立足点和补给路线。",["race:Tauren"]="营救卡雅直接帮助了因恐怖图腾氏族的侵略行径而分崩离析的同胞。"},sec={{t="岩架上的囚徒",b="石爪山脉中弥漫着牛头人之间激烈的竞争，其中最尖锐的矛盾莫过于针对奸诈的恐怖图腾氏族的紧张局势。卡雅·扁蹄在敌对领地的深处被俘并遭到囚禁。徒步逃离需要穿过蜿蜒的小径，那里既有伺机而动的捕食者，又有警惕的敌人，因此武装护送是她能抵达安全地带的唯一现实希望。"},{t="前往阿帕拉耶营地",b="阿帕拉耶营地位于石爪山脉东部，卡雅知道从那里回家的路。她的目标是那个营地，并确信一旦抵达那里，她就能找到回家的路。护送她通过充满伏击的路径，可以确保她在抓捕者意识到她溜走之前避免再次被俘。"},{t="父亲的宽慰",b="玛卡巴·扁蹄在石爪山脉东南部边界等待消息，他非常担心失踪女儿的安危。当信使带来卡雅已安全抵达阿帕拉耶营地的确切消息时，玛卡巴的绝望转变成了对那些在他孩子与绑架者之间筑起防线的英雄们的无尽感激。"}},faq={{q="卡雅·扁蹄是谁？",a="卡雅·扁蹄是一位年轻的牛头人，在石爪山脉被敌对的恐怖图腾势力俘虏。她依靠路过的部落冒险者将她解救出来，并护送至安全地带。",al={"卡雅是谁","卡雅·扁蹄背景故事","卡雅"}},{q="卡雅需要被护送到哪里？",a="卡雅必须被安全地护送穿过通往石爪山脉东部阿帕拉耶营地的小径，从那里她知道回家的路。",al={"卡雅护送目的地","要把卡雅带到哪里","卡雅去哪里"}},{q="玛卡巴·扁蹄是谁？",a="玛卡巴·扁蹄是卡雅的父亲，焦急地等待在石爪山脉的东南部入口处。在冒险者带回她获救的消息之前，他一直为失踪的孩子感到绝望。",al={"玛卡巴是谁","玛卡巴·扁蹄背景故事","卡雅的父亲"}},{q="是谁俘虏了卡雅？",a="卡雅是被敌对的恐怖图腾牛头人俘虏的，他们在石爪山脉的岩架上设有营地并进行伏击。",al={"谁抓了卡雅","谁绑架了卡雅","卡雅的绑架者"}},{q="卡雅抵达阿帕拉耶营地后会发生什么？",a="一旦卡雅抵达阿帕拉耶营地，她就能找到回家的路，而玩家的任务是回到玛卡巴·扁蹄身边，传递她幸存下来的喜讯。",al={"保护卡雅之后","护送之后做什么","保护卡雅后续"}},{q="联盟玩家可以接这个任务吗？",a="不能。扁蹄家族属于热爱和平的牛头人，他们效忠于部落，因此这项救援任务仅限部落冒险者。",al={"联盟能做保护卡雅吗","卡雅是部落专属吗"}}},fp="12,224,22.345.0,22.228.0,17.265.1,21.180.0,36.129.0,23.198.0,18.100.0,45.137.0,44.120.0"}
P.entries["quest:653"] = {n="密斯莱尔的盟友",s="密斯莱尔大喊着她自由了，并且说她会躲起来积蓄力量以避开她的囚禁者。她称你为高尚的盟友，并让你去找位于铁炉堡荒弃的洞穴里的一家商店中的葛利·硬骨，他知道如何召唤她。",h="密斯莱尔大喊着她自由了，并且说她会躲起来积蓄力量以避开她的囚禁者。她称你为高尚的盟友，并让你去找位于铁炉堡荒弃的洞穴里的一家商店中的葛利·硬骨，他知道如何召唤她。",kw={"阿拉希高地","荒弃的洞穴","葛利·硬骨","巨人","铁炉堡","基石","密斯莱尔"},sec={{t="重获自由积蓄力量",b="密斯莱尔自由了，她打算躲起来积蓄力量，避开她的囚禁者，因为如果现在与他们相遇，她肯定会被再次击败并囚禁起来。终有一天她要面对那些巨人，她发誓他们会后悔曾经囚禁过她。她称你为高尚的盟友，并说她会再次需要你的帮助，在她准备好时将她召唤到地表。"},{t="给葛利·硬骨的消息",b="密斯莱尔让你去和葛利·硬骨交谈，他的商店位于铁炉堡的荒弃的洞穴。他知道该如何召唤她。"}},faq={{q="在哪里可以找到葛利·硬骨？",a="葛利·硬骨在铁炉堡的荒弃的洞穴开了一家店。",al={"葛利·硬骨位置","葛利·硬骨在哪里","寻找葛利·硬骨"}},{q="为什么密斯莱尔要躲起来？",a="她需要先积蓄力量。如果她的囚禁者现在就面对她，她肯定会被再次击败并囚禁起来。",al={"为什么密斯莱尔要躲藏","密斯莱尔要去哪里"}},{q="密斯莱尔提到的囚禁者是谁？",a="是那些曾经监管她的巨人。她说终有一天她会去面对他们，他们会为此感到后悔。",al={"密斯莱尔的囚禁者","谁囚禁了密斯莱尔","密斯莱尔和巨人"}},{q="为什么密斯莱尔让你去铁炉堡？",a="葛利·硬骨知道如何召唤她，她说当她准备好时，需要你把她召唤到地表。",al={"为什么去铁炉堡","拜访葛利的目的"}}},fp="16,213,23.331.0,24.110.0,35.59.0,35.114.0,38.124.0,39.150.0"}
P.entries["quest:654"] = {n="塔纳利斯的样本",s="开启电源后，野外测试工具包开始发光并振动。你现在有两个小时的时间来收集塔纳利斯的沙漠产物，否则数据就会丢失。",h="开启电源后，野外测试工具包开始发光并振动。你现在有两个小时的时间来收集塔纳利斯的沙漠产物，否则数据就会丢失。",kw={"蜥蜴","比格维兹","野外测试工具包","加基森","鬣狗","电源","蝎子","塔纳利斯","水业公司"},sec={{t="滴答作响的电源",b="电源启动后，工具包开始发光并振动，看起来一切运行正常。首席工程师沙克斯·比格维兹说，你需要在两小时内从塔纳利斯沙漠收集到足够的数据：从八只蜥蜴、八只鬣狗和八只蝎子身上采集的合格样本。如果时间耗尽，所有的东西都会丢失，你必须从比格维兹那里重新购买电源。在电量耗尽前，必须将该工具包带回加基森交给比格维兹。"},{t="公司的利润",b="对于任何工具包没电的人，比格维兹都不会表示同情。他唯一关心的就是加基森水业公司能赚多少钱。比格维兹愿意一直出售电源，直到公司有能力从丹莫罗的冰泉进口水源。"}},faq={{q="测试工具包需要采集哪些生物的样本？",a="从塔纳利斯沙漠的八只蜥蜴、八只鬣狗和八只蝎子身上采集的合格样本。",al={"需要测试哪些动物","样本采集目标","需要击杀什么"}},{q="完成样本采集有多少时间？",a="从电源开启的那一刻起，你有两个小时的时间。",al={"时间限制","我有多少时间","计时器"}},{q="如果电源耗尽会发生什么？",a="工具包里的一切都会损毁，你必须从加基森的首席工程师沙克斯·比格维兹那里重新购买一个电源才能重新开始。",al={"如果计时器时间到了","任务失败","电源耗尽"}},{q="装满后的测试工具包要送到哪里？",a="在电量耗尽前，送到加基森的首席工程师沙克斯·比格维兹那里。",al={"我该交给谁","交任务地点","比格维兹在哪里"}},{q="为什么比格维兹要一直出售电源？",a="比格维兹希望加基森水业公司能盈利，即使这意味着要通过出售电源来维持，直到公司有能力从丹莫罗的冰泉进口水源。",al={"比格维兹的目标","加基森水业公司的目标","为什么要采集样本"}}},fp="22,120,22.403.0,20.237.0,54.89.0,52.67.0,42.120.0,40.99.0,49.164.0"}
P.entries["quest:6541"] = {n="向卡德拉克报到",s="十字路口的索克指引有能力的部落战士前往灰谷边境附近的卡德拉克岗哨。卡德拉克负责协调部落向这座古老森林的扩张，并让新来的招募者为前方的持续冲突做好准备。",h="十字路口的索克指引有能力的部落战士前往灰谷边境附近的卡德拉克岗哨。卡德拉克负责协调部落向这座古老森林的扩张，并让新来的招募者为前方的持续冲突做好准备。",kw={"灰谷","贫瘠之地","十字路口","卡德拉克","碎木岗哨","索克","岗哨","佐拉姆海岸"},ang={["faction:Horde"]="这份调令标志着从保卫贫瘠之地已定居领土到确保北方争议森林中重要资源生命线的转变。",["race:Orc"]="灰谷是兽人至关重要的试炼场，确保了加固奥格瑞玛并在卡利姆多建立永久家园所需的木材。"},sec={{t="通往北方之路",b="当十字路口忙于应对野猪人、半人马和当地强盗时，部落更广泛的领土利益着眼于北方的灰谷茂密森林。索克充当中间人，将那些在贫瘠之地中部证明了自己的老练战士引导至卡德拉克驻守的北部边境岗哨。"},{t="边境战略",b="卡德拉克负责监管通往灰谷的南部路径，组织增援部队以巩固部落在边境线上的立足点。随着碎木岗哨和佐拉姆海岸前哨站等新营地的建立，部落尽管面临当地暗夜精灵的激烈抵抗，仍在积极巩固其在木材资源丰富的林地中的存在。"}},faq={{q="谁是索克？",a="索克是一名驻扎在贫瘠之地十字路口的兽人军官。他协助协调当地的防御工作，并将有前途的冒险者指派去参与灰谷战役等区域性的战争行动。",al={"索克 十字路口","谁给予向卡德拉克报到的任务","索克 贫瘠之地"}},{q="卡德拉克在哪里？",a="卡德拉克驻扎在贫瘠之地的北部岗哨，就在通往灰谷森林的主干道旁。",al={"卡德拉克位置","卡德拉克在哪里","卡德拉克 岗哨"}},{q="为什么部落要进军灰谷？",a="部落需要木材和资源来建设他们在杜隆塔尔和贫瘠之地的新城市。向灰谷扩张提供了至关重要的木材，尽管这使他们与暗夜精灵陷入了直接冲突。",al={"为什么是灰谷","部落在灰谷","灰谷入侵"}},{q="部落在灰谷建立了哪些前哨站？",a="卡德拉克提到，部落在通往森林的中央道路旁建立了碎木岗哨，并在更西边的佐拉姆海岸建立了另一个前哨站。",al={"部落在灰谷的基地","佐拉姆海岸基地","碎木岗哨"}},{q="向卡德拉克报到后会发生什么？",a="一旦你向卡德拉克报到，他会向你简要说明当地的军事局势，并指派你收集散布在灰谷各处的战歌伐木场哨所的报告。",al={"卡德拉克之后","卡德拉克之后的任务","卡德拉克提供什么"}},{q="除了贫瘠之地，还有其他地方能接到这个任务吗？",a="可以。石爪山脉玛拉卡金的部落战士也会接到一份几乎完全相同的去向卡德拉克报到的征召令。",al={"其他的卡德拉克任务","石爪山脉 卡德拉克任务"}}},fp="16,159,14.255.0,17.286.0,13.174.0,24.90.0,40.190.0,53.128.0,37.154.0,69.129.0"}
P.entries["quest:6542"] = {n="向卡德拉克报到",s="这份军事急报引导部落战士从石爪山脉的玛拉卡金前往位于北贫瘠之地边界的卡德拉克岗哨。这标志着从保卫山崖转为增援部落在灰谷内充满争议的军事行动。通过向卡德拉克报到，士兵们被召集起来支持碎木岗哨和佐拉姆海岸等前哨营地。",h="这份军事急报引导部落战士从石爪山脉的玛拉卡金前往位于北贫瘠之地边界的卡德拉克岗哨。这标志着从保卫山崖转为增援部落在灰谷内充满争议的军事行动。通过向卡德拉克报到，士兵们被召集起来支持碎木岗哨和佐拉姆海岸等前哨营地。",kw={"灰谷","贫瘠之地","达恩·鹰爪","卡德拉克","碎木岗哨","石爪山脉","战歌报告","佐拉姆海岸"},ang={["faction:Horde"]="这道命令将你纳入了酋长更广泛的战争努力中，将边境老兵投入到争夺灰谷资源的积极斗争中。",["race:Orc"]="灰谷战役对于战歌氏族和杜隆塔尔的生存至关重要，这也使卡德拉克的岗哨成为了年轻兽人战士的试炼场。",["race:Tauren"]="像兽人达恩·鹰爪这样的部落哨兵引导旅行者安全地穿越山区边界，保持了血蹄领地与酋长北方战线之间的通讯畅通。"},sec={{t="北方战线的征召",b="在玛拉卡金的崎岖山口，兽人达恩·鹰爪时刻注视着部落的南部和山区边境。然而，最大的军事压力来自于北方的灰谷古老森林，在那里，暗夜精灵哨兵与战歌伐木工不断发生冲突。达恩发现了途径石爪山脉的浴血战士，便引导有能力的征募兵前往北贫瘠之地的瞭望塔，以协助正在进行的战役。"},{t="卡德拉克的岗哨",b="兽人卡德拉克驻守在干旱大草原与灰谷葱郁树冠交汇的北部边界，负责监督部落军队进入争议领土的行动。部落正在积极巩固其立足点，在西部的佐拉姆海岸和北部的碎木岗哨都设有前哨。卡德拉克是协调这些交战森林前线物资、部队和紧急报告的重要枢纽。"}},faq={{q="是谁从石爪山脉派你去卡德拉克那里的？",a="达恩·鹰爪，一位驻扎在石爪山脉玛拉卡金部落前哨站的兽人，向前往森林边界的有能力的冒险者提供了这份急报。",al={"任务发布人：向卡德拉克报到","谁开启了向卡德拉克报到（石爪山脉）","达恩·鹰爪任务"}},{q="卡德拉克在哪里？",a="卡德拉克驻扎在贫瘠之地的北部瞭望塔，守卫着通往北面灰谷的主要道路。",al={"卡德拉克位置","卡德拉克在哪里","寻找卡德拉克"}},{q="为什么部落要为灰谷征募战士？",a="部落需要木材来维持奥格瑞玛的运转，并已建立了诸如佐拉姆海岸和碎木岗哨等防御阵地。由于这些行动遭到了当地暗夜精灵的强烈抵抗，指挥官们需要不断的增援来确保该地区的安全。",al={"为什么去灰谷","部落灰谷战役","为什么在灰谷作战"}},{q="向卡德拉克报到后会发生什么？",a="卡德拉克将向你简要介绍灰谷的战略局势，并指派你通过《战歌报告》在森林中的各处交战前哨传递和收集军事报告。",al={"向卡德拉克报到后做什么","战歌报告","卡德拉克后续任务"}},{q="这个任务和贫瘠之地的版本有什么不同吗？",a="这两个都是引导玩家前往灰谷边界卡德拉克处的引导任务。一个在贫瘠之地（十字路口）提供，而这一个在石爪山脉提供；完成其中任何一个都会引导你进入灰谷的故事线。",al={"贫瘠之地与石爪山脉卡德拉克任务","两个向卡德拉克报到的任务","卡德拉克引导任务重复"}},{q="简报中提到的佐拉姆海岸是什么地方？",a="佐拉姆海岸是位于灰谷西北部沿隐匿之海的一个沿海地区。部落在那里建立了一个防御性的海滩前哨，以支持战术行动并确保海上通道的安全。",al={"什么是佐拉姆海岸","佐拉姆海岸前哨站","灰谷海滩基地"}}},fp="16,210,28.358.0,14.304.0,40.135.0,24.98.0,51.199.0,39.129.0,49.188.0,51.187.0"}
P.entries["quest:6543"] = {n="战歌报告",s="这项任务由卡德拉克指派，他在贫瘠之地北部与灰谷交界的边境岗哨执勤。任务要求信使在这一交战森林区域协调前线情报。冒险者必须将常备军令送达，并从驻扎在艾萨拉、碎木岗哨和佐拉姆海岸附近的战歌氏族成员那里收集前线侦察信息。",h="这项任务由卡德拉克指派，他在贫瘠之地北部与灰谷交界的边境岗哨执勤。任务要求信使在这一交战森林区域协调前线情报。冒险者必须将常备军令送达，并从驻扎在艾萨拉、碎木岗哨和佐拉姆海岸附近的战歌氏族成员那里收集前线侦察信息。",kw={"灰谷","贫瘠之地","卡德拉克","碎木岗哨","战歌侦查骑兵","战歌报告","战歌信使","战歌斥候","佐拉姆海岸","佐拉姆加前哨站"},ang={["class:Hunter"]="在灰谷危机四伏的道路上行进，是对导航和野外生存技能的考验，必须应对野兽掠食者和隐藏的精灵弓箭手。",["faction:Horde"]="递送这些报告，标志着一名年轻的部落勇士在卡利姆多北部对抗暗夜精灵的领土斗争中迈出的真正第一步。",["race:Orc"]="对于兽人来说，支持战歌氏族既是氏族荣誉的表现，也是实际的需要，以确保木材源源不断地运往奥格瑞玛进行建设。"},sec={{t="边境后勤",b="卡德拉克伫立在贫瘠之地北缘的加固岗哨上，俯瞰着通往灰谷的狭窄山谷。对于部落而言，确保这条通道的安全至关重要：干旱的草原无法提供奥格瑞玛所需的巨量木材，这迫使战歌氏族深入古老的精灵林地。要让分散的前方巡逻队获得补给并保持同步，就需要可靠的信使，他们必须能够躲避灰谷危机四伏的荒野小径上的暗夜精灵伏击。"},{t="灰谷之眼",b="这项任务的路线横跨整片古老森林。在最西端雾气弥漫的佐拉姆海岸，一名战歌信使负责监视纳迦的活动以及佐拉姆加前哨站附近的沿海威胁。深入内陆的碎木岗哨，一名战歌斥候负责协调防御，抵御哨兵不断的突袭。在通往艾萨拉废墟的蜿蜒道路上向东更远处，一名战歌侦查骑兵负责监控东部的动向。从这三个哨站收集更新信息，能让卡德拉克对暗夜精灵的部队动向和边境漏洞有一个全局的了解。"}},faq={{q="这项任务在哪里开始？",a="任务开始于卡德拉克，他是一名兽人军官，驻守在贫瘠之地北部与灰谷南部交界处守护山口的木制岗哨内。",al={"任务发布者","卡德拉克位置","谁发布战歌报告任务","在哪里开始"}},{q="为什么部落要在灰谷进行侦察？",a="部落严重依赖灰谷茂密的木材来建造和加固像奥格瑞玛这样的定居点。当地的暗夜精灵拼死捍卫他们神圣的林地，使整个区域变成了一个活跃的战区，需要持续的侦察来维护哨站并保障补给线。",al={"为什么是灰谷","战歌伐木","灰谷冲突"}},{q="这三名战歌斥候在哪里可以找到？",a="战歌信使驻扎在最西北端佐拉姆海岸的佐拉姆加前哨站。战歌斥候驻守在大路旁的碎木岗哨。战歌侦查骑兵在通往艾萨拉边界的东部道路上巡逻。",al={"斥候位置","斥候在哪里","侦查骑兵信使斥候位置"}},{q="战歌侦查骑兵是谁？",a="战歌侦查骑兵是战歌兽人氏族的斥候和突袭者。他们以凶猛的骑兵和游击战术而闻名，是部落在灰谷森林进行扩张、木材采伐和领土防御的先锋。",al={"战歌氏族","谁是战歌侦查骑兵","灰谷的战歌氏族"}},{q="交回报告后会发生什么？",a="在收到收集到的情报后，卡德拉克会利用这些战术更新来规划后续的部队调动，增援佐拉姆加和碎木岗哨等脆弱的据点，并巩固部落在森林深处的存在。",al={"报告交付","下一步行动","卡德拉克的作用"}},{q="对于低等级信使来说，穿过灰谷的道路安全吗？",a="不安全。穿过灰谷的主干道经常面临隐身的暗夜精灵哨兵、潜行者和熊等危险野生动物的伏击，以及从阿斯特兰纳等定居点出动的联盟巡逻队的威胁。",al={"灰谷危险","道路是否安全","暗夜精灵偷袭"}}},fp="19,205,18.410.0,21.421.0,30.150.0,37.236.0,44.214.0,30.179.0,41.195.0,58.169.0"}
P.entries["quest:6544"] = {n="托雷克的突袭",s="“托雷克的突袭”是一场部落发动的直接突袭，他们从灰谷的荒野中出发，进攻附近银翼哨站的暗夜精灵驻军。在碎木岗哨的指令下，由兽人劫掠者托雷克率领，此次打击旨在粉碎当地哨兵的抵抗，并击杀她们的指挥官杜利尔·月火。这标志着在这场旷日持久的灰谷边境战争中，最鲁莽且血腥的冲突之一。",h="“托雷克的突袭”是一场部落发动的直接突袭，他们从灰谷的荒野中出发，进攻附近银翼哨站的暗夜精灵驻军。在碎木岗哨的指令下，由兽人劫掠者托雷克率领，此次打击旨在粉碎当地哨兵的抵抗，并击杀她们的指挥官杜利尔·月火。这标志着在这场...",kw={"灰谷","杜利尔·月火","埃尔托格·怒齿","劫掠者","哨兵","银翼哨站","碎木岗哨","托雷克"},ang={["class:Warrior"]="这是一场残酷的正面近战，考验着战士们面对经验丰富的哨兵弓箭手和刀锋战士时的纯粹肉体耐力。",["faction:Alliance"]="杜利尔·月火的倒下使银翼哨站陷入危机，并威胁到暗夜精灵的祖传林地领地。",["faction:Horde"]="对于部落来说，突破银翼哨站是一次至关重要的力量测试，削弱了包围碎木岗哨的暗夜精灵封锁线。",["race:NightElf"]="这场突袭直接打击了哨兵前线指挥的核心，在灰谷的树荫下洒下了精灵的鲜血。"},sec={{t="阴影中的打击",b="灰谷正陷入部落伐木场与当地暗夜精灵之间不断升级的边境战争。为了突破联盟的防御圈，托雷克在银翼哨站外集结了一队碎木岗哨的劫掠者。托雷克并没有等待反击，而是协调了一次正面冲锋，试图在暗夜精灵针对碎木岗哨组织起增援行动前，彻底摧毁哨站的防御。"},{t="攻占银翼",b="银翼哨站是一座防御森严的林地据点，驻守着警惕的银翼要塞守军和凶猛的精灵战士。托雷克的主要目标是她们的领袖，杜利尔·月火。击倒杜利尔就等于铲除了当地暗夜精灵的军事指挥中枢，让劫掠者们能够向碎木岗哨的埃尔托格·怒齿指挥官报告这一血腥的胜利。"}},faq={{q="谁是托雷克？",a="托雷克是一位激进的兽人劫掠者，活动于灰谷的碎木岗哨。他凶猛且渴望战斗，指挥着一支肩负重任的劫掠者小队，旨在直接打击盘踞在森林中的暗夜精灵部队。",al={"托雷克 非玩家角色","谁是托雷克","托雷克 兽人"}},{q="什么是银翼哨站？",a="银翼哨站是灰谷内一座防御性的暗夜精灵定居点。由精锐的哨兵和战士守卫，它是监视林间小道上部落军队动向的军事堡垒。",al={"银翼哨站","什么是银翼"}},{q="谁是杜利尔·月火？",a="杜利尔·月火是负责守卫银翼哨站的暗夜精灵指挥官。作为驻军首领，她指挥当地哨兵抵御部落的入侵，直到托雷克的突袭小队突破营地并将她击倒。",al={"杜利尔·月火","杜利尔"}},{q="谁是埃尔托格·怒齿？",a="埃尔托格·怒齿是驻扎在碎木岗哨的部落军官。他是托雷克的上级，负责监督该地区的军事行动，并接收针对联盟的胜利报告。",al={"埃尔托格·怒齿","埃尔托格"}},{q="部落为什么要攻击银翼哨站？",a="部落与暗夜精灵在整个灰谷陷入了激烈的领土战争。打击银翼哨站可以减轻部落补给线的压力，并直接削弱守护森林深处的哨兵防御网络。",al={"为什么攻击银翼","灰谷冲突 银翼"}},{q="这次袭击发生在哪里？",a="突袭始于银翼哨站外，位于灰谷内弗伦河东侧的部落控制区，并最终在暗夜精灵营地内部达到高潮。",al={"托雷克突袭地点","托雷克在哪里"}}},fp="15,215,25.343.0,17.299.0,13.152.0,27.159.0,23.179.1,22.179.0,45.210.0,34.159.0"}
P.entries["quest:6545"] = {n="战歌信使的报告",s="“战歌信使的报告”是一项部落的通讯任务，旨在连接灰谷的前线防御工事与边境各地的指挥官。这份信件被托付给信使和新兵，详细说明了战歌侦察兵所面临的军事压力日益增长，尤其是来自入侵纳迦的侵略行径。",h="“战歌信使的报告”是一项部落的通讯任务，旨在连接灰谷的前线防御工事与边境各地的指挥官。这份信件被托付给信使和新兵，详细说明了战歌侦察兵所面临的军事压力日益增长，尤其是来自入侵纳迦的侵略行径。",kw={"灰谷","卡德拉克","莫尔杉","纳迦","壁垒","报告","信使","侦察兵","战歌"},ang={["faction:Horde"]="森林前线的每一名士兵都很重要，在此处，维持贫瘠之地与前线哨站之间的通讯线路对于生存至关重要。",["race:Orc"]="战歌氏族依赖其信使的勇气和警惕，以守住在大酋长萨尔命令下所占领的土地。"},sec={{t="前线急报",b="战歌氏族在整个灰谷部署了一系列的侦察兵和信使，以监视周边的敌对势力并保持补给线畅通。由于与暗夜精灵哨兵的领土冲突以及恶劣的地理环境，迅速获取情报至关重要。运送前线急报的信使对于确保偏远哨站与驻扎在莫尔杉壁垒的卡德拉克等指挥官保持协调至关重要。"},{t="纳迦的威胁",b="虽然部落预计会遭遇来自树林中暗夜精灵的猛烈反抗，但前哨岗哨报告称，纳迦的袭击正变得日益大胆。这些蛇形入侵者从水道和古代遗迹发起突袭，试探着哨站的防御工事，并迫使守军分散注意力，无法专心进行林业生产和边境巡逻。带回莫尔杉壁垒的报告拉响了关于这些协同两栖攻击的警报。"}},faq={{q="这份报告是发给谁的？",a="这份报告被直接送回给卡德拉克，他是一位驻扎在莫尔杉壁垒的监工，该壁垒位于灰谷与北贫瘠之地交界的边境线上。",al={"谁收到报告","卡德拉克报告","报告去向"}},{q="报告中提到了哪些威胁？",a="侦察兵报告说，当地哨站已经抵御了多次袭击，并强调了附近水域中敌对纳迦日益升级的威胁。",al={"报告内容","信使报告详情","纳迦袭击"}},{q="为什么部落在这里依赖徒步信使？",a="茂密的植被、活跃的暗夜精灵神射手以及孤立的哨站使得空中运输在灰谷的部分地区变得困难重重或极易暴露。地面信使能够在受到保护的小径上进行迅速、隐秘的通讯。",al={"为什么需要信使","战歌信使背景","为什么不用双足飞龙"}},{q="什么是战歌信使？",a="他们是战歌氏族的侦察兵、信使和先锋战士，负责确保补给线的安全，并监视森林争议边境周围的敌军动向。",al={"战歌氏族灰谷","谁是战歌信使"}},{q="纳迦在灰谷的哪些地方发动攻击？",a="纳迦在灰谷的岸边和湖泊旁的遗迹中建立了据点，经常伏击旅行者并突袭附近的营地。",al={"纳迦在哪里","灰谷纳迦"}},{q="哨站在这个地区的作用是什么？",a="该哨所作为早期预警站和防御锚点，确保敌对势力无法切断深林伐木作业与贫瘠之地之间的通讯。",al={"哨站设立原因","部落营地目的"}}},fp="21,178,20.299.0,15.325.0,32.115.0,41.113.0,45.185.0,28.168.0,42.118.0,43.139.0"}
P.entries["quest:6546"] = {n="战歌侍从的报告",s="“战歌侍从的报告”是一个部落送达任务，任务发起始于灰谷东部险象环生的道路上。一名孤身在此的战歌斥候将一份至关重要的情报托付给了一位冒险者，这份情报详细记录了来自附近联盟军队、根深蒂固的萨特以及临近艾萨拉地区不断蔓延的纳迦所构成的威胁。",h="“战歌侍从的报告”是一个部落送达任务，任务发起始于灰谷东部险象环生的道路上。一名孤身在此的战歌斥候将一份至关重要的情报托付给了一位冒险者，这份情报详细记录了来自附近联盟军队、根深蒂固的萨特以及临近艾萨拉地区不断蔓延的纳迦...",kw={"灰谷","艾萨拉","卡德拉克","莫尔杉壁垒","纳迦","萨特","战歌侦查骑兵","战歌报告"},ang={["faction:Horde"]="每一份在莫尔杉防线上传递的简报，都巩固了部落在灰谷茂密森林中脆弱的立足点。",["race:Orc"]="战歌氏族以身处前锋为荣，但他们的斥候深知，仅凭勇气无法抵挡四面受敌的困境。"},sec={{t="森林边缘的注视",b="灰谷东部是一个充满争端的边界地区，部落的补给线在这里不断遭到袭扰。战歌氏族在丛林中保持着严密的警戒网，他们会在敌方突袭队威胁到莫尔杉壁垒或碎木岗哨等前哨站之前，就侦查到敌人的动向。遇到一名巡逻的战歌侦查骑兵，就意味着直接进入了一个活跃的侦查战区，在这里，情报可能决定了一个据点是能守住，还是会沦陷于伏击。"},{t="地平线上的威胁",b="这份由战歌侦查骑兵汇编的报告，勾勒出了部落在卡利姆多中部森林所面临的严峻战术局势。除了与暗夜精灵及更广泛的联盟之间无处不在的小规模冲突外，灰谷东部还潜伏着狡猾的恶魔萨特。更危险的是，斥候们发现大批纳迦正扩散至邻近的艾萨拉沿海废墟，这警告指挥官们，部落正处于几乎来自四面八方的敌对势力的包围之中。"}},faq={{q="什么是战歌报告？",a="这是一份由战歌侦查骑兵撰写的情报简报，总结了敌军的部署和区域威胁。它强调了来自附近联盟部队、灰谷东部活跃的萨特集会以及艾萨拉新发现的纳迦动向的威胁。",al={"战歌报告任务物品","报告上说了什么","斥候报告"}},{q="卡德拉克是谁？",a="卡德拉克是一位驻扎在莫尔杉壁垒的部落指挥官，那是守卫贫瘠之地和灰谷北部边界的防御屏障。他负责监管进出的斥候，并协调进入森林的前线行动。",al={"卡德拉克是谁","卡德拉克在哪里","卡德拉克交任务"}},{q="为什么要提到艾萨拉的纳迦？",a="艾萨拉直接与灰谷东部接壤。侦查骑兵会跟踪相邻领土上的外敌动向，以确保部落在应对暗夜精灵的同时，侧翼不会被大规模的入侵所突袭。",al={"纳迦与艾萨拉的联系","为什么要提到艾萨拉","艾萨拉的纳迦威胁"}},{q="为什么灰谷东部对部落如此危险？",a="该地区夹在活跃的联盟分遣队、渗透着恶魔腐化的远古萨特遗迹以及未驯服的丛林野兽之间，这使得部落的信使和巡逻队极易遭到来自各个方向的伏击。",al={"为什么灰谷东部很危险","灰谷的威胁","萨特威胁"}},{q="谁是战歌氏族？",a="他们是战歌氏族在灰谷的前锋部队和侦查骑兵，负责追踪暗夜精灵的动向、守卫伐木场并保障贸易路线的安全。",al={"什么是侦查骑兵","战歌斥候","侦查骑兵背景设定"}},{q="为什么侦查骑兵不能亲自递交报告？",a="这名侦查骑兵肩负着在小径上保持警戒的任务，以实时追踪敌对动向的发展。离开他的观察点，前线将无法及时察觉到联盟或萨特的突然袭击。",al={"我为什么要递交报告","为什么他不自己递交"}}},fp="23,211,26.359.0,24.362.0,27.246.0,14.226.0,38.207.0,56.206.0,30.182.0,50.176.0"}
P.entries["quest:6547"] = {n="战歌斥候的报告",s="战歌斥候的报告是一项部落的通讯任务，旨在连接灰谷边界的前哨指挥官与监视这片争议森林的前线斥候。信使携带来自卡德拉克的战略命令，以确保战歌氏族保持严密监视，防范暗夜精灵的伏击。它凸显了部落在他们新占领的领土上努力维持的岌岌可危、充满敌意的控制权。",h="战歌斥候的报告是一项部落的通讯任务，旨在连接灰谷边界的前哨指挥官与监视这片争议森林的前线斥候。信使携带来自卡德拉克的战略命令，以确保战歌氏族保持严密监视，防范暗夜精灵的伏击。它凸显了部落在他们新占领的领土上努力维持的岌岌...",kw={"灰谷","贫瘠之地","卡德拉克","暗夜精灵","报告","斥候","哨兵部队","战歌"},ang={["faction:Horde"]="每一位在卡德拉克和外围斥候之间传递命令的信使，都在帮助部落在灰谷站稳脚跟，抵御暗夜精灵不断的伏击。",["race:NightElf"]="战歌斥候在边界潜伏，代表着对艾露恩神圣森林的持续亵渎，而哨兵部队正致力于将其清除。",["race:Orc"]="战歌氏族的传奇由他们在灰谷的顽强意志所定义，尽管土地及其古老的守护者充满敌意，他们依然夺取了至关重要的木材。"},sec={{t="阴影中的双眼",b="灰谷的边境地区依然是一个火药桶，双方寸步不让。卡德拉克指挥下的部落军队严重依赖部署在高风险前哨的零散战歌斥候，来追踪暗夜精灵的动向并保护争议中的补给线。由于森林本身为联盟隐秘的哨兵提供了天然掩护，定期的报告和书面更新对于防止孤立的斥候被切断联系并遭歼灭至关重要。"},{t="坚守阵地",b="对战歌氏族来说，每一片被清理或占领的森林都是用鲜血换来的。斥候们时刻警惕着旨在夺回林地的暗夜精灵报复性突袭。传递卡德拉克的命令让先锋部队确信增援和协调依然在进行，并使斥候能够汇报他们的防御措施在持续的精灵抵抗下依然行之有效。"}},faq={{q="卡德拉克是谁？",a="卡德拉克是一名驻扎在贫瘠之地与灰谷边界的部落指挥官。他负责协调侦察任务、边境防御，以及为侵入古老森林的战歌行动提供后勤支持。",al={"卡德拉克","卡德拉克是谁","卡德拉克的职责"}},{q="为什么战歌斥候对暗夜精灵如此警惕？",a="暗夜精灵能自然地融入他们祖传森林的阴影中，对部落巡逻队发动突袭。由于战歌氏族正在积极清理木材并定居在精灵视为圣地的土地上，斥候们时刻面临着致命偷袭的威胁。",al={"为何惧怕暗夜精灵","阴影中的暗夜精灵","战歌斥候面临的精灵威胁"}},{q="为什么灰谷会成为争夺焦点？",a="部落需要灰谷的木材和资源来建设奥格瑞玛，并支持其在干旱的贫瘠之地和杜隆塔尔的定居点。当地的暗夜精灵将森林视为圣地，并积极抗争，试图将兽人伐木工和驻军赶走。",al={"为何争夺灰谷","灰谷战争","部落在灰谷的冲突"}},{q="战歌氏族在这里的角色是什么？",a="战歌氏族是部落在灰谷扩张和资源采集的先锋。他们在第三次战争期间由格罗姆·地狱咆哮带领进入森林，此后他们的存在一直根深蒂固，运营着伐木场，并与哨兵部队进行着持续的小规模冲突。",al={"战歌氏族在灰谷","战歌氏族的职责"}},{q="这份报告在送达斥候后会去哪里？",a="在斥候收到卡德拉克的最新指示后，他们会将针对精灵反击的当地战况汇报回去，确保部落领导层随时掌握前线的稳定情况。",al={"报告的接收者","卡德拉克的报告","斥候报告的结果"}},{q="部落目前在灰谷的计划进展顺利吗？",a="前线斥候认为他们的防御工作是成功的，能够守住防御阵地并击退精灵的打击，尽管该地区仍然是一个激烈争夺的战场，双方都未能取得绝对优势。",al={"部落是否在灰谷占据优势","战歌氏族的进展"}}},fp="20,173,19.283.0,18.292.0,14.174.0,57.200.0,35.224.0,37.208.0,51.165.0,60.196.0"}
P.entries["quest:6548"] = {n="为我的村庄复仇",s="玛卡巴·扁蹄在石爪山脉东南部的村庄遭到恐怖图腾部族的突袭，他侥幸逃过一劫。他与族人失散，周围满是尸体。他请求部落的旅者反击恐怖图腾恶棍和雇佣兵的营地，为他死去的族人复仇。",h="玛卡巴·扁蹄在石爪山脉东南部的村庄遭到恐怖图腾部族的突袭，他侥幸逃过一劫。他与族人失散，周围满是尸体。他请求部落的旅者反击恐怖图腾恶棍和雇佣兵的营地，为他死去的族人复仇。",kw={"复仇之村","恐怖图腾","恐怖图腾雇佣兵","恐怖图腾恶棍","格伦迪格·黑云","玛卡巴·扁蹄","石爪山脉"},ang={["faction:Horde"]="部落依赖于贫瘠之地和石爪山脉之间开放且安全的通道。一支残暴的恐怖图腾小队谋杀旅客和盟友村庄，威胁到了大酋长穿过山脉的补给线。",["race:Tauren"]="恐怖图腾部族的背叛对牛头人旅客打击最大。看到同胞舒哈鲁（shu'halo）被同类屠杀，更加凸显了部族分裂的残酷现实，以及恐怖图腾对凯恩的团结子民所构成的危险。"},sec={{t="岩石中的鲜血",b="在贫瘠之地与石爪山脉红石隘口的边界附近，玛卡巴·扁蹄独自站在一场残酷大屠杀的余波中。打着恐怖图腾部族黑暗旗帜的掠夺者毫无预兆地突然袭击，杀光了他定居点里的所有人。虽然玛卡巴奋力反击并击倒了几名袭击者，但最终还是被迫逃亡，只剩下一条命和满腔怒火。"},{t="恐怖图腾的威胁",b="恐怖图腾长期以来一直是大酋长凯恩·血蹄领导下团结的牛头人部落中桀骜不驯、充满侵略性的眼中钉。与在莫高雷游荡的和平游牧民不同，恐怖图腾战团经常雇佣冷酷的恶棍和投机取巧的雇佣兵来开拓领土，袭击孤立的定居点。对玛卡巴来说，外交或部落亲情现在毫无意义；只有血债血偿才能缓解他的悲痛。"}},faq={{q="谁发布了这个任务？",a="玛卡巴·扁蹄是一位驻扎在通往石爪山脉东南隘口附近的牛头人幸存者。他在附近村庄遭到恐怖图腾部族的暴力洗劫后幸存下来，并寻求向那些掠夺者复仇。",al={"任务发布者","玛卡巴·扁蹄","玛卡巴是谁"}},{q="为什么恐怖图腾要袭击其他牛头人？",a="恐怖图腾部族从来没有真正拥护过部落的团结，也不认可凯恩·血蹄的和平愿景。他们极具领地意识、排外且充满攻击性，他们公开劫掠敌对定居点，杀害外来者，并利用武装暴徒和雇佣兵来宣称对石爪山脉等地区的主权。",al={"为何恐怖图腾敌对","牛头人攻击牛头人","恐怖图腾部族背景故事"}},{q="恐怖图腾袭击者在哪里？",a="恐怖图腾的恶棍和雇佣兵驻扎在玛卡巴·扁蹄在石爪山东南部位置以西的一个营地里，位于俯瞰隘口的岩石山丘中。",al={"怪物在哪里","恐怖图腾营地位置","去哪里找恶棍"}},{q="谁是恐怖图腾雇佣兵？",a="恐怖图腾部族经常通过雇佣冷酷的战士和雇佣兵来加强其战团，从而补充自身兵力，确保他们有足够的武力来恐吓和践踏孤立的定居点。",al={"雇佣兵","恐怖图腾雇佣兵","雇佣兵是谁"}},{q="这个任务之后会发生什么？",a="在消灭了前线的恶棍和雇佣兵后，玛卡巴请求你去打击大屠杀背后的首领——格伦迪格·黑云（格鲁迪格·暗云），这在后续任务“杀死格伦迪格·黑云”中进行。",al={"后续任务","复仇之村后续","杀死格伦迪格·黑云"}},{q="玛卡巴的村庄位于哪里？",a="玛卡巴的定居点是一个孤立的牛头人营地，位于石爪山脉东南部的边界隘口附近。它在恐怖图腾的突袭中被彻底摧毁，玛卡巴是为数不多的已知幸存者之一。",al={"扁蹄村","村庄在哪里","哪个村庄被摧毁"}}},fp="17,241,18.334.0,20.358.0,20.193.0,45.262.0,42.140.0,34.132.0,30.138.1,35.187.0"}
P.entries["quest:655"] = {n="落锤镇",s="落锤镇讲述了部落大酋长奥格瑞姆·毁灭之锤在阿拉希高地解放一座联盟收容所时不幸阵亡的悲剧。通过戈穆尔那些充满悲痛的回忆，旅人们得以了解这座营地是如何被解放的，以及这座据点为何拥有这个庄严的名字。",h="落锤镇讲述了部落大酋长奥格瑞姆·毁灭之锤在阿拉希高地解放一座联盟收容所时不幸阵亡的悲剧。通过戈穆尔那些充满悲痛的回忆，旅人们得以了解这座营地是如何被解放的，以及这座据点为何拥有这个庄严的名字。",kw={"阿拉希高地","奥格瑞姆·毁灭之锤","戈穆尔","落锤镇","收容所","萨尔","托尔甘"},ang={["class:Warrior"]="奥格瑞姆·毁灭之锤依然是一位标志性的传奇战士，行走在他阵亡的战场上具有沉重的军事意义。",["faction:Horde"]="落锤镇作为一座庄严的纪念碑，见证了兽人收容所的解放和大酋长奥格瑞姆·毁灭之锤的牺牲。",["race:Orc"]="对于兽人来说，奥格瑞姆·毁灭之锤在阿拉希的倒下是他们历史上最痛苦的时刻之一，这标志着一个时代的结束和萨尔领导的新部落的崛起。"},sec={{t="血与断链",b="落锤镇曾是一座阴森的联盟收容所，在第二次战争后，俘虏的兽人们被囚禁在木头与钢铁构成的牢笼中。当年轻的萨尔和大酋长奥格瑞姆·毁灭之锤发起突袭，击碎了牢笼并解放了他们的族人时，一切都改变了。尽管这次突袭成功解放了许多俘虏并摧毁了营地的防御，但它却以悲剧告终：奥格瑞姆·毁灭之锤在冲锋中被一名骑兵从背后用长矛刺中，倒在了如今这座部落定居点所在的土地上。"},{t="失败的阴影",b="并非每一位俘虏在那命运之日都获得了自由。在战斗的混乱和大地的震颤中，一位名叫戈穆尔的兽人眼睁睁看着那位传奇大酋长倒下，丧失了所有的斗志。当他的同胞逃离时，他被留在了原地，戈穆尔在荒原上漫无目的地游荡，心中充满了悲伤。即使如今部落已将此地收复为一座堡垒，那次卑劣袭击的记忆仍困扰着幸存者们。"}},faq={{q="谁是戈穆尔？",a="戈穆尔曾是被关押在落锤镇旧址收容所里的一名兽人俘虏。尽管萨尔和奥格瑞姆·毁灭之锤发起突袭解放了该营地，但戈穆尔在混乱的逃亡中被抛下，在绝望中孤独地游荡了多年。",al={"谁是戈穆尔","戈穆尔背景故事","戈穆尔的经历"}},{q="奥格瑞姆·毁灭之锤是如何阵亡的？",a="奥格瑞姆·毁灭之锤在解放阿拉希收容所的战斗中阵亡。当他身穿黑色板甲领导进攻时，一名骑马冲锋的联盟骑士从背后用长矛刺穿了他的身体。",al={"奥格瑞姆·毁灭之锤是如何阵亡的","谁杀了奥格瑞姆·毁灭之锤","奥格瑞姆·毁灭之锤阵亡的故事"}},{q="为什么这座前哨站被命名为落锤镇？",a="这座前哨站被命名为落锤镇，是为了纪念在此地为了将族人从人类的囚禁中解放出来而阵亡的大酋长奥格瑞姆·毁灭之锤。部落后来回到了这座荒废的营地，建立了一座永久的基地。",al={"为什么叫落锤镇","落锤镇名字的由来","落锤镇历史"}},{q="谁是托尔甘？",a="托尔甘是驻扎在落锤镇的一名部落代表，他帮助照看这座营地，并理解像戈穆尔这样的前俘虏所遭受的创伤。",al={"谁是托尔甘","托尔甘 落锤镇","托尔甘任务"}},{q="萨尔参加了此地的战斗吗？",a="是的。萨尔与大酋长奥格瑞姆·毁灭之锤并肩作战，袭击了这座阿拉希收容所。他们共同击碎了营地的防御以解放被俘的兽人，尽管这场胜利的代价是奥格瑞姆·毁灭之锤的生命。",al={"萨尔和奥格瑞姆 毁灭之锤 阿拉希","落锤镇的解放","萨尔在落锤镇战斗过吗"}},{q="为什么戈穆尔如此消沉？",a="戈穆尔亲眼目睹奥格瑞姆·毁灭之锤倒下，这击碎了他的精神。当其他俘虏逃入荒野时，他被留在了原地，在毫无希望的情况下漫无目的地游荡，直到部落回来建立了落锤镇。",al={"为什么戈穆尔如此悲伤","戈穆尔的消沉","戈穆尔为什么失去希望"}}},fp="10,169,23.321.0,30.367.0,15.224.0,30.141.0,36.186.0,15.161.0,40.181.0,29.212.0"}
P.entries["quest:65593"] = {n="Hearts of the Lovers",s="凯伦丁·哈加尔想用 Avelina Lilly 和 Isaac Pearson 的心脏引来一只夜魔。他们对彼此的思念，让这两颗心成为格外强效的诱饵。",h="凯伦丁·哈加尔想用 Avelina Lilly 和 Isaac Pearson 的心脏引来一只夜魔。他们对彼此的思念，让这两颗心成为格外强效的诱饵。",kw={"安伯米尔","avelina lilly","凯伦丁·哈加尔","hearts of the lovers","夜魔","isaac pearson","恋人","棘齿城"},sec={{t="占卜的选择",b="凯伦丁·哈加尔在诅咒神殿的工作需要两颗心脏。他的占卜指向了安伯米尔的 Avelina Lilly 和棘齿城的 Isaac Pearson。Avelina 用裁缝手艺为堕落的巫师们效力，而 Isaac 希望在这座海滨小镇闯出名堂。尽管相隔遥远，各自劳作，他们仍思念着彼此。凯伦丁要你把他们的心脏带给他，用来引诱一只夜魔。"},{t="两颗心脏",b="凯伦丁收下了 Avelina Lilly 和 Isaac Pearson 的心脏。他双手各握一颗，轻轻将它们合在一起，随后骂这对恋人是傻瓜。"}},faq={{q="Avelina Lilly 和 Isaac Pearson 是谁？",a="Avelina Lilly 为安伯米尔的堕落巫师提供裁缝服务，Isaac Pearson 则希望在棘齿城闯出名堂。他们的心渴望着彼此。",al={"avelina 和 isaac","恋人是谁"}},{q="凯伦丁为什么想要他们的心脏？",a="凯伦丁说，恋人的心脏能够引来夜魔，而最深切的思念能成为最强效的诱饵。",al={"夜魔心脏","为什么要心脏"}},{q="这对恋人在哪里？",a="Avelina Lilly 在银松森林的安伯米尔，Isaac Pearson 则在贫瘠之地的棘齿城。",al={"avelina 在哪里","isaac 在哪里"}},{q="凯伦丁·哈加尔是谁？",a="凯伦丁·哈加尔身在诅咒神殿，他在那里要你把 Avelina 和 Isaac 的心脏带给他。",al={"凯伦丁","诅咒神殿"}}},fp="20,155,18.387.0,10.153.1,40.165.0,36.107.0,25.101.0,23.106.0"}
P.entries["quest:65597"] = {n="誓缚",s="幽暗城魔法区的凯伦丁·哈加尔要你用 Lovers’ Hearts 召唤并制服一只梦魔，之后还要把心交还给他。",h="幽暗城魔法区的凯伦丁·哈加尔要你用 Lovers’ Hearts 召唤并制服一只梦魔，之后还要把心交还给他。",kw={"凯伦丁·哈加尔","梦魔","lovers’ hearts","魔法区","召唤","誓缚","幽暗城"},sec={{t="幽暗城的一场召唤",b="凯伦丁·哈加尔在幽暗城的魔法区请求你的帮助。你要用 Lovers’ Hearts 召唤并制服一只梦魔，然后把它们带回给他。归还后，这些心仍由凯伦丁保管。"}},faq={{q="谁在请求帮助？",a="幽暗城魔法区的凯伦丁·哈加尔请求你帮忙。",al={"谁想要这个","谁给了它","凯伦丁·哈加尔"}},{q="Lovers’ Hearts 有什么用？",a="你要用 Lovers’ Hearts 召唤并制服一只梦魔。",al={"爱侣之心的用途","心有什么用","用心召唤梦魔"}},{q="召唤之后会发生什么？",a="你要把 Lovers’ Hearts 还给魔法区的凯伦丁·哈加尔。",al={"把心还到哪里","归还爱侣之心","接下来做什么"}}},fp="11,160,28.226.0,23.72.0,34.61.0,33.72.0"}
P.entries["quest:656"] = {n="召唤大地公主",s="迷失者塞尔杜林说，必须在密斯莱尔还在成长时将其击败，不能让她积蓄起足以挑战监禁者们的力量。你需要在密斯莱尔之碎片处召唤她，将其击败，并将她的怪异镣铐束缚在这些碎片上。",h="迷失者塞尔杜林说，必须在密斯莱尔还在成长时将其击败，不能让她积蓄起足以挑战监禁者们的力量。你需要在密斯莱尔之碎片处召唤她，将其击败，并将她的怪异镣铐束缚在这些碎片上。",kw={"阿拉希高地","怪异镣铐","密斯莱尔","密斯莱尔卷轴","密斯莱尔之碎片","迷失者塞尔杜林"},sec={{t="为什么要阻止她",b="塞尔杜林希望在密斯莱尔的力量膨胀到足以对抗她的监禁者之前就阻止她。有人声称她可以被控制；塞尔杜林反问，如果真是这样，巨人为什么还要费尽心机去锁住她。"},{t="在碎片处",b="你带着密斯莱尔卷轴前往密斯莱尔之碎片，也就是你第一次与她交谈的地方，将她召唤出来。在你击败她之后，你便可以把她的怪异镣铐束缚在碎片上，再次将她封印。"},{t="当镣铐被安置好后",b="当镣铐在碎片周围稳固时，深处传来一声哀号，紧接着是一声咆哮。碎片曾经给予的温暖与安全感荡然无存。现在，它们脉动着显而易见的威胁，仿佛藏在它们之下的东西对地表怀有恶意。"}},faq={{q="谁派你去对付密斯莱尔？",a="迷失者塞尔杜林。他警告说，必须在密斯莱尔的力量增长到足以挑战她的监禁者之前将其击败。",al={"任务发布者","谁给予召唤公主任务","塞尔杜林任务"}},{q="召唤在什么地方进行？",a="在密斯莱尔之碎片，也就是你第一次与她交谈的地方。",al={"在哪里召唤密斯莱尔","密斯莱尔之碎片位置","召唤地点"}},{q="为什么塞尔杜林想要击败密斯莱尔？",a="塞尔杜林担心她会变得足够强大，从而挑战她的监禁者。塞尔杜林还指出，如果她真的能被控制，巨人就不会把她锁起来了。",al={"为什么要杀掉密斯莱尔","塞尔杜林的动机","为什么要召唤她"}},{q="密斯莱尔是如何被召唤的？",a="使用密斯莱尔卷轴，在密斯莱尔之碎片处使用。",al={"如何召唤她","密斯莱尔卷轴的使用","召唤过程"}},{q="你如何处理怪异镣铐？",a="击败密斯莱尔，取得她的镣铐，并将它们固定在碎片上。这样她就会再次被封印。",al={"需要什么物品","怪异镣铐"}}},fp="22,199,23.184.0,13.188.0,28.226.1,31.105.0,36.76.0,41.142.0,24.71.0,42.89.0"}
P.entries["quest:65601"] = {n="Love Hurts",s="甘鲁尔让你沿着奥格瑞玛的主街寻找玛加尔。他对Krilge的思念或许能指向召唤魅魔来到现世所需的物品。",h="甘鲁尔让你沿着奥格瑞玛的主街寻找玛加尔。他对Krilge的思念或许能指向召唤魅魔来到现世所需的物品。",kw={"暗影裂口","甘鲁尔","魅魔","克里格","爱让人受伤","玛加尔","奥格瑞玛","萨亚德"},sec={{t="玛加尔的寻觅",b="玛加尔住在暗影裂口以东。他盼望Krilge归来，并请你寻找一件珍贵之物。把那件物品带给甘鲁尔，他需要一件饱含爱意与忠诚的物品来召唤魅魔。"}},faq={{q="玛加尔是谁？",a="玛加尔住在奥格瑞玛的主街附近，盼望克里奇归来。",al={"玛加尔是谁"}},{q="克里奇是谁？",a="克里奇是玛加尔的伴侣，玛加尔盼望着他归来。",al={"克里格是谁","玛加尔的伴侣"}},{q="魅魔是什么？",a="魅魔是男性萨亚德，以极度邪恶、一心一意著称。",al={"魅魔含义","男性萨亚德"}},{q="甘鲁尔需要什么？",a="甘鲁尔需要一件代表深厚爱意与忠诚的物品，以引诱魅魔来到现世。",al={"甘鲁尔需要什么","魅魔召唤物品"}},{q="我在哪里能找到玛加尔？",a="玛加尔住在暗影裂口以东，奥格瑞玛的主街附近。",al={"玛加尔的位置","玛加尔在哪里"}}},fp="10,154,14.199.0,13.71.0,14.60.0,19.63.0,23.98.0,23.68.0"}
P.entries["quest:65602"] = {n="What Is Love?",s="黑暗缚灵者加科因正在寻找一尊木雕小像，它年代久远，来历特殊，适合用于梦魇仪式。小像蕴含的情感或许能吸引那生物靠近。",h="黑暗缚灵者加科因正在寻找一尊木雕小像，它年代久远，来历特殊，适合用于梦魇仪式。小像蕴含的情感或许能吸引那生物靠近。",kw={"灰谷","黑暗缚灵者加科因","梦魇","迈斯特拉岗哨","仪式","暴风城","什么是爱","木雕小像"},sec={{t="古老的纪念品",b="黑暗缚灵者加科因通过占卜找到了这尊小像。他说，小像曾属于一对年轻伴侣，距今已有数千年，而它的主人早已不在人世。你需要从灰谷迈斯特拉岗哨外的一所房屋中取回这件纪念品，交给暴风城法师区的加科因。"},{t="小像的力量",b="你归还木雕小像后，加科因感受到，尽管岁月流逝，其中蕴含的情感力量依然强大。他说，梦魇会被它吸引，因此它正是仪式所需的试剂。"}},faq={{q="加科因要我找什么？",a="加科因让你找回一尊木雕小像，他相信它能吸引梦魇前来参加仪式。",al={"什么小像","木雕小像","加科因的物品"}},{q="小像在哪里？",a="加科因说，小像在灰谷迈斯特拉岗哨外的一所房屋里。",al={"小像位置","它在哪里","灰谷的房屋"}},{q="小像曾属于谁？",a="数千年前，这尊小像属于一对年轻伴侣。",al={"旧主人","伴侣的小像","谁拥有过它"}},{q="加科因为什么要小像？",a="加科因感受到小像中蕴含着情感能量，并说它能在仪式中吸引梦魇。",al={"为何要小像","梦魇试剂","它有什么用"}}},fp="13,143,15.275.0,20.201.1,32.97.0,22.63.0,23.63.0,33.97.0"}
P.entries["quest:65603"] = {n="誓缚",s="黑暗缚灵者加科因让你在地下墓穴中使用一尊木雕，并直面一只incubus。你的成败将决定他能否教你召唤恶魔。",h="黑暗缚灵者加科因让你在地下墓穴中使用一尊木雕，并直面一只incubus。你的成败将决定他能否教你召唤恶魔。",kw={"地下墓穴","黑暗缚灵者加科因","incubus","咒语","sayaad","召唤法阵","誓缚","木雕"},ang={["class:Warlock"]="身为术士，你要接受加科因的试炼，束缚sayaad，并学习召唤incubus的咒语。"},sec={{t="地下墓穴中的试炼",b="黑暗缚灵者加科因已在已宰的羔羊下方的地下墓穴中布置好召唤法阵。你将一尊木雕放在法阵中央，为一只incubus打开通道。它是一种sayaad恶魔。它可能会试图蛊惑你，但加科因警告说，它提出的一切都是谎言。若你失败，灵魂将落入险境。"},{t="誓缚之术",b="你击败incubus后，加科因赞扬你坚定不移的意志。他说，许多试图束缚sayaad的术士都会成为它的下一顿美餐。随后，他教你召唤已被你束缚的incubus所需的咒语。"}},faq={{q="加科因要我做什么？",a="加科因要你在地下墓穴的召唤法阵处使用一尊木雕，制服incubus，再把木雕交还给他。",al={"要我做什么","木雕任务","召唤incubus"}},{q="召唤法阵在哪里？",a="加科因说，召唤法阵位于已宰的羔羊下方的地下墓穴中。",al={"在哪里召唤它","地下墓穴法阵","羔羊下方"}},{q="什么是sayaad？",a="sayaad是一种恶魔。加科因警告你，不要低估它们。",al={"sayaad恶魔","是什么恶魔","incubus类型"}},{q="为什么我不该相信incubus？",a="加科因警告说，incubus可能会用蛊惑和欺骗的手段迷惑你，它提出的一切都是谎言。",al={"能相信它吗","incubus欺骗","它会提出什么"}},{q="试炼之后，加科因会教我什么？",a="你击败incubus后，加科因会教你召唤已被你束缚的恶魔所需的咒语。",al={"之后会发生什么","誓缚之术","incubus召唤咒语"}}},fp="11,159,21.294.0,18.210.1,30.130.0,30.76.0,17.75.0,34.101.0,38.99.0"}
P.entries["quest:65604"] = {n="誓缚",s="甘鲁尔·血眼派你带着 Withered Scarf 召唤一只魅魔并将其制服。誓缚将考验你驾驭恶魔魅惑与力量的本领。",h="甘鲁尔·血眼派你带着 Withered Scarf 召唤一只魅魔并将其制服。誓缚将考验你驾驭恶魔魅惑与力量的本领。",kw={"甘鲁尔·血眼","魅魔","玛加尔","尼尔鲁的帐篷","sayaad","召唤圈","誓缚","withered scarf"},ang={["class:Warlock"]="作为一名术士，你正接受召唤并制服魅魔的考验。甘鲁尔警告你，恶魔会用它们的魅惑之力对付你。"},sec={{t="在召唤圈",b="甘鲁尔·血眼从 Withered Scarf 的丝线中感受到爱意，相信它能引来一只魅魔。你要在奥格瑞玛尼尔鲁的帐篷里，于召唤圈使用它，证明自己能驾驭恶魔。甘鲁尔警告你，魅魔不会轻易屈服，并让你制服它后把围巾带回来。"},{t="归还围巾",b="魅魔被制服后，甘鲁尔收回了围巾。他说会教你召唤恶魔，并把围巾还给玛加尔。这块布让他想起，术士可以驾驭恶魔的黑暗，但绝不能被恶魔驾驭。"}},faq={{q="谁交给你誓缚？",a="甘鲁尔·血眼把 Withered Scarf 交给你，让你召唤并制服一只魅魔。",al={"甘鲁尔是谁","甘鲁尔的誓缚","谁给围巾"}},{q="Withered Scarf 有什么作用？",a="甘鲁尔从围巾的丝线中感受到爱意，相信它能引来一只魅魔。",al={"围巾的用途","withered scarf","围巾的作用"}},{q="召唤圈在哪里？",a="召唤圈在奥格瑞玛尼尔鲁的帐篷里。",al={"魅魔召唤圈","在哪里召唤","尼尔鲁的帐篷"}},{q="魅魔是什么？",a="魅魔属于 Sayaad。甘鲁尔警告说，Sayaad 会支配心智、折磨灵魂，而魅魔还能蛊惑猎物。",al={"魅魔的含义","sayaad","什么恶魔"}},{q="甘鲁尔让你做什么？",a="甘鲁尔让你用 Withered Scarf 召唤一只魅魔，将其制服，再把围巾还给他。",al={"誓缚任务","要做什么","魅魔誓缚"}}},fp="11,148,13.325.0,18.231.1,26.91.0,32.88.0,30.53.0,19.123.0,32.102.0"}
P.entries["quest:6561"] = {n="黑暗深渊中的邪恶",s="“黑暗深渊的邪恶”是一项紧急请求，由一名被困在黑暗深渊内部且生命垂危的银色黎明十字军战士发出。部落的冒险者受命去终结梦游者克尔里斯，这位邪教领袖正在下方的废墟中策划着向某种古老怪物的恐怖血祭。",h="“黑暗深渊的邪恶”是一项紧急请求，由一名被困在黑暗深渊内部且生命垂危的银色黎明十字军战士发出。部落的冒险者受命去终结梦游者克尔里斯，这位邪教领袖正在下方的废墟中策划着向某种古老怪物的恐怖血祭。",kw={"阿库麦尔","银色黎明","巴珊娜·符文图腾","黑暗深渊","黑暗深渊的邪恶","克尔里斯","月亮井","塞尔瑞德","梦游者克尔里斯","暮光之锤"},ang={["class:Druid"]="虚空崇拜邪教徒和纳迦对一座古老暗夜精灵月亮井的亵渎，是卡利姆多的自然和精神圣地上的一道痛苦伤口。",["class:Shaman"]="由克尔里斯和阿库麦尔引起的动荡触犯了元素的平衡，将纯净的地下水扭曲成了一个充满阴影和祭祀的溃烂之地。",["faction:Horde"]="对于部落来说，与一名银色黎明侦察兵达成这一契约，代表了在对抗宇宙祸害这一共同利益上难得的时刻，从而赢得了银色黎明的早期好感。",["race:Tauren"]="巴珊娜·符文图腾将击败克尔里斯视为对大地母亲至关重要的防御，清除了一个试图将世界的自然秩序推向原始混沌的憎恶。"},sec={{t="绝望的背水一战",b="银月守卫塞尔瑞德被吸引到了灰谷海岸下的地下神庙中，却发现了远比单纯的纳迦入侵更可怕的恐怖。这名暗夜精灵在洞穴中身受重伤、精疲力竭，他意识到自己无法独自完成任务。与其让自己的侦察成果随自己而去，他向任何愿意打击盘踞在沉没大厅中的黑暗势力的路过的部落勇士寻求帮助。"},{t="深渊的祭品",b="这项任务的目标是梦游者克尔里斯，他是暮光之锤邪教徒的首领，这些邪教徒已经在废墟般的月神殿中扎下根来。克尔里斯与当地的纳迦结盟，在受亵渎的月亮井上进行黑暗仪式，将活着的俘虏喂给阿库麦尔——一头贪婪的多头蛇，也是上古之神的野兽——以此疯狂追求宇宙力量和原始混沌。"},{t="带给雷霆崖的消息",b="银色黎明曾一度认为克尔里斯已死或失踪，因此确认他的死讯至关重要。与其强迫英雄们回到人类领土，塞尔瑞德指示将这名邪教领袖死亡的证明交给雷霆崖长者高地的巴珊娜·符文图腾。巴珊娜与大地母亲的自然平衡有着深刻的感应，她赞扬了这一胜利，因为这消除了意图将卡利姆多拖入原始废墟的邪恶腐化。"}},faq={{q="谁是梦游者克尔里斯？",a="克尔里斯是占领了黑暗深渊的暮光之锤邪教徒的首领。银色黎明曾以为他已死或失踪，但他却一直在受腐化的月亮井中通过向古老多头蛇阿库麦尔献上活祭来秘密积蓄力量。",al={"克尔里斯","谁是克尔里斯","梦游者克尔里斯"}},{q="为什么会有银色黎明成员在黑暗深渊里？",a="银月守卫塞尔瑞德前来调查这座暗夜精灵废墟神庙中日益增长的威胁。他被其中的居民击溃且身受重伤，被困在此地，必须依靠路过的冒险者来完成他的职责并消灭克尔里斯。",al={"银月守卫塞尔瑞德","为什么塞尔瑞德在这里","银色黎明在黑暗深渊"}},{q="阿库麦尔是什么？",a="阿库麦尔是一头巨大的古老多头蛇，被认为是上古之神的原始仆从。它沉睡在沉没的废墟之下，当深层的地下腐化污染了神庙的神圣水域时，它苏醒了，现在它吞噬着由暮光之锤送来的俘虏。",al={"阿库麦尔","谁是阿库麦尔","阿库麦尔背景故事"}},{q="为什么要将任务提交给巴珊娜·符文图腾？",a="塞尔瑞德指引部落勇士前往雷霆崖长者高地寻找巴珊娜·符文图腾。作为大地母亲平衡的守护者，巴珊娜与对抗古老邪恶的防御者们保持联系，并将克尔里斯对上古之神的崇拜视为卡利姆多上令人憎恶的祸害。",al={"巴珊娜·符文图腾","为什么在雷霆崖","黑暗深渊的邪恶任务去哪交"}},{q="黑暗深渊的废墟发生了什么？",a="很久以前，这个地下建筑群是一座供奉月亮女神艾露恩的神圣神庙。大灾变和来自地底的古老黑暗渗漏污染了宏伟的月亮井，使纳迦和末日邪教徒得以将这些沉没的圣所据为己有，献给他们黑暗的主人阿库麦尔。",al={"黑暗深渊的历史","艾露恩神庙废墟","为什么黑暗深渊被腐化了"}},{q="暮光之锤邪教在此的目标是什么？",a="暮光之锤试图通过崇拜上古之神将世界带回原始混沌的时代。克尔里斯寻求通过黑暗交流获得个人力量，将无辜者投入深渊以换取古老实体的青睐。",al={"暮光之锤的动机","为什么邪教在黑暗深渊","克尔里斯的目标"}}},fp="20,210,22.316.0,22.295.0,21.314.1,28.228.0,54.228.0,16.230.0,43.250.0,48.253.0,52.211.0"}
P.entries["quest:65610"] = {n="Wish You Were Here",s="一位月布制作者请你前往灰谷的坠星湖寻找Krilge。曾与他并肩服役的人称他为逃兵，但制作者相信他并未擅离岗位。",h="一位月布制作者请你前往灰谷的坠星湖寻找Krilge。曾与他并肩服役的人称他为逃兵，但制作者相信他并未擅离岗位。",kw={"灰谷","沼泽兽","逃兵","坠星湖","甘鲁尔·血眼","克里格","失踪","月布"},sec={{t="失踪的朋友",b="制作者在灰谷制作月布时结识了Krilge。Krilge奉命驻守当地保护平民，之后却失踪了。他们常在坠星湖相会，直到凶猛的沼泽兽占据了那里。制作者仍希望查明他的下落。"},{t="湖畔寻踪",b="有人请你调查坠星湖，并将发现报告给奥格瑞玛的甘鲁尔·血眼。此番搜寻或许能找到Krilge的踪迹，他的战友已经不再寻找他了。"}},faq={{q="克里奇是谁？",a="克里奇曾驻守灰谷保护平民，后来失踪了。他和月布制作者常在坠星湖相会。",al={"克里格","月布制作者失踪的朋友"}},{q="为什么克里奇被称为逃兵？",a="克里奇从岗位上失踪后，曾与他并肩服役的人不再寻找他，并认定他是逃兵。",al={"克里格逃兵","他们为何不再寻找"}},{q="是谁请你寻找克里奇？",a="一位在灰谷结识克里尔格的月布制作者请你寻找他的踪迹。",al={"是谁派我来的","月布制作者"}},{q="克里尔格和制作者在哪里见面？",a="在凶猛的沼泽兽占据该地之前，他们常在灰谷的坠星湖相会。",al={"克里格会面地点","坠星湖在哪里"}},{q="你应该把发现报告给谁？",a="有人请你将发现报告给奥格瑞玛的甘鲁尔·血眼。",al={"向甘鲁尔报告","我该向谁报告"}}},fp="18,169,16.258.0,11.205.0,14.134.0,38.99.0,32.83.0,36.110.0,38.71.0"}
P.entries["quest:6562"] = {n="帮助耶努萨克雷",s="“深渊中的麻烦”是一项从石爪山脉发出的求援呼吁，目标直指遥远的灰谷海岸。苏纳曼指引部落的冒险者前往佐拉姆加前哨站寻找巨魔学者耶努萨克雷，并警告说海岸边潜伏着危险的势力。",h="“深渊中的麻烦”是一项从石爪山脉发出的求援呼吁，目标直指遥远的灰谷海岸。苏纳曼指引部落的冒险者前往佐拉姆加前哨站寻找巨魔学者耶努萨克雷，并警告说海岸边潜伏着危险的势力。",kw={"灰谷","黑暗深渊","耶努萨克雷","石爪山脉","苏纳曼","狂风峭壁","佐拉姆海岸","佐拉姆加前哨站"},ang={["class:Shaman"]="佐拉姆海岸波涛下的骚动威胁到了当地水之灵的平衡，需要精神上的洞察力来净化这种腐朽。",["faction:Horde"]="在佐拉姆加前哨站坚守阵地，对于保卫卡利姆多的西侧防线免受暗夜精灵部队和海岸恐怖的侵害至关重要。",["race:Troll"]="响应耶努萨克雷的呼唤为暗矛部族的族人提供了一个至关重要的机会，去协助他们最杰出的学者之一揭开远古卡利姆多的谜团。"},sec={{t="海岸的召唤",b="在石爪山脉干旱的峭壁上，苏纳曼察觉到北方传来的黑暗隆隆声不容忽视。他派遣有能力的部落旅人穿过灰谷——暗夜精灵的祖传林地——去与耶努萨克雷取得联系。耶努萨克雷驻扎在被称为佐拉姆海岸的遥远西缘的佐拉姆加前哨站，他发现自己正面临着需要外界干预的日益严重的危险。"},{t="通往佐拉姆海岸之路",b="对于部落的旅人来说，抵达灰谷的西海岸并非易事。无论是穿过地精出没的狂风峭壁隘口，还是从贫瘠之地向北出发，旅人们都必须进入由暗夜精灵哨兵严密守卫的敌对森林。穿过密集的树冠，在那被风暴冲刷的佐拉姆海岸上，这座孤零零的前哨站正一边窥视着附近阴影笼罩的水域，一边苦苦支撑。"},{t="波涛下的低语",b="抵达海岸后，耶努萨克雷揭示了正在酝酿的麻烦根源于黑暗深渊的地下神庙。古老的腐蚀、邪恶的水元素和暮光之锤的邪教徒们聚集在潮汐之下，诱使远古邪恶重返世界。耶努萨克雷依靠前来的勇士深入地表之下，直面在那沉没大厅中被唤醒的原始恐怖。"}},faq={{q="谁给予了任务“深渊中的麻烦”？",a="位于石爪山脉的苏纳曼提供了这项任务。他意识到灰谷海岸线的盟友需要增援，并指引旅行中的部落冒险者前往大海。",al={"任务发布者","谁开启深渊中的麻烦","苏纳曼"}},{q="耶努萨克雷在哪里？",a="耶努萨克雷驻扎在佐拉姆海岸的佐拉姆加前哨站，位于灰谷最西端的海岸线上。",al={"耶努在哪里","耶努萨克雷位置","佐拉姆加前哨站"}},{q="如何从石爪山脉到达佐拉姆加前哨站？",a="旅人可以向东北穿过狂风峭壁进入灰谷，或者向东绕过贫瘠之地并从南面进入森林。从灰谷中部出发，径直向西走，直到到达佐拉姆海岸的开阔水域。",al={"通往灰谷的路径","如何前往佐拉姆海岸","从石爪山脉到灰谷的路线"}},{q="耶努萨克雷在调查什么麻烦？",a="耶努萨克雷正在监视附近的黑暗深渊废墟，那里的邪教徒和受腐蚀的水生实体正在地表之下搅动远古恐怖。",al={"佐拉姆海岸发生了什么","为什么耶努需要帮助"}},{q="“深渊中的麻烦”后续任务是什么？",a="与耶努萨克雷交谈将直接引出“阿库麦尔的精华”，该任务会派遣冒险者进入黑暗深渊，从其隧道中收集被元素充能的阿库麦尔蓝宝石。",al={"下一个任务","深渊中的麻烦后续"}},{q="为什么穿越灰谷的旅程被认为是危险的？",a="灰谷是暗夜精灵的领地，他们会激烈抵制任何部落的入侵。穿过林地的旅人面临着遭遇敌对哨兵和隐秘伏击者的风险。",al={"灰谷的危险","暗夜精灵威胁"}}},fp="20,192,22.271.0,24.383.0,24.318.1,41.99.0,32.99.0,51.196.0,37.144.0,40.120.0,57.133.0"}
P.entries["quest:6563"] = {n="阿库麦尔水晶",s="位于佐拉姆加前哨站的耶努萨克雷发现，黑暗深渊的娜迦正在洞穴中采集威力强大的蓝宝石簇。出于对这些宝石所蕴含的魔法属性和元素水能量的担忧，这位萨满委托部落冒险者在这些宝石被滥用之前将其回收。",h="位于佐拉姆加前哨站的耶努萨克雷发现，黑暗深渊的娜迦正在洞穴中采集威力强大的蓝宝石簇。出于对这些宝石所蕴含的魔法属性和元素水能量的担忧，这位萨满委托部落冒险者在这些宝石被滥用之前将其回收。",kw={"灰谷","黑暗深渊","耶努萨克雷","娜迦","阿库麦尔蓝宝石","深渊中的麻烦","水之灵","佐拉姆海岸"},ang={["class:Shaman"]="耶努萨克雷对水晶的解读揭示了束缚在其中的躁动不安的水之灵，这是一种微妙的警告，表明元素力量正在神庙下方受到腐蚀。",["faction:Horde"]="部落在佐拉姆加前哨站的立足点岌岌可危；阻止附近的娜迦获取原始魔法力量有助于保护这个海岸营地。",["race:Troll"]="耶努萨克雷是一位目光敏锐的暗矛秘术师，依靠与灵魂沟通以及祖先的智慧，来应对卡利姆多面临的各种奇异威胁。"},sec={{t="深渊中的威胁",b="在雾气笼罩的佐拉姆海岸，暗矛萨满耶努萨克雷一直在监视着那些被邪恶势力侵占的古老卡多雷遗迹。在黑暗深渊淹没的洞室深处，娜迦们开始挖掘生长在潮湿洞穴壁上的鲜艳蓝宝石。萨克雷感觉到这些蛇形入侵者企图利用这种不稳定的力量，因此他试图在他们的阴谋得逞之前拦截这些战利品。"},{t="水之灵与奥术力量",b="阿库麦尔的蓝宝石绝非普通的宝石；它们搏动着元素共鸣，并依附着水之灵。在熟练的施法者手中，这些媒介能够助长危险的奥术仪式，或是增强阴影九头蛇阿库麦尔的影响力——它那黑暗的存在渗透着整个地下神庙。回收这些宝石簇不仅剥夺了娜迦宝贵的试剂，还能保护海岸线免受失控元素魔法的侵害。"}},faq={{q="谁发布了这个任务？",a="该任务由暗矛巨魔萨满耶努萨克雷发布，他驻扎在灰谷西北部的佐拉姆海岸的佐拉姆加前哨站。",al={"任务发布者","谁开启阿库麦尔的精华任务","耶努萨克雷位置"}},{q="为什么娜迦想要阿库麦尔的蓝宝石？",a="虽然他们具体的阴谋仍笼罩在迷雾之中，但这些蓝宝石拥有强大的元素水能量和原始的魔法力量，这使得它们成为娜迦施法时极其危险的试剂。",al={"娜迦为什么想要蓝宝石","水晶有什么用","蓝宝石用途"}},{q="在哪里可以找到蓝宝石簇？",a="它们分布在黑暗深渊外部隧道和被淹没通道的洞穴壁和地面上，就在佐拉姆海岸沿线那被毁坏的地下入口内部。",al={"去哪里找蓝宝石","阿库麦尔的蓝宝石位置","水晶刷新点"}},{q="阿库麦尔是什么？",a="阿库麦尔是一头居住在被淹没的神庙遗迹深处的巨大三头九头蛇。它受到暮光之锤教徒的崇拜，并作为上古之神的仆从而令人恐惧。",al={"阿库麦尔是谁","阿库麦尔是什么","阿库麦尔"}},{q="这个任务需要击杀地下城首领吗？",a="不需要。蓝宝石簇生长在早期被淹没的洞穴墙壁上，在遇到黑暗深渊的主要首领之前就可以找到。",al={"需要组满队伍吗","可以单人完成蓝宝石收集吗","首领击杀要求"}},{q="这个任务与其他剧情有关联吗？",a="是的。它紧随“深渊中的麻烦”任务，是耶努萨克雷对黑暗深渊内不断滋生的黑暗和邪教活动调查的一部分。",al={"任务链","前置任务","深渊中的麻烦"}}},fp="22,160,22.319.0,30.364.0,21.129.0,46.137.0,38.185.0,16.158.0,52.117.0,47.151.0"}
P.entries["quest:6564"] = {n="上古之神的仆从",s="“忠于古神”是一个部落任务，可以通过从黑暗深渊内的娜迦身上找回一份浸水的便笺来触发。将这份便笺交给佐拉姆加前哨站的耶努萨克雷，会揭开一个在黑暗深渊被淹没的遗迹深处酝酿的邪恶仪式阴谋。",h="“忠于古神”是一个部落任务，可以通过从黑暗深渊内的娜迦身上找回一份浸水的便笺来触发。将这份便笺交给佐拉姆加前哨站的耶努萨克雷，会揭开一个在黑暗深渊被淹没的遗迹深处酝酿的邪恶仪式阴谋。",kw={"阿库麦尔","效忠","灰谷","黑暗深渊","潮湿的便笺","耶努萨克雷","洛古斯·杰特","古神","怒鳞","佐拉姆加前哨站"},ang={["class:Shaman"]="娜迦在仪式水晶中奴役水元素灵魂代表着对自然平衡的严重扭曲，需要迅速予以纠正。",["faction:Horde"]="发现洛古斯·杰特的便笺有助于保护佐拉姆加前哨站免受暮光之锤及其娜迦盟友的侵害，这些敌人威胁着部落在灰谷西海岸的立足点。",["race:Troll"]="协助你的暗矛同胞耶努萨克雷将揭开那些古老宇宙实体的真面目，它们的回归将威胁到艾泽拉斯的每一个部族。"},sec={{t="潦草的声明",b="在与黑暗深渊的娜迦战斗时，部落侦察兵发现了一份潮湿、皱巴巴的便笺，上面有着狂乱的笔迹。这份潦草的羊皮纸详细记录了针对娜迦女祭司的指令，命令她们收集水元素水晶。这些水晶绝非随意掠夺而来，而是被收集起来为娜迦水术士的召唤提供能量，汇集元素力量以达到更黑暗的目的。"},{t="深渊的低语",b="找回的命令显示，娜迦打算利用水晶中的元素能量来安抚并完全召唤阿库麦尔，这是一头侍奉古神的怪物多头蛇。便笺大胆地宣称，这样做将预示着世界“最伟大时代”的回归——即古神统治的史前时代。在佐拉姆加前哨站收到这份羊皮纸后，暗矛秘术师耶努萨克雷指出了这场阴谋背后的始作俑者：暮光之锤教徒洛古斯·杰特。"}},faq={{q="什么是潮湿的便笺？",a="潮湿的便笺是一份由暮光之锤教徒洛古斯·杰特所写的被找回的命令。它指示娜迦女祭司收集注入元素的水晶，以加强她们的水术士并召唤怪物仆从阿库麦尔。",al={"潮湿的便笺","便笺上写了什么","便笺背景知识"}},{q="耶努萨克雷是谁？",a="耶努萨克雷是一位驻扎在灰谷佐拉姆加前哨站的暗矛巨魔先知兼学者。作为大地之环的代表，他正在调查附近的黑暗深渊遗迹中涌现的元素失衡和古老威胁。",al={"耶努萨克雷","耶努是谁","佐拉姆加任务发布者"}},{q="洛古斯·杰特是谁？",a="洛古斯·杰特是一位在黑暗深渊内活动的暮光之锤教派的人类萨满，教徒们在那里与娜迦结盟。他负责监督元素水晶的采集工作，以增强娜迦的仪式并唤醒黑暗的古老恐惧。",al={"洛古斯·杰特","谁写了便笺","佐拉姆娜迦首领"}},{q="阿库麦尔是什么？",a="阿库麦尔是一头居住在黑暗深渊淹没深处的巨大三头多头蛇。这只生物与古神的原始黑暗紧密相连，受到暮光之锤教派和黑暗深渊娜迦的崇拜。",al={"阿库麦尔","阿库麦尔是谁","阿库麦尔背景知识"}},{q="娜迦为什么要收集水元素水晶？",a="被困在水晶中的水元素灵魂为娜迦水术士提供了原始力量。通过汲取这种元素魔法，他们希望能安抚阿库麦尔，并聚集足够的力量迎来古神的回归。",al={"为什么娜迦需要水晶","娜迦元素水晶","水术士水晶"}},{q="这个任务链通向哪里？",a="将便笺交给耶努萨克雷会直接开启一个后续任务，该任务要求追踪并处决洛古斯·杰特，以破坏教派在黑暗深渊的仪式计划。",al={"忠于古神后续任务","忠于古神第二部分","下一个任务"}}},fp="26,141,23.300.0,20.366.1,22.211.0,22.207.0,19.213.0,16.198.0,43.195.0,33.152.1"}
P.entries["quest:6565"] = {n="上古之神的仆从",s="“效忠上古之神”是一个部落任务，要求冒险者前往黑暗深渊的深处消灭洛古斯·杰特。该任务由佐拉姆加前哨站的暗矛巨魔先知耶努萨克雷发布，旨在打击试图唤醒远古破坏力量的暮光之锤邪教徒。击败洛古斯将对邪教在灰谷海岸下的颠覆性行动给予直接打击。",h="“效忠上古之神”是一个部落任务，要求冒险者前往黑暗深渊的深处消灭洛古斯·杰特。该任务由佐拉姆加前哨站的暗矛巨魔先知耶努萨克雷发布，旨在打击试图唤醒远古破坏力量的暮光之锤邪教徒。击败洛古斯将对邪教在灰谷海岸下的颠覆性行动给...",kw={"效忠上古之神","灰谷","黑暗深渊","耶努萨克雷","洛古斯·杰特","上古之神","暮光之锤","佐拉姆加"},ang={["class:Shaman"]="暮光之锤试图通过侍奉混乱的上古之神来释放元素的愤怒，这使得铲除他们成为了那些发誓要与大地之环共同维护元素平衡之人的优先事项。",["faction:Horde"]="消灭洛古斯·杰特巩固了佐拉姆加前哨站的周边防御，保护了部落在灰谷这座孤立的沿海营地免受邪教徒阴险阴谋的侵害。",["race:Troll"]="协助耶努萨克雷不仅能保护艾泽拉斯的原始精神，也是对这位远在回音群岛之外努力工作的受人尊敬的暗矛先知的智慧表示敬意。"},sec={{t="佐拉姆加之下的威胁",b="坐落在灰谷海岸边的部落前哨站佐拉姆加，时刻保持着对黑暗深渊的警惕。这座被淹没的寺庙建筑群已沦为黑暗魔法的滋生地，到处都是娜迦、受腐蚀的野兽以及披着斗篷的暮光之锤狂热信徒。驻扎在海岸边的大地之环先知耶努萨克雷敏锐地察觉到，这些邪教徒并不敬畏自然的平衡或大地之灵。相反，他们宣誓效忠于上古之神——那些在远古时代被击败、充满混乱的怪物，而它们邪恶的触须至今仍残留在艾泽拉斯那些被遗忘的角落。"},{t="终结洛古斯·杰特",b="耶努指派部落的勇士潜入地下废墟，搜寻并消灭邪教高层中的关键人物洛古斯·杰特。洛古斯活动在巨龟加摩拉和水元素阿奎尼斯男爵之间的石质走廊深处。耶努本人因年迈体衰无法亲自深入那潮湿黑暗的洞穴，因此除掉洛古斯对于切断邪教徒在灰谷浪潮下试图策划的任何黑暗仪式至关重要。"},{t="遏制混乱",b="随着洛古斯·杰特的死亡，对海岸直接造成的仪式性威胁已被控制，但耶努深知暮光之锤远未被彻底根除。邪教在古老圣地的悄然渗透预示着一场更大、更阴险的危机正在蔓延，其目的正是为了让上古之神彻底回归。对于驻扎在佐拉姆加的部落而言，击败洛古斯为对抗这些潜伏在世界阴影中的敌人争取了宝贵的时间。"}},faq={{q="洛古斯·杰特是谁？",a="洛古斯·杰特是盘踞在黑暗深渊中的暮光之锤邪教徒的重要头目之一。他指挥着旨在迎接远古上古之神回归与统治的邪教仪式。",al={"洛古斯·杰特","洛古斯是谁","洛古斯·杰特背景故事"}},{q="在黑暗深渊哪里可以找到洛古斯·杰特？",a="洛古斯·杰特在黑暗深渊被淹没的走廊中巡逻，具体位于加摩拉的巢穴和阿奎尼斯男爵的祭坛区域之间的通道内。",al={"洛古斯·杰特位置","洛古斯在哪里","寻找洛古斯·杰特"}},{q="耶努萨克雷是谁？",a="耶努萨克雷是一名隶属于大地之环的暗矛巨魔先知，驻扎在灰谷佐拉姆海岸的佐拉姆加前哨站，负责监视元素骚乱以及黑暗深渊中的腐化。",al={"耶努萨克雷","谁发布效忠上古之神","耶努"}},{q="为什么耶努会关注暮光之锤？",a="作为一名致力于理解自然与元素平衡的先知，耶努将暮光之锤视为一种生存威胁。该邪教侍奉上古之神，那是充满混乱的远古存在，它们的回归将摧毁世界的和谐。",al={"为什么要对抗暮光之锤","大地之环上古之神"}},{q="什么是上古之神？",a="上古之神是代表混乱与毁灭的太古存在，在远古时代统治过艾泽拉斯，随后被击败并封印。暮光之锤邪教一直在崇拜它们，密谋打破封印，让它们那充满毁灭性的统治重现世间。",al={"上古之神背景故事","上古之神是什么","混乱生物"}},{q="为什么耶努萨克雷不能亲自去杀死洛古斯·杰特？",a="耶努承认自己年迈体衰，无法独自面对黑暗深渊中的危险，因此他只能依靠强大的部落勇士去战斗，而他自己则留在前哨站追踪精神和元素的波动。",al={"为什么耶努不去","耶努体弱吗"}}},fp="26,239,28.446.0,18.398.0,17.332.1,19.168.0,52.141.0,22.201.0,49.212.0,22.243.0,50.156.0"}
P.entries["quest:6568"] = {n="幻术的欺诈",s="雷克萨说，想要潜入黑龙军团的防线，需要用到幻象。他认识一位幻术大师，即住在西瘟疫之地的巫女麦兰达，并让你带一封信给她。",h="雷克萨说，想要潜入黑龙军团的防线，需要用到幻象。他认识一位幻术大师，即住在西瘟疫之地的巫女麦兰达，并让你带一封信给她。",kw={"黑龙军团","凄凉之地","幻象","欺诈大师","巫女麦兰达","雷克萨","悔恨岭","雷克萨的遗嘱","西瘟疫之地"},sec={{t="幻术的艺术",b="雷克萨问你对幻象了解多少，因为你必须依靠幻象来绕过黑龙军团的防线。他提到了一个可以协助你进行伪装的人：巫女麦兰达，一位被洛丹伦联盟驱逐的幻术大师，现居住在西瘟疫之地。雷克萨说，只要她认为值得，她以前就曾帮助过他的族人。你带着他的信去找她。"},{t="洛丹伦的访客",b="麦兰达评论说，部落成员在洛丹伦的这一带很少见，她询问你带了什么给她。"},{t="麦兰达的回答",b="麦兰达拿着便条，停顿了一下，微笑了。她询问雷克萨的情况，然后解释说这张纸之所以是空白的，是因为写信人的意图都在这上面。她明白雷克萨为什么不写上字，因为如果你在途中被俘虏或杀害，这些内容可能会带来危险。她同意帮助你，因为她欠大酋长一个人情。"}},faq={{q="巫女麦兰达是谁？",a="巫女麦兰达是一位幻术大师，曾属于洛丹伦，后被联盟驱逐。她位于西瘟疫之地的悔恨岭。",al={"麦兰达是谁","巫女麦兰达背景故事","麦兰达在哪里"}},{q="为什么要寻找幻术师？",a="雷克萨说，你必须依靠幻象来绕过黑龙军团的防线，他认识一位可以提供帮助的大师。",al={"为什么要伪装","为什么要寻找幻术师","欺骗黑龙军团"}},{q="雷克萨让你去哪儿？",a="他让你前往西瘟疫之地，在悔恨岭找到巫女麦兰达。",al={"我该去哪里","悔恨岭在哪里","欺诈大师目的地"}},{q="麦兰达以前帮助过部落吗？",a="雷克萨说，只要她认为事业值得，她以前就曾帮助过他的族人。",al={"麦兰达喜欢部落吗","麦兰达是联盟还是部落","麦兰达与大酋长的人情"}}},fp="23,150,19.293.0,22.121.0,16.334.1,23.136.0,37.105.0,27.83.0,36.82.0"}
P.entries["quest:657"] = {n="新的瘟疫？",s="奎艾翻阅了文件夹，得知药剂师乔瑞尔正在格沙克农场进行致命的实验。奎艾在与兽人冲突后状态不佳，无法帮助基恩洛。基恩洛前往农场窃取尚未送往塔伦米尔的乔瑞尔的研究成果时，需要你的保护。",h="奎艾翻阅了文件夹，得知药剂师乔瑞尔正在格沙克农场进行致命的实验。奎艾在与兽人冲突后状态不佳，无法帮助基恩洛。基恩洛前往农场窃取尚未送往塔伦米尔的乔瑞尔的研究成果时，需要你的保护。",kw={"药剂师乔瑞尔","被遗忘者","格沙克农场","基恩洛","费恩","瘟疫","奎艾","塔伦米尔"},sec={{t="乔瑞尔的实验",b="奎艾翻阅了文件夹，发现药剂师乔瑞尔正在格沙克农场进行致命的实验。奎艾并不清楚这与希尔斯布莱德有什么关系，但费恩一定不希望这种事继续下去。乔瑞尔的一些研究成果已经被送往了塔伦米尔。"},{t="基恩洛的保护者",b="在你离开期间，奎艾与一些兽人发生了冲突，现在的状态无法帮助基恩洛。基恩洛打算前往农场窃取乔瑞尔尚未送往塔伦米尔的研究成果，她需要保护。你去和基恩洛谈谈吧。"},{t="基恩洛的决心",b="基恩洛说，如果能让费恩获得安宁，她会亲手消灭每一个被遗忘者。自从瘟疫爆发以来，费恩为基恩洛和其他人做了很多事，他们本以为再也找不到朋友或家人了。基恩洛让你准备好后告诉她，你们俩马上就会出发。"}},faq={{q="为什么奎艾不能陪同基恩洛？",a="奎艾在你离开期间与一些兽人发生了冲突，现在的状态无法帮助基恩洛。",al={"为什么奎艾留在这里","为什么奎艾不帮忙","为什么要独自护送基恩洛"}},{q="文件夹里发现了什么？",a="药剂师乔瑞尔一直在格沙克农场进行致命的实验。",al={"文件夹里有什么","乔瑞尔的实验","乔瑞尔在做什么"}},{q="为什么奎艾和基恩洛要调查这件事？",a="她们是费恩的同伴，费恩领导着一群调查异常事件的冒险者。费恩不希望乔瑞尔的实验继续下去。",al={"费恩是谁","为什么他们关心瘟疫","为什么要帮助费恩"}},{q="研究成果被送往哪里？",a="一部分已经被送往了塔伦米尔。基恩洛计划窃取乔瑞尔尚未送出的那部分。",al={"笔记被送往哪里","塔伦米尔的研究"}}},fp="22,186,20.228.0,20.209.0,18.318.1,34.78.0,34.74.0,45.159.0,33.107.0"}
P.entries["quest:6571"] = {n="战歌氏族的补给品",s="“战歌补给”是一个由位于碎木岗哨的洛克·奥卡尔发放的部落大型后勤任务。为了维持战歌伐木营地的正常运转，必须收回散落在充满敌意的熊怪和萨特领地中的重要伐木装备，同时还需要从遥远的地精港口获取进口物资。",h="“战歌补给”是一个由位于碎木岗哨的洛克·奥卡尔发放的部落大型后勤任务。为了维持战歌伐木营地的正常运转，必须收回散落在充满敌意的熊怪和萨特领地中的重要伐木装备，同时还需要从遥远的地精港口获取进口物资。",kw={"灰谷","藏宝海湾","洛克·奥卡尔","伐木绳","皮克希尔","锯条","碎木岗哨","战歌伐木营地","战歌之油","战歌补给"},ang={["faction:Horde"]="部落在杜隆塔尔的扩张完全取决于战歌氏族提供的木材。收回这些工具直接巩固了奥格瑞玛的根基。",["profession:Engineering"]="这批货物中的地精组件凸显了采伐古老森林所必需的基础机械供应链——从皮克希尔的锯条到蒸汽引擎润滑油。",["race:Orc"]="为了战歌氏族在灰谷的荣耀，必须让他们的斧头保持锋利，并保证营地的补给充足，尽管要面对来自森林原住民的不断骚扰。"},sec={{t="让锯子转起来",b="战歌氏族在灰谷采伐古老木材的行动需要源源不断的重型工具供应。部落军需官们在碎木岗哨的前哨基地面临着持续不断的补给中断问题。洛克·奥卡尔负责确保伐木营地的装备齐全，但当地的货物运送遭到了本土生物和恶魔邪教徒的劫掠而损失殆尽，导致该行动急需关键装备。"},{t="分散的后勤链",b="获取所需的设备是一项艰巨的任务，范围覆盖了大部分卡利姆多，甚至跨越了海洋。圆锯片在碎木岗哨的地精信使皮克希尔那里等待领取，而一箱重型斧头则需要去藏宝海湾的码头管理员罗兹基尔那里领取。其余的基本物资必须直接从敌人手中夺回：被充满敌意的黑木熊怪和蓟皮熊怪抢走的坚固伐木绳，以及被夜道谷、萨维亚和萨提纳尔的萨特偷走用于其亵渎仪式的战歌之油桶。"}},faq={{q="所需的战歌补给有哪些？",a="洛克·奥卡尔需要四种基本物品：地精皮克希尔持有的战歌锯条、运往藏宝海湾的一箱战歌之斧、当地熊怪劫掠的重型伐木绳，以及被灰谷的萨特偷走的战歌之油桶。",al={"战歌补给清单","需要什么物品","需要的补给"}},{q="洛克·奥卡尔是谁？",a="洛克·奥卡尔是一名驻扎在碎木岗哨的兽人，负责协调向战歌伐木营地的物资运送。为了避免行动延误，他承受着巨大的压力，于是他招募往来的部落冒险者来找回他散失的货物。",al={"洛克·奥卡尔背景","谁发放战歌补给任务","碎木岗哨任务发布者"}},{q="为什么部落要从藏宝海湾运送装备？",a="部落依赖热砂港这样的中立贸易网络来进口杜隆塔尔和贫瘠之地无法轻易大量锻造的特种制成品。通过地精渠道订购的重型伐木斧会通过藏宝海湾这样的海运枢纽，最后才能到达灰谷。",al={"为什么是藏宝海湾","藏宝海湾的斧头货物","热砂港工具"}},{q="为什么萨特需要战歌之油？",a="居住在萨提纳尔、夜道谷和萨维亚等遗迹中的萨特并没有将这些工业用油用于机械，而是将其转用于献给燃烧军团的黑暗腐化仪式，以及加剧费伍德森林的污染。",al={"萨特之油背景","为什么萨特会有油","战歌之油仪式"}},{q="是哪些熊怪偷走了伐木绳？",a="伐木绳是被黑木熊怪和蓟皮熊怪部落伏击并夺走的。这两个部落对部落在灰谷进行的皆伐作业怀有强烈的领土敌意。",al={"谁偷了绳子","熊怪抢劫绳子背景","黑木蓟皮熊怪绳子"}},{q="为什么战歌伐木营地对部落如此重要？",a="杜隆塔尔的干旱土地几乎无法提供可用于建筑的木材。战歌氏族被部署到灰谷郁郁葱葱的边境地区，专门为了采伐建造奥格瑞玛和为部落日益增长的军事基础设施提供燃料所需的巨大树木。",al={"为什么要开发灰谷","战歌伐木营地的重要性","兽人伐木"}}},fp="16,175,25.277.0,27.361.0,39.194.0,19.186.0,51.263.0,35.173.0,38.139.0,53.281.0"}
P.entries["quest:658"] = {n="新的瘟疫？",s="奎艾和金已经监视格沙克农场好几天了。金看到一名信使从南边的一间小屋里走出来，他们怀疑那名信使带着要送往塔伦米尔的笔记。奎艾想要那些文件，并询问你是否是一名熟练的追踪者。",h="奎艾和金已经监视格沙克农场好几天了。金看到一名信使从南边的一间小屋里走出来，他们怀疑那名信使带着要送往塔伦米尔的笔记。奎艾想要那些文件，并询问你是否是一名熟练的追踪者。",kw={"药剂师","阿拉希高地","被遗忘者信使","格沙克农场","金","费恩·奥德利克","奎艾","密封的信件","塔伦米尔"},sec={{t="监视农场",b="奎艾对费恩·奥德利克派你来查看他们的状况并不感到惊讶，因为费恩总是杞人忧天。奎艾和金已经监视农场好几天了。不久前，金看到一名信使从南边的一间小屋里走出来。金虽然话多，但奎艾总是信任金在危险区域的感知能力。"},{t="信使的文件夹",b="奎艾询问你是否是一名熟练的追踪者。那名信使可能带着要送往塔伦米尔的笔记，弄到这些文件或许能揭示希尔斯布莱德正在发生的事情。你要找到被遗忘者信使，并将她的密封的信件带回给格沙克农场附近的奎艾。当你搜索时，金发现一名药剂师也离开了那间屋子。奎艾确信那个药剂师没安好心，但在有人做出鲁莽举动之前，需要证据。"}},faq={{q="是谁派你来找奎艾和金的？",a="费恩·奥德利克派你来查看他们的状况，奎艾对此并不感到惊讶，因为费恩总是杞人忧天。",al={"谁派我去找奎艾","谁开启了新的瘟疫的迹象任务","费恩·奥德利克任务"}},{q="信使是从哪里出来的？",a="金看到信使从南边的一间小屋里走出来。",al={"信使从哪里来","信使位置","农场南边的屋子"}},{q="信使要去哪里？",a="奎艾和金怀疑信使带着要送往塔伦米尔的笔记。",al={"信使目的地","信使要去哪里"}},{q="你要找回什么物品？",a="被遗忘者信使的密封的信件，要将其带回给格沙克农场附近的奎艾。",al={"信使有什么物品","密封的信件"}},{q="还有谁在那间屋子被发现？",a="在你离开时，金发现一名药剂师也离开了那间位于南边的屋子。",al={"农场的药剂师","谁从屋子里出来"}},{q="为什么奎艾想要这些文件？",a="它们可能有助于了解希尔斯布莱德正在发生的事情，在有人做出鲁莽举动之前，奎艾需要证据。",al={"为什么要获取文件","这些笔记是做什么用的"}}},fp="22,215,17.252.0,20.399.0,34.93.0,32.53.0,29.69.0,35.69.0,34.83.0,33.109.0"}
P.entries["quest:6581"] = {n="战歌锯条",s="“战歌锯条”是部落在碎木岗哨进行的一项差事，旨在支持战歌氏族的伐木行动。为了获得从棘齿城进口的重型锯条，冒险者必须与信使皮克希尔达成一笔私下交易，她要求在交出货物前获得人身保护。完成这笔交易可以确保部落在灰谷的伐木场顺利运转所需的关键机械设备。",h="“战歌锯条”是部落在碎木岗哨进行的一项差事，旨在支持战歌氏族的伐木行动。为了获得从棘齿城进口的重型锯条，冒险者必须与信使皮克希尔达成一笔私下交易，她要求在交出货物前获得人身保护。完成这笔交易可以确保部落在灰谷的伐木场顺利...",kw={"灰谷","致命的短枪","皮克希尔","棘齿城","碎木岗哨","战歌氏族","战歌锯条","战歌补给品"},ang={["faction:Horde"]="灰谷的伐木营地为奥格瑞玛的扩张提供了至关重要的结构骨干，使得每一批机械的运送对部落在卡利姆多的生存都至关重要。",["profession:Engineering"]="皮克希尔要求的“致命的短枪”是熟练工匠的主要产品，凸显了地精和凡人的工程学如何推动前线战争的后勤工作。",["race:Orc"]="战歌氏族在格罗玛什·地狱咆哮的领导下将他们的骄傲寄托在对灰谷的伐木上；让他们的工业锯条持续运转，是对该氏族在森林中继续立足的尊重。"},sec={{t="信使的精明易货",b="灰谷的战歌伐木工完全依赖进口的重型机械来砍伐深林中的古老树木。虽然皮克希尔已经成功地将一批特制的锯条直接从地精港口棘齿城运到了碎木岗哨，但她无意免费交出它们。在灰谷危机四伏的野外，金币的价值有限，而人身安全则要珍贵得多。皮克希尔没有索要金币，而是坚持用重型锯条换取一把可靠的“致命的短枪”，以确保她在危险的敌对领土旅行时的安全。"},{t="供应战争物资",b="灰谷茂密的树冠深受部落青睐，因为杜隆塔尔和贫瘠之地的干旱平原正面临严重的木材短缺。然而，砍伐古老的哨兵之林会迅速磨损普通的斧头，使得地精锻造的工业锯条成为必需品。获得皮克希尔的这批货物将直接推动战歌伐木场的运作，确保部落能够在暗夜精灵的激烈抵抗下继续建造前哨站和战争机器。"}},faq={{q="皮克希尔是谁，为什么她会有锯条？",a="皮克希尔是一名目前驻扎在碎木岗哨的信使，她运送了一批直接来自地精港口棘齿城的工业锯条。她扣留了这批货物，直到能为自己获得一件可靠的武器以寻求保护。",al={"皮克希尔是谁","皮克希尔 碎木岗哨","锯条信使"}},{q="为什么皮克希尔想要“致命的短枪”而不是金币？",a="穿越贫瘠之地并深入灰谷的暗夜精灵领地极其危险。了解道路上的凶险，皮克希尔认为人身防御比金币更重要，因此要求获得一件工程学制造的火器来保卫她的旅途。",al={"为什么需要致命的短枪","皮克希尔枪械交易","为什么要枪"}},{q="为什么这些锯条对部落如此重要？",a="部落需要大量的木材来在卡利姆多各地建造防御工事和战争机器。标准的切割工具在灰谷古老的铁木面前很快就会磨损，因此进口的机械锯条对于战歌氏族的伐木机械至关重要。",al={"为什么需要锯条","战歌伐木的重要性","为什么需要战歌补给品"}},{q="这些锯条最初来自哪里？",a="这些锯条是在贫瘠之地东海岸的中立地精港口——棘齿城制造并运出的，随后被陆运至碎木岗哨。",al={"锯条的来源","棘齿城锯条","锯条从哪里来"}},{q="这个任务在战歌伐木行动中处于什么位置？",a="这项任务是为灰谷的伐木营地筹集战歌补给品这一更大行动的一部分。从皮克希尔手中收回锯条是维持部落伐木运作所需的关键后勤要求之一。",al={"战歌补给链","战歌锯条前置任务"}},{q="有人能制造皮克希尔想要的武器吗？",a="“致命的短枪”是由熟练的工程师使用铜管、铜栓、木质枪托和皮革制造的，不过信使和战士们也经常通过当地市场或同行冒险者来交换它们。",al={"如何获得致命的短枪","短枪来源","工程学枪械"}}},fp="18,235,25.287.0,24.331.0,50.149.0,57.158.0,51.178.0,46.79.0,58.99.0,39.200.0"}
P.entries["quest:659"] = {n="新的瘟疫？",s="费恩·奥德利克带领着一队冒险者调查该地区发生的离奇事件，他认为亡灵牵涉其中。他的两位同伴，奎艾和基恩洛，前往了阿拉希高地的格沙克农场。他们已经好几天没有消息了。",h="费恩·奥德利克带领着一队冒险者调查该地区发生的离奇事件，他认为亡灵牵涉其中。他的两位同伴，奎艾和基恩洛，前往了阿拉希高地的格沙克农场。他们已经好几天没有消息了。",kw={"阿拉希高地","格沙克农场","希尔斯布莱德丘陵","基恩洛","费恩·奥德利克","奎艾","斯坦利"},sec={{t="离奇事件",b="不久前，费恩在希尔斯布莱德的表亲不得不除掉了他的狗斯坦利。那头野兽离奇地肿胀到了巨大的体型，并疯狂地攻击任何靠近的人。费恩认为亡灵与这些离奇事件有关，该团队正在寻找证据以证明这一点。"},{t="失踪的同伴",b="奎艾和基恩洛是费恩的两名同伴，他们前往了阿拉希高地的格沙克农场，已经好几天没有消息了。费恩非常担心，希望你能去农场附近找到他们。"}},faq={{q="费恩·奥德利克是谁？",a="费恩带领着一队冒险者，正在调查该地区发生的离奇事件。",al={"费恩·奥德利克","谁暗示了新瘟疫","任务发布者"}},{q="斯坦利怎么了？",a="斯坦利是费恩在希尔斯布莱德的表亲的狗。那头野兽离奇地肿胀到了巨大的体型，并疯狂地攻击任何靠近的人，所以他的表亲除掉了它。",al={"狗斯坦利","这条狗发生了什么","希尔斯布莱德的斯坦利"}},{q="奎艾和基恩洛应该在哪里？",a="在阿拉希高地的格沙克农场附近，他们出发前往了那里。费恩已经好几天没收到他们的消息了。",al={"奎艾在哪里","基恩洛在哪里","奎艾的位置","寻找奎艾"}},{q="费恩为什么要进行调查？",a="费恩认为亡灵牵涉到了该地区的离奇事件中，而他的团队正在寻找证据来证明这一点。",al={"为什么要前往格沙克农场","格沙克农场的亡灵","调查格沙克"}}},fp="22,165,14.244.0,22.167.0,19.70.0,25.139.0,43.110.0,26.100.0"}
P.entries["quest:66"] = {n="斯塔文的传说",s="斯塔文的传说始于夜色镇，起因是镇上的占卜师伊瓦夫人带来的一个不祥预兆。伊瓦因其孙女艾丽莎即将面临死亡的凶兆而深感不安，她通过卡牌和恍惚的幻象占卜出了一个挥之不去的名字：斯塔文。为了理清这股恐惧的源头，她派遣冒险者前往夜色镇大厅查阅镇上的记录。",h="斯塔文的传说始于夜色镇，起因是镇上的占卜师伊瓦夫人带来的一个不祥预兆。伊瓦因其孙女艾丽莎即将面临死亡的凶兆而深感不安，她通过卡牌和恍惚的幻象占卜出了一个挥之不去的名字：斯塔文。为了理清这股恐惧的源头，她派遣冒险者前往夜色...",kw={"艾丽莎","书记员达尔塔","夜色镇","死神牌","暮色森林","伊瓦夫人","斯塔文","市政厅"},ang={["class:Priest"]="走在夜色镇黑暗道路上的牧师们通常会留意精神上的警示，这使得伊瓦夫人那令人不寒而栗的死亡预兆成了牧师职责中一件刻不容缓的大事。",["faction:Alliance"]="由于暮色森林在缺乏暴风城正规军队支持的情况下艰难求生，联盟冒险者经常挺身而出，协助镇上的长者并保护像伊瓦夫人家庭这样脆弱的平民。"},sec={{t="死亡的幻象",b="在暮色森林永恒的阴霾中，伊瓦夫人作为夜色镇的常驻占卜师，为忧心忡忡的当地人解读预兆和占卜卡牌。在一次因可怕的心灵感应而惊醒后，伊瓦查阅了她的占卜牌，结果却抽到了与她年幼的孙女艾丽莎有关的死神牌。她陷入了一场深沉而阴暗的恍惚中以穿透迷雾，最终只带出了唯一的线索：斯塔文这个名字。出于对这一预兆可能给她的家人和城镇带来灾难的恐惧，她转而求助于有能力的冒险者，希望在悲剧发生前顺藤摸瓜找到真相。"},{t="大厅的问询",b="伊瓦知道，揭开斯塔文真相的关键在于查阅夜色镇的书面历史。她指引冒险者穿过广场前往夜色镇大厅，去寻找书记员达尔塔，他是市政账本和公共档案的保管员。达尔塔掌管着镇上尘封的文档，因此只有他能够确定斯塔文究竟是前居民、过路旅人，还是埋葬在暮色森林过去中更邪恶的存在。"}},faq={{q="伊瓦夫人是谁？",a="伊瓦夫人是一位居住在夜色镇的算命师和占卜师。她利用卡牌和恍惚仪式来窥探未来的预兆，并能感知到暮色森林中发生的魔法波动。",al={"伊瓦夫人","伊瓦是谁","夜色镇算命师"}},{q="为什么伊瓦夫人需要帮助？",a="伊瓦夫人经历了一个可怕的幻象，预示着她的孙女艾丽莎正处于致命的危险之中。她的牌组抽到了死神牌，而她的恍惚状态中只出现了“斯塔文”这个名字，这促使她寻求外界的援助来调查这一威胁。",al={"为何开启斯塔文任务","伊瓦的幻象","为何帮助伊瓦"}},{q="书记员达尔塔是谁？",a="书记员达尔塔是驻守在夜色镇大厅的市政记录官。他负责管理城镇的账本、登记册和历史文档，是询问陌生人名字的最佳人选。",al={"书记员达尔塔","达尔塔","谁是镇书记员"}},{q="什么是夜色镇大厅？",a="夜色镇大厅是该镇的行政中心，这里设有地方政府官员、历史记录档案以及守夜人的指挥人员。",al={"夜色镇大厅","暮色森林市政厅"}},{q="艾丽莎是谁？",a="艾丽莎是居住在夜色镇的伊瓦夫人的年幼孙女。伊瓦的占卜显示，艾丽莎正受到一个与名为斯塔文的人有关的死亡预兆的威胁。",al={"艾丽莎","伊瓦夫人的孙女"}},{q="这项调查接下来会指向何处？",a="与书记员达尔塔交谈将揭示城镇记录和过往的询问，从而开启一项遍布暮色森林及周边地区的广泛调查，以揭开斯塔文的历史和命运。",al={"斯塔文后续步骤","达尔塔说了什么"}}},fp="21,160,17.366.0,22.301.0,18.166.0,30.180.0,20.166.0,28.109.0,14.145.0,40.185.0"}
P.entries["quest:660"] = {n="新的瘟疫？",s="基恩洛准备前往农场，希望你与她同行。她担心亡灵在希尔斯布莱德拖得越久，造成的伤害就越大，她请求你护送她安全回到奎艾身边。",h="基恩洛准备前往农场，希望你与她同行。她担心亡灵在希尔斯布莱德拖得越久，造成的伤害就越大，她请求你护送她安全回到奎艾身边。",kw={"护送","希尔斯布莱德丘陵","新瘟疫的迹象","基恩洛","瘟疫","奎艾"},sec={{t="为基恩洛保驾护航",b="在完成了早先的调查步骤后，基恩洛准备采取行动。她请求你陪她前往农场。你需要护送她安全回到奎艾身边，所有关心希尔斯布莱德人民安危的人都被敦促去保护她。"},{t="安全返回",b="回到奎艾身边后，你因为这次护送得到了感谢。奎艾承认她曾担心基恩洛会不会太难缠：她非常友善，但若是你的敌人，她也同样致命。"}},faq={{q="是谁让你执行这次护送任务的？",a="基恩洛准备动身时，要求你与她同行。",al={"任务发布者","谁给予任务","谁开始新瘟疫的迹象4"}},{q="基恩洛要去哪里？",a="她前往农场，然后动身返回奎艾那里。",al={"护送路线","基恩洛要去哪","基恩洛目的地"}},{q="完成后向谁汇报？",a="奎艾，一旦基恩洛安全回到她身边。",al={"任务交付","谁完成任务","在哪里交付任务"}},{q="在调查的这一部分之前发生了什么？",a="“新瘟疫的迹象？”的第三部分，直接引导至本部分。",al={"前置任务","前提条件","之前是什么"}},{q="安全返回后接下来是什么？",a="调查将继续进行，“新瘟疫的迹象？”的第五部分。",al={"后续任务","接下来是什么","后续"}},{q="为什么要保护基恩洛？",a="所有关心希尔斯布莱德人民的人都被敦促确保她平安无事。",al={"为何保护基恩洛","为何关心基恩洛"}}},fp="22,168,24.188.0,13.154.1,29.62.0,31.51.0,35.53.0,54.83.0,36.48.0,31.101.0"}
P.entries["quest:6608"] = {n="你真棒！",s="“你太强了。”是一个部落任务，由奥格瑞玛的钓鱼训练师鲁玛克在钓鱼者超越了普通训练水平后提供。鲁玛克会派遣他有成就的学生去寻找他的人类朋友——纳特·帕格，此人驻扎在尘泥沼泽偏远的海岸边。这个任务标志着从标准教学到高难度的专家级钓鱼艺术的转变。",h="“你太强了。”是一个部落任务，由奥格瑞玛的钓鱼训练师鲁玛克在钓鱼者超越了普通训练水平后提供。鲁玛克会派遣他有成就的学生去寻找他的人类朋友——纳特·帕格，此人驻扎在尘泥沼泽偏远的海岸边。这个任务标志着从标准教学到高难度的专...",kw={"专家级钓鱼","尘泥沼泽","鲁玛克","纳特·帕格","奥格瑞玛","塞拉摩","你太强了"},ang={["faction:Horde"]="这个任务展示了在阵营战争之下，个人有时能通过无害的技艺和共同的爱好形成跨阵营的羁绊。",["race:Orc"]="即使在奥格瑞玛这座崇尚武力的堡垒中，鲁玛克也证明了耐心、幽默感和对大自然的深刻尊重，可以引导一名兽人在敌对阵营之间结交朋友。"},sec={{t="鲁玛克的局限",b="鲁玛克是奥格瑞玛荣誉谷的主要钓鱼训练师，但即使是这位耐心的兽人也能看出来，当学生在钓鱼技术上的造诣已经追上了他时，他已无更多知识可教。鲁玛克坦率地承认，这位钓鱼者的水平已经“太强了”，普通课程已不适用。为了达到专家等级，必须将目光投向城墙之外，超越种族的界限。"},{t="一段非同寻常的友谊",b="尽管卡利姆多大陆上部落与联盟之间的摩擦不断，但钓鱼往往能在外交失败的地方架起沟通的桥梁。鲁玛克向旅行者指引他的一位私人好友，纳特·帕格，并郑重其事地强调绝不能伤害或吃掉这名人类。纳特在尘泥沼泽的塞拉摩岛南边的一个小岛上扎营，只要有鱼上钩，他便乐于忽略政治纷争。"}},faq={{q="谁发布了这个任务？",a="鲁玛克，位于奥格瑞玛荣誉谷水边的钓鱼训练师。当你的钓鱼技能等级足以超越专家级时，他会给你这个任务。",al={"谁开启你太强了任务","鲁玛克任务发布者","在哪里领取你太强了任务"}},{q="纳特·帕格在哪里？",a="纳特·帕格驻扎在尘泥沼泽海岸外的一个小岛上，位于人类定居点塞拉摩岛的南面。",al={"纳特·帕格在哪里","纳特·帕格位置","寻找纳特·帕格"}},{q="为什么兽人会有个人类朋友？",a="艾泽拉斯各地的钓鱼爱好者往往拥有超越阵营战争的相互尊重。鲁玛克和纳特·帕格纯粹是因为钓鱼而结缘，不论兽人和人类之间有何苦涩的敌对关系，他们都认可彼此对这项活动的挚爱。",al={"鲁玛克和纳特·帕格的友谊","为什么纳特·帕格和兽人是朋友"}},{q="当我与纳特·帕格交谈时会发生什么？",a="与纳特·帕格交谈将开启他那高难度的专家级试炼，你需要横跨艾泽拉斯捕获各种稀有鱼类，他才会亲自传授你进一步的技巧。",al={"纳特·帕格教授什么","钓鱼专家任务"}},{q="部落穿过塞拉摩安全吗？",a="不安全，塞拉摩是联盟严密把守的堡垒城镇。部落冒险者必须绕道城镇或沿着海岸绕行，才能在不引起塞拉摩卫兵敌意的情况下到达纳特的小岛。",al={"部落可以穿过塞拉摩吗","部落如何到达纳特·帕格处"}},{q="为什么鲁玛克不能继续训练我？",a="鲁玛克已经教给你他所知道的一切。钓鱼艺术的真正大师之道需要纳特·帕格的点拨，他被公认为已知世界中最传奇的钓鱼者。",al={"为什么鲁玛克停止训练","部落钓鱼从专家到专家级"}}},fp="13,160,14.234.0,22.281.0,27.109.0,27.87.0,36.124.0,39.115.0,44.139.0,41.134.0"}
P.entries["quest:661"] = {n="新的瘟疫？",s="基恩洛已经从农场安全归来了，奎艾拿到了她带回来的物品。奎艾和基恩洛打算在阿拉希多待一会儿，所以把消息带给南海镇的费恩·奥德利克的任务就交给你了。",h="基恩洛已经从农场安全归来了，奎艾拿到了她带回来的物品。奎艾和基恩洛打算在阿拉希多待一会儿，所以把消息带给南海镇的费恩·奥德利克的任务就交给你了。",kw={"阿拉希高地","被遗忘者","希尔斯布莱德","基恩洛","费恩·奥德利克","瘟疫","奎艾","南海镇"},sec={{t="带给南海镇的消息",b="奎艾很高兴你把基恩洛照顾得这么好，她回来时的状态甚至比在酒馆待了一晚还要好。从农场带回来的物品应该能让费恩·奥德利克对阿拉希发生的状况有所了解。由于农场遭到了袭击，奎艾和基恩洛打算再多待一阵子，以防有人报复，并请求你回到南海镇去找费恩谈谈。"},{t="费恩的回答",b="得知基恩洛和奎艾安然无恙，费恩感到很高兴，称她们二人是不可替代的朋友和旅伴。费恩代表整个团队赠送了一份礼物向你表示感谢，并希望他们能幸运地探明被遗忘者究竟在计划什么，并阻止这一切。"}},faq={{q="是谁让你去和费恩·奥德利克交谈的？",a="在基恩洛从农场安全回来后，奎艾请求你去南海镇。",al={"谁提供了新瘟疫的线索 5","谁开启了新瘟疫的线索","奎艾的任务"}},{q="为什么奎艾和基恩洛不亲自返回南海镇？",a="奎艾想让她们在阿拉希多待一会儿，以防有人因农场遇袭而进行报复。",al={"为什么奎艾要留在阿拉希","为什么要留下来","奎艾留守"}},{q="在哪里可以找到费恩·奥德利克？",a="在南海镇。",al={"费恩·奥德利克的位置","费恩在哪里","费恩·奥德利克 南海镇"}},{q="给费恩·奥德利克带去消息的目的是什么？",a="基恩洛从农场带回来的物品应该能帮助费恩·奥德利克了解阿拉希究竟发生了什么。",al={"为什么要拜访费恩","费恩·奥德利克的目的","费恩想要什么"}}},fp="22,144,19.375.0,13.283.1,40.77.0,64.110.0,31.29.0,52.104.0"}
P.entries["quest:6610"] = {n="蚌肉大餐",s="迪尔格·奎克里弗想为他的蚌肉大餐收集食材，这是他新创的一道菜。作为回报，他愿意教你异国料理，并为你做上几份。",h="迪尔格·奎克里弗想为他的蚌肉大餐收集食材，这是他新创的一道菜。作为回报，他愿意教你异国料理，并为你做上几份。",kw={"奥特兰克冷酪","蚌肉大餐","迪尔格·奎克里弗","巨蛋","鲜嫩的蚌肉"},ang={["profession:Cooking"]="作为一名厨师，你可以向迪尔格·奎克里弗学习异国料理的精妙之处。"},sec={{t="一道新菜谱",b="迪尔格·奎克里弗准备向你展示蚌肉大餐的做法。开做之前，他需要巨蛋、鲜嫩的蚌肉和奥特兰克冷酪。收集他要的食材，迪尔格就会在烹制这道菜时教你异国料理。"}},faq={{q="什么是蚌肉大餐？",a="蚌肉大餐是迪尔格·奎克里弗最新创制的菜肴，由巨蛋、鲜嫩的蚌肉和奥特兰克冷酪制成。",al={"蚌肉大餐","什么是蚌肉大餐"}},{q="谁在要这些食材？",a="迪尔格·奎克里弗想要制作蚌肉大餐的食材。",al={"谁要这些材料","迪尔格任务"}},{q="迪尔格需要哪些食材？",a="迪尔格需要巨蛋、鲜嫩的蚌肉和奥特兰克冷酪。",al={"蚌肉大餐食材","要收集什么"}},{q="我在哪里能找到巨蛋？",a="巨蛋可以从在塔纳利斯游荡的风鹏或其他大型鸟类身上获得。",al={"巨蛋位置","哪里有巨蛋"}},{q="鲜嫩的蚌肉从哪里来？",a="鲜嫩的蚌肉可以从蚌里找到。",al={"蚌肉来源","鲜嫩的蚌肉"}},{q="我在哪里能买到奥特兰克冷酪？",a="迪尔格说，可以去奶酪店买奥特兰克冷酪。",al={"奥特兰克冷酪来源","给迪尔格的奶酪"}},{q="迪尔格会给我什么回报？",a="Dirge愿意教你异域烹饪的精妙之处，并为你准备几份clamlettes。",al={"能得到什么","迪尔格教什么"}}},fp="18,154,12.259.0,20.117.0,34.66.0,33.59.0,32.73.0,41.38.0,30.48.0,32.104.0"}
P.entries["quest:6611"] = {n="加基森之旅！",s="“前往加基森！”是部落厨师为了超越主城训练师所能传授的极限而踏上的旅程。在奥格瑞玛的扎姆沙指引下，渴望精进技艺的厨师们会向南穿过卡利姆多，前往塔纳利斯寻找古怪的地精屠夫迪尔格·奎克里弗。这项引导任务标志着厨师迈向烹饪艺术大师之路的起点。",h="“前往加基森！”是部落厨师为了超越主城训练师所能传授的极限而踏上的旅程。在奥格瑞玛的扎姆沙指引下，渴望精进技艺的厨师们会向南穿过卡利姆多，前往塔纳利斯寻找古怪的地精屠夫迪尔格·奎克里弗。这项引导任务标志着厨师迈向烹饪艺术...",kw={"专家级烹饪","烹饪","迪尔格·奎克里弗","加基森","奥格瑞玛","塔纳利斯","力量谷","扎姆沙"},ang={["faction:Horde"]="奥格瑞玛需要依靠像中立地精厨师这样的外部专家，来帮助其工匠突破部落标准菜肴的局限。",["profession:Cooking"]="这个任务标志着厨师在主城训练师的教导下学有所成，必须冒险进入危险的荒野，向一位专家级大师求学的里程碑。"},sec={{t="超越奥格瑞玛的厨艺",b="在奥格瑞玛的暗影裂口，巨魔厨师扎姆沙为来往于杜隆塔尔红褐色峡谷的无数战士和旅行者提供食物。然而，当一名专注的厨师学会了扎姆沙所能传授的所有食谱和技巧后，这位大师也只能承认自己已经倾囊相授。在传授了她所有的烹饪秘诀后，她会将这位成熟的学生送往南方的塔纳利斯沙漠，并坦言只有一位精通奇特异域肉类的真正大师，才能帮助天赋异禀的厨师更进一步。"},{t="沙漠中的屠夫",b="目的地是加基森，这是一座由热砂港运营的蒸汽动力贸易枢纽。在那里，在嘈杂的城镇旅店里，经营着迪尔格·奎克里弗。迪尔格是一位拥有非凡味觉且对烹饪毫无顾忌的地精，他在整个卡利姆多都颇具传奇色彩，他能将各种可怕的沙漠生物（有时甚至是皮革废料）烹饪成足以支撑坚毅冒险者的丰盛大餐。"}},faq={{q="谁会指引你去加基森？",a="扎姆沙是位于奥格瑞玛暗影裂口篝火旁的巨魔专家烹饪训练师，她会将这项任务交给已经掌握了她所知全部技艺的厨师。",al={"任务发布者","谁开启任务","扎姆沙任务"}},{q="为什么扎姆沙要让你离开？",a="扎姆沙已经传授了她所能教授的所有食谱和烹饪技巧。为了达到专家级的烹饪大师水平，她指引有前途的厨师前往塔纳利斯的迪尔格·奎克里弗那里学习，这位古怪的专家以善于用最严酷的沙漠食材制作出可口的饭菜而闻名。",al={"为什么去加基森","为什么找迪尔格·奎克里弗","烹饪大师"}},{q="迪尔格·奎克里弗是谁？",a="迪尔格·奎克里弗是一位地精屠夫兼专家级烹饪训练师，位于加基森的旅店中。他以暴躁的脾气、古怪的营养理论（比如从旧皮靴中提取蛋白质）以及对高端异域荒野烹饪的精通而闻名。",al={"谁是迪尔格","迪尔格 加基森"}},{q="学习专家级烹饪需要这个任务吗？",a="不需要。这个任务仅仅是一个引导玩家前往塔纳利斯的指引任务。只要烹饪等级足够，厨师可以直接前往加基森，在没有收到扎姆沙推荐的情况下与迪尔格·奎克里弗交谈。",al={"我需要这个任务吗","烹饪引导任务","这是强制的吗"}},{q="加基森在哪里？",a="加基森是一座由热砂港运营的围墙式沙漠前哨站，位于塔纳利斯北部的沙漠中，坐落在卡利姆多大陆最南端，千针石林的下方。",al={"加基森位置","迪尔格在哪里"}},{q="当你回来时，扎姆沙真的能学到什么吗？",a="虽然扎姆沙调皮地要求你成为烹饪大师后回来教她，但她依然是奥格瑞玛的一位专家级训练师，继续在篝火旁为下一代旅行者服务。",al={"扎姆沙会学烹饪吗","教扎姆沙"}}},fp="20,95,25.295.0,25.364.0,27.117.0,29.181.0,24.239.0,48.146.0,27.138.0,51.194.0"}
P.entries["quest:6612"] = {n="我认识一个家伙…",s="你的烹饪技艺已超越了本地导师所能教授的范围，他已经无技可授。若想继续精进厨艺，你必须远渡重洋前往卡利姆多，在沙漠城镇加基森寻访一位烹饪大师。",h="你的烹饪技艺已超越了本地导师所能教授的范围，他已经无技可授。若想继续精进厨艺，你必须远渡重洋前往卡利姆多，在沙漠城镇加基森寻访一位烹饪大师。",kw={"烹饪","厨艺","迪尔格·奎克里弗","加基森","地精","卡利姆多","塔纳利斯"},ang={["profession:Cooking"]="作为一名厨师，这趟旅程标志着你已达到寻常厨艺大师无法再教你更多的境地，于是你将远渡重洋，寻求地精的烹饪技艺。"},sec={{t="远渡重洋",b="你的烹饪技艺已超出本地导师所能传授的范围。若想精进厨艺，你需要远渡重洋，前往塔纳利斯的干燥沙海。在那里，加基森的地精聚居地中，一位古怪的厨师迪尔格·奎克里弗正等着你。"}},faq={{q="迪尔格·奎克里弗是谁？",a="迪尔格·奎克里弗是一位居住在加基森的地精厨师，被誉为卡利姆多大陆上最出色的厨师之一。",al={"迪尔格·奎克里弗是谁","迪尔格·奎克里弗在哪里","加基森厨师"}},{q="加基森位于哪里？",a="加基森是位于卡利姆多南部塔纳利斯沙海中的一座地精城镇。",al={"加基森在哪里","怎么去加基森","加基森位置"}},{q="为什么必须远赴卡利姆多？",a="本地导师已经把所知的一切都教给了你。塔纳利斯一位声名远扬的地精烹饪大师，是唯一能让你的厨艺更进一步的人。",al={"为什么在卡利姆多学烹饪","为什么去塔纳利斯","提升烹饪技能"}},{q="是谁建议你去寻找迪尔格·奎克里弗？",a="一位经验丰富的烹饪导师看出了你的厨艺造诣，但已无法再教你更多，于是指引你去海那边拜访一位同行。",al={"谁让你去找迪尔格","我有个熟人任务给予者"}}},fp="15,258,14.291.0,24.128.0,27.93.0,44.158.0,44.161.0"}
P.entries["quest:662"] = {n="深海打捞",s="继“陆地啊！”之后，大副尼兹利克斯要求你在任何人离开海湾之前找回两艘沉船的海图和航海日志。",h="继“陆地啊！”之后，大副尼兹利克斯要求你在任何人离开海湾之前找回两艘沉船的海图和航海日志。",kw={"阿拉希高地","藏宝海湾","深海打捞","先驱号","少女的愚行号","尼兹利克斯","奥布林","卡拉·海角","银松之魂号"},sec={{t="礁石上的两艘沉船",b="奥布林带领三艘船进入海湾，确信宝藏就在这里。先驱号安全靠岸。随后，当“少女的愚行号”和“银松之魂号”驶入时，潮水开始退去，两艘船都搁浅在礁石中一座类似神庙的结构上，并迅速沉没。"},{t="尼兹利克斯想要找回的东西",b="尼兹利克斯希望回收两艘失事船只的航海日志和海图，因为这些信息绝不能留给窥探者。他说，如果这些东西落入敌人手中，舰队指挥官卡拉·海角会将船员们全部处死。"}},faq={{q="为什么少女的愚行号和银松之魂号会沉没？",a="当这两艘船驶入时，潮水开始退去。它们都搁浅在礁石中一座类似神庙的东西上，并迅速沉没。",al={"船只失事原因","船只沉没方式","阿拉希海湾沉船原因"}},{q="大副尼兹利克斯是谁？",a="他是提及奥布林带领三艘船进入海湾的那位大副，他要求找回那两艘沉船的航海日志和海图。",al={"尼兹利克斯","谁发布了深海打捞任务"}},{q="为什么海图和航海日志如此重要？",a="尼兹利克斯不希望这些信息被留下来落入窥探者手中。他说，如果被敌人获得，舰队指挥官卡拉·海角会将船员们全部处死。",al={"为什么要找回日志","为什么是海图和日志"}},{q="哪艘船安全抵达了？",a="只有先驱号。它在海湾安全靠岸，而另外两艘船则沉没了。",al={"哪艘船幸存","先驱号"}},{q="舰队指挥官卡拉·海角是谁？",a="尼兹利克斯提到他，说如果船队的记录落入敌人手中，他会将船员们全部处死。",al={"舰队指挥官卡拉·海角的作用","卡拉·海角是谁"}},{q="这项任务之前是什么？",a="它紧随“陆地啊！”之后。",al={"深海打捞前置任务","上一个任务"}}},fp="16,121,26.247.0,23.206.0,57.158.0,26.142.0,41.157.0,28.71.0,28.117.0,27.26.0"}
P.entries["quest:6621"] = {n="污林熊怪之王",s="“肮脏之林之王”是部落在佐拉姆加前哨站由卡拉恩·阿玛卡发起的一次军事打击行动。为了制服阿斯特兰纳东南方受腐化的肮脏之林熊怪，部落勇士需要在该部落神圣的图腾堆顶端插上一面战旗，以此激怒并处决他们的首领穆戈特酋长。",h="“肮脏之林之王”是部落在佐拉姆加前哨站由卡拉恩·阿玛卡发起的一次军事打击行动。为了制服阿斯特兰纳东南方受腐化的肮脏之林熊怪，部落勇士需要在该部落神圣的图腾堆顶端插上一面战旗，以此激怒并处决他们的首领穆戈特酋长。",kw={"灰谷","肮脏之林","熊怪","绿爪村","卡拉恩·阿玛卡","穆戈特","图腾堆","佐拉姆加"},ang={["class:Shaman"]="肮脏之林那扭曲的图腾和侵略性，反映了燃烧军团入侵后困扰灰谷土著部落的持续精神失衡。",["faction:Horde"]="卡拉恩·阿玛卡利用公开的武力展示来震慑灰谷的敌对部落，从而确保部落补给车队能够安全通过中央道路。",["race:Orc"]="通过插旗来激怒敌方首领进行单挑，是典型的兽人式战争手段，它将力量和决定性的对抗置于长期的摩擦之上。"},sec={{t="武力展示",b="当暗夜精灵竭力遏制灰谷中受腐化的土著部落时，部落采取了经过深思熟虑的侵略性手段来应对这一威胁。佐拉姆加前哨站的卡拉恩·阿玛卡认为，虽然肮脏之林部落的数量无法与北方的蓟皮熊怪相提并论，但他们那肆无忌惮的凶残性构成了沿南方道路潜伏的巨大危险。与其等待部落巡逻队遭到伏击，卡拉恩下令进行一次先发制人的军事威慑，以摧毁该部落的意志。"},{t="亵渎与挑战",b="这次打击的目标是位于密斯特拉湖东北方的绿爪村。卡拉恩制作了一面部落战旗，旨在将其直接插入肮脏之林图腾堆的中心——这对于该部落的先祖之灵和尊严来说是不可饶恕的侮辱。熊怪防卫者们绝望地冲向图腾堆试图拔掉这面冒犯性的旗帜，迫使穆戈特酋长不得不现身，在公开战斗中捍卫自己的荣誉。夺取穆戈特的个人图腾会击溃他们的领导层，并确立部落在该地区的统治地位。"}},faq={{q="是谁下令处死穆戈特酋长的？",a="卡拉恩·阿玛卡，一名驻扎在灰谷西海岸佐拉姆加前哨站的兽人。在对邻近的蓟皮熊怪进行调查后，他发布了这项任务。",al={"肮脏之林之王任务发放者","谁发布肮脏之林之王任务","卡拉恩·阿玛卡任务"}},{q="绿爪村位于哪里？",a="绿爪村位于暗夜精灵定居点阿斯特兰纳的东南方，坐落在密斯特拉湖的东北侧，正好位于灰谷主要东向大道的南边。",al={"绿爪村位置","肮脏之林位置","卡拉恩的旗子插在哪里"}},{q="为什么部落要在图腾堆上插旗？",a="将卡拉恩的旗子直接插在部落神圣的图腾堆上是一种蓄意的挑衅。亵渎他们神圣的领地会迫使肮脏之林熊怪愤怒地发起攻击，并迫使穆戈特酋长为了捍卫自己的地位而公开应战。",al={"为什么插旗","图腾堆插旗目的","为什么要挑战穆戈特"}},{q="肮脏之林熊怪是什么？",a="肮脏之林是灰谷中在第三次战争后陷入疯狂与腐化的众多熊怪部落之一。尽管他们的人数比蓟皮熊怪要少，但他们对外来者依然充满暴力和敌意。",al={"什么是肮脏之林","肮脏之林部落背景","穆戈特酋长是谁"}},{q="取回穆戈特的图腾有什么作用？",a="将穆戈特酋长的图腾带回佐拉姆加前哨站证明了这位酋长的落败。失去了领导者，且神圣的图腾堆也蒙受了羞辱，幸存的肮脏之林熊怪会被震慑，从而避免与部落发生进一步的冲突。",al={"穆戈特的图腾用途","穆戈特死后发生了什么"}},{q="这个任务是如何与之前的熊怪调查联系起来的？",a="这个任务紧随“两难之间（蓟皮熊怪）”之后。在处理完北方的蓟皮熊怪部落后，卡拉恩将注意力转向南方，旨在先发制人地粉碎肮脏之林部落，以防他们发动协同突袭。",al={"与两难之间（蓟皮熊怪）的联系","肮脏之林之王前置任务"}}},fp="21,189,15.274.0,25.382.0,37.162.0,34.126.0,53.171.0,31.190.0,47.216.0,64.182.0"}
P.entries["quest:6622"] = {n="Triage",s="你需要用 Triage Bandages 救治受伤的士兵。他们伤势严重，耽搁不得。",h="你需要用 Triage Bandages 救治受伤的士兵。他们伤势严重，耽搁不得。",kw={"伤势严重","身负重伤","受伤的士兵","伤员","士兵","急救","triage bandages","伤口"},sec={{t="伤员",b="身负重伤的士兵最先撑不住，伤势严重的士兵随后倒下。受伤的士兵能坚持最久，因此救治顺序至关重要。你必须在六人因伤死亡前救治十五名伤员。"}},faq={{q="我需要做什么？",a="你需要用 Triage Bandages 救治十五名伤员，并赶在六人因伤死亡之前完成。",al={"急救任务","什么是急救","救治士兵"}},{q="哪些士兵伤势最重？",a="身负重伤的士兵死得最快，其次是伤势严重的士兵。",al={"谁死得最快","身负重伤的士兵","伤势最重"}},{q="谁能坚持最久？",a="受伤的士兵能坚持最久，应当在伤势更重的士兵之后救治。",al={"士兵救治顺序","谁最后救治","伤势最轻"}},{q="Triage Bandages 有什么用？",a="Triage Bandages 用来救治士兵的伤口。",al={"绷带用途","triage bandages","如何救治伤员"}}},fp="6,104,11.215.0,28.97.0,38.80.0,21.96.0,29.57.0"}
P.entries["quest:6623"] = {n="部落医疗队",s="“部落创伤”是一份征召令，指示经验丰富的部落医护人员前往阿拉希高地的落锤镇报到。部落创伤部门的首席医师格里高利·维克托医生正在招募并考察那些能够在极端压力下挽救生命的技术能手。响应此征召意味着医护人员将直接投身于前线野战外科手术残酷且高风险的现实之中。",h="“部落创伤”是一份征召令，指示经验丰富的部落医护人员前往阿拉希高地的落锤镇报到。部落创伤部门的首席医师格里高利·维克托医生正在招募并考察那些能够在极端压力下挽救生命的技术能手。响应此征召意味着医护人员将直接投身于前线野战...",kw={"阿拉希高地","格里高利·维克托医生","急救","落锤镇","部落创伤","阿诺克","救死扶伤"},ang={["class:Priest"]="虽然神圣魔法可以瞬间缝合伤口，但世俗的分诊技术能教人养成必要的纪律，在法力耗尽时分辨出谁是可以被挽救的。",["faction:Horde"]="部落的军事实力在很大程度上依赖于坚韧的战场外科医生，他们能让步兵在阿拉希高地这样残酷的边境冲突中保持战力。"},sec={{t="来自落锤镇的征召",b="在奥格瑞玛的荣誉谷，兽人急救训练师阿诺克会向精通治疗术的人员传达消息，告知他们已经引起了格里高利·维克托医生本人的注意。维克托在落锤镇的防御工事中监管着部落创伤部门，该镇坐落于阿拉希高地崎岖的丘陵地带。阿诺克不仅将这份征召视为一道命令，更将其看作任何一名战场外科医生职业生涯的巅峰。"},{t="残酷的战场分诊工作",b="抵达落锤镇后，你会发现这里的环境极其艰苦。在与激流堡军队和当地敌对势力的持续小规模冲突中，维克托医生被源源不断的受伤步兵、劫掠者和侦察兵搞得应接不暇。首席医师没有时间对新人寒暄；相反，受招募者会立即被要求换上手术服，在快节奏的残酷紧急分诊中证明自己的价值。"}},faq={{q="什么是“部落创伤”？",a="“部落创伤”代表着服务于部落前线的专业医疗和外科分支。它由格里高利·维克托医生在落锤镇领导，其成员专门从事战场医疗、紧急分诊，以及在混乱条件下处理严重的战斗伤势。",al={"部落创伤阵营","什么是部落创伤","部落创伤是谁"}},{q="是谁指派我执行这个任务的？",a="奥格瑞玛荣誉谷的兽人急救训练师阿诺克发布了这份征召。他认为，能够在格里高利·维克托医生麾下效力，是一名有抱负的野战医护人员所能获得的最高荣誉。",al={"部落创伤任务发布者","谁开始部落创伤任务","克伦克·断肢","阿诺克"}},{q="格里高利·维克托医生在哪里？",a="格里高利·维克托医生驻扎在落锤镇的医疗室，这是位于阿拉希高地东北部的主要部落据点。",al={"格里高利·维克托医生位置","维克托在哪里","落锤镇医生"}},{q="报到落锤镇后会发生什么？",a="抵达后，维克托医生会立即指示你换上手术服，进行后续任务“救死扶伤”。你将被置于一项高压测试中，必须在受伤士兵因伤势恶化而死亡之前，对他们进行优先级排序和治疗。",al={"部落创伤后是什么","部落创伤后续任务","救死扶伤任务"}},{q="为什么落锤镇如此急需野战医护人员？",a="落锤镇在阿拉希地区四面楚歌，不断面临人类军队、辛迪加特工和当地野兽的侵袭。伤员源源不断地涌入营地，使得基地本就匮乏的医疗人员捉襟见肘。",al={"为什么落锤镇需要医护人员","落锤镇医疗状况"}},{q="联盟玩家可以接受这个任务吗？",a="不可以。“部落创伤”仅面向部落成员。联盟有对应的医疗评估任务，由塞拉摩岛据点的古斯塔夫·范沃森医生负责。",al={"联盟可以做部落创伤吗","部落创伤联盟版本"}}},fp="12,171,25.318.0,37.292.0,21.204.0,32.190.0,39.111.0,43.233.0,48.221.0,42.145.0"}
P.entries["quest:6624"] = {n="救死扶伤",s="一位治疗者请你用急救绷带救治伤兵。你必须在太多伤兵死去之前救治足够多的人。",h="一位治疗者请你用急救绷带救治伤兵。你必须在太多伤兵死去之前救治足够多的人。",kw={"重伤","绷带","垂危","受伤","伤员","士兵","急救"},sec={{t="床边救治",b="士兵们身负重伤，而你有急救绷带可以救治他们。垂危的士兵最危险，其次是重伤的士兵。受伤的士兵还能撑更久，所以救治顺序很重要。"}},faq={{q="我需要救活多少名士兵？",a="你需要救活十五名伤兵。",al={"救活多少名伤兵","急救人数"}},{q="最多能有多少名伤兵死亡？",a="你救活十五名伤兵之前，最多只能有五名伤兵死亡。",al={"最多能死多少人","急救死亡人数"}},{q="应该先救治哪些士兵？",a="垂危的士兵死得最快，所以要先救治他们。其次是重伤的士兵，然后是受伤的士兵。",al={"先救治哪些士兵","急救顺序"}},{q="哪些士兵能撑得最久？",a="受伤的士兵死得最慢，应该在伤势更重的士兵之后救治。",al={"谁能撑得久","伤兵救治顺序"}}},fp="6,118,14.224.0,36.34.0,26.65.0,21.123.0,32.96.0"}
P.entries["quest:6625"] = {n="联盟外科医疗队",s="“联盟创伤”是一份征召令，旨在指引造诣深厚的战地医生前往尘泥沼泽的塞拉摩岛。该征召令由联盟各大主城的急救训练师发出，邀请技术娴熟的医师在联盟精英医疗团的首席医师古斯塔夫·范沃森医生麾下进修。",h="“联盟创伤”是一份征召令，旨在指引造诣深厚的战地医生前往尘泥沼泽的塞拉摩岛。该征召令由联盟各大主城的急救训练师发出，邀请技术娴熟的医师在联盟精英医疗团的首席医师古斯塔夫·范沃森医生麾下进修。",kw={"联盟创伤","尘泥沼泽","急救","铁炉堡","尼莎·火石","塞拉摩","分诊","范沃森"},ang={["faction:Alliance"]="“联盟创伤”确保了卡利姆多和东部王国的每一位前线战士都能拥有在炮火下稳定危重伤情的娴熟战地医生。",["race:Dwarf"]="像铁炉堡的尼莎·火石这样的训练师，正热切地从大锻炉发掘有前途的从业者，派遣他们前往塞拉摩代表联盟最顶尖的医疗人才。"},sec={{t="战地征召",b="当一名医生掌握了联盟各大城市所能传授的基础急救技术后，当地的训练师就已很难再有更多指教。对于那些在缝合、包扎和分诊方面表现出卓越天赋的医师，消息会被直接传达给古斯塔夫·范沃森医生。范沃森医生坐镇于塞拉摩岛这一前线要塞，统领着“联盟创伤”组织，负责在卡利姆多乃至更广阔地区的残酷战区中挽救生命。"},{t="通往塞拉摩之路",b="诸如铁炉堡的尼莎·火石之类的训练师，将范沃森医生的亲自征召视为一种非同寻常的殊荣。塞拉摩岛长期受到来自区域威胁、小规模冲突和严酷荒野环境的压力，不断有重伤士兵被送往此处。要抵达范沃森医生的诊所，需要经过漫长的海上航行前往尘泥沼泽，只有最沉着冷静的战地外科医生才有望通过他严苛的分诊考核。"}},faq={{q="什么是联盟创伤？",a="“联盟创伤”是联盟负责高级战地医疗和紧急分诊的精英医疗分支。该组织由首席医师古斯塔夫·范沃森领导，负责处理常规战地包扎无法解决的危重伤情。",al={"联盟创伤背景故事","谁是联盟创伤"}},{q="是谁指派了这个任务？",a="联盟的急救训练师，例如铁炉堡大锻炉的尼莎·火石，会在有前途的医师达到常规城市训练的巅峰水平后将他们引荐过去。",al={"谁发布联盟创伤任务","铁炉堡急救任务发布者"}},{q="你需要前往哪里？",a="你必须前往位于卡利姆多大陆尘泥沼泽东海岸的人类港口要塞——塞拉摩岛。",al={"范沃森在哪里","联盟创伤目的地"}},{q="古斯塔夫·范沃森医生是谁？",a="古斯塔夫·范沃森医生是“联盟创伤”的首席医师。他驻扎在塞拉摩的军事诊所，被公认为联盟在急救医学和外科分诊领域最权威的专家之一。",al={"古斯塔夫·范沃森","首席医师范沃森"}},{q="向范沃森医生报到后会发生什么？",a="抵达塞拉摩后，范沃森会对候选人进行严酷的实地分诊评估，测试他们在一波又一波垂死士兵面前的救治能力，只有通过测试才能被允许加入战地医疗的高级序列。",al={"联盟创伤之后做什么","分诊任务后续"}},{q="为什么诊所设在塞拉摩，而不是暴风城或铁炉堡？",a="塞拉摩是一座活跃的前线驻军要塞，四周环绕着充满敌意的沼泽、危险的野兽和地区性冲突。不断涌入的重伤士兵使其成为进行高强度创伤训练的理想基地。",al={"为什么选择塞拉摩诊所","为什么在尘泥沼泽进行创伤训练"}}},fx={a452e047={q="尼莎·火石为什么派你去塞拉摩？",a="联盟外科医疗队的首席医师古斯塔夫·范沃森医生亲自点名召你前往塞拉摩，加入他的队伍。尼莎·火石对这位著名的外科医生推崇备至，认为能在他手下工作是无上的荣誉。她转达这次召见，是希望你不要错失如此难得的医学进修机会。",al={"尼莎为什么要办这件事","尼莎·火石的动机","为什么派去塞拉摩"}},a6ba6381={q="范沃森医生为什么专门召见你？",a="古斯塔夫·范沃森医生需要技艺高超、经验丰富的战地医师，能在压力之下救治重伤员。你已经证明了自己卓越的急救技艺，引起了联盟高级外科医师团的注意，因此范沃森亲自召你前往塞拉摩，考察你在战场环境下的本领。",al={"联盟外科医疗队为什么找我","范沃森为什么找我","为什么派玩家去塞拉摩"}}},fp="15,183,19.199.0,21.353.0,24.216.0,28.169.0,28.100.0,31.206.0,49.183.0,71.231.0"}
P.entries["quest:6626"] = {n="A Host of Evil",s="Myriam Moonsinger 要求你去对付剃刀高地的守卫和教徒。她派你去处理的，正是他们的存在。",h="Myriam Moonsinger 要求你去对付剃刀高地的守卫和教徒。她派你去处理的，正是他们的存在。",kw={"邪恶之众","亡首教徒","myriam moonsinger","razorfen battleguard","剃刀高地","剃刀织棘者"},sec={{t="邪恶之众",b="在剃刀高地入口附近，Myriam Moonsinger 要求你去对付里面的 Razorfen Battleguard、剃刀织棘者和亡首教徒。她希望你处理完他们后回去找她。"}},faq={{q="谁在剃刀高地寻求帮助？",a="Myriam Moonsinger 在剃刀高地入口附近，要求你去对付那里的守卫和教徒。",al={"myriam是谁","myriam moonsinger"}},{q="Myriam 提到了哪些敌人？",a="Myriam 提到了 Razorfen Battleguard、剃刀织棘者和亡首教徒。",al={"要打谁","剃刀敌人"}},{q="我该回到哪里找 Myriam？",a="回到剃刀高地入口附近找 Myriam Moonsinger。",al={"myriam在哪里","myriam的位置"}}},fp="14,136,18.212.0,36.104.0,31.84.0,28.64.0"}
P.entries["quest:6627"] = {n="知识试炼",s="“知识的试炼”是隐士布劳格·幽魂在石爪山脉设下的一项关于智慧与历史记忆的考验。在取回古籍“巨龙的遗产”后，旅者必须回答布劳格的提问，以证明他们对古代历史的理解。那些未能研读文本的人会发现自己被突然放逐到卡利姆多的各个角落。",h="“知识的试炼”是隐士布劳格·幽魂在石爪山脉设下的一项关于智慧与历史记忆的考验。在取回古籍“巨龙的遗产”后，旅者必须回答布劳格的提问，以证明他们对古代历史的理解。那些未能研读文本的人会发现自己被突然放逐到卡利姆多的各个角落...",kw={"守护巨龙","布劳格·幽魂","大地守卫者","耐萨里奥","石爪山脉","陶拉祖营地","信仰的试炼","老屋"},ang={["class:Mage"]="法师们会发现布劳格的传送结界既令人印象深刻又具有惩罚性，这表明石爪山脉的隐士们掌握着古老的魔法，用来教训那些粗心的学者。",["faction:Horde"]="部落在卡利姆多的试炼需要的不仅仅是蛮力；无论是战士还是萨满，都应当理解塑造了这片大陆的古老伤痕和巨龙之力。",["race:Tauren"]="这项试炼体现了牛头人对祖先智慧和古代历史的尊重，确保年轻的勇士们不会在不了解世界平衡的情况下盲目前行。"},sec={{t="智慧的试炼",b="作为由老屋的多恩·平原行者所开启的一系列试炼的一部分，“知识的试炼”将重点从武力生存或盲目信任转移到了对这个世界古老过去的理解上。居住在石爪山脉峭壁间的布劳格·幽魂要求寻求者找回古籍，并真正吸收书页中所蕴含的知识。"},{t="巨龙的遗产",b="这一课的重点在于守护巨龙的创造与分化，特别是早在天崩地裂发生前就已缔结的宿命契约。布劳格考察寻求者对大地守卫者耐萨里奥的回忆，正是他的堕落与背叛重塑了艾泽拉斯的地表。不尊重历史的人将无法继续走上智慧之路。"},{t="臆测的代价",b="布劳格无法容忍随意的猜测。提供错误答案的寻求者会立即被神秘力量驱逐，并被传送到数英里外的南贫瘠之地陶拉祖营地。若想挽回自己的地位，必须长途跋涉回到石爪山脉，再次面对这位隐士的审视。"}},faq={{q="布劳格·幽魂的问题的答案是什么？",a="布劳格询问的是古籍“巨龙的遗产”中记载的大地守卫者的身份。正确答案是耐萨里奥，这位黑龙之王后来背叛了他的同族巨龙。",al={"布劳格的问题答案","知识的试炼答案","巨龙的遗产问题"}},{q="如果回答错误会发生什么？",a="给布劳格错误的答案会立即导致魔法放逐，将你直接传送到贫瘠之地的陶拉祖营地。你必须长途跋涉回到他在石爪山脉的栖身处，才能再次尝试这项试炼。",al={"知识的试炼回答错误","知识的试炼失败","传送到陶拉祖"}},{q="布劳格·幽魂是谁？",a="布劳格·幽魂是一位居住在石爪山脉的年长隐士，他为部落主持知识和传说的试炼，延续了在千针石林开启的一系列精神试炼。",al={"布劳格·幽魂","谁提供知识的试炼"}},{q="这与千针石林的试炼有何关联？",a="这项试炼始于千针石林老屋的多恩·平原行者所主持的“信仰的试炼”。多恩考察身体和精神上的信任，然后将合格的受试者派往卡利姆多各地，接受其他睿智长者的考验，以检验他们的智慧、意志和力量。",al={"多恩·平原行者的联系","信仰的试炼任务链"}},{q="布劳格考核你的书是什么？",a="这次考核旨在测试你对“巨龙的遗产”的理解，这是一部古老的论著，详细记载了泰坦赐福给五大守护巨龙以守护艾泽拉斯的事迹。",al={"布劳格考核的书籍","巨龙的遗产"}},{q="这个任务链接下来通向哪里？",a="通过布劳格关于守护巨龙的考核后，接下来将进行更深入的古代历史探索试炼，要求寻求者搜寻遥远的地区，以寻找更多的失落记录和祖先知识。",al={"知识的试炼之后是什么","知识的试炼的后续任务"}}},fx={a70a9b29={q="布劳格·幽魂为什么要考验你？",a="布劳格·幽魂是千针石林试炼中的考官。其他试炼考验你的武艺或信仰，而知识试炼旨在确保你不会只依靠蛮力。布劳格要求你找回古代典籍并理解其内容，希望借此培养那些志在代表部落的人所需的智慧和历史知识。",al={"布劳格为什么考验你","布劳格·幽魂的职责","为什么要进行知识试炼"}}},fp="12,217,17.284.0,21.322.0,22.247.1,49.147.0,39.164.0,23.185.0,56.247.0,38.150.0,38.176.0"}
P.entries["quest:6628"] = {n="知识试炼",s="这项试炼是千针石林一系列精神测试中智力考核的标志。在搜寻世界各地的历史文献后，初学者必须前往幽暗城觐见帕科瓦·芬塔拉斯，证明他们了解塑造了艾泽拉斯的那些黑暗历史。",h="这项试炼是千针石林一系列精神测试中智力考核的标志。在搜寻世界各地的历史文献后，初学者必须前往幽暗城觐见帕科瓦·芬塔拉斯，证明他们了解塑造了艾泽拉斯的那些黑暗历史。",kw={"多恩·平原行者","巫妖王","耻辱印记","耐奥祖","帕科瓦·芬塔拉斯","博学试炼","千针石林","幽暗城","老屋"},ang={["faction:Horde"]="这项试炼加强了卡利姆多各部落与洛丹伦地下王国之间的联系，提醒勇士们：智慧对于部落的生存与蛮力同样重要。",["race:Tauren"]="在长者传统的引导下，这项测试促使牛头人旅行者去了解他们北方的盟友——被遗忘者的冷酷历史，以及卡利姆多之外的世界。",["race:Undead"]="试炼的主题直指被遗忘者身份的核心：耐奥祖被创造的悲剧，以及在希尔瓦娜斯打破巫妖王掌控之前，束缚他们的诅咒起源。"},sec={{t="知识的试炼",b="虽然部落的许多试炼旨在考验武力或耐力，“博学试炼”则要求学者般的专注。这一试炼源自多恩·平原行者在老屋制定的精神修炼法，其旅程将候选人从千针石林风蚀的峡谷带往幽暗城阴暗的大厅。帕科瓦·芬塔拉斯担任考官，以严苛的历史知识标准要求寻求者。"},{t="天灾军团的起源",b="为了满足帕科瓦的要求，初学者必须研读《亡灵威胁的开端》，这是一本详述洛丹伦天灾军团被诅咒起源的文献。他盘问的核心是统治冰封王座之实体的起源：前萨满长老耐奥祖，他的精华被燃烧军团锻造成了巫妖王。了解这段冷酷的血统对于理解被遗忘者的存在，以及卡利姆多和东部王国共同面临的危险至关重要。"}},faq={{q="帕科瓦的问题答案是什么？",a="帕科瓦·芬塔拉斯询问的是巫妖王的真名。正确答案是耐奥祖，这位古老的兽人萨满的灵魂被束缚在冰封王座上。",al={"巫妖王答案","帕科瓦的问题","博学试炼答案"}},{q="如果问题回答错误会怎样？",a="回答错误会被施加“耻辱印记”减益效果，你必须等待惩罚时间结束，帕科瓦才会允许你再次尝试考试。",al={"耻辱印记","博学试炼回答错误"}},{q="这个任务链从哪里开始？",a="整个试炼始于千针石林高耸尖塔中的老屋，找多恩·平原行者接取。",al={"博学试炼从哪里开始","多恩·平原行者任务线"}},{q="帕科瓦·芬塔拉斯在哪里？",a="帕科瓦·芬塔拉斯居住在幽暗城，徘徊于被遗忘者的地下图书馆和走廊间，在那里盘问未来的学生。",al={"寻找帕科瓦","帕科瓦·芬塔拉斯位置"}},{q="这项试炼基于什么文献？",a="该测试基于《亡灵威胁的开端》一书，书中详述了亡灵瘟疫的起源和巫妖王的诞生。",al={"博学试炼需要哪本书","《开端》之书"}},{q="为什么千针石林的任务会让人去幽暗城？",a="牛头人设立的这些试炼旨在挑战冒险者的方方面面。为了考验博学程度，候选人需跨越大海，去探寻保存在洛丹伦废墟中的学术记录。",al={"为什么去幽暗城","千针石林到幽暗城"}}},fx={b37475e3={q="帕科瓦·芬塔拉斯为什么要你完成这件事？",a="帕科瓦·芬塔拉斯要用这项任务考验你追求知识的决心。他相信，在这个危机四伏的世界里，知识至关重要——你学得越多、观察得越仔细，就越能看清真相。他让你去取得《亡灵威胁》一书，要求你证明自己确实研读并理解了其中阴郁的历史，而不是只跑了一趟腿。",al={"帕科瓦的动机","帕科瓦为什么考验我","为什么要进行知识试炼"}}},fp="12,200,20.332.0,21.381.1,41.135.0,46.131.0,34.131.0,35.136.0,33.135.0,60.163.0"}
P.entries["quest:6629"] = {n="杀死格鲁迪格·暗云",s="“干掉格伦迪格·暗云”是一个由玛卡巴·扁蹄在石爪山脉东南侧道路旁给予的部落任务。在消灭了恐怖图腾暴徒和雇佣兵之后，玛卡巴指引你去击杀那个摧毁他家园的罪魁祸首：格伦迪格·暗云。除掉格伦迪格和他手下的蛮兵，能为那座被毁的定居点伸张正义。",h="“干掉格伦迪格·暗云”是一个由玛卡巴·扁蹄在石爪山脉东南侧道路旁给予的部落任务。在消灭了恐怖图腾暴徒和雇佣兵之后，玛卡巴指引你去击杀那个摧毁他家园的罪魁祸首：格伦迪格·暗云。除掉格伦迪格和他手下的蛮兵，能为那座被毁的定居...",kw={"蛮兵","暗云","扁蹄","恐怖图腾","格伦迪格","玛卡巴","岗哨","石爪山脉"},ang={["faction:Horde"]="石爪山脉对于部落向卡利姆多的扩张至关重要，而像格伦迪格这样激进的恐怖图腾督军，威胁到了连接贫瘠之地与烈日石居的补给线。",["race:Tauren"]="恐怖图腾氏族不断在牛头人之中播撒不和的种子，格伦迪格的屠杀行径表明，他们始终会以极端的残暴手段反对部落旗下的统一。"},sec={{t="道路屠夫",b="玛卡巴·扁蹄在石爪山脉的小径上遭遇了突如其来的暴力袭击，虽然他侥幸逃生，但心中的伤痛依然无法平复。在确认你有能力对付恐怖图腾的步兵之后，他指引你去找这场血腥屠杀的幕后黑手：格伦迪格·暗云。与那些只是趁火打劫的掠夺者不同，格伦迪格拥有一群忠心耿耿的蛮兵，并亲自带头实施了夷平该村庄的屠杀。"},{t="突袭恐怖图腾岗哨",b="格伦迪格在位于西侧山路更上方的恐怖图腾岗哨建立了营地。为了替玛卡巴的族人复仇并确保这条通道不再遭受暴力侵害，旅行者必须深入这座据点，杀穿暗云的蛮兵核心圈，并在他的袭击小队骚扰其他脆弱的营地之前，终结格伦迪格的性命。"}},faq={{q="格伦迪格·暗云是谁？",a="格伦迪格·暗云是一名残暴的恐怖图腾指挥官，以石爪山脉东南部的恐怖图腾岗哨为基地。他直接策划并领导了那场摧毁玛卡巴·扁蹄村庄的残酷袭击。",al={"格伦迪格·暗云","格伦迪格是谁","恐怖图腾首领"}},{q="在哪里可以找到格伦迪格·暗云？",a="格伦迪格·暗云位于恐怖图腾岗哨，就在靠近贫瘠之地边界、玛卡巴·扁蹄营地西侧的小径上方的山道旁。",al={"格伦迪格位置","格伦迪格在哪","恐怖图腾岗哨位置"}},{q="玛卡巴·扁蹄执行这项任务的动机是什么？",a="玛卡巴眼睁睁看着自己的家园和族人被恐怖图腾屠杀。在初步惩戒了他们的暴徒和雇佣兵之后，他请求取下首领格伦迪格·暗云的人头，以获得真正的了结与复仇。",al={"为什么杀格伦迪格","玛卡巴故事","玛卡巴复仇"}},{q="为什么恐怖图腾会袭击这里的和平定居点？",a="恐怖图腾氏族对其他牛头人部族怀有强烈的蔑视，尤其是那些与部落结盟或信奉温和道路的部族。他们经常使用伏击、掠夺和纯粹的暴力手段，将竞争对手赶出他们想要霸占的土地。",al={"为什么恐怖图腾攻击","恐怖图腾敌意"}},{q="杀掉格伦迪格·暗云之后会发生什么？",a="杀掉格伦迪格·暗云和他手下的蛮兵，就是玛卡巴·扁蹄短暂复仇链条的终点。随着这名屠夫被诛杀，玛卡巴终于可以在确认正义得到伸张后，为他的村庄哀悼。",al={"格伦迪格之后做什么","扁蹄任务链后续"}},{q="这项任务的前置任务是什么？",a="你必须先完成“复仇我的村庄”，玛卡巴·扁蹄会在该任务中测试你的决心，让你去击杀驻扎在西侧的恐怖图腾暴徒和雇佣兵。",al={"击杀格伦迪格前置","格伦迪格之前的任务"}}},fp="22,189,23.315.0,24.279.0,25.156.0,37.117.0,47.190.0,58.198.0,43.147.0,45.159.0"}
P.entries["quest:663"] = {n="法迪尔海湾",s="在法迪尔海湾，瞭望员洛洛迎接了你，并带来了一个消息：奥布里船长在此的停留时间将比原计划长得多。舰队中的两艘船，银松之魂号和少女的愚行号，已经失踪了。洛洛建议你去找船长谈谈。",h="在法迪尔海湾，瞭望员洛洛迎接了你，并带来了一个消息：奥布里船长在此的停留时间将比原计划长得多。舰队中的两艘船，银松之魂号和少女的愚行号，已经失踪了。洛洛建议你去找船长谈谈。",kw={"藏宝海湾","法迪尔海湾","先驱号","瞭望员洛洛","少女的愚行号","海角","沙克斯·奥布里","银松之魂号"},sec={{t="洛洛的欢迎",b="一直在瞭望的洛洛发现了你抵达法迪尔海湾。奥布里船长原本承诺船员们只在这里停留几个小时，时间足够收集财宝并返回藏宝海湾。洛洛怀疑事情不会那么顺利。舰队中的两艘船，银松之魂号和少女的愚行号，现在正沉在海底。任何打算留下来的人都被告知要去找船长谈话。"},{t="船长的叙述",b="奥布里船长称整件事是一团糟，并担心如果消息传出去，海角会夺走这艘船。教授的某个装置指向了海湾附近的失踪财宝，所以先驱号靠岸停泊，并向其他两艘船发出了跟随信号。随后大海隆隆作响，海水退去，两艘船都撞上了暗礁。船长说，那不仅仅是暗礁，水下有东西。如果能帮助船员，将会得到丰厚的报酬。"}},faq={{q="其他船只发生了什么事？",a="舰队中的两艘船，银松之魂号和少女的愚行号，已经失踪并沉在海底。",al={"其他船只在哪里","法迪尔海湾的沉船","是什么击沉了船只"}},{q="船员们为什么来到法迪尔海湾？",a="奥布里船长来到海湾是为了收集财宝，原计划只停留几个小时就返回藏宝海湾。",al={"他们为什么在这里","探险的目的","是什么把他们带到了阿拉希"}},{q="在法迪尔海湾应该找谁谈话？",a="如果你打算留下来，瞭望员洛洛建议你去找法迪尔海湾的奥布里船长谈谈。",al={"奥布里船长是谁","沙克斯·奥布里在哪里"}}},fp="8,195,14.382.0,21.442.1,33.87.0,39.142.0,40.94.0"}
P.entries["quest:664"] = {n="船长的复仇",s="斯迪加特船长在失去心爱的“少女的愚行”号后，正坐在法迪尔海湾哀悼。斯迪加特请求你前去追杀那些屠杀了船难幸存者的刺脊娜迦。",h="斯迪加特船长在失去心爱的“少女的愚行”号后，正坐在法迪尔海湾哀悼。斯迪加特请求你前去追杀那些屠杀了船难幸存者的刺脊娜迦。",kw={"阿拉希","刺脊","法迪尔海湾","少女的愚行","娜迦","奥布林","劫掠者","女巫","斯迪加特"},sec={{t="火边的船长",b="斯迪加特船长坐在法迪尔海湾的火堆旁，真希望自己也已葬身鱼腹。船员们拼尽全力想要挽救美丽的“少女的愚行”号，但大海吞噬了它，海水瞬间涌入。奥布林安全抵达了岸边，但娜迦杀害了幸存者。斯迪加特想要刺脊劫掠者和刺脊女巫偿命。"}},faq={{q="斯迪加特船长是谁？",a="“少女的愚行”号的船长，在船只沉没后，他现在正坐在法迪尔海湾的火堆旁。",al={"斯迪加特船长","斯迪加特","任务发布者是谁"}},{q="“少女的愚行”号发生了什么？",a="斯迪加特说大海吞噬了这艘船：上一秒它还浮在水面上，下一秒海水就涌了进来，尽管船员们竭尽全力去抢救它。",al={"少女的愚行","船怎么了","斯迪加特为何沉船"}},{q="为什么斯迪加特船长要杀死那些娜迦？",a="娜迦杀害了船难的幸存者。斯迪加特称他们为渣滓，并发誓要将他们赶尽杀绝。",al={"为什么要杀娜迦","斯迪加特的复仇","刺脊娜迦的原因"}},{q="斯迪加特想要杀死哪些娜迦？",a="十名刺脊劫掠者和三名刺脊女巫。",al={"要杀哪些娜迦","目标娜迦","刺脊目标"}}},fp="15,134,21.341.0,24.106.0,36.142.0,47.68.0,35.76.0"}
P.entries["quest:6641"] = {n="鞭笞者沃尔沙",s="鞭笞者沃什加是一头残暴的多头蛇，它在灰谷海岸的佐拉姆加前哨站肆虐，威胁着部落的立足点。当地的娜迦敬畏这只怪兽的凶猛，在离岸的一座小岛上设立了一个祭坛火盆来供奉它。部落的勇士可以通过熄灭这团圣火来激怒沃什加，将其引诱上岸，从而终结它的掠食暴行。",h="鞭笞者沃什加是一头残暴的多头蛇，它在灰谷海岸的佐拉姆加前哨站肆虐，威胁着部落的立足点。当地的娜迦敬畏这只怪兽的凶猛，在离岸的一座小岛上设立了一个祭坛火盆来供奉它。部落的勇士可以通过熄灭这团圣火来激怒沃什加，将其引诱上岸，...",kw={"灰谷","火盆","多头蛇","穆格拉什","娜迦","沃什加","佐拉姆海岸","佐拉姆加"},ang={["faction:Horde"]="保卫佐拉姆加前哨站对于维持灰谷北部的后勤补给点至关重要，那里的补给线时刻处于被攻击的状态。",["race:Orc"]="像穆格拉什这样的兽人拒绝躲在简陋的木墙后面，他们选择冲进海浪中，与掠食野兽进行面对面的猎杀。"},sec={{t="深海之恐",b="佐拉姆加前哨站位于灰谷西北部的一片狭长海岸线上，时刻受到敌对生物、暗夜精灵和蛇形入侵者的围攻。在佐拉姆海岸游荡的最具破坏性的威胁之一就是鞭笞者沃什加，这头巨大的多头蛇以对前哨站发动野蛮且无端的袭击而闻名。这头怪兽会从海浪中冲出，摧毁防御工事并屠杀守卫，然后又消失在深海之中。"},{t="娜迦的火盆",b="附近的娜迦不仅容忍这头贪婪的多头蛇，甚至积极崇拜它那掠食的恶意。在海岸外的一处礁石上，这些蛇形怪兽点燃了一座祭坛火盆，以此向沃什加致敬。穆格拉什，一名决心结束前哨站所受无休止骚扰的兽人，意识到亵渎这团仪式之火会使这头怪兽在狂怒中冲出水面，这样防御者们就能将它引诱进埋伏，而不是坐以待毙，等待下一次突如其来的屠杀。"}},faq={{q="谁是鞭笞者沃什加？",a="鞭笞者沃什加是一头凶猛巨大的多头蛇，出没于佐拉姆海岸附近的水域。它经常对佐拉姆加前哨站发动无端的袭击，摧毁营地防御并屠杀部落人员。",al={"沃什加","什么是沃什加","沃什加多头蛇"}},{q="为什么娜迦要供奉沃什加？",a="佐拉姆海岸的娜迦因沃什加那永不满足的凶猛和破坏欲而对其保持敬畏。它们在离岸处维护着一个为纪念这头怪兽邪恶本性而常年点燃的火盆，将它视作野蛮海岸狂怒的化身。",al={"为什么娜迦喜欢多头蛇","沃什加娜迦火盆","为什么要供奉沃什加"}},{q="如何引诱沃什加现身战斗？",a="穆格拉什带队突袭了娜迦照看沃什加火盆的小岛。熄灭圣火会深深激怒当地的娜迦守卫以及多头蛇本身，迫使沃什加从海中浮出水面进行报复。",al={"如何召唤沃什加","如何呼唤沃什加","火盆岛沃什加"}},{q="穆格拉什是谁？",a="穆格拉什是一名驻扎在佐拉姆加前哨站的兽人。厌倦了生活在沃什加无端海岸肆虐的恐惧中，他制定了一个计划：扑灭娜迦的祭祀火盆，并与可靠的盟友一起对抗这头怪兽。",al={"穆格拉什是谁","穆格拉什兽人","佐拉姆加穆格拉什"}},{q="为什么佐拉姆加前哨站容易受到海岸野兽的攻击？",a="佐拉姆加前哨站是一座孤立且毫无遮蔽的边境营地，直接坐落在灰谷的沙滩上。由于海中盘踞着娜迦，冲浪区又有野生多头蛇巡逻，其靠水的地理位置使它在各个方向上都容易受到两栖攻击。",al={"为什么佐拉姆加会被攻击","佐拉姆海岸危险"}},{q="鞭笞者沃什加被击败后会发生什么？",a="随着多头蛇被击败，胜利的消息会传回给坚守佐拉姆加前哨站的战歌远行者，减轻了边境守卫持续的压力，并保障了海岸免受突如其来的袭击。",al={"沃什加任务交付","向谁报告沃什加任务"}}},fp="17,243,22.435.0,23.448.0,25.200.0,29.163.0,33.193.0,15.192.0,54.209.0,35.213.1"}
P.entries["quest:665"] = {n="水下宝藏",s="既然他们现在已经成为了正式的黑水掠夺者，菲兹索普教授和德拉克里格博士就要协助奥布林先生寻找失落的精灵宝藏。为了在黑暗的海底搜寻那些宝石，教授需要你在他于洞穴中为魔法之石上的护目镜充能时提供保护。",h="既然他们现在已经成为了正式的黑水掠夺者，菲兹索普教授和德拉克里格博士就要协助奥布林先生寻找失落的精灵宝藏。为了在黑暗的海底搜寻那些宝石，教授需要你在他于洞穴中为魔法之石上的护目镜充能时提供保护。",kw={"阿拉希高地","黑水掠夺者","德拉克里格","魔法之石","护目镜","奥布林","菲兹索普","沉没的宝藏"},sec={{t="为护目镜充能",b="如果没有帮助，在黑暗的海底几乎不可能找到那些宝石，所以德拉克里格博士制造了用于搜寻的护目镜。这些护目镜需要用山坡上一小段距离外的洞穴里，一块魔法之石所蕴含的能量来充电。然而，那个洞穴被诅咒了：靠近的人都会遭到伏击。菲兹索普教授请求你在他将石头的能量充入护目镜时保护他。"}},faq={{q="是谁在寻求帮助？",a="菲兹索普教授请求你在他往返洞穴，并利用魔法之石为博士的护目镜充能的过程中保护他。",al={"谁发布此任务","菲兹索普","任务发布者"}},{q="为什么要给护目镜充能？",a="德拉克里格博士制造它们是为了帮助在黑暗的海底寻找失落的宝石。为了发挥作用，它们必须先用石头的能量来充电。",al={"为什么给护目镜充能","护目镜用途","护目镜是做什么用的"}},{q="为什么教授需要护送？",a="那个洞穴被诅咒了，当他们靠近时就会受到伏击。他需要你在他引导石头的能量时保护他。",al={"为什么要保护菲兹索普","洞穴里有什么"}},{q="教授和博士在为谁工作？",a="教授说他们现在已经是正式的黑水掠夺者了，所以协助奥布林先生寻找失落的精灵宝藏是他们的职责。",al={"他们在帮助谁","奥布林先生","黑水掠夺者"}}},fp="15,226,20.358.0,23.149.0,38.127.0,38.140.0,49.161.0"}
P.entries["quest:666"] = {n="水下宝藏",s="在完成“沉没的宝藏”的第一部分后，德拉克里格博士会将他的寻宝潜水镜借给你，并请你为奥布林船长收集十枚位于海底的精灵宝石，随后将潜水镜归还给他。",h="在完成“沉没的宝藏”的第一部分后，德拉克里格博士会将他的寻宝潜水镜借给你，并请你为奥布林船长收集十枚位于海底的精灵宝石，随后将潜水镜归还给他。",kw={"阿拉希高地","奥布林船长","德拉克里格博士","精灵宝石","法迪尔海湾","舰队指挥官卡拉·海角","寻宝潜水镜","沉没的宝藏"},sec={{t="化作顽石的宝石",b="海底的宝石因为沉没多年，已经硬化成了顽石。但潜水镜中蕴含的力量让你依然能找到它们。德拉克里格博士为这些潜水镜背后的侏儒科技感到自豪。他将潜水镜借给你，这样你就能为奥布林船长收集那些遗失的宝石。"},{t="博士的旱地工作",b="他说他本可以亲自潜下去，但安全干燥的陆地上还有科学工作在等着他。他希望事后能归还潜水镜，因为他确信奥布林船长之后还会频繁使用它们。"}},faq={{q="谁派你去收集宝石？",a="德拉克里格博士，他正在法迪尔海湾等待。他想为奥布林船长收集十枚精灵宝石。",al={"谁给予沉没的宝藏2","沉没的宝藏任务发布者"}},{q="为什么搜寻工作需要特殊的潜水镜？",a="因为沉在海底太久，这些宝石已经变成了顽石。寻宝潜水镜内置的力量让你能轻松找到它们。",al={"为什么需要寻宝潜水镜","潜水镜的作用"}},{q="为什么德拉克里格博士不亲自下水寻找宝石？",a="他说重要的科学事务使他必须留在安全干燥的陆地上。",al={"为什么德拉克里格不游泳","为什么德拉克里格待在陆地上"}},{q="你能保留寻宝潜水镜吗？",a="不能。博士只是将它们借给你，并且在你完成任务后要求归还，因为他预计奥布林船长会经常用到它们。",al={"保留寻宝潜水镜","我需要归还潜水镜吗"}},{q="这个任务在“沉没的宝藏”系列任务中处于什么位置？",a="它紧接在“沉没的宝藏”第一部分之后，在那部分里菲兹索普教授为潜水镜充了能。在此之后还有第三部分。",al={"此任务之前是什么","下一步是什么"}}},fp="15,140,20.298.0,23.211.0,33.101.0,48.130.0,57.78.0,40.120.0,50.119.0"}
P.entries["quest:6661"] = {n="捕捉矿道老鼠",s="“矿道地铁之鼠”是联盟在矿道地铁的一项任务，玩家需要协助蒙蒂进行害虫防治。玩家需使用一支迷人的音乐笛子，将活着的矿道地铁老鼠聚集起来，为蒙蒂的兄弟提供新鲜的肉类，以便制作烤鼠肉串。",h="“矿道地铁之鼠”是联盟在矿道地铁的一项任务，玩家需要协助蒙蒂进行害虫防治。玩家需使用一支迷人的音乐笛子，将活着的矿道地铁老鼠聚集起来，为蒙蒂的兄弟提供新鲜的肉类，以便制作烤鼠肉串。",kw={"矿道地铁老鼠","矿道地铁之鼠","矿道地铁","蒙蒂","捕鼠者之笛","烤鼠肉串","害虫"},ang={["profession:Cooking"]="蒙蒂的兄弟用刚捕获的矿道地铁害虫来制作烤鼠肉串，他强调这些啮齿动物在烹饪前必须保持活着，以免肉质变质。"},sec={{t="铁轨之下的害虫",b="在矿道地铁的地下管道深处，一个名叫蒙蒂的个性角色正在努力清理地下交通线上的害虫。他满口海员黑话，把地铁当成船甲板一样对待，并招募路过的旅行者帮忙驱赶那些在车站出没的乱窜害虫。"},{t="一道可疑的美味",b="蒙蒂并没有直接消灭这些啮齿动物，而是给帮手配备了一支捕鼠者之笛，吹奏迷人的旋律来引诱矿道地铁老鼠跟随。这些生物必须活着带回来，因为蒙蒂的兄弟需要新鲜的食材来进行烹饪：确切地说，是在肉变质之前把它们做成烤鼠肉串。"}},faq={{q="谁发布了“矿道地铁之鼠”任务？",a="蒙蒂，一个驻扎在矿道地铁、说话像海盗一样的角色，发布了这个任务。他正在寻找帮手来协助管理地下交通线上的鼠患。",al={"谁发布矿道地铁之鼠","蒙蒂 矿道地铁","老鼠任务发布者"}},{q="为什么蒙蒂需要活捉这些老鼠？",a="蒙蒂需要活捉这些矿道地铁老鼠，这样它们在被送到他兄弟手中做成烤鼠肉串之前才不会变质。如果这些害虫死得太早，肉就会坏掉。",al={"为什么要活捉老鼠","蒙蒂用老鼠做什么","烤鼠肉串背景故事"}},{q="如何引诱并聚集这些老鼠？",a="蒙蒂会提供一支附魔的捕鼠者之笛。在害虫附近吹奏它的旋律可以引诱它们，使老鼠跟在玩家身后回到蒙蒂的车站。",al={"如何捕捉矿道地铁老鼠","笛子有什么用","捕鼠者之笛 矿道地铁"}},{q="这项任务在哪里进行？",a="该任务发生在矿道地铁内，这是连接联盟城市暴风城和铁炉堡的地下工程奇迹。蒙蒂驻扎在地铁站台上。",al={"矿道地铁之鼠在哪里","蒙蒂位置","矿道地铁老鼠"}},{q="蒙蒂的兄弟是谁？",a="蒙蒂提到他有一个做烤鼠肉串的兄弟，但没有直接说出他的名字。他的兄弟需要源源不断的新鲜活鼠供应，以避免供应变质的肉。",al={"蒙蒂的兄弟是谁","蒙蒂的兄弟 厨师","制作烤肉串的兄弟"}},{q="为什么蒙蒂说话像个海盗？",a="虽然蒙蒂说话时带着浓重的航海海盗口音，把地铁当成船甲板一样，但他其实是在地下铁路承担着害虫防治的工作。",al={"为什么地铁里有个海盗","蒙蒂 海盗 矿道地铁"}}},fp="19,138,24.241.0,23.220.1,40.128.0,44.129.0,39.133.0,32.106.0,23.152.0,34.142.0"}
P.entries["quest:6662"] = {n="我的兄弟，尼普希",s="“我兄弟，尼普希”是一个联盟的运送任务，它带领旅行者穿过铁炉堡和暴风城之间的矿道地铁。一个名叫蒙提的侏儒委托乘客将一箱活老鼠运送给他兄弟尼普希，尼普希在地铁站的另一端经营着一个鼠肉串摊位。在这个古怪的差事之下，隐藏着诺莫瑞根悲剧后，蒙提破碎的心灵令人动容的一面。",h="“我兄弟，尼普希”是一个联盟的运送任务，它带领旅行者穿过铁炉堡和暴风城之间的矿道地铁。一个名叫蒙提的侏儒委托乘客将一箱活老鼠运送给他兄弟尼普希，尼普希在地铁站的另一端经营着一个鼠肉串摊位。在这个古怪的差事之下，隐藏着诺莫...",kw={"矿道地铁","诺莫瑞根","铁炉堡车站","我兄弟，尼普希","蒙提","神秘的肉","尼普希","鼠肉串","暴风城车站"},ang={["faction:Alliance"]="矿道地铁是连接暴风城和铁炉堡的一项必不可少的、高速的工程奇迹，在两端的车站都有古怪的当地小贩为旅行者服务。",["profession:Cooking"]="尼普希的烹饪事业围绕着将新鲜的矿道地铁老鼠串成可食用的肉串，供在铁炉堡和暴风城之间旅行的通勤者食用。",["race:Gnome"]="蒙提古怪的妄想和海盗做派直接源于诺莫瑞根事件的创伤，显示了城市陷落对幸存侏儒造成的深重个人代价。"},sec={{t="地下的运送",b="“我兄弟，尼普希”是一个简短的快递任务，它向乘客们介绍了矿道地铁的奇观——以及危险。驻扎在矿道地铁铁炉堡一侧的古怪侏儒蒙提，委托旅行者将一箱新鲜的活物通过地下交通走廊运送到暴风城仓库的他兄弟尼普希那里。这次运送凸显了连接矮人和人类首都的山脉之下正在进行的奇异日常商业活动。"},{t="鼠肉串生意",b="虽然被贴上了“装着神秘肉品的纸箱”的标签，但这包裹里其实装满了活蹦乱跳的矿道地铁老鼠。尼普希在暴风城终点站经营着一家鼠肉串企业，他需要在这些货变质前收到它们。当箱子完好无损且还在蠕动着送达时，尼普希松了一口气，因为他能继续为穿过这个交通枢纽的饥饿旅行者提供餐饮了。"},{t="诺莫瑞根的伤痕",b="在这次幽默的运送背后，隐藏着对铁炉堡流离失所的侏儒们沉痛的一瞥。蒙提用夸张的海盗俚语说话，警告旅行者要把手脚留在车内，以免落得截肢的下场。在收到老鼠后，尼普希感叹蒙提这辈子从未见过大海；他古怪的海盗人格仅仅是一种源自诺莫瑞根放射性灾难挥之不去创伤的应对机制。"}},faq={{q="谁发布了“我兄弟，尼普希”这个任务？",a="蒙提是一个在矿道地铁铁炉堡一侧发现的古怪侏儒。深受诺莫瑞根灾难影响的蒙提，尽管从未见过大海，却采用了海盗的言谈举止，并捕捉活老鼠通过地铁线运送。",al={"谁发布了“我兄弟，尼普希”","蒙提是谁","蒙提与地铁"}},{q="尼普希是谁？",a="尼普希是蒙提的兄弟，他在暴风城矿道地铁站经营着一个食品摊。他依靠蒙提通过地铁隧道运送活老鼠，以维持他的鼠肉串生意有充足的新鲜原料。",al={"尼普希是谁","尼普希在哪里","尼普希的位置"}},{q="装着神秘肉品的纸箱里装的是什么？",a="尽管贴着“神秘的肉”这种戏谑的标签，箱子里装的其实是蒙提捕捉的、活蹦乱跳的矿道地铁老鼠。尼普希坚持要求它们活着送达，这样肉才不会在被串成肉串之前变质。",al={"装着神秘肉品的纸箱是什么","神秘肉品箱","箱子里有什么"}},{q="为什么蒙提说话像个海盗？",a="蒙提说话像个海盗是因为诺莫瑞根灾难的创伤摧毁了他的心智。正如他的兄弟尼普希所感叹的那样，蒙提甚至从未见过大海，但他却执着于海盗的做派，并警告旅行者不要因为地铁轨道而失去肢体。",al={"为什么蒙提说话像海盗","蒙提是海盗吗","蒙提的海盗背景故事"}},{q="尼普希用这些老鼠做什么？",a="尼普希为经过暴风城车站的通勤者准备并出售鼠肉串。保持地铁上源源不断地运来新鲜、蠕动的小动物，是他这家非传统的地下餐馆得以经营下去的原因。",al={"尼普希用老鼠做什么","鼠肉串生意","尼普希的食物"}},{q="你要把货物送到哪里？",a="你要带着货物穿过矿道地铁，从铁炉堡车站运往暴风城终点站。登上高速地铁车厢，它会载着你穿过海底隧道，直达暴风城一侧尼普希的车站。",al={"如何找到尼普希","我该把肉送到哪","坐地铁去找尼普希"}}},fp="17,183,23.243.0,19.287.0,19.248.1,38.246.0,13.171.0,42.157.0,35.216.0,33.130.0,34.180.0"}
P.entries["quest:667"] = {n="水下伏兵",s="在阿拉希高地，沙克斯·奥布里预料到刺脊纳迦会从海上发起进攻，而如果没有奥布里对这片水域的了解，船员们就无法航行回藏宝海湾。你留在奥布里身旁，操纵大炮击退纳迦。",h="在阿拉希高地，沙克斯·奥布里预料到刺脊纳迦会从海上发起进攻，而如果没有奥布里对这片水域的了解，船员们就无法航行回藏宝海湾。你留在奥布里身旁，操纵大炮击退纳迦。",kw={"阿拉希高地","藏宝海湾","刺脊","纳迦","沙克斯·奥布里","船载大炮"},sec={{t="坚守甲板",b="在完成“沉没的财宝”任务后，沙克斯·奥布里看到刺脊纳迦正在集结准备进攻。纳迦以残忍著称，他们会不断发起攻击，直到奥布里死亡为止。奥布里并不认为自己的生命比船员们更重要，但请求你保护他们，因为如果没有那份航海知识，船员们就无法到达藏宝海湾。你和奥布里留在船上，等待纳迦从水中出现。"},{t="事后",b="袭击结束后，奥布里说船会在潮汐上涨时立刻起航。奥布里本想邀请你加入船员队伍，但看出你有更重要的使命要去完成。"}},faq={{q="谁在攻击沙克斯·奥布里？",a="刺脊纳迦正在集结准备进攻，他们会不断发起攻击，直到沙克斯·奥布里死亡为止。他们来自海上。",al={"谁攻击沙克斯","谁是攻击者","刺脊袭击"}},{q="为什么保护沙克斯·奥布里对船员如此重要？",a="沙克斯·奥布里并不认为自己的生命比船员们更重要，但如果没有奥布里对这片海洋的了解，船员们就无法航行回藏宝海湾。",al={"为什么要保护沙克斯·奥布里","为什么沙克斯很重要","沙克斯·奥布里航海术"}},{q="你如何击退纳迦的进攻？",a="你留在船上，陪伴沙克斯·奥布里并操纵大炮，在纳迦从海上袭来时将他们击退。",al={"如何完成来自下方的死亡","如何保卫沙克斯","大炮防御"}},{q="这场防守发生在什么地方？",a="在阿拉希高地沙克斯·奥布里的船上，纳迦正从海上袭来。",al={"来自下方的死亡在哪里","来自下方的死亡地点"}}},fp="16,174,16.372.0,9.176.1,32.120.0,54.138.0,34.108.0,35.87.0"}
P.entries["quest:668"] = {n="水下宝藏",s="德拉克里格博士将精灵宝石交给你，并让你将其送往奥布林船长处。在海盗中待了几周后，他和教授都明白，私藏这些财宝是不明智的。",h="德拉克里格博士将精灵宝石交给你，并让你将其送往奥布林船长处。在海盗中待了几周后，他和教授都明白，私藏这些财宝是不明智的。",kw={"阿拉希高地","奥布林船长","德拉克里格博士","精灵宝石","海盗","沙克斯·奥布里","沉没的宝藏"},sec={{t="献给船长的财宝",b="德拉克里格博士不想让奥布林船长久等，因为船长会想亲眼看看这些精灵宝石。在这些海盗中待了数周后，博士和教授都意识到，如果被发现私藏海盗的财宝，对他们的身体健康很不利。他将宝石交给你，让你带给正在甲板上等待的奥布林船长。"}},faq={{q="是谁派你去找奥布林船长的？",a="德拉克里格博士把精灵宝石交给你，并让你把它们送给奥布林船长。",al={"谁给予沉没的宝藏3","德拉克里格任务"}},{q="为什么德拉克里格博士这么急着交出宝石？",a="在这些海盗中待了几周后，他和教授认定，如果被发现私藏这些海盗的财宝，对他们的身体健康很不利。",al={"为什么要交出精灵宝石","为什么要给海盗宝石"}},{q="这个任务在任务链中处于什么位置？",a="它是“沉没的宝藏”的第三部分，其后还有第四部分。",al={"沉没的宝藏任务链位置","沉没的宝藏3之前是什么"}}},fp="15,215,24.319.0,33.72.0,55.136.0,34.82.0"}
P.entries["quest:669"] = {n="水下宝藏",s="在“沉没的宝藏”系列任务的前一步之后，沙克斯·奥布里被困在了原地，需要你给藏宝海湾的舰队指挥官卡拉·海角带个信。他请求你带上一颗宝石样本作为找到宝藏的证明。",h="在“沉没的宝藏”系列任务的前一步之后，沙克斯·奥布里被困在了原地，需要你给藏宝海湾的舰队指挥官卡拉·海角带个信。他请求你带上一颗宝石样本作为找到宝藏的证明。",kw={"阿拉希高地","黑水强盗","藏宝海湾","舰队指挥官卡拉·海角","精灵宝石样本","沙克斯·奥布里","沉没的宝藏"},sec={{t="给藏宝海湾的口信",b="沙克斯·奥布里希望舰队指挥官卡拉·海角能立刻得知宝藏被发现的消息，但他自己却无法轻易离开。潮水退得太低了，而且他们惊扰到的生物正盯着他们的一举一动。他请求你帮助黑水强盗，去藏宝海湾告诉卡拉·海角，宝藏已经被发现，且有更多的宝藏正在被打捞上来。一颗精灵宝石样本将作为证明随你一同前往。"}},faq={{q="为什么沙克斯·奥布里不能亲自去送宝石？",a="因为潮水退得太低，他们无法离开，而且他们惊扰到的生物正密切监视着他们的一举一动。",al={"为什么沙克斯无法离开","为什么沙克斯被困住了","为什么沙克斯需要信使"}},{q="舰队指挥官卡拉·海角是谁？",a="他是藏宝海湾的舰队指挥官，奥布里希望他能立刻得知发现宝藏的消息。",al={"卡拉·海角是谁","舰队指挥官卡拉·海角在哪里"}},{q="带往藏宝海湾的证明是什么？",a="一颗精灵宝石样本，用以证明宝藏已被发现，且有更多宝藏正在开采中。",al={"证明是什么","要交付的宝石是什么"}}},fp="15,117,18.301.0,49.117.0,28.88.0,41.90.0"}
P.entries["quest:67"] = {n="斯塔文的传说",s="这项任务开启了调查斯塔文·密斯特曼托命运的线索，由夜色镇市政厅的书记员达尔塔发出。他最古老的记录指向西方的西部荒野中荒废的月溪镇校舍，从而引发了一场关于一个普通人堕落过程的经典调查。",h="这项任务开启了调查斯塔文·密斯特曼托命运的线索，由夜色镇市政厅的书记员达尔塔发出。他最古老的记录指向西方的西部荒野中荒废的月溪镇校舍，从而引发了一场关于一个普通人堕落过程的经典调查。",kw={"达尔塔","暮色森林","脚柜","弃灵","密斯特曼托","月溪镇","校舍","斯塔文","西部荒野"},ang={["class:Mage"]="守护脚柜的弃灵使用变形术和削弱性的诅咒，在原本平凡的教室场景中提供了一次与被悲伤束缚的魔法进行的诡异遭遇。",["faction:Alliance"]="调查的这一阶段突显了该王国的乡村城镇已经分裂得多么严重，迫使英雄们必须穿越被迪菲亚占领的西部荒野，仅仅为了解决一个夜色镇的城镇登记查询。"},sec={{t="镇书记员的请求",b="在夜色镇进行初步询问后，书记员达尔塔调取了城镇登记册来定位斯塔文·密斯特曼托。令他惊讶的是，这份登记册多年未曾更新，上面记载的斯塔文最后已知的住址在遥远的西方，即月溪镇的校舍。由于并不知晓这桩调查背后的阴暗本质，达尔塔将其视为常规的文书工作，请求旅行者去查看该地址，并收集可能有助于更新夜色镇尘封档案的记录。"},{t="月溪镇废墟",b="追踪这条线索意味着要走出暮色森林的阴霾，进入法外之地西部荒野的尘土中。月溪镇曾经是一个繁荣的农业定居点，如今却到处都是迪菲亚潜行者的暴徒。在废弃城镇的中心附近坐落着那间荒废的校舍，在强盗的占领中静静伫立。在校舍内，一个旧脚柜里存放着斯塔文作为教师的过去生活的最初实证，以及一种束缚在箱子上、挥之不去的烦躁悲伤。"},{t="悲剧性的骚灵",b="打扰那个旧脚柜所揭露的不仅仅是被遗忘的书页；它还召唤出了一个在发掘斯塔文过去时攻击任何人的弃灵。那具幻象所带有的忧伤魔法诅咒了入侵者，并暗示了一场与这位校舍教师离开西部荒野有关的未解悲剧，标志着这桩简单的历史调查转变为一场活跃的闹鬼事件。"}},faq={{q="书记员达尔塔是谁？",a="书记员达尔塔是位于暮色森林夜色镇市政厅的城镇记录保管员。他协助在当地登记册中查找关于斯塔文·密斯特曼托的记录，却只找到了古老且过时的条目。",al={"达尔塔","夜色镇书记员","谁开启了斯塔文的传说之二"}},{q="月溪镇校舍在哪里？",a="校舍位于西部荒野西南部的月溪镇。它的建筑风格类似于夜色镇市政厅，矗立在城镇中央，周围环绕着敌对的迪菲亚强盗。",al={"月溪镇校舍位置","校舍在哪里","斯塔文脚柜在哪里"}},{q="旧脚柜里有什么？",a="脚柜中存放着斯塔文·密斯特曼托在月溪镇担任教师期间的旧记录和个人物品，提供了寻找他下落的下一个线索。",al={"斯塔文的脚柜","脚柜里有什么"}},{q="为什么打开脚柜时会有鬼魂攻击？",a="打开脚柜会召唤出一个弃灵，它会使用变形术和诅咒进行攻击。这个烦躁的幻象与围绕斯塔文的过去及其离开月溪镇的黑暗悲剧紧密相连。",al={"弃灵","为什么会刷出鬼魂","斯塔文鬼魂的诅咒"}},{q="斯塔文为什么离开西部荒野？",a="斯塔文曾在月溪镇担任校舍教师，之后为了在王国其他地方寻求私人补习工作而离开，将他旧校舍里的财物锁在了这个被遗弃的城镇中。",al={"斯塔文为何离开月溪镇","斯塔文在月溪镇的历史"}},{q="月溪镇安全吗？",a="不安全。月溪镇已完全处于迪菲亚潜行者的控制之下，这意味着任何寻找校舍的人都必须在全副武装的盗贼和暴徒中杀出一条路。",al={"月溪镇是否危险","月溪镇的怪物"}}},fp="21,175,24.393.0,22.351.0,17.289.1,20.167.0,35.166.0,34.182.0,52.182.1,31.165.0,27.114.0"}
P.entries["quest:670"] = {n="水下宝藏",s="舰队指挥官卡拉·海角目前因补给问题，船只无法离开藏宝海湾，他委托你将一封机密信件送交给正在阿拉希高地沿岸忙碌的沙克斯·奥布里。",h="舰队指挥官卡拉·海角目前因补给问题，船只无法离开藏宝海湾，他委托你将一封机密信件送交给正在阿拉希高地沿岸忙碌的沙克斯·奥布里。",kw={"阿拉希高地","黑水强盗","藏宝海湾","舰队指挥官卡拉·海角","海角的密封信","沙克斯·奥布里","沉没的宝藏"},sec={{t="给奥布里的信",b="舰队指挥官卡拉·海角打量着你，觉得你是个冒险家。由于补给尚未完成，他的船只暂时无法离开藏宝海湾，而他声称无论是本地还是海外都正在酝酿着大事。他需要将一封绝密信件送交给在阿拉希高地沿岸的沙克斯·奥布里，并询问你是否能保证安全且保密地送达此消息。"}},faq={{q="谁让你去送信？",a="藏宝海湾的舰队指挥官卡拉·海角给了你一封给沙克斯·奥布里的密封信件。",al={"谁发布沉没的宝藏5","谁开启了这个任务","海角的信任务发布者"}},{q="为什么舰队指挥官卡拉·海角不亲自去送信？",a="因为在完成补给之前，他的船只无法离开藏宝海湾。",al={"为什么海角不能离开藏宝海湾","为什么舰队指挥官卡拉·海角被困住了"}},{q="沙克斯·奥布里在哪里？",a="在阿拉希高地沿岸，海角说他正忙于那里的事务。",al={"在哪里找到沙克斯·奥布里","沙克斯·奥布里位置","沙克斯在哪里"}},{q="这次送信任务之前发生了什么？",a="这是“沉没的宝藏”任务线的第四部分后续。",al={"沉没的宝藏任务链","沉没的宝藏5之前的任务是什么"}}},fp="15,136,20.286.0,37.79.0,60.56.0,32.61.0,31.57.0"}
P.entries["quest:671"] = {n="邪恶的魔法",s="“邪恶魔法”是一个部落任务，始于阿拉希高地的落锤镇。托尔甘察觉到西方存在令人不安的恶魔气息，并在诺斯弗德农场发现了黑暗召唤仪式的痕迹。他请求冒险者前往该农场，取回用于这些召唤仪式的血石护身符，以便他研究其中的黑暗魔法。",h="“邪恶魔法”是一个部落任务，始于阿拉希高地的落锤镇。托尔甘察觉到西方存在令人不安的恶魔气息，并在诺斯弗德农场发现了黑暗召唤仪式的痕迹。他请求冒险者前往该农场，取回用于这些召唤仪式的血石护身符，以便他研究其中的黑暗魔法。",kw={"阿拉希高地","血石","血石护身符","恶魔召唤","邪恶魔法","落锤镇","诺斯弗德农场","托尔甘"},ang={["class:Warlock"]="术士非常熟悉召唤恶魔所需的仪式和束缚试剂，这使得在诺斯弗德农场发现的血石护身符成为了特别值得关注的物品。",["faction:Horde"]="由于落锤镇是部落在阿拉希高地唯一的据点，黑暗召唤者在西侧活动的行径对该定居点构成了直接的安全威胁。",["race:Orc"]="兽人与恶魔腐化之间有着沉重而痛苦的历史，残留的邪能魔法会从物理上导致他们的血液沸腾并激起非自然的愤怒。托尔甘在诺斯弗德农场附近的本能反应凸显了兽人对恶魔召唤持久的敏感性。"},sec={{t="沸腾的怒火",b="托尔甘是一名驻扎在部落前哨站落锤镇的兽人，他开始注意到阿拉希高地中弥漫着一种令人不安的波动。对于兽人而言，恶魔能量不仅仅是一种抽象的威胁；它还会引发一种根植于血之诅咒历史的本能生物反应。当托尔甘向西追踪这股让他焦躁不安的源头至诺斯弗德农场时，周围环境中的腐化气息令他的血液沸腾，并在他体内激起了一种无法克制的愤怒。在意识到这是恶魔召唤留下的明显后果后，他在黑暗影响彻底吞噬自己的理智之前撤退了，转而寻求外部的帮助，而不是亲自回去。"},{t="血石护身符",b="在诺斯弗德农场，托尔甘发现了黑暗仪式的物证：地上掉落着一块用血石雕刻而成的护身符。这些魔法护身符被积极地用于促进和稳定恶魔召唤仪式。托尔甘设法回收的那块护身符中的魔法储备已经耗尽，导致无法进行彻底的魔法分析。为了彻底调查召唤事件的程度并确定被召唤出来的实体，他指派部落的旅行者前往诺斯弗德农场，从那里的施法者手中取回十块完好的血石护身符。"}},faq={{q="谁发布了“邪恶魔法”任务？",a="该任务由托尔甘发布，他是一名位于阿拉希高地部落据点落锤镇的兽人。托尔甘感觉到附近存在一股令人不安的恶魔气息，并请求冒险者调查诺斯弗德农场，以发现究竟是何种黑暗力量在作祟。",al={"邪恶魔法任务发布者","谁开启邪恶魔法任务","托尔甘阿拉希任务"}},{q="诺斯弗德农场位于何处？",a="诺斯弗德农场位于落锤镇以西，阿拉希高地的北部丘陵地带。这里曾经是一处人类家园，如今已成为使用血石护身符进行隐秘恶魔召唤的场所。",al={"诺斯弗德农场位置","诺斯弗德农场在哪里","查找阿拉希诺斯弗德农场"}},{q="血石护身符有什么用途？",a="血石护身符是用于辅助恶魔召唤仪式的魔法媒介。托尔甘发现诺斯弗德农场的施法者使用这些石头来引导黑暗魔法，但单个护身符在召唤过程中耗尽力量后就会失去作用。",al={"什么是血石护身符","血石护身符的用途","为什么需要血石护身符"}},{q="为什么托尔甘在诺斯弗德农场附近会感到愤怒？",a="由于残留的恶魔召唤能量，托尔甘在诺斯弗德农场附近产生了剧烈的身体反应。对于兽人来说，接触邪能会激起血之诅咒的残余，导致他们的血液沸腾并引发不可控的愤怒。",al={"为什么托尔甘血液沸腾","托尔甘诺斯弗德之怒","为什么托尔甘会生气"}},{q="为什么托尔甘拒绝回到诺斯弗德农场？",a="托尔甘拒绝回到诺斯弗德农场，因为残留的恶魔力量在他体内激起了危险的怒火。由于担心自己可能会失去控制或屈服于这种腐化的影响，他招募外部的冒险者代他取回护身符。",al={"为什么托尔甘不去诺斯弗德","为什么托尔甘不回去","为什么托尔甘不能自己拿护身符"}},{q="需要多少个血石护身符？",a="托尔甘要求从诺斯弗德农场收集十个血石护身符。由于他在地上找到的那块护身符已经完全耗尽了能量，他需要多个带有能量的样本来正确地检查和理解那里正在进行的仪式。",al={"需要多少个血石护身符","血石护身符数量","邪恶魔法任务目标数量"}},{q="是谁在诺斯弗德农场召唤恶魔？",a="黑暗施法者占领了诺斯弗德农场以进行非法的恶魔召唤。他们的黑暗仪式以及由此产生的邪能残渣引起了落锤镇托尔甘的注意，促使部落对该庄园进行了调查。",al={"谁在诺斯弗德农场","谁在诺斯弗德召唤恶魔","诺斯弗德农场邪教徒"}}},fp="11,160,16.391.0,22.436.0,32.173.0,33.184.0,37.149.0,48.193.0,53.182.0,39.174.0,43.178.0"}
P.entries["quest:672"] = {n="振奋精神",s="“振奋精神”是阿拉希高地的一个部落任务，托尔甘试图借此振奋一位名叫戈穆尔的消沉兽人的精神。当关于奥格瑞玛和萨尔大酋长的故事都无济于事时，托尔甘转而利用新近被重新发现的萨满教传统，用高地迅猛龙的眼睛制作了一个能让人恢复活力的护身符。",h="“振奋精神”是阿拉希高地的一个部落任务，托尔甘试图借此振奋一位名叫戈穆尔的消沉兽人的精神。当关于奥格瑞玛和萨尔大酋长的故事都无济于事时，托尔甘转而利用新近被重新发现的萨满教传统，用高地迅猛龙的眼睛制作了一个能让人恢复活力...",kw={"阿拉希高地","戈穆尔","落锤镇","高地迅猛龙之眼","奥格瑞玛","振奋精神","萨满教","萨尔","托尔甘"},ang={["class:Shaman"]="这次努力展示了部落复兴的萨满传统如何被用来治愈情感创伤和萎靡不振，利用动物之灵重燃兄弟的求生欲望。",["faction:Horde"]="这个任务反映了萨尔领导的部落富有同情心的一面，在落锤镇这样偏远的哨所，战友们会照顾消沉的兄弟，而不是抛弃他们。",["race:Orc"]="许多像戈穆尔这样的老兵在集中营的生活和失去原本的生活方式后，依然承受着倦怠和绝望的重负，难以接受萨尔的新部落。"},sec={{t="落锤镇的沉重心情",b="在阿拉希高地偏远的落锤镇前哨站，兽人们既面临外部的敌人，也承受着内心的煎熬。他们的一员，戈穆尔，陷入了深深的、无法摆脱的忧郁之中。他的同伴们试图用卡利姆多的荣耀故事、宏伟的奥格瑞玛要塞，以及年轻大酋长萨尔的远见卓识来激励他。然而，这些伟大的胜利和遥远的奇迹都无法穿透戈穆尔心中的阴霾，也不能给他带来希望。"},{t="荒野之灵",b="托尔甘意识到单纯的言语对戈穆尔的消沉无济于事，于是他转向了部落复兴的信仰遗产。通过收集阿拉希游荡的凶猛高地迅猛龙的眼睛，托尔甘制作了一个受掠食者之灵祝福的护身符。这项仪式并没有依赖蛮力或邪能，而是调用了新近采纳的萨满教传统所带来的恢复力量，希望野兽的生命之火能唤醒这位兄弟沉睡的求生欲望。"}},faq={{q="托尔甘是谁？",a="托尔甘是驻扎在阿拉希高地部落哨所落锤镇的一名兽人。为了帮助消沉的同伴戈穆尔，托尔甘求助于部落新近重新发现的萨满魔法，制作了一个能够恢复其战友内心之火的护身符。",al={"托尔甘是谁","托尔甘 落锤镇","振奋精神 任务发布者"}},{q="戈穆尔是谁，他为什么需要振作起来？",a="戈穆尔是落锤镇的一名兽人居民，正遭受严重的消沉和倦怠困扰。尽管他的兽人同伴们试图用奥格瑞玛和萨尔领导的故事来让他振作，但没有任何事情能触动他或点燃他的精神。",al={"戈穆尔是谁","为什么戈穆尔很悲伤","落锤镇 抑郁兽人"}},{q="为什么托尔甘需要高地迅猛龙的眼睛？",a="托尔甘使用高地奔行者和高地鞭笞者的眼睛来制作萨满护身符。通过引导这些凶猛掠食者的灵魂，托尔甘希望能将迅猛龙与生俱来的力量和坚韧注入戈穆尔体内，重燃他的斗志。",al={"为什么需要迅猛龙眼睛","迅猛龙眼睛护身符","迅猛龙眼睛的作用"}},{q="这个任务发生在哪里？",a="落锤镇是阿拉希高地主要的部落前哨站，以纪念前大酋长Orgrim Doomhammer而命名。它是留在东部王国的兽人们的一处坚固避难所。",al={"落锤镇在哪里","落锤镇位置","阿拉希的兽人"}},{q="托尔甘提到的新近发现的萨满魔法是什么？",a="在遭受恶魔腐化和随后的俘虏期间，兽人失去了与元素和先祖之灵的精神联系。在大酋长萨尔的领导下，部落重新找回了这条古老的萨满之路，利用精神和谐而不是邪能来指引他们的人民。",al={"兽人萨满魔法","新部落的兽人萨满教","为什么需要新的萨满魔法"}},{q="哪些故事没能让戈穆尔振作起来？",a="他的同伴们试图用卡利姆多大海彼岸的新首都奥格瑞玛的伟大故事，以及萨尔大酋长手持Orgrim Doomhammer的盔甲和传奇战锤的英勇事迹来激励戈穆尔。",al={"关于萨尔的故事","他们讲了什么故事给戈穆尔听","奥格瑞玛 戈穆尔的故事"}}},fp="15,220,27.248.0,19.268.0,15.171.0,48.134.0,43.190.0,33.175.0,63.236.0,40.170.0"}
P.entries["quest:673"] = {n="邪恶的魔法",s="落锤镇的托尔甘确信，在斯托姆加德的城墙内住着一位强大的术士，而且那术士正使用一件奥术圣物大量召唤恶魔。在“邪恶的魔法”第一部分任务完成后，他会派你去干掉那个术士，并将圣物带回来。",h="落锤镇的托尔甘确信，在斯托姆加德的城墙内住着一位强大的术士，而且那术士正使用一件奥术圣物大量召唤恶魔。在“邪恶的魔法”第一部分任务完成后，他会派你去干掉那个术士，并将圣物带回来。",kw={"阿拉希高地","血石","落锤镇","玛瑞兹·考尔","斯托姆加德","托尔甘","术士"},sec={{t="斯托姆加德的术士",b="托尔甘确信，斯托姆加德的城墙内住着一位术士。那个术士时不时地会使用一件奥术圣物来召唤出大批可怕的恶魔。托尔甘血液中的灼烧感日益加剧。他想要找到并杀死那个术士，并将她身上那件魔法物品带回来，这样他就能将其摧毁，防止它的力量污染这片土地。那个术士名叫玛瑞兹·考尔，而那件物品就是邪恶的血石宝珠。"},{t="宝珠带来的回忆",b="随着宝珠被摧毁，托尔甘希望自己焦躁不安的夜晚能变得宁静。对他来说，这件物品勾起了他对恶魔曾经控制兽人们的恐怖回忆，那是在地狱咆哮将他们从诅咒中解放出来之前的事。"}},faq={{q="是谁派你去猎杀术士的？",a="落锤镇的托尔甘派你进入斯托姆加德，找到那个术士并取回她携带的魔法物品。",al={"谁给予邪恶的魔法","邪恶的魔法任务发布者","托尔甘任务"}},{q="那个术士在哪里？",a="玛瑞兹·考尔就在斯托姆加德的城墙内，在要塞外部的西侧，躲在一栋建筑后面。你可以听到她在引导法术的声音。",al={"玛瑞兹·考尔在哪里","斯托姆加德术士位置","哪里找到玛瑞兹·考尔"}},{q="你要取回什么圣物？",a="玛瑞兹·考尔的邪恶的血石宝珠，那是托尔甘想要你带回给他以便摧毁的魔法物品。",al={"托尔甘想要什么物品","邪恶的血石宝珠","邪恶的魔法任务物品"}},{q="为什么托尔甘要阻止那个术士？",a="那个术士已经大量召唤出了可怕的恶魔。托尔甘想要消除这种力量的源头并摧毁宝珠，这样它就不能再污染这片土地了。",al={"为什么要摧毁宝珠","托尔甘的动机","为什么要阻止术士"}}},fp="11,165,23.399.0,20.219.1,34.123.0,29.129.0,36.111.0,42.176.0"}
P.entries["quest:674"] = {n="振奋精神",s="“重燃斗志”是一个部落任务，旨在重新点燃戈穆尔的战斗意志，他是一位被绝望吞噬、深受打击的战士。一位使者送来了迅猛龙利爪护符，希望能唤醒他曾经拥有的狂野精神。然而，戈穆尔依然心怀苦涩，质疑任何简单的饰品是否真的能抚平他的悲伤，或是让部落重现荣耀。",h="“重燃斗志”是一个部落任务，旨在重新点燃戈穆尔的战斗意志，他是一位被绝望吞噬、深受打击的战士。一位使者送来了迅猛龙利爪护符，希望能唤醒他曾经拥有的狂野精神。然而，戈穆尔依然心怀苦涩，质疑任何简单的饰品是否真的能抚平他的悲...",kw={"戈穆尔","部落","重燃斗志","迅猛龙护符","迅猛龙利爪护符","战士"},ang={["class:Warrior"]="这个任务的核心是重新点燃一位兽人心中那熄灭的战士之魂，他因一次懦弱的袭击而陷入绝望和悲痛之中。",["faction:Horde"]="戈穆尔哀悼部落陨落的力量，质疑一件小小的饰品是否真的能让这个阵营恢复往日的荣耀。"},sec={{t="熄灭之焰的火星",b="“重燃斗志”涉及将一件迅猛龙利爪护符交给一位名叫戈穆尔的兽人。他的盟友希望通过这个护符引导迅猛龙的狂野力量和凶猛，从而重新唤醒这位战士曾经在他血管中熊熊燃烧的火焰。"},{t="苦涩与绝望",b="收到护符后，戈穆尔只表现出苦涩的悲痛。他深受最伟大的勇士被懦弱之手击杀的回忆所折磨，将这件信物斥为仅仅是打磨过的骨头，并质疑任何饰品怎能让部落恢复往日的荣耀。"}},faq={{q="什么是“重燃斗志”？",a="“重燃斗志”是一个任务，要求将一件迅猛龙利爪护符交给一位名叫戈穆尔的颓废战士，希望能借此重燃他的战斗精神。",al={"什么是重燃斗志","重燃斗志任务"}},{q="戈穆尔是谁？",a="戈穆尔是一位意志消沉的战士，在目睹了最伟大的勇士死于懦夫之手后，他陷入了绝望。他拒绝接受任何信物，并质疑部落的未来。",al={"戈穆尔是谁","戈穆尔"}},{q="为什么要给戈穆尔送去迅猛龙利爪护符？",a="迅猛龙利爪护符由打磨过的骨头和迅猛龙利爪制成，人们献上它，是希望通过引导迅猛龙天生的力量和凶猛，来唤醒戈穆尔心中的火焰。",al={"为什么要送护符","迅猛龙利爪护符有什么用"}},{q="为什么戈穆尔会如此颓废？",a="在目睹了最强大的战士因懦弱而倒下后，戈穆尔失去了所有的希望。这场悲剧让他确信荣誉和力量可以轻易被抹杀，这摧毁了他的战斗意志。",al={"为什么戈穆尔很悲伤","为什么戈穆尔很颓废"}},{q="戈穆尔对护符有什么反应？",a="戈穆尔拒绝了这个礼物，苦涩地将护符斥为仅仅是打磨过的骨头，认为它绝不可能恢复部落的荣耀，也无法挽回他所哀悼的那场悲剧。",al={"戈穆尔喜欢这个护符吗","戈穆尔的反应"}},{q="戈穆尔对部落说了什么？",a="戈穆尔公开质疑部落是否还能重现往日的荣耀，在卑鄙的背叛甚至能击倒最伟大的英雄时，他看不到多少希望。",al={"部落能恢复吗","戈穆尔 部落荣耀"}}},fp="15,225,26.231.0,22.218.1,24.120.0,15.164.0,50.191.0,26.182.0,37.119.0,38.130.0"}
P.entries["quest:675"] = {n="振奋精神",s="“唤醒灵魂”是一个部落任务，讲述了一位老兽人老兵挥之不去的心理创伤。在托尔甘的指引下，一位萨满试图通过先祖魔法来触动痛苦的戈穆尔，以恢复他失去的骄傲和生存意志。",h="“唤醒灵魂”是一个部落任务，讲述了一位老兽人老兵挥之不去的心理创伤。在托尔甘的指引下，一位萨满试图通过先祖魔法来触动痛苦的戈穆尔，以恢复他失去的骄傲和生存意志。",kw={"护身符","戈穆尔","怜悯","兽人","唤醒灵魂","萨满","托尔甘","老兵","酋长"},ang={["class:Shaman"]="这项任务阐述了现代兽人萨满教的修复和精神目的，利用强化的圣物来帮助治愈破碎老兵中残留的创伤。",["faction:Horde"]="在萨尔的领导下，部落积极寻求重新整合并提升那些心怀苦涩的老兵，而不是让他们沉沦于绝望。",["race:Orc"]="戈穆尔体现了那些老兵深层的精神不适和名誉受损，他们未能实现自己心中与过去的酋长一同光荣战死的愿望。"},sec={{t="破碎的灵魂",b="在历经往昔的战争后，许多兽人老兵都在艰难地承受着生存的负担和所谓的名誉扫地。戈穆尔便是这样一位战士，他因未能与倒下的酋长一同光荣战死，而陷入了苦涩的沮丧之中。身为一名富有同情心的萨满，托尔甘试图通过唤醒族人的精神力量来减轻戈穆尔的痛苦。托尔甘相信先祖能量可以治愈心灵的创伤，于是准备了一枚附魔护身符，旨在重新点燃这位老战士的自豪感。"},{t="护身符的局限",b="当把护身符交给戈穆尔时，它并未产生预期的效果。戈穆尔在愤怒的爆发中将护身符扔在泥地上，质问为什么当命运拒绝给他一个光荣的结局时，还会有人向他施舍怜悯。托尔甘从容地接受了这一挫折，他意识到单凭一枚护身符的力量不足以克服多年累积的悲伤。尽管如此，这位萨满依然坚定地执行着他的使命，决心用萨满教义的蓬勃发展最终引导戈穆尔找回往日的荣誉。"}},faq={{q="谁是戈穆尔？",a="戈穆尔是一位饱受悲痛和幸存者内疚折磨的兽人老兵。他在老部落的冲突中幸存了下来，而他的酋长却倒下了，因此他将继续活着视为命运残酷的捉弄，并拒绝一切常规的同情。",al={"戈穆尔是谁","戈穆尔的背景故事","戈穆尔出了什么问题"}},{q="托尔甘是谁，他为什么要帮助戈穆尔？",a="托尔甘是一位萨满，他试图将戈穆尔从苦涩的绝望中解救出来。托尔甘相信，重新与先祖之道建立联系可以修复破碎的灵魂，因此他制作了注入力量的护身符，以提醒昔日的战士们他们族人精神上的重生。",al={"托尔甘是谁","托尔甘想要什么","托尔甘的目的"}},{q="护身符的目的是什么？",a="护身符是托尔甘准备的一个附魔物品，旨在通过萨满能量重新唤醒戈穆尔的战士之魂。当送给戈穆尔时，他拒绝了并将其扔在地上，认为它的魔法不足以驱散他内心深处的苦涩。",al={"什么是护身符","为什么戈穆尔扔掉了护身符","护身符起作用了吗"}},{q="戈穆尔悼念的是哪位酋长？",a="虽然戈穆尔诅咒命运拒绝让他与自己的酋长一同战死，但他并没有直接说出名字。他的话语反映了老部落被击败的残部所怀有的那种悲剧视角，他们渴望在战场上光荣地死去。",al={"哪位酋长死了","戈穆尔的酋长是谁","戈穆尔曾为谁效力"}},{q="护身符失效后，托尔甘打算做什么？",a="尽管初次尝试失败了，但托尔甘保持着耐心。他承认护身符本身的力量不够强大，但他坚信，展示萨满教义的真正力量最终会重新点燃戈穆尔失去的自豪感。",al={"托尔甘放弃了吗","唤醒灵魂任务之后发生了什么","戈穆尔会恢复吗"}},{q="为什么托尔甘要用萨满教来帮助戈穆尔？",a="这一努力突显了萨满作为新部落精神治疗者的重要作用，他们的工作不仅仅是引导元素进行战争，还要抚慰族人受伤的心灵和自尊。",al={"这表明了萨满的什么特质","为什么在这里使用萨满魔法"}}},fp="15,133,15.376.0,24.363.1,15.207.0,45.240.0,35.198.0,34.118.0,52.153.0,47.132.0"}
P.entries["quest:676"] = {n="落锤之战",s="部落勇士受塔伦米尔的塔洛派遣，穿越群山进入阿拉希高地，以支援战事吃紧的落锤镇。在向杜拉姆法尔报到之前，冒险者必须在激流堡废墟附近潜伏的粗野的巨石拳食人魔身上证明自己的战斗准备情况。",h="部落勇士受塔伦米尔的塔洛派遣，穿越群山进入阿拉希高地，以支援战事吃紧的落锤镇。在向杜拉姆法尔报到之前，冒险者必须在激流堡废墟附近潜伏的粗野的巨石拳食人魔身上证明自己的战斗准备情况。",kw={"阿拉希高地","巨石拳执法者","巨石拳食人魔","杜拉姆法尔","落锤镇","希尔斯布莱德丘陵","激流堡","塔洛","塔伦米尔","粗鲁的征召"},ang={["class:Warrior"]="面对魁梧的巨石拳执法者，是那些希望获得像杜拉姆法尔这样的资深兽人指挥官尊重的先锋战士们的经典试炼场。",["faction:Horde"]="这项任务标志着从希尔斯布莱德的局部争端到阿拉希高地更大规模防御的主要过渡，巩固了落锤镇在该地区的重要立足点。",["race:Orc"]="落锤镇对兽人来说具有深厚的情感和历史价值，它是为了纪念大酋长奥格瑞姆·毁灭之锤在解放运动中牺牲而建立的。"},sec={{t="粗鲁的征召",b="在塔伦米尔，塔洛对在希尔斯布莱德丘陵游荡的未经考验的冒险者没什么耐心。看到无纪律的新兵无所事事，而遥远的盟友却在流血牺牲，他指示有能力的战士向东穿过索拉丁之墙，进入阿拉希高地。部落的前哨站落锤镇正受到多方围攻，但塔洛拒绝派遣那些没有先证明自己能应对重大威胁的人去送死。"},{t="巨石拳的试炼",b="为了不让新兵盲目闯入落锤镇，塔洛要求他们在激流堡东北方的食人魔土堆展示武力。巨石拳氏族在阿拉希有很强的势力，他们魁梧的食人魔和执法者对任何行走在高地小径上的人都构成了直接威胁。屠杀这些蛮族既能削减威胁道路侧翼的敌对势力，也能确保只有能干的战士才会抵达前哨站。"},{t="向落锤镇报到",b="在清理完巨石拳营地后，道路指向东北方的落锤镇，这是一个为纪念大酋长奥格瑞姆·毁灭之锤而命名的前哨站。在那里，指挥官杜拉姆法尔以疲惫且怀疑的态度迎接新到来者。无论塔洛是想加强防御力量，还是仅仅送这些傻瓜去送死，杜拉姆法尔都不会浪费时间，他立刻将这些已被证明了实力的战士投入到威胁前哨站生存的无休止冲突中。"}},faq={{q="这个任务在哪里接取和完成？",a="该任务由位于希尔斯布莱德丘陵塔伦米尔的塔洛提供。在完成阿拉希高地所需的击杀任务后，任务在落锤镇的部落前哨站内交给杜拉姆法尔。",al={"粗鲁的征召从哪里开始","任务交付地点","谁提供了粗鲁的征召任务"}},{q="巨石拳食人魔在哪里？",a="巨石拳食人魔居住在阿拉希高地激流堡废墟东北方的一个显著土堆及周围营地中。",al={"巨石拳食人魔位置","阿拉希的食人魔在哪里","巨石拳土堆"}},{q="落锤镇是什么地方？",a="落锤镇是位于阿拉希高地东北部的一个加固过的部落定居点。它以纪念前大酋长奥格瑞姆·毁灭之锤的名字命名，他在兽人收容所解放战争期间在附近阵亡。",al={"什么是落锤镇","落锤镇背景故事","谁建立了落锤镇"}},{q="为什么塔洛要在报到落锤镇前让你去打食人魔？",a="落锤镇正处于不断的攻击之中，极度需要有能力的战士。塔洛派遣新兵去对付巨石拳食人魔作为严酷的试炼场，以确保任何抵达那里协助杜拉姆法尔的人都是有实战能力的，而不是一个累赘。",al={"为什么要先杀食人魔","塔洛的动机","为什么要测试我"}},{q="杜拉姆法尔是谁？",a="杜拉姆法尔是一位资深的兽人战士兼指挥官，驻守在阿拉希高地的落锤镇，负责组织防卫力量以对抗敌对的野生生物、食人魔、巨魔和联盟残部。",al={"杜拉姆法尔的身份","落锤镇指挥官","杜拉姆法尔是谁"}},{q="这个任务之后是什么？",a="向杜拉姆法尔报到后将直接开启“战斗召唤”战役，这是一系列旨在清除周边威胁的军事行动，包括威胁高地的枯木巨魔部落。",al={"后续任务","粗鲁的征召后续","接下来要做什么"}}},fp="19,217,15.379.0,20.319.0,23.345.1,36.190.0,40.123.0,34.188.0,68.189.0,16.172.0,29.183.0"}
P.entries["quest:677"] = {n="短兵相接",s="“备战”是部落的一项军事行动，由落锤镇前哨站的杜拉姆法尔在阿拉希高地发起。受到当地枯木森林巨魔与巨石拳食人魔结盟的威胁，部落对枯木部族发动了先发制人的攻势，以确保他们在该地区的立足点。",h="“备战”是部落的一项军事行动，由落锤镇前哨站的杜拉姆法尔在阿拉希高地发起。受到当地枯木森林巨魔与巨石拳食人魔结盟的威胁，部落对枯木部族发动了先发制人的攻势，以确保他们在该地区的立足点。",kw={"阿拉希高地","掷斧手","巨石拳","备战","杜拉姆法尔","落锤镇","猎头者","巫医","枯木部族"},ang={["faction:Horde"]="落锤镇孤悬于阿拉希高地，四周强敌环伺；保卫前哨站免受当地敌对势力的侵扰，对于确保部落在人类统治的土地上建立永久据点至关重要。",["race:Orc"]="落锤镇建立在第二次战争时期一处拘留营的旧址之上，它是兽人获得解放的象征，这使得保卫他们的新定居点免受敌对邻居的侵犯变得尤为重要。",["race:Troll"]="对于效忠萨尔部落的暗矛巨魔来说，与敌对的枯木森林巨魔作战，凸显了他们的人民与那些拒绝新部落的部族之间截然不同的分野。"},sec={{t="保卫落锤镇",b="在落锤镇这座坚固的堡垒中，杜拉姆法尔组织了一场针对阿拉希高地敌对原住民势力的先发制人军事打击。由于被古老的人类遗迹和当地的敌对派系所包围，这座部落定居点正面临严峻威胁，威胁来自于当地土著枯木森林巨魔与野蛮的巨石拳食人魔之间形成的合作条约。杜拉姆法尔没有坐等敌人掌握生存的主动权，而是号召勇士们发起进攻。"},{t="枯木部族的威胁",b="最初的攻势集中在落锤镇以南，目标直指枯木部族领地的核心。枯木部族拒绝了任何外交手段，转而选择与巨石拳食人魔密谋，试图将部落势力从高地清除出去。通过猎杀他们精锐的掷斧手、猎头者和巫医，落锤镇试图摧毁他们的军事领导层，并表明部落将在此扎根。"}},faq={{q="谁发布了“备战”任务？",a="“备战”是由杜拉姆法尔发布的，他是一位驻扎在阿拉希高地东北部部落前哨站落锤镇的兽人。他负责协调防御和进攻打击，以确保营地能够在邻近势力的威胁下生存下来。",al={"谁发布备战","杜拉姆法尔在哪里","备战任务发布者"}},{q="为什么落锤镇要攻击枯木巨魔？",a="枯木森林巨魔部族已经与巨石拳食人魔结盟，意图将部落从阿拉希高地清除出去。由于他们拒绝了和平共处，并背弃了部落，他们咄咄逼人的态势使得落锤镇别无选择，只能先发制人。",al={"为什么要杀枯木巨魔","为什么攻击阿拉希的巨魔","枯木部族做了什么"}},{q="枯木巨魔位于何处？",a="枯木巨魔居住在阿拉希高地落锤镇以南的数个定居点和营地中，包括靠近山脉的枯木村深处。",al={"枯木巨魔在哪里","枯木营地位置","去哪里找阿拉希的掷斧手"}},{q="巨石拳食人魔在这个冲突中扮演什么角色？",a="巨石拳食人魔是一个居住在阿拉希高地的野蛮氏族。据杜拉姆法尔所言，他们与枯木巨魔达成了权宜之盟，旨在根除部落在高地的存在。",al={"巨石拳食人魔是谁","阿拉希的食人魔","巨石拳与巨魔结盟"}},{q="什么是落锤镇，为什么需要保卫它？",a="落锤镇是部落在阿拉希高地的主要前哨站，以大酋长奥格瑞姆·毁灭之锤的名字命名。它坐落在一处旧联盟拘留营的遗址上，是部落在东部王国来之不易的避难所和军事堡垒。",al={"什么是落锤镇","落锤镇背景","部落为何在阿拉希"}},{q="枯木巨魔是部落的一员吗？",a="不是。虽然暗矛部族的丛林巨魔是部落的成员，但枯木巨魔是东部王国的原生森林巨魔。他们对外来者怀有深切的敌意，并暴力拒绝了部落的任何接触提议。",al={"枯木部族属于部落吗","森林巨魔对部落友好吗","暗矛对战枯木"}}},fp="12,173,20.364.0,21.332.0,34.181.0,50.170.0,40.129.0,57.165.0,50.229.0,44.202.0"}
P.entries["quest:678"] = {n="短兵相接",s="“武装号召”是杜拉姆法尔在阿拉希高地的落锤镇哨所发布的部落军事试炼。在证明了自己的基本战斗素养后，冒险者们受命向西南方的矮人桥进发，去对付危险的石拳食人魔。消灭前线的蛮兵和施法者法师，既能考验勇士的决心，也能保护部落在阿拉希脆弱的立足点。",h="“武装号召”是杜拉姆法尔在阿拉希高地的落锤镇哨所发布的部落军事试炼。在证明了自己的基本战斗素养后，冒险者们受命向西南方的矮人桥进发，去对付危险的石拳食人魔。消灭前线的蛮兵和施法者法师，既能考验勇士的决心，也能保护部落在阿...",kw={"阿拉希高地","石拳","石拳蛮兵","石拳法师","武装号召","杜拉姆法尔","落锤镇","食人魔","萨多尔大桥"},ang={["class:Mage"]="对抗石拳法师可以让法师们反制那些将奥术能量引向原始破坏目的的野蛮施法者。",["class:Warrior"]="杜拉姆法尔要求在面对蛮力和奥术力量时展现坚韧，这对勇士们的战斗耐力和尚武荣誉是一次直接的考验。",["faction:Horde"]="保卫落锤镇对于部落在东部王国的立足至关重要，铲除富有侵略性的石拳食人魔可以防止哨所被淹没。",["race:Orc"]="落锤镇是以大酋长奥格瑞姆·毁灭之锤的名字命名的，这使得兽人们在驱逐威胁这座纪念性据点的任何竞争对手时，都有着深切的个人情感羁绊。"},sec={{t="勇气考验",b="在孤立的部落据点落锤镇，生存需要坚定不移的尚武精神。杜拉姆法尔认识到那些援助哨所的旅者能力在不断增强，因此他拒绝让任何人因为轻松的胜利而懈怠。勇士们不仅要面对小股散兵，还必须在法尔认为的真正威胁面前证明自己的勇气：那些笨重的石拳食人魔。这些蛮兵不断骚扰部落的远征队，考验着落锤镇守卫们的决心。法尔对这项任务提出了简单的要求——勇士们要么带着战功归来，要么以勇士之魂回归，而只要在战斗中展现出坚韧不拔的品质，就能获得赞誉。"},{t="石拳威胁",b="石拳氏族在落锤镇西南方建立了一处根深蒂固的巢穴，将其势力范围延伸至连接阿拉希与湿地的宏伟矮人桥。与那些毫无纪律的野兽不同，这些食人魔既拥有压倒性的物理力量，又掌握着致命的神秘法术，既有坚韧的蛮兵，也有狡猾的法师。它们极具侵略性的存在对部落的补给线和区域统治构成了直接挑战。通过下令消灭十名石拳蛮兵和四名石拳法师，杜拉姆法尔试图削弱它们的力量，确保石拳氏族明白落锤镇的勇士绝不会让出地盘，也绝不容忍阿拉希出现竞争对手。"}},faq={{q="谁发布了“武装号召”任务？",a="该任务由杜拉姆法尔发布，他是驻扎在阿拉希高地东北部、防御森严的部落哨所——落锤镇中的一名军官。为了寻求能干的勇士来保卫据点脆弱的阵地，法尔指派久经考验的战士去打击该地区危险的敌人，以展现他们的军事纪律和原始力量。",al={"谁发布了武装号召","杜拉姆法尔任务","武装号召任务发布者"}},{q="石拳巢穴在哪里？",a="石拳食人魔定居点位于落锤镇的西南方，坐落在通往萨多尔大桥的道路沿线，那是通往湿地的大型矮人桥。这些食人魔占据了高地上的土洞和土丘，它们的肉搏战士和施法者都聚集在那里。",al={"石拳位置","食人魔在哪里","阿拉希石拳巢穴"}},{q="完成这项任务需要击败哪些敌人？",a="杜拉姆法尔指示勇士们消灭十名石拳蛮兵和四名石拳法师，然后返回落锤镇。蛮兵依靠沉重的近战攻击，而法师则在远处用奥术进行支援，这使得它们比阿拉希普通的劫掠者要危险得多。",al={"武装号召击杀数量","杀哪些食人魔","武装号召目标"}},{q="为什么石拳食人魔被认为是落锤镇的威胁？",a="石拳氏族在阿拉希建立了牢固的立足点，并屡次挑战落锤镇的部落驻军。它们靠近通往南部矮人桥的关键交通路线，威胁着部落的侦察和补给线。杜拉姆法尔认为它们是一股必须通过常规军事打击加以遏制的真正竞争势力。",al={"为什么要对抗石拳","石拳对部落敌对吗","阿拉希食人魔威胁"}},{q="杜拉姆法尔所说的“带着肉身或灵魂归来”是什么意思？",a="杜拉姆法尔那冷酷的话语反映了阿拉希部落不妥协的勇士精神。他期望他的战士们能成功生还，但也尊重那些在与强大的敌人英勇作战时牺牲的人。在他看来，在压倒性的食人魔力量面前展现出坚韧和无畏本身就是一种荣誉，无论是否能在血腥的战斗中幸存下来。",al={"杜拉姆法尔语录","灵魂归来的含义","肉身或灵魂归来"}},{q="联盟玩家可以接受这个任务吗？",a="不可以，“武装号召”严格来说是杜拉姆法尔在落锤镇内发布的部落任务。联盟军队在西部的避难谷地行动，并将落锤镇的守卫者和石拳食人魔都视为争夺阿拉希高地控制权的敌对势力。",al={"武装号召是部落独有吗","联盟阿拉希武装号召","联盟能做这个任务吗"}},{q="为什么杜拉姆法尔同时针对蛮兵和法师？",a="同时针对这两类食人魔可以抵消石拳氏族兵种组合的战术优势。蛮兵构成了吸收伤害的肌肉前线，而法师则在后方施展破坏性魔法。击败这两类敌人可以确保该氏族无法对落锤镇发起有组织的联合反击。",al={"为什么要杀法师","石拳法师的重要性","石拳蛮兵和法师"}}},fp="12,131,16.330.0,22.452.0,33.184.0,38.185.0,48.185.0,64.242.0,58.230.0,42.231.0,46.249.0"}
P.entries["quest:679"] = {n="短兵相接",s="继之前的“号角吹响”任务后，落锤镇的杜拉姆法尔宣称是时候斩断野兽的头颅了。他派你去寻找盘踞在激流堡废墟中的石拳食人魔领主和萨满。",h="继之前的“号角吹响”任务后，落锤镇的杜拉姆法尔宣称是时候斩断野兽的头颅了。他派你去寻找盘踞在激流堡废墟中的石拳食人魔领主和萨满。",kw={"阿拉希高地","石拳","石拳领主","石拳萨满","杜拉姆法尔","落锤镇","激流堡"},sec={{t="野兽的头颅",b="杜拉姆法尔说你已经证明自己有足够的能力去完成最后一击。那些发动袭击的领袖们盘踞在激流堡废墟中，他称那里是人类脆弱的象征。去猎杀石拳领主和侍奉他们的萨满吧，因为他们正试图将部落驱逐出这片土地。"}},faq={{q="是谁派你去对抗石拳领袖的？",a="杜拉姆法尔，位于阿拉希高地的部落前哨站落锤镇。",al={"谁发布号角吹响任务","杜拉姆法尔任务","谁开启了号角吹响3"}},{q="石拳领主和萨满位于何处？",a="杜拉姆法尔说那些发动袭击的领袖正躲藏在激流堡废墟中。",al={"石拳领主在哪里","石拳萨满位置","去哪里找食人魔领袖"}},{q="这一步在任务链中处于什么位置？",a="它是继之前的“号角吹响”任务后的后续，也是始于塔伦米尔的塔洛任务链的最后一步。",al={"号角吹响3之前是什么任务","号角吹响任务链","落锤镇食人魔任务链"}},{q="杜拉姆法尔希望对石拳领袖们做什么？",a="他希望作为最后一击杀掉那些领导袭击的领主和萨满，因为他们企图将部落赶出这片土地。",al={"为什么要杀石拳领主","为什么要攻击激流堡的食人魔"}}},fp="12,157,21.304.0,47.78.0,51.105.0,40.112.0,56.138.0"}
P.entries["quest:68"] = {n="斯塔文的传说",s="这次调查揭开了斯塔文·密斯曼陀黑暗传说中被遗忘的篇章。在月溪镇的一个旧脚踏箱里找到的一封覆满灰尘的信，成为了他行踪消失前居所的确凿证据，线索再次指向了夜色镇的档案记录。",h="这次调查揭开了斯塔文·密斯曼陀黑暗传说中被遗忘的篇章。在月溪镇的一个旧脚踏箱里找到的一封覆满灰尘的信，成为了他行踪消失前居所的确凿证据，线索再次指向了夜色镇的档案记录。",kw={"书记员达尔塔","斯塔文诅咒","夜色镇","暮色森林","一封覆满灰尘的信","脚踏箱","弃灵","密斯曼陀","月溪镇","斯塔文"},ang={["class:Mage"]="守护脚踏箱的敌对幽灵挥舞着欺骗性的奥术工具（如变形术）以及一种破坏性的诅咒，暗示了斯塔文所过之处编织的不自然力量。",["class:Priest"]="弃灵束缚在一个简单的纪念品箱子上，这一现象说明了一种无法在死后安息的痛苦情感负担。",["faction:Alliance"]="解开斯塔文·密斯曼陀的谜团，有助于饱受困扰的夜色镇整理登记曾穿过该地区边界的阴影人物。"},sec={{t="月溪镇的遗踪",b="在追寻斯塔文·密斯曼陀的历史时，月溪镇一个被冷落的旧脚踏箱里藏着拼图的关键碎片：一封覆满灰尘的信。月溪镇曾是一个繁荣的农业聚居点，如今已沦为废墟，到处是亡命之徒和不安的幽灵。斯塔文在这里的停留时间很短，以至于被人们遗忘，但这一被忽视的信件确凿地证实了他曾在此地停留。"},{t="脚踏箱边的闹鬼事件",b="挖掘斯塔文的遗物并没有悄无声息地进行。翻动箱子惊动了阴影中的一个弃灵，它迫切地想要守护这里留下的秘密。这个幽灵发动了迷惑的魔法和虚弱的斯塔文诅咒进行攻击，这表明无论此人遭遇了什么命运，悲伤和黑暗的咒语都紧紧缠绕着他的剩余物品。"},{t="更新城镇登记册",b="将信送回边界另一端的夜色镇，为书记员达尔塔提供了他所需的缺失证明。虽然达尔塔觉得这封信从未寄出很奇怪，但证据确凿。随着月溪镇这一环节得到证实，官僚的文书记录终于可以指引调查方向，探寻斯塔文接下来逃往了何处。"}},faq={{q="月溪镇的旧脚踏箱里有什么？",a="脚踏箱里有“一封覆满灰尘的信”，是斯塔文·密斯曼陀在月溪镇逗留期间写的。它作为确凿证据，证实了他在失踪前曾居住在该镇。",al={"我发现了什么","脚踏箱内容物","斯塔文的信"}},{q="为什么打开箱子时会有灵魂攻击？",a="一个弃灵徘徊在斯塔文被遗忘的遗物附近，一旦有人扰动箱子，它就会起身攻击。它会使用令人不安的魔法，包括恐惧、变形术以及挥之不去的斯塔文诅咒。",al={"弃灵","为什么被攻击","脚踏箱幽灵"}},{q="为什么要带这封信去见书记员达尔塔？",a="书记员达尔塔负责夜色镇市政厅的城镇记录和登记工作。他需要确切的记录来确认斯塔文过去的行踪，然后才能协助进一步追踪他。",al={"书记员达尔塔是谁","为什么要找达尔塔","夜色镇大厅"}},{q="为什么这封信从未寄出具有重要意义？",a="这封信被塞在废弃的脚踏箱里无人理睬，暗示了仓促的离去或日益增长的妄想，这加剧了围绕斯塔文行踪的诡异秘密感。",al={"未寄出的信的秘密","为什么没寄出去"}},{q="斯塔文诅咒有什么作用？",a="由守护脚踏箱的弃灵施加，斯塔文诅咒是一种虚弱的妖术，会使受害者的所有主要属性在十分钟内降低。",al={"斯塔文诅咒减益","灵魂诅咒"}},{q="把信交给达尔塔后，线索指向哪里？",a="一旦书记员达尔塔用这份来自月溪镇的证据更新了市政登记册，他就能引导你的查询方向，指向斯塔文随后的已知目的地。",al={"接下来做什么","达尔塔之后的去向","下一条线索"}}},fp="21,187,30.276.0,28.225.1,26.268.0,47.139.0,50.185.0,36.143.0,53.154.0,34.127.0,60.111.0"}
P.entries["quest:680"] = {n="真正的威胁",s="继“号召武装”之后，科林法尔告诉你，她的丈夫并不清楚落锤镇为何会遭受攻击，她请求你去杀死食人魔奥卡拉尔并将他的头颅带给她。",h="继“号召武装”之后，科林法尔告诉你，她的丈夫并不清楚落锤镇为何会遭受攻击，她请求你去杀死食人魔奥卡拉尔并将他的头颅带给她。",kw={"阿拉希高地","落锤镇","科林法尔","玛格索尔","奥卡拉尔","激流堡","阿拉索之塔"},sec={{t="对她丈夫的怨恨",b="科林法尔说你为她丈夫效力得很好，但他却完全不知道落锤镇为何会遭到攻击。罪魁祸首是玛格索尔在激流堡的走卒奥卡拉尔，他因为多年前被她丈夫击败而怀恨在心，一心想要他的命。她的占卜显示，这名食人魔已经为他设下了陷阱。"},{t="科林的隐瞒",b="科林向她的丈夫隐瞒了这名食人魔存在的迹象，因为她认为如果让他知道奥卡拉尔在哪里，他会鲁莽地冲过去。她转而请求你的帮助。你会在阿拉索之塔附近找到奥卡拉尔，她希望他的死能结束对落锤镇的攻击。"}},faq={{q="科林法尔试图保护谁？",a="她的丈夫。她的占卜告诉她，奥卡拉尔已经为他设下了陷阱，这名食人魔因为多年前被他击败而想要他的命。",al={"科林的丈夫","为什么科林需要帮助"}},{q="为什么奥卡拉尔要攻击落锤镇？",a="科林法尔称奥卡拉尔是玛格索尔在激流堡的走卒，对多年前击败他的丈夫怀有刻骨的仇恨。她说他的死将会平息这些攻击。",al={"为什么奥卡拉尔憎恨科林的丈夫","谁是奥卡拉尔","奥卡拉尔的动机"}},{q="奥卡拉尔在哪里？",a="科林法尔说他在阿拉索之塔附近。",al={"奥卡拉尔的位置","哪里找到奥卡拉尔","找到奥卡拉尔"}},{q="为什么科林要对她丈夫隐瞒这个威胁？",a="她担心如果让他知道食人魔的位置，他会鲁莽地冲过去，因此她一直没让他看到任何奥卡拉尔存在的痕迹。",al={"为何保密","为何隐藏奥卡拉尔","科林的秘密"}}},fp="15,98,28.274.0,16.266.0,35.158.0,37.171.0,26.30.0,57.135.0"}
P.entries["quest:681"] = {n="诺斯弗德农场",s="位于避难谷地的尼艾丝队长请求支援，以对抗占据诺斯弗德农场的辛迪加。他们控制了激流堡守军与南海镇之间的土地，使得补给难以运达。",h="位于避难谷地的尼艾丝队长请求支援，以对抗占据诺斯弗德农场的辛迪加。他们控制了激流堡守军与南海镇之间的土地，使得补给难以运达。",kw={"尼艾丝队长","强盗","雇佣兵","诺斯弗德农场","避难谷地","南海镇","激流堡","辛迪加"},sec={{t="苦战",b="激流堡被食人魔、辛迪加和联盟瓜分，各派势力之间进行着血腥的僵持。联盟的军队在不断减少，而敌人的势力却在壮大。守军需要来自南海镇的支援，但补给物资却迟迟不到。"},{t="农场的辛迪加",b="辛迪加占据了守军和南海镇之间的地带。尼艾丝队长希望你去他们的基地——诺斯弗德农场，消灭那里的强盗和雇佣兵，希望能借此减轻补给线的压力，让更多的物资运抵这里。"}},faq={{q="为什么尼艾丝队长想要在诺斯弗德农场攻击辛迪加？",a="南海镇是补给的来源地，但辛迪加却盘踞在南海镇和守军之间的土地上。尼艾丝希望在他们的基地消灭他们，从而减轻补给线的压力。",al={"为何攻击诺斯弗德农场","尼艾丝的目标","诺斯弗德农场任务的目的"}},{q="激流堡目前的局势如何？",a="食人魔、辛迪加和联盟瓜分了这座曾经伟大的城市，各方势力陷入了血腥的僵局。联盟的兵力正在缩减，而敌人的势力却在不断增强。",al={"激流堡战争状态","谁控制了激流堡","激流堡的状况"}},{q="联盟的补给来自哪里？",a="守军指望南海镇能提供支援，但辛迪加对中间地带的控制使得物资难以运送。",al={"谁为避难谷地提供补给","南海镇补给","补给从哪里发出"}},{q="需要在农场消灭哪些敌人？",a="在诺斯弗德农场消灭十名辛迪加强盗和六名辛迪加雇佣兵。",al={"在诺斯弗德杀谁","诺斯弗德的目标","辛迪加敌人列表"}}},fp="15,162,20.224.0,26.254.0,70.163.0,44.162.0,44.124.0,49.74.0"}
P.entries["quest:682"] = {n="激流堡徽章",s="在激流堡，辛迪加正在与一支民兵部队交战，其头目会为从阵亡民兵身上搜出的每一枚徽记支付金币。在避难谷地，尼艾丝队长希望找回这些徽记。",h="在激流堡，辛迪加正在与一支民兵部队交战，其头目会为从阵亡民兵身上搜出的每一枚徽记支付金币。在避难谷地，尼艾丝队长希望找回这些徽记。",kw={"阿拉希","徽记","尼艾丝队长","民兵","避难谷地","激流堡","辛迪加"},sec={{t="士兵的悬赏",b="在激流堡，辛迪加正与一支民兵部队交战。为了驱使手下与训练有素的士兵战斗，辛迪加的头目会对每一枚从阵亡民兵身上搜出的徽记支付金币。尼艾丝队长称他们为割喉恶徒，决不允许他们保留勇敢的阵亡者身上的战利品，因此你被派往辛迪加控制下的激流堡区域搜寻这些徽记，并将它们带回避难谷地。尼艾丝希望让辛迪加明白，他们无法靠死人牟利。"},{t="狩猎之后",b="尼艾丝承诺会告知阵亡者的亲属，他们是战死沙场的。虽然传递这样的消息很残酷，但尼艾丝认为这总比让一个家庭去猜测失踪亲人的下落要好。"}},faq={{q="辛迪加为什么要激流堡徽记？",a="他们的头目对民兵设下了悬赏：每一枚从阵亡民兵身上搜出的徽记都能换取金币，这是为了驱使辛迪加的追随者去攻击那些训练有素的部队。",al={"为什么要辛迪加徽记","辛迪加激流堡悬赏","为什么要收集徽记"}},{q="徽记在哪里可以找到？",a="尼艾丝队长派你进入激流堡中辛迪加控制的区域去寻找这些徽记。",al={"哪里可以找到徽记","激流堡徽记位置","徽记掉落位置"}},{q="是谁下令收回这些徽记的？",a="避难谷地的尼艾丝队长，她不希望辛迪加保留阵亡民兵的战利品。",al={"谁发放激流堡徽记任务","尼艾丝队长徽记任务","激流堡徽记任务发布者"}}},fp="17,132,20.450.0,14.215.1,46.161.0,27.74.0,39.128.0"}
P.entries["quest:683"] = {n="萨拉·巴鲁的请求",s="“萨拉·巴鲁的请求”是一项沉重的任务，委托人是铁炉堡一位悲痛的矮人遗孀。萨拉因沉浸在巨大的悲痛中，无法直面她的君主，因此将一封写给国王麦格尼·铜须的私人请愿书托付给你，这封信是关于她阵亡的丈夫萨利·巴鲁的。",h="“萨拉·巴鲁的请求”是一项沉重的任务，委托人是铁炉堡一位悲痛的矮人遗孀。萨拉因沉浸在巨大的悲痛中，无法直面她的君主，因此将一封写给国王麦格尼·铜须的私人请愿书托付给你，这封信是关于她阵亡的丈夫萨利·巴鲁的。",kw={"国王的敬意","丹莫罗","铁炉堡","麦格尼·铜须","萨拉·巴鲁","萨利·巴鲁","萨多尔大桥"},ang={["faction:Alliance"]="在悲伤的市民和联盟领袖之间传递信息，突显了普通民众在保卫王国的冲突中所承受的个人代价。",["race:Dwarf"]="将一位悲伤遗孀的请求直接呈交给你们的国王，触及了矮人文化中对石艺、血统和尊崇先祖牺牲的深厚重视。"},sec={{t="遗孀的请求",b="在从萨多尔大桥深处的水中找回了那封凄惨的遗书后，萨拉·巴鲁悲痛欲绝。为了不让丈夫萨利的牺牲被世人遗忘，她写下了一封呈交给铁炉堡王座的请愿书。由于悲伤过度，她无法亲自前往宫廷遵守礼仪，因此将这封密封的羊皮纸交给了一位值得信赖的联盟勇士，代她向国王麦格尼·铜须陈情。"},{t="觐见国王",b="向铁炉堡的王座厅呈递私人请愿书绝非寻常琐事，但麦格尼·铜须非常关注卡兹莫丹的勇猛保卫者。在收到这份信息后，国王暂停了国事，亲自阅读了一位士兵遗孀谦卑的请求，这体现了他与那些建设并保卫他山中王国的平民矮人之间的深厚纽带。"}},faq={{q="萨拉·巴鲁是谁？",a="萨拉·巴鲁是一位铁炉堡矮人，她的丈夫是士兵萨利·巴鲁，他在萨多尔大桥的惨剧中丧生。她居住在城内，时刻怀念着她的丈夫。",al={"萨拉·巴鲁","萨拉是谁"}},{q="为什么萨拉要我去见国王，而不是自己去？",a="萨拉在最终得知丈夫的确切命运后，被悲痛淹没了。她觉得自己在王座厅向国王麦格尼·铜须请愿时，无法维持应有的礼节和镇定。",al={"为什么萨拉不能亲自去","萨拉的悲伤"}},{q="萨利·巴鲁是谁？",a="萨利·巴鲁是一位矮人士兵，曾保卫过萨多尔大桥。他在桥上的战斗中牺牲，留下了一封被水浸湿的给妻子的信。",al={"萨利·巴鲁","萨拉的丈夫"}},{q="我在哪里递交“萨拉·巴鲁的请求”？",a="你需要直接将这份请愿书送到位于铁炉堡中心的王座厅，交给国王麦格尼·铜须。",al={"麦格尼在哪里","国王麦格尼的位置","任务提交位置"}},{q="国王麦格尼阅读请愿书后会发生什么？",a="阅读萨拉的请求让国王麦格尼决心妥善纪念这位阵亡的士兵，这直接引出了后续的任务“国王的敬意”，旨在建立一座永恒的纪念碑。",al={"任务后续","下一个任务"}},{q="哪个阵营可以执行此任务？",a="这项任务仅限联盟成员执行，因为它涉及矮人的内部事务以及觐见国王麦格尼·铜须。",al={"部落可以做这个吗","阵营要求"}}},fx={ca82ce02={q="萨拉·巴鲁为什么要把她的请求送交国王麦格尼？",a="萨拉·巴鲁正为丈夫苏利·巴鲁的死而悲痛，他在保卫萨多尔大桥时阵亡。她终于收到了从桥下找回的丈夫的最后一封信，希望国王麦格尼·铜须能正式表彰苏利的牺牲，纪念他。送交这份请求，是她让铁炉堡铭记亡夫对联盟忠诚的方式。",al={"萨拉·巴鲁为什么要办这件事","萨拉·巴鲁的动机","为什么向麦格尼递交请求"}}},fp="18,101,17.321.0,22.261.1,19.150.0,63.170.0,21.141.0,38.96.0,45.126.1,37.129.0"}
P.entries["quest:684"] = {n="通缉：玛雷兹·考尔",s="“通缉：玛瑞兹·考尔”是一个联盟的赏金任务，目标是盘踞在激流堡废墟中的一名辛迪加高层特工。考尔既是一名极具影响力的顾问，也是一名与恶魔勾结的黑暗术士，她对试图收复阿拉希高地的联盟部队构成了严重威胁。",h="“通缉：玛瑞兹·考尔”是一个联盟的赏金任务，目标是盘踞在激流堡废墟中的一名辛迪加高层特工。考尔既是一名极具影响力的顾问，也是一名与恶魔勾结的黑暗术士，她对试图收复阿拉希高地的联盟部队构成了严重威胁。",kw={"阿拉希高地","赏金","尼艾丝队长","玛瑞兹·考尔","避难谷地","激流堡","辛迪加","术士"},ang={["class:Paladin"]="作为一名在古老人类王国废墟中公然与恶魔实体勾结的人，考尔的行为是对圣光和激流堡防御的公然挑衅。",["class:Warlock"]="玛瑞兹·考尔代表了辛迪加中更黑暗的邪教分支，展现了这些政治叛乱分子如何轻易地转向恶魔召唤以扩张自己的势力。",["faction:Alliance"]="在尼艾丝队长的领导下，避难谷地的联盟驻军正在奋力收复激流堡，这使得玛瑞兹·考尔这类辛迪加高层目标成为了首要的战略优先级。"},sec={{t="辛迪加头目的悬赏",b="“通缉：玛瑞兹·考尔”是一份联盟的赏金法令，旨在铲除辛迪加在阿拉希高地的关键领导人物之一。玛瑞兹·考尔在该组织中担任高层顾问和外勤特工，负责策划他们在废墟之城激流堡的活动。通过悬赏她的项上人头，避难谷地的联盟指挥官旨在摧毁辛迪加当地的指挥体系。"},{t="激流堡的术士",b="与辛迪加中常见的强盗或落魄贵族不同，玛瑞兹·考尔是一名精通黑暗巫术的施法者。她以狡诈的术士闻名，公然与恶魔势力勾结，以此贯彻自己的意志并保卫辛迪加的领地。想要进入她在激流堡的巢穴，不仅要面对那些切喉者和阴谋家，还要对抗她所驱使的邪恶实体。"}},faq={{q="玛瑞兹·考尔是谁？",a="玛瑞兹·考尔是辛迪加内部的一名高级特工兼顾问。她绝非普通的步兵，在这个犯罪组织中拥有相当大的影响力，并被公认为一名狡猾且危险的术士，以与恶魔势力勾结而闻名。",al={"玛瑞兹·考尔是谁","玛瑞兹·考尔背景","她是谁"}},{q="玛瑞兹·考尔在哪里？",a="玛瑞兹·考尔居住在阿拉希高地激流堡废墟中由辛迪加控制的区域。任何试图猎杀她的人都必须穿过重重盘踞的犯罪势力，才能找到她的圣所。",al={"哪里能找到玛瑞兹·考尔","玛瑞兹·考尔位置","玛瑞兹在哪里"}},{q="谁发布了针对玛瑞兹·考尔的赏金？",a="这份赏金是代表驻扎在阿拉希高地的联盟军事部队提供的。它由指挥避难谷地联盟据点的尼艾丝队长负责监管。",al={"谁发布了玛瑞兹·考尔的赏金","谁想要玛瑞兹·考尔死","谁支付赏金"}},{q="为什么悬赏她？",a="通缉她是由于她在辛迪加担任重要的领导角色，并积极在激流堡进行恶魔召唤仪式。她的存在对挣扎着收复这座荒废王国的联盟驻军构成了直接威胁。",al={"为什么要通缉玛瑞兹·考尔","为什么悬赏玛瑞兹·考尔","为什么要杀玛瑞兹·考尔"}},{q="玛瑞兹·考尔使用什么魔法？",a="玛瑞兹不仅仅是一名政治阴谋家；她是一位造诣深厚的术士，积极召唤并与恶魔进行交易。猎人们被特别提醒，在面对她和她的恶魔爪牙时务必保持极度谨慎。",al={"玛瑞兹·考尔为什么危险","玛瑞兹·考尔的能力","玛瑞兹·考尔强吗"}},{q="在哪里交付玛瑞兹·考尔的赏金任务？",a="玛瑞兹·考尔被杀后，必须将她的人头直接带给避难谷地的尼艾丝队长，那是阿拉希高地主要的联盟前哨站。",al={"在哪里交付玛瑞兹·考尔的赏金","尼艾丝队长在哪里","交付玛瑞兹的人头"}}},fp="18,142,31.242.0,25.262.0,18.155.0,28.184.0,36.147.0,34.171.0,39.132.0,47.124.0"}
P.entries["quest:685"] = {n="通缉：奥图和法库雷斯特",s="斯托姆加德民兵发出一份悬赏令，宣布通缉辛迪加在当地势力的首领法肯雷德领主及其致命的保镖奥托。消灭他们是对这个犯罪组织在阿拉希高地的立足点的一次重大打击。必须将他们死亡的证明交给避难谷地的尼艾丝队长。",h="斯托姆加德民兵发出一份悬赏令，宣布通缉辛迪加在当地势力的首领法肯雷德领主及其致命的保镖奥托。消灭他们是对这个犯罪组织在阿拉希高地的立足点的一次重大打击。必须将他们死亡的证明交给避难谷地的尼艾丝队长。",kw={"阿拉希高地","悬赏","尼艾丝队长","法肯雷德","奥托","避难谷地","斯托姆加德民兵","辛迪加"},ang={["faction:Alliance"]="法肯雷德领主和他的辛迪加特工威胁着斯托姆加德的残余势力，这份悬赏对于保卫避难谷地和收复高地至关重要。",["race:Human"]="对于斯托姆加德的守军来说，杀死辛迪加中那些背叛的人类贵族是一场为他们陨落的王国复仇的个人之战。"},sec={{t="绝望的悬赏",b="斯托姆加德民兵已经发出了一份正式悬赏，目标是阿拉希高地的两个关键人物：法肯雷德领主和他凶猛的保镖奥托。驻扎在避难谷地的斯托姆加德守军身陷困境，他们试图打破辛迪加对祖先领地的控制。猎手们必须将两个目标的头颅交给尼艾丝队长以领取赏金。"},{t="指挥官与执行者",b="法肯雷德领主是辛迪加协同向阿拉希高地进军的幕后主使。他的死对于联盟而言是一场至关重要的战略胜利，有望严重破坏该犯罪网络在这一地区的行动。在他身边的是奥托，一位极其危险的保镖，他的刀刃已经夺去了数十名斯托姆加德残存民兵的性命。"}},faq={{q="法肯雷德领主是谁？",a="法肯雷德领主是一位贵族兼指挥官，负责领导辛迪加在阿拉希高地的行动。他的存在组织了他们对破碎的斯托姆加德王国的投机性掠夺，因此清除他成为了当地人类民兵的首要目标。",al={"法肯雷德领主是谁","法肯雷德背景故事","法肯雷德是谁"}},{q="奥托是谁？",a="奥托是法肯雷德领主的致命私人保镖。虽然他不像他的主人那样是战略策划者，但他是一位凶猛的战士，曾在高地负责杀害了数十名斯托姆加德守军。",al={"奥托是谁","法肯雷德的保镖","奥托 辛迪加"}},{q="为什么斯托姆加德民兵要悬赏他们？",a="斯托姆加德民兵悬赏他们是为了削弱辛迪加在阿拉希高地的领导层。消灭法肯雷德可以瓦解他们的区域指挥结构，而干掉奥托则可以消除一个屠杀了许多联盟战士的致命威胁。",al={"为什么悬赏法肯雷德","为什么要杀死奥托和法肯雷德","斯托姆加德悬赏"}},{q="谁为奥托和法肯雷德提供奖励？",a="法肯雷德领主和奥托的赏金由尼艾丝队长负责发放，她是驻扎在阿拉希高地避难谷地的一名斯托姆加德民兵军官。",al={"在哪里交奥托和法肯雷德的任务","尼艾丝队长是谁","法肯雷德悬赏上交"}},{q="辛迪加在阿拉希高地做什么？",a="辛迪加由没落的奥特兰克贵族和亡命之徒组成，他们希望在洛丹伦北部崩溃之际攫取土地和财富。在阿拉希高地，他们已经进入了斯托姆加德的废墟，试图从幸存的守军手中夺取控制权。",al={"辛迪加在阿拉希做什么","辛迪加在阿拉希的角色"}},{q="领取赏金需要什么证明？",a="为了领取奖励，猎手们必须将法肯雷德领主和奥托被割下的头颅直接带给避难谷地的尼艾丝队长，作为他们死亡的确凿证据。",al={"在哪里上交奥托的头颅","悬赏证明"}}},fp="28,291,18.246.0,22.253.0,24.212.0,12.163.0,55.236.0,47.146.0,52.243.0,43.121.0"}
P.entries["quest:686"] = {n="国王的礼物",s="“国王的敬意”是联盟的一项任务，由铁炉堡王座厅的国王麦格尼·铜须发放。国王被萨拉·巴鲁的悲痛深深打动，她的丈夫萨利在保卫萨多尔大桥时牺牲。国王决定用一座不朽的丰碑来纪念这位阵亡的士兵。他派遣一位冒险者去向大石匠玛布勒斯坦传达他的皇家委托。",h="“国王的敬意”是联盟的一项任务，由铁炉堡王座厅的国王麦格尼·铜须发放。国王被萨拉·巴鲁的悲痛深深打动，她的丈夫萨利在保卫萨多尔大桥时牺牲。国王决定用一座不朽的丰碑来纪念这位阵亡的士兵。他派遣一位冒险者去向大石匠玛布勒斯坦...",kw={"铁炉堡","麦格尼·铜须","玛布勒斯坦","纪念碑","萨拉·巴鲁","萨利·巴鲁","萨多尔大桥"},ang={["faction:Alliance"]="萨多尔大桥的阵亡者们为守卫卡兹莫丹与北方王国之间至关重要的补给线而献出了生命。",["race:Dwarf"]="这项任务展现了麦格尼国王对他族人的关怀，表明即使是地位最低微的矮人步兵，王座也从未将他遗忘。"},sec={{t="君主的重担",b="当国王麦格尼·铜须收到萨拉·巴鲁的恳求时，他并没有忽视这位悲伤的遗孀。虽然他知道平民可能难以理解战争中残酷的必要性，但每一位为联盟旗帜而战的士兵的牺牲，都沉重地压在他的良心上。尽管无法改变前线阵亡的冷酷事实，麦格尼还是决定确保萨利·巴鲁的牺牲永远不会被遗忘。"},{t="石匠的凿子",b="国王并没有只说些空洞的客套话，而是决定竖立一座实体纪念碑来纪念萨利。他任命冒险者作为他皇家意旨的执行者，派遣他们前往铁炉堡的各处去与大石匠玛布勒斯坦商议。身负国王的私人委托，这位石匠大师准备将一位阵亡捍卫者的记忆刻入岩石之中。"}},faq={{q="谁是萨利·巴鲁？",a="萨利·巴鲁是一名矮人士兵，在萨多尔大桥的防御战中为联盟献出了生命。他的遗孀萨拉·巴鲁在得知他的死讯后，向国王麦格尼·铜须请愿。",al={"谁是萨利","萨利·巴鲁背景故事","谁阵亡了"}},{q="为什么麦格尼国王要委托建造纪念碑？",a="国王麦格尼承载着联盟持续不断的斗争中每一位逝去矮人的沉重负担。虽然他无法让萨利回到遗孀身边，但他希望用一座不朽的皇家纪念碑来缅怀这位士兵的勇气。",al={"为什么建造纪念碑","麦格尼的动机","国王的敬意目的"}},{q="谁是大石匠玛布勒斯坦？",a="大石匠玛布勒斯坦是铁炉堡的石工大师，负责执行城内主要的市政和皇家建筑项目。麦格尼国王依靠他来雕刻萨利·巴鲁的纪念碑。",al={"谁是玛布勒斯坦","大石匠职责"}},{q="这个任务发生在哪里？",a="该任务完全在铁炉堡内进行，始于王座厅的国王麦格尼·铜须，并导向城市中其他地点的大石匠玛布勒斯坦。",al={"任务地点在哪里","任务位置"}},{q="这个任务的前置条件是什么？",a="在接受此任务之前，冒险者必须完成“萨拉·巴鲁的恳求”，将这位遗孀感人至深的信件直接送达国王麦格尼·铜须手中。",al={"前置条件","前序任务"}},{q="这座纪念碑只是为了纪念萨利·巴鲁吗？",a="虽然该纪念碑是专门以萨利·巴鲁的名义委托建造以慰藉其遗孀萨拉，但这份敬意也象征着国王对每一位为服务联盟而牺牲的矮人战士的崇敬。",al={"纪念谁","是否只为了萨利"}}},fx={["66401eff"]={q="麦格尼国王为何选择你来负责这份悼念之礼？",a="是你将萨拉·巴鲁发自肺腑的恳求直接带到了王座厅，让她个人的悲剧呈现在王座之前。因为你愿意倾听一位悲痛寡妇的哀诉，并将她的话带给国王，麦格尼便将落实王室褒奖的重任托付给你，让你负责执行他的旨意，而非交给宫廷官僚。",al={"国王的礼物为何选我","麦格尼为何派人","为何选我"}}},fp="16,177,20.284.0,18.284.0,21.176.0,42.190.0,30.203.0,33.149.0,29.91.0,39.146.0"}
P.entries["quest:687"] = {n="迷失者塞尔杜林",s="一名暮光之锤成员请求你找到迷失者塞尔杜林，他曾是该组织的一员，后来丧失了理智，并带着密斯莱尔卷轴逃走了。传言说他在荒芜之地。",h="一名暮光之锤成员请求你找到迷失者塞尔杜林，他曾是该组织的一员，后来丧失了理智，并带着密斯莱尔卷轴逃走了。传言说他在荒芜之地。",kw={"荒芜之地","葛利·硬骨","密斯莱尔","密斯莱尔卷轴","塞尔杜林","迷失者塞尔杜林","暮光之锤","萨鲁克"},sec={{t="窃取卷轴之人",b="塞尔杜林曾属于暮光之锤，直到他精神错乱，背弃了组织的教条。他在逃跑时带走了密斯莱尔卷轴。他留下的同伙没能追上他。"},{t="关于荒芜之地的传言",b="组织听说塞尔杜林藏身于荒芜之地，变得疯疯癫癫。密斯莱尔卷轴对于那位女士的回归至关重要，要得到它，你必须先找到那个拿走卷轴的人。"}},faq={{q="迷失者塞尔杜林是谁？",a="暮光之锤的前成员，他丧失了理智，摒弃了组织的教条，并带着密斯莱尔卷轴逃走了。",al={"塞尔杜林背景故事","谁是塞尔杜林","塞尔杜林剧情"}},{q="暮光之锤为什么要找他？",a="他带着密斯莱尔卷轴逃跑了，该组织声称必须找到这份卷轴才能让那位女士回归。",al={"为什么要找塞尔杜林","为什么邪教徒要找塞尔杜林"}},{q="塞尔杜林离开组织后逃到了哪里？",a="组织只掌握了一些传言，称他藏身于荒芜之地。",al={"塞尔杜林在哪里","塞尔杜林位置剧情"}},{q="这个任务之前的前置任务是什么？",a="它是《密斯莱尔的盟友》的后续。",al={"塞尔杜林前置任务","迷失者塞尔杜林的前提条件"}}},fp="18,115,28.174.0,22.184.0,26.142.0,45.140.0,49.96.0,39.36.0"}
P.entries["quest:688"] = {n="密斯莱尔的盟友",s="迈兹拉通过基石向你传话，宣称自己已经重获自由，但目前必须躲避囚禁她的人。她让你去落锤镇找萨鲁克，他说知道如何召唤她。",h="迈兹拉通过基石向你传话，宣称自己已经重获自由，但目前必须躲避囚禁她的人。她让你去落锤镇找萨鲁克，他说知道如何召唤她。",kw={"阿拉希高地","巨人","落锤镇","基石","迈兹拉","萨鲁克"},sec={{t="重获自由，但被迫隐藏",b="迈兹拉呼喊着她终于自由了。现在，她必须在囚禁她的人看不见的地方积蓄力量，因为如果现在与他们对抗，他们会再次击败并将她囚禁。她发誓，终有一天她会去面对那些囚禁她的巨人，让他们为囚禁她的行为感到后悔。"},{t="落锤镇的萨鲁克",b="迈兹拉称赞你是高贵的盟友，并表示日后还会需要你的帮助。当她准备好时，她会让你把她召唤到地面上来。现在，她让你去落锤镇找萨鲁克，因为他知道该如何做到这一点。"}},faq={{q="是谁让你去找萨鲁克的？",a="迈兹拉本人通过基石向你传话，让你去落锤镇找萨鲁克。",al={"谁给予了迈兹拉的盟友任务","迈兹拉的盟友任务发布者","谁通过基石传话"}},{q="为什么迈兹拉要躲藏起来？",a="她说如果现在面对那些囚禁她的人，他们会再次将她制服并囚禁，所以她在积蓄力量期间必须躲藏起来。",al={"为什么迈兹拉不战斗","为什么迈兹拉很虚弱","为什么迈兹拉要躲藏"}},{q="在哪里可以找到萨鲁克？",a="在落锤镇。",al={"萨鲁克的位置","萨鲁克在哪里","寻找萨鲁克"}},{q="萨鲁克在迈兹拉的计划中扮演什么角色？",a="迈兹拉说他知道如何将她召唤出来。",al={"为什么要找萨鲁克谈话","萨鲁克知道什么","萨鲁克的目的"}}},fp="16,157,15.260.0,19.211.0,23.85.0,22.122.0,25.33.0,38.49.0"}
P.entries["quest:689"] = {n="国王的礼物",s="国王麦格尼·铜须委托制作了一座纪念萨利·巴鲁的纪念碑，这位矮人战士在保卫萨多尔大桥时英勇牺牲。为了以长久的尊严纪念这位阵亡的战士，大石匠玛布勒斯坦派遣旅行者前往希尔斯布莱德取回纯净的奥特兰克花岗岩。",h="国王麦格尼·铜须委托制作了一座纪念萨利·巴鲁的纪念碑，这位矮人战士在保卫萨多尔大桥时英勇牺牲。为了以长久的尊严纪念这位阵亡的战士，大石匠玛布勒斯坦派遣旅行者前往希尔斯布莱德取回纯净的奥特兰克花岗岩。",kw={"奥特兰克花岗岩","达隆山","铁炉堡","麦格尼·铜须","玛布勒斯坦","石匠","萨利·巴鲁","萨多尔大桥"},ang={["faction:Alliance"]="从希尔斯布莱德获取材料不仅加强了联盟在分裂的北方地区的存在感，也纪念了一位为共同事业献出生命的普通士兵。",["profession:Mining"]="矿工们理解玛布勒斯坦挑剔的眼光；奥特兰克花岗岩坚硬、顽固的矿脉需要经验丰富的工匠才能在不破碎的情况下完整开采出来。",["race:Dwarf"]="纪念萨利·巴鲁触动了矮人文化的核心，在这里，石雕工艺、尚武牺牲以及对铜须国王的坚定忠诚是紧密交织在一起的。"},sec={{t="皇家委托",b="当国王麦格尼·铜须认为阵亡士兵萨利·巴鲁值得一座永恒的纪念碑时，这项任务便直接落到了铁炉堡最优秀的工匠，大石匠玛布勒斯坦的肩上。巴鲁在萨多尔大桥的灾难中丧生，这座连接矮人领地与北方王国的重要枢纽曾遭受黑铁矮人破坏者的残酷袭击。对于玛布勒斯坦来说，完成国王的皇家法令意味着创作一座能够经受住时间和战争考验的雕塑，确保矮人的牺牲在大锻炉中既不会被忽视，也不会被遗忘。"},{t="北方的岩石",b="一位矮人石匠大师绝不会满足于用普通的采石场岩石来完成国王的工程。玛布勒斯坦坚持认为，唯有奥特兰克花岗岩才能捕捉到萨利·巴鲁的神韵，这种致密、坚韧的岩石因其耐用性和纯净的质地而备受推崇。挑战在于获取它：最好的矿床位于希尔斯布莱德充满争议的丘陵地带中的达隆山附近。深入这片动荡的北方地区虽然危险，但矮人的石雕工艺需要配得上他们所纪念的英雄主义的材料。"}},faq={{q="萨利·巴鲁是谁？",a="萨利·巴鲁是一名联盟士兵，他在萨多尔大桥遭受毁灭性破坏时为了保卫它而牺牲。国王麦格尼·铜须被其遗孀萨拉·巴鲁的一封悲痛的信所打动，下令竖立一座永久性的雕像以示纪念。",al={"萨利·巴鲁","萨利·巴鲁是谁","萨利·巴鲁背景故事"}},{q="大石匠玛布勒斯坦是谁？",a="大石匠玛布勒斯坦是铁炉堡的雕塑与石工大师。他在城中的平民区工作，负责处理皇家委托，并以只使用最优质的区域性石材而引以为傲。",al={"大石匠玛布勒斯坦","玛布勒斯坦铁炉堡","谁是玛布勒斯坦"}},{q="为什么需要奥特兰克花岗岩？",a="奥特兰克花岗岩因其卓越的密度、细腻的纹理和抗侵蚀能力而在东部王国广受赞誉。玛布勒斯坦坚持认为，唯有这种品质的石材才配得上流传后世的皇家贡品。",al={"为什么选择奥特兰克花岗岩","奥特兰克花岗岩用途","什么是奥特兰克花岗岩"}},{q="达隆山在哪里？",a="达隆山是希尔斯布莱德丘陵北部的一片丘陵地区，位于海岬下方，靠近奥特兰克边境，在那里的洞穴中可以找到奥特兰克花岗岩。",al={"达隆山在哪里","达隆山位置","寻找达隆山"}},{q="萨多尔大桥发生了什么？",a="萨多尔大桥是连接湿地与阿拉希高地的巨大桥梁，遭受了黑铁矮人破坏者的袭击，他们安放炸药切断了联盟的补给路线，导致许多守卫丧生。",al={"萨多尔大桥悲剧","萨多尔大桥灾难","萨多尔大桥发生了什么"}},{q="把花岗岩带给玛布勒斯坦后会发生什么？",a="一旦提供了奥特兰克花岗岩，玛布勒斯坦就会完成纪念碑，并让你向国王麦格尼报告工程已经完工。",al={"上交花岗岩后","玛布勒斯坦雕像进度"}}},fx={["1680ec58"]={q="大石匠玛布勒斯坦为何想要完成这件事？",a="国王麦格尼·铜须亲自委托他建造一座纪念碑，纪念阵亡的士兵苏利·巴鲁。对大石匠玛布勒斯坦而言，王室的委托享有最高优先级，也要求他拿出最好的手艺。尽管他为艾泽拉斯各地无休止的流血而叹息，他仍坚持只用最上等的石料，打造一座宏伟而长存的纪念碑，不负国王的嘱托。",al={"玛布勒斯坦为何在意","玛布勒斯坦的动机","为何建造苏利·巴鲁纪念碑"}}},fp="16,192,18.364.0,18.333.0,20.224.0,30.184.0,30.206.0,21.139.0,34.192.0,54.125.0"}
P.entries["quest:69"] = {n="斯塔文的传说",s="这项任务标志着搜寻难以捉摸的斯塔文·密斯特曼托一事的关键转折，引领调查者走出暮色森林的阴霾，回向王国的腹地。在夜色镇的城镇登记册中发现的一条匆忙且被划掉的记录指向了河流对岸的闪金镇。顺着这条线索前往繁忙的狮王之傲旅店是揭开这位神秘导师去向的下一步。",h="这项任务标志着搜寻难以捉摸的斯塔文·密斯特曼托一事的关键转折，引领调查者走出暮色森林的阴霾，回向王国的腹地。在夜色镇的城镇登记册中发现的一条匆忙且被划掉的记录指向了河流对岸的闪金镇。顺着这条线索前往繁忙的狮王之傲旅店是揭...",kw={"书记员达尔塔","夜色镇","暮色森林","艾尔文森林","闪金镇","旅店老板法雷","狮王之傲旅店","斯塔文"},ang={["faction:Alliance"]="揭开南部联盟领地的地方历史和尘封线索，需要往返于像夜色镇这样的边境哨所和像闪金镇这样的核心村庄之间。",["race:Human"]="重走斯塔文的足迹会带你穿越暴风城王国的中心地带，将暮色森林闹鬼的边境与艾尔文森林熟悉的舒适感联系起来。"},sec={{t="账簿中的线索",b="在查阅夜色镇的记录时，书记员达尔塔发现了城镇登记册中的一处疏漏。在斯塔文·密斯特曼托之前的一条记录下方，隐藏着第二个目的地，书写匆忙且部分被划掉，仿佛有人改变了主意或是刻意想要掩盖其行踪。这条记录表明斯塔文计划向西北方向前往艾尔文森林，具体目标是狮王之傲旅店。"},{t="进入艾尔文森林",b="离开暮色森林阴暗的树林，前往闪金镇阳光明媚的道路，两者形成了鲜明的对比，但斯塔文过去的阴影甚至笼罩到了这里。狮王之傲旅店是艾尔文森林繁华的十字路口，迎接各地的旅行者、商人和士兵。旅店老板法雷负责管理这间忙碌的旅店，他是打听一位寻求住宿的受过教育的流浪者的最佳人选。"}},faq={{q="为什么线索指向闪金镇？",a="书记员达尔塔在夜色镇登记册中斯塔文最初的记录下方发现了第二个、部分被划掉的地址。它清楚地表明他计划前往闪金镇的狮王之傲旅店。",al={"为什么去闪金镇","为什么要前往闪金镇","斯塔文在闪金镇"}},{q="谁是书记员达尔塔？",a="书记员达尔塔是驻守在夜色镇市政厅的记录员。他负责维护当地的登记册，并协助发掘有关过去居民的历史文件。",al={"达尔塔","达尔塔是谁"}},{q="我在狮王之傲旅店应该和谁谈话？",a="你需要直接和旅店老板法雷谈话，他负责管理狮王之傲旅店，并记录着往来闪金镇的旅行者和顾客。",al={"找谁谈话","狮王之傲旅店联系人","闪金镇旅店老板"}},{q="为什么登记册上的记录被划掉了？",a="账簿上的条目只是被部分擦除，这表明斯塔文在离开暮色森林时，有人仓促或刻意地试图隐瞒他前往艾尔文森林的路线。",al={"被划掉的笔记","为什么被划掉"}},{q="这个任务涉及战斗吗？",a="不。这一阶段的调查纯粹是旅行和询问，让你安全地从夜色镇的市政厅前往闪金镇的旅店。",al={"有战斗吗","需要战斗吗"}},{q="什么是狮王之傲旅店？",a="狮王之傲旅店是艾尔文森林闪金镇的中心枢纽。它是往来于暴风城、西部荒野和暮色森林的旅行者们众所周知的休憩之所。",al={"狮王之傲旅店","闪金镇旅店"}}},fp="21,98,20.274.0,20.304.0,37.167.0,20.140.0,42.126.0,48.140.0,35.92.0,29.159.0"}
P.entries["quest:690"] = {n="马林的要求",s="“马林的请求”是暴风城法师区的大法师马林向联盟成员发布的一项任务。马林请求经验丰富的冒险者前往遥远北方的阿拉希高地避难谷地，那里的一支探险队正试图寻回激流堡陷落时遗失的珍贵魔法圣物。",h="“马林的请求”是暴风城法师区的大法师马林向联盟成员发布的一项任务。马林请求经验丰富的冒险者前往遥远北方的阿拉希高地避难谷地，那里的一支探险队正试图寻回激流堡陷落时遗失的珍贵魔法圣物。",kw={"阿拉希高地","马林","避难谷地","斯奎尔图","暴风城","激流堡","阿拉索之塔","特雷莱恩","奥术圣所"},ang={["class:Mage"]="对于造访奥术圣所的法师们来说，协助马林直接保护了与阿拉索法师遗产息息相关的珍贵奥术研究和圣物。",["faction:Alliance"]="避难谷地代表了联盟在阿拉希脆弱的残余立足点，因此从暴风城派出的任何增援对于维持该地区而言都至关重要。",["race:Human"]="激流堡曾是人类文明的摇篮；协助找回其珍宝对于阿拉索的儿女而言，不仅关乎荣誉，更关乎历史的存续。"},sec={{t="大师遗失的物品",b="驻扎在暴风城法师区的奥术圣所的大法师马林，是代表他的前导师大法师特雷莱恩行事。当尚武的王国激流堡陷入混乱与毁灭时，特雷莱恩曾在阿拉索之塔进行了绝望的坚守。随着城市陷落于敌手，特雷莱恩被迫放弃阵地，并遗留下了强大的附魔财物。马林急于在敌手染指之前取回这些遗失的文物，于是指派有能力的雇佣兵向北进发，去增援他在那里的行动人员。"},{t="避难谷地举步维艰的前哨站",b="寻找特雷莱恩圣物的道路穿过了避难谷地，这是阿拉希高地中部激流堡忠诚派的堡垒，但现在正处于困境之中。马林在防守者中的主要联络人是矮人斯奎尔图。然而，避难谷地正受到周围辛迪加暴徒、枯木巨魔和巨石食人魔的严密挤压。抵达的旅行者很快就会发现，斯奎尔图和前哨站的守军已疲于奔命，如果没有即时的援助，根本无法给予他们热情的接待。"}},faq={{q="大法师马林是谁？",a="大法师马林是一位资深的人类法师，居住在暴风城的奥术圣所。他曾是大法师特雷莱恩的学徒，如今正在暴风城协调各项工作，以寻回他这位前任导师的魔法研究成果。",al={"大法师马林","马林是谁","马林 暴风城"}},{q="为什么马林需要阿拉希的帮助？",a="激流堡近期在围攻下陷落，迫使大法师特雷莱恩逃离了阿拉索之塔。马林在当地的代理人正努力寻回特雷莱恩遗弃的魔法圣物，但他们已不堪重负，急需增援。",al={"为什么去阿拉希","马林的任务目的","为什么是阿拉希高地"}},{q="斯奎尔图在哪里？",a="斯奎尔图是一位驻扎在避难谷地的矮人斥候，该避难谷地是位于阿拉希高地中部主要贸易道路沿线的坚固联盟营地。",al={"寻找斯奎尔图","斯奎尔图位置","避难谷地在哪里"}},{q="阿拉索之塔发生了什么？",a="阿拉索之塔曾是激流堡内的一座奥术堡垒。在王国覆灭期间，大法师特雷莱恩曾试图坚守该塔以抵御入侵的辛迪加盗贼和巨石食人魔，但防御终告失败，他被迫逃离。",al={"阿拉索之塔陷落","激流堡发生了什么","特雷莱恩之塔"}},{q="向斯奎尔图报到后会发生什么？",a="斯奎尔图在初见时会显得不堪重负且表现冷淡，他会立即指引你前往避难谷地的同伴处，开始寻回特雷莱恩散落的财物。",al={"马林任务后续","马林之后的下一个任务","斯奎尔图的下一个任务"}},{q="大法师特雷莱恩是谁？",a="大法师特雷莱恩是激流堡的一位杰出法师，也是大法师马林的导师。在王国陷落前，他是阿拉索首都的主要保卫者之一。",al={"大法师特雷莱恩","特雷莱恩是谁","特雷莱恩 激流堡"}}},fx={["5671e9ba"]={q="大法师马林为何需要冒险者来执行这项任务？",a="大法师马林职责在身，必须留在遥远南方的暴风城巫师圣殿。他虽然已在阿拉希高地的避难谷地派驻了人员，但他们报告说，陷落的激流堡城周边形势危急，需要增援。四处游历的冒险者既能自由行动，迅速北上，也有足够的战斗胆识，深入正式使者难以抵达、敌人盘踞且争夺不断的废墟。",al={"为何派冒险者","马林为何选我","马林为何不亲自去"}}},fp="15,250,26.467.0,37.407.0,22.199.0,35.198.0,25.136.0,38.207.0,40.154.0,24.154.0"}
P.entries["quest:691"] = {n="证明实力",s="在避难谷地，学徒克里汀正在寻找枯木巨魔的獠牙、医药包和一把暗影猎手的刀，这些都是大法师马林的施法材料，大法师派他和斯奎尔图来收集这些东西。他请求你去阿拉希东南部，在枯木巨魔身上寻找它们。",h="在避难谷地，学徒克里汀正在寻找枯木巨魔的獠牙、医药包和一把暗影猎手的刀，这些都是大法师马林的施法材料，大法师派他和斯奎尔图来收集这些东西。他请求你去阿拉希东南部，在枯木巨魔身上寻找它们。",kw={"学徒克里汀","阿拉希高地","大法师马林","医药包","避难谷地","暗影猎手的刀","斯奎尔图","枯木巨魔","枯木獠牙"},sec={{t="马林的试剂",b="大法师马林派克里汀和斯奎尔图前往阿拉希收集试剂，在见到你之前，克里汀完全不知道该怎么收集它们。他需要十个枯木獠牙、四个医药包和一把暗影猎手的刀。枯木巨魔住在阿拉希的东南部。"},{t="枯木巨魔携带的物品",b="根据克里汀的研究，任何枯木巨魔都应该有獠牙，而巫医则携带着医药包。那把刀属于最强大的暗影猎手，是他们在完成成人礼后得到的。只有通过战斗，才能知道他们中谁持有它。"}},faq={{q="学徒克里汀在为谁工作？",a="大法师马林派克里汀和斯奎尔图前往阿拉希，为他收集试剂。",al={"谁派克里汀来的","克里汀的导师","克里汀为什么在阿拉希"}},{q="枯木巨魔住在哪里？",a="在阿拉希的东南部，那里是枯木巨魔的家园。",al={"枯木巨魔位置","哪里能找到枯木巨魔","枯木村位置"}},{q="哪些巨魔携带医药包？",a="克里汀的研究表明，是枯木巫医携带着医药包，而任何枯木巨魔应该都有獠牙。",al={"医药包来源","谁有医药包","枯木医药包"}},{q="如何获得暗影猎手的刀？",a="最强大的枯木暗影猎手应该有这把刀，这是他们在成人礼后获得的武器。至于他们之中谁持有它，只有通过战斗才能揭晓。",al={"暗影猎手的刀位置","谁掉落暗影猎手的刀","成人礼之刀"}}},fp="24,195,16.251.0,25.257.0,37.76.0,40.65.0,40.115.0,40.142.0"}
P.entries["quest:692"] = {n="遗失的卷轴碎片",s="迷失者塞尔杜林对密斯莱尔卷轴感到十分惊恐。它的魔法可能会把密斯莱尔拖出地面，但如果她已经重获自由，这张卷轴可能就是再次束缚她的唯一办法。狂怒的元素生物已经将其撕碎，并为这些残片争斗不休，而你被派去收集它们。",h="迷失者塞尔杜林对密斯莱尔卷轴感到十分惊恐。它的魔法可能会把密斯莱尔拖出地面，但如果她已经重获自由，这张卷轴可能就是再次束缚她的唯一办法。狂怒的元素生物已经将其撕碎，并为这些残片争斗不休，而你被派去收集它们。",kw={"荒芜之地","揉皱的卷轴碎片","元素生物","密斯莱尔","密斯莱尔卷轴","烧焦的卷轴碎片","迷失者塞尔杜林","撕裂的卷轴碎片"},sec={{t="危险的羊皮纸",b="当听到密斯莱尔卷轴时，迷失者塞尔杜林显得忧心忡忡，担心它的魔法会将密斯莱尔引出地面。随后他又改变了主意：如果她已经逃脱，或者正在积蓄力量准备发动攻击，那么这张卷轴正是你需要用来再次禁锢她的东西。"},{t="元素撕裂",b="卷轴已不再完整。愤怒的元素生物夺走了它，将其撕成了碎片，现在正为这些残片而争斗。你需要找回三片残卷：一片被撕裂的、一片被揉皱的、还有一片被烧焦的，塞尔杜林打算尝试修复它们。这些窃贼就在塞尔杜林身后的山丘上游荡。"}},faq={{q="是谁派你去收集卷轴碎片的？",a="迷失者塞尔杜林请求你带回被毁坏的卷轴碎片。",al={"任务发布者","谁开启了迷失的碎片任务","塞尔杜林任务"}},{q="密斯莱尔卷轴有什么用？",a="塞尔杜林说它的魔法可能会把密斯莱尔引出地面。塞尔杜林还认为，如果她已经重获自由，这就是你需要用来再次禁锢她的东西。",al={"卷轴的作用","密斯莱尔卷轴传说","为什么寻找卷轴碎片"}},{q="卷轴碎片在哪里？",a="狂怒的元素生物带走了卷轴，将其撕碎并为残片争斗。它们就在塞尔杜林身后的山丘上。",al={"谁持有这些碎片","到哪里寻找卷轴碎片","卷轴碎片位置"}},{q="这个任务的前序任务是什么？",a="它是紧接着你之前与迷失者塞尔杜林的交易而来的。",al={"前序任务","迷失的碎片的先决条件"}}},fp="18,147,21.234.0,20.209.0,46.73.0,45.150.0,31.110.0,29.57.0"}
P.entries["quest:6921"] = {n="废墟之间",s="受到佐拉姆加前哨站的耶努萨克雷委托，部落的冒险者深入被淹没的黑暗深渊神庙，试图寻回一枚深渊之核。大地之环正寻求这件圣物，以揭露入侵此地的暮光之锤教派所策划的黑暗元素阴谋。",h="受到佐拉姆加前哨站的耶努萨克雷委托，部落的冒险者深入被淹没的黑暗深渊神庙，试图寻回一枚深渊之核。大地之环正寻求这件圣物，以揭露入侵此地的暮光之锤教派所策划的黑暗元素阴谋。",kw={"废墟之间","灰谷","黑暗深渊","大地之环","深渊之核","深渊之石","耶努萨克雷","月光神殿废墟","暮光之锤","佐拉姆加前哨站"},ang={["class:Shaman"]="取回深渊之核直接服务于大地之环的目标，即保护水元素与土元素之灵免受暮光之锤的胁迫。",["faction:Horde"]="通过清理黑暗深渊内的威胁，你可以保卫佐拉姆加前哨站，并稳固部落在灰谷海岸那片充满争端的立足点。",["race:Troll"]="帮助耶努萨克雷也是在帮助一位同胞暗矛巨魔，他架起了部落与大地之环元素守护者之间的桥梁。"},sec={{t="深处的威胁",b="古老的暗夜精灵神庙黑暗深渊，曾经是供奉艾露恩的圣地，如今已沦为邪恶势力的据点。在它那被水淹没的通道深处，暮光之锤的邪教徒们建立了一个要塞。驻扎在灰谷佐拉姆加前哨站那风蚀海岸上的暗矛巨魔萨满耶努萨克雷，怀着日益增长的忧虑注视着这种腐化的蔓延，他意识到该教派企图奴役当地的元素来对抗这片土地及其守卫者。"},{t="深渊之石",b="为了对抗该教派的图谋，耶努萨克雷指派部落的勇士前往月光神殿废墟，从水下的深渊之石中取回一枚深渊之核。当技艺精湛的萨满祭司正确解读它时，深渊之核便会展现出一份关于元素潮流与扰动的详尽记录。大地之环希望借助这件神器，看穿暮光之锤的行动，并保护该地区免遭元素灾难的侵袭。"}},faq={{q="谁发布了“废墟之间”这个任务？",a="该任务由耶努萨克雷发布，他是大地之环的一位巨魔代表，驻扎在灰谷西部的佐拉姆海岸的佐拉姆加前哨站。",al={"任务发布者","任务领取地点","谁发布废墟之间任务"}},{q="什么是深渊之核？",a="深渊之核是一件特殊的远古神器，藏在遗迹中被水淹没的深渊之石内。萨满祭司读取它时，能获得一份关于元素活动的完整历史记录，揭示当地的元素是如何受到胁迫与操纵的。",al={"什么是深渊之核","深渊之石的作用","深渊之核有什么用"}},{q="大地之环为何关心黑暗深渊？",a="大地之环致力于在自然元素之间寻求平衡。那些占据了被淹没遗迹的暮光之锤邪教徒们，正在积极地腐化并胁迫元素为他们的黑暗目的服务，这威胁到了整个地区的稳定性。",al={"大地之环的目的","大地之环为何关心此事","黑暗深渊的邪教徒"}},{q="深渊之石位于何处？",a="深渊之石沉没在黑暗深渊内的月光神殿废墟的水中，探险者需要潜入水面之下才能取回深渊之核。",al={"深渊之石在哪里","深渊之核位置","月光神殿废墟深渊之核"}},{q="联盟玩家可以接取这个任务吗？",a="不行。该任务仅限部落接取，因为耶努萨克雷是在部落的佐拉姆加前哨站开展工作，并在履行他大地之环职责的同时，协助部落在灰谷的战略部署。",al={"是否部落专属","联盟版本","联盟能否进行废墟之间任务"}},{q="是什么组织占据了黑暗深渊？",a="这座洞穴神庙群已经被暮光之锤占领，这是一个致力于侍奉邪恶的上古之神实体，并将元素扭曲至灾难性目的的末日教派。",al={"谁在黑暗深渊中","黑暗深渊的敌人","暮光之锤黑暗深渊"}}},fp="17,199,20.341.0,16.355.0,38.137.0,22.197.0,58.188.0,34.152.0,37.186.0,42.139.0"}
P.entries["quest:6922"] = {n="阿奎尼斯男爵",s="当冒险者在黑暗深渊中击败水元素阿奎尼斯男爵后，可以获得一个装有污浊、腐臭液体的奇怪的水球。将它交给大地之环的耶努萨克雷，这件神器将成为灰谷下方蔓延的元素腐化的关键证据。耶努萨克雷认为，这件物品将证明是什么腐化了男爵，如果这确实是潜伏在沉没遗迹中的暮光之锤邪教徒所为，他一点也不会感到惊讶。",h="当冒险者在黑暗深渊中击败水元素阿奎尼斯男爵后，可以获得一个装有污浊、腐臭液体的奇怪的水球。将它交给大地之环的耶努萨克雷，这件神器将成为灰谷下方蔓延的元素腐化的关键证据。耶努萨克雷认为，这件物品将证明是什么腐化了男爵，如果...",kw={"灰谷","阿奎尼斯男爵","黑暗深渊","大地之环","元素腐化","耶努萨克雷","奇怪的水球","暮光之锤","佐拉姆海岸"},ang={["class:Shaman"]="大地之环将元素之灵的腐化视为对自然秩序的严重践踏。调查阿奎尼斯男爵被污染的状态对于恢复元素平衡至关重要。",["faction:Horde"]="耶努萨克雷与佐拉姆加前哨站的部落侦察兵协同工作，寻找勇敢的勇士来净化潜伏在灰谷海岸下方的腐化水域。"},sec={{t="一颗腐化的心",b="阿奎尼斯男爵并非普通的水之灵，而是在黑暗深渊被淹没的洞穴中被邪恶法术所腐化的强大元素。当这个元素被摧毁时，它会留下一颗奇怪的水球——一个坚不可摧的球体，里面盛着晃动的腐臭液体，似乎正是这种液体维持并扭曲了该生物的本质。该物体不受物理伤害，其中蕴含的能量让那些与元素平衡调和的人感到深深的不安。"},{t="大地之环的研究",b="驻扎在佐拉姆海岸的大地之环萨满耶努萨克雷一眼就认出这件神器是遭到非自然干预的证据。他和他的组织早就怀疑阿奎尼斯男爵成了黑暗势力的猎物，并将矛头直接指向了占据沉没的神庙的暮光之锤邪教徒。通过研究这个水球，耶努萨克雷不仅希望能证实该邪教的罪责，还希望能发现他们究竟使用了什么黑暗手段来奴役和扭曲艾泽拉斯的元素之灵。"}},faq={{q="阿奎尼斯男爵是谁？",a="阿奎尼斯男爵是栖息在黑暗深渊地下水域中的强大水元素。阿奎尼斯并没有自由游荡，而是被居住在神庙废墟中的黑暗修行者所腐化并束缚。",al={"阿奎尼斯是谁","阿奎尼斯首领","阿奎尼斯男爵背景故事"}},{q="奇怪的水球是什么？",a="奇怪的水球是击败阿奎尼斯男爵后留下的坚不可摧的球体。里面晃动着一种污浊、腐臭的液体，它是导致该元素处于腐化状态的污染能量来源。",al={"水球","奇怪的水球","阿奎尼斯任务物品"}},{q="耶努萨克雷为什么想要这个水球？",a="作为大地之环的成员，耶努萨克雷负责监测整个灰谷的元素异常。他研究这个水球是为了确认暮光之锤是否是造成腐化的幕后黑手，并揭开他们用来扭曲元素之灵的仪式真相。",al={"为什么要交给耶努萨克雷","耶努萨克雷的目的"}},{q="是谁腐化了阿奎尼斯男爵？",a="主要嫌疑人是盘踞在黑暗深渊深处的暮光之锤邪教徒。他们在神庙中的存在与亵渎神灵以及与非自然生物进行黑暗沟通的行动相吻合。",al={"谁腐化了阿奎尼斯","阿奎尼斯与暮光之锤","黑暗深渊的邪教徒"}},{q="耶努萨克雷在哪里？",a="耶努萨克雷是一位驻扎在灰谷西北海岸佐拉姆海岸的大地之环萨满，靠近黑暗深渊洞穴系统的入口。",al={"耶努萨克雷在哪里","交还阿奎尼斯任务","在哪里上交水球"}},{q="交还这个任务后会发生什么？",a="上交这个水球会直接引出对该地区元素危机的进一步调查，促使冒险者继续协助大地之环对抗不断增长的灾祸。",al={"下一个任务","元素危机"}}},fp="13,242,17.349.0,27.391.1,22.172.0,32.194.0,39.240.0,46.219.0,32.157.0,39.157.0"}
P.entries["quest:693"] = {n="特雷莱恩的符咒魔杖",s="位于避难谷地的斯奎尔图已经查明了特雷莱恩的第一件遗物在什么地方。科格雷什在石拳大厅拿到了特雷莱恩的符咒魔杖，斯奎尔图想要你把它取回来。",h="位于避难谷地的斯奎尔图已经查明了特雷莱恩的第一件遗物在什么地方。科格雷什在石拳大厅拿到了特雷莱恩的符咒魔杖，斯奎尔图想要你把它取回来。",kw={"阿拉希高地","石拳大厅","科格雷什","避难谷地","斯奎尔图","激流堡","萨多尔大桥","特雷莱恩","符咒魔杖","食人魔与魔杖"},sec={{t="食人魔与魔杖",b="在你为学徒克里汀完成工作后，斯奎尔图已经找到了特雷莱恩的第一件遗物的下落。科格雷什在石拳大厅持有这件遗物，并一直用它向自己的同类发射冰霜冲击，以迫使他们服从。斯奎尔图认为这个食人魔一定快要弄清楚这根魔杖的所有能力了。石拳大厅位于避难谷地以南，萨多尔大桥以东。"},{t="斯奎尔图的清单",b="当你回来时，斯奎尔图根据他的清单计算了一下，这根魔杖是第一件，还有三件没找回。另外三件都在激流堡。"}},faq={{q="谁发布了“食人魔与魔杖”这个任务？",a="阿拉希高地避难谷地的斯奎尔图。",al={"食人魔与魔杖任务发布者","谁开启食人魔与魔杖","哪里接取食人魔与魔杖"}},{q="科格雷什在哪里？",a="科格雷什在石拳大厅，它位于避难谷地以南，萨多尔大桥以东。",al={"科格雷什在哪里","科格雷什位置","找到科格雷什"}},{q="需要回收什么物品？",a="特雷莱恩的符咒魔杖，这是特雷莱恩的第一件遗物。科格雷什一直用它向同类发射冰霜冲击。",al={"科格雷什持有什么物品","什么魔杖","特雷莱恩的魔杖"}},{q="完成这个任务需要什么前提条件？",a="它是“物有所值”的后续任务，也就是你为学徒克里汀所做的工作。",al={"食人魔与魔杖前置任务","食人魔与魔杖的前提条件","食人魔与魔杖的上一个任务"}}},fp="14,161,21.321.0,14.123.1,35.79.0,27.87.0,32.134.0,45.91.0"}
P.entries["quest:694"] = {n="特雷莱恩的防御",s="斯奎尔图手持魔杖，转向包围阿拉索之塔的食人魔。为了激活塔的防御系统，他需要从巨石拳萨满手中夺取一块天蓝玛瑙，并将其送到避难谷地的学徒克里汀那里。",h="斯奎尔图手持魔杖，转向包围阿拉索之塔的食人魔。为了激活塔的防御系统，他需要从巨石拳萨满手中夺取一块天蓝玛瑙，并将其送到避难谷地的学徒克里汀那里。",kw={"学徒克里汀","天蓝玛瑙","巨石拳萨满","避难谷地","斯奎尔图","激流堡","阿拉索之塔","特雷兰的防御系统"},sec={{t="塔的防御系统",b="食人魔包围了激流堡的阿拉索之塔。斯奎尔图说，如果你想在对抗它们的同时活着拿到那些物品，就必须激活塔的防御系统。"},{t="作为钥匙的宝石",b="塔中的某些宝石被巨石拳萨满看中了并被它们抢走，但斯奎尔图说它们不会保管太久。带一块天蓝玛瑙给避难谷地的学徒克里汀，他知道如何附魔这块宝石，使它能作为一把钥匙使用。"}},faq={{q="为什么需要天蓝玛瑙？",a="斯奎尔图想要激活塔的防御系统，这样你才能面对阿拉索之塔周围的食人魔并活着拿到那些物品。经过附魔后，这块宝石就能作为钥匙使用。",al={"为什么需要天蓝玛瑙","特雷兰的防御系统目的","为什么要获取宝石"}},{q="天蓝玛瑙是从哪里来的？",a="巨石拳萨满从阿拉索之塔将它们抢走，并对这些宝石产生了兴趣。",al={"谁拿走了玛瑙","宝石来自哪里","玛瑙来源"}},{q="谁能为宝石附魔？",a="避难谷地的学徒克里汀知道附魔这块宝石的咒语，使其能作为钥匙使用。",al={"谁为玛瑙附魔","克里汀的作用","谁把它变成钥匙"}}},fp="18,190,20.166.0,15.257.0,29.161.0,37.99.0,24.91.0"}
P.entries["quest:695"] = {n="学徒的魔法",s="学徒克里汀为你从巨石萨满手中取回的玛瑙施加了附魔。将它触碰塔底的基座，就能唤醒这座塔的防御系统。在你离开之前，他让你去找斯奎尔图了解剩下的事情。",h="学徒克里汀为你从巨石萨满手中取回的玛瑙施加了附魔。将它触碰塔底的基座，就能唤醒这座塔的防御系统。在你离开之前，他让你去找斯奎尔图了解剩下的事情。",kw={"学徒克里汀","阿拉希高地","附魔玛瑙","斯奎尔图","塔","特雷莱恩"},sec={{t="塔的钥匙",b="克里汀把附魔宝石交给你。他解释说，将其触碰塔底的基座即可唤醒塔的防御，当你准备好去取回特雷莱恩剩余的物品时，就用得上它。他会在营地等你回来。首先，去和斯奎尔图谈谈，他会告诉你还需要知道的其他事情。"}},faq={{q="附魔玛瑙有什么用途？",a="触碰塔底的基座，它能唤醒塔的防御系统。当你准备好进去取回特雷莱恩剩余的物品时，就可以使用它。",al={"为什么需要玛瑙","附魔玛瑙用法","宝石的作用"}},{q="离开营地前你需要找谁谈话？",a="斯奎尔图。克里汀让你在离开前和他谈谈，因为他会告诉你还需要知道的其他事情。",al={"应该找谁谈话","下一步去哪里","谁是斯奎尔图"}},{q="克里汀会在哪里？",a="他会在营地等你回来。",al={"克里汀在哪里","克里汀等待"}}},fp="27,174,19.335.0,43.174.0,47.95.0,21.45.0"}
P.entries["quest:696"] = {n="进攻高塔",s="随着高塔的防御机制被激活，避难谷地的斯奎尔图派遣你潜入食人魔控制的高塔，去寻找特瑞莱恩的护命匣、宝珠和余烬玛瑙。它们应该就在里面的箱子里，斯奎尔图说，如果你能把它们带回来，马林一定会非常高兴。",h="随着高塔的防御机制被激活，避难谷地的斯奎尔图派遣你潜入食人魔控制的高塔，去寻找特瑞莱恩的护命匣、宝珠和余烬玛瑙。它们应该就在里面的箱子里，斯奎尔图说，如果你能把它们带回来，马林一定会非常高兴。",kw={"阿拉希高地","攻击高塔","马林","食人魔","避难谷地","斯奎尔图","特瑞莱恩","特瑞莱恩的余烬玛瑙","特瑞莱恩的宝珠","特瑞莱恩的护命匣"},sec={{t="深入高塔",b="在克莱顿施加附魔之后，斯奎尔图会告诉你需要寻找的东西：特瑞莱恩的护命匣、宝珠和余烬玛瑙。这三样东西应该就在高塔内的箱子里，你打开它们应该不成问题，不过要小心食人魔。高塔的防御机制不会主动对付它们，如果食人魔发现你在偷窃，它们会让你吃尽苦头。"},{t="斯奎尔图的裁决",b="当你带回这三样物品时，斯奎尔图会说，马林再也找不到比你更适合在这里帮忙的人了。马林得知他们的冒险取得了圆满成功，一定会非常高兴。"}},faq={{q="谁指派了这个任务？",a="斯奎尔图，位于阿拉希高地的避难谷地，就在克莱顿为宝石施加附魔之后。",al={"谁给予攻击高塔任务","攻击高塔任务发布者","在哪里接攻击高塔任务"}},{q="你被派去取回什么物品？",a="特瑞莱恩的护命匣、宝珠和余烬玛瑙。它们应该都在高塔内的一个箱子里。",al={"攻击高塔任务物品","需要获取什么圣物","特瑞莱恩的物品"}},{q="食人魔会怎么做？",a="高塔的防御机制不会帮你对付它们。如果食人魔发现你在偷窃，它们会让你吃尽苦头。",al={"食人魔危险吗","高塔食人魔"}},{q="在此之前需要完成什么？",a="紧接着“学徒的附魔”任务，在该任务中，克莱顿会为宝石施加附魔并将你引向斯奎尔图。",al={"攻击高塔任务前置","哪个任务在前"}}},fp="19,228,14.307.0,17.194.1,22.91.0,36.111.0,23.98.0,23.95.0"}
P.entries["quest:6962"] = {n="冬幕节的礼物",s="给冬天爷爷的节日点心是奥格瑞玛在冬幕节期间发布的一项节日任务。那位坐在烟林牧场展示摊位上的快乐人物在听完节日愿望后感到十分疲惫，于是向一位热心的冒险者请求一些新鲜的姜饼和牛奶。",h="给冬天爷爷的节日点心是奥格瑞玛在冬幕节期间发布的一项节日任务。那位坐在烟林牧场展示摊位上的快乐人物在听完节日愿望后感到十分疲惫，于是向一位热心的冒险者请求一些新鲜的姜饼和牛奶。",kw={"姜饼","冬天爷爷","节日香料","冰镇牛奶","奥格瑞玛","烟林牧场","给冬天爷爷的节日点心","冬幕节"},ang={["faction:Horde"]="这场盛宴由富有进取心的烟林牧场地精带到奥格瑞玛，为这座粗犷的战士之城带来了一丝难得的轻快家庭欢乐。",["profession:Cooking"]="这项节日传统为学徒厨师提供了一个练习简单烘焙的机会，将野蛋和季节性香料变成节日的姜饼。"},sec={{t="冬日里的疲惫顾客",b="虽然冬天爷爷是艾泽拉斯冬日与富足的神话象征，但在这力量谷迎接访客的这位人物，其实是烟林牧场雇佣的一名勤奋的表演者。长时间坐着听市民们谈论节日好物让他感到饥肠辘辘。厌倦了仅仅谈论节日美食，这位冬天爷爷很乐意招募路过的旅行者来满足他对热烘烘的糕点和冷饮的渴望。"},{t="节日美食精神",b="满足冬天爷爷的请求需要一点家常烹饪。冒险者必须从烟林牧场的地精商贩那里直接购买节日香料，从荒野的野生禽类身上采集小蛋，然后烘焙出经典的姜饼。配上一瓶从当地旅店购买的冰镇牛奶，这份小小的供品将回报烘焙者以节日欢欣和节日组织者的一点感激之情。"}},faq={{q="奥格瑞玛的冬天爷爷是谁？",a="他是烟林牧场雇佣的一名演员，负责在冬幕节期间扮演传说中的冬天爷爷。他坐在力量谷的节日贸易展示摊位附近，迎接部落的公民，聆听节日的请求，并宣传季节性的欢乐。",al={"谁是冬天爷爷","奥格瑞玛冬天爷爷","他是真正的冬天爷爷吗"}},{q="冬天爷爷想要什么美食？",a="冬天爷爷想要五块刚烤好的姜饼和一份冰镇牛奶，以帮助他度过漫长而疲惫的迎接节日访客的一天。",al={"他想要什么","请求的美食","他需要什么曲奇"}},{q="如何制作姜饼？",a="节日展示摊位周围的烟林牧场商人出售食谱和节日香料。烘焙师将节日香料与从野生禽类身上采集的小蛋混合，然后在烹饪之火上制作饼干。",al={"如何获得姜饼","姜饼食谱","曲奇配料"}},{q="哪里可以找到冰镇牛奶？",a="冰镇牛奶可以从奥格瑞玛和其他主要定居点的几乎任何食物和饮料商贩、旅店老板或酒保处购买。",al={"哪里可以获得冰镇牛奶","购买牛奶","牛奶商人"}},{q="为什么冬天爷爷要亲自索要食物？",a="整天听孩子们和市民们谈论食物、礼物和庆典，让这位表演者饿坏了。由于他无法轻易离开他在力量谷的岗位，他请求路过的冒险者为他带来一些快餐。",al={"为什么他想要美食","冬天爷爷饿了吗"}},{q="这个任务有联盟对应版本吗？",a="有。驻扎在铁炉堡的冬天爷爷也会提出同样的请求，他同样会在节日期间向联盟的勇士索要姜饼和冰镇牛奶。",al={"联盟版本","铁炉堡美食"}}},fp="30,159,24.234.0,23.236.0,39.254.0,44.137.0,36.196.0,33.117.0,50.238.0,45.141.0"}
P.entries["quest:697"] = {n="马林的要求",s="斯奎尔图交给你一封给大法师马林的密封信，他就在暴风城的法师区。信中告诉马林，克莱登和斯奎尔图很快就会回家了，斯奎尔图确信马林会因为你在阿拉希对他们的帮助而给予你丰厚的报酬。",h="斯奎尔图交给你一封给大法师马林的密封信，他就在暴风城的法师区。信中告诉马林，克莱登和斯奎尔图很快就会回家了，斯奎尔图确信马林会因为你在阿拉希对他们的帮助而给予你丰厚的报酬。",kw={"阿拉希高地","大法师马林","克莱登","法师区","马林的请求","密封信","斯奎尔图","暴风城"},sec={{t="给大法师的信",b="在阿拉希的工作完成后，斯奎尔图交给你一封信，让你带回暴风城。信中给法师区的大法师马林传达的消息是，克莱登和斯奎尔图很快就会回家了。斯奎尔图毫不怀疑马林会因为你帮助他们而给你丰厚的报酬，并祝愿你旅途平安。"},{t="马林阅读信件",b="当马林打开信件时，他的眼睛睁大了。他很高兴，并说特雷兰会非常开心的。他想克莱登和斯奎尔图现在正赶回暴风城，应该和他一样兴奋。"}},faq={{q="是谁让你送信的？",a="是斯奎尔图。信中告诉马林，他和克莱登很快就会回家了。",al={"谁给了这封信","谁开启了马林的请求","马林的请求起始"}},{q="大法师马林在哪里？",a="大法师马林在暴风城的法师区。",al={"大法师马林在哪里","大法师马林位置","我在哪里交这个任务"}},{q="克莱登是谁？",a="克莱登是斯奎尔图在阿拉希高地的同伴。斯奎尔图说他们两个很快就会回家了。",al={"克莱登是谁","克莱登阿拉希"}},{q="这一步之前是什么？",a="这是在“攻击塔楼”之后进行的，那是斯奎尔图在阿拉希的塔楼交给你的工作。",al={"上一个任务","前置任务","什么引导至此"}}},fp="15,160,25.243.0,22.193.1,30.88.0,32.46.0,14.91.0,28.90.0"}
P.entries["quest:698"] = {n="缺乏补给",s="达尔正在为东部海滩边的前哨站收集补给品，托克卡尔在那里除了执勤和为士兵做饭，几乎没有多余的时间。达尔让你给托克卡尔送去一批锯齿肉。",h="达尔正在为东部海滩边的前哨站收集补给品，托克卡尔在那里除了执勤和为士兵做饭，几乎没有多余的时间。达尔让你给托克卡尔送去一批锯齿肉。",kw={"达尔","肉排","肉","前哨站","锯齿鱼","悲伤沼泽","托克卡尔"},sec={{t="岸边的补给",b="达尔正在为东部海滩边的前哨站收集补给品。托克卡尔在那里竭尽所能地工作，但执勤和为士兵做饭让他几乎没有空闲时间。士兵们如果能弄到锯齿肉的话很喜欢烹饪它，但达尔一直没有时间给他们送去补给。"},{t="挑选肉类",b="达尔提醒你不要去动年幼的锯齿鱼，因为年长的肉质更好。幼鱼需要一两年的时间才能长到完全成熟。你需要带八块未经处理的锯齿鱼肉排给悲伤沼泽里的托克卡尔。"}},faq={{q="是谁在请求锯齿鱼肉？",a="达尔，他正在为东部海滩边的前哨站收集补给。",al={"谁给予物资匮乏任务","谁开启物资匮乏任务","达尔 悲伤沼泽"}},{q="托克卡尔驻扎在哪里？",a="在达尔提到的东部海滩前哨站。肉要送到那里给悲伤沼泽的托克卡尔。",al={"托克卡尔在哪里","托克卡尔位置","托克卡尔前哨站"}},{q="为什么托克卡尔需要别人帮忙带肉？",a="在执勤和为士兵做饭之间，托克卡尔几乎没有剩下的时间。",al={"为什么托克卡尔需要肉","为什么达尔要送食物"}},{q="应该猎杀哪种锯齿鱼？",a="年长的那些。幼鱼味道不够好，而且需要一两年的时间才能长到完全成熟。",al={"哪种锯齿鱼","什么锯齿鱼掉落肉","锯齿鱼肉排来源"}},{q="需要多少块肉排？",a="八块未经处理的锯齿鱼肉排，带给托克卡尔。",al={"需要多少肉排","未经处理的锯齿鱼肉排数量"}},{q="接下来要做什么？",a="后续有一个同名的第二步任务。",al={"物资匮乏的后续任务","物资匮乏后续"}}},fp="15,165,22.253.0,17.189.0,36.68.0,27.104.0,43.79.0,33.94.0,27.47.0,29.42.0"}
P.entries["quest:6981"] = {n="发光的碎片",s="发光的碎片是一块从哀嚎洞穴的黑暗深处开采出来的神秘翡翠色宝石。这件令人不安的遗物表面光洁，其下却翻涌着烟雾般的精粹，驱使着冒险者们前往棘齿城及更远的地方寻求答案。",h="发光的碎片是一块从哀嚎洞穴的黑暗深处开采出来的神秘翡翠色宝石。这件令人不安的遗物表面光洁，其下却翻涌着烟雾般的精粹，驱使着冒险者们前往棘齿城及更远的地方寻求答案。",kw={"贫瘠之地","尖牙德鲁伊","翡翠梦魇","菲拉·古风","发光的碎片","棘齿城","斯布特瓦夫","哀嚎洞穴"},ang={["class:Druid"]="对于德鲁伊来说，碎片那翡翠般的光泽和烟雾状的核心是翡翠梦魇通过哀嚎洞穴中堕落的同胞渗入现实世界的严峻证据。",["faction:Alliance"]="即使在远方的卡利姆多，联盟的探索者们也认识到，无论是什么样的黑暗力量在腐蚀贫瘠之地地下的自然，都构成了全球性的威胁。",["faction:Horde"]="解开碎片的谜团有助于保护贫瘠之地重要的十字路口和贸易路线，使其免受地下泉水中滋生的非自然威胁的影响。",["race:Tauren"]="贫瘠之地的平衡对舒哈鲁来说至关重要，将这件非自然的遗物交给菲拉·古风有助于了解毒害他们祖地的腐化。"},sec={{t="一个令人不安的发现",b="发光的碎片取自哀嚎洞穴深处，持有它的人会立刻感到不安。它呈耀眼的绿色，看似坚硬，但在其结晶体表面下却有着翻腾的雾状阴影。这块水晶散发着一种微妙的吸引力，引人注目，同时也流露出一种深沉而令人不安的气息，暗示了那些沉睡的德鲁伊和他们那被梦魇侵蚀的圣地受到了腐化。"},{t="在棘齿城寻求答案",b="冒险者们不清楚这块石头的来历或本质，于是将这件神器带到了地精港口棘齿城。当地的工程师斯布特瓦夫检查了这个古怪的东西，却意识到它的起源超出了地精机械学和常规地质学的范畴。于是，他指引寻找答案的人前往洞穴上方的岩脊，牛头人神秘学家菲拉·古风正在那里守护着贫瘠之地不安的灵魂。"}},faq={{q="发光的碎片是什么？",a="这是一块在哀嚎洞穴深处发现的、受到腐化的绿色发光水晶。在它玻璃般的外壳内，淡淡的烟雾在翻腾，让任何仔细观察它的人都感到不安。",al={"发光的碎片物品","这颗绿色宝石是什么","哀嚎洞穴的碎片"}},{q="在棘齿城有谁能检查这块碎片？",a="驻扎在棘齿城飞行管理员附近的工程师斯布特瓦夫会检查这块碎片。虽然他是一位工程师而非德鲁伊，但他认出了其中的奇异能量，并指引你去找一位拥有灵性专业知识的人。",al={"棘齿城里谁检查碎片","棘齿城碎片非玩家角色","斯布特瓦夫碎片"}},{q="菲拉·古风在哪里？",a="菲拉·古风在贫瘠之地中部哀嚎洞穴入口正上方的山顶扎营。",al={"菲拉·古风位置","菲拉在哪里","哀嚎洞穴上方的山峰"}},{q="斯布特瓦夫头上有任务标记吗？",a="没有。斯布特瓦夫不会显示活动的任务图标。你必须直接与他交谈，并选择关于那块奇怪发光碎片的对话选项来推进任务。",al={"斯布特瓦夫没有问号","无法向斯布特瓦夫交任务","斯布特瓦夫故障"}},{q="为什么碎片看起来像包含了烟雾？",a="水晶内翻腾的烟雾反映了正在扭曲哀嚎洞穴的广泛腐化，这直接与入侵沉睡的尖牙德鲁伊思想的翡翠梦魇有关。",al={"为什么碎片有烟雾","宝石里的绿色烟雾","碎片中的腐化"}},{q="谁能完成菲拉·古风之后的任务链？",a="部落和联盟的冒险者都可以进行这条故事线。菲拉·古风的发现直接引出了任务“梦魇之中”，要求英雄们向各自的领袖和长者寻求指引。",al={"这个任务是部落专属吗","联盟发光的碎片","谁能接到梦魇之中"}}},fx={["8f9c92be"]={q="为什么要调查发光的碎片？",a="这块发光的碎片令人极度不安。它质地坚硬，内部却有烟雾般的绿色深处不断翻涌，散发着一种不自然的气息，亟待解释。你从状况堪忧的哀嚎洞穴深处找到了它，需要弄清它携带着何种腐化，以及它可能会给贫瘠之地带来什么威胁。",al={"为什么调查发光的碎片","发光的碎片的动机","为什么把碎片带到棘齿城"}}},fp="17,128,22.271.0,26.297.1,26.145.0,37.156.0,32.119.0,52.135.0,47.174.0,54.168.1"}
P.entries["quest:6984"] = {n="烟林牧场的感谢",s="这项节日任务标志着熏木农场在奥格瑞玛的冬季恢复工作圆满结束。在从卑劣的格林奇手中夺回被盗的节日佳肴后，冒险者将受到地精商人凯玛德·考伯宾奇的指引，直接从冬天爷爷那里接受一份正式的节日感谢礼。",h="这项节日任务标志着熏木农场在奥格瑞玛的冬季恢复工作圆满结束。在从卑劣的格林奇手中夺回被盗的节日佳肴后，冒险者将受到地精商人凯玛德·考伯宾奇的指引，直接从冬天爷爷那里接受一份正式的节日感谢礼。",kw={"冬幕节","冬天爷爷","格林奇","凯玛德·考伯宾奇","奥格瑞玛","熏木农场","力量谷"},ang={["faction:Horde"]="部落在奥格瑞玛的冬幕节庆祝活动将古老的萨满季节更替崇拜与喧闹的地精商业精神融合在了一起。",["profession:Cooking"]="熏木农场的时令补给是节日烹饪的核心，提供了大厨们每年翘首以盼的异国配方和节日食材。"},sec={{t="企业节日",b="熏木农场热衷于利用冬幕节的气氛，在艾泽拉斯的各大主城营销各类佳肴、配方和节日礼品。当他们的一批节日货物在奥特兰克山脉的雪山中被抢走后，业务陷入了停滞。随着佳肴被夺回，偷窃的格林奇也被解决，商人凯玛德·考伯宾奇迅速确保这些乐于助人的勇士们能够获得充分的企业感谢——以及一场隆重的颁奖仪式。"},{t="觐见冬天爷爷",b="地精们没有在柜台上递过普通的钱袋，而是安排冬天爷爷亲自颁发奖励。这位节日人物在力量谷的节日树旁主持大局，既是文化赞助人，也是节日庆典的名誉领袖。他用节日的祝福和一份熏木农场特殊礼物来嘉奖那些挽救了节日补给的人们。"}},faq={{q="谁指派我去和冬天爷爷谈话？",a="凯玛德·考伯宾奇，即驻扎在奥格瑞玛力量谷的熏木农场代表。一旦你成功夺回了公司被盗的节日佳肴，他就会指引你去找冬天爷爷。",al={"谁开启此任务","任务发布者","凯玛德的角色"}},{q="我做了什么才赢得了熏木农场的感激？",a="你在奥特兰克山脉追踪并找到了卑劣的格林奇，夺回了被盗的节日佳肴，为地精们挽救了冬幕节的供应链。",al={"为什么他们要感谢我","什么佳肴被偷了","格林奇背景"}},{q="冬天爷爷在奥格瑞玛的什么地方？",a="他就坐在力量谷那棵装饰华丽的大冬幕树下，就在熏木农场的摊位旁边。",al={"冬天爷爷位置","奥格瑞玛的圣诞老人哪里找","奥格瑞玛的冬幕树"}},{q="谁是冬天爷爷？",a="在古老的传说中，冬天爷爷是一位象征季节更替的元素或神话使者，他为大地披上冬雪。在冬幕节期间，凡人扮演者会穿上他传统的红色长袍，传播善意并向孩子们和冒险者分发糖果。",al={"冬天爷爷是谁","冬天爷爷真实存在吗","冬幕节传说"}},{q="什么是熏木农场？",a="熏木农场是一家由地精经营的餐饮和农业企业。在冬幕节期间，他们为部落和联盟供应节日食品、时令食材和装饰性小商品。",al={"熏木农场传说","熏木农场是什么","地精节日商人"}},{q="和他说过话后，我还会收到其他东西吗？",a="是的。冬天爷爷会代表公司交给你一份熏木农场特殊礼物，你的努力也会让你获得热砂港的声望。",al={"任务奖励","伪装道具","邮寄礼物"}}},fp="32,194,19.327.0,33.232.0,47.166.0,52.175.0,50.136.0,27.240.0,27.200.0,51.155.0"}
P.entries["quest:699"] = {n="缺乏补给",s="托克卡尔和海岸边的士兵们驻扎在这里，是为了防范鱼人对斯通纳德的威胁，或者在大规模敌袭时发出警报。托克卡尔需要六个锯齿龙虾人的爪子，并愿意用前哨站的一件武器作为报答。",h="托克卡尔和海岸边的士兵们驻扎在这里，是为了防范鱼人对斯通纳德的威胁，或者在大规模敌袭时发出警报。托克卡尔需要六个锯齿龙虾人的爪子，并愿意用前哨站的一件武器作为报答。",kw={"爪子","鱼人","锯齿龙虾人","斯通纳德","悲伤沼泽","托克卡尔"},sec={{t="海岸卫兵的武器",b="由于海岸边存在鱼人的威胁，托克卡尔和士兵们被派驻于此，以保卫斯通纳德，或者在敌方规模过大时发出警报。这让他们几乎没有休息的时间，托克卡尔希望能得到更多的帮助。锯齿龙虾人的爪子如果经过妥善处理，可以制成精良的武器。托克卡尔请求收集六个，并承诺以一件前哨站的武器作为回报，同时他也非常感激你能带来的肉食与陪伴。"}},faq={{q="谁要求收集爪子？",a="托克卡尔，他正驻扎在海岸边保卫斯通纳德。",al={"谁发布了供应短缺任务","任务发布者","托克卡尔"}},{q="为什么托克卡尔需要锯齿龙虾人的爪子？",a="如果经过妥善处理，它们的爪子可以制成精良的武器，托克卡尔需要六个。",al={"为什么需要爪子","锯齿龙虾人的用途","武器爪子"}},{q="海岸前哨站正在防范什么威胁？",a="海岸边的鱼人。士兵们驻扎在那里是为了保卫斯通纳德，或者在大规模敌袭时发出警报。",al={"海岸危险","鱼人攻击斯通纳德","托克卡尔在监视什么"}},{q="接下来的任务是什么？",a="接下来是“来自大海的威胁”。",al={"接下来是什么","后续任务","供应短缺之后"}}},fp="15,194,21.347.0,23.78.0,45.82.0,45.112.0,26.28.0"}
P.entries["quest:7"] = {n="剿灭狗头人",s="“清理狗头人营地”是治安官玛克布莱德指派给刚抵达北郡山谷的新兵的一项早期军事任务。该任务旨在让志愿者们清理潜伏在北部林地中的狗头人害虫，防止这些具有攻击性的地下食腐生物淹没修道院。这是新兵在保卫暴风城领土边界时的第一次真正考验。",h="“清理狗头人营地”是治安官玛克布莱德指派给刚抵达北郡山谷的新兵的一项早期军事任务。该任务旨在让志愿者们清理潜伏在北部林地中的狗头人害虫，防止这些具有攻击性的地下食腐生物淹没修道院。这是新兵在保卫暴风城领土边界时的第一次真...",kw={"回音山","艾尔文森林","狗头人","治安官玛克布莱德","北郡","北郡修道院","害虫"},ang={["faction:Alliance"]="北郡的不安局势凸显了暴风城本土领地所承受的压力，即使是低等级的食腐生物入侵也需要紧急动员志愿民兵。",["race:Human"]="对于北郡的人类来说，驱逐狗头人害虫是保护修道院和农田免遭蹂躏的一项基本公民义务。"},sec={{t="压力重重的山谷",b="北郡山谷曾是一片宁静的祈祷、务农与新兵训练场所，但近年来暴风城的军事力量已捉襟见肘。随着国王失踪以及皇家卫队被调离，野生生物和投机者们胆大妄为地向文明边缘推进。治安官玛克布莱德在北郡修道院内组织当地防务，依靠新招募的志愿者在威胁干扰修道院运作或威胁周边葡萄园之前将其镇压。"},{t="林中的害虫",b="狗头人天生胆小且痴迷蜡烛，通常满足于在远离阳光的地下矿脉中挖掘。然而，一个完整的狗头人氏族已经涌入了北郡北部的林线。如果不加遏制，它们庞大的数量足以将食腐行为演变成公开的掠夺。玛克布莱德下令猎杀狗头人害虫有着双重目的：既能削弱它们的先头部队，又能检验新兵是否具备保卫王国所需的决心。"}},faq={{q="是谁下令清理狗头人营地的？",a="治安官玛克布莱德下达了命令。他驻扎在北郡修道院内，代表暴风城负责监督当地新兵的招募以及山谷的安保工作。",al={"谁发布了这个任务","任务发布者","治安官玛克布莱德的角色"}},{q="为什么狗头人不在矿洞里，而是在北部的林地中？",a="虽然狗头人通常居住在洞穴和矿洞中，但它们在北郡的人口已经稠密到溢出到了森林中。它们在北部的树林间建立了原始营地，在文明之地的边缘徘徊。",al={"为什么狗头人在外面","地表的狗头人","为什么在林地"}},{q="为什么这些狗头人被视为对暴风城的威胁？",a="从个体来看，狗头人害虫胆小而虚弱。然而，成群结队的它们是肆无忌惮的盗贼，能够伏击旅行者、掠夺补给并占领无人防守的哨所，而在军事力量已经过度紧缩的情况下，暴风城无法承受这样的损失。",al={"狗头人危险吗","为什么要杀死害虫"}},{q="这项任务接下来会指向哪里？",a="在清理掉地表的害虫后，治安官玛克布莱德会要求新兵深入调查回音山矿洞，那里才是狗头人入侵的中心。",al={"下一个任务是什么","下一步","清理营地之后"}},{q="北郡能得到定期的皇家军队支援吗？",a="不能。由于国王瓦里安失踪后王国各地的政治紧张局势和部队短缺，像玛克布莱德这样的地方指挥官必须依靠平民志愿者、冒险者和受训人员来处理边界安全问题。",al={"暴风城的守卫在哪里","为什么要志愿者"}},{q="是什么让狗头人如此依恋蜡烛？",a="狗头人将蜡烛视为抵御地下隧道中窒息黑暗的主要防线。火焰对它们而言代表着安全、视力和所有权，因此如果有任何人试图夺走蜡烛，它们会表现出众所周知的敌意。",al={"为什么需要蜡烛","蜡烛痴迷症"}}},fx={afae4267={q="治安官玛克布莱德为何想要清理狗头人的营地？",a="一支狗头人氏族开始侵占修道院北面的树林，治安官玛克布莱德希望在它们占领整座山谷之前削减其数量。暴风城已被其他地方的威胁牵制，北郡只能自保。狗头人独处时胆小，成群结队时却会变得大胆。现在消灭它们，既能保卫聚居地，也是将它们彻底赶出北郡的第一步。",al={"为何消灭狗头人","玛克布莱德消灭狗头人的动机","为何清理狗头人营地"}},["35967b57"]={q="派你猎杀的狗头人歹徒是什么？",a="狗头人歹徒是一个潜入北方森林的氏族中的斥候和拾荒者。这些形似老鼠的类人生物天生穴居，独处时是胆怯的窃贼，如今却在北郡外的树林里聚集，数量多得令人不安。若放任不管，它们不断扩张的营地将威胁旅人、果园，乃至修道院本身。",al={"狗头人歹徒是谁","狗头人歹徒是什么","狗头人歹徒目标"}},["921e514b"]={q="治安官玛克布莱德为何派你出马，而不是暴风城卫兵？",a="暴风城的皇家军队忙于应对王国各地的危机，兵力捉襟见肘，北郡山谷只剩下少数卫兵驻守。玛克布莱德必须让士兵留守修道院周围和主要道路，维持防线。由于没有多余的兵力巡逻荒野，他只能依靠有能力的新兵和路过的志愿者，铲除正在滋生的危险。",al={"为何不派卫兵","玛克布莱德为何需要我","为何招募冒险者对付狗头人"}}},fp="19,169,23.267.0,23.319.0,42.126.0,56.203.0,55.199.0,34.145.1,50.184.0,48.164.0"}
P.entries["quest:70"] = {n="斯塔文的传说",s="调查的这一阶段将寻找者引向多年前遗落在闪金镇旅店的一封被遗弃的信件。沿着斯塔文·密斯特曼托的踪迹，调查从艾尔文森林一直延伸到暴风城的运河区。",h="调查的这一阶段将寻找者引向多年前遗落在闪金镇旅店的一封被遗弃的信件。沿着斯塔文·密斯特曼托的踪迹，调查从艾尔文森林一直延伸到暴风城的运河区。",kw={"运河","管理员弗索姆","闪金镇","旅店老板法雷","狮王之傲旅店","密斯特曼托","斯塔文","暴风城","未投递的信件"},ang={["faction:Alliance"]="解开斯塔文之谜需要穿过联盟的核心地带，从安静的闪金镇小村一路追溯到首都的大运河。",["race:Human"]="这项调查揭露了暴风王国更深层的黑暗暗流，表明困扰暮色森林的邪恶根源一直延伸到首都的门口。"},sec={{t="午夜惊魂",b="当询问狮王之傲旅店的旅店老板法雷关于斯塔文·密斯特曼托的事情时，他回忆起多年前一个暴风雨的夜晚。一名旅行信使曾为了躲避倾盆大雨而在那里寻求庇护，却在午夜时分惊慌失措地冲下楼梯。那名信使只穿着睡衣，直接冲进了黑暗的风暴中，从此再也没有出现过。"},{t="遗留的包裹",b="在惊慌逃窜中，信使将他的挎包和个人箱子遗弃在楼上的房间里。在被遗忘的货物中有一封未寄出的信，上面写着斯塔文的名字，收件人是住在暴风城运河区的人。这个箱子一直原封不动地放在床脚，直到法雷允许将其打开。"},{t="冰冷的接待",b="将这封迟到的信带入暴风城，会找到管理员弗索姆，他负责看管公园附近运河沿岸的房产。提到斯塔文的名字并看到他的笔迹，并没有换来对完成遗留投递工作的感激，反而引发了立时的厌恶和敌意，暗示着与寄信人有关的深层丑闻。"}},faq={{q="未投递的信件存放在哪里？",a="信件放在闪金镇狮王之傲旅店楼上的一个储物箱里。走上楼梯，向右转，进入那间带床的卧室；箱子就放在床架的脚头。",al={"寻找信件","斯塔文箱子位置","箱子在哪里"}},{q="为什么这封信最初没有被投递？",a="多年前，信使在狮王之傲旅店躲避倾盆大雨。午夜时分，某种东西把他吓坏了，他只穿着睡衣就逃进了风暴中，留下了他的箱子和信件。",al={"为什么信被遗弃","信使被什么吓跑了","为什么信使逃跑了"}},{q="我在哪里能找到暴风城的管理员弗索姆？",a="管理员弗索姆站在暴风城的运河边，靠近公园区边缘。",al={"弗索姆位置","管理员弗索姆在哪里","运河区上交任务"}},{q="为什么管理员弗索姆对收到这封信感到愤怒？",a="弗索姆立刻认出了斯塔文的笔迹和名字，反应十分愤慨。斯塔文·密斯特曼托给暴风城中与他过去有牵连的人们留下了痛苦的回忆和愤慨。",al={"为什么弗索姆很生气","弗索姆的反应","你胆子不小"}},{q="这与暮色森林的麻烦有什么联系？",a="夜色镇的镇议会正在调查与斯塔文·密斯特曼托这个名字有关的挥之不去的邪恶。揭开斯塔文生前究竟是谁的真相，需要追溯他早年在艾尔文森林和暴风城的旅行与交往。",al={"为什么暮色森林任务在闪金镇","这与暮色森林有何关联"}},{q="将信交给管理员弗索姆后会发生什么？",a="管理员弗索姆激烈的回应开启了调查的暴风城篇章，推动你去揭开斯塔文曾经的雇佣关系，以及他所服务的贵族家庭发生的可怕事件。",al={"下一步","这个任务之后是什么"}}},fp="21,134,17.266.0,19.289.0,16.261.1,37.203.0,46.205.0,46.91.0,57.183.0,49.198.0,57.186.1"}
P.entries["quest:700"] = {n="国王的礼物",s="“国王的贡品”是向阵亡的矮人战士苏利·巴鲁致敬的最后一步。在从洛丹伦废墟收集了优质花岗岩后，大石匠玛布勒斯坦奉国王麦格尼·铜须之命，在铁炉堡雕刻了一座庄严肃穆的纪念碑。",h="“国王的贡品”是向阵亡的矮人战士苏利·巴鲁致敬的最后一步。在从洛丹伦废墟收集了优质花岗岩后，大石匠玛布勒斯坦奉国王麦格尼·铜须之命，在铁炉堡雕刻了一座庄严肃穆的纪念碑。",kw={"国王的贡品","花岗岩","铁炉堡","洛丹伦","麦格尼·铜须","玛布勒斯坦","纪念碑","苏利·巴鲁"},ang={["class:Warrior"]="国王麦格尼·铜须的话语直接向苏利·巴鲁这样在战斗中牺牲了一切的前线士兵的无私英勇表示了敬意。",["faction:Alliance"]="这座纪念碑令人心酸地提醒着人们，近期发生的冲突在卡兹莫丹和北方诸王国造成了沉重的代价。",["race:Dwarf"]="对于矮人来说，用永恒的石头纪念祖先阵亡的勇士是他们最神圣的文化传统之一。"},sec={{t="镌刻哀思的纪念碑",b="国王麦格尼·铜须委托修建了一座永久性的纪念碑，以缅怀苏利·巴鲁，一位为保卫族人而牺牲的勇敢矮人。这座纪念碑由大石匠玛布勒斯坦使用从饱受战火摧残的洛丹伦运来的优质花岗岩雕刻而成，矗立在铁炉堡，作为阵亡将士的永恒见证，他们的牺牲守护了矮人王国。"},{t="君主的沉思",b="当得知纪念碑完工的消息时，麦格尼·铜须陷入了对石头与凡人生命极限的沉思。虽然他承认雕刻出的岩石永远无法真正等同于一位勇敢矮人的生命，但他希望这座纪念碑能长久留存，让行走在艾泽拉斯的后世子孙永远不会忘记那些为了换取他们明天而流血牺牲的英雄。"}},faq={{q="这座纪念碑是为了纪念谁？",a="这座纪念碑是为了纪念苏利·巴鲁，一位为他的族人和联盟英勇作战而献出生命的勇敢矮人战士。",al={"谁的纪念碑","苏利·巴鲁纪念碑","阵亡者"}},{q="为什么要从洛丹伦采集石料？",a="大石匠玛布勒斯坦需要最优质的花岗岩来制作持久的皇家贡品。尽管洛丹伦在天灾军团入侵后已成废墟，但该地区盛产出色的采石。",al={"为什么使用洛丹伦的石头","洛丹伦花岗岩","玛布勒斯坦的石雕"}},{q="这个任务发生在哪里？",a="任务始于大石匠玛布勒斯坦，并最终在铁炉堡的王座厅面见国王麦格尼·铜须处完成。",al={"任务交还地点","完成任务的角色"}},{q="为什么国王麦格尼要亲自委托制作这个贡品？",a="麦格尼认为统治者必须向保卫王国的士兵致敬。他视纪念碑为后世子孙的重要警示，提醒他们普通的士兵为他们的安全付出了何等高昂的代价。",al={"国王麦格尼·铜须的用意","麦格尼·铜须与苏利·巴鲁"}},{q="纪念碑完工后会发生什么？",a="向国王麦格尼汇报便完成了这一纪念任务线。雕像将留在铁炉堡，成为苏利·巴鲁一座庄严而永久的纪念碑。",al={"接下来是什么","国王的贡品后续"}},{q="这座雕像在石匠工艺上有什么意义？",a="大石匠玛布勒斯坦是铁炉堡成就最高的矮人工匠之一。他加工了进口的洛丹伦花岗岩，代表君主将未经雕琢的石料塑造成了一件适宜的国家艺术品。",al={"玛布勒斯坦的角色","大石匠的工艺"}}},fx={["964451bf"]={q="大石匠玛布勒斯坦为何让你去见国王？",a="是你冒险远赴洛丹伦废墟，取回了雕像所需的优质花岗岩。你取得石料，让这份悼念之礼得以完成，因此大石匠玛布勒斯坦托付你，将苏利·巴鲁纪念碑完工的喜讯直接禀报给国王麦格尼·铜须。",al={"为何派我去见麦格尼","为何禀报麦格尼国王","玛布勒斯坦为何派玩家"}}},fp="16,131,26.297.0,24.259.0,38.117.0,42.172.0,33.100.0,55.178.0,44.132.0,47.169.0"}
P.entries["quest:7003"] = {n="被缩小的巨人",s="在菲拉斯的被遗忘的海岸，码头附近，索尔宾·范达瑟声称那些巨人影响了他的生意。索尔宾根据地精的设计制造了一种缩小射线，并用地精的专有技术对其进行了改进。他把这种“超级缩小器”交给你，让你去对菲拉斯的巨人试用一下。",h="在菲拉斯的被遗忘的海岸，码头附近，索尔宾·范达瑟声称那些巨人影响了他的生意。索尔宾根据地精的设计制造了一种缩小射线，并用地精的专有技术对其进行了改进。他把这种“超级缩小器”交给你，让你去对菲拉斯的巨人试用一下。",kw={"峭壁巨人","菲拉斯","被遗忘的海岸","陆地漫步者","缩小残渣","超级缩小器","巨人的缩小射线","索尔宾·范达瑟"},sec={{t="巨人的缩小射线",b="索尔宾·范达瑟必须对菲拉斯的巨人采取一些行动，因为只要这些巨人存在，索尔宾就没法在这里好好做生意。解决办法是对地精缩小射线进行改进，索尔宾自豪地称之为“卓越的地精科技”。为了避免死亡等不便，索尔宾更希望由你来测试它。你需要对峭壁巨人、深渊漫步者、海浪漫步者、海岸漫步者或陆地漫步者等巨人使用超级缩小器，并在他们缩小后收集残留的缩小残渣，然后带回码头。"},{t="为什么索尔宾需要残渣",b="索尔宾称缩小残渣是工程学中的一种宝贵原料，因为它有助于确保射线枪不会发生令用户失望的爆炸。索尔宾随后补充说，这只适用于其他射线枪，而不适用于你手中的这一把。"},{t="回到码头",b="当你回来时，索尔宾很高兴看到残渣，并且发现你所有的主要肢体都还在。索尔宾随即坚称超级缩小器从未有过任何风险，并称你为所有地精的朋友。"}},faq={{q="谁制造了超级缩小器？",a="索尔宾·范达瑟，他在菲拉斯的被遗忘的海岸的码头附近。",al={"谁发布巨人的缩小射线任务","索尔宾·范达瑟任务发布者","巨人的缩小射线在哪里领取"}},{q="为什么索尔宾想把巨人变小？",a="索尔宾说，如果他要留在这里，这些巨人显然会妨碍生意，而缩小后的巨人要好对付得多。",al={"为什么要缩小巨人","为什么在菲拉斯缩小巨人","索尔宾·范达瑟的目的"}},{q="哪些巨人可以被缩小？",a="菲拉斯的任何巨人都可以。在被遗忘的海岸，这包括峭壁巨人、深渊漫步者、海浪漫步者、海岸漫步者和陆地漫步者。",al={"我可以缩小哪些巨人","哪些巨人计算任务进度","巨人的缩小射线目标"}},{q="什么是缩小残渣？",a="它是在巨人被缩小后在他们身上发现的物质。索尔宾称它是工程学中的宝贵原料，并表示它有助于确保射线枪不会对用户发生爆炸。",al={"为什么需要缩小残渣","残渣有什么用","索尔宾收集残渣的目的"}}},fp="13,232,30.457.0,28.193.0,17.182.1,33.84.0,39.108.0,27.154.0,32.159.0"}
P.entries["quest:701"] = {n="迅猛龙的狡诈",s="“迅猛龙的狡诈”是一个任务，在此任务中，托尔甘试图唤醒戈穆尔内心沉睡的战士精神。托尔甘计划通过收集高原血掠龙的心脏，来制作一件注入了迅猛龙狡诈与捕食力量的附魔物品。",h="“迅猛龙的狡诈”是一个任务，在此任务中，托尔甘试图唤醒戈穆尔内心沉睡的战士精神。托尔甘计划通过收集高原血掠龙的心脏，来制作一件注入了迅猛龙狡诈与捕食力量的附魔物品。",kw={"沉睡的战士","戈穆尔","迅猛龙的狡诈","高原血掠龙","迅猛龙心脏","托尔甘","战士"},ang={["class:Warrior"]="托尔甘试图用迅猛龙的狡诈和凶猛，来重新点燃戈穆尔内心沉睡的战士精神，提醒他那曾经拥有的武力。",["faction:Horde"]="这一仪式反映了部落利用原始野兽和自然之灵，来帮助消沉或受困的同伴找回人生目标的传统。"},sec={{t="唤醒沉睡的战士",b="托尔甘致力于恢复一位名叫戈穆尔的消沉同伴，此人的战士精神已经陷入沉睡。托尔甘并没有单纯依赖劝说，而是转向原始魔法，试图通过冲击让戈穆尔重振旗鼓。他希望通过制作一个注入了野生掠食者精魂的护符，让戈穆尔重新找回战斗的决心，并向他展示这股新力量的强大。"},{t="掠食者的心脏",b="为了引导野外的捕食本能，托尔甘需要高原血掠龙的心脏。在萨满教和原始传统中，狡猾猎手的心脏承载着它们的凶猛与狡诈。托尔甘利用这些战利品编织成一件实体信物并施加咒语，旨在直接向戈穆尔灌输掠食者的狡诈，从而让他重拾真正的使命。"}},faq={{q="托尔甘是谁？",a="托尔甘是一位萨满或精神领袖，他试图帮助戈穆尔。托尔甘认为戈穆尔已经失去了内心的力量，因此正在收集试剂，制作一件注入了野兽魔法的物品来唤醒他。",al={"托尔甘是谁","托尔甘","任务发布者"}},{q="戈穆尔是谁？",a="戈穆尔是一个已经丧失斗志，让内心的战士陷入沉睡的人。托尔甘打算向他注入原始掠食者的精魂，让他见证新的力量，并重新站起来战斗。",al={"戈穆尔是谁","为什么要帮助戈穆尔","沉睡的战士"}},{q="托尔甘为什么需要迅猛龙心脏？",a="托尔甘需要十二颗迅猛龙心脏来制作实体护身符，并完成注入戈穆尔所需的附魔。原始魔法经常使用掠食者的心脏来引导它们固有的本能、狡诈和捕食力量。",al={"为什么需要迅猛龙心脏","心脏有什么用","迅猛龙魔法"}},{q="这些迅猛龙心脏从哪里来？",a="所需的心脏取自高原血掠龙，这是一种以不懈的狩猎技巧和狡诈而闻名的掠食性迅猛龙。托尔甘认为它们的心脏足以驱动这种唤醒咒语。",al={"从哪获得心脏","哪种迅猛龙","高原血掠龙"}},{q="“迅猛龙的狡诈”象征着什么？",a="迅猛龙的狡诈代表了掠食者的狡猾、敏捷的反应和致命的本能。托尔甘相信引导这种特定的天性将能打破戈穆尔的怠惰，并复苏他的战斗本能。",al={"什么是迅猛龙的狡诈","什么力量","迅猛龙狡诈的含义"}},{q="仪式的最终目标是什么？",a="托尔甘利用收集到的心脏制作物品并编织咒语，旨在向戈穆尔展示新的力量，唤醒他沉睡的战士身份，让他重回正轨。",al={"戈穆尔痊愈了吗","仪式之后会发生什么","这管用吗"}}},fp="19,196,29.335.0,25.336.0,15.190.0,15.194.0,36.199.0,37.179.0,42.187.0,40.176.0"}
P.entries["quest:702"] = {n="迅猛龙的狡诈",s="在之前的“迅猛龙的狡诈”之后，托尔甘交给你一颗宝珠，并让你前往落锤镇寻找戈穆尔。宝珠的能量中蕴含着迅猛龙的精髓，旨在唤醒戈穆尔的精神，为他指引新的方向。",h="在之前的“迅猛龙的狡诈”之后，托尔甘交给你一颗宝珠，并让你前往落锤镇寻找戈穆尔。宝珠的能量中蕴含着迅猛龙的精髓，旨在唤醒戈穆尔的精神，为他指引新的方向。",kw={"阿拉希高地","戈穆尔","落锤镇","迅猛龙精髓","托尔甘","托尔甘的宝珠"},sec={{t="托尔甘的宝珠",b="托尔甘给了你一颗宝珠，其能量旨在将迅猛龙的精髓灌注给戈穆尔。他希望能借此唤醒这位战士的精神，让他开始新的人生。一旦戈穆尔恢复正常，托尔甘打算向他解释部落目前的处境，并在这个不断的战斗中寻求这位伟大战士的帮助。"},{t="戈穆尔的苦涩",b="戈穆尔对你的归来冷嘲热讽，声称他再也不需要托尔甘的怜悯，并用那些鲜艳的绳子戏弄你。"},{t="一股奇异的力量",b="尽管如此，这颗宝珠还是比戈穆尔预想的要有趣得多，他也注意到了它所散发出的奇异力量。"},{t="心中的迅猛龙",b="当戈穆尔接过宝珠时，他的血液开始沸腾，迅猛龙的狡诈渗透了他的全身。他自言自语地怀疑这是否就是托尔甘所说的萨满之道，随后宣称自己重获新生，力量也随之回归。"}},faq={{q="戈穆尔是谁？",a="戈穆尔是落锤镇的一名意志消沉的战士。托尔甘希望能鼓舞他的精神，让他走上新的道路，从而让部落获得这位伟大战士的帮助。",al={"戈穆尔是谁","戈穆尔背景故事","戈穆尔出了什么问题"}},{q="托尔甘的宝珠有什么用途？",a="它的能量旨在将迅猛龙的精髓灌注给戈穆尔，唤醒他的精神并赋予他新的目标。",al={"宝珠有什么用","托尔甘的宝珠用途","狡诈宝珠"}},{q="这一步之前发生了什么？",a="在此之前先是“迅猛龙的狡诈”，这一步是在此基础上展开的。",al={"上一个任务","前置任务"}}},fp="19,160,13.310.0,20.144.0,15.79.1,17.206.1,15.160.0,37.127.0,27.84.0"}
P.entries["quest:7025"] = {n="冬幕节的礼物",s="在冬幕节期间，扮演铁炉堡冬天爷爷的表演者感到非常疲惫，他请求过往的行人给他送点节日点心。给他送去新鲜出炉的曲奇和冰镇牛奶，就能换取一份节日奖励，并得到他的衷心感谢。",h="在冬幕节期间，扮演铁炉堡冬天爷爷的表演者感到非常疲惫，他请求过往的行人给他送点节日点心。给他送去新鲜出炉的曲奇和冰镇牛奶，就能换取一份节日奖励，并得到他的衷心感谢。",kw={"冬幕节","曲奇","冬天爷爷","冰镇牛奶","铁炉堡","熏木农场","冬天爷爷的馈赠"},ang={["faction:Alliance"]="铁炉堡是联盟主要的冬幕节庆祝中心，吸引了来自东部王国各地的旅行者来到平民区的节日树前。",["profession:Cooking"]="这个任务需要简单的烹饪技能，将小蛋和节日香料混合制作成节日的曲奇。",["race:Dwarf"]="对于矮人来说，冬天爷爷代表着一个与泰坦和冬季馈赠有关的古老传说，尽管看到他在平民区大嚼曲奇让这个神话变得非常接地气。"},sec={{t="坐得太久的漫长一天",b="虽然冬幕节的起源可以追溯到古老的泰坦传说和矮人神话中那位身披寒冬斗篷的不朽人物，但现代的庆祝活动在很大程度上依赖于熏木农场的商业赞助。在铁炉堡平民区的节日树旁，一位普通的矮人每天都要穿着沉重的冬天爷爷装束，倾听市民和孩子们诉说节日愿望，工作十分辛苦。"},{t="烘焙节日欢乐",b="在听了一整天的礼物请求后，扮演冬天爷爷的这位矮人自己也不免感到饥肠辘辘。他并没有要求什么奢华的东西，只是希望能吃上一口简单的慰藉：五个用节日香料制作的新鲜出炉的曲奇，再配上一杯冰镇牛奶。这一交易既让疲惫的节日工作人员得到了一丝喘息，也把善意传播到了这座冰雪覆盖的首都之中。"}},faq={{q="我在铁炉堡哪里能找到冬天爷爷？",a="冬天爷爷坐在铁炉堡平民区的大型节日树和熏木农场展位旁边，周围环绕着节日的装饰品。",al={"冬天爷爷在哪里","铁炉堡冬天爷爷位置","铁炉堡圣诞老人位置"}},{q="如何制作曲奇？",a="配方由冬天爷爷附近的熏木农场商人出售。烘焙它们需要烹饪技能，还需要从节日商人那里购买的节日香料，以及从野生鸟类身上收集的小蛋。",al={"哪里获得曲奇","曲奇配方","如何烘焙曲奇"}},{q="我在哪里能弄到冰镇牛奶？",a="冰镇牛奶可以从联盟各大主城（包括铁炉堡各处的旅店）的几乎任何旅店老板、食物商或饮料商那里买到。",al={"冰镇牛奶商人","哪里买牛奶","铁炉堡牛奶"}},{q="这个冬天爷爷是真正的神话人物吗？",a="不是，他是由熏木农场雇佣的矮人表演者，代表冬幕节庆祝活动中那位与泰坦有关的传说人物。",al={"冬天爷爷是真的吗","铁炉堡的那个人是谁","他是真的冬天爷爷吗"}},{q="完成任务后，冬天爷爷会给你什么？",a="收到曲奇和牛奶后，冬天爷爷会给你一份熏木农场礼物包作为一点心意。",al={"冬天爷爷的馈赠任务奖励","冬天爷爷的邮件","熏木农场样本"}},{q="部落玩家可以完成这个特定任务吗？",a="这个特殊的任务是在铁炉堡提供给联盟玩家的。部落成员有他们自己对应的任务，可以去奥格瑞玛拜访冬天爷爷。",al={"部落能做这个任务吗","部落的冬天爷爷的馈赠"}}},fx={["4b1f8d0d"]={q="冬天爷爷为何想要完成这件事？",a="冬天爷爷整天坐在铁炉堡，倾听节日愿望，迎接访客，一刻也没有休息。冬幕节给其他人带来了欢乐，但听着人们谈论各种节日点心，他已经又累又饿，于是请你取来一份他急需的点心。",al={"冬天爷爷要饼干的动机","冬天爷爷为何想要饼干","为何给冬天爷爷送点心"}},a70b2277={q="冰镇牛奶有什么用？",a="冰镇牛奶只是一种清爽的饮品，用来搭配那批热乎乎的姜饼。整天迎接旅人，高声送上节日祝福，难免口干舌燥，而甜美的节日饼干与冰凉的饮料再相配不过。",al={"为何需要冰镇牛奶","给冬天爷爷的牛奶","冰镇牛奶的用途"}},cc125737={q="姜饼有什么用？",a="姜饼是专门给冬天爷爷本人的节日点心。分发了许多点心，又听完一个接一个居民的请求后，他想吃一份用节日香料制成的传统冬幕节甜点，恢复体力。",al={"姜饼给冬天爷爷的点心","为何需要姜饼","给冬天爷爷的饼干"}},["6bf2696f"]={q="冬天爷爷为何需要你帮忙，而不自己去取点心？",a="冬天爷爷不能在节日庆典期间擅离岗位。他要守在铁炉堡的树旁迎接人群，为烟林牧场传递欢乐，因此只能留在原地，依靠像你这样慷慨的路人跑腿，帮他找些吃的。",al={"冬天爷爷为何需要我","冬天爷爷为何不能自己取饼干","冬天爷爷为何请冒险者帮忙"}}},fp="29,183,22.305.0,20.261.0,48.143.0,36.195.0,29.137.0,50.116.0,64.104.1,47.144.0"}
P.entries["quest:7029"] = {n="Vyletongue Corruption",s="Vark 战痕请你照料玛拉顿中遭到腐化的植物。橙色水晶池和 Vylestem Vines 与这项任务有关。",h="Vark 战痕请你照料玛拉顿中遭到腐化的植物。橙色水晶池和 Vylestem Vines 与这项任务有关。",kw={"cerulean vial","遭到腐化的植物","玛拉顿","noxxious scion","橙色水晶池","葬影村","vark 战痕","vylestem vines","vyletongue corruption"},sec={{t="Vark 的请求",b="在葬影村，Vark 战痕请你治愈受腐化侵染的植物。他给你一个 Coated Cerulean Vial，让你去玛拉顿的橙色水晶池中灌满。这个瓶子是用来对付 Vylestem Vines 的，那里会出现遭到腐化的 Noxxious Scions。"},{t="那些植物",b="治愈植物的关键在于 Noxxious Scions。治愈八株植物后，你就可以回到葬影村找 Vark 战痕。"}},faq={{q="Vark 战痕要我做什么？",a="Vark 战痕要你治愈玛拉顿中遭到腐化侵染的八株植物，然后回葬影村找他。",al={"vark 的植物任务","vark 的请求","替 vark 做什么"}},{q="Cerulean Vial 在哪里获得？",a="Vark 战痕会把 Coated Cerulean Vial 交给你，你要去玛拉顿的橙色水晶池中灌满它。",al={"cerulean vial 的位置","瓶子在哪里","橙色水池"}},{q="Vylestem Vines 有什么用？",a="在 Vylestem Vines 上使用 Filled Cerulean Vial，会引出一只遭到腐化的 Noxxious Scion。",al={"vylestem vines","藤蔓的用途","藤蔓和瓶子"}},{q="怎样才能治愈植物？",a="杀死从 Vylestem Vines 中出现的遭到腐化的 Noxxious Scions，就能治愈植物。",al={"治愈植物","植物腐化","noxxious scions 和植物"}},{q="需要治愈多少株植物？",a="需要治愈八株植物，然后回去找 Vark 战痕。",al={"植物数量","需要多少株植物","八株植物"}},{q="Vark 战痕在哪里？",a="Vark 战痕在葬影村。",al={"vark 的位置","vark 在哪里","葬影村的 vark"}}},fp="21,131,16.253.0,10.139.0,39.124.0,33.107.0,32.91.0,26.99.0,29.63.0,25.41.0"}
P.entries["quest:703"] = {n="烧烤秃鹰翅膀",s="里格弗兹对烤秃鹫翅膀推崇备至，那是用浓郁的酱汁烹制出的鲜美肉食。除了秃鹫翅膀本身，制作这道菜所需的其他配料他都已经准备好了。只要你能带回足够的翅膀，里格弗兹或许会把食谱传授给你。",h="里格弗兹对烤秃鹫翅膀推崇备至，那是用浓郁的酱汁烹制出的鲜美肉食。除了秃鹫翅膀本身，制作这道菜所需的其他配料他都已经准备好了。只要你能带回足够的翅膀，里格弗兹或许会把食谱传授给你。",kw={"荒芜之地","烧烤","秃鹫","烹饪","食谱","里格弗兹","翅膀"},ang={["profession:Cooking"]="厨师们注意：这道菜的食谱可以作为奖励。"},sec={{t="当地人的最爱",b="里格弗兹以他的烤秃鹫翅膀为荣。酱汁浓郁，肉质鲜美，香气能传到很远的地方，引来饥肠辘辘的食客。制作这道菜的所有配料他都准备好了，就差秃鹫翅膀了。带四只秃鹫翅膀来，里格弗兹或许愿意分享这份食谱。"}},faq={{q="谁想要秃鹫翅膀？",a="里格弗兹想要秃鹫翅膀来做一批烤秃鹫翅膀。",al={"谁提供烤秃鹫翅膀","谁是里格弗兹","任务提供者"}},{q="里格弗兹用什么作为交换？",a="里格弗兹暗示如果你带回足够的翅膀，他就分享食谱。",al={"奖励是什么","我能得到什么","食谱奖励"}},{q="为什么里格弗兹需要秃鹫翅膀？",a="里格弗兹已经有了制作烤秃鹫翅膀所需的其他所有材料，只缺翅膀了。",al={"为什么选秃鹫","里格弗兹的目的","为什么里格弗兹想要翅膀"}},{q="里格弗兹需要多少翅膀？",a="四只秃鹫翅膀。",al={"多少只秃鹫翅膀","秃鹫翅膀数量"}}},fp="23,92,16.251.0,31.66.0,51.59.0,39.62.0,36.36.0"}
P.entries["quest:7041"] = {n="维利塔恩的污染",s="尼耶尔前哨站的 Talendria 需要净化玛拉顿内受污染的植物。将洞穴橙色水晶池中的水浇在枯萎藤蔓上，便能逼出扎根其中的腐化幼体。",h="尼耶尔前哨站的 Talendria 需要净化玛拉顿内受污染的植物。将洞穴橙色水晶池中的水浇在枯萎藤蔓上，便能逼出扎根其中的腐化幼体。",kw={"cerulean vial","水晶池","玛拉顿","尼耶尔前哨站","noxxious scion","talendria","vylestem vines","vyletongue corruption"},sec={{t="净化洞穴",b="玛拉顿深处，邪恶的植物肆意蔓延，堵塞了地下林地。尼耶尔前哨站的 Talendria 想用直接取自橙色水晶池的水，驱除 Vylestem Vines 上的腐坏。给植物浇水会引出感染它们的 Noxxious Scions。杀死八只这种生物，便能让受污染的植物恢复生机。"}},faq={{q="是谁派你前往玛拉顿？",a="Talendria 在尼耶尔前哨站的联盟据点下达了这项任务。",al={"talendria 任务","谁发布了 vyletongue corruption 任务","尼耶尔前哨站任务发布者"}},{q="水池在哪里？",a="橙色水晶池位于玛拉顿深处的洞穴之中。",al={"橙色水晶池位置","在哪里装满 cerulean vial","cerulean vial 池水"}},{q="如何治愈 Vylestem Vines？",a="将橙色水池中的水浇在藤蔓上，会逼出藏身其中的 Noxxious Scions。杀死幼体便能净化植物。",al={"如何净化藤蔓","引出 noxxious scion","vylestem vines"}},{q="必须净化多少株植物？",a="必须消灭藏在植物中的幼体，净化八株植物。",al={"需要多少只幼体","治愈多少株植物","幼体数量"}}},fp="21,210,21.332.0,28.70.0,26.74.0,35.136.0,33.74.0"}
P.entries["quest:7044"] = {n="玛拉顿的传说",s="寻找 Celebras’s Scepter 的两部分，会让你去寻找与 Celebras 交谈的方法。",h="寻找 Celebras’s Scepter 的两部分，会让你去寻找与 Celebras 交谈的方法。",kw={"celebras","塞雷布拉斯钻石","塞雷布拉斯魔棒","maraudon 的传说","玛拉顿","权杖","塞雷布拉斯节杖"},sec={{t="权杖的两部分",b="你要寻找塞雷布拉斯魔棒和塞雷布拉斯钻石，它们是 Celebras’s Scepter 的两部分。你还需要找到与 Celebras 交谈的方法。"}},faq={{q="我在寻找哪些部分？",a="塞雷布拉斯魔棒和塞雷布拉斯钻石是 Celebras’s Scepter 的两部分。",al={"权杖的部分","塞雷布拉斯魔棒和钻石","哪些部分"}},{q="我需要和谁交谈？",a="你要寻找与 Celebras 交谈的方法。",al={"与 celebras 交谈","和 celebras 说话","谁是 celebras"}},{q="塞雷布拉斯魔棒是什么？",a="塞雷布拉斯魔棒是 Celebras’s Scepter 的两部分之一。",al={"塞雷布拉斯魔棒","魔棒部分","魔棒"}},{q="塞雷布拉斯钻石是什么？",a="塞雷布拉斯钻石是 Celebras’s Scepter 的两部分之一。",al={"钻石部分","塞雷布拉斯钻石","钻石"}}},fp="19,99,18.132.0,29.82.0,28.49.0,26.66.0,30.70.0"}
P.entries["quest:7046"] = {n="塞雷布拉斯节杖",s="Celebras the Redeemed 请求你协助锻造塞雷布拉斯节杖。仪式进行时，你必须在他身旁守卫；力量平息后，再与他交谈。",h="Celebras the Redeemed 请求你协助锻造塞雷布拉斯节杖。仪式进行时，你必须在他身旁守卫；力量平息后，再与他交谈。",kw={"celebras","celebras the redeemed","仪式","节杖","塞雷布拉斯节杖"},sec={{t="创造仪式",b="Celebras the Redeemed 准备打造一件以自己命名的圣物。创造仪式需要双手稳定，并时刻保持警惕；仪式结束前，他都毫无防备。施法完成后，你要与他交谈，领取制成的节杖。"}},faq={{q="谁在请求援助？",a="Celebras the Redeemed 在打造节杖时寻求援助。",al={"谁在求助","谁发布了这个任务","celebras 是谁"}},{q="Celebras 想要打造什么？",a="Celebras 正通过一场特殊仪式打造塞雷布拉斯节杖。",al={"正在创造什么","celebras 在打造什么","节杖的用途"}},{q="仪式期间需要什么？",a="你要守在 Celebras the Redeemed 身边，保护并协助他，直到施法结束。",al={"仪式需要什么","仪式期间要做什么"}}},fp="23,185,20.262.0,29.68.0,32.70.0,33.89.0"}
P.entries["quest:705"] = {n="潜水采珍珠",s="里格弗兹是一个地精，他发现荒芜之地充满了凶猛的掠食者和胆大的拾荒者，他靠着狡诈手段生存了下来：使用闪光弹吓跑野生动物。碎蓝珍珠粉的存货不多了，所以你被派往荆棘谷的暗礁海去获取更多。",h="里格弗兹是一个地精，他发现荒芜之地充满了凶猛的掠食者和胆大的拾荒者，他靠着狡诈手段生存了下来：使用闪光弹吓跑野生动物。碎蓝珍珠粉的存货不多了，所以你被派往荆棘谷的暗礁海去获取更多。",kw={"荒芜之地","蓝珍珠","闪光弹","潜水采珠","里格弗兹","荆棘谷","暗礁海"},ang={["profession:Engineering"]="工程学玩家很有理由对里格弗兹的闪光弹感兴趣。"},sec={{t="一个狡猾的小地精",b="荒芜之地非常严酷，里格弗兹承认作为一个置身于掠食者和拾荒者当中的矮小地精，他感到很害怕。里格弗兹懂得制作闪光弹的配方，并利用它们吓跑野生动物。其中一种原料快用完了：碎蓝珍珠粉。"},{t="来自暗礁海的珍珠",b="蓝珍珠来自荆棘谷暗礁海里的蛤蜊。里格弗兹开玩笑说你最好穿上结实的靴子，然后他在荒芜之地等着你带回九颗珍珠，并承诺会让你的努力物有所值。"}},faq={{q="为什么里格弗兹需要蓝珍珠？",a="里格弗兹使用碎蓝珍珠粉来制作闪光弹，而这些粉末快用完了。",al={"里格弗兹 珍珠","为什么潜水采珠","为什么需要蓝珍珠"}},{q="蓝珍珠在哪里可以找到？",a="它们可以在荆棘谷暗礁海里的蛤蜊中找到。",al={"蓝珍珠在哪里","蓝珍珠位置","暗礁海珍珠"}},{q="为什么里格弗兹要使用闪光弹？",a="荒芜之地到处都是凶猛的掠食者和胆大的拾荒者，闪光弹可以把这些野生动物吓跑。",al={"为什么使用闪光弹","里格弗兹的防御"}},{q="里格弗兹需要多少蓝珍珠？",a="九颗蓝珍珠，带回荒芜之地交给里格弗兹。",al={"蓝珍珠数量","需要多少珍珠"}}},fp="12,136,22.241.0,20.199.0,37.93.0,32.65.0,36.118.0,42.67.0"}
P.entries["quest:706"] = {n="黑龙之火",s="西格鲁·铁斧正在荒芜之地等待来自铁炉堡的消息，她掌握了一种为武器附上烈焰的技术。这需要从一只罕见的黑龙幼龙尚在跳动的心脏中提取血液，而莱瑟罗峡谷的幼龙正是你要寻找的目标。",h="西格鲁·铁斧正在荒芜之地等待来自铁炉堡的消息，她掌握了一种为武器附上烈焰的技术。这需要从一只罕见的黑龙幼龙尚在跳动的心脏中提取血液，而莱瑟罗峡谷的幼龙正是你要寻找的目标。",kw={"荒芜之地","黑龙心脏","费拉诺·钢趾","烈焰附魔","铁炉堡","莱瑟罗峡谷","灼热幼龙","焦灼卫士","西格鲁·铁斧"},ang={["faction:Alliance"]="西格鲁·铁斧正在等待铁炉堡的消息，而这项工作是为联盟准备的。"},sec={{t="学徒的手艺",b="西格鲁·铁斧在担任费拉诺·钢趾的学徒时，学会了一种特殊的为武器附加烈焰附魔的方法，据最后的消息，费拉诺在洛丹伦的一支狩猎队的铁匠铺里。西格鲁正在等待来自铁炉堡的消息，除此之外她没什么事可做。"},{t="莱瑟罗峡谷的幼龙",b="西格鲁几乎不透露关于这个过程的细节，只说它需要从一只罕见的黑龙幼龙尚在跳动的心脏中提取血液。从那条峡谷的幼龙身上取下一颗心脏交给西格鲁，她就会向你展示这项技艺。那里的灼热幼龙和焦灼卫士就是心脏的来源。"}},faq={{q="是谁教会了西格鲁·铁斧这种附魔技术？",a="西格鲁是在担任费拉诺·钢趾的学徒时学会的，据最后的消息，他曾在洛丹伦的一支狩猎队的铁匠铺工作。",al={"西格鲁的导师","谁训练了西格鲁","费拉诺·钢趾"}},{q="给刀刃附加烈焰需要什么材料？",a="从一只罕见的黑龙幼龙心脏中提取的血液，那颗心脏必须还在跳动。",al={"西格鲁需要什么","黑龙心脏需求","烈焰附魔材料"}},{q="在哪里可以找到黑龙幼龙？",a="在东部荒芜之地的莱瑟罗峡谷。",al={"在哪里寻找黑龙","莱瑟罗峡谷幼龙","黑龙心脏位置"}},{q="为什么西格鲁·铁斧滞留在荒芜之地？",a="西格鲁在等待来自铁炉堡的消息，在此期间她没什么其他事情可忙。",al={"为什么西格鲁在荒芜之地","西格鲁·铁斧的目的"}},{q="哪些生物会掉落所需的心脏？",a="莱瑟罗峡谷的灼热幼龙和焦灼卫士。",al={"什么掉落黑龙心脏","哪些幼龙有心脏"}}},fp="24,208,21.244.0,28.266.0,53.142.0,52.89.0,39.72.0,48.84.0,39.84.0"}
P.entries["quest:7066"] = {n="生命之种",s="你带着 Seed of Life 前往月光林地的圣所。守护者雷姆洛斯在那里等候，准备接收这件神圣遗物，其中还留存着一丝他故人的气息。",h="你带着 Seed of Life 前往月光林地的圣所。守护者雷姆洛斯在那里等候，准备接收这件神圣遗物，其中还留存着一丝他故人的气息。",kw={"塞纳里奥","腐化","月光林地","雷姆洛斯","seed of life"},sec={{t="前往月光林地",b="一段静谧的朝圣之旅，引你前往德鲁伊隐居的林地。在月光林地，守护者雷姆洛斯静守于此，等待能够穿透笼罩世间的腐化阴霾之人。带着 Seed of Life 来到他面前，便有望见到这片土地上一位古老的守护者。"},{t="林地重生",b="接过遗物后，雷姆洛斯认出这件信物，明白他已逝的兄弟终于得以安息。尽管他的兄弟长久以来受傲慢与愤怒所困，却并未真正迷失，而是通过牺牲拥抱了重生。在雷姆洛斯的守护下，这件神器留存下来，成为饱受摧残的世界重燃希望的灯火。"}},faq={{q="雷姆洛斯在哪里？",a="雷姆洛斯居住在月光林地的圣所中。",al={"雷姆洛斯在哪里","雷姆洛斯位置","谁接收 seed of life"}},{q="Seed of Life 是什么？",a="Seed of Life 是一件源于牺牲的神器，人们将它作为供奉带到月光林地，交给雷姆洛斯。",al={"seed of life 是什么","seed of life 的用途","为何送交 seed of life"}},{q="你接近雷姆洛斯时，他察觉到了什么？",a="雷姆洛斯能从携带它的人身上感受到熟悉的气息，即使这些旅行者身上也沾染着冒险途中常见的腐化余毒。",al={"雷姆洛斯对 seed of life 的反应","雷姆洛斯如何看待 seed of life"}}},fp="12,177,20.308.0,20.315.1,27.52.0,25.98.0,47.138.0"}
P.entries["quest:7067"] = {n="贱民的指引",s="在凄凉之地的荒原上，一名被放逐的半人马把一份书面指引交给了你。他想让你从玛拉顿深处取出一件名为联合坠饰的古老遗物。他打算如何处置这件饰物，只有你和这名弃民知道。",h="在凄凉之地的荒原上，一名被放逐的半人马把一份书面指引交给了你。他想让你从玛拉顿深处取出一件名为联合坠饰的古老遗物。他打算如何处置这件饰物，只有你和这名弃民知道。",kw={"联合坠饰","半人马","centaur pariah","凄凉之地","玛拉顿","弃民的指引"},sec={{t="弃民的请求",b="半人马弃民在凄凉之地灰暗的荒原南部徘徊，被族中交战的氏族驱逐。他把写下的话交托给你，恳请你前往玛拉顿的圣窟。在那些洞窟深处，藏着联合坠饰。他请求你取回这件遗物，并带回他孤寂的营地。"}},faq={{q="Centaur Pariah 是谁？",a="他是一名被放逐的半人马，在凄凉之地南部徘徊，遭到族中交战氏族的排斥。",al={"半人马弃民传说","谁发布了这个任务","凄凉之地弃民"}},{q="联合坠饰是什么？",a="联合坠饰是一件遗物，藏在玛拉顿深处，Centaur Pariah 希望将它取回。",al={"联合坠饰","联合坠饰传说","玛拉顿坠饰"}},{q="Centaur Pariah 在哪里等候？",a="这名弃民待在凄凉之地南部，远离各大氏族的据点。",al={"半人马弃民位置","弃民位置","凄凉之地弃民位置"}}},fp="25,261,23.328.0,26.96.0,28.110.0,35.98.0"}
P.entries["quest:7068"] = {n="暗影残片",s="奥格瑞玛的尤塞尔奈需要十块来自玛拉顿的 Shadowshard Fragments。你需要从洞穴中收集这些矿物残片，并将它们带回部落的首都。",h="奥格瑞玛的尤塞尔奈需要十块来自玛拉顿的 Shadowshard Fragments。你需要从洞穴中收集这些矿物残片，并将它们带回部落的首都。",kw={"碎片","玛拉顿","奥格瑞玛","shadowshard fragments","尤塞尔奈"},sec={{t="玛拉顿的碎片",b="玛拉顿中有尤塞尔奈想要的水晶碎片。要收集十块，就得深入洞穴，再把它们带回兽人之都。"}},faq={{q="尤塞尔奈是谁？",a="尤塞尔奈在奥格瑞玛城中等候，希望有人从玛拉顿带回碎片。",al={"尤塞尔奈是谁","谁给予 shadowshard fragments","尤塞尔奈在哪里"}},{q="Shadowshard Fragments 来自哪里？",a="Shadowshard Fragments 可以在玛拉顿深处找到。",al={"在哪里能找到 shadowshard fragments","去哪里获取 shadowshard fragments","shadowshard fragments 位置"}},{q="需要多少块 Shadowshard Fragments？",a="尤塞尔奈需要十块 Shadowshard Fragments，并要你把它们带到奥格瑞玛。",al={"需要多少块碎片","需要多少块 shadowshard fragments","碎片数量"}}},fp="21,173,22.172.0,17.88.0,45.53.0,42.66.0"}
P.entries["quest:7070"] = {n="Shadowshard Fragments",s="塞拉摩的大法师 Tervosh 请你从玛拉顿收集 Shadowshard Fragments，并带回十块给他。",h="塞拉摩的大法师 Tervosh 请你从玛拉顿收集 Shadowshard Fragments，并带回十块给他。",kw={"大法师tervosh","尘泥沼泽","玛拉顿","shadowshard fragments","tervosh","塞拉摩"},sec={{t="Tervosh的请求",b="大法师 Tervosh 在尘泥沼泽海岸的塞拉摩等候。他请你从玛拉顿带回十块 Shadowshard Fragments，这些碎片正是他请求的核心。"}},faq={{q="谁在索要 Shadowshard Fragments？",a="塞拉摩的大法师 Tervosh 请你收集 Shadowshard Fragments。",al={"谁要碎片","tervosh碎片"}},{q="这些碎片来自哪里？",a="Shadowshard Fragments 来自玛拉顿。",al={"碎片来源","玛拉顿碎片"}},{q="Tervosh 想要多少块碎片？",a="大法师 Tervosh 想要十块 Shadowshard Fragments。",al={"碎片数量","十块碎片"}},{q="我该把它们带到哪里？",a="把碎片带给尘泥沼泽海岸塞拉摩的大法师 Tervosh。",al={"碎片交还地点","tervosh位置"}}},fp="21,119,19.182.0,39.76.0,33.45.0,37.52.0,22.87.0"}
P.entries["quest:708"] = {n="黑盒子",s="一个金属制的黑匣子出现在荒芜之地的巨型秃鹫胃里，其表面严重凹陷，仿佛被酸液浸泡过一样。在其底部的符号下方印着一行字：19号引擎——铁炉堡攻城小队。",h="一个金属制的黑匣子出现在荒芜之地的巨型秃鹫胃里，其表面严重凹陷，仿佛被酸液浸泡过一样。在其底部的符号下方印着一行字：19号引擎——铁炉堡攻城小队。",kw={"荒芜之地","黑匣子","被腐蚀的黑匣子","巨型秃鹫","武器大厅","铁炉堡攻城小队","飞行员比罗·长须"},ang={["faction:Alliance"]="这个匣子上带有铁炉堡的标记，它的线索止于铁炉堡。"},sec={{t="从秃鹫胃中取出",b="这些凹痕表明这个黑匣子在秃鹫的胃里待了很久，酸液一直在腐蚀金属。翻过它，底部印着一个符号，下面写着“19号引擎——铁炉堡攻城小队”。你必须把它带到铁炉堡的武器大厅，交给飞行员比罗·长须。"}},faq={{q="这个被腐蚀的黑匣子是从哪里来的？",a="它是在荒芜之地的一只巨型秃鹫的胃里找到的，看起来已经在那里待了很长时间。",al={"匣子来自何处","匣子是怎么到这里的","黑匣子起源"}},{q="匣子上印着什么标记？",a="底部印有一个符号，下方写着“19号引擎——铁炉堡攻城小队”。",al={"匣子上写着什么","黑匣子上的标记","匣子铭文"}},{q="谁应该接收这个匣子？",a="铁炉堡武器大厅的飞行员比罗·长须。",al={"谁来接收匣子","黑匣子要送到哪里","我该把匣子交给谁"}}},fp="13,74,20.211.0,43.100.0,37.90.0,35.50.0"}
P.entries["quest:7082"] = {n="奥特兰克山谷的墓地",s="Corporal Teeka Bloodsnarl让你袭击奥特兰克山脉的一处墓地，然后回去找她。",h="Corporal Teeka Bloodsnarl让你袭击奥特兰克山脉的一处墓地，然后回去找她。",kw={"奥特兰克","奥特兰克山脉","corporal teeka bloodsnarl","墓地突袭","墓地"},sec={{t="墓地突袭",b="在奥特兰克山脉，Corporal Teeka Bloodsnarl派你去袭击一处墓地。之后你要回去找她。"}},faq={{q="是谁让我去袭击墓地？",a="Corporal Teeka Bloodsnarl让我袭击奥特兰克山脉的一处墓地。",al={"是谁交代的","teeka墓地","墓地任务"}},{q="墓地在哪里？",a="墓地位于奥特兰克山脉。",al={"墓地位置","要去哪里","奥特兰克墓地"}},{q="Teeka让我做什么？",a="Teeka让你袭击一处墓地，然后回到奥特兰克山脉找她。",al={"要做什么","墓地请求","任务是什么"}}},fp="25,103,19.116.0,35.83.0,23.42.0,29.83.0"}
P.entries["quest:71"] = {n="回复托马斯",s="“向托马斯报告”是艾尔文森林东部的一个任务，内容是关于卫兵托马斯对东部水道附近失踪的暴风城卫兵的调查。冒险者在东部桥梁处协助卫兵托马斯，调查他失踪战友的下落，并报告河流沿岸的情况。",h="“向托马斯报告”是艾尔文森林东部的一个任务，内容是关于卫兵托马斯对东部水道附近失踪的暴风城卫兵的调查。冒险者在东部桥梁处协助卫兵托马斯，调查他失踪战友的下落，并报告河流沿岸的情况。",kw={"桥梁","艾尔文森林","闪金镇","卫兵托马斯","马拉凯","勋章","鱼人","罗尔夫"},ang={["faction:Alliance"]="罗尔夫和马拉凯的死亡说明了艾尔文森林边界的脆弱状态，由于人手短缺，即便是日常的河流巡逻也可能遭到覆灭。",["race:Human"]="找回阵亡卫兵的勋章，让那些死于保卫王国境内道路的暴风城士兵得到了一份荣誉和安息。"},sec={{t="令人沉痛的确认",b="卫兵托马斯在几乎没有多余人手的情况下，守卫着闪金镇和东谷伐木场之间的渡口。当他的两名战友，马拉凯和罗尔夫，在河岸地区失踪时，他仍抱有他们只是被隔绝或耽搁的希望。将他们找回的服役勋章带回桥上，打破了这一希望，证实了两名卫兵已在水道附近遇害。"},{t="水边的威胁",b="几个月来，暴风城的领导层一直将鱼人视为河岸的麻烦制造者而大加忽视，重点关注强盗活动和更广阔的王国边界。两名武装暴风城卫兵在内陆溪流沿岸被屠杀，证明了这是一场有组织的暴行。证据在手，托马斯意识到艾尔文森林的东部边境正面临积极的进攻，这迫使他要求采取应对措施，以免伐木路线和定居点被淹没。"}},faq={{q="卫兵托马斯驻扎在哪里？",a="卫兵托马斯驻扎在艾尔文森林东部跨河的石桥上，那里连接着闪金镇和东谷伐木场之间的道路。",al={"托马斯位置","卫兵托马斯桥梁","卫兵托马斯在哪里"}},{q="罗尔夫和马拉凯是谁？",a="罗尔夫和马拉凯是被派往艾尔文森林东部巡逻的暴风城卫兵。两人都被潜伏在河岸和石碑湖沿岸的鱼人包围并杀害了。",al={"艾尔文森林失踪卫兵","罗尔夫是谁","马拉凯是谁"}},{q="为什么要找回他们的勋章？",a="勋章是暴风城卫兵的正式身份证明。将它们带回为卫兵托马斯提供了确凿的证据，证明他失踪的部下已因公殉职。",al={"为什么要勋章","卫兵勋章的作用"}},{q="为什么鱼人的攻击如此严重？",a="鱼人通常被视为原始、胆怯的害虫，而不是对受训士兵的致命威胁。两名武装卫兵的死亡证明，这些河岸部落已经变得胆大妄为，并且有能力进行协调一致的伏击。",al={"为什么鱼人是威胁","艾尔文森林的鱼人危险吗"}},{q="向托马斯报告后会发生什么？",a="托马斯让你将一份关于卫兵死亡和日益严重的鱼人威胁的报告带给闪金镇的治安官杜汉。杜汉警告说该地区的防御力量已经捉襟见肘。",al={"向托马斯报告后的后续任务","托马斯接下来做什么"}},{q="为什么卫兵托马斯独自驻扎在桥上？",a="随着瓦里安·乌瑞恩国王的失踪和资源的紧张，暴风城的军事力量在全国范围内捉襟见肘。像东部大桥这样的偏远哨所只有极少的人员来保卫重要的交通路线。",al={"为什么托马斯独自一人","暴风城桥梁卫兵为何单独驻守"}}},fx={d4d51b05={q="为何要把徽章交给卫兵托马斯？",a="卫兵托马斯派出了前往河边的巡逻队，他们却从此杳无音信。在芦苇丛中发现倒下的罗尔夫和马拉凯，残酷地证实了他们的结局。将找回的徽章交还托马斯，便能确凿地说明他手下士兵的遭遇，也能提醒他，东边水域沿岸的鱼人足以致命。",al={"为何向托马斯报告","为何把徽章带给托马斯","向托马斯报告的目的"}},["3744e02c"]={q="为什么要由你把徽章交还给托马斯？",a="罗尔夫和马拉凯已经死了，被河岸上那座敌意森然的村落深处的鱼人杀害。卫兵托马斯独自驻守东面的桥梁，不能擅离职守，让那里无人看守。你发现了阵亡的卫兵，又冒险从鱼人手中取回了他们的徽记，因此，带回这个噩耗的任务便落在了你身上。",al={"为什么由我向托马斯报告","为什么由我带回徽章"}}},fp="16,179,19.300.0,26.390.0,30.144.0,26.154.1,36.133.1,41.180.1,44.185.1,47.196.0"}
P.entries["quest:710"] = {n="研究石元素",s="鲁特维尔·沃拉图斯在荒芜之地停留，研究元素束缚枷锁。为了测试一些攻击性法术和几件拼凑起来的小玩意，鲁特维尔需要附近小型岩石元素身上的小型石片。",h="鲁特维尔·沃拉图斯在荒芜之地停留，研究元素束缚枷锁。为了测试一些攻击性法术和几件拼凑起来的小玩意，鲁特维尔需要附近小型岩石元素身上的小型石片。",kw={"荒芜之地","小型岩石元素","鲁特维尔·沃拉图斯","元素束缚枷锁","小型石片","元素研究：岩石"},ang={["class:Mage"]="鲁特维尔的枷锁是为法师们所准备的。"},sec={{t="元素枷锁",b="鲁特维尔·沃拉图斯在荒芜之地这里进行一项研究：元素束缚枷锁。一旦完成，法师们就能召唤出更强大的元素来为他们服务。为了开始这项研究，鲁特维尔需要十块小型石片，你可以轻松地从西边山丘上的小型岩石元素身上获得它们。"}},faq={{q="是谁在要求收集石片？",a="鲁特维尔·沃拉图斯，他因为一项研究工作在荒芜之地停留。",al={"谁发布了这个任务","任务发布者","鲁特维尔·沃拉图斯"}},{q="鲁特维尔·沃拉图斯在研究什么？",a="元素束缚枷锁，旨在让法师们召唤出更强大的元素。",al={"鲁特维尔的项目","元素束缚枷锁","鲁特维尔在建造什么"}},{q="鲁特维尔为什么需要小型石片？",a="它们用于测试鲁特维尔最新的一些攻击性法术和几件拼凑起来的小玩意。",al={"为什么要石片","石片的用途","石片是用来干什么的"}},{q="石片在哪里可以找到？",a="从鲁特维尔西边山丘上的小型岩石元素身上获取。",al={"去哪里找石片","小型岩石元素的位置","石片的来源"}}},fp="27,147,18.305.0,35.71.0,35.104.0,40.82.0,33.84.0"}
P.entries["quest:711"] = {n="研究石元素",s="鲁特维尔·沃拉图斯称赞你的能力远超他所有的学徒，并希望进行下一步的测试。这次需要的是三块大型石板，这种材料最好从岩石元素身上获取。",h="鲁特维尔·沃拉图斯称赞你的能力远超他所有的学徒，并希望进行下一步的测试。这次需要的是三块大型石板，这种材料最好从岩石元素身上获取。",kw={"荒芜之地","大型石板","鲁特维尔·沃拉图斯","岩石元素","石板","元素的研究：岩石"},sec={{t="更大的碎片",b="鲁特维尔·沃拉图斯的研究接下来的部分需要更强的力量。岩石元素拥有更大、更结实的躯体，因此它们更有可能携带着足以用于测试的碎片。鲁特维尔指引你前往更西边，或者沿着群山的边缘向东南方寻找，并让你去收集三块大型石板。鲁特维尔需要一些时间来测试你之前带来的较小的碎片。"},{t="鲁特维尔的期望",b="鲁特维尔的法术正如预料的那样对那些小碎片产生了作用。如果接下来的实验也像预想的那样顺利，那么在鲁特维尔控制下的元素将令之前召唤出的任何东西都黯然失色。"}},faq={{q="是谁派你去收集大型石板的？",a="鲁特维尔·沃拉图斯，他正在荒芜之地工作。",al={"谁给予这个任务","鲁特维尔任务","元素的研究给予者"}},{q="这个请求之前发生了什么？",a="那是早先的“元素的研究：岩石”，你当时给鲁特维尔带来了小的石片。",al={"上一个任务","前一步骤","我之前做了什么"}},{q="鲁特维尔说在哪里可以找到岩石元素？",a="在鲁特维尔所在位置的更西边，或者沿着群山的边缘向东南方向。",al={"元素在哪里","元素位置","哪里寻找石板"}},{q="鲁特维尔为什么需要大型石板？",a="鲁特维尔需要更大的碎片来进行接下来的测试。岩石元素有更大、更强壮的躯体，所以它们的碎片足够大。",al={"为什么要大型石板","石板的目的","鲁特维尔的研究目标"}}},fp="27,148,13.306.0,14.177.0,36.78.0,30.106.0,50.77.0,40.140.0"}
P.entries["quest:712"] = {n="研究石元素",s="鲁特维尔·沃拉图斯需要荒芜之地元素生物掉落的最后一样部件：岩石束缚护腕，它们来自高等岩石元素。据鲁特维尔的计算，这些护腕足以用来衡量他自己那些镣铐的强度。",h="鲁特维尔·沃拉图斯需要荒芜之地元素生物掉落的最后一样部件：岩石束缚护腕，它们来自高等岩石元素。据鲁特维尔的计算，这些护腕足以用来衡量他自己那些镣铐的强度。",kw={"荒芜之地","岩石束缚护腕","高等岩石元素","卡拉诺斯","鲁特维尔·沃拉图斯","卢西恩","食人魔","瑟沃"},sec={{t="衡量镣铐",b="在石板之后，鲁特维尔·沃拉图斯还要从荒芜之地的元素生物身上获取最后一样部件。取自高等岩石元素的岩石束缚护腕应该能让鲁特维尔判断他正在制造的镣铐的强度。如果鲁特维尔的记忆没错的话，他的探知术显示有一群元素生物在西南方向，靠近一些食人魔的地方。他需要五个护腕，这样可以多准备一些备用的，因为瑟沃出了名地会弄丢试剂和研究资料。"}},faq={{q="鲁特维尔为什么需要这些护腕？",a="根据鲁特维尔的计算，岩石束缚护腕足以用来衡量他自己那些镣铐的强度。",al={"为什么需要岩石束缚护腕","护腕的用途","鲁特维尔 束缚护腕"}},{q="鲁特维尔为什么要五个护腕？",a="为了多备一些，因为瑟沃出了名地会弄丢鲁特维尔的试剂和研究资料。",al={"为什么需要五个护腕","需要多少护腕","为什么要备用"}},{q="高等岩石元素在哪里？",a="根据鲁特维尔的探知，它们的一群栖息在鲁特维尔西南方，靠近一些食人魔的地方。卡格营地周围的山丘上就是它们的家。",al={"岩石元素在哪里","高等岩石元素位置","哪里可以找到护腕"}},{q="之前收集的石板怎么样了？",a="一旦这里的工作完成，卢西恩会把多余的石板带回卡拉诺斯，因为它们以后可能还会派上用场。",al={"石板去了哪里","卢西恩 石板","卡拉诺斯 石板"}}},fp="27,98,20.369.0,33.79.0,37.100.0,46.126.0,50.115.0"}
P.entries["quest:713"] = {n="至关重要的冷却剂",s="鲁特维尔·沃拉图斯想要一瓶冰霜之油，用来加固束缚所召唤朋友的枷锁。布洛金是鲁特维尔在奥特兰克的一位地精朋友，他可以教你如何制作这种油。",h="鲁特维尔·沃拉图斯想要一瓶冰霜之油，用来加固束缚所召唤朋友的枷锁。布洛金是鲁特维尔在奥特兰克的一位地精朋友，他可以教你如何制作这种油。",kw={"荒芜之地","布洛金","冷却剂至上","冰霜之油","鲁特维尔·沃拉图斯","奥特兰克废墟","枷锁"},sec={{t="至关重要的冷却剂",b="鲁特维尔·沃拉图斯发誓，没有什么比冰霜之油更能防止引擎或齿轮过热了，作为润滑剂，它的价值无与伦比。它还能帮助魔法物品保持其附魔效果。一瓶冰霜之油将提高鲁特维尔枷锁的魔法容量，使其足够强大，足以阻止他所召唤的朋友杀掉所有人。"},{t="奥特兰克的布洛金",b="鲁特维尔的一位地精朋友布洛金可以教你制作这种油。布洛金就在奥特兰克废墟，他在老城墙上进行售卖。"},{t="当油送到时",b="一旦油送到，鲁特维尔就称其为新护腕的完美冷却剂。鲁特维尔发誓，如果这些附魔无法持续一个世纪，他所有的财产都将归瑟沃所有。鲁特维尔还期待着当工作完成时，议会的法师们会感到敬畏。"}},faq={{q="为什么鲁特维尔·沃拉图斯需要冰霜之油？",a="一瓶冰霜之油可以增加鲁特维尔枷锁的魔法容量，这样它们就足够强大，能阻止他所召唤的朋友杀掉所有人。",al={"为什么需要冰霜之油","冰霜之油的用途","鲁特维尔的油"}},{q="谁知道怎么酿造冰霜之油？",a="鲁特维尔的一位地精朋友布洛金可以教你制作它。他在奥特兰克废墟，在老城的一面墙上。",al={"谁传授冰霜之油","在哪里学习冰霜之油","布洛金的配方"}},{q="冰霜之油有什么特别之处？",a="鲁特维尔说，没有什么比它更能防止引擎或齿轮过热，它作为润滑剂的价值无与伦比，并且它还能帮助魔法物品保持附魔效果。",al={"冰霜之油的特性","为什么冰霜之油很好"}}},fp="21,147,15.262.0,18.134.0,20.254.1,40.111.0,32.143.0,32.165.0"}
P.entries["quest:714"] = {n="发条式什么什么仪",s="在你带着“冷却头领必胜”任务中的冰霜之油交给鲁特维尔·沃拉图斯之后，你发现鲁特维尔依然沉浸在荒芜之地的某个装置里无法自拔。还差一个虽小但至关重要的零件：陀螺仪。",h="在你带着“冷却头领必胜”任务中的冰霜之油交给鲁特维尔·沃拉图斯之后，你发现鲁特维尔依然沉浸在荒芜之地的某个装置里无法自拔。还差一个虽小但至关重要的零件：陀螺仪。",kw={"荒芜之地","装置","冷却头领必胜","陀螺仪","卡拉诺斯","鲁特维尔·沃拉图斯"},ang={["profession:Engineering"]="工程师可以自己制作陀螺仪。"},sec={{t="至关重要的零件",b="鲁特维尔·沃拉图斯因为忙于工作而心不在焉，他说你完成的工作远超标准，并让你如果以后在卡拉诺斯见面，可以去申请一份工作。随后他急忙抓住了什么东西，提出了真正的请求：一个陀螺仪。鲁特维尔承认，这是一个虽小但至关重要的零件。带一个给他，项目应该就能完成了。"},{t="交付零件",b="当你把陀螺仪交给他时，鲁特维尔大喊着一把抓过，说工作真的快完成了，而且这个项目是目前的首要任务。但他承诺完成的时间一直在变，从几分钟到可能还要很久不等。"}},faq={{q="是谁在索要陀螺仪？",a="鲁特维尔·沃拉图斯，他正在荒芜之地研究一个装置。",al={"谁需要陀螺仪","陀螺仪任务发布者","鲁特维尔·沃拉图斯 荒芜之地"}},{q="鲁特维尔·沃拉图斯需要陀螺仪做什么？",a="这是一个虽小但相当关键的零件，有了它，鲁特维尔就能准备完成这个项目了。",al={"为什么需要陀螺仪","鲁特维尔在造什么"}},{q="关于卡拉诺斯的工作机会是怎么回事？",a="鲁特维尔因工作分心，说如果你在卡拉诺斯遇到他，随时可以去申请工作。",al={"鲁特维尔 卡拉诺斯","卡拉诺斯的工作机会"}},{q="在哪里可以找到陀螺仪？",a="工程师可以制作陀螺仪，也可以从工程学供应商那里购买。",al={"如何获得陀螺仪","陀螺仪来源","哪里购买陀螺仪"}}},fp="13,180,14.358.0,15.227.1,36.93.0,53.125.0,33.72.0,35.67.0"}
P.entries["quest:7142"] = {n="为奥特兰克而战",s="Voggah Deathgrip派你前往奥特兰克山谷，击败矮人将军范达尔·雷矛。击败他就是这项任务的目的。",h="Voggah Deathgrip派你前往奥特兰克山谷，击败矮人将军范达尔·雷矛。击败他就是这项任务的目的。",kw={"奥特兰克","奥特兰克山脉","奥特兰克山谷","矮人将军","范达尔·雷矛","voggah deathgrip"},sec={{t="奥特兰克的将军",b="在奥特兰克山脉，Voggah Deathgrip派你前往奥特兰克山谷。矮人将军范达尔·雷矛是你的目标，Voggah正等你回来。"}},faq={{q="是谁派我去奥特兰克山谷？",a="Voggah Deathgrip派你前往奥特兰克山谷，击败范达尔·雷矛。",al={"voggah是谁","voggah的任务"}},{q="目标是谁？",a="目标是矮人将军范达尔·雷矛。",al={"奥特兰克将军","范达尔是谁"}},{q="我该去哪里？",a="你要前往奥特兰克山谷。",al={"战斗在哪里","奥特兰克山谷"}},{q="我该回去找谁？",a="击败范达尔·雷矛后，你要回到奥特兰克山脉，去找Voggah Deathgrip。",al={"回去找谁","voggah"}}},fp="22,142,20.160.0,31.75.0,18.51.0,14.33.0,28.98.0"}
P.entries["quest:716"] = {n="有备无患",s="卢希恩·枪穗很清楚洛特维尔有多吝啬，他愿意为你付出的辛劳制造点东西作为补偿：用你收集的多余石头制作附魔护腕。卢希恩现在缺的是一件铁匠制造的纹饰青铜护腕。",h="卢希恩·枪穗很清楚洛特维尔有多吝啬，他愿意为你付出的辛劳制造点东西作为补偿：用你收集的多余石头制作附魔护腕。卢希恩现在缺的是一件铁匠制造的纹饰青铜护腕。",kw={"荒芜之地","元素岩石","附魔护腕","鲁特维尔·沃拉图斯","卢希恩·枪穗","纹饰青铜护腕"},ang={["profession:Blacksmithing"]="卢希恩想要的青铜护腕需要通过铁匠获得。"},sec={{t="对你辛苦劳作的答谢",b="在完成了“元素研究：岩石”的试炼后，卢希恩·枪穗承认洛特维尔确实很吝啬，并想补偿你。卢希恩一直在忙于处理你收集的多余石头，他可以用这些石头制造出精良的附魔护腕。这些护腕甚至可能在洛特维尔最新的发明所引发的所谓“即将到来的暴行”中保护你。"},{t="卢希恩需要什么",b="为了完成护腕的制作，卢希恩需要一件铁匠制造的纹饰青铜护腕。卢希恩警告说，最好别等太久，因为没人知道接下来会发生什么。"}},faq={{q="谁提出要制作护腕？",a="位于荒芜之地的卢希恩·枪穗提议用你收集的多余石头为你制作附魔护腕。",al={"谁提供石材胜于布料任务","任务发布者","卢希恩·枪穗"}},{q="卢希恩为什么要为你制作这件护甲？",a="卢希恩了解洛特维尔有多吝啬，他想为你的辛苦付出做点补偿。这或许也能帮你抵御洛特维尔的最新发明。",al={"为什么要制作护腕","卢希恩的动机","洛特维尔吝啬"}},{q="卢希恩完成护腕制作需要什么？",a="纹饰青铜护腕，也就是铁匠能做的那种。",al={"需要什么物品","所需物品","需要纹饰青铜护腕"}},{q="这个任务的前置是什么？",a="它紧接在洛特维尔的第三次“元素研究：岩石”任务之后。",al={"前置任务","石材胜于布料的前置条件"}}},fp="26,175,28.310.0,17.155.0,32.92.0,40.147.0,53.100.0,29.75.0"}
P.entries["quest:7162"] = {n="实验场",s="“试炼场”是哈格丁中尉为那些在奥特兰克向雷矛卫队应征入伍的联盟新兵所设立的入队仪式。为了获得正式的雷矛徽记，申请者必须冒险进入遍布鹰身人的冰翼洞穴，并取回一面插在那里的战旗。在洞穴中证明自己的勇气，是晋升远征军军衔的第一步。",h="“试炼场”是哈格丁中尉为那些在奥特兰克向雷矛卫队应征入伍的联盟新兵所设立的入队仪式。为了获得正式的雷矛徽记，申请者必须冒险进入遍布鹰身人的冰翼洞穴，并取回一面插在那里的战旗。在洞穴中证明自己的勇气，是晋升远征军军衔的第一...",kw={"丹巴达尔","哈格丁","鹰身人","冰翼洞穴","徽记","试炼场","雷矛","雷矛军旗"},ang={["faction:Alliance"]="雷矛远征军代表了联盟在奥特兰克的主要军事行动，结合了矮人的考古野心与对抗部落的领土防御。",["race:Dwarf"]="雷矛卫队主要由寻求先祖遗物和泰坦奥秘的铁炉堡矮人领导，因此这项试炼也是你加入本族最引以为傲的军事单位之一的途径。"},sec={{t="勇气的衡量",b="雷矛卫队正在奥特兰克山谷对霜狼氏族进行着无情的征战。哈格丁中尉在奥特兰克山脉的联盟营地协调部队，他拒绝让毫无经验的新兵在没有经过测试的情况下就进入战场。在授予任何士兵卫队中的正式身份前，哈格丁要求他们进入丹巴达尔西南方危险的冰翼洞穴，以证明自己的技能和胆量。"},{t="冰翼洞穴",b="这项试炼的概念很简单，但执行起来却很致命：一面雷矛军旗插在幽深的地下冰雪隧道之中。洞穴并非空无一物；凶残的冰霜鹰身人筑巢于这片冻土之中，迫不及待地将毫无防备的闯入者撕成碎片。带着完好无损的军旗返回，证明了新兵能够在危险的地形中穿行、经受住残酷掠食者的攻击，并能在压力下保持纪律。"},{t="雷矛徽记",b="在洞穴中幸存并取回军旗，士兵就能获得雷矛新兵徽记，从而正式加入远征军。正如哈格丁所承诺的那样，这枚徽记不仅仅是一个小饰品——它代表着军衔，随着士兵在战场上获得更高的荣誉，它还可以升级，最终有望获得像指挥官之眼这样传奇的荣誉。"}},faq={{q="哈格丁中尉是谁？",a="哈格丁中尉是一位驻扎在奥特兰克山脉的联盟军官，负责雷矛卫队的招募和战场识别工作。他负责测试潜在的战士，并用军事徽记来奖励他们的服务。",al={"哈格丁中尉","哈格丁","谁负责试炼场"}},{q="冰翼洞穴在哪里？",a="冰翼洞穴位于丹巴达尔联盟要塞的西南方，坐落在奥特兰克山谷的冰封地带内。它们是由冰雪和岩石雕凿而成的迷宫般的地下隧道。",al={"冰翼洞穴位置","冰翼洞穴在哪里","军旗位置"}},{q="冰翼洞穴里有什么威胁？",a="洞穴里栖息着凶猛的冰霜鹰身人。哈格丁中尉警告新兵，这些野蛮的生物会毫不犹豫地伏击闯入者，并扯断他们的喉咙。",al={"鹰身人","冰翼洞穴里有什么","冰翼鹰身人"}},{q="为什么雷矛卫队需要进行这项测试？",a="与霜狼兽人的战斗残酷且无情。哈格丁坚持要在新兵加入主力部队前将其筛选出来，以确保每一名扛着军旗的士兵都能在严酷的环境下作战。",al={"为什么要有试炼场","为什么要进行军旗试炼","雷矛入队仪式"}},{q="完成试炼场有什么奖励？",a="完成试炼后，新兵将获得一枚雷矛新兵徽记。随着士兵在奥特兰克山谷积累荣誉，哈格丁会将这枚徽记升级为更强大的版本。",al={"雷矛徽记","指挥官之眼","试炼场奖励"}},{q="哈格丁提到的霜狼氏族是谁？",a="霜狼氏族是一个兽人氏族，自几十年前被流放以来就一直居住在奥特兰克山谷。雷矛卫队认为他们是阻碍联盟在山谷中利益和挖掘工作的敌对野蛮人。",al={"霜狼野蛮人","霜狼氏族是谁","霜狼氏族"}}},fp="15,256,20.271.0,19.276.0,22.254.0,28.213.0,30.136.0,46.119.0,47.191.0,53.135.0,47.209.0"}
P.entries["quest:717"] = {n="大地的震颤",s="加瑞克认定布莱克拉什和赫玛图斯已不可信，无法继续被关押在莱索尔的监狱中。黑龙已经潜入那里，食人魔又夺走了大地印章，因此加瑞克派你去释放并击杀那些幼龙。",h="加瑞克认定布莱克拉什和赫玛图斯已不可信，无法继续被关押在莱索尔的监狱中。黑龙已经潜入那里，食人魔又夺走了大地印章，因此加瑞克派你去释放并击杀那些幼龙。",kw={"布莱克拉什","加瑞克","赫玛图斯","肯瑞托","克拉苏","莱瑟罗峡谷","符文石","大地之印","大地印章","大地的震颤"},ang={["faction:Alliance"]="加瑞克的请求是联盟的任务。"},sec={{t="摇摇欲坠的监狱",b="加瑞克无法再确保布莱克拉什和赫玛图斯会老实呆在监狱里。黑龙现在栖息在莱索尔，而食人魔带走了大地印章。加瑞克认为必须采取更严厉的手段，这些幼龙必须死。"},{t="破除封印",b="三块符文石将这些幼龙禁锢于此，只有大地印章才能取回它们。你将印章用于紫水晶、蛋白石和钻石之柱上，然后将符文石安放进大地之印中。这会释放那两个家伙，然后你要将它们击杀。加瑞克需要你带回布莱克拉什的锁链、赫玛图斯的锁链以及大地印章。"},{t="任务完成后",b="一旦这些幼龙被杀，加瑞克宣布肯瑞托不必再为莱索尔的囚犯而担忧。加瑞克打算向他的主人克拉苏报告这一成功，想必他会感到满意的。"}},faq={{q="谁是布莱克拉什和赫玛图斯？",a="被关押在莱索尔封印之后的幼龙。",al={"布莱克拉什和赫玛图斯","幼龙是谁","莱索尔关押着什么"}},{q="为什么要杀死这些幼龙，而不是继续关押它们？",a="加瑞克无法再确保它们会老实呆在监狱里。黑龙现在栖息在莱索尔，而食人魔带走了大地印章。",al={"为什么要杀死布莱克拉什","为什么要破除监狱","为什么要击杀赫玛图斯"}},{q="如何解除监狱的封印？",a="用大地印章从柱子上取下三块符文石，然后放入大地之印中。",al={"如何打开大地之印","如何召唤布莱克拉什","如何释放幼龙"}},{q="需要给加瑞克带回什么？",a="有三样东西要送回给加瑞克：布莱克拉什的锁链、赫玛图斯的锁链和大地印章。",al={"给加瑞克带回什么","布莱克拉什的锁链","赫玛图斯的锁链"}},{q="这个任务之前是什么任务？",a="这是《大地的震颤》任务的后续。",al={"前置任务","大地的震颤的前置条件"}}},fp="20,175,16.194.0,17.353.0,14.179.1,30.63.0,58.140.0,27.129.0,35.82.0,29.43.0"}
